INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-06-11T12:29:51.275465+00:00', '', '', '3cab03f6-5318-4b0d-b2cc-6685031d0102', false, '[]'::jsonb, '2026-06-11T12:29:54.543+00:00', '2ad473fe-77dd-481e-8ba7-4b2b0336173f', '', 'b8e329e9-34f1-4568-a632-3bdabb11d2f0', '', '[]'::jsonb, '[{"children":[],"content":[{"styles":{"bold":true},"text":"🎨 Decorators — Wrapping Functions With Extra Behaviour","type":"text"}],"id":"f7f360c0-1106-40bd-b211-0b15c43b7633","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"The Problem Decorators Solve","type":"text"}],"id":"d76f4d5e-ee14-40b2-a71d-67d38f7d9839","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Imagine you have 10 banking functions and you want to log every time any of them is called. The naive approach:","type":"text"}],"id":"19231002-d6d1-4e43-be69-1a06ad70c16b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"pythondef get_balance(account_id):\n    print(\"LOG: get_balance was called\")   # copy-pasted into every function\n    return 50000\n\ndef deposit(account_id, amount):\n    print(\"LOG: deposit was called\")       # same line, 10 times\n    ...                    \n                      \n                      \n                      \n  ","type":"text"}],"id":"51124a82-9fe2-4e34-b426-c16830c73e4d","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"This violates a core programming principle: ","type":"text"},{"styles":{"bold":true},"text":"Don''t Repeat Yourself (DRY)","type":"text"},{"styles":{},"text":". If you want to change the log format, you edit 10 places. Decorators solve this by letting you ","type":"text"},{"styles":{"bold":true},"text":"wrap","type":"text"},{"styles":{},"text":" a function with extra behaviour — once — and apply it anywhere.","type":"text"}],"id":"19d6860f-9fee-4544-ab12-9a2f77a18cad","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Mental model — The Gift Wrapper:","type":"text"}],"id":"be1a550a-dd91-45ea-8b22-08cacafd7903","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"A decorator is like a gift wrapper. The gift (your function) doesn''t change. The wrapper adds something around it — a bow, paper, a tag. The person receiving it still gets the gift. But the presentation is enhanced. You can use the same wrapper on any gift.","type":"text"}],"id":"9feabadf-9a44-491d-ae88-e620e3f8f24c","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"740f767c-0fed-415f-b21c-c4201fc231d5","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"Building a Decorator — Step by Step","type":"text"}],"id":"58479022-7139-4ecc-8455-ef2b1f75d8e5","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"First, understand that ","type":"text"},{"styles":{"bold":true},"text":"functions in Python are objects","type":"text"},{"styles":{},"text":" — you can pass them around like variables:","type":"text"}],"id":"41d38384-64a7-408e-89de-5a203551b77b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"pythondef greet():\n    return \"Hello\"\n\n# Pass a function as an argument to another function\ndef shout(func):\n    result = func()\n    return result.upper()\n\nprint(shout(greet))   # \"HELLO\"                    \n  ","type":"text"}],"id":"e199092d-f91b-497c-8b95-f6d5963270d4","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"A decorator is just this pattern formalised:","type":"text"}],"id":"b6699665-0b9e-4447-8b49-80ec1344022e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"python# Step 1: A decorator is a function that takes a function and returns a function\ndef logger(func):                          # receives the original function\n    def wrapper(*args, **kwargs):          # the new \"wrapped\" version\n        print(f\"LOG: {func.__name__} called\")\n        result = func(*args, **kwargs)     # calls the original function\n        print(f\"LOG: {func.__name__} finished\")\n        return result\n    return wrapper                         # returns the wrapped version\n\n# Step 2: Apply manually (so you understand what @ does)\ndef get_balance(account_id):\n    return 50000\n\nget_balance = logger(get_balance)          # wrap it manually\n\n# Step 3: The @ syntax does EXACTLY the same thing — cleaner\n@logger\ndef deposit(account_id, amount):\n    return f\"Deposited Rs.{amount}\"\n\ndeposit(''ACC001'', 5000)\n# LOG: deposit called\n# LOG: deposit finished","type":"text"}],"id":"8411724e-00ff-4a54-b001-61c695a37dee","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"code":true},"text":"@logger","type":"text"},{"styles":{"bold":true},"text":" above a function is 100% identical to writing ","type":"text"},{"styles":{"code":true},"text":"deposit = logger(deposit)","type":"text"},{"styles":{"bold":true},"text":" after it.","type":"text"},{"styles":{},"text":" The ","type":"text"},{"styles":{"code":true},"text":"@","type":"text"},{"styles":{},"text":" is just syntactic sugar — a shortcut Python provides.","type":"text"}],"id":"e9dd189e-21e0-4792-945a-af648a4d6d85","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"e752f490-27ec-4f4b-9f05-8a6013f50808","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"code":true},"text":"args","type":"text"},{"styles":{"bold":true},"text":" and ","type":"text"},{"styles":{"code":true},"text":"*kwargs","type":"text"},{"styles":{"bold":true},"text":" — Why the Wrapper Needs Them","type":"text"}],"id":"2a3214b1-f88a-4dec-ab5c-8bbef79bf17c","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"code":true},"text":"pythondef wrapper(*args, **kwargs): result = func(*args, **kwargs)","type":"text"}],"id":"c2a91cf7-6c8c-4e69-85ff-ace1499a75d6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"The wrapper doesn''t know in advance how many arguments the original function takes. ","type":"text"},{"styles":{"code":true},"text":"*args","type":"text"},{"styles":{},"text":" captures any positional arguments, ","type":"text"},{"styles":{"code":true},"text":"**kwargs","type":"text"},{"styles":{},"text":" captures any keyword arguments — and passes them through unchanged. This makes the decorator ","type":"text"},{"styles":{"bold":true},"text":"universal","type":"text"},{"styles":{},"text":" — it works on any function regardless of its signature.","type":"text"}],"id":"dfc3cde6-2341-4cb5-9bd4-2582ea5cf5d4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"python# Works on a function with no arguments\n@logger\ndef ping():\n    return \"pong\"\n\n# Works on a function with many arguments\n@logger\ndef transfer(from_acc, to_acc, amount, currency=''LKR''):\n    return f\"Transferred {amount}\"                    \n                      \n                      \n  ","type":"text"}],"id":"0af64cde-14f7-4038-aab1-9c218103e521","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"d7a77c5b-cc7e-4628-96b6-30a17eedbf0e","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"Real Banking Examples","type":"text"}],"id":"07139d73-823a-4146-9c9d-30e521f5cc72","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"pythonimport time\nimport functools\n\n# 1. TIMING DECORATOR — how long did this take?\ndef timer(func):\n    @functools.wraps(func)          # preserves the original function''s name/docs\n    def wrapper(*args, **kwargs):\n        start = time.time()\n        result = func(*args, **kwargs)\n        duration = time.time() - start\n        print(f\"{func.__name__} took {duration:.4f} seconds\")\n        return result\n    return wrapper\n\n# 2. AUTHENTICATION DECORATOR — is the user logged in?\ndef require_auth(func):\n    @functools.wraps(func)\n    def wrapper(user, *args, **kwargs):\n        if not user.get(''is_authenticated''):\n            raise PermissionError(\"User not authenticated\")\n        return func(user, *args, **kwargs)\n    return wrapper\n\n# 3. VALIDATION DECORATOR — is the amount valid?\ndef validate_amount(func):\n    @functools.wraps(func)\n    def wrapper(*args, **kwargs):\n        amount = args[1] if len(args) > 1 else kwargs.get(''amount'')\n        if amount <= 0:\n            raise ValueError(\"Amount must be positive\")\n        return func(*args, **kwargs)\n    return wrapper\n\n# Apply multiple decorators — they stack top to bottom\n@timer\n@require_auth\n@validate_amount\ndef process_transfer(user, amount, to_account):\n    return f\"Transferred Rs.{amount} to {to_account}\"                    \n  ","type":"text"}],"id":"891a3869-3e41-4799-bf61-47dedc78fced","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Stacking order matters:","type":"text"}],"id":"377e69b1-ead1-4a43-9b9f-1048da042339","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"text@timer           ← outermost — runs first (starts the clock)\n@require_auth    ← middle\n@validate_amount ← innermost — closest to the actual function\ndef process_transfer(...)                    \n                      \n                      \n                      \n                      \n  ","type":"text"}],"id":"09648b40-4488-4258-bd38-9ecb71ac5df7","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"0d44b540-ad83-484b-b45f-89debce70ba9","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"code":true},"text":"@staticmethod","type":"text"},{"styles":{"bold":true},"text":" and ","type":"text"},{"styles":{"code":true},"text":"@classmethod","type":"text"},{"styles":{"bold":true},"text":" — Built-in Decorators","type":"text"}],"id":"2848cf2f-20c1-4746-a2f7-cbdd430ed6a6","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"These are Python''s own decorators for class methods:","type":"text"}],"id":"b3feef78-ba76-4c84-8eef-55ea6d4a2e3c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"pythonclass BankAccount:\n    bank_name = \"National Bank\"      # class-level attribute\n\n    def __init__(self, account_id, balance):\n        self.account_id = account_id\n        self.balance    = balance\n\n    # Regular method — needs self (the specific object)\n    def get_balance(self):\n        return self.balance\n\n    # @classmethod — works on the CLASS, not an instance\n    # Use when the method needs class-level data but not object data\n    @classmethod\n    def get_bank_name(cls):\n        return cls.bank_name\n\n    # @staticmethod — belongs to the class logically, but needs neither\n    # Use for utility functions that are related to the class concept\n    @staticmethod\n    def validate_account_id(account_id):\n        return account_id.startswith(''ACC'') and len(account_id) == 6\n\n# @classmethod — call on the class itself, no object needed\nprint(BankAccount.get_bank_name())             # \"National Bank\"\n\n# @staticmethod — call on the class, no object needed\nprint(BankAccount.validate_account_id(''ACC001''))  # True\nprint(BankAccount.validate_account_id(''XYZ''))     # False","type":"text"}],"id":"a1905ba6-ffb2-44cc-8ee2-912dfa3a8b37","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":{"columnWidths":[null,null,null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{"bold":true},"text":"Method Type","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"First Parameter","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"Access To","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"Use When","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Regular","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"code":true},"text":"self","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"object data + class data","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"most methods","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"@classmethod","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"code":true},"text":"cls","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"class data only","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"factory methods, class-level config","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"@staticmethod","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"nothing","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"neither","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"utility/helper functions logically related to the class","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"5c889220-30a2-429e-ac46-f48acaf718dd","props":{"textColor":"default"},"type":"table"},{"children":[],"id":"cab7f607-9d46-4bfe-b9d9-03cee515112b","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"⚡ Generators — Memory-Efficient Sequences","type":"text"}],"id":"08c5645b-a230-4648-874d-45f22dd92025","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"The Problem Generators Solve","type":"text"}],"id":"8235b524-5091-4cc1-bc97-ca7e4ea8c11e","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"python# This loads ALL 10 million transactions into memory at once — dangerous\ndef get_all_transactions():\n    transactions = []\n    for i in range(10_000_000):\n        transactions.append({''txn_id'': i, ''amount'': i * 100})\n    return transactions                    # 10 million dicts in RAM 💥","type":"text"}],"id":"bd2b2deb-1d1b-479d-b047-41ecd32165e6","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"In a banking system processing millions of records, you can''t load everything into memory. You need to process ","type":"text"},{"styles":{"bold":true},"text":"one item at a time","type":"text"},{"styles":{},"text":" — get it, use it, discard it, get the next one.","type":"text"}],"id":"cb607495-5f8c-4884-abbd-cc89521a4710","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Mental model — The Water Tap vs The Swimming Pool:","type":"text"}],"id":"0a556766-3a94-460d-88dc-7c6de64c98bd","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"A regular function returning a list is a swimming pool — all the water is there at once, filling your RAM. A generator is a tap — water flows one drop at a time, exactly when you ask for it. The tap doesn''t know how much water is in the reservoir. It just gives you the next drop on demand.","type":"text"}],"id":"0dcf370c-08d8-41b2-b6cc-1379c3ce0e2e","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"500dc3b5-31b2-4afd-b259-bc90c56e8316","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"code":true},"text":"yield","type":"text"},{"styles":{"bold":true},"text":" — The Generator Keyword","type":"text"}],"id":"6c706af9-34e8-4a87-b35b-ccb770d4bafb","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The only difference between a regular function and a generator is ","type":"text"},{"styles":{"code":true},"text":"yield","type":"text"},{"styles":{},"text":" instead of ","type":"text"},{"styles":{"code":true},"text":"return","type":"text"},{"styles":{},"text":":","type":"text"}],"id":"0133576e-df32-44fe-abb0-a33f0a945af1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"python# Regular function — computes everything, returns all at once\ndef get_transactions_list(n):\n    result = []\n    for i in range(n):\n        result.append({''txn_id'': f''T{i:04d}'', ''amount'': i * 100})\n    return result                     # all n items in memory\n\n# Generator function — computes one item, pauses, waits for next()\ndef get_transactions_gen(n):\n    for i in range(n):\n        yield {''txn_id'': f''T{i:04d}'', ''amount'': i * 100}\n        # ↑ pauses here, hands back one item, resumes on next request                    \n  ","type":"text"}],"id":"5e3d0b12-cb5e-440c-8622-bab92f3eb07b","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"What ","type":"text"},{"styles":{"code":true},"text":"yield","type":"text"},{"styles":{"bold":true},"text":" does:","type":"text"}],"id":"01b94542-b4ba-4c43-91b0-6ccbdd85e584","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Returns one value to the caller","type":"text"}],"id":"024616a1-1bac-4bb0-9dd5-d5d56026bfc9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Pauses the function","type":"text"},{"styles":{},"text":" — saves its entire state (local variables, where it is in the loop)","type":"text"}],"id":"1009c615-7663-4386-9d9c-1a78b93967a5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"When the caller asks for the next value, ","type":"text"},{"styles":{"bold":true},"text":"resumes from exactly where it paused","type":"text"}],"id":"33dab6c8-6fce-4b52-aa26-cb44cdba5e13","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"python# Using the generator — processes one transaction at a time\ngen = get_transactions_gen(10_000_000)\n\nfor transaction in gen:              # asks for next item each iteration\n    process(transaction)             # only ONE dict in memory at any time\n    # previous transaction is discarded                    \n  ","type":"text"}],"id":"87ccc400-a3ea-473b-a4dc-6be586c4120d","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"c82d73d5-805c-4cee-a412-7b9de7d1af63","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"Seeing the Pause in Action","type":"text"}],"id":"f282350c-0444-4b94-bd24-72bb3a31a46f","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"pythondef banking_events():\n    print(\"Setting up...\")\n    yield \"Account opened\"          # pause 1\n\n    print(\"Processing deposit...\")\n    yield \"Deposit received\"        # pause 2\n\n    print(\"Sending confirmation...\")\n    yield \"Confirmation sent\"       # pause 3\n\ngen = banking_events()\n\nprint(next(gen))   # \"Setting up...\"   then   \"Account opened\"\nprint(next(gen))   # \"Processing deposit...\"  then \"Deposit received\"\nprint(next(gen))   # \"Sending confirmation...\"then \"Confirmation sent\"\nprint(next(gen))   # StopIteration — generator exhausted                    \n  ","type":"text"}],"id":"08862bad-2bcc-4a31-9e3d-4177516baad9","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"The function doesn''t run to completion — it runs to the next ","type":"text"},{"styles":{"code":true},"text":"yield","type":"text"},{"styles":{},"text":", hands back a value, and freezes until you ask again.","type":"text"}],"id":"a49fd39b-8d19-47c2-aff1-71b1a8c08dbd","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"c761df7c-7da2-4220-8956-3b7ebf87502c","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"Practical Banking Generator","type":"text"}],"id":"2031308f-151a-462c-98ba-2abbe0b741ae","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"python# Process a massive transaction log file line by line\ndef read_transaction_log(filepath):\n    with open(filepath, ''r'') as f:\n        for line in f:\n            parts = line.strip().split('','')\n            yield {\n                ''txn_id'':  parts[0],\n                ''account'': parts[1],\n                ''amount'':  float(parts[2]),\n                ''type'':    parts[3]\n            }\n    # File closes automatically when generator is exhausted\n\n# Only ONE line in memory at a time — file could be 100GB\nfor transaction in read_transaction_log(''transactions.csv''):\n    if transaction[''type''] == ''DEBIT'' and transaction[''amount''] > 100000:\n        flag_for_review(transaction)                    \n  ","type":"text"}],"id":"226185ed-8a25-4410-8281-b0db582807d8","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"d693e122-7ec4-4355-9584-77536e207980","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"Generator Expression — One-Line Generator","type":"text"}],"id":"20d23651-a7e1-4a7e-b321-3f3e46a66799","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Just like list comprehensions, but with ","type":"text"},{"styles":{"code":true},"text":"()","type":"text"},{"styles":{},"text":" instead of ","type":"text"},{"styles":{"code":true},"text":"[]","type":"text"},{"styles":{},"text":":","type":"text"}],"id":"f198fce2-db87-47ec-858d-99a139aec65c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"pythonamounts = [5000, 2000, 8000, 15000, 3000]\n\n# List comprehension — creates full list in memory\ndoubled_list = [a * 2 for a in amounts]\n\n# Generator expression — lazy, one at a time\ndoubled_gen = (a * 2 for a in amounts)\n\n# Use directly in functions that iterate\ntotal = sum(a * 2 for a in amounts)   # no intermediate list created\nlarge = any(a > 10000 for a in amounts)   # stops at first True                    \n  ","type":"text"}],"id":"8ae966c3-e153-4a28-bb53-b95358c0cb7f","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"081ba9ad-10ce-4ac4-a268-38012cb8832d","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"🆚 Decorator vs Generator — Keeping Them Separate","type":"text"}],"id":"b0d0d511-1b94-4275-8bfa-b556edc643e6","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"These two concepts confuse people because they both use unusual syntax. Keep them distinct:","type":"text"}],"id":"08f2c7fd-db57-47da-b615-2327fa83b3ee","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"textDecorator   → WRAPS a function to add behaviour around it\n              Uses @syntax, wrapper pattern, *args/**kwargs\n              \"What happens before and after this function runs?\"\n\nGenerator   → PRODUCES values one at a time on demand\n              Uses yield, pauses and resumes\n              \"How do I process a million items without loading them all?\"                    \n  ","type":"text"}],"id":"b1afbd33-d8ae-4a04-a17c-52dbd34b2841","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"3500d51b-7537-4d68-b5f2-ea3641c81719","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"✅ Interview Questions","type":"text"}],"id":"4de62cc4-6820-4094-9c25-6d725be7375e","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"\"What is a decorator?\"","type":"text"}],"id":"02453374-c0f9-4d72-b26e-451ea52e32c4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true,"italic":true},"text":"\"A function that wraps another function to add behaviour before or after it runs — without modifying the original function. I use them for cross-cutting concerns like logging, timing, authentication, and validation. The ","type":"text"},{"styles":{"code":true},"text":"@syntax","type":"text"},{"styles":{"bold":true,"italic":true},"text":" is just shorthand for reassigning the function to its wrapped version.\"","type":"text"}],"id":"4583cc6c-1f72-405e-b53e-155d412fa4ab","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"bold":true},"text":"\"What does ","type":"text"},{"styles":{"code":true},"text":"*args","type":"text"},{"styles":{"bold":true},"text":" and ","type":"text"},{"styles":{"code":true},"text":"**kwargs","type":"text"},{"styles":{"bold":true},"text":" in a wrapper do?\"","type":"text"}],"id":"fe0b3102-b50a-42e5-9249-3e186d79cf6b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true,"italic":true},"text":"\"They let the wrapper accept any arguments the original function might take and pass them through unchanged. Without them, the decorator would only work on functions with specific signatures.\"","type":"text"}],"id":"8f07e10a-9c72-41ca-b3bb-bbbdf35cefd3","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"bold":true},"text":"\"What is a generator and why would you use one?\"","type":"text"}],"id":"afe37cbf-8ac6-44fb-a2b2-9d60397c3f85","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true,"italic":true},"text":"\"A function that uses ","type":"text"},{"styles":{"code":true},"text":"yield","type":"text"},{"styles":{"bold":true,"italic":true},"text":" instead of ","type":"text"},{"styles":{"code":true},"text":"return","type":"text"},{"styles":{"bold":true,"italic":true},"text":". It produces values one at a time and pauses between each one, only resuming when the next value is requested. I''d use it when processing large datasets — like a banking transaction log with millions of records — where loading everything into memory at once would crash the system.\"","type":"text"}],"id":"abcc165d-f393-4fb6-ab14-cfa07ca32f89","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"bold":true},"text":"\"What''s the difference between ","type":"text"},{"styles":{"code":true},"text":"yield","type":"text"},{"styles":{"bold":true},"text":" and ","type":"text"},{"styles":{"code":true},"text":"return","type":"text"},{"styles":{"bold":true},"text":"?\"","type":"text"}],"id":"a27cf49b-04cb-4552-ba6d-1b93b2ed9729","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true,"italic":true},"text":"\"","type":"text"},{"styles":{"code":true},"text":"return","type":"text"},{"styles":{"bold":true,"italic":true},"text":" ends the function and hands back one value. ","type":"text"},{"styles":{"code":true},"text":"yield","type":"text"},{"styles":{"bold":true,"italic":true},"text":" pauses the function, hands back a value, and saves the function''s state so it can resume from exactly that point when called again.\"","type":"text"}],"id":"7d20ab2d-5d93-4747-a2ab-d561ea1b0186","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[],"id":"eb5820b0-3a12-48b3-8152-302ef7c25a05","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"}]'::jsonb, '3e9e3dd3-a59b-4b02-968a-ee95e7317583') ON CONFLICT ("node_id") DO UPDATE SET "bad_example" = EXCLUDED."bad_example", "completed_at" = EXCLUDED."completed_at", "created_at" = EXCLUDED."created_at", "definition" = EXCLUDED."definition", "good_example" = EXCLUDED."good_example", "is_completed" = EXCLUDED."is_completed", "key_points" = EXCLUDED."key_points", "last_edited" = EXCLUDED."last_edited", "map_id" = EXCLUDED."map_id", "mental_model" = EXCLUDED."mental_model", "notes" = EXCLUDED."notes", "resources" = EXCLUDED."resources", "rich_content" = EXCLUDED."rich_content", "user_id" = EXCLUDED."user_id";
INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-06-13T06:21:56.355545+00:00', '', '', 'e294d556-9310-44ac-93c9-667e2677436c', false, '[]'::jsonb, '2026-06-13T06:22:14.555+00:00', '2ad473fe-77dd-481e-8ba7-4b2b0336173f', '', '3413c3a0-d563-4351-8fbb-2dfbe2bddedf', '', '[]'::jsonb, '[{"children":[],"id":"ef6c1b4a-0043-4f74-9cb9-9020307ee2d3","props":{"backgroundColor":"default","caption":"","name":"image.png","showPreview":true,"textAlignment":"left","url":"https://ixmvqmfesibpnrjmvzuj.supabase.co/storage/v1/object/public/study-assets/3e9e3dd3-a59b-4b02-968a-ee95e7317583/3413c3a0-d563-4351-8fbb-2dfbe2bddedf/1781331716785-jp7l5ltqp69.webp"},"type":"image"},{"children":[],"content":[{"styles":{"bold":true},"text":"What really happens when you run a Python script?","type":"text"}],"id":"0ba89945-66ea-4e37-89c5-062a4cab0987","props":{"backgroundColor":"rgb(21, 21, 23)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(249, 250, 251)"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Step 0: The Python Interpreter Starts","type":"text"}],"id":"e3854eca-153f-4dd6-84e9-04a82ce55dcf","props":{"backgroundColor":"rgb(21, 21, 23)","isToggleable":false,"level":3,"textAlignment":"left","textColor":"rgb(249, 250, 251)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"When you run ","type":"text"},{"styles":{"code":true},"text":"python my_script.py","type":"text"},{"styles":{},"text":", the Python executable (e.g., CPython) loads into memory.","type":"text"}],"id":"818ae126-5a23-4a8b-aefa-ae3237756646","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"It sets up essential data structures: the module cache, built-in functions, and the ","type":"text"},{"styles":{"bold":true},"text":"Garbage Collector","type":"text"},{"styles":{},"text":" (which starts running in the background).","type":"text"}],"id":"a703ebe7-190f-45ec-8e8b-8340d759c41a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"It also initializes the ","type":"text"},{"styles":{"bold":true},"text":"Global Interpreter Lock (GIL)","type":"text"},{"styles":{},"text":"—a mutex that prevents multiple threads from executing Python bytecode at the same time.","type":"text"}],"id":"f5ee3e77-d953-4b5d-942c-2059d712b0e2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Step 1: Parsing into an Abstract Syntax Tree (AST)","type":"text"}],"id":"3fb73979-a691-48f4-b302-95ce6cb9af89","props":{"backgroundColor":"rgb(21, 21, 23)","isToggleable":false,"level":3,"textAlignment":"left","textColor":"rgb(249, 250, 251)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Python reads your ","type":"text"},{"styles":{"code":true},"text":".py","type":"text"},{"styles":{},"text":" file as raw text.","type":"text"}],"id":"f38470c8-ab09-4372-85fe-b7a54759d50b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"It parses the text into an ","type":"text"},{"styles":{"bold":true},"text":"AST","type":"text"},{"styles":{},"text":"—a tree structure that represents the grammatical rules of your code (e.g., \"this is an ","type":"text"},{"styles":{"code":true},"text":"if","type":"text"},{"styles":{},"text":" statement containing a ","type":"text"},{"styles":{"code":true},"text":"print","type":"text"},{"styles":{},"text":" call\").","type":"text"}],"id":"46d286b3-2c66-4301-8beb-62f298f7005a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"This is where syntax errors are caught. If parsing fails, the script stops immediately.","type":"text"}],"id":"d2116ab7-5f70-47d7-96eb-3b4f47a70397","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Step 2: Compilation to Bytecode","type":"text"}],"id":"835fc65e-9531-44e7-ae6f-83a3628d019d","props":{"backgroundColor":"rgb(21, 21, 23)","isToggleable":false,"level":3,"textAlignment":"left","textColor":"rgb(249, 250, 251)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Python walks the AST and compiles it into bytecode—a low-level, platform-independent instruction set (e.g., LOAD_FAST, CALL_FUNCTION, RETURN_VALUE).","type":"text"}],"id":"6a5581a3-a2e9-46cf-9918-56b04cceb0a5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"This compilation happens all at once per code block (module, function, or class body). Not line by line.","type":"text"}],"id":"2e5dff40-76ba-4962-9e34-abb22c09406e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"For the main script, bytecode is kept in memory but not saved to disk.","type":"text"}],"id":"a67601bd-d1c7-469c-958f-87c53d9fff9d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"For imported modules (e.g., import math), Python saves the bytecode as a .pyc file inside a ","type":"text"},{"styles":{"bold":true},"text":"pycache","type":"text"},{"styles":{},"text":" folder. On the next run, if the source .py hasn''t changed, Python loads the .pyc directly—skipping parsing and compilation entirely.","type":"text"}],"id":"5b02ed2c-6d4b-4c19-9b8b-341fb55956ea","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Step 3: Execution by the Python Virtual Machine (PVM)","type":"text"}],"id":"69bbec98-fe07-4ce3-a070-debd79502bd6","props":{"backgroundColor":"rgb(21, 21, 23)","isToggleable":false,"level":3,"textAlignment":"left","textColor":"rgb(249, 250, 251)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The PVM is a large loop inside CPython that reads the bytecode instructions one by one.","type":"text"}],"id":"8410cb45-b8d7-49fc-b005-6e4670eb940c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"For each instruction (e.g., ","type":"text"},{"styles":{"code":true},"text":"BINARY_ADD","type":"text"},{"styles":{},"text":"), the PVM performs the corresponding operation (e.g., pop two numbers off the stack, add them, push the result).","type":"text"}],"id":"6e769f27-f81e-4fd7-b109-ccc17f3e558a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"This happens ","type":"text"},{"styles":{"bold":true},"text":"during runtime","type":"text"},{"styles":{},"text":" and is why Python is called an interpreted language.","type":"text"}],"id":"e2e7b87a-4ddb-49e5-bf13-65f390c02508","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Important:","type":"text"},{"styles":{},"text":" The PVM does not execute your original Python lines. It executes bytecode. One Python line can become 5–20 bytecode instructions.","type":"text"}],"id":"781a54c4-1c30-4f82-aa32-abe8f342ce65","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Step 4: Memory Management (Runs Throughout)","type":"text"}],"id":"e50b4d00-c66f-4b1b-bd3c-697948740037","props":{"backgroundColor":"rgb(21, 21, 23)","isToggleable":false,"level":3,"textAlignment":"left","textColor":"rgb(249, 250, 251)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"While the PVM is executing bytecode, Python is constantly managing memory in two ways:","type":"text"}],"id":"84eaa3a0-e500-4d48-9459-a99d9d21548c","props":{"backgroundColor":"rgb(21, 21, 23)","textAlignment":"left","textColor":"rgb(249, 250, 251)"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Reference Counting (Immediate):","type":"text"},{"styles":{},"text":" Every Python object (like ","type":"text"},{"styles":{"code":true},"text":"[1, 2, 3]","type":"text"},{"styles":{},"text":" or ","type":"text"},{"styles":{"code":true},"text":"\"hello\"","type":"text"},{"styles":{},"text":") stores a count of how many references point to it. When that count reaches zero, the object is ","type":"text"},{"styles":{"bold":true},"text":"deleted immediately","type":"text"},{"styles":{},"text":" and its memory is freed. This is deterministic and fast.","type":"text"}],"id":"18e52c49-36db-45f0-9169-fe1975ab840c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Garbage Collection (Periodic):","type":"text"},{"styles":{},"text":" Reference counting cannot handle ","type":"text"},{"styles":{"bold":true},"text":"reference cycles","type":"text"},{"styles":{},"text":" (e.g., Object A refers to B, and B refers to A, but nothing else refers to either). Python''s garbage collector periodically runs in the background, detects these cycles, and cleans them up.","type":"text"}],"id":"68df8fbf-899b-4662-a471-aec96f922318","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Step 5: Dynamic Features (The \"Uncompiled\" Behavior)","type":"text"}],"id":"6604948f-6db4-4924-a8e9-5086a408efa4","props":{"backgroundColor":"rgb(21, 21, 23)","isToggleable":false,"level":3,"textAlignment":"left","textColor":"rgb(249, 250, 251)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Unlike compiled languages (C, Rust), Python allows code to change itself ","type":"text"},{"styles":{"bold":true},"text":"at runtime","type":"text"},{"styles":{},"text":":","type":"text"}],"id":"cbe16283-d10a-44d5-b6e6-a7e4e6acf3dc","props":{"backgroundColor":"rgb(21, 21, 23)","textAlignment":"left","textColor":"rgb(249, 250, 251)"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"You can ","type":"text"},{"styles":{"code":true},"text":"eval(\"print(''hello'')\")","type":"text"},{"styles":{},"text":" to compile and execute new code on the fly.","type":"text"}],"id":"7009abd3-bdbd-4c71-bddf-f01421d3667b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"You can add, modify, or delete attributes of objects and classes while the program is running.","type":"text"}],"id":"ad66614d-9631-44de-86ae-3bed30d72f47","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"You can import modules from paths that were created ","type":"text"},{"styles":{"bold":true},"text":"during execution","type":"text"},{"styles":{},"text":" (e.g., downloading a module, then importing it).","type":"text"}],"id":"648cc52b-4f71-424f-9146-e2f519b76a52","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"This dynamic behavior is why the AST and bytecode are not permanently fixed—they can be extended or modified at runtime, though this is slower.","type":"text"}],"id":"882f6d1f-4baf-4ed9-bcaa-85d88d48849f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Step 6: The Global Interpreter Lock (GIL)","type":"text"}],"id":"4060b6d2-ea90-4e90-af20-4cc40d99e858","props":{"backgroundColor":"rgb(21, 21, 23)","isToggleable":false,"level":3,"textAlignment":"left","textColor":"rgb(249, 250, 251)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The GIL ensures that only one thread at a time can execute Python bytecode.","type":"text"}],"id":"17eaad97-a8d2-4558-9e08-d83a95d5f409","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"This simplifies memory management (reference counting doesn''t need complex locks) but means that CPU-bound multithreaded Python code won''t run faster on multiple cores.","type":"text"}],"id":"f31195cd-2851-4759-a725-909d3a5b9c55","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"To use multiple cores, you must use ","type":"text"},{"styles":{"bold":true},"text":"multiple processes","type":"text"},{"styles":{},"text":" (e.g., ","type":"text"},{"styles":{"code":true},"text":"multiprocessing","type":"text"},{"styles":{},"text":" module) or write CPU-intensive parts in C extensions.","type":"text"}],"id":"fba966c9-2fe1-479e-b6d8-478efb1c04a8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Step 7: The Program Ends","type":"text"}],"id":"a7f43ba8-f374-4d4c-a0fb-052fbe9abb02","props":{"backgroundColor":"rgb(21, 21, 23)","isToggleable":false,"level":3,"textAlignment":"left","textColor":"rgb(249, 250, 251)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"When the PVM finishes executing the last bytecode (or an unhandled exception occurs), Python begins shutdown.","type":"text"}],"id":"dc2be94e-e043-4118-a2ab-04b518ba5355","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"It calls ","type":"text"},{"styles":{"code":true},"text":"atexit","type":"text"},{"styles":{},"text":" functions, flushes buffers, and frees remaining memory.","type":"text"}],"id":"4fc04ac8-c1d4-4372-b0dc-e71024d8394e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"The operating system reclaims any final resources (memory, file handles).","type":"text"}],"id":"dd91892c-e7ba-44e8-83fc-958f4e361465","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"The Full Picture (One Paragraph)","type":"text"}],"id":"17ea2810-da4f-40fb-8bef-b9666a3f2ca6","props":{"backgroundColor":"rgb(21, 21, 23)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(249, 250, 251)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Python starts the interpreter, then ","type":"text"},{"styles":{"bold":true},"text":"parses","type":"text"},{"styles":{},"text":" your source code into an Abstract Syntax Tree (AST). It ","type":"text"},{"styles":{"bold":true},"text":"compiles","type":"text"},{"styles":{},"text":" the AST into bytecode all at once (saving ","type":"text"},{"styles":{"code":true},"text":".pyc","type":"text"},{"styles":{},"text":" files for imported modules). Then the ","type":"text"},{"styles":{"bold":true},"text":"Python Virtual Machine (PVM)","type":"text"},{"styles":{},"text":" executes the bytecode sequentially, while the ","type":"text"},{"styles":{"bold":true},"text":"reference counter","type":"text"},{"styles":{},"text":" and ","type":"text"},{"styles":{"bold":true},"text":"garbage collector","type":"text"},{"styles":{},"text":" manage memory in the background—all guarded by the ","type":"text"},{"styles":{"bold":true},"text":"Global Interpreter Lock (GIL)","type":"text"},{"styles":{},"text":". Because Python supports dynamic features like ","type":"text"},{"styles":{"code":true},"text":"eval","type":"text"},{"styles":{},"text":" and runtime class modification, it cannot be fully compiled ahead of time like C or Rust. This hybrid model—","type":"text"},{"styles":{"bold":true},"text":"compile to bytecode, then interpret","type":"text"},{"styles":{},"text":"—combined with automatic memory management and the GIL, is the complete story of how CPython (the standard Python) works.","type":"text"}],"id":"10717631-d091-4a47-a118-c09ca65209d8","props":{"backgroundColor":"rgb(21, 21, 23)","textColor":"rgb(249, 250, 251)"},"type":"quote"},{"children":[],"content":[],"id":"8bebf52d-8fc1-437c-93bf-fc507b49d0ba","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"}]'::jsonb, '3e9e3dd3-a59b-4b02-968a-ee95e7317583') ON CONFLICT ("node_id") DO UPDATE SET "bad_example" = EXCLUDED."bad_example", "completed_at" = EXCLUDED."completed_at", "created_at" = EXCLUDED."created_at", "definition" = EXCLUDED."definition", "good_example" = EXCLUDED."good_example", "is_completed" = EXCLUDED."is_completed", "key_points" = EXCLUDED."key_points", "last_edited" = EXCLUDED."last_edited", "map_id" = EXCLUDED."map_id", "mental_model" = EXCLUDED."mental_model", "notes" = EXCLUDED."notes", "resources" = EXCLUDED."resources", "rich_content" = EXCLUDED."rich_content", "user_id" = EXCLUDED."user_id";
INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-06-14T10:03:12.187667+00:00', '', '', '7bece0ab-cf16-4096-800b-5d6ceaa455bc', false, '[]'::jsonb, '2026-06-14T12:05:40.059+00:00', '2ad473fe-77dd-481e-8ba7-4b2b0336173f', '', 'c3b995f7-b4bf-4f1d-b43c-f466cc0f5a5d', '', '[]'::jsonb, '[{"children":[],"content":[{"styles":{},"text":"Database Theory Fundamentals — ACID, Normalization, Relational vs NoSQL — Interview-Ready Note","type":"text"}],"id":"577dc1f8-f7cb-4439-8e58-4320ea16df8c","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Target:","type":"text"},{"styles":{},"text":" Sysco LABS · EY GDS · Dialog Axiata — Data Engineering Intern / Junior Data Engineer","type":"text"}],"id":"bc37d893-2017-4581-9a48-46eba70289ce","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"04cec2da-2e4e-491f-9835-e8e4acd2fd4b","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"1. Mental Model","type":"text"}],"id":"8a378a4d-e49b-4ddd-a437-6f959972779d","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"ACID is like the safety rules of a bank transaction — every step must complete fully, correctly, independently, and permanently.","type":"text"},{"styles":{},"text":" ","type":"text"},{"styles":{"bold":true},"text":"Normalization is like organizing information into clean separate files to avoid duplicate mistakes — each piece of data lives in exactly one place.","type":"text"},{"styles":{},"text":" ","type":"text"},{"styles":{"bold":true},"text":"Relational databases are like structured filing cabinets with labeled drawers and strict cross-references.","type":"text"},{"styles":{},"text":" ","type":"text"},{"styles":{"bold":true},"text":"NoSQL databases are like flexible storage systems designed for different data shapes and scale — a key rack, a document binder, a wide spreadsheet, or a web of connected notes.","type":"text"}],"id":"ceefea83-e282-4a34-a2eb-fc1994189361","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{},"text":"Let''s make each one concrete.","type":"text"}],"id":"9140d1ce-563e-42e5-9273-a57e18f7f5bb","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"07c94202-b776-4a43-b99f-e46591712952","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"ACID — The Bank Vault Rules","type":"text"}],"id":"5e3b082f-9ac1-461e-98eb-f94d0f717c09","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Imagine you''re at a bank counter transferring Rs. 50,000 from your savings account to your current account.","type":"text"}],"id":"65f87604-cbf4-41d3-bd74-16c7da00c7dd","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"The banker follows four absolute rules:","type":"text"}],"id":"6ead2b9b-72c5-4797-8242-37e61590891a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Atomicity:","type":"text"},{"styles":{},"text":" Both the withdrawal and deposit happen ","type":"text"},{"styles":{"bold":true},"text":"completely","type":"text"},{"styles":{},"text":" or ","type":"text"},{"styles":{"bold":true},"text":"not at all","type":"text"},{"styles":{},"text":". If the system crashes halfway, the money doesn''t vanish — it rolls back fully.","type":"text"}],"id":"13239e80-08b4-444f-8455-35f000ba9837","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Consistency:","type":"text"},{"styles":{},"text":" Before and after, the bank''s total money across all accounts ","type":"text"},{"styles":{"bold":true},"text":"must balance","type":"text"},{"styles":{},"text":". No rule can be broken — like creating money from nowhere.","type":"text"}],"id":"f336ef00-6759-436d-ba15-e9b50eac1a1d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Isolation:","type":"text"},{"styles":{},"text":" If someone else transfers money at the exact same moment, their transaction won''t interfere with yours. Each sees a stable, separate view until both complete.","type":"text"}],"id":"91f8a029-c498-4c80-a238-bff5545fd2b5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Durability:","type":"text"},{"styles":{},"text":" Once the banker stamps \"Confirmed,\" that transfer is permanent. A power outage 10 seconds later cannot undo it.","type":"text"}],"id":"37b4cffa-b718-47e3-a95b-e4d4fab56f40","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"These are the ACID properties — non-negotiable for any system handling money, orders, or anything where correctness is paramount.","type":"text"}],"id":"8b2699bf-86a9-45b3-9009-9e6f992596b9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"237371ba-b2a8-4234-a7e3-432224c9c0a1","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Normalization — The Clean File System","type":"text"}],"id":"0719cc96-4b6a-4ba6-b37c-c5d9de7f4a87","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Imagine a messy single spreadsheet tracking everything in a business:","type":"text"}],"id":"01b9255d-e173-4f8c-9fb8-a79589c89e36","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Order ID | Customer | Customer City | Product | Category | Category Head\n1001     | Ashan    | Colombo       | Phone   | Electronics | Nuwan Silva\n1002     | Ashan    | Colombo       | Laptop  | Electronics | Nuwan Silva\n1003     | Nayomi   | Kandy         | Phone   | Electronics | Nuwan Silva","type":"text"}],"id":"9029cbeb-9c59-48b0-af42-5a26a0ad4b81","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Problems:","type":"text"}],"id":"e27e8477-c0a1-4939-8ff1-9cd55a7317c7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"\"Electronics\" and \"Nuwan Silva\" are repeated hundreds of times","type":"text"}],"id":"b98e065b-4564-4e87-8ded-7026a8d0425d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"If Nuwan Silva changes, you must update every single row — miss one and you have inconsistency","type":"text"}],"id":"f416eb3f-2d05-4c61-86bb-67f65acfda3b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"If you delete the last order of a product, you accidentally lose the product itself","type":"text"}],"id":"ad6eb829-d79a-480f-a1da-cb800be4ceb7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Normalization","type":"text"},{"styles":{},"text":" splits this into clean, separate files:","type":"text"}],"id":"1c7bf510-1804-4bdf-904f-bc4beff9aec6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"code":true},"text":"customers","type":"text"},{"styles":{},"text":" file (customer info — stored once)","type":"text"}],"id":"13ec0fd6-8595-4c77-b0f7-e7ee264ed892","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"code":true},"text":"products","type":"text"},{"styles":{},"text":" file (product info — stored once)","type":"text"}],"id":"f602e9b5-73dc-40f5-a969-b24cbfa813f7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"code":true},"text":"categories","type":"text"},{"styles":{},"text":" file (category info — stored once)","type":"text"}],"id":"cd9baf48-ce0f-400a-b0d5-16109405386b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"code":true},"text":"orders","type":"text"},{"styles":{},"text":" file (just references — order belongs to a customer, contains a product)","type":"text"}],"id":"366d8b8e-75a4-459b-a7e2-7513edf9a262","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Each piece of data lives in ","type":"text"},{"styles":{"bold":true},"text":"exactly one place","type":"text"},{"styles":{},"text":". No duplication. Updates happen in one row. This is normalization.","type":"text"}],"id":"4c8e8ace-d532-4d30-ac62-c513275167e7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"5c5dc611-ee20-49aa-9b42-36dd80e908f6","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Relational vs NoSQL — Different Storage Systems","type":"text"}],"id":"9c123f51-1c86-4464-88df-b2801a799ca4","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Relational databases","type":"text"},{"styles":{},"text":" are like a well-organized filing cabinet:","type":"text"}],"id":"d86b451c-8bf4-489b-907d-dbb5c19dae42","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Every drawer has a rigid label (schema)","type":"text"}],"id":"08249340-64fb-4b58-a68b-ccb09332e0c5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Every file inside follows the same structure (tables with columns)","type":"text"}],"id":"a9e34775-41e1-437f-a218-509356942d66","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Files reference each other with clear cross-references (foreign keys)","type":"text"}],"id":"fc100edc-0d96-48cc-99ce-96ea1f8b1c53","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Perfect for data that fits cleanly into rows and columns","type":"text"}],"id":"90bedef0-c99a-4f6c-ae86-b597bd58bea7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"NoSQL databases","type":"text"},{"styles":{},"text":" are like a flexible storage facility with different sections:","type":"text"}],"id":"d684bdb1-eed9-4bd4-9ede-107551d778db","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Key-Value:","type":"text"},{"styles":{},"text":" A giant key rack — every item has a label, instantly retrieved by that label (Redis)","type":"text"}],"id":"0ff9dde4-35be-4d80-a3e0-630dae4e138b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Document:","type":"text"},{"styles":{},"text":" A binder of structured but flexible pages — each page can have different fields (MongoDB)","type":"text"}],"id":"51b20159-80df-45ea-abd5-ecc66031d826","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Column-Family:","type":"text"},{"styles":{},"text":" A massive, wide spreadsheet optimized for reading specific columns fast (Cassandra)","type":"text"}],"id":"3f38645c-3f6b-470f-9f3a-2ea32264229a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Graph:","type":"text"},{"styles":{},"text":" A web of sticky notes connected by strings — perfect for relationships and networks (Neo4j)","type":"text"}],"id":"add52261-408b-4f35-b773-9a52c3a5d677","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Each shape serves a different purpose. No one storage system solves everything.","type":"text"}],"id":"23005c96-d0e3-4fe2-ad26-76b4004bb42a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"66330b3c-e797-46be-8032-b8ade3a2e00b","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"2. Clear Concept Explanation","type":"text"}],"id":"7f6a44a9-c87d-4b7d-8955-3763fe107bc5","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"What is ACID?","type":"text"}],"id":"3ffc5041-6bf1-4b26-9dcc-60ea110d81f5","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"ACID","type":"text"},{"styles":{},"text":" is a set of four properties that guarantee database transactions are processed reliably in relational database systems:","type":"text"}],"id":"a8af4fb5-f497-46c1-8017-f7183de71176","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"A","type":"text"},{"styles":{},"text":"tomicity — All or nothing","type":"text"}],"id":"7d367c1c-a058-4b2f-8dbe-a3210edcc9bf","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"C","type":"text"},{"styles":{},"text":"onsistency — Rules are always respected","type":"text"}],"id":"2e206082-ecc1-4596-a695-78439a6e1ea8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"I","type":"text"},{"styles":{},"text":"solation — Transactions don''t interfere with each other","type":"text"}],"id":"2b5688fc-cd8f-4b7e-ad2a-21b48da80fa7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"D","type":"text"},{"styles":{},"text":"urability — Committed data is never lost","type":"text"}],"id":"cda59506-1701-4783-9aaf-f0b760a463b1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"ACID compliance is the gold standard for transactional integrity. It is critical for any system where data correctness is non-negotiable — banking, e-commerce payments, order management, inventory tracking.","type":"text"}],"id":"06dae804-a912-4f49-9d7c-617fc2203c06","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Why ACID Matters in Transactional Systems","type":"text"}],"id":"560ec7a4-a26e-4bd5-802b-f76908d3147f","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Without ACID, your system is vulnerable to:","type":"text"}],"id":"8fc42c49-250c-4c26-9b7c-479cd0c0d46e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Partial updates (money withdrawn but never deposited — it vanishes)","type":"text"}],"id":"623caf7f-04ee-4d4d-8ed9-0d1b6cbff3c8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Data corruption (two transactions interleave and produce an impossible state)","type":"text"}],"id":"fb560a25-8e21-43ea-af53-23428023eaa0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Lost data (system crashes after a confirmation, and the record disappears)","type":"text"}],"id":"e4433e05-e719-47f9-9988-a2eac5b1ddee","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Constraint violations (a sale recorded for a product that doesn''t exist)","type":"text"}],"id":"3bc6eb82-03a8-49c1-8cbe-db2a54e651e8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"ACID guarantees prevent all of these. In production OLTP systems, this is the foundation of trust.","type":"text"}],"id":"60dce27d-5178-4fdb-a14f-b756b76b34a0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"8eddc2a6-bab9-41ad-90a7-f03ffe77d657","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"What is Normalization?","type":"text"}],"id":"4988a93c-f9d5-4ec3-843c-8a1dd1dd3c66","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Normalization","type":"text"},{"styles":{},"text":" is a database design technique that organizes data to ","type":"text"},{"styles":{"bold":true},"text":"minimize redundancy and eliminate data anomalies","type":"text"},{"styles":{},"text":" by splitting data into multiple related tables.","type":"text"}],"id":"4a1ea153-a627-454d-801d-03be3c61d3ca","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"The goal: ","type":"text"},{"styles":{"bold":true},"text":"Each piece of data should exist in exactly one place.","type":"text"}],"id":"784b56e0-66c3-43f9-9b07-553130c4fcc2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Why Normalization is Used in OLTP Systems","type":"text"}],"id":"775a3b34-9c1c-492c-a365-0a3ebf2869b1","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"OLTP systems handle frequent writes and updates. If customer addresses are duplicated across 10,000 order rows, a single address change requires 10,000 updates. Normalization stores the address once in a ","type":"text"},{"styles":{"code":true},"text":"customers","type":"text"},{"styles":{},"text":" table — one update changes it everywhere it''s referenced.","type":"text"}],"id":"647b150f-20bf-4429-9745-09b31f2f8f1d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Normalization also prevents anomalies — situations where data becomes inconsistent because of how it''s stored.","type":"text"}],"id":"fbe3e23e-73ba-48ca-bb46-a12ed1ceee74","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"What are 1NF, 2NF, and 3NF? (Interview Level)","type":"text"}],"id":"68210a22-65de-480a-b1c7-cb7e923964e0","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"You don''t need to recite formal definitions. Understand the practical meaning:","type":"text"}],"id":"c7fa3c60-9771-4559-8a5b-a8ef09b1fa66","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":{"columnWidths":[null,null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Normal Form","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"In Simple Terms","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"What It Fixes","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"1NF","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Each cell contains ","type":"text"},{"styles":{"bold":true},"text":"one value","type":"text"},{"styles":{},"text":"; no repeating groups","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"A single cell can''t hold a list like \"Phone, Laptop\"","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"2NF","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Every non-key column depends on the ","type":"text"},{"styles":{"bold":true},"text":"whole primary key","type":"text"},{"styles":{},"text":", not part of it","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"If a table''s key is ","type":"text"},{"styles":{"code":true},"text":"(order_id, product_id)","type":"text"},{"styles":{},"text":", the ","type":"text"},{"styles":{"code":true},"text":"customer_name","type":"text"},{"styles":{},"text":" should not depend only on ","type":"text"},{"styles":{"code":true},"text":"order_id","type":"text"},{"styles":{},"text":" — it belongs in a customers table","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"3NF","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Every non-key column depends ","type":"text"},{"styles":{"bold":true},"text":"only on the primary key","type":"text"},{"styles":{},"text":", not on another non-key column","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"code":true},"text":"category_head","type":"text"},{"styles":{},"text":" depends on ","type":"text"},{"styles":{"code":true},"text":"category","type":"text"},{"styles":{},"text":", not on ","type":"text"},{"styles":{"code":true},"text":"product_id","type":"text"},{"styles":{},"text":" — it belongs in a categories table","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"e8d318c7-5537-4f2a-b053-e825323162b0","props":{"textColor":"default"},"type":"table"},{"children":[],"content":[{"styles":{"bold":true},"text":"Rule of thumb for OLTP:","type":"text"},{"styles":{},"text":" Design to at least 3NF. This eliminates most redundancy and all major anomaly types.","type":"text"}],"id":"0194ca0c-0902-4f0d-84b6-df315ae4c5af","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{},"text":"Why OLAP Systems Often Denormalize","type":"text"}],"id":"32223665-bb16-4bf9-b6d5-55d9971c855a","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"OLAP systems are ","type":"text"},{"styles":{"bold":true},"text":"read-heavy","type":"text"},{"styles":{},"text":", not write-heavy. They query millions of rows to aggregate, filter, and group.","type":"text"}],"id":"3261c10e-90db-405b-85bd-b797e9c4eebd","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Normalized schemas require many JOINs to reconstruct a full picture — and JOINs across millions of rows are expensive.","type":"text"}],"id":"8a3e9c94-a9ba-4aa4-8133-2f9e3177a29b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Denormalization intentionally reintroduces redundancy to:","type":"text"}],"id":"e4e6b0c5-d380-473a-b653-07b401dc4186","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Reduce the number of JOINs needed per query","type":"text"}],"id":"5dccdcc1-4cad-4836-9bd8-9cfc0f880215","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Make analytical queries faster","type":"text"}],"id":"768b5457-615c-48d1-bf8f-9c6a87dbf49a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Align with columnar storage engines (Snowflake, BigQuery) that work well with wide tables","type":"text"}],"id":"dae24584-bd00-4724-b345-73588d357d89","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"The trade-off:","type":"text"},{"styles":{},"text":" More storage and update complexity — but in OLAP, storage is cheap and updates are rare. Read speed wins.","type":"text"}],"id":"4ff28d73-3fa0-4bcf-b62c-5e8a384f73e4","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"53e4d8e7-d3ad-48e4-a1d9-5b974dfdd126","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"What are Relational Databases?","type":"text"}],"id":"5389dd66-8dbf-467e-91bb-66caa55045e0","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Relational databases","type":"text"},{"styles":{},"text":" organize data into ","type":"text"},{"styles":{"bold":true},"text":"tables","type":"text"},{"styles":{},"text":" (relations) with ","type":"text"},{"styles":{"bold":true},"text":"rows","type":"text"},{"styles":{},"text":" (tuples) and ","type":"text"},{"styles":{"bold":true},"text":"columns","type":"text"},{"styles":{},"text":" (attributes). Tables are connected through ","type":"text"},{"styles":{"bold":true},"text":"foreign keys","type":"text"},{"styles":{},"text":" that define explicit relationships.","type":"text"}],"id":"e793c781-3298-4c99-adb4-7bd8724c54ce","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Core characteristics:","type":"text"}],"id":"d202eaee-c3e3-4a47-8ebc-798c26400065","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Schema-on-write","type":"text"},{"styles":{},"text":" — structure must be defined before data is inserted","type":"text"}],"id":"87897ea8-27f6-4cef-9a77-a60b839ad43b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"ACID compliance","type":"text"},{"styles":{},"text":" — strong transactional guarantees","type":"text"}],"id":"6e5c9851-7f8e-4019-831c-dd8ad2fb428b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"SQL","type":"text"},{"styles":{},"text":" — standard query language (Structured Query Language)","type":"text"}],"id":"e301f761-ec26-4350-8bdc-fbb6657c9120","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Normalization","type":"text"},{"styles":{},"text":" — designed to minimize redundancy","type":"text"}],"id":"78a4ba81-66e7-4f38-8b46-dc7c91b46451","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Strong consistency","type":"text"},{"styles":{},"text":" — all reads reflect the latest committed state","type":"text"}],"id":"318f4448-a475-4cbb-b2d7-921f1bf21076","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"What are NoSQL Databases?","type":"text"}],"id":"705586f5-4168-4426-820c-b675407c01fb","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"NoSQL","type":"text"},{"styles":{},"text":" (\"Not Only SQL\") databases are a family of database systems designed to handle data models and scalability requirements that differ from traditional relational databases.","type":"text"}],"id":"f2424cb7-c83e-484f-acd7-ebfdb01fee72","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Core characteristics:","type":"text"}],"id":"a4a503d4-bc9e-4ce0-9988-19975418b4ec","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Schema flexibility","type":"text"},{"styles":{},"text":" — structure can evolve; doesn''t need to be pre-defined rigidly","type":"text"}],"id":"75e13c78-9d95-481c-96a0-d66fc68686c5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Eventual consistency","type":"text"},{"styles":{},"text":" common — may sacrifice strong consistency for availability and performance (CAP theorem)","type":"text"}],"id":"874cc481-bad1-4c12-af03-7b40f50a9750","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Horizontal scalability","type":"text"},{"styles":{},"text":" — designed to scale across many commodity servers","type":"text"}],"id":"5f9ae2ef-3684-43c6-bb9a-cfd19dc230dc","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Specialized data models","type":"text"},{"styles":{},"text":" — key-value, document, column-family, graph","type":"text"}],"id":"b6d93a67-630a-4799-91e6-7cc307b8c416","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Not ACID-at-all-costs","type":"text"},{"styles":{},"text":" — some NoSQL systems offer ACID within limits, but most prioritize scale and flexibility","type":"text"}],"id":"e7560ed7-4193-43c0-b329-299b3759839d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Why NoSQL Databases Exist","type":"text"}],"id":"d35f8695-94c6-4246-9ec7-dd9209d453d5","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"NoSQL emerged because certain modern workloads broke the relational model:","type":"text"}],"id":"400862ea-5ce1-4e56-a33d-cfd8380c5e07","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Problem with Relational","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"NoSQL Solution","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Rigid schema makes evolving data hard","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Flexible schema — add fields anytime","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Scaling reads/writes horizontally is complex","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Distributed by design — add servers easily","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"JOINs become slow at massive scale","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Denormalized data or join-free models","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Not optimized for unstructured data (logs, JSON)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Document stores handle nested data naturally","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Graph-like relationships are painful in SQL","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Graph databases traverse relationships natively","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"1968b864-fb18-4c29-a2f7-bc48b51f1cc6","props":{"textColor":"default"},"type":"table"},{"children":[],"content":[{"styles":{},"text":"How All This Connects to Data Engineering","type":"text"}],"id":"ebef18ff-8189-4bf6-9cab-a8f3ceffe8c3","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"As a data engineer, you work with ","type":"text"},{"styles":{"bold":true},"text":"all of these","type":"text"},{"styles":{},"text":":","type":"text"}],"id":"363c8d5c-c35d-4c98-8db0-52ecd92aff60","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"OLTP relational databases","type":"text"},{"styles":{},"text":" (PostgreSQL, MySQL) are your ","type":"text"},{"styles":{"bold":true},"text":"source systems","type":"text"},{"styles":{},"text":" — applications write transactions here; they are normalized and ACID-compliant","type":"text"}],"id":"71e6d116-3f7f-4ff2-9a69-a9a31776efac","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"NoSQL databases","type":"text"},{"styles":{},"text":" may also be source systems — event streams, user activity logs, IoT sensor data","type":"text"}],"id":"5dfbc16e-af3d-48a5-bfb7-9e32b2899214","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Your ETL/ELT pipelines","type":"text"},{"styles":{},"text":" extract from these sources, then transform and load into...","type":"text"}],"id":"aa1ffed8-67e9-40d6-b693-53436f43e3e4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"OLAP systems","type":"text"},{"styles":{},"text":" (Snowflake, BigQuery, Databricks) which are denormalized, non-ACID (or eventually consistent), and optimized for analytical reads","type":"text"}],"id":"4fea3207-efc6-4d0b-b348-8a02063626b9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"You''re not choosing one database type — you''re ","type":"text"},{"styles":{"bold":true},"text":"integrating and moving data across them","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"f48e374b-ff2c-4ad6-87e5-2a3776390fac","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"f1361acf-0f7d-49c9-b21b-3a32336e6bd5","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"3. ACID Properties","type":"text"}],"id":"b9729bfc-4acd-4802-a48e-d6102e34884b","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Property-by-Property with a Bank Transfer Example","type":"text"}],"id":"72ad36a6-eda5-4c99-b028-5cff31c0cd03","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Scenario:","type":"text"},{"styles":{},"text":" Ashan transfers Rs. 50,000 from his Savings account to his Current account.","type":"text"}],"id":"6f8d75c2-6974-4305-8bc8-347b5144cd04","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Atomicity — \"All or Nothing\"","type":"text"}],"id":"b23d25ed-4e28-4f68-a9f1-c8327bde0af5","props":{"backgroundColor":"default","isToggleable":false,"level":4,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The entire transaction runs completely, or not at all.","type":"text"}],"id":"aaa332b8-7404-4f8b-bc47-d219ebea5ded","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"bold":true},"text":"What happens:","type":"text"}],"id":"aef26468-61b3-46d7-b26f-b9fcb9d9f094","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Debit Rs. 50,000 from Savings","type":"text"}],"id":"20173561-d043-4bea-ac7e-30d0596baebd","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Credit Rs. 50,000 to Current","type":"text"}],"id":"c0784a53-e64f-46b3-ae34-4a80be5aaaa4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"If the system crashes after Step 1 but before Step 2, Atomicity ensures the debit is ","type":"text"},{"styles":{"bold":true},"text":"rolled back","type":"text"},{"styles":{},"text":". Money is not lost or created. Both operations succeed together or neither does.","type":"text"}],"id":"85ca5452-d6f5-4999-bfdc-2db457a8b2b0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"BEGIN TRANSACTION;\n    UPDATE accounts SET balance = balance - 50000 WHERE account_id = ''SAV-123'';\n    UPDATE accounts SET balance = balance + 50000 WHERE account_id = ''CUR-456'';\nCOMMIT;\n-- If anything fails between BEGIN and COMMIT, everything rolls back","type":"text"}],"id":"02b8b8c2-815b-4db6-8d08-b9e65473df0e","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Consistency — \"Rules Must Hold\"","type":"text"}],"id":"efea845d-aacf-41e3-9f86-1f6973054d9e","props":{"backgroundColor":"default","isToggleable":false,"level":4,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The database moves from one valid state to another. All constraints, triggers, and rules are satisfied.","type":"text"}],"id":"89932455-0c6e-4d02-89c0-6d7cffe1321a","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it means:","type":"text"}],"id":"8fbd675f-87ba-439f-9e9b-403c5888dd1f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"The total balance across all accounts before and after must be equal (money is not created)","type":"text"}],"id":"5c09ee2a-9239-402d-b177-3a2a0d4661fe","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"No account can go below its minimum balance if that constraint exists","type":"text"}],"id":"4b223b4c-ae35-41c4-9459-d65128fa38bd","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Foreign keys remain valid — no orphan records","type":"text"}],"id":"d1e1caa1-ee82-46d8-a1c2-45dae0fe3b75","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Isolation — \"Don''t Interfere\"","type":"text"}],"id":"c1edb935-6294-46c3-8597-868ccbd1c6e0","props":{"backgroundColor":"default","isToggleable":false,"level":4,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Concurrent transactions see a consistent view of the database. They do not interfere with each other''s intermediate states.","type":"text"}],"id":"eaaed7a5-73b8-45c6-a863-3cae1308766b","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it means:","type":"text"}],"id":"996e2b52-b4d2-494c-a958-0c2179400214","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"If someone checks Ashan''s balance while the transfer is in progress, they don''t see the money debited but not yet credited","type":"text"}],"id":"a1237229-4358-4c30-b0a5-e4d69ec70746","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Two transfers happening at the exact same time don''t produce unpredictable results","type":"text"}],"id":"923bd55b-5b56-48b0-b5fd-47feff028b9d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"The outcome is the same as if transactions ran one after another (serializability, at the strictest isolation level)","type":"text"}],"id":"90859922-a7a2-4532-8644-5af593f408e0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Durability — \"Permanent Once Confirmed\"","type":"text"}],"id":"0d14616d-dd40-44ad-b012-75e2bb1a7893","props":{"backgroundColor":"default","isToggleable":false,"level":4,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Once a transaction is committed, it survives permanently — even a system crash immediately after.","type":"text"}],"id":"b0f29060-324d-4415-84a8-42a46a256100","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it means:","type":"text"}],"id":"3fd085f7-ccc7-4585-ab15-6ded22226b9f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"After ","type":"text"},{"styles":{"code":true},"text":"COMMIT","type":"text"},{"styles":{},"text":" returns success, the transfer is permanent","type":"text"}],"id":"e3ac2603-21f4-4292-a34a-99a218a0d7ca","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"A power outage, server crash, or network failure cannot undo it","type":"text"}],"id":"1e76417c-8b77-4380-96b9-80bd1f526618","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"The database uses write-ahead logging (WAL) or similar mechanisms to survive crashes","type":"text"}],"id":"e466f5df-7787-4930-8fa1-858228539786","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"id":"1a3bb7c1-6d62-4c83-92fa-7329c6b4cbce","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Why ACID is Important for These Systems","type":"text"}],"id":"f1038467-1d94-445b-afaa-5639bd83dc19","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"System Type","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Why ACID Matters","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Banking","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Money must never be lost, created, or left in an intermediate state. Atomicity and durability are non-negotiable.","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"E-Commerce Payments","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"An order confirmed but not paid, or paid but not recorded, creates business and legal liability. All-or-nothing execution is critical.","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Order Management","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Reducing stock quantity but failing to record the order → lost inventory tracking. The updates must be atomic.","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Inventory Transactions","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Two warehouses can''t sell the same last unit. Isolation prevents simultaneous deduction of the same stock.","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"004822a6-05e8-45d1-90b3-05dc003fcdfe","props":{"textColor":"default"},"type":"table"},{"children":[],"content":[{"styles":{},"text":"Without ACID, your system has ","type":"text"},{"styles":{"bold":true},"text":"no transactional trust","type":"text"},{"styles":{},"text":". In any system handling money, goods, or critical state, that trust is the foundation of the entire application.","type":"text"}],"id":"cc054d80-8e65-499f-9933-87d49d79f998","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"949f62ab-af56-48f9-982c-d1eb2e49e056","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"4. Normalization Understanding","type":"text"}],"id":"09d51f0d-7064-42e4-9ed2-e6f4f17ce4a7","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Why Duplicate Data Causes Problems","type":"text"}],"id":"31a7d0bb-dbae-4581-b1f2-8e4f34fbadfb","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Consider a single denormalized ","type":"text"},{"styles":{"code":true},"text":"sales","type":"text"},{"styles":{},"text":" table:","type":"text"}],"id":"f6fbfaa4-9918-44f6-9389-3e459624ae4e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"order_id | customer_name | customer_city | product_name | category | category_head\n1001     | Ashan Perera  | Colombo       | Phone        | Elec     | Nuwan Silva\n1002     | Ashan Perera  | Colombo       | Laptop       | Elec     | Nuwan Silva\n1003     | Nayomi Dias   | Kandy         | Phone        | Elec     | Nuwan Silva","type":"text"}],"id":"2a618d38-c696-46ef-ae16-1b1138c8f11c","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"This creates three types of ","type":"text"},{"styles":{"bold":true},"text":"anomalies","type":"text"},{"styles":{},"text":":","type":"text"}],"id":"31b744d2-a685-4f5e-be6d-d53837fd23a0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"38a5a339-3400-437e-b364-144454fab627","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Update, Insert, and Delete Anomalies","type":"text"}],"id":"30ca8dbb-84d0-4352-9e20-8d12487f99e9","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Update Anomaly","type":"text"}],"id":"cba27a35-fde7-41c9-8859-a3af38179a44","props":{"backgroundColor":"default","isToggleable":false,"level":4,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"If Nuwan Silva (category head) changes:","type":"text"}],"id":"6d771c6e-40f0-4bd8-b641-4b50cfa2c3aa","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"UPDATE sales SET category_head = ''Kasun Fernando'' WHERE category = ''Elec'';","type":"text"}],"id":"e3ccead0-d25d-4d24-9e6e-7b658de14ea3","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"You must update ","type":"text"},{"styles":{"bold":true},"text":"every single row","type":"text"},{"styles":{},"text":" with that category. Miss one — and now some rows have Nuwan Silva, others Kasun Fernando. Data inconsistency.","type":"text"}],"id":"7fb49677-6388-4e76-a1a1-c4fa7fccc09a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Insert Anomaly","type":"text"}],"id":"7c95a36f-c386-4c27-aca1-acc6fea48936","props":{"backgroundColor":"default","isToggleable":false,"level":4,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"You want to add a new category \"Accessories\" with head \"Priya Raj\" — but you can''t insert it until someone actually orders an accessories product. The category has no order to attach to. You can''t store data about categories that haven''t sold yet.","type":"text"}],"id":"72d864d8-bf8f-4a54-8373-27dc7a3bbb4b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Delete Anomaly","type":"text"}],"id":"14459665-40e0-4c3a-af53-66ae4949980e","props":{"backgroundColor":"default","isToggleable":false,"level":4,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"You delete the only order for a specific product. Now all information about that product is gone — name, category, everything. Deleting a sale should not destroy product master data.","type":"text"}],"id":"6ea0f818-4799-4900-9505-41ad7c3691c7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"3bd58570-3c15-46f9-9247-cacb4e8b2353","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Normal Forms Explained Simply","type":"text"}],"id":"156b6190-6313-4040-9b98-bc1867bf5219","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"1NF — One Value Per Cell, No Repeating Groups","type":"text"}],"id":"7c96e1f8-758e-4b21-9105-0ee7cbaaa5e7","props":{"backgroundColor":"default","isToggleable":false,"level":4,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Problem:","type":"text"},{"styles":{},"text":" A cell containing ","type":"text"},{"styles":{"code":true},"text":"\"Phone, Laptop\"","type":"text"},{"styles":{},"text":" — multiple values.","type":"text"}],"id":"8289cef3-eeb0-453c-8065-4211bd9eee24","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Fix:","type":"text"},{"styles":{},"text":" Each cell holds a single atomic value. No repeating columns like ","type":"text"},{"styles":{"code":true},"text":"product_1","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"product_2","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"product_3","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"3c0e5292-32f0-4e16-9174-96a3189e0860","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"order_id | product_name\n1001     | Phone\n1001     | Laptop","type":"text"}],"id":"ed41b80f-00dc-4749-8f57-bcb56970a396","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"2NF — Depend on the Whole Primary Key","type":"text"}],"id":"ccd44485-c7d8-4b4b-af07-a31290371e95","props":{"backgroundColor":"default","isToggleable":false,"level":4,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Problem:","type":"text"},{"styles":{},"text":" In a table with composite key ","type":"text"},{"styles":{"code":true},"text":"(order_id, product_id)","type":"text"},{"styles":{},"text":", the column ","type":"text"},{"styles":{"code":true},"text":"customer_name","type":"text"},{"styles":{},"text":" depends only on ","type":"text"},{"styles":{"code":true},"text":"order_id","type":"text"},{"styles":{},"text":", not on the full key.","type":"text"}],"id":"409ea2cf-59b5-497e-90c2-9e8a753993c9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Fix:","type":"text"},{"styles":{},"text":" Split into ","type":"text"},{"styles":{"code":true},"text":"orders","type":"text"},{"styles":{},"text":" table (order-level info) and ","type":"text"},{"styles":{"code":true},"text":"order_items","type":"text"},{"styles":{},"text":" table (product-level info). Each non-key column depends on the entire primary key of its table.","type":"text"}],"id":"e7b22dbd-3980-447f-b9f6-058a6a0a8526","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"orders:     order_id | customer_name\norder_items: order_id | product_id | quantity","type":"text"}],"id":"93fc30d3-0be8-48bc-ae6e-d0314283831b","props":{"language":