INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-06-14T12:18:08.522562+00:00', '', '', 'a5412fcf-e663-4d73-838b-3e0ec97ac34d', false, '[]'::jsonb, '2026-06-14T12:22:08.056+00:00', '2ad473fe-77dd-481e-8ba7-4b2b0336173f', '', '6002def1-23ec-4f18-a29b-e8f131fed30f', '', '[]'::jsonb, '[{"children":[],"content":[{"styles":{},"text":"Apache Airflow — Basic Awareness — Interview-Ready Note","type":"text"}],"id":"40553a2c-e2d6-49cb-ade7-369fb9a7d7eb","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Target:","type":"text"},{"styles":{},"text":" Sysco LABS · EY GDS · Dialog Axiata — Data Engineering Intern / Junior Data Engineer","type":"text"}],"id":"f89cef94-2349-462c-930b-68e088aa3184","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"382d8a30-9dd8-4c0f-8f8e-36ae6a9122c1","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"1. Mental Model","type":"text"}],"id":"d31229b9-ab26-4c28-95e0-9f8a877b1853","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Airflow is like a project supervisor for data pipelines.","type":"text"},{"styles":{},"text":" ","type":"text"},{"styles":{"bold":true},"text":"It does not usually process the data itself. It decides what task should run, when it should run, what depends on what, and what should happen if something fails.","type":"text"}],"id":"0525b4ab-c277-40c3-9f7e-9949c6b809e3","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{},"text":"Imagine a construction site building a house.","type":"text"}],"id":"da909003-941f-4aed-acee-72696ba7fee8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"The ","type":"text"},{"styles":{"bold":true},"text":"construction supervisor","type":"text"},{"styles":{},"text":" doesn''t pour concrete, lay bricks, or install plumbing. Instead, the supervisor:","type":"text"}],"id":"4a122153-5daf-4850-805b-3b4a5cd31843","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Plans the sequence of work","type":"text"},{"styles":{},"text":" — foundation before walls, walls before roof","type":"text"}],"id":"ea3df27b-bc40-4c1f-8e7f-3f8b464e5953","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Schedules when each crew starts","type":"text"},{"styles":{},"text":" — electricians come after plumbers","type":"text"}],"id":"610c48a9-aefb-43aa-9035-c6e41dbf8034","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Monitors progress","type":"text"},{"styles":{},"text":" — checks if each stage is complete","type":"text"}],"id":"3588d56a-1b76-46e3-a82a-5d9701088ce0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Handles failures","type":"text"},{"styles":{},"text":" — if the concrete delivery is late, delays the next stage","type":"text"}],"id":"a36d1301-cd74-403e-969f-ae90396e3642","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Coordinates teams","type":"text"},{"styles":{},"text":" — ensures the right crew shows up at the right time","type":"text"}],"id":"22403625-9998-4c2a-b303-c1b2a339fde6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"That supervisor is ","type":"text"},{"styles":{"bold":true},"text":"Airflow","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"da2d3085-4b61-4ba8-9bb1-20a497efa831","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"The actual construction work — pouring concrete (extracting data), laying bricks (transforming data), installing wiring (loading data) — is done by ","type":"text"},{"styles":{"bold":true},"text":"specialist workers","type":"text"},{"styles":{},"text":" (Spark, SQL, Python scripts, dbt).","type":"text"}],"id":"3a3e2b60-e328-47bd-8c0e-0544fe88d00c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Airflow''s job is ","type":"text"},{"styles":{"bold":true},"text":"orchestration","type":"text"},{"styles":{},"text":" — making sure the right work happens in the right order at the right time.","type":"text"}],"id":"61dd7151-a7dc-4184-ac79-f589293c708e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"b84a7d34-2bda-4225-9667-1d8b5eff4a82","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"The Mapping","type":"text"}],"id":"61602fb9-8503-4ac6-8a8e-f733a804d32a","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Concept","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Mental Model","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"DAG","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"The construction blueprint — the full plan of what needs to be built and in what order","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Task","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"One specific job on the construction site — \"pour the foundation,\" \"install plumbing\"","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Dependency","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"The order rule — \"you can''t build the roof before the walls are up\"","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Scheduler","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"The site manager who checks the clock and says \"it''s time to start the next task\"","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Executor","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"The foreman who assigns workers to each task","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Web UI","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"The supervisor''s control room with live monitors showing progress on each task","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Operator","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"A task template — \"PythonOperator\" means \"run this Python script,\" like \"PlumbingOperator\" means \"install pipes\"","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"be349167-1687-46aa-a4bc-b57a0cd6966b","props":{"textColor":"default"},"type":"table"},{"children":[],"content":[{"styles":{"bold":true},"text":"This mental model makes Airflow instantly understandable to anyone — including non-technical interviewers.","type":"text"}],"id":"35b09744-a4b8-4421-b591-7a0b7800ef39","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"92e90a64-89ed-4d91-bde9-4cedcf8b85df","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"2. Clear Concept Explanation","type":"text"}],"id":"339b34c7-be0f-4d0f-8901-c9bc9f4015ef","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"What is Apache Airflow?","type":"text"}],"id":"71382e56-4d87-4856-92cb-346f2ed3fdf5","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Apache Airflow","type":"text"},{"styles":{},"text":" is an ","type":"text"},{"styles":{"bold":true},"text":"open-source workflow orchestration platform","type":"text"},{"styles":{},"text":" used to ","type":"text"},{"styles":{"bold":true},"text":"schedule, monitor, and manage data pipelines","type":"text"},{"styles":{},"text":" programmatically.","type":"text"}],"id":"e8739b8c-1685-43eb-8d94-2c57a0cab821","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"It was created by ","type":"text"},{"styles":{"bold":true},"text":"Airbnb","type":"text"},{"styles":{},"text":" in 2014 and is now the ","type":"text"},{"styles":{"bold":true},"text":"industry standard","type":"text"},{"styles":{},"text":" for orchestrating complex data workflows.","type":"text"}],"id":"afa9b388-8949-4323-9ded-2e7c5faad0e3","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Why Does Airflow Exist?","type":"text"}],"id":"1a7228ea-445c-4104-92fa-012d161bbf50","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Data engineering pipelines are ","type":"text"},{"styles":{"bold":true},"text":"not one-time scripts","type":"text"},{"styles":{},"text":". They are:","type":"text"}],"id":"a02faff7-305c-46fc-b811-b3c870bef566","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Scheduled","type":"text"},{"styles":{},"text":" — run daily, hourly, or in real-time","type":"text"}],"id":"ad41c80d-3389-45ad-8582-ab45a7d5c652","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Multi-step","type":"text"},{"styles":{},"text":" — extract → validate → transform → load → report","type":"text"}],"id":"a2db0414-3478-47bd-9304-e6739893de33","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Dependent","type":"text"},{"styles":{},"text":" — step 3 can''t run until step 2 succeeds","type":"text"}],"id":"d9b1de93-def0-48ee-8d4a-0759be64f299","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Failure-prone","type":"text"},{"styles":{},"text":" — APIs go down, networks timeout, data formats change","type":"text"}],"id":"d8561f97-5ccd-4023-b57e-1997f0c19b92","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Mission-critical","type":"text"},{"styles":{},"text":" — business decisions depend on data being ready on time","type":"text"}],"id":"15dd61e8-7aaf-49db-8070-f4fce555f4f3","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Before Airflow, teams used:","type":"text"}],"id":"b647f337-f6bb-4291-9084-c55a47f281d5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Cron jobs","type":"text"},{"styles":{},"text":" — simple scheduling, but no dependency management, no monitoring, no retry logic","type":"text"}],"id":"cc298820-9bd0-4806-8f08-6a05671622e9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Custom scripts","type":"text"},{"styles":{},"text":" — hard to maintain, no visibility, poor failure handling","type":"text"}],"id":"31b19548-17e5-4a79-b15e-390988b8bf1a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Enterprise schedulers","type":"text"},{"styles":{},"text":" (like Control-M, Autosys) — expensive, inflexible, not code-based","type":"text"}],"id":"1b4720eb-9c9b-4389-896b-f19dfa70cd1d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Airflow solved this by providing a ","type":"text"},{"styles":{"bold":true},"text":"Python-based, code-first","type":"text"},{"styles":{},"text":" way to define, schedule, and monitor workflows.","type":"text"}],"id":"9259104e-afdb-40dd-b755-401610d5a753","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"What Problem Does Airflow Solve in Data Engineering?","type":"text"}],"id":"34557ac6-139e-4e78-99c8-739e05a337c1","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":{"columnWidths":[null,null],"headerRows