left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Send Alert","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Notifies team of success/failure","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Email, Slack, PagerDuty","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"2a392604-a941-45a2-a1b1-2473dd2f3e92","props":{"textColor":"default"},"type":"table"},{"children":[],"id":"f20f7348-c237-4f82-9b6b-57d5bb79b7a4","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Why Task Order Matters","type":"text"}],"id":"e7c5e4f5-a46e-456b-a4e3-53df9054a749","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Correct order:","type":"text"}],"id":"67d06173-1a82-4569-b0be-62e60cfdd027","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"ingest → validate → transform → load → alert","type":"text"}],"id":"3f710236-9da9-46b9-a671-4aa586008ac2","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Incorrect order (violates dependencies):","type":"text"}],"id":"954aae03-d36a-4fb9-9f22-3e29964b0e4f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"load → transform → ingest  ❌ (You can''t load data before extracting it)","type":"text"}],"id":"c2d06aaf-e651-