INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-05-26T07:50:17.83907+00:00', '', '', '900739a1-f678-4f4b-821c-79c607cce04d', false, '[]'::jsonb, '2026-05-26T07:55:47.887+00:00', 'f22b10db-248b-447f-80b6-4a27bd9171ed', '', '9c1ecc4f-bb15-4770-aa8b-90b461c911b8', '', '[]'::jsonb, '[{"children":[],"content":[{"styles":{"bold":true},"text":"The Core Purpose","type":"text"}],"id":"b2b04f6d-2847-4efb-af29-e7227bc5702c","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Data engineering exists to ","type":"text"},{"styles":{"bold":true},"text":"bridge the gap between raw data and actionable business value","type":"text"},{"styles":{},"text":" — transforming chaotic, unusable data into structured, reliable pipelines that power real decisions.","type":"text"}],"id":"eb974d31-c121-4e82-9e6d-29e1eb9475d6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"a4d5457e-85ca-4b0f-b277-8bf57d981896","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"🧠 Mental Model — The Plumber Analogy","type":"text"}],"id":"863682dc-d02d-470f-bf81-d7d223653cf3","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Think of a data engineer as a ","type":"text"},{"styles":{"bold":true},"text":"highly skilled plumber","type":"text"},{"styles":{},"text":" connecting a city''s raw water supply to specialized home appliances:","type":"text"}],"id":"c8dd43f9-3087-4ae9-b06e-e094d5a6d143","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{"bold":true},"text":"Analogy","type":"text"}],"props":{"backgroundColor":"rgba(214, 213, 212, 0.035)","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"Real World","type":"text"}],"props":{"backgroundColor":"rgba(214, 213, 212, 0.035)","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Raw water supply","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Raw data from apps, sensors, databases","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Plumbing/pipes","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Data pipelines built by data engineers","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Home appliances","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"ML models, BI dashboards, analytics tools","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"c0e09876-f823-492c-aabe-3a5dfdf609b1","props":{"textColor":"default"},"type":"table"},{"children":[],"content":[{"styles":{"bold":true},"text":"Without the plumbing, the raw material exists — but cannot be safely or efficiently used to power the system.","type":"text"}],"id":"88853b9e-e8f4-4a35-b974-8045a84186f2","props":{"backgroundColor":"default","textColor":"rgb(214, 213, 212)"},"type":"quote"},{"children":[],"id":"37d2dd07-5ff5-4c5c-b306-c65443722567","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"📖 Why Data Engineering Exists","type":"text"}],"id":"521bae54-e6b5-4ba6-9c6f-8f8c0defdecb","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Every user interaction on the internet — clicking a product, liking a post, ordering food — ","type":"text"},{"styles":{"bold":true},"text":"generates raw data","type":"text"},{"styles":{},"text":". But businesses cannot make sense of this data in its native state.","type":"text"}],"id":"4af958f2-c333-4631-b5a9-9e6596ef1c72","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Data engineers fill the gap between two worlds:","type":"text"}],"id":"e14018af-495f-47aa-b3e5-4ae96a7e57f5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Front-end Software Engineers","type":"text"},{"styles":{},"text":" — build the apps that ","type":"text"},{"styles":{"italic":true},"text":"generate","type":"text"},{"styles":{},"text":" data","type":"text"}],"id":"7b9b0afa-dec3-4c8e-9446-cb81425c0726","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Data Scientists / Analysts","type":"text"},{"styles":{},"text":" — use data to ","type":"text"},{"styles":{"italic":true},"text":"predict the future","type":"text"},{"styles":{},"text":" or ","type":"text"},{"styles":{"italic":true},"text":"analyze past trends","type":"text"}],"id":"7ac97971-c2d8-4e6d-8a9b-72a16cf3aa6f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"What Data Engineers Enable","type":"text"}],"id":"3d3de93c-a289-4d62-bc21-811f44117820","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Move businesses away from ","type":"text"},{"styles":{"bold":true},"text":"human assumption-based decisions","type":"text"}],"id":"07fdccd0-ab58-4694-94b6-7379939c74a0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Shift toward ","type":"text"},{"styles":{"bold":true},"text":"factual, data-driven insights","type":"text"}],"id":"47c04a54-4be1-41d9-aed4-c843cb60fb0a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[{"children":[],"content":[{"styles":{},"text":"📈 Increase profit","type":"text"}],"id":"f2f692b3-7883-4be9-893b-8e178157a8e7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"🤝 Improve customer service","type":"text"}],"id":"77b8dee1-7e06-4afa-bcc3-5b2ca5e668a7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[{"children":[],"content":[{"styles":{"bold":true},"text":"⚠️ Key Principle: If a data pipeline does not ultimately help the business save costs, improve processes, or understand customers — it is considered completely useless.","type":"text"}],"id":"b0cbf17f-82c4-4069-8826-7759180ac735","props":{"backgroundColor":"default","textColor":"rgb(214, 213, 212)"},"type":"quote"}],"content":[{"styles":{},"text":"🔧 Fix operational bottlenecks","type":"text"}],"id":"404b8026-cf1a-494f-832f-b6293888705b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"}],"content":[{"styles":{},"text":"Help companies:","type":"text"}],"id":"65c890aa-fe2b-4c3b-80fc-ecfd4313cea5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"id":"ca137681-b7a4-46db-8984-e795796e6084","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"🔧 Application — Building an End-to-End Pipeline","type":"text"}],"id":"82dd3c91-2c47-41d4-ae0e-4ce7300012f6","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"In practice, achieving this core purpose involves a ","type":"text"},{"styles":{"bold":true},"text":"4-stage data pipeline","type":"text"},{"styles":{},"text":":","type":"text"}],"id":"8053796f-52a8-4a17-953b-84675235e69b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[{"children":[],"content":[{"styles":{},"text":"Relational databases (DBMS)","type":"text"}],"id":"113df930-3080-4145-a2ae-966adb1794ed","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Third-party APIs","type":"text"}],"id":"8a799053-c12e-41eb-a820-38bea66a88ac","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"IoT devices","type":"text"}],"id":"15b62662-4ab0-4c10-8e12-95d0ed1bc5c9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"}],"content":[{"styles":{"bold":true},"text":"Ingestion","type":"text"},{"styles":{},"text":" — Capture data from sources as soon as it is generated","type":"text"}],"id":"9613b286-c937-4c30-aa7c-d5739340bb74","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Storage","type":"text"},{"styles":{},"text":" — Persist the raw ingested data securely","type":"text"}],"id":"bf9d5275-3bda-40ea-8967-0ae70c7305de","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Transformation","type":"text"},{"styles":{},"text":" — Apply business logic to clean and format the data","type":"text"}],"id":"c8fddefa-c13d-4d1b-808c-6a27cfe0dadc","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Serving","type":"text"},{"styles":{},"text":" — Load structured data into a centralized storage layer (e.g., a data warehouse)","type":"text"}],"id":"5ddd3aef-47b1-4bca-bf82-e08b7505de0e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"text","type":"text"}],"id":"3edfac8e-3a79-4495-a167-e6309acf3385","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"code":true},"text":"[Source: DB / API / IoT]\n ↓\n [Ingestion Layer]\n ↓\n [Raw Storage]\n ↓\n [Transformation]\n ↓\n [Structured / Serving Layer]\n ↓\n[Analysts / ML Engineers / BI Dashboards]","type":"text"}],"id":"da006845-146c-4e90-9eab-920a1c79a0e6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"f804f63f-0e9e-4ebc-a6d7-5dea7a914a1a","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"💡 Real-World Examples","type":"text"}],"id":"6fe0b4ff-f81b-457b-9e1d-bb76b6bab72c","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"🛒 Amazon — Supply Chain Optimization","type":"text"}],"id":"4ae3a91c-b529-49b8-8ca3-e96626192561","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"A veteran shipping manager with 15 years of experience relies on ","type":"text"},{"styles":{"bold":true},"text":"human intuition","type":"text"},{"styles":{},"text":" to guess where bottlenecks occur","type":"text"}],"id":"d63bb629-cd94-49f5-ae74-ff97efacd5a1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Data engineers ","type":"text"},{"styles":{"bold":true},"text":"pipe factual shipping and order data","type":"text"},{"styles":{},"text":" into a dashboard","type":"text"}],"id":"0660f0e0-9988-4f8c-97dd-077392e17dde","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Result: The business can ","type":"text"},{"styles":{"bold":true},"text":"pinpoint exact delays","type":"text"},{"styles":{},"text":" and make purely data-driven operational decisions — no guesswork needed","type":"text"}],"id":"6c464dc7-ee6f-4aaa-896f-c367a2918498","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"📱 Instagram & Netflix — Recommendation Engines","type":"text"}],"id":"0363308e-b322-4fc0-a76e-fc6de829ffe7","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Every like, scroll, or movie watch generates ","type":"text"},{"styles":{"bold":true},"text":"raw engagement data","type":"text"}],"id":"03c82507-8b59-4b80-bc59-39ab52180a36","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Data engineers ","type":"text"},{"styles":{"bold":true},"text":"collect and format","type":"text"},{"styles":{},"text":" this massive volume of interaction data","type":"text"}],"id":"12ef0cff-2364-4694-af73-714a39b3f63f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Result: ML Engineers can train algorithms to serve ","type":"text"},{"styles":{"bold":true},"text":"highly personalized content","type":"text"},{"styles":{},"text":" — keeping users on the platform longer","type":"text"}],"id":"f3b652b2-39c5-431a-813f-00a85ba0273d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"id":"90124782-0357-43d7-8103-401065b9b1e5","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"🗝️ Key Takeaway","type":"text"}],"id":"928ea8b9-00a5-4958-808c-f88094c61939","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Data engineering is not just a technical discipline — it is a business-critical function. The value of a pipeline is always measured by its real-world business impact, not its technical sophistication.","type":"text"}],"id":"fbd78cdc-c8e5-4708-9e6e-eb83f6be6a4d","props":{"backgroundColor":"default","textColor":"rgb(214, 213, 212)"},"type":"quote"},{"children":[],"content":[{"styles":{},"text":"\n","type":"text"}],"id":"96befc14-fd2c-4f3c-a1c0-b85b04c8b1d4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[],"id":"bee6fcc7-783e-46e1-89c8-56152f007cfe","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"}]'::jsonb, '3e9e3dd3-a59b-4b02-968a-ee95e7317583') ON CONFLICT ("node_id") DO UPDATE SET "bad_example" = EXCLUDED."bad_example", "completed_at" = EXCLUDED."completed_at", "created_at" = EXCLUDED."created_at", "definition" = EXCLUDED."definition", "good_example" = EXCLUDED."good_example", "is_completed" = EXCLUDED."is_completed", "key_points" = EXCLUDED."key_points", "last_edited" = EXCLUDED."last_edited", "map_id" = EXCLUDED."map_id", "mental_model" = EXCLUDED."mental_model", "notes" = EXCLUDED."notes", "resources" = EXCLUDED."resources", "rich_content" = EXCLUDED."rich_content", "user_id" = EXCLUDED."user_id";
