INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-05-26T13:56:42.799919+00:00', '', '', 'ca1ab700-fa76-4dea-8ec1-20ccce7283ec', false, '[]'::jsonb, '2026-05-26T14:01:36.703+00:00', 'f22b10db-248b-447f-80b6-4a27bd9171ed', '', '1824e09b-36f1-4f27-8768-b484681bffe5', '', '[]'::jsonb, '[{"children":[],"content":[{"styles":{"bold":true},"text":"Slowly Changing Dimensions (SCD)","type":"text"}],"id":"5feab2eb-ad93-4085-9a30-90807e1e9b2a","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"In the real world, dimension data is ","type":"text"},{"styles":{"bold":true},"text":"not static","type":"text"},{"styles":{},"text":". A customer moves cities, a product changes its category, an employee gets promoted. ","type":"text"},{"styles":{"bold":true},"text":"Slowly Changing Dimensions (SCD)","type":"text"},{"styles":{},"text":" are the strategies data engineers use to decide how to handle these changes inside a data warehouse — balancing history retention against simplicity.","type":"text"}],"id":"6ad6bd82-b6eb-49b2-83d4-4f40b1d795ea","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"id":"a30ab4b1-d015-4794-8dac-798c068057ab","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"🏠 Mental Model — The Address Book Analogy","type":"text"}],"id":"48ea3dff-062c-4ce7-b220-0d7d7a39b3d8","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Imagine you keep a physical address book for your contacts:","type":"text"}],"id":"90409936-f0f7-4c0a-9649-e26cea0016e5","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{"bold":true},"text":"SCD Type","type":"text"}],"props":{"backgroundColor":"rgba(214, 213, 212, 0.035)","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"What You Do","type":"text"}],"props":{"backgroundColor":"rgba(214, 213, 212, 0.035)","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Type 1","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Erase the old address and write the new one — no trace of the old address remains","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Type 2","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Add a new page for the contact with today''s date — the old page is kept with its own date range","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Type 3","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Write the new address in a \"Current\" field and move the old one into a \"Previous\" field on the same page","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Type 6","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"The super page — has a \"Previous\" field, full dated history entries, ","type":"text"},{"styles":{"italic":true},"text":"and","type":"text"},{"styles":{},"text":" always shows the latest address on every page","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"1735ef09-6dca-4923-ab42-27082c2cab42","props":{"textColor":"default"},"type":"table"},{"children":[],"id":"ddeb0e6a-641e-4a6d-8160-82b855cf07e0","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"🔁 SCD Type 1 — Overwrite ","type":"text"},{"styles":{"bold":true,"italic":true},"text":"(Forget the Past)","type":"text"}],"id":"8d1bdedc-132b-4ac0-867b-33862e24313f","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The simplest strategy. When a dimension value changes, the ","type":"text"},{"styles":{"bold":true},"text":"old value is overwritten","type":"text"},{"styles":{},"text":" with the new one. No history is kept whatsoever.","type":"text"}],"id":"79dc8876-fcba-4308-aa82-3155f010d680","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"When to Use","type":"text"}],"id":"9528ad4b-dfbf-4d25-ba70-5e5cebd65ba0","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"When ","type":"text"},{"styles":{"bold":true},"text":"historical accuracy doesn''t matter","type":"text"},{"styles":{},"text":" for this attribute","type":"text"}],"id":"504d3a2d-345f-466f-b4c1-f7ec97cf62d4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Fixing data entry errors (e.g., a misspelled name)","type":"text"}],"id":"c29d0d4c-6125-4773-be67-290f17b8a585","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"When only the ","type":"text"},{"styles":{"bold":true},"text":"current state","type":"text"},{"styles":{},"text":" is relevant to the business","type":"text"}],"id":"6105fa2e-1193-4b61-9534-d3809116fee2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Example — Customer changes city from Mawanella to Colombo:","type":"text"}],"id":"47cbc6d5-9497-4c2b-9b65-125272bdb5ae","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Before change:","type":"text"}],"id":"346da9d3-f913-4ba4-8c79-b7a9d7fcfb68","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":{"columnWidths":[null,null,null],"headerRows":1,"rows":[{"cells":