t":[{"styles":{},"text":"Advanced DW designs","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"31939346-164f-4792-9dc2-8c49112817e8","props":{"textColor":"default"},"type":"table"},{"children":[],"id":"8c81274e-b6d0-4ac9-9a5e-1ed172b4aeb3","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"🗝️ Key Takeaway","type":"text"}],"id":"c55b4b35-1ccd-4de8-a7ff-21159f085931","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"SCD Type 2 is the industry standard — always start here for any dimension that changes over time. Use Type 1 only for corrections where history is irrelevant. Use Type 3 sparingly when only one prior state matters. Use Type 6 when your BI team needs to simultaneously analyze ","type":"text"},{"styles":{"bold":true,"italic":true},"text":"historical point-in-time values","type":"text"},{"styles":{"bold":true},"text":" and ","type":"text"},{"styles":{"bold":true,"italic":true},"text":"current state","type":"text"},{"styles":{"bold":true},"text":" without writing complex SQL every time.","type":"text"}],"id":"fe3b34e6-51bf-4e48-bc6d-b6c9bb23be28","props":{"backgroundColor":"default","textColor":"rgb(214, 213, 212)"},"type":"quote"},{"children":[],"content":[],"id":"2535fe1f-bf1c-486d-b820-044cdf689f53","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"}]'::jsonb, '3e9e3dd3-a59b-4b02-968a-ee95e7317583') ON CONFLICT ("node_id") DO UPDATE SET "bad_example" = EXCLUDED."bad_example", "completed_at" = EXCLUDED."completed_at", "created_at" = EXCLUDED."created_at", "definition" = EXCLUDED."definition", "good_example" = EXCLUDED."good_example", "is_completed" = EXCLUDED."is_completed", "key_points" = EXCLUDED."k