INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-05-26T08:12:08.034391+00:00', '', '', '43931fa0-563b-424d-9825-7fba88d35b7a', false, '[]'::jsonb, '2026-05-26T08:13:33.793+00:00', 'f22b10db-248b-447f-80b6-4a27bd9171ed', '', 'e2db3f45-581d-4824-b49a-f58e55c77a10', '', '[]'::jsonb, '[{"children":[],"content":[{"styles":{"bold":true},"text":"Processing Paradigms — OLTP vs. OLAP","type":"text"}],"id":"270676f1-472c-40fc-a872-d0cc169d168a","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"There are two fundamentally different ways databases are designed to process data — ","type":"text"},{"styles":{"bold":true},"text":"OLTP","type":"text"},{"styles":{},"text":" for fast daily transactions and ","type":"text"},{"styles":{"bold":true},"text":"OLAP","type":"text"},{"styles":{},"text":" for deep analytical queries. Understanding both is critical because a data engineer''s core job is to ","type":"text"},{"styles":{"bold":true},"text":"bridge exactly these two systems","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"695d8948-ec7b-4b47-a535-49725ceccfb1","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"id":"989573cc-1137-4272-8ebd-ed9b9560b826","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"🧾 Mental Model — Receipt Printer vs. Master Ledger","type":"text"}],"id":"a001166b-a34d-49bc-81d7-aab99fccae80","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{"bold":true},"text":"Concept","type":"text"}],"props":{"backgroundColor":"rgba(214, 213, 212, 0.035)","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"Analogy","type":"text"}],"props":{"backgroundColor":"rgba(214, 213, 212, 0.035)","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"OLTP","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Individual receipt printer at a grocery checkout — extremely fast, processes one customer at a time, row-by-row","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"OLAP","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Corporate accounting department''s master ledger — groups everything by category (columns) so the CEO can instantly get total annual revenue","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"86b9a184-ec15-4e24-91db-15ed5786dbc3","props":{"textColor":"default"},"type":"table"},{"children":[],"content":[{"styles":{"bold":true},"text":"The receipt printer is useless for year-end analysis. The master ledger is too slow for printing individual receipts. Both are necessary — just for different jobs.","type":"text"}],"id":"f1d5b068-95b0-4a4b-bc97-5f311930a45f","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textColor":"rgb(214, 213, 212)"},"type":"quote"},{"children":[],"id":"71d35b85-7a90-41fc-9c26-1c76c89807dc","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"📖 OLTP — Online Transactional Processing","type":"text"}],"id":"de49b031-bfd1-4058-8af0-3f0ae848a349","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Relational databases built to handle ","type":"text"},{"styles":{"bold":true},"text":"daily, operational transactions","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"698a0cff-89f0-48f3-b407-57d25760ef1b","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"How it Works — Row-Based Storage","type":"text"}],"id":"336ce55e-4fe9-4233-a7d9-50f68e194d49","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Every piece of information tied to a single event is ","type":"text"},{"styles":{"bold":true},"text":"packaged together in one row","type":"text"},{"styles":{},"text":":","type":"text"}],"id":"fd869d76-0fde-4aca-8c91-41e6381ddc78","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"| Order_ID | User_ID | Product    | Price | Date       |\n|----------|---------|------------|-------|------------|\n| 1001     | 42      | Headphones | 4500  | 2026-05-26 |\n| 1002     | 87      | Keyboard   | 2200  | 2026-05-26 |","type":"text"}],"id":"62bca889-b312-4c25-a3e6-94984a1db4b0","props":{"language":"text"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"All data for one event lives together → ","type":"text"},{"styles":{"bold":true},"text":"perfect for CRUD operations","type":"text"}],"id":"94fb10b6-8919-4054-920c-7c7937179144","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"✅ OLTP Strengths","type":"text"}],"id":"eca6b6d1-3d45-4f74-9c84-e68054981674","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Lightning-fast ","type":"text"},{"styles":{"bold":true},"text":"inserts, updates, and deletes","type":"text"},{"styles":{},"text":" on specific rows","type":"text"}],"id":"75d86ebb-ee72-435c-888f-05ee0a504aa0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Optimized for ","type":"text"},{"styles":{"bold":true},"text":"high-frequency, low-latency","type":"text"},{"styles":{},"text":" individual transactions","type":"text"}],"id":"86793686-bf44-4159-916f-b8dde9a2c52f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Powers ","type":"text"},{"styles":{"bold":true},"text":"live production applications","type":"text"}],"id":"781e76e4-53c7-4e5b-bdcb-37952d30aecb","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"❌ OLTP Weakness","type":"text"}],"id":"1f407a7e-3924-47f5-a478-b92a63a2960d","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"To sum payments across millions of rows, the system must ","type":"text"},{"styles":{"bold":true},"text":"scan every single row from start to finish","type":"text"},{"styles":{},"text":" — just to extract one value per row. Massively wasteful for analytics.","type":"text"}],"id":"0222b6eb-9e58-4654-b016-3ed0ea430f0b","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[],"id":"0362a0f0-399e-4cb3-9d88-7e0c29a45550","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"📊 OLAP — Online Analytical Processing","type":"text"}],"id":"62705430-359e-4594-a6ef-ba27f744f3bb","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Systems explicitly built for ","type":"text"},{"styles":{"bold":true},"text":"complex analytical queries over massive historical datasets","type":"text"},{"styles":{},"text":" — most commonly implemented as ","type":"text"},{"styles":{"bold":true},"text":"Data Warehouses","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"5f4a0267-f756-407c-8234-2c4eb988e884","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"How it Works — Column-Based Storage","type":"text"}],"id":"aeb2c104-03fd-4dd3-91ae-a79e8830be41","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"All identical data types are stored together:","type":"text"}],"id":"86a48ffc-09bd-48ce-ae6b-6377e4194d74","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Payment Column:   [4500, 2200, 8700, 1100, 3300, ...]\nUser_ID Column:   [42, 87, 15, 203, 67, ...]\nProduct Column:   [Headphones, Keyboard, Phone, ...]","type":"text"}],"id":"f47e2355-bdf2-465e-92ce-5a07b4a6aae5","props":{"language":"text"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"When an analytical query runs, the system ","type":"text"},{"styles":{"bold":true},"text":"goes directly to the required column","type":"text"},{"styles":{},"text":" and completely ignores everything else.","type":"text"}],"id":"65587290-cfa2-4f11-a02a-6d8c148ea09c","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"✅ OLAP Strengths","type":"text"}],"id":"e39fcbec-7453-48e6-9f33-377e50388e21","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Lightning-fast ","type":"text"},{"styles":{"bold":true},"text":"aggregations","type":"text"},{"styles":{},"text":" (SUM, AVG, COUNT) over millions of records","type":"text"}],"id":"2a42d356-7a6e-4507-a5c5-2be8db14b20f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Skips irrelevant columns","type":"text"},{"styles":{},"text":" entirely — massive performance gain","type":"text"}],"id":"74