INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-05-27T04:46:41.366303+00:00', '', '', 'feb6f441-5b1c-4775-927c-ae517b70fb3b', false, '[]'::jsonb, '2026-05-27T04:47:03.101+00:00', '21b23730-1e24-468d-a7ac-836d2cdf3ffe', '', '04d0c2d7-39bd-4204-9c14-2695c9e7db58', '', '[]'::jsonb, '[{"children":[],"content":[{"styles":{"bold":true},"text":"1. Mental Model","type":"text"}],"id":"cd98949e-6be8-47b1-a79d-91031ad5e4c2","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Think of this block as the ","type":"text"},{"styles":{"bold":true},"text":"engineering vocabulary for the city","type":"text"},{"styles":{},"text":". Before you can design neighborhoods, roads, and utilities, you need to know the difference between districts, connections, traffic patterns, and building styles.","type":"text"}],"id":"5281b3d1-616b-4f1e-9b7d-5a62a2c6c0c9","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"City planning terms  →  Data architecture concepts\nDistrict             →  Domain\nBuilding purpose     →  Service\nTraffic network      →  Distributed system\nStreet connectivity  →  Coupling\nApartment complex    →  Multitenancy\nPublic event         →  Event-driven architecture\nOld neighborhood     →  Brownfield\nVacant land          →  Greenfield","type":"text"}],"id":"279504a7-43f9-4d9f-a8a3-ffd9dc024309","props":{"language":"text"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"This block gives you the language to reason about the structure of a data architecture, not just its tools.","type":"text"}],"id":"8e983bc1-d12b-4ec1-ac50-27d0f495891e","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"id":"9d750587-9536-471a-bf85-bd2c5d0220da","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"2. Explanation","type":"text"}],"id":"cd5a21e7-5b79-4d59-af4a-b0065bc660a1","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Domains and services","type":"text"}],"id":"b13a5fdf-d086-430b-a78d-23483a41f108","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"A ","type":"text"},{"styles":{"bold":true},"text":"domain","type":"text"},{"styles":{},"text":" is a real-world area of business knowledge, such as sales, inventory, or accounting.","type":"text"}],"id":"d2efa783-8a3c-4f6e-a6fb-3de96ee3d6f1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"A ","type":"text"},{"styles":{"bold":true},"text":"service","type":"text"},{"styles":{},"text":" is a unit of functionality that performs a task within a domain.","type":"text"}],"id":"0e0beae2-3ab1-4957-bc88-95bab4d73dd6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"A domain can contain multiple services, and services may be shared across domains when business logic overlaps.","type":"text"}],"id":"0c29b7fe-e4ba-49b6-bcce-d324305f43ed","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Distributed systems, scalability, and failure","type":"text"}],"id":"239ae7fb-9e8d-40d2-8b93-724c5ee999fd","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Data systems often run as ","type":"text"},{"styles":{"bold":true},"text":"distributed systems","type":"text"},{"styles":{},"text":", where work is spread across multiple machines.","type":"text"}],"id":"2e0ea67a-da1f-4e33-905d-fcbc6707454f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Distributed systems help with scale and resilience.","type":"text"}],"id":"2e1e12e0-8492-477f-8f7e-c4faf4aea3fa","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"The architecture must account for availability, reliability, elasticity, and the reality that nodes fail.","type":"text"}],"id":"3db3fd15-8b06-41d0-a576-d81cfd991895","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Tight vs loose coupling","type":"text"}],"id":"293b218c-8036-443c-83ee-c5a146dc5726","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Tight coupling","type":"text"},{"styles":{},"text":" means systems depend heavily on one another.","type":"text"}],"id":"e0170b0f-11da-4244-bf4e-90f29ea89c83","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Loose coupling","type":"text"},{"styles":{},"text":" means components can change independently using stable interfaces like APIs or schemas.","type":"text"}],"id":"8ed4e960-923f-44dd-98b6-56785c2d7884","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"The chapter strongly favors loose coupling because it improves team independence, reuse, and maintainability.","type":"text"}],"id":"82007315-124c-4e85-b570-9b6d1c2c4b43","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Tiers, monoliths, and microservices","type":"text"}],"id":"92b90d81-52b6-4d57-80e1-b5ad6dee0ec8","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"A ","type":"text"},{"styles":{"bold":true},"text":"single-tier","type":"text"},{"styles":{},"text":" architecture puts too much in one place and is fragile in production.","type":"text"}],"id":"8aaf0d8b-5a1a-49a4-a3a9-f65885233322","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"A ","type":"text"},{"styles":{"bold":true},"text":"multi-tier","type":"text"},{"styles":{},"text":" architecture separates concerns like data, logic, and presentation.","type":"text"}],"id":"3f4288e6-187e-420d-96f6-088164e34feb","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"A ","type":"text"},{"styles":{"bold":true},"text":"monolith","type":"text"},{"styles":{},"text":" centralizes functionality in one tightly integrated system.","type":"text"}],"id":"7e728678-f13b-4179-9cfd-cdd69a0d7502","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Microservices","type":"text"},{"styles":{},"text":" break the system into independent services with clearer boundaries.","type":"text"}],"id":"7cdeefcf-4bd9-4652-8406-017f095d47ad","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Single-tenant vs multitenant user access","type":"text"}],"id":"8adf26f8-0d20-4d5a-89b9-d717f0fc778c","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Single-tenant","type":"text"},{"styles":{},"text":" setups isolate one customer or group.","type":"text"}],"id":"5067ed9a-5734-4e75-8e25-3836089349f6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Multitenant","type":"text"},{"styles":{},"text":" setups share infrastructure across customers or groups while enforcing isolation through permissions and design.","type":"text"}],"id":"25832f3f-3bb0-4146-afd5-bd2f86fd95d9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Multitenancy shows up in warehouses, object storage, cloud platforms, and customer-facing data products.","type":"text"}],"id":"9cfd31b2-79d3-4464-9e2b-48a77bc2b0d0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Event-driven architecture","type":"text"}],"id":"4a099e1e-ea32-4be8-bc27-f49a2049e52b","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"An ","type":"text"},{"styles":{"bold":true},"text":"event","type":"text"},{"styles":{},"text":" is something that happened, usually a change in state.","type":"text"}],"id":"163bf6eb-ee10-4abf-be73-a814259ec450","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"In event-driven systems, events are produced, routed, and consumed asynchronously.","type":"text"}],"id":"2f50f304-b5a4-49f6-8879-0833f1137983","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"This works well when systems need to respond to business changes without tight dependencies.","type":"text"}],"id":"60893f02-eee6-425b-aa13-d7b9e1c70a63","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Brownfield vs greenfield","type":"text"}],"id":"557ef1b7-1d04-4ac2-bf44-646370f417e1","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Brownfield","type":"text"},{"styles":{},"text":" projects work within existing systems and constraints.","type":"text"}],"id":"6b1ae0cd-842e-4baa-b20b-84b9643aa703","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Greenfield","type":"text"},{"styles":{},"text":" projects start fresh with no legacy baggage.","type":"text"}],"id":"b8714d9a-83bc-46ad-9070-b7140f70603b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Brownfield work requires patience and reversibility; greenfield work requires discipline to avoid shiny-object syndrome.","type":"text"}],"id":"59bb338e-cd34-41d0-93d4-3bb99e725785","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"id":"0214c0fa-d193-47ad-b599-fbf5f892f4ce","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"3. Application","type":"text"}],"id":"40f0e648-8a79-4528-ac46-519597e0743c","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why these concepts matter","type":"text"}],"id":"63153e90-54fa-4551-bcb4-e8e2b0a5f922","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"These concepts let you describe an architecture precisely instead of speaking vaguely about “the stack.”","type":"text"}],"id":"67b212ff-d519-4bc2-a137-376df229ae2f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"They help you choose boundaries, interfaces, scaling patterns, and team responsibilities.","type":"text"}],"id":"8cc15433-1f54-426a-886a-0bed98434565","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"They also help you avoid accidentally building a system that is centralized, brittle, or impossible to change.","type":"text"}],"id":"dd5f9140-8ea1-4d54-b1df-b7c8bf70e4c8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"How to use them","type":"text"}],"id":"cc2bef2b-083a-4a07-a0ea-71eaad16f70e","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Use ","type":"text"},{"styles":{"bold":true},"text":"domains","type":"text"},{"styles":{},"text":" to organize business ownership.","type":"text"}],"id":"176996f2-710f-4fd8-b75d-651355414804","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Use ","type":"text"},{"styles":{"bold":true},"text":"services","type":"text"},{"styles":{},"text":" to separate responsibilities.","type":"text"}],"id":"95271aec-93bd-4524-9b17-53e256d6490e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Use ","type":"text"},{"styles":{"bold":true},"text":"coupling","type":"text"},{"styles":{},"text":" to evaluate how independently parts of the system can evolve.","type":"text"}],"id":"1c65cc09-0312-4e94-b9fd-a90f631c9bcf","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Use ","type":"text"},{"styles":{"bold":true},"text":"event-driven thinking","type":"text"},{"styles":{},"text":" when business activity naturally happens as changes over time.","type":"text"}],"id":"a8fce844-ebd9-4d38-b74f-fbcfe148aa5d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Use ","type":"text"},{"styles":{"bold":true},"text":"brownfield/greenfield","type":"text"},{"styles":{},"text":" thinking to set realistic expectations for architecture change.","type":"text"}],"id":"1f4e9a21-440e-452a-a067-7d52b36ad2c8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Strategic takeaway","type":"text"}],"id":"4eef3a4c-fbb3-48c1-83b6-6355c31fc589","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The best architecture is not just technically correct.","type":"text"}],"id":"7c80ba54-33ca-4e16-b43a-152f89c8b016","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"It also matches how the business works and how teams can realistically operate.","type":"text"}],"id":"b0ca409c-38aa-41e3-a609-b34320f546fb","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"That is why this block is foundational: it gives you the design language for the rest of Chapter 3.","type":"text"}],"id":"39f07ddc-62c7-4a23-81e4-ffa138e4dccc","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"id":"66fb8daa-40f2-4e03-b6e9-ae1b389fa219","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"4. Examples","type":"text"}],"id":"4df62afa-6c1e-4b8d-aaf2-7cad190fea9c","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Example 1 — Domain and service\n","type":"text"},{"styles":{},"text":"A retail company has a sales domain with services for orders, invoices, and products. Accounting shares the invoice service because invoices matter to both domains. This keeps business logic clear without duplicating everything.","type":"text"}],"id":"aeb21b17-aca2-4c78-8c55-1ba2304c4f7c","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Example 2 — Loose coupling\n","type":"text"},{"styles":{},"text":"A team exposes customer data through an API instead of letting other teams query its internal tables directly. That lets the customer team change its backend without breaking downstream consumers.","type":"text"}],"id":"e500d862-fe07-41a7-9d2a-a043994b5108","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Example 3 — Event-driven architecture\n","type":"text"},{"styles":{},"text":"When an order is created, an event is emitted. Billing, inventory, and shipping all consume that event independently. Each service reacts to the same business moment without needing synchronous calls to every other service.","type":"text"}],"id":"2de5cc44-369f-408c-b588-3dadfef7935d","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Example 4 — Brownfield vs greenfield\n","type":"text"},{"styles":{},"text":"A company modernizing a legacy warehouse must preserve current reporting while gradually introducing new domain pipelines. That is brownfield architecture. A startup starting from scratch can choose a clean, greenfield design, but it still needs to avoid overbuilding too early.","type":"text"}],"id":"199223ec-2f7a-4f1b-9e37-73d90193dc5a","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"id":"70896e3e-2944-47d7-9141-f44c1f9188a4","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"5. What to remember","type":"text"}],"id":"ed5cd10f-3bfb-4b1c-88d6-7d2c9638dd6c","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Domains are about ","type":"text"},{"styles":{"bold":true},"text":"business meaning","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"6986f538-31ae-4706-b605-de16aa2f4fd8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Services are about ","type":"text"},{"styles":{"bold":true},"text":"functionality","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"b6a7c896-1dc9-48db-9002-b8060df86e13","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Distributed systems are about ","type":"text"},{"styles":{"bold":true},"text":"scale and resilience","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"29f1e933-7297-45d1-8f73-79a2ad82cc24","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Coupling is about ","type":"text"},{"styles":{"bold":true},"text":"independence vs dependency","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"8f347a53-7f42-464a-9079-9d038287a997","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Event-driven design is about ","type":"text"},{"styles":{"bold":true},"text":"reacting to change","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"9929cd16-451f-4a51-a07b-a61f5a2c371b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Brownfield and greenfield describe ","type":"text"},{"styles":{"bold":true},"text":"how much legacy you inherit","type":"text"}],"id":"b4292207-d6bd-42b6-9c46-43dc245861c2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[],"id":"0b994877-f5f0-40ca-aa7b-749212237dff","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"}]'::jsonb, '3e9e3dd3-a59b-4b02-968a-ee95e7317583') ON CONFLICT ("node_id") DO UPDATE SET "bad_example" = EXCLUDED."bad_example", "completed_at" = EXCLUDED."completed_at", "created_at" = EXCLUDED."created_at", "definition" = EXCLUDED."definition", "good_example" = EXCLUDED."good_example", "is_completed" = EXCLUDED."is_completed", "key_points" = EXCLUDED."key_points", "last_edited" = EXCLUDED."last_edited", "map_id" = EXCLUDED."map_id", "mental_model" = EXCLUDED."mental_model", "notes" = EXCLUDED."notes", "resources" = EXCLUDED."resources", "rich_content" = EXCLUDED."rich_content", "user_id" = EXCLUDED."user_id";
INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-05-27T06:19:46.842857+00:00', '', '', '70e520b7-c79a-48c6-bc55-b468a47bd7c7', false, '[]'::jsonb, '2026-05-27T06:27:42.831+00:00', 'f22b10db-248b-447f-80b6-4a27bd9171ed', '', 'f6f3c612-1141-49f4-849c-4d58fc77cf4f', '', '[]'::jsonb, '[{"children":[],"content":[{"styles":{"bold":true},"text":"Cloud Computing Platforms","type":"text"}],"id":"725be73f-4dab-4830-b4ff-991abf95d450","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Cloud computing ","type":"text"},{"styles":{"bold":true},"text":"eliminates the burden of building and maintaining physical servers","type":"text"},{"styles":{},"text":" by letting companies rent world-class infrastructure from giant tech providers — paying only for exactly what they use.","type":"text"}],"id":"0eb23aef-8ced-4dc9-bd92-2ae46a45c4fc","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"id":"8526ec4f-ab26-455e-bdac-890da6558fd6","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"⚡ Mental Model — Power Plant vs. Wall Socket","type":"text"}],"id":"1859e320-b951-4e1d-879a-b2f276082aec","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{"bold":true},"text":"Concept","type":"text"}],"props":{"backgroundColor":"rgba(214, 213, 212, 0.035)","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"Analogy","type":"text"}],"props":{"backgroundColor":"rgba(214, 213, 212, 0.035)","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"On-premise servers","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Building your own power plant — buy fuel, hire mechanics, manage all risk","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Cloud computing","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Plugging into the wall socket — tap into a massive grid built by someone else","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Server failure","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Your generator catches fire — you''re entirely in the dark","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Cloud outage","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"The power company handles it — not your problem","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Pay-per-use","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"You pay only for the exact electricity you consumed this month","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"da6de10c-f4ce-4959-bfb0-89cf22b08fe1","props":{"textColor":"default"},"type":"table"},{"children":[],"content":[{"styles":{"bold":true},"text":"You don''t need to own the power plant to keep your lights on. You don''t need to own the servers to run your data platform.","type":"text"}],"id":"2a036c68-24e7-45b9-9bc8-2f2dfa9b4f4f","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textColor":"rgb(214, 213, 212)"},"type":"quote"},{"children":[],"id":"adf63aba-ae9c-4307-bb03-abc5e1a716b8","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"📖 Why Cloud Computing Exists","type":"text"}],"id":"b0152620-d2f8-4992-a2d6-d613759cc5c6","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Historically, building a data system meant building ","type":"text"},{"styles":{"bold":true},"text":"physical servers from scratch","type":"text"},{"styles":{},"text":":","type":"text"}],"id":"5c6cdd99-56a8-4b80-997a-aae6498376cd","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"What companies had to buy and manage on-premise:","type":"text"}],"id":"7637ca34-847b-4e47-b583-8dab987772ff","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"💽 Physical hard disks and RAM","type":"text"}],"id":"398cdf9a-2b16-4258-b16c-401770e10ee2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"⚙️ Processors and networking routers","type":"text"}],"id":"1e63529d-0dcd-40d4-b3f4-975fd4a6b2f6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"❄️ Massive air conditioning units to prevent overheating","type":"text"}],"id":"380b6979-4e24-49bf-857c-8e158c636101","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"🔧 Full-time maintenance engineers","type":"text"}],"id":"2f80d48d-c872-496b-b7b8-fe38fc175a91","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"🔒 Physical security for the building","type":"text"}],"id":"3d8bae47-b036-4ac1-ae08-8872bb1f1919","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"The risks:","type":"text"}],"id":"6240f55f-790a-4a49-96e5-8ffc37a7c107","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Hard drive failure → data permanently lost","type":"text"}],"id":"79a5063d-61b3-488d-aecf-97cd027372ff","props":{"backgroundColor":"default","textA