pe":"text"},{"styles":{},"text":" is an attribute (or combination of attributes) that ","type":"text"},{"styles":{"bold":true},"text":"uniquely identifies each instance","type":"text"},{"styles":{},"text":" of an entity.","type":"text"}],"id":"da8ebf0c-2509-42b4-957e-bd1a7f0086a1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Must be unique for every row","type":"text"}],"id":"e1c7b547-5b9b-46d9-a859-b99430496af7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Cannot be null","type":"text"}],"id":"016fa2a9-d7a2-49fc-864f-6e1e82915302","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Should never change","type":"text"}],"id":"47d051cc-bbc5-49f7-9224-42a1b9532122","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Examples:","type":"text"}],"id":"6879f3bb-5cf2-4889-8228-6a0f54589442","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"code":true},"text":"customer_id","type":"text"},{"styles":{},"text":" in the ","type":"text"},{"styles":{"code":true},"text":"Customer","type":"text"},{"styles":{},"text":" entity","type":"text"}],"id":"d1778a7d-09c1-4477-891a-6089ab4807d6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"code":true},"text":"order_id","type":"text"},{"styles":{},"text":" in the ","type":"text"},{"styles":{"code":true},"text":"Order","type":"text"},{"styles":{},"text":" entity","type":"text"}],"id":"82303169-ec93-429b-ad19-0da2991e76b4","props":{"b