ding"},{"children":[],"content":[{"styles":{},"text":"Attributes can be:","type":"text"}],"id":"5dda7a61-ff03-4b11-8deb-00542a6d23d0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Simple:","type":"text"},{"styles":{},"text":" Cannot be divided further (","type":"text"},{"styles":{"code":true},"text":"customer_name","type":"text"},{"styles":{},"text":")","type":"text"}],"id":"fac01ad1-c6fa-42dd-9a94-57e0ea1f6860","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Composite:","type":"text"},{"styles":{},"text":" Can be broken down (","type":"text"},{"styles":{"code":true},"text":"address","type":"text"},{"styles":{},"text":" → ","type":"text"},{"styles":{"code":true},"text":"street","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"city","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"postal_code","type":"text"},{"styles":{},"text":")","type":"text"}],"id":"b88fa8b5-8c7c-482f-b8a2-6eb7ec484e8c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Single-valued:","type":"text"},{"styles":{},"text":" One value per entity instance (","type":"text"},{"styles":{"code":true},"text":"customer_id","type":"text"},{"styles":{},"text":")","type":"text"}],"id":"312a0685-8e65-45d8-8fc8-d32ffdd1500c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Multi-valued:","type":"text"},{"styles":{},"text":" Can have multiple values (e.g., ","type":"text"},{"styles":{"code":true},"text":"phone_numbers","type":"text"},{"styles":{},"text":" — though this usually violates 1NF and should be normalized)","type":"text"}],"id":"b3535fea-c45c-4d92-ba71-667235937e53","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Primary Key","type":"text"}],"id":"0bb8f63f-fa38-4122-b3bb-68f43415f6e3","props":{"backgroundColor":"default","isToggleable":false,"level":4,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The unique identifier. Best practices:","type":"text"}],"id":"249bef2c-cbfb-485e-8ace-e266f95991ed","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Use a ","type":"text"},{"styles":{"bold":true},"text":"surrogate key","type":"text"},{"styles":{},"text":" (auto-incremented integer) rather than natural keys (like email) for stability","type":"text"}],"id":"c987732b-5a12-4e96-878a-323142e9237b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Keep it simple — single-column keys are easier to manage than composite keys","type":"text"}],"id":"509780ab-79cd-4090-9ff0-78a383c026ea","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Never allow nulls","type":"text"}],"id":"b229e384-a045-450c-aa4f-1698aae53ea9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Never reuse primary key values","type":"text"}],"id":"b6205102-c1ea-4991-8e71-f350593c8ee5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Foreign Key","type":"text"}],"id":"3b6dcd52-d778-4e4f-bd80-086ec271d599","props":{"backgroundColor":"default","isToggleable":false,"level":4,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The \"glue\" that connects entities. Foreign keys enforce ","type":"text"},{"styles":{"bold":true},"text":"referential integrity","type":"text"},{"styles":{},"text":" — you cannot insert an order with a ","type":"text"},{"styles":{"code":true},"text":"customer_id","type":"text"},{"styles":{},"text":" that doesn''t exist in the ","type":"text"},{"styles":{"code":true},"text":"customers","type":"text"},{"styles":{},"text":" table.","type":"text"}],"id":"a71db3c8-7b7d-4bf0-9cfd-347604fdfbf4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Junction Table","type":"text"}],"id":"9f0933c8-714a-4070-8eae-e0bb44aa607c","props":{"backgroundColor":"default","isToggleable":false,"level":4,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"When two entities have a ","type":"text"},{"styles":{"bold":true},"text":"many-to-many","type":"text"},{"styles":{},"text":" relationship, you cannot model it directly in a relational database. Instead, you create a ","type":"text"},{"styles":{"bold":true},"text":"junction table","type":"text"},{"styles":{},"text":" (also called a bridge table or associative entity) that sits between them and breaks the M:N into two 1:N relationships.","type":"text"}],"id":"a28a9c8e-1faa-4f78-b432-903c513b4dc4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"a08286f0-cf79-45cb-ba0c-2e6aede12988","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"4. Relationship Types","type":"text"}],"id":"130775cc-7d97-425d-b892-23ab4e1a12da","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"One-to-One (1:1)","type":"text"}],"id":"95168dab-e58d-4ce0-9a8c-0e263866b01c","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Definition:","type":"text"},{"styles":{},"text":" Each instance of Entity A is associated with exactly one instance of Entity B, and vice versa.","type":"text"}],"id":"ba90494d-23ec-4cb7-8243-11416f493fd0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Visual Representation:","type":"text"}],"id":"81a0de53-e759-4ce0-9993-257f8acdc6c1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Person ─── Passport","type":"text"}],"id":"e5aa5748-6092-4611-aa6e-709ec02a6446","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Example Scenario:","type":"text"}],"id":"ce81044a-eeca-4b24-bd97-fc0c9ccc0b76","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Each person has exactly one passport","type":"text"}],"id":"892d5f10-c613-46ab-a8f9-b2d7b0756e65","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Each passport belongs to exactly one person","type":"text"}],"id":"6b0cb862-bc49-4bec-ad14-e77137c77cfc","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Implementation:","type":"text"},{"styles":{},"text":" The foreign key can go in either table. Typically, the more frequently accessed table holds the FK.","type":"text"}],"id":"41982202-8c61-4142-b64a-14254672c5ed","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"CREATE TABLE persons (\n    person_id SERIAL PRIMARY KEY,\n    name      VARCHAR(200)\n);\n\nCREATE TABLE passports (\n    passport_id     SERIAL PRIMARY KEY,\n    passport_number VARCHAR(50) UNIQUE,\n    person_id       INT UNIQUE REFERENCES persons(person_id)\n);","type":"text"}],"id":"e2867d99-a3e6-41e5-9b2d-fdea6ee4b244","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Note:","type":"text"},{"styles":{},"text":" One-to-one relationships are relatively rare. Often, both entities could be combined into a single table.","type":"text"}],"id":"ddcc0ec4-14fc-43c1-be2c-a42b9425962a","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"90ca84cc-4b28-42eb-a92c-6dee9716fd6d","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"One-to-Many (1:N)","type":"text"}],"id":"ccdcc6f5-831e-41d6-ab44-e96026926412","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Definition:","type":"text"},{"styles":{},"text":" Each instance of Entity A can be associated with many instances of Entity B, but each instance of B is associated with only one instance of A.","type":"text"}],"id":"85916e05-98ef-4af7-9724-66f9fabc27a2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Visual Representation:","type":"text"}],"id":"fba4ee9b-5021-4c5e-b2f4-ceae697bb78c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Customer ───< Order\n\nOne customer can place many orders.\nEach order belongs to one customer.","type":"text"}],"id":"75c9ad34-5e84-458d-ac76-de30afffe206","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Symbols:","type":"text"}],"id":"b96066d9-2c95-47f0-8e16-35b7838657fb","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"code":true},"text":"───<","type":"text"},{"styles":{},"text":" or ","type":"text"},{"styles":{"code":true},"text":"1:N","type":"text"},{"styles":{},"text":" or ","type":"text"},{"styles":{"code":true},"text":"1..*","type":"text"},{"styles":{},"text":" indicate one-to-many","type":"text"}],"id":"92952cb1-5ffb-4a5f-b16d-0656b53d2570","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Example Scenario:","type":"text"}],"id":"f5d0ab5c-71da-4d7a-9b6b-39302b5b94bb","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"A customer places many orders","type":"text"}],"id":"4f4418d0-b15b-4460-a52e-15bf438a7422","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"An order is placed by one customer","type":"text"}],"id":"a99d5243-854e-4648-bb0e-48f789186d35","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Implementation:","type":"text"},{"styles":{},"text":" The ","type":"text"},{"styles":{"bold":true},"text":"foreign key goes in the \"many\" side","type":"text"},{"styles":{},"text":" (the ","type":"text"},{"styles":{"code":true},"text":"Order","type":"text"},{"styles":{},"text":" table).","type":"text"}],"id":"68302566-b2a5-4e68-929b-e895e80109bf","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"CREATE TABLE customers (\n    customer_id SERIAL PRIMARY KEY,\n    name        VARCHAR(200)\n);\n\nCREATE TABLE orders (\n    order_id     SERIAL PRIMARY KEY,\n    order_date   DATE,\n    customer_id  INT NOT NULL REFERENCES customers(customer_id)\n);","type":"text"}],"id":"30379c6e-edfb-4b2a-979b-fd514e59a2e5","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Rule:","type":"text"},{"styles":{},"text":" The foreign key always lives on the \"many\" side of a one-to-many relationship.","type":"text"}],"id":"257ccd85-6866-4146-a0a4-5400a1ef0b95","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"9dffb8e3-91a7-4966-b66f-324f4ff8d71f","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Many-to-Many (M:N)","type":"text"}],"id":"d08c3aa2-20c3-4e0e-8d57-f08c45e8f48e","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Definition:","type":"text"},{"styles":{},"text":" Each instance of Entity A can be associated with many instances of Entity B, and vice versa.","type":"text"}],"id":"35c1e880-614a-4954-a566-b7d03905f689","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Visual Representation (Initial — Incorrect):","type":"text"}],"id":"207f3466-633a-4ad8-988e-1d8bfcfa7efb","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Order >───< Product\n\nOne order can contain many products.\nOne product can appear in many orders.","type":"text"}],"id":"5a6c9a4a-7c8c-4fc0-bff6-56fa359e5388","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Problem:","type":"text"},{"styles":{},"text":" Relational databases ","type":"text"},{"styles":{"bold":true},"text":"cannot directly represent many-to-many relationships","type":"text"},{"styles":{},"text":". You cannot have a column in ","type":"text"},{"styles":{"code":true},"text":"orders","type":"text"},{"styles":{},"text":" that stores multiple ","type":"text"},{"styles":{"code":true},"text":"product_id","type":"text"},{"styles":{},"text":" values (violates 1NF).","type":"text"}],"id":"90e376b4-729e-49d3-9e27-69ccff294963","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Solution:","type":"text"},{"styles":{},"text":" Introduce a ","type":"text"},{"styles":{"bold":true},"text":"junction table","type":"text"},{"styles":{},"text":" (also called a bridge table or associative entity).","type":"text"}],"id":"1fc091c5-568c-40af-8640-5df71cd725c7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"ff050225-0eb9-4e7e-9905-4cfba2d42db6","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Resolving Many-to-Many with a Junction Table","type":"text"}],"id":"59f34da9-06e3-43b6-bda7-202e35e30e01","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Corrected Representation:","type":"text"}],"id":"f341d8d7-38c6-4995-9e60-d8589e26e35d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Order ───< OrderItem >─── Product\n\nOne order has many order items.\nOne product appears in many order items.","type":"text"}],"id":"610f1cbe-4f2e-4e92-90cc-270af5c9481d","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"What Happened:","type":"text"}],"id":"03ad96d6-6f7f-47a9-af7a-fe95a6af2ef6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"The direct M:N relationship between ","type":"text"},{"styles":{"code":true},"text":"Order","type":"text"},{"styles":{},"text":" and ","type":"text"},{"styles":{"code":true},"text":"Product","type":"text"},{"styles":{},"text":" was broken into two 1:N relationships","type":"text"}],"id":"94253d9a-5ec9-44ba-82b2-b0540677c5b1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"The ","type":"text"},{"styles":{"code":true},"text":"OrderItem","type":"text"},{"styles":{},"text":" junction table sits in the middle","type":"text"}],"id":"f0ab6ae3-96ff-4c4a-a067-d19a7902616a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"code":true},"text":"OrderItem","type":"text"},{"styles":{},"text":" contains foreign keys to both ","type":"text"},{"styles":{"code":true},"text":"Order","type":"text"},{"styles":{},"text":" and ","type":"text"},{"styles":{"code":true},"text":"Product","type":"text"}],"id":"34fc0717-a54e-468c-aeee-7c36b01d7600","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"code":true},"text":"OrderItem","type":"text"},{"styles":{},"text":" can also store relationship-specific attributes like ","type":"text"},{"styles":{"code":true},"text":"quantity","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"unit_price","type":"text"}],"id":"101f3ae8-6cb5-4fa0-8313-8ad4e96d0dc4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Implementation:","type":"text"}],"id":"e4a48143-c002-4b89-a7cf-be4521b39dca","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"CREATE TABLE orders (\n    order_id   SERIAL PRIMARY KEY,\n    order_date DATE\n);\n\nCREATE TABLE products (\n    product_id   SERIAL PRIMARY KEY,\n    product_name VARCHAR(200),\n    price        DECIMAL(10,2)\n);\n\nCREATE TABLE order_items (\n    order_item_id SERIAL PRIMARY KEY,         -- Surrogate key (optional)\n    order_id      INT NOT NULL REFERENCES orders(order_id),\n    product_id    INT NOT NULL REFERENCES products(product_id),\n    quantity      INT NOT NULL,\n    unit_price    DECIMAL(10,2) NOT NULL,\n    UNIQUE (order_id, product_id)            -- Composite unique constraint\n);","type":"text"}],"id":"b1654981-d660-4685-b0b6-431bd25e30da","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Key Insight:","type":"text"},{"styles":{},"text":" The junction table not only resolves the M:N relationship but also stores ","type":"text"},{"styles":{"bold":true},"text":"context-specific attributes","type":"text"},{"styles":{},"text":" — like ","type":"text"},{"styles":{"code":true},"text":"quantity","type":"text"},{"styles":{},"text":" and ","type":"text"},{"styles":{"code":true},"text":"unit_price","type":"text"},{"styles":{},"text":" — that belong to the relationship itself, not to either entity alone.","type":"text"}],"id":"e6069ff9-aba1-4b43-810e-4c2d4eb56a69","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"5db69f07-223b-4a6e-a42b-0439745a2335","props":{},"type":"divider"},{"children":