ships:","type":"text"}],"id":"d394c57e-eacc-40a3-aaaa-62bc6b40ade8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Customer ───< Order","type":"text"},{"styles":{},"text":" (1:N)","type":"text"}],"id":"d74b5783-01c3-4e8f-9f7a-20e68356f10a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Order ───< OrderItem","type":"text"},{"styles":{},"text":" (1:N)","type":"text"}],"id":"8d21c2a2-66f1-4a2c-8c76-fdacafe0e6b7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Product ───< OrderItem","type":"text"},{"styles":{},"text":" (1:N)","type":"text"}],"id":"c99e4d64-3e86-476e-b75d-a667cba68934","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"id":"9b22b08d-bc8a-45f1-b97b-e4bfc6018428","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"How the ERD Becomes SQL Tables","type":"text"}],"id":"2b6b23cf-0e0c-4239-a92e-89b92aaf84a1","props":{"backgroundColor":"default","isToggleable":false,"level":4,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"-- ─────────────────────────────────────────────────────\n-- Entity: Customer\n-- ─────────────────────────────────────────────────────\nCREATE TABLE customers (\n    customer_id SERIAL       PRIMARY KEY,\n    name        VARCHAR(200) NOT NULL,\n    email       VARCHAR(200) UNIQUE NOT NULL,\n    city        VARCHAR(100),\n    phone       VARCHAR(20)\n);\n\n-- ─────────────────────────────────────────────────────\n-- Entity: Product\n-- ─────────────────────────────────────────────────────\nCREATE TABLE products (\n    product_id     SERIAL        PRIMARY KEY,\n    product_name   VARCHAR(200)  NOT NULL,\n    category       VARCHAR(100),\n    price          DECIMAL(10,2) NOT NULL,\n    stock_quantity INT           DEFAULT 0\n);\n\n-- ─────────────────────────────────────────────────────\n-- Entity: Order (1:N with Customer)\n-- ─────────────────────────────────────────────────────\nCREATE TABLE orders (\n    order_id     SERIAL        PRIMARY KEY,\n    customer_id  INT           NOT NULL REFERENCES customers(customer_id),\n    order_date   DATE          DEFAULT CURRENT_DATE,\n    total_amount DECIMAL(12,2),\n    status       VARCHAR(50)   DEFAULT ''Pending''\n);\n\n-- ─────────────────────────────────────────────────────\n-- Junction Table: OrderItem (resolves M:N between Order and Product)\n-- ─────────────────────────────────────────────────────\nCREATE TABLE order_items (\n    order_item_id SERIAL        PRIMARY KEY,\n    order_id      INT           NOT NULL REFERENCES orders(order_id),\n    product_id    INT           NOT NULL REFERENCES products(product_id),\n    quantity      INT           NOT NULL CHECK (quantity > 0),\n    unit_price    DECIMAL(10,2) NOT NULL,\n    UNIQUE (order_id, product_id)  -- Prevent duplicate product in same order\n);","type":"text"}],"id":"44589757-c469-4307-9691-9094fb3984c8","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"id":"855ea2f0-7494-400e-a2ee-37b874dd1be0","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Example 2: Inventory Tracking System","type":"text"}],"id":"0db3df6d-eb47-4e2a-80c3-c76f59cedeb0","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Business Requirement","type":"text"}],"id":"f848c586-5b29-4e0c-86e1-ca39d4b74dc1","props":{"backgroundColor":"default","isToggleable":false,"level":4,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles