yles":{},"text":"Unlike ","type":"text"},{"styles":{"code":true},"text":"Customer","type":"text"},{"styles":{},"text":" or ","type":"text"},{"styles":{"code":true},"text":"Product","type":"text"},{"styles":{},"text":", which represent ","type":"text"},{"styles":{"bold":true},"text":"things","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"StockMovement","type":"text"},{"styles":{},"text":" represents ","type":"text"},{"styles":{"bold":true},"text":"events","type":"text"},{"styles":{},"text":" — actions that happened at a specific time.","type":"text"}],"id":"a91e9ac6-5a42-4b08-adde-edc33552b53f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Event tables:","type":"text"}],"id":"a39e5675-cb66-44b1-97b0-b4635cd56c03","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Typically have a timestamp","type":"text"}],"id":"2d5937c0-3987-4e23-aec5-b17ebbeff9cd","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Are append-only (you don''t update past events)","type":"text"}],"id":"39579f19-78bc-4355-9dca-249535b05a3a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Support audit trails and time-series analysis","type":"text"}],"id":"7b698972-7055-453f-947f-8eb07651fad7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Relationships:","type":"text"}],"id":"a9ebb7a0-e1fb-4f42-9850-715d46b9583b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Warehouse ───< StockMovement","type":"text"},{"styles":{},"text":" (1:N)","type":"text"}],"id":"5b2368fc-0257-41d9-ad71-cb8c591dc3ac","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Product ───< StockMovement","type":"text"},{"styles":{},"text":" (1:N)","type":"text"}],"id":"93a4ea36-6b42-433c-ba49-29c37346bcf0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"CREATE TABLE warehouses (\n    warehouse_id   SERIAL PRIMARY KEY,\n    warehouse_name VARCHAR(200),\n    city           VARCHAR(100)\n);\n\nCREATE TABLE products (\n    product_id   SERIAL PRIMARY KEY,\n    product_name VARCHAR(200),\n    category     VARCHAR(100)\n);\n\nCREATE TABLE stock_movements (\n    movement_id   SERIAL PRIMARY KEY,\n    product_id    INT  NOT NULL REFERENCES products(product_id),\n    warehouse_id  INT  NOT NULL REFERENCES warehouses(warehouse_id),\n    movement_type VARCHAR(10) CHECK (movement_type IN (''IN'', ''OUT'')),\n    quantity      INT  NOT NULL,\n    movement_date DATE DEFAULT CURRENT_DATE\n);","type":"text"}],"id":"bfd3858b-43aa-4f12-9f31-bd5c91b5cb94","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"id":"fe550771-363f-4d1d-877d-1b823a57aec7","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"7. Interview-Level Understanding","type":"text"}],"id":"43e941bb-aadc-4653-aaaf-56244b28dc98","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Key Interview Question:","type":"text"}],"id":"2bbec049-1eb9-4ebf-880c-a07d33a467b4","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"\"Why did you create ","type":"text"},{"styles":{"code":true},"text":"OrderItem","type":"text"},{"styles":{"bold":true},"text":" as a separate table?\"","type":"text"}],"id":"bd2f532d-9730-4002-ab71-2fae4148b11b","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{},"text":"Strong Answer:","type":"text"}],"id":"60c75792-fafb-4b1f-a950-441f2bb2d5c7","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"I created ","type":"text"},{"styles":{"code":true},"text":"OrderItem","type":"text"},{"styles":{"italic":true},"text":" as a junction table to resolve the many-to-many relationship between ","type":"text"},{"styles":{"code":true},"text":"Order","type":"text"},{"styles":{"italic":true},"text":" and ","type":"text"},{"styles":{"code":true},"text":"Product","type":"text"},{"styles":{"italic":true},"text":".","type":"text"}],"id":"bd582c2e-e69c-4d8b-8b17-ade9b6469e95","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"The business reality is that one order can contain many products, and one product can appear in many different orders. Relational databases cannot directly model many-to-many relationships — you can''t store multiple ","type":"text"},{"styles":{"code":true},"text":"product_id","type":"text"},{"styles":{"italic":true},"text":" values in a single column without violating First Normal Form.","type":"text"}],"id":"1b6ee439-e379-47ff-8809-f9419b30ccdb","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"The junction table breaks the M:N relationship into two one-to-many relationships: one order has many order items, and one product appears in many order items. This is a standard normalization technique.","type":"text"}],"id":"663f93fe-c1d0-4960-9e54-fdc4be94f853","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"Additionally, ","type":"text"},{"styles":{"code":true},"text":"OrderItem","type":"text"},{"styles":{"italic":true},"text":" is not just a structural necessity — it also stores relationship-specific data that doesn''t belong to either ","type":"text"},{"styles":{"code":true},"text":"Order","type":"text"},{"styles":{"italic":true},"text":" or ","type":"text"},{"styles":{"code":true},"text":"Product","type":"text"},{"styles":{"italic":true},"text":" alone. For example, the ","type":"text"},{"styles":{"code":true},"text":"quantity","type":"text"},{"styles":{"italic":true},"text":" of a specific product in a specific order, and the ","type":"text"},{"styles":{"code":true},"text":"unit_price","type":"text"},{"styles":{"italic":true},"text":" at the time of purchase — which may differ from the product''s current price. Without ","type":"text"},{"styles":{"code":true},"text":"OrderItem","type":"text"},{"styles":{"italic":true},"text":", there would be no clean place to store this context.","type":"text"}],"id":"446f9d3f-cb4c-40c1-bf6e-2363bcd46316","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"So ","type":"text"},{"styles":{"code":true},"text":"OrderItem","type":"text"},{"styles":{"italic":true},"text":" serves both a structural purpose — resolving the many-to-many relationship — and a functional purpose — capturing the details of each product within each order.\"","type":"text"}],"id":"b1ecd999-8f14-4bf0-88a3-9549c85cc40d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"3344e3ed-1d92-4c2a-ab0d-0037778afc37","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"How to Approach a Whiteboard ERD Design Question","type":"text"}],"id":"64acb943-594f-4f88-a040-b401e0a02ad2","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"\"Design an ERD for an e-commerce system.\"","type":"text"}],"id":"4e11f2ec-88cf-451a-b2db-70bdad980d49","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"bold":true},"text":"Step-by-Step Approach:","type":"text"}],"id":"a65a3f03-14b3-42d6-bfb5-dd8fa98fbd91","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Step 1: Clarify Requirements (Ask Questions)","type":"text"}],"id":"8f35e2ad-9db3-4c4c-9749-992f4d755b95","props":{"backgroundColor":"default","isToggleable":false,"level":4,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"\"What are the main entities the system needs to track?\"","type":"text"}],"id":"0da0b4a4-2ef3-4c1f-8e67-6b263c6152aa","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"\"Does a customer have a single address or multiple addresses?\"","type":"text"}],"id":"69ff5ec8-8736-4b72-b727-8f83a541d371","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"\"Can an order contain multiple products?\"","type":"text"}],"id":"bd1e9dd0-4379-4654-805a-0869994b0a3b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"\"Do we track inventory? Payment methods? Shipping?\"","type":"text"}],"id":"ea381e1b-7ac0-4afa-85b8-7a568e1ca8c4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Interviewers appreciate candidates who clarify before diving in.","type":"text"}],"id":"a2bb8e11-6988-4bad-9a62-3e87547ca790","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{},"text":"Step 2: Identify Entities","type":"text"}],"id":"75106619-5c84-4cba-8586-551b9b57bad4","props":{"backgroundColor":"default","isToggleable":false,"level":4,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"List the ","type":"text"},{"styles":{"bold":true},"text":"nouns","type":"text"},{"styles":{},"text":" in the business domain:","type":"text"}],"id":"b3e76ba7-3f23-4721-8f3f-b2c16dc85872","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"code":true},"text":"Customer","type":"text"}],"id":"66734fe8-1a1d-4f70-91e3-d4bb0d227ec2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"code":true},"text":"Order","type":"text"}],"id":"c56f1f5f-bd0d-451d-a39f-96598d1a8fa7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"code":true},"text":"Product","type":"text"}],"id":"4c37c2ed-fcfe-4727-b542-8a194a50cc66","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"(Maybe: ","type":"text"},{"styles":{"code":true},"text":"Address","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"Payment","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"Warehouse","type":"text"},{"styles":{},"text":")","type":"text"}],"id":"0176f76a-452e-42cf-9219-568d055cc7b6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Start simple — 3-4 core entities. You can always add more.","type":"text"}],"id":"1b2f63dc-a6b9-47e5-a08b-63fab9eed0a2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Step 3: Add Attributes to Each Entity","type":"text"}],"id":"0c82f17e-425b-4dda-b76a-19a541d1c31e","props":{"backgroundColor":"default","isToggleable":false,"level":4,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"For each entity, list what you need to know:","type":"text"}],"id":"bacf7714-3318-4e7e-893e-cd54bb98cfc2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Customer: customer_id, name, email, city, phone\nOrder:    order_id, order_date, total_amount, status\nProduct:  product_id, name, price, category, stock","type":"text"}],"id":"90636b30-a90c-46de-a204-cde5306dde29","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Step 4: Choose Primary Keys","type":"text"}],"id":"676b3fe4-1beb-404f-b969-c2391f3f1539","props":{"backgroundColor":"default","isToggleable":false,"level":4,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Identify the unique identifier for each entity:","type":"text"}],"id":"adf3919c-bdc7-470a-bbf7-616003f85dac","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"code":true},"text":"customer_id","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"order_id","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"product_id","type":"text"}],"id":"536ca6ee-d3a5-40a0-9035-708a0eb665dd","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Best practice:","type":"text"},{"styles":{},"text":" Use surrogate keys (auto-incremented integers).","type":"text"}],"id":"d387862c-d5ed-4fa7-9d3c-c21964b63944","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{},"text":"Step 5: Add Foreign Keys to Establish Relationships","type":"text"}],"id":"fcd1082c-3c00-450c-9f7a-efec0e8b2686","props":{"backgroundColor":"default","isToggleable":false,"level":4,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Each order belongs to one customer → ","type":"text"},{"styles":{"code":true},"text":"Order.customer_id","type":"text"},{"styles":{},"text":" (FK → ","type":"text"},{"styles":{"code":true},"text":"Customer.customer_id","type":"text"},{"styles":{},"text":")","type":"text"}],"id":"6bebf850-4110-4f1a-b6b3-9086178d847d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Step 6: Define Relationships and Cardinality","type":"text"}],"id":"d98de2d4-2ac1-4edc-85f7-40d844a61e00","props":{"backgroundColor":"default","isToggleable":false,"level":4,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"code":true},"text":"Customer ───< Order","type":"text"},{"styles":{},"text":" (1:N)","type":"text"}],"id":"fadd8589-3442-4299-99c9-3bfa28befa21","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"code":true},"text":"Order >───< Product","type":"text"},{"styles":{},"text":" (M:N)","type":"text"}],"id":"6f1a9a83-55fb-487e-83e7-76bd5636fabb","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Draw the lines and mark cardinality.","type":"text"}],"id":"4fa92370-9797-410e-9849-5c992b7da251","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Step 7: Resolve Many-to-Many Relationships","type":"text"}],"id":"71f0fac9-b61b-476c-b294-66a9db3062a2","props":{"backgroundColor":"default","isToggleable":false,"level":4,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Introduce ","type":"text"},{"styles":{"code":true},"text":"OrderItem","type":"text"},{"styles":{},"text":" junction table:","type":"text"}],"id":"09b15759-bd82-492e-a9cc-8185bf9b1529","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"code":true},"text":"Order ───< OrderItem >─── Product","type":"text"}],"id":"d3db23bb-3df6-4919-ab91-9b9c90778cf5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Add attributes to the junction table:","type":"text"}],"id":"27262c6d-9078-4788-9ae1-bb1af0038aeb","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"code":true},"text":"order_item_id","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"order_id","type":"text"},{"styles":{},"text":" (FK), ","type":"text"},{"styles":{"code":true},"text":"product_id","type":"text"},{"styles":{},"text":" (FK), ","type":"text"},{"styles":{"code":true},"text":"quantity","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"unit_price","type":"text"}],"id":"8197045f-774d-4527-a597-b8235793a0e8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Step 8: Review and Validate","type":"text"}],"id":"f8a0a144-6390-4927-b934-b5423aef6d63","props":{"backgroundColor":"default","isToggleable":false,"level":4,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Does this model the business correctly?","type":"text"}],"id":"47141e0d-5e7f-4b68-a000-56621baed407","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Are all necessary attributes present?","type":"text"}],"id":"1982b5b4-cd22-4a32-8f13-4cee3b13913d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Are all relationships properly captured?","type":"text"}],"id":"1bc4c51c-10c4-4075-b4ba-6b60966f8aa0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Is the schema normalized (at least 3NF)?","type":"text"}],"id":"bd29f80b-c0b6-4641-a7d7-f4a3f76b2eec","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Walk the interviewer through your thought process out loud. They''re evaluating your reasoning, not just the final diagram.","type":"text"}],"id":"ab457851-9c52-43a3-829c-e72ef62e4079","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"df70f273-a71a-4a5c-a309-ac792727350b","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"8. C.A.C.O. Application","type":"text"}],"id":"853add98-4fd2-4967-9be8-4c69db9c01cd","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Concept","type":"text"}],"id":"be781fb7-a57b-4023-b797-e122f7433ac4","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"An ","type":"text"},{"styles":{"bold":true},"text":"ERD","type":"text"},{"styles":{},"text":" is a visual blueprint for a relational database. Entities become tables, attributes become columns, primary keys enforce uniqueness, foreign keys enforce relationships, and cardinality defines the numerical nature of those relationships. Many-to-many relationships require junction tables to be implemented correctly in a normalized relational schema.","type":"text"}],"id":"0f5e525e-fcca-4b20-b027-27dfb00ae72a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"c070f81d-66d8-4688-b88e-271c5f7380b8","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Architecture","type":"text"}],"id":"1a82ee65-90ff-4a31-bb8c-819e2cafee8b","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Business Requirements\n        ↓\nIdentify Entities (Customers, Orders, Products)\n        ↓\nDefine Attributes (name, price, order_date)\n        ↓\nChoose Primary Keys (customer_id, order_id, product_id)\n        ↓\nDefine Relationships (Customer places Order, Order contains Product)\n        ↓\nIdentify Cardinality (1:N, M:N)\n        ↓\nResolve M:N with Junction Tables (OrderItem)\n        ↓\nDraw ERD\n        ↓\nTranslate ERD into SQL DDL\n        ↓\nImplement Database Schema","type":"text"}],"id":"db1215f5-6702-4e39-b1e8-36ed6c750219","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"8ac9beb7-bbd0-4a5c-8cdc-1253cd76d0ab","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Code — SQL DDL from ERD","type":"text"}],"id":"61827873-2b6c-40ff-b9d8-78a878957dad","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Full advanced database modeling is not required at intern level. This shows how an ERD translates directly into SQL.","type":"text"}],"id":"3173f7c7-2a91-4193-a7b0-73be8e78a6aa","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{},"text":"-- ─────────────────────────────────────────────────────\n-- Customer Entity\n-- ─────────────────────────────────────────────────────\nCREATE TABLE customers (\n    customer_id SERIAL       PRIMARY KEY,\n    name        VARCHAR(200) NOT NULL,\n    email       VARCHAR(200) UNIQUE NOT NULL,\n    city        VARCHAR(100),\n    phone       VARCHAR(20)\n);\n\n-- ─────────────────────────────────────────────────────\n-- Product Entity\n-- ─────────────────────────────────────────────────────\nCREATE TABLE products (\n    product_id     SERIAL        PRIMARY KEY,\n    product_name   VARCHAR(200)  NOT NULL,\n    category       VARCHAR(100),\n    price          DECIMAL(10,2) NOT NULL,\n    stock_quantity INT           DEFAULT 0\n);\n\n-- ─────────────────────────────────────────────────────\n-- Order Entity (1:N relationship with Customer)\n-- ─────────────────────────────────────────────────────\nCREATE TABLE orders (\n    order_id     SERIAL        PRIMARY KEY,\n    customer_id  INT           NOT NULL REFERENCES customers(customer_id),\n    order_date   DATE          DEFAULT CURRENT_DATE,\n    total_amount DECIMAL(12,2),\n    status       VARCHAR(50)   DEFAULT ''Pending''\n);\n\n-- ─────────────────────────────────────────────────────\n-- Junction Table: OrderItem (resolves M:N between Order and Product)\n-- ─────────────────────────────────────────────────────\nCREATE TABLE order_items (\n    order_item_id SERIAL        PRIMARY KEY,\n    order_id      INT           NOT NULL REFERENCES orders(order_id),\n    product_id    INT           NOT NULL REFERENCES products(product_id),\n    quantity      INT           NOT NULL CHECK (quantity > 0),\n    unit_price    DECIMAL(10,2) NOT NULL,\n    UNIQUE (order_id, product_id)  -- Prevent duplicate product in same order\n);","type":"text"}],"id":"e03b0790-cc07-4d54-b447-13477523ddb8","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"id":"b4d8afa9-3257-4c31-a334-5bb8fb26ad6c","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Sample Queries Using This Schema","type":"text"}],"id":"b5797720-11aa-4d32-aa17-d3491faca97b","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"-- Find all orders placed by a specific customer\nSELECT o.order_id, o.order_date, o.total_amount, o.status\nFROM orders o\nWHERE o.customer_id = 5;\n\n-- Find all products in a specific order\nSELECT p.product_name, oi.quantity, oi.unit_price,\n       (oi.quantity * oi.unit_price) AS line_total\nFROM order_items oi\nJOIN products p ON oi.product_id = p.product_id\nWHERE oi.order_id = 1001;\n\n-- Total revenue by product category\nSELECT p.category, SUM(oi.quantity * oi.unit_price) AS total_revenue\nFROM order_items oi\nJOIN products p ON oi.product_id = p.product_id\nGROUP BY p.category\nORDER BY total_revenue DESC;","type":"text"}],"id":"5ad20c12-1680-44ee-9550-eda315f8c19e","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"id":"7470546a-146a-4674-9c21-43263ff75c5c","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Optimization / Interview Tactics","type":"text"}],"id":"b3b7eaa3-f648-473c-8bac-e0bf2448bfbc","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Always start by clarifying requirements","type":"text"},{"styles":{},"text":" — ask the interviewer what entities they want you to model","type":"text"}],"id":"fb1d18e2-c124-4691-b5d0-77043fb6744f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Draw before you speak","type":"text"},{"styles":{},"text":" — sketch the entities and relationships; visual diagrams communicate faster than words","type":"text"}],"id":"6f1705f9-5e10-46d7-8b63-ae39d2c1eb4c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Explain your thought process out loud","type":"text"},{"styles":{},"text":" — interviewers are assessing your reasoning, not just the final answer","type":"text"}],"id":"17c824ad-6cfc-4257-a41b-82aba318d152","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Use standard notation","type":"text"},{"styles":{},"text":" — underline primary keys, mark (FK) for foreign keys, use ","type":"text"},{"styles":{"code":true},"text":"───<","type":"text"},{"styles":{},"text":" for one-to-many","type":"text"}],"id":"1e9d1395-d075-478a-a6f2-70405db45f6a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Mention normalization","type":"text"},{"styles":{},"text":" — \"This design is in 3NF because...\" shows depth","type":"text"}],"id":"4e2294ed-93bb-453b-bb9d-b64ae1eb3cb2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Know when to stop","type":"text"},{"styles":{},"text":" — don''t over-engineer; for a 20-minute interview, 4-5 entities is enough","type":"text"}],"id":"6271e9a1-fef3-4f00-a792-c564bcc595ec","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Always justify the junction table","type":"text"},{"styles":{},"text":" — explain why many-to-many needs it; it shows you understand relational constraints","type":"text"}],"id":"6af5becb-1cf7-4c65-ad09-b5de97d7adb3","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"If you forget a relationship, acknowledge it","type":"text"},{"styles":{},"text":" — ","type":"text"},{"styles":{"italic":true},"text":"\"I should also model the relationship between X and Y\"","type":"text"},{"styles":{},"text":" — shows self-awareness","type":"text"}],"id":"6c3abd88-5ed7-410f-92c7-3a7fdc6204e6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Name real-world examples","type":"text"},{"styles":{},"text":" — ","type":"text"},{"styles":{"italic":true},"text":"\"This is similar to how Amazon models orders and products\"","type":"text"},{"styles":{},"text":" — shows practical awareness","type":"text"}],"id":"18167a69-d865-4a95-901a-a4d3f9e77a51","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"For Sysco LABS / EY GDS / Dialog Axiata:","type":"text"},{"styles":{},"text":" These companies deal with enterprise systems — expect questions about designing ERDs for order management, customer tracking, billing, or inventory","type":"text"}],"id":"5ed489bb-0539-42ef-bbed-d7bb775fb91f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"id":"8adb4eac-6091-4bb5-ad91-e75767149713","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"9. Final Interview Summary","type":"text"}],"id":"d91ee0f6-9c68-48fb-992d-60751829b7a5","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Key Terms","type":"text"}],"id":"25415f48-71ed-4d70-be9d-129d90308576","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Term","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Definition","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"ERD","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Entity-Relationship Diagram — visual blueprint of database structure","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Entity","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"A thing the business tracks — becomes a table","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Attribute","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"A property of an entity — becomes a column","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Primary Key (PK)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Unique identifier for each entity instance","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Foreign Key (FK)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Attribute referencing another entity''s primary key — establishes relationship","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Relationship","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Association between two entities","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Cardinality","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Numerical nature of a relationship (1:1, 1:N, M:N)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"One-to-One (1:1)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Each instance of A relates to exactly one instance of B","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"One-to-Many (1:N)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Each instance of A relates to many instances of B","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Many-to-Many (M:N)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Each instance of A relates to many B; each B to many A","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Junction Table","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Table resolving M:N into two 1:N relationships","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Composite Key","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Primary key made of multiple columns (common in junction tables)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Referential Integrity","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Foreign key constraints ensure relationships remain valid","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"79516d95-83d9-483f-80b4-ba4fb8cd1d12","props":{"textColor":"default"},"type":"table"},{"children":[],"id":"5a6895e1-9681-4efd-80ed-27b4541e35c4","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Must-Remember Points","type":"text"}],"id":"7f786f68-bed3-41c4-b1e5-8d907109d87f","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"✅ ","type":"text"},{"styles":{"bold":true},"text":"ERD = blueprint before coding","type":"text"},{"styles":{},"text":" — design the schema visually before writing SQL","type":"text"}],"id":"e039d0e7-e06e-46e2-837d-9f1350016d57","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"✅ Entities → tables, Attributes → columns, PK → unique identifier, FK → relationship connector","type":"text"}],"id":"80c3123c-f72d-4d7f-a88f-cf176db00667","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"✅ ","type":"text"},{"styles":{"bold":true},"text":"Three relationship types:","type":"text"},{"styles":{},"text":" 1:1, 1:N, M:N","type":"text"}],"id":"472f1fe7-6531-469e-948e-c61cde7113e5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"✅ ","type":"text"},{"styles":{"bold":true},"text":"Many-to-many requires a junction table","type":"text"},{"styles":{},"text":" — relational databases cannot model M:N directly","type":"text"}],"id":"059166d7-70ac-4e11-b31f-8c5aa8e088ee","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"✅ Foreign key always goes on the ","type":"text"},{"styles":{"bold":true},"text":"\"many\" side","type":"text"},{"styles":{},"text":" of a 1:N relationship","type":"text"}],"id":"872bfade-1a64-4985-a2e5-96e7a63df7f1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"✅ Junction table stores both FKs plus ","type":"text"},{"styles":{"bold":true},"text":"relationship-specific attributes","type":"text"},{"styles":{},"text":" (like ","type":"text"},{"styles":{"code":true},"text":"quantity","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"unit_price","type":"text"},{"styles":{},"text":")","type":"text"}],"id":"39f40310-0cb6-45c5-9ce1-59b4f88ad12b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"✅ Primary keys should be ","type":"text"},{"styles":{"bold":true},"text":"surrogate keys","type":"text"},{"styles":{},"text":" (auto-increment integers), not natural keys","type":"text"}],"id":"5eaa062c-d36c-4b19-b408-0457355dfdd7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"✅ Always ","type":"text"},{"styles":{"bold":true},"text":"normalize to at least 3NF","type":"text"},{"styles":{},"text":" in OLTP schema design","type":"text"}],"id":"2fef3231-3f57-43ef-9417-e73755d0f0d1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"✅ ","type":"text"},{"styles":{"bold":true},"text":"Clarify requirements before designing","type":"text"},{"styles":{},"text":" — ask what entities and relationships are needed","type":"text"}],"id":"4145f890-fe30-4abd-a22d-510190b4a8d5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"✅ ","type":"text"},{"styles":{"bold":true},"text":"Walk through your reasoning aloud","type":"text"},{"styles":{},"text":" — interviewers evaluate thought process, not just final diagram","type":"text"}],"id":"309666af-175f-468a-9d74-6196e3b04e18","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"id":"19fb1ebf-e668-472a-b4e2-5d6c43432ddb","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"3 Interview-Ready One-Liners","type":"text"}],"id":"6f7ae4a2-fd4d-406d-87c1-424e280d1990","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"1.","type":"text"},{"styles":{},"text":" ","type":"text"},{"styles":{"italic":true},"text":"\"An ERD is the visual blueprint of a relational database where entities become tables, attributes become columns, primary keys uniquely identify rows, and foreign keys establish relationships — and it''s designed before writing any SQL to ensure the schema correctly models the business.\"","type":"text"}],"id":"0e993125-643f-49f9-b5d7-b1e4a38127cb","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"bold":true},"text":"2.","type":"text"},{"styles":{},"text":" ","type":"text"},{"styles":{"italic":true},"text":"\"Many-to-many relationships cannot be directly represented in a relational database, so we introduce a junction table that breaks the M:N into two one-to-many relationships — for example, ","type":"text"},{"styles":{"code":true},"text":"OrderItem","type":"text"},{"styles":{"italic":true},"text":" sits between ","type":"text"},{"styles":{"code":true},"text":"Order","type":"text"},{"styles":{"italic":true},"text":" and ","type":"text"},{"styles":{"code":true},"text":"Product","type":"text"},{"styles":{"italic":true},"text":", storing not only the foreign keys but also relationship-specific attributes like quantity and unit price.\"","type":"text"}],"id":"eacfa1d8-dc2c-411d-b5af-394b9a907f5f","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"bold":true},"text":"3.","type":"text"},{"styles":{},"text":" ","type":"text"},{"styles":{"italic":true},"text":"\"When designing an ERD, I start by identifying entities as the key nouns in the business domain, define their attributes and primary keys, establish relationships with foreign keys, identify cardinality, and resolve any many-to-many relationships with junction tables — this ensures a normalized, well-structured schema that supports both data integrity and efficient querying.\"","type":"text"}],"id":"27b9fba9-af54-4112-af2c-dbc805a0fc42","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"e4d98365-34e3-42ea-8fac-6e1f7b14a43c","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Common Mistakes to Avoid","type":"text"}],"id":"7f2cfb5e-6792-4c43-8c16-c21aa5f04392","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":{"columnWidths":[null,null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Mistake","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Why It''s Wrong","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Correct Approach","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Storing multiple values in one column (e.g., \"301,205,408\")","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Violates 1NF — not atomic; impossible to query efficiently","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Use a junction table with one row per value","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Trying to model M:N without a junction table","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Cannot be done in a relational database","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Always introduce a junction table for M:N","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Putting the FK on the wrong side of a 1:N","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Causes data duplication and violates normalization","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"FK goes on the \"many\" side","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Using natural keys as primary keys","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Natural keys can change (email, phone); causes cascading updates","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Use surrogate auto-increment integer keys","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Forgetting to mark FKs in the diagram","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Makes relationships unclear","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Always label foreign keys explicitly","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Over-complicating the design in an interview","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Wastes time; interviewer loses track","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Start simple — 3-4 entities, add complexity only if asked","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Not explaining the junction table purpose","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Looks like rote memorization","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Explain both structural and functional reasons","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Skipping normalization","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Results in update/insert/delete anomalies","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Always design to at least 3NF","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Not asking clarifying questions","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Shows you''re guessing, not designing","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Always clarify requirements before drawing","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"553df6a0-749e-481f-a378-2bac03417beb","props":{"textColor":"default"},"type":"table"},{"children":[],"id":"9503b5db-8720-4474-ac4c-226bca4f09f4","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"Remember the map.","type":"text"},{"styles":{},"text":" An ERD is the map of a business system. Entities are the landmarks — customers, orders, products. Attributes describe them. Keys uniquely identify and connect them. Relationships show how they interact. Draw the map before building the city. A clear ERD prevents months of costly rework once data is loaded and the system is live.","type":"text"}],"id":"18bcfd64-358e-413b-9c2b-88f9a293dcfc","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[],"id":"148febb2-8dad-48cc-9093-95e26603050e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"}]'::jsonb, '3e9e3dd3-a59b-4b02-968a-ee95e7317583') ON CONFLICT ("node_id") DO UPDATE SET "bad_example" = EXCLUDED."bad_example", "completed_at" = EXCLUDED."completed_at", "created_at" = EXCLUDED."created_at", "definition" = EXCLUDED."definition", "good_example" = EXCLUDED."good_example", "is_completed" = EXCLUDED."is_completed", "key_points" = EXCLUDED."key_points", "last_edited" = EXCLUDED."last_edited", "map_id" = EXCLUDED."map_id", "mental_model" = EXCLUDED."mental_model", "notes" = EXCLUDED."notes", "resources" = EXCLUDED."resources", "rich_content" = EXCLUDED."rich_content", "user_id" = EXCLUDED."user_id";
INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-06-11T12:30:29.682628+00:00', '', '', '21891f6e-4261-4b03-bd88-34b6da981cc3', false, '[]'::jsonb, '2026-06-11T12:31:39.66+00:00', '2ad473fe-77dd-481e-8ba7-4b2b0336173f', '', 'bcc18360-2042-4040-a5c6-659b809519d8', '', '[]'::jsonb, '[{"children":[],"content":[{"styles":{"bold":true},"text":"What Is a Log?","type":"text"}],"id":"97365e95-be00-4f6c-ad7f-e10465054d6d","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"A ","type":"text"},{"styles":{"bold":true},"text":"log","type":"text"},{"styles":{},"text":" is simply a diary that a program writes automatically while it''s running.","type":"text"}],"id":"dfcbc667-40a7-48ff-aac6-bb2380835644","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Every time something happens inside a running program — a user logged in, an error occurred, a database query ran — the program writes a ","type":"text"},{"styles":{"bold":true},"text":"one-line note","type":"text"},{"styles":{},"text":" describing what happened, when it happened, and how serious it was.","type":"text"}],"id":"3a612228-ae3d-4b85-b98d-a1b4cbd63a9a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"That collection of notes is called a ","type":"text"},{"styles":{"bold":true},"text":"log file","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"f3c55537-38e2-4062-a119-bd894dfa9ef5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"6aec3185-b825-4e5a-91eb-94930894c73e","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"What a Log File Looks Like — Physically","type":"text"}],"id":"1cca91e7-a01c-4ec1-a034-6f93403e882e","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Open any ","type":"text"},{"styles":{"code":true},"text":".log","type":"text"},{"styles":{},"text":" file in a text editor and you see plain text like this:","type":"text"}],"id":"2f153721-d21d-452f-8eac-6f8c50cb3594","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"code":true},"text":"text","type":"text"}],"id":"5dce0470-36d3-4dc0-881f-4323765c844d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"2026-03-27 10:00:00 INFO    Server started successfully\n2026-03-27 10:01:03 DEBUG   Checking database connection\n2026-03-27 10:01:04 INFO    Connected to database\n2026-03-27 10:02:17 WARNING Memory usage at 80%\n2026-03-27 10:03:45 ERROR   Database query timed out\n2026-03-27 10:03:46 ERROR   Retrying connection...\n2026-03-27 10:04:01 CRITICAL Memory limit exceeded — shutting down","type":"text"}],"id":"c8990103-3f55-4a23-8a82-1acc21671b01","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"That''s it. Just text. One line per event. Each line has the same structure:","type":"text"}],"id":"3fe4d588-4dcc-4ef9-b5fa-6df6eaa5995b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"code":true},"text":"text","type":"text"}],"id":"f2f6ce20-3f8d-4246-a161-7223dcd80876","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"2026-03-27  10:00:00   INFO    Server started successfully\n──────────  ────────   ────    ──────────────────────────\n  date        time     level        message","type":"text"}],"id":"7b418da4-be9e-46bb-8468-96e6b60d83ee","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"a47979c8-1718-4945-945d-ac6798d07b8c","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"What the \"Level\" Means","type":"text"}],"id":"aaac659b-73f7-4476-8e54-063db2681800","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The level tells you ","type":"text"},{"styles":{"bold":true},"text":"how serious","type":"text"},{"styles":{},"text":" the event was — like a traffic light system:","type":"text"}],"id":"36094a20-56ab-46b4-a782-0576b72b451e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"textDEBUG    → developer detail — \"I''m checking the database now\"    (not important)\nINFO     → normal event    — \"Server started\"                   (everything fine)\nWARNING  → concern         — \"Memory at 80%\"                    (watch this)\nERROR    → something broke — \"Database timed out\"               (needs fixing)\nCRITICAL → serious failure — \"System shutting down\"             (emergency)","type":"text"}],"id":"0fd975ae-ba83-47f4-8bf3-e995fb4e5cda","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"When something goes wrong in production, a developer opens the log file, searches for ","type":"text"},{"styles":{"code":true},"text":"ERROR","type":"text"},{"styles":{},"text":" and ","type":"text"},{"styles":{"code":true},"text":"CRITICAL","type":"text"},{"styles":{},"text":" lines, and reads the messages to understand what happened. That''s called ","type":"text"},{"styles":{"bold":true},"text":"log reading","type":"text"},{"styles":{},"text":" — which is on your interview list.","type":"text"}],"id":"9ea361b0-300d-4cce-9228-52363a5d62df","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"792d9816-904d-465c-9637-d46d813723fe","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why Do We Need to Process Logs With Python?","type":"text"}],"id":"e19f88a5-2170-48ea-80d2-c5ef7e4c95ed","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"A real log file can have ","type":"text"},{"styles":{"bold":true},"text":"millions of lines","type":"text"},{"styles":{},"text":". You can''t read it manually. So you write a Python program that:","type":"text"}],"id":"cd003f49-a608-42c7-bbc9-53dcedc56623","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Opens the file","type":"text"}],"id":"e354cd3f-11a9-40ff-80f9-d069687134fd","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Reads every line","type":"text"}],"id":"e4bc861e-84df-49af-bd68-399ec2833f34","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Converts each line from raw text → a Python dict you can work with","type":"text"}],"id":"60d04302-ae81-4f9f-b834-0a6e24e5c08c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Counts errors, finds patterns, saves results","type":"text"}],"id":"91335331-4b58-460b-9fca-964f1c7ebd51","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"That''s exactly what the entire script does.","type":"text"}],"id":"c8b7cdaf-e2bb-4d27-bd67-71d441e580c9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"138e4d4d-6441-488f-8bb3-badb19f899e8","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"Now — What Each Function Does in Plain English","type":"text"}],"id":"20aee38e-3ec7-4c69-bc29-ac20d26c24b0","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"code":true},"text":"parse_log_line()","type":"text"},{"styles":{"bold":true},"text":" — Read One Sentence in the Diary","type":"text"}],"id":"4876e13d-7f1e-45f1-a37d-65e1c66710a1","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Imagine the log file is a diary with hundreds of entries. This function reads ","type":"text"},{"styles":{"bold":true},"text":"one single entry","type":"text"},{"styles":{},"text":" and converts it from raw text into a structured Python dict.","type":"text"}],"id":"69799221-e9db-4215-a48f-887dd0e55186","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"textRaw text:  \"2026-03-27 10:03:45 ERROR Database query timed out\"\n\nAfter parsing:\n{\n    ''timestamp'': ''2026-03-27T10:03:45'',\n    ''level'':     ''ERROR'',\n    ''message'':   ''Database query timed out'',\n    ''line_number'': 5\n}","type":"text"}],"id":"3901bd5b-ae1d-4b18-b74f-2a8acf56b621","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Now Python can work with it — check the level, compare timestamps, filter by type. You can''t do that with raw text.","type":"text"}],"id":"a6349032-3471-455f-b390-254e7a5ce352","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"What can go wrong here?","type":"text"}],"id":"5ce68d8b-4937-495c-89f1-734ad04567a2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"text\"THIS LINE IS BROKEN\"           → only 1 part, not 4 → InvalidLogFormatError\n\"2026-99-99 10:00:00 ERROR msg\" → invalid date       → InvalidLogFormatError\n\"2026-03-27 10:00:00 OOPS msg\"  → unknown level      → InvalidLogFormatError\n\"\"                              → blank line          → returns None (not an error)","type":"text"}],"id":"5fe4b7fe-ce66-46e5-b19e-724ba5921db5","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"d699564b-455a-4180-a71f-15f66f4a7cda","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"code":true},"text":"process_log_file()","type":"text"},{"styles":{"bold":true},"text":" — Read the Entire Diary","type":"text"}],"id":"a61e779c-c20f-4170-87bd-feffc58fbdf7","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"This function opens the entire log file and calls ","type":"text"},{"styles":{"code":true},"text":"parse_log_line()","type":"text"},{"styles":{},"text":" for every single line — returning a list of all the parsed dicts.","type":"text"}],"id":"413503ed-92d3-4a3f-8d52-9ab0ea108b6c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"text\"sample.log\"  (raw file on disk)\n    ↓\n[ line 1, line 2, line 3, line 4, line 5, line 6 ]   ← f.readlines()\n    ↓\nparse each line one by one\n    ↓\n[\n    {''timestamp'': ''...'', ''level'': ''INFO'',     ''message'': ''Server started''},\n    {''timestamp'': ''...'', ''level'': ''DEBUG'',    ''message'': ''Checking connection''},\n    {''timestamp'': ''...'', ''level'': ''ERROR'',    ''message'': ''Database timeout''},\n    # line 4 was broken → skipped (skip_invalid=True)\n    {''timestamp'': ''...'', ''level'': ''CRITICAL'', ''message'': ''Memory limit exceeded''},\n    {''timestamp'': ''...'', ''level'': ''WARNING'',  ''message'': ''High CPU usage''}\n]","type":"text"}],"id":"9c6ff09c-18fe-4509-a440-c383da3c0029","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"What can go wrong here?","type":"text"}],"id":"7229ad1a-9b63-406b-b5c0-bd752b014af7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"textFile doesn''t exist     → FileNotFoundError\nNo permission to read  → PermissionError\nAll lines are broken   → EmptyLogFileError","type":"text"}],"id":"52d01cc6-8561-4c1d-ba64-adedd8cca9ea","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"8946342b-dc93-4d37-9715-f12df17407b8","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"code":true},"text":"analyze_logs()","type":"text"},{"styles":{"bold":true},"text":" — Count and Summarize the Diary","type":"text"}],"id":"b02898d9-be19-4e86-8698-a3d48fea5ee3","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Takes the list of parsed dicts and answers: ","type":"text"},{"styles":{"bold":true},"text":"\"How many of each type? Which ones were critical?\"","type":"text"}],"id":"fea6e5f7-350a-4ca5-9e16-96c44a8a21f6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"textInput (list of dicts):\n[\n    {''level'': ''INFO'',     ...},\n    {''level'': ''DEBUG'',    ...},\n    {''level'': ''ERROR'',    ...},\n    {''level'': ''CRITICAL'', ...},\n    {''level'': ''WARNING'',  ...}\n]\n\nOutput (summary dict):\n{\n    ''total'': 5,\n    ''by_level'': {\n        ''INFO'':     1,\n        ''DEBUG'':    1,\n        ''ERROR'':    1,\n        ''CRITICAL'': 1,\n        ''WARNING'':  1\n    },\n    ''critical'': [\n        {''level'': ''ERROR'',    ''message'': ''Database timeout'',      ...},\n        {''level'': ''CRITICAL'', ''message'': ''Memory limit exceeded'', ...}\n    ]\n}","type":"text"}],"id":"883a30d4-7511-4533-b0cb-f6ff09ec9f16","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"This is just the ","type":"text"},{"styles":{"bold":true},"text":"counter pattern","type":"text"},{"styles":{},"text":" you already know — applied to log levels.","type":"text"}],"id":"84bc9d34-1d66-4fbf-b405-50bb463a7993","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"8f906d2c-df4f-40f9-98cd-082c5fd4b100","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"code":true},"text":"run_log_analysis()","type":"text"},{"styles":{"bold":true},"text":" — The Manager","type":"text"}],"id":"57ad1b93-d828-4ff1-b6e8-fc97b4b9fbcc","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"This function doesn''t do any real work itself. It calls the other three functions in order and handles everything that goes wrong — printing clear messages to the user instead of crashing.","type":"text"}],"id":"74752011-54e7-421a-8066-554d1e32d59c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"textrun_log_analysis(\"sample.log\")\n│\n├─ calls process_log_file()   → gets list of dicts\n├─ calls analyze_logs()        → gets summary dict\n├─ prints summary to screen\n└─ saves results.json (if requested)\n\nIf anything fails at any step → prints error message → returns None","type":"text"}],"id":"45e68ab9-addc-4eaa-a7b8-06b7b6d287f0","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Think of it as the ","type":"text"},{"styles":{"bold":true},"text":"front desk","type":"text"},{"styles":{},"text":" — the user talks to the front desk, the front desk coordinates with the back office. The user never needs to know how the back office works.","type":"text"}],"id":"17b665c0-3641-4f38-b9dd-5c7fdf4b786b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"65f3f9ef-f7e3-4684-a5e9-9fccbb310257","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"The Complete Mental Picture","type":"text"}],"id":"027221fa-214b-4bfa-8018-05ff4a4bf6b1","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"textsample.log (text file on disk)\n│\n│  2026-03-27 10:00:00 INFO  Server started\n│  2026-03-27 10:02:00 ERROR Database timeout\n│  THIS LINE IS BROKEN\n│  2026-03-27 10:03:00 CRITICAL Memory exceeded\n│\n▼\nprocess_log_file()     ← opens file, feeds each line to parse_log_line()\n│\n├── parse_log_line()   ← converts \"2026-03-27 10:00:00 INFO Server started\"\n│                         into {''level'': ''INFO'', ''message'': ''Server started'', ...}\n│\n├── parse_log_line()   ← converts ERROR line into dict\n│\n├── parse_log_line()   ← \"THIS LINE IS BROKEN\" → skip (skip_invalid=True)\n│\n└── parse_log_line()   ← converts CRITICAL line into dict\n│\n▼\n[list of 3 valid dicts]\n│\n▼\nanalyze_logs()         ← counts: INFO=1, ERROR=1, CRITICAL=1\n                          collects: ERROR + CRITICAL entries\n│\n▼\n{\n    ''total'': 3,\n    ''by_level'': {''INFO'': 1, ''ERROR'': 1, ''CRITICAL'': 1},\n    ''critical'': [ERROR entry, CRITICAL entry]\n}\n│\n▼\nrun_log_analysis()     ← prints summary to screen\n                          saves results.json","type":"text"}],"id":"53175e83-7a38-469c-9fd4-30e148f5e0b6","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Now every line of that script connects to something physical and real. The functions aren''t abstract — they''re reading a diary, converting sentences, counting words, and reporting the summary. That''s the entire codebase.","type":"text"}],"id":"ae86964d-3be1-4de6-a389-b0615acc786a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[],"id":"5a9d028b-596a-4c7f-b6e6-149762b70e60","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"}]'::jsonb, '3e9e3dd3-a59b-4b02-968a-ee95e7317583') ON CONFLICT ("node_id") DO UPDATE SET "bad_example" = EXCLUDED."bad_example", "completed_at" = EXCLUDED."completed_at", "created_at" = EXCLUDED."created_at", "definition" = EXCLUDED."definition", "good_example" = EXCLUDED."good_example", "is_completed" = EXCLUDED."is_completed", "key_points" = EXCLUDED."key_points", "last_edited" = EXCLUDED."last_edited", "map_id" = EXCLUDED."map_id", "mental_model" = EXCLUDED."mental_model", "notes" = EXCLUDED."notes", "resources" = EXCLUDED."resources", "rich_content" = EXCLUDED."rich_content", "user_id" = EXCLUDED."user_id";
INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-06-13T14:20:14.272378+00:00', '', '', 'ed60f42e-c0f8-4021-9a47-7080c2e76f56', false, '[]'::jsonb, '2026-06-13T14:20:23.375+00:00', '2ad473fe-77dd-481e-8ba7-4b2b0336173f', '', 'e5c9367f-8c05-4c99-b484-4d87d0c88924', '', '[]'::jsonb, '[{"children":[],"content":[],"id":"5834b155-349f-4c30-a31f-7628f896f0b5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"aa879e34-7f92-43dd-b467-36a7a448dc31","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Very short intro","type":"text"}],"id":"10c1f878-f1cb-4b11-8949-5657d899f61b","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"At the ","type":"text"},{"styles":{"bold":true},"text":"Distribution Hub","type":"text"},{"styles":{},"text":", the ","type":"text"},{"styles":{"bold":true},"text":"Data Vault","type":"text"},{"styles":{},"text":" is where processed shipments are stored and retrieved safely. You cannot just walk in — you need the ","type":"text"},{"styles":{"bold":true},"text":"vault door","type":"text"},{"styles":{},"text":" open, pass the ","type":"text"},{"styles":{"bold":true},"text":"security panel","type":"text"},{"styles":{},"text":", and use the right ","type":"text"},{"styles":{"bold":true},"text":"access code","type":"text"},{"styles":{},"text":" so nothing gets injected or corrupted. The ","type":"text"},{"styles":{"bold":true},"text":"control desk","type":"text"},{"styles":{},"text":" (SQLAlchemy) manages all of this. The ","type":"text"},{"styles":{"bold":true},"text":"raw key","type":"text"},{"styles":{},"text":" (psycopg2) opens the vault directly but gives you no help. Topic 5 is the minimum you need to read from and write to a database safely.","type":"text"}],"id":"fef851c2-2cb7-4d19-969a-1df18940fd6a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"e880279c-739e-47ac-9327-e98fb0c94367","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Mind map","type":"text"}],"id":"a74621e5-0b16-4a27-b20b-dc3bfd88c96e","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"DATA VAULT\n(Safe Database Connectivity)\n│\n├── Control Desk\n│   └── SQLAlchemy (the layer that manages everything)\n│\n├── Raw Key\n│   └── psycopg2 (direct driver, no abstraction)\n│\n├── Vault Door\n│   └── create_engine()\n│\n├── Security Panel\n│   └── with engine.connect() as conn:\n│\n├── Access Code\n│   └── text() + :param (parameterized queries)\n│\n├── Receipt Printer\n│   └── pd.read_sql()\n│\n└── Storage Slot\n    └── df.to_sql() + if_exists","type":"text"}],"id":"df77f819-eb93-4fc2-9e99-7fabb15d4147","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"df1ea0b9-4976-4831-ab5b-b817c9cf4288","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Decision tree","type":"text"}],"id":"c633b0fb-946b-4a3a-8cd2-d12db15d40c5","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Need to connect to PostgreSQL?\n│\n├── Want abstraction, safety, and pandas integration?\n│   └── Use SQLAlchemy → create_engine()\n│\n└── Need a raw, lightweight connection only?\n    └── Use psycopg2 directly\n\nHave an engine?\n│\n├── Running a query and reading results into pandas?\n│   └── pd.read_sql(query, conn)\n│\n└── Writing a DataFrame to the database?\n    └── df.to_sql(\"table_name\", engine, if_exists=...)\n            │\n            ├── \"fail\"    → error if table exists\n            ├── \"replace\" → drop and recreate\n            └── \"append\"  → add rows to existing table\n\nRunning a parameterized query?\n└── Always use text(\"SELECT ... WHERE x = :val\")\n    with conn.execute(query, {\"val\": value})\n    Never use f-strings or string concat in SQL.","type":"text"}],"id":"2912fa13-efae-4218-a423-16bb649561f2","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"8c61fda3-387c-40b2-a2df-79178721c412","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Concept breakdown","type":"text"}],"id":"34918728-42b9-4cb6-91ad-5d7667ef5eda","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"id":"405c2fe6-6604-485a-acc3-81263c813858","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"1) Vault Door — ","type":"text"},{"styles":{"code":true},"text":"create_engine()","type":"text"}],"id":"3c77d015-edac-4d46-974f-b91021414db8","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" Creates a SQLAlchemy engine that holds the connection configuration. It does not open a connection immediately — it just sets up the door.","type":"text"}],"id":"d89f9de7-f55e-4a14-9b46-8bc05be53352","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters in an interview:","type":"text"},{"styles":{},"text":" This is the entry point to every SQLAlchemy-based DB task. Interviewers expect you to know the connection string shape and what the engine represents.","type":"text"}],"id":"6a96eddd-8629-4638-9678-b630a9059142","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"83d9b84b-9a5c-4c86-ab90-2a6bb7e717e2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"from sqlalchemy import create_engine\n\nengine = create_engine(\n    \"postgresql+psycopg2://user:password@host:5432/dbname\"\n)","type":"text"}],"id":"6ee53bb9-d73b-4ee9-973f-225f053d6a1d","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Rule: The engine is not a connection. It is a factory. Connections come from ","type":"text"},{"styles":{"code":true},"text":"engine.connect()","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"95fcf579-7aeb-4824-8585-65076b48a9e4","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"2056773c-e0d6-4c32-850a-94baf102afd0","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"2) Basic connection string for PostgreSQL","type":"text"}],"id":"36b39b9e-16b2-4612-b614-4ecc5d82eae5","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" The URL that tells SQLAlchemy how to reach the database. The shape is always the same.","type":"text"}],"id":"a50de7cf-37f5-497d-94cb-c427c23995dd","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters in an interview:","type":"text"},{"styles":{},"text":" You will be asked to write or read a connection string. Knowing the shape prevents wasted time.","type":"text"}],"id":"9117c89e-41ce-4264-9ff6-bca6888ec4dc","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"postgresql+psycopg2://  user  :  password  @  host  :  port  /  dbname\n└── driver ──────────┘  └─ credentials ─┘    └─ location ─┘   └─ db ─┘","type":"text"}],"id":"3b1080c2-53c4-49ef-8466-b477d2a3a411","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Memorize this shape. The ","type":"text"},{"styles":{"code":true},"text":"+psycopg2","type":"text"},{"styles":{},"text":" part tells SQLAlchemy to use the psycopg2 driver.","type":"text"}],"id":"866acc01-d8f6-492c-bdc0-8fbb72d4df7f","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"70f740d0-b013-4d17-b5ab-7f674b9ba435","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"3) Security Panel — ","type":"text"},{"styles":{"code":true},"text":"with engine.connect() as conn:","type":"text"}],"id":"75da4a55-fc58-427f-b223-4e18179a43c3","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" Opens a connection from the engine and automatically closes it when the block exits. Safe and clean.","type":"text"}],"id":"9241a170-69ad-4750-bbac-39ace5c94e78","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters in an interview:","type":"text"},{"styles":{},"text":" Using ","type":"text"},{"styles":{"code":true},"text":"with","type":"text"},{"styles":{},"text":" ensures the connection is always closed, even if an error happens. Interviewers expect this pattern.","type":"text"}],"id":"a901fc34-4ccf-4c76-bea7-0e47428d80b7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"eb86dba1-ffa9-4519-90f6-3e820f40500e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"with engine.connect() as conn:\n    result = conn.execute(text(\"SELECT 1\"))\n    print(result.fetchone())","type":"text"}],"id":"ef624607-acb3-49b9-9abb-3480a24eb469","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Rule: Always use ","type":"text"},{"styles":{"code":true},"text":"with engine.connect()","type":"text"},{"styles":{},"text":". Never open and close manually.","type":"text"}],"id":"ecb981bc-e148-4dd1-934e-f5b8c0290e53","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"7986de47-d945-4c06-a665-a73bc0779643","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"4) Access Code — parameterized queries with ","type":"text"},{"styles":{"code":true},"text":"text()","type":"text"},{"styles":{},"text":" and ","type":"text"},{"styles":{"code":true},"text":":param","type":"text"}],"id":"43bdff00-571d-417f-a8c3-3effca16a286","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" A safe way to pass values into SQL queries. You write ","type":"text"},{"styles":{"code":true},"text":":param_name","type":"text"},{"styles":{},"text":" as a placeholder and pass a dict with the values. SQLAlchemy handles escaping — no SQL injection possible.","type":"text"}],"id":"bb8d7c16-4ba4-476c-8385-b950b1012d69","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters in an interview:","type":"text"},{"styles":{},"text":" Using f-strings to build SQL is a security anti-pattern. This is an almost guaranteed interview topic. You must use parameterized queries.","type":"text"}],"id":"ddb9993e-7cc2-49e4-a24e-ad46111b60db","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"efa12eb1-540d-4999-8ac7-332c13938353","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"from sqlalchemy import text\n\nquery = text(\"SELECT * FROM orders WHERE status = :status\")\n\nwith engine.connect() as conn:\n    result = conn.execute(query, {\"status\": \"shipped\"})\n    rows = result.fetchall()","type":"text"}],"id":"31eed190-d7bf-4e88-b319-fa3649a6e193","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Rule: ","type":"text"},{"styles":{"code":true},"text":":param","type":"text"},{"styles":{},"text":" in the SQL string. Dict of values in ","type":"text"},{"styles":{"code":true},"text":"execute()","type":"text"},{"styles":{},"text":". Never use ","type":"text"},{"styles":{"code":true},"text":"f\"... WHERE x = {value}\"","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"515bb2ed-8f51-4151-af2b-8cfcc2b1484a","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"29bc1721-0625-49b6-909c-e2bd8dd4648e","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"5) Receipt Printer — ","type":"text"},{"styles":{"code":true},"text":"pd.read_sql()","type":"text"}],"id":"d8676aaa-0243-43dd-9864-1f743604b535","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" Runs a SQL query and loads the result directly into a pandas DataFrame.","type":"text"}],"id":"e979f6cf-97a0-4c18-99fd-f081858434bd","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters in an interview:","type":"text"},{"styles":{},"text":" The fastest way to get query results into pandas for downstream processing. Common in every internship DE task involving databases.","type":"text"}],"id":"62e6f482-b6ad-4ceb-a6bb-bca778b0b245","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"2276f173-a9b2-4898-8003-f757a99bc9bd","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"import pandas as pd\nfrom sqlalchemy import text\n\nquery = text(\"SELECT * FROM orders WHERE status = :status\")\n\nwith engine.connect() as conn:\n    df = pd.read_sql(query, conn, params={\"status\": \"shipped\"})\n\nprint(df.head())","type":"text"}],"id":"8b63a320-1ce7-444e-9848-a68c7588fc18","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Rule: Pass ","type":"text"},{"styles":{"code":true},"text":"conn","type":"text"},{"styles":{},"text":" (the open connection), not ","type":"text"},{"styles":{"code":true},"text":"engine","type":"text"},{"styles":{},"text":", into ","type":"text"},{"styles":{"code":true},"text":"pd.read_sql()","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"28ba16e2-8a1c-4ee5-9005-833cdb5043e7","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"dae0800c-19b1-4173-9264-81329d8135c5","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"6) Storage Slot — ","type":"text"},{"styles":{"code":true},"text":"df.to_sql()","type":"text"},{"styles":{},"text":" with ","type":"text"},{"styles":{"code":true},"text":"if_exists","type":"text"}],"id":"af3982b8-e6a2-44d2-94eb-48ef2f7985d8","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" Writes a DataFrame to a database table. The ","type":"text"},{"styles":{"code":true},"text":"if_exists","type":"text"},{"styles":{},"text":" argument controls what happens if the table already exists.","type":"text"}],"id":"1c90c370-ce80-40e7-b626-09f0367626e5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters in an interview:","type":"text"},{"styles":{},"text":" You must know all three ","type":"text"},{"styles":{"code":true},"text":"if_exists","type":"text"},{"styles":{},"text":" options and when to use each. Choosing wrong can destroy data or fail silently.","type":"text"}],"id":"b511755a-4a95-437b-b221-954c51a734c2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"731b1605-b687-449e-b5aa-fae7bfa0de89","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"df.to_sql(\n    \"orders_clean\",\n    engine,\n    if_exists=\"append\",   # \"fail\" | \"replace\" | \"append\"\n    index=False           # do not write DataFrame index as a column\n)","type":"text"}],"id":"0841e0e3-3829-4494-83be-89ffc34d77ca","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Rule: ","type":"text"},{"styles":{"code":true},"text":"index=False","type":"text"},{"styles":{},"text":" almost always. ","type":"text"},{"styles":{"code":true},"text":"if_exists=\"replace\"","type":"text"},{"styles":{},"text":" drops and recreates — use carefully.","type":"text"}],"id":"675d2f27-b533-4056-897c-7d7bd8ba077c","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"6d09ea46-2227-4a5e-acd7-4de203314e3a","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"7) Raw Key vs Control Desk — ","type":"text"},{"styles":{"code":true},"text":"psycopg2","type":"text"},{"styles":{},"text":" vs SQLAlchemy","type":"text"}],"id":"6d8d3abc-0906-4502-9ed2-1a6901016925","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"}],"id":"9f389414-29c0-4b7f-a945-6460220ecc19","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"psycopg2","type":"text"},{"styles":{},"text":" is the raw PostgreSQL driver. Low-level, no abstraction.","type":"text"}],"id":"c719265c-7bf5-41be-8a26-d9b4f119a61a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"SQLAlchemy","type":"text"},{"styles":{},"text":" sits on top of psycopg2 and gives you engine management, connection pooling, and pandas integration.","type":"text"}],"id":"c937b388-23c4-48eb-a22d-ae180c67d6d4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters in an interview:","type":"text"},{"styles":{},"text":" A common question is \"what is the difference?\" The answer is one sentence: SQLAlchemy is the abstraction layer; psycopg2 is the underlying driver it uses.","type":"text"}],"id":"11d49101-a8d9-4868-9449-d7e312dfa8fc","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"582012b8-038e-46ac-b56d-51f88dd90001","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"# Raw Key: psycopg2 only\nimport psycopg2\nconn = psycopg2.connect(\n    host=\"host\", dbname=\"dbname\", user=\"user\", password=\"password\"\n)\ncursor = conn.cursor()\ncursor.execute(\"SELECT * FROM orders\")\n\n# Control Desk: SQLAlchemy (uses psycopg2 under the hood)\nfrom sqlalchemy import create_engine\nengine = create_engine(\"postgresql+psycopg2://user:password@host:5432/dbname\")","type":"text"}],"id":"f55a0311-95a8-40e3-a602-b30cf82c27aa","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Rule: For internship tasks, default to SQLAlchemy. Use psycopg2 directly only if told to.","type":"text"}],"id":"8cc004ec-9cc8-44aa-888a-cd9d4f12bedc","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"bf4af341-d226-43bc-b883-45b8dd94964e","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Common mistakes","type":"text"}],"id":"14247ed5-da78-4b93-9d6e-7abc65756e0f","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Mistake","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Fix","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Using f-strings to build SQL queries","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Always use ","type":"text"},{"styles":{"code":true},"text":"text()","type":"text"},{"styles":{},"text":" with ","type":"text"},{"styles":{"code":true},"text":":param","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Passing ","type":"text"},{"styles":{"code":true},"text":"engine","type":"text"},{"styles":{},"text":" instead of ","type":"text"},{"styles":{"code":true},"text":"conn","type":"text"},{"styles":{},"text":" to ","type":"text"},{"styles":{"code":true},"text":"pd.read_sql()","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Pass the open ","type":"text"},{"styles":{"code":true},"text":"conn","type":"text"},{"styles":{},"text":" from ","type":"text"},{"styles":{"code":true},"text":"with engine.connect()","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Forgetting ","type":"text"},{"styles":{"code":true},"text":"index=False","type":"text"},{"styles":{},"text":" in ","type":"text"},{"styles":{"code":true},"text":"df.to_sql()","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Add ","type":"text"},{"styles":{"code":true},"text":"index=False","type":"text"},{"styles":{},"text":" to avoid a junk index column","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Using ","type":"text"},{"styles":{"code":true},"text":"if_exists=\"replace\"","type":"text"},{"styles":{},"text":" carelessly","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"This drops and recreates the table — all existing rows gone","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Not using ","type":"text"},{"styles":{"code":true},"text":"with engine.connect()","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Connection leaks if not properly closed","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Confusing psycopg2 and SQLAlchemy","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"SQLAlchemy wraps psycopg2; they are not alternatives at the same level","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Wrong connection string format","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Memorize: ","type":"text"},{"styles":{"code":true},"text":"postgresql+psycopg2://user:pass@host:port/db","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"9649e46c-2602-4a73-bf6e-f4839065fdb4","props":{"textColor":"default"},"type":"table"},{"children":[],"id":"90dc91cc-fe8d-4961-a3fe-6a444479e756","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Practice ideas","type":"text"}],"id":"5f19062c-0868-4da6-92dd-8e7aece6f8ff","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Write a ","type":"text"},{"styles":{"code":true},"text":"create_engine()","type":"text"},{"styles":{},"text":" call for a PostgreSQL database from memory.","type":"text"}],"id":"dd6a0363-753a-4364-97f7-60f23cb373cc","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Open a connection with ","type":"text"},{"styles":{"code":true},"text":"with engine.connect()","type":"text"},{"styles":{},"text":" and run ","type":"text"},{"styles":{"code":true},"text":"SELECT 1","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"d6669aaa-7c63-4213-b744-38a087fc7dcb","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Write a parameterized query using ","type":"text"},{"styles":{"code":true},"text":"text()","type":"text"},{"styles":{},"text":" that filters by a date column.","type":"text"}],"id":"8ba913e7-e12d-4db6-bab6-ba03de61bda7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Use ","type":"text"},{"styles":{"code":true},"text":"pd.read_sql()","type":"text"},{"styles":{},"text":" to load the result of that query into a DataFrame.","type":"text"}],"id":"a842c152-de4a-4388-b482-d87d65970c32","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Write a small DataFrame to a test table with ","type":"text"},{"styles":{"code":true},"text":"df.to_sql()","type":"text"},{"styles":{},"text":". Try all three ","type":"text"},{"styles":{"code":true},"text":"if_exists","type":"text"},{"styles":{},"text":" modes and observe the behavior.","type":"text"}],"id":"6c49665c-4f66-4159-9b9c-6996075d4f2e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Explain aloud: what does psycopg2 do, and what does SQLAlchemy add?","type":"text"}],"id":"73060d86-3d54-414b-9f04-fc7dfc93a446","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"id":"3c55c8d7-7c9e-4374-8d35-54138e4ef2b7","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Final integrated coding example","type":"text"}],"id":"601a891a-dd40-455b-899a-ac23f078fd33","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Scenario:","type":"text"},{"styles":{},"text":" Pull shipped orders from a PostgreSQL database into a DataFrame, add a processed timestamp column, and write the result to a new summary table. Use parameterized queries throughout.","type":"text"}],"id":"8e27776a-b6a2-4718-bf33-81a34499666a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"import pandas as pd\nfrom datetime import datetime, timezone\nfrom sqlalchemy import create_engine, text\n\n# --- Vault Door: open the engine ---\n# postgresql+psycopg2://user:password@host:port/dbname\nengine = create_engine(\n    \"postgresql+psycopg2://de_user:secret@localhost:5432/hub_db\"\n)\n\n# psycopg2 vs SQLAlchemy note:\n# psycopg2 is the raw driver. SQLAlchemy wraps it.\n# We use SQLAlchemy here because it integrates cleanly with pandas.\n\n# --- Access Code: parameterized query ---\nquery = text(\"\"\"\n    SELECT order_id, customer_id, amount, status\n    FROM orders\n    WHERE status = :status\n      AND amount > :min_amount\n\"\"\")\n\n# --- Security Panel + Receipt Printer: read query results into DataFrame ---\nwith engine.connect() as conn:\n    df = pd.read_sql(\n        query,\n        conn,\n        params={\"status\": \"shipped\", \"min_amount\": 50}\n    )\n\nprint(f\"Fetched {len(df)} rows\")\nprint(df.head())\n\n# --- Light processing: add a UTC timestamp column ---\ndf[\"processed_at\"] = datetime.now(timezone.utc).isoformat()\n\n# --- Storage Slot: write results to a summary table ---\ndf.to_sql(\n    \"orders_shipped_summary\",   # target table name\n    engine,\n    if_exists=\"append\",         # append to existing, do not drop\n    index=False                 # do not write the DataFrame index\n)\n\nprint(\"Done. Rows written to orders_shipped_summary.\")","type":"text"}],"id":"5e6dd32d-4022-4196-ba12-ae3bfbfe9481","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"What each section maps to:","type":"text"}],"id":"69f40885-7cf6-4a34-abe5-fb5460f13eaf","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Code section","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Metaphor part","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"create_engine(...)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Vault Door","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"\"postgresql+psycopg2://...\"","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Connection string shape","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"with engine.connect() as conn:","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Security Panel","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"text(\"... WHERE x = :param\")","type":"text"},{"styles":{},"text":" + dict","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Access Code","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"pd.read_sql(query, conn, params=...)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Receipt Printer","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"df.to_sql(..., if_exists=\"append\")","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Storage Slot","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"SQLAlchemy wrapping psycopg2 comment","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Control Desk vs Raw Key","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"bff1c401-349c-4df4-a2b8-2eb3eb8273fc","props":{"textColor":"default"},"type":"table"},{"children":[],"id":"b00e053f-37a6-4c48-99ba-1482fe343184","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"italic":true},"text":"If you can write this script from memory and explain every line — especially why you never use f-strings in SQL — you are ready for internship-level database connectivity questions at the Data Vault.","type":"text"}],"id":"3d518c03-a1e8-4464-994a-e99fec1cf0f7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[],"id":"5e61bf7c-2018-4ebb-b00a-c61bf6c9a478","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"}]'::jsonb, '3e9e3dd3-a59b-4b02-968a-ee95e7317583') ON CONFLICT ("node_id") DO UPDATE SET "bad_example" = EXCLUDED."bad_example", "completed_at" = EXCLUDED."completed_at", "created_at" = EXCLUDED."created_at", "definition" = EXCLUDED."definition", "good_example" = EXCLUDED."good_example", "is_completed" = EXCLUDED."is_completed", "key_points" = EXCLUDED."key_points", "last_edited" = EXCLUDED."last_edited", "map_id" = EXCLUDED."map_id", "mental_model" = EXCLUDED."mental_model", "notes" = EXCLUDED."notes", "resources" = EXCLUDED."resources", "rich_content" = EXCLUDED."rich_content", "user_id" = EXCLUDED."user_id";
INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-06-13T15:13:44.634828+00:00', '', '', '00191f35-c0f5-4eeb-89fd-a96aaa619a84', false, '[]'::jsonb, '2026-06-13T15:13:54.036+00:00', '2ad473fe-77dd-481e-8ba7-4b2b0336173f', '', '559f9215-05d6-460a-82a8-75026984a794', '', '[]'::jsonb, '[{"children":[],"content":[],"id":"e6282d2d-af6d-46d0-9e4a-66e94516d7f8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"29c22cd0-d529-4966-b141-4cfce4707050","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Very short intro","type":"text"}],"id":"0515cb49-53d9-42be-a3c6-c9fc665ad3d9","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"At the ","type":"text"},{"styles":{"bold":true},"text":"Distribution Hub","type":"text"},{"styles":{},"text":", the ","type":"text"},{"styles":{"bold":true},"text":"Quality Check Point","type":"text"},{"styles":{},"text":" is where every incoming parcel is inspected before it moves further. A ","type":"text"},{"styles":{"bold":true},"text":"missing tag sign","type":"text"},{"styles":{},"text":" catches parcels with no label. A ","type":"text"},{"styles":{"bold":true},"text":"wrong size gauge","type":"text"},{"styles":{},"text":" checks if the content is the right type. A ","type":"text"},{"styles":{"bold":true},"text":"range meter","type":"text"},{"styles":{},"text":" flags values that are out of bounds. A ","type":"text"},{"styles":{"bold":true},"text":"format scanner","type":"text"},{"styles":{},"text":" verifies the label follows the correct pattern. Anything that fails goes into the ","type":"text"},{"styles":{"bold":true},"text":"reject bin","type":"text"},{"styles":{},"text":", gets counted on the ","type":"text"},{"styles":{"bold":true},"text":"count board","type":"text"},{"styles":{},"text":", and lands in the ","type":"text"},{"styles":{"bold":true},"text":"dead letter tray","type":"text"},{"styles":{},"text":" for review. Topic 12 is the minimum data validation knowledge an internship interviewer will expect.","type":"text"}],"id":"7958fe00-1e9b-41ff-8667-dcb2f9bf196f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"8a9729aa-ca2e-4136-8dbb-bd1744bf0bf8","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Mind map","type":"text"}],"id":"b7b4abd0-9579-4cd4-8444-a3116969bccf","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"QUALITY CHECK POINT\n(Basic Data Validation)\n│\n├── Missing Tag Sign\n│   └── pd.isna() / is None\n│\n├── Wrong Size Gauge\n│   └── isinstance()\n│\n├── Range Meter\n│   └── value < min or value > max\n│\n├── Format Scanner\n│   └── str.startswith() / re.match()\n│\n├── Reject Bin\n│   └── skip invalid row, record reason\n│\n├── Count Board\n│   └── valid_count / invalid_count summary\n│\n└── Dead Letter Tray\n    └── rejected rows → CSV file","type":"text"}],"id":"c013133b-d88f-4123-931f-1e00ed142860","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"4ad37111-9125-4a8d-94e2-832124d048de","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Decision tree","type":"text"}],"id":"5b6db1b0-7322-4f6b-a777-ea740058e208","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"A row arrives at the Quality Check Point.\n│\n├── Is a required field null or None?\n│   └── pd.isna(value) or value is None\n│       └── FAIL → Reject Bin\n│\n├── Is the value the right type?\n│   └── isinstance(value, (int, float))\n│       └── FAIL → Reject Bin\n│\n├── Is a numeric value within the expected range?\n│   └── value < 0 or value > 10_000\n│       └── FAIL → Reject Bin\n│\n├── Does a string field match the expected format?\n│   └── str.startswith(\"ORD-\") or re.match(pattern, value)\n│       └── FAIL → Reject Bin\n│\n└── Passed all checks?\n    └── PASS → valid_count += 1\n                row goes to clean output\n\nAfter all rows:\n├── Print Count Board (valid / invalid totals)\n└── Write dead letter rows to rejected.csv","type":"text"}],"id":"17579a39-3d7a-44af-9fef-7f9d6f319faa","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"bd892597-55e4-4ebe-bb04-bc5bd66a82c7","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Concept breakdown","type":"text"}],"id":"9a27a9e4-98ab-4512-8fac-0a0726d84759","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"id":"22feec40-827f-48f4-8a62-90ac92d6c94c","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"1) Missing Tag Sign — ","type":"text"},{"styles":{"code":true},"text":"pd.isna()","type":"text"},{"styles":{},"text":" / ","type":"text"},{"styles":{"code":true},"text":"is None","type":"text"}],"id":"29718722-e27b-4a82-b774-0fa4a671bd56","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" Checks whether a value is null. Use ","type":"text"},{"styles":{"code":true},"text":"pd.isna()","type":"text"},{"styles":{},"text":" for pandas values (handles ","type":"text"},{"styles":{"code":true},"text":"NaN","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"None","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"pd.NaT","type":"text"},{"styles":{},"text":"). Use ","type":"text"},{"styles":{"code":true},"text":"is None","type":"text"},{"styles":{},"text":" for plain Python objects.","type":"text"}],"id":"0a1675ce-407e-4c86-9577-5f51c74d52d6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters in an interview:","type":"text"},{"styles":{},"text":" Null checks are the first and most common validation step. Using ","type":"text"},{"styles":{"code":true},"text":"== None","type":"text"},{"styles":{},"text":" instead of ","type":"text"},{"styles":{"code":true},"text":"is None","type":"text"},{"styles":{},"text":" or ","type":"text"},{"styles":{"code":true},"text":"pd.isna()","type":"text"},{"styles":{},"text":" is a classic mistake.","type":"text"}],"id":"2a946230-7ff6-4277-9c9f-944254a9f09c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"5baf2e19-fe89-43f3-985b-f541b48a0838","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"import pandas as pd\n\nvalue = None\n\n# Plain Python\nif value is None:\n    print(\"Missing\")\n\n# Pandas / mixed types\nif pd.isna(value):\n    print(\"Missing\")","type":"text"}],"id":"9f6d102e-b7c6-4e42-a6ae-fa0267b0e0dc","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Rule: Use ","type":"text"},{"styles":{"code":true},"text":"pd.isna()","type":"text"},{"styles":{},"text":" when working with DataFrames or CSV-parsed values. Use ","type":"text"},{"styles":{"code":true},"text":"is None","type":"text"},{"styles":{},"text":" for plain Python dicts.","type":"text"}],"id":"53f2433d-34b0-451e-b032-96cefd7e6082","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"3cb440e8-ef54-449e-8403-0a998c12db88","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"2) Wrong Size Gauge — ","type":"text"},{"styles":{"code":true},"text":"isinstance()","type":"text"}],"id":"c1df73c3-2be0-4048-9f60-c509951ec91b","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" Checks whether a value is an instance of one or more expected types.","type":"text"}],"id":"05fdc10b-ffec-43a3-bbed-36a50d54a8e8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters in an interview:","type":"text"},{"styles":{},"text":" CSV parsing returns everything as strings. After type conversion, you need to verify the result is actually the expected type before using it.","type":"text"}],"id":"e1c71996-f3c2-4e49-a4ee-0994d030858e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"84d91670-a1ac-4a84-840a-7e464d905bf5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"amount = 250.0\n\nif not isinstance(amount, (int, float)):\n    print(f\"Expected number, got {type(amount)}\")","type":"text"}],"id":"396a9bcb-0684-4b1c-b745-c8a6c596cf18","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Rule: Pass a tuple of types to check multiple at once: ","type":"text"},{"styles":{"code":true},"text":"isinstance(x, (int, float))","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"9ae03d1b-efe7-4f1d-8f08-6a81b69ef6f3","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"08b3bb59-0d08-4407-8bec-99d4be2b581e","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"3) Range Meter — range checks","type":"text"}],"id":"1c0e3fc1-fe07-4423-bef3-befcbbfe4480","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" Validates that a numeric value falls within an acceptable range. Simple ","type":"text"},{"styles":{"code":true},"text":"if","type":"text"},{"styles":{},"text":" comparisons.","type":"text"}],"id":"2e90b9d3-eb88-4c76-bff6-f135cadd5704","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters in an interview:","type":"text"},{"styles":{},"text":" Out-of-range values (negative amounts, impossible percentages) are a very common data quality issue. Range checks are expected in any validation task.","type":"text"}],"id":"c5a5167a-47ad-464e-a45e-b7b20146a08b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"415d7da5-34d8-4e32-bc6e-32bd4f60d201","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"amount = -50.0\n\nif amount < 0 or amount > 100_000:\n    print(f\"Amount out of valid range: {amount}\")","type":"text"}],"id":"3452fc49-a46e-4701-8e26-e46d54cb7acb","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"abc0f30c-3e1d-4adc-9b17-e542f68dac30","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"4) Format Scanner — ","type":"text"},{"styles":{"code":true},"text":"startswith()","type":"text"},{"styles":{},"text":" / ","type":"text"},{"styles":{"code":true},"text":"re.match()","type":"text"}],"id":"eaebdb4f-477c-4a27-8d1d-3f8cb9c5b4cf","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"}],"id":"37a06b52-22a4-4f28-8268-1b1e781f5de8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"code":true},"text":"startswith()","type":"text"},{"styles":{},"text":" — simple prefix check for strings.","type":"text"}],"id":"f22b3cf7-0695-4bb2-b822-0260cd0ebb40","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"code":true},"text":"re.match()","type":"text"},{"styles":{},"text":" — pattern check using a regular expression.","type":"text"}],"id":"70330451-fa16-4a9f-a2a2-b313860dd12a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters in an interview:","type":"text"},{"styles":{},"text":" String format validation (IDs, codes, dates) is a basic expectation. Use ","type":"text"},{"styles":{"code":true},"text":"startswith()","type":"text"},{"styles":{},"text":" for simple checks and ","type":"text"},{"styles":{"code":true},"text":"re.match()","type":"text"},{"styles":{},"text":" when a pattern is needed.","type":"text"}],"id":"f6a9878d-fbc6-4495-8cf2-c1e07ca273ad","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"4ecc2331-e4b2-40a4-b173-ba046f9ae636","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"import re\n\norder_id = \"ORD-12345\"\n\n# Simple prefix check\nif not order_id.startswith(\"ORD-\"):\n    print(\"Invalid order ID prefix\")\n\n# Pattern check: ORD- followed by exactly 5 digits\nif not re.match(r\"^ORD-\\d{5}$\", order_id):\n    print(\"Invalid order ID format\")","type":"text"}],"id":"ea1be4c2-d89f-4ac4-ad13-e503f53c9ecb","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Rule: Use ","type":"text"},{"styles":{"code":true},"text":"re.match()","type":"text"},{"styles":{},"text":" only when ","type":"text"},{"styles":{"code":true},"text":"startswith()","type":"text"},{"styles":{},"text":" is not specific enough. Keep regex simple.","type":"text"}],"id":"1546f73e-4a1f-49b9-b8e4-6ad8c483a2c1","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"d8cc2be5-ecac-4c13-9c3c-331e113f5c5f","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"5) Reject Bin — skip invalid rows and record reason","type":"text"}],"id":"f0f138ae-ce7f-4751-bbb5-03545cf6c394","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" When a row fails any check, skip it for processing, record why it failed, and move on. Never crash the whole job on one bad row.","type":"text"}],"id":"634d16a3-666b-4a08-a5d6-f10e4960a41c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters in an interview:","type":"text"},{"styles":{},"text":" This is the real-world validation pattern. Interviewers expect you to separate valid and invalid rows, not stop the pipeline.","type":"text"}],"id":"72c8143b-92e2-43cb-bed6-ef1df117850d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"e59da742-c098-483a-acd8-01ae4b30f61b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"rejected_rows = []\n\nfor row in rows:\n    if pd.isna(row.get(\"amount\")):\n        rejected_rows.append({**row, \"reason\": \"null amount\"})\n        continue\n\n    # more checks...\n\n    valid_rows.append(row)","type":"text"}],"id":"59a310c1-395a-4c4f-83af-57a6cf999272","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"ce1bab3c-674e-4e30-8496-3eb2fda26912","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"6) Count Board — valid/invalid summary","type":"text"}],"id":"cd10f8e5-47b4-4093-ad52-435f0222856a","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" A simple count of how many rows passed and how many failed. Printed at the end of the job.","type":"text"}],"id":"43b1b285-57c4-469c-b592-cffcdf67fc50","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters in an interview:","type":"text"},{"styles":{},"text":" Any pipeline should report what happened. A summary count is the minimum expected output for a validation job.","type":"text"}],"id":"473149fe-986a-48a9-85c4-f691991f9214","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"ca5fa9cd-1a84-4f3a-bed9-33e463fec9cd","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"print(f\"Valid rows  : {valid_count}\")\nprint(f\"Invalid rows: {invalid_count}\")\nprint(f\"Total rows  : {valid_count + invalid_count}\")","type":"text"}],"id":"9e4fe42a-22f4-4cd1-8dfe-3145127864d9","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"4b3ef539-2662-42c9-b759-25f03bc7f7ac","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"7) Dead Letter Tray — rejected rows CSV","type":"text"}],"id":"c139c56c-1715-4b7e-b186-98b79e03f96d","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" Writing all rejected rows (with their failure reason) to a separate CSV file for review.","type":"text"}],"id":"3fa45483-5226-45ab-bb6d-1ea23df66300","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters in an interview:","type":"text"},{"styles":{},"text":" Silently dropping bad rows is poor practice. A dead letter file lets data owners investigate and fix source data. This shows real DE awareness.","type":"text"}],"id":"6fc970cd-4fa6-44eb-9b33-4df3d35cadc8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"b13c25dc-efc5-463a-9f4f-bae0ea6a54c2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"import csv\n\nwith open(\"rejected.csv\", \"w\", newline=\"\", encoding=\"utf-8\") as f:\n    if rejected_rows:\n        writer = csv.DictWriter(f, fieldnames=rejected_rows[0].keys())\n        writer.writeheader()\n        writer.writerows(rejected_rows)","type":"text"}],"id":"708c61a0-3beb-4a05-b17e-eb49dd2e6bde","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"00ddbb0c-024f-498e-a928-48386bb4e9af","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Common mistakes","type":"text"}],"id":"416a14ed-ab61-479c-a7e7-082671fe2e7a","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Mistake","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Fix","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Using ","type":"text"},{"styles":{"code":true},"text":"== None","type":"text"},{"styles":{},"text":" instead of ","type":"text"},{"styles":{"code":true},"text":"is None","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Use ","type":"text"},{"styles":{"code":true},"text":"is None","type":"text"},{"styles":{},"text":" for Python objects, ","type":"text"},{"styles":{"code":true},"text":"pd.isna()","type":"text"},{"styles":{},"text":" for pandas","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Using ","type":"text"},{"styles":{"code":true},"text":"== np.nan","type":"text"},{"styles":{},"text":" to check for NaN","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"code":true},"text":"NaN != NaN","type":"text"},{"styles":{},"text":" — always use ","type":"text"},{"styles":{"code":true},"text":"pd.isna()","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Crashing the pipeline on one bad row","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Wrap checks in ","type":"text"},{"styles":{"code":true},"text":"if","type":"text"},{"styles":{},"text":" blocks, skip bad rows with ","type":"text"},{"styles":{"code":true},"text":"continue","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Not recording why a row was rejected","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Always append a ","type":"text"},{"styles":{"code":true},"text":"\"reason\"","type":"text"},{"styles":{},"text":" field to rejected rows","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Forgetting the Count Board summary","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Always print valid/invalid counts at the end","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Not writing rejected rows anywhere","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Always produce a dead letter CSV","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Overcomplicating regex when ","type":"text"},{"styles":{"code":true},"text":"startswith()","type":"text"},{"styles":{},"text":" is enough","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Use the simplest tool that works","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"8dfab97d-ac9c-440c-b870-6ebacd23d8db","props":{"textColor":"default"},"type":"table"},{"children":[],"id":"c2a40163-a116-429a-8ce0-4c91fbea4e9e","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Practice ideas","type":"text"}],"id":"34531507-1031-4b31-a518-da060ff67443","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Write a null check using both ","type":"text"},{"styles":{"code":true},"text":"is None","type":"text"},{"styles":{},"text":" and ","type":"text"},{"styles":{"code":true},"text":"pd.isna()","type":"text"},{"styles":{},"text":" on the same value.","type":"text"}],"id":"10bf42d1-3d7d-4002-9d7c-69821d20ff0a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Write an ","type":"text"},{"styles":{"code":true},"text":"isinstance()","type":"text"},{"styles":{},"text":" check that accepts both ","type":"text"},{"styles":{"code":true},"text":"int","type":"text"},{"styles":{},"text":" and ","type":"text"},{"styles":{"code":true},"text":"float","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"176fad17-2c6c-4901-9840-6e9baad133d7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Write a range check that rejects amounts below 0 or above 10,000.","type":"text"}],"id":"b20c8b1b-f5e4-4589-9788-0221504aacbc","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Write a format check using ","type":"text"},{"styles":{"code":true},"text":"startswith()","type":"text"},{"styles":{},"text":" for an ","type":"text"},{"styles":{"code":true},"text":"\"ORD-\"","type":"text"},{"styles":{},"text":" prefix.","type":"text"}],"id":"63709910-44ac-4cfa-b271-4f2b4990b841","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Write the same check using ","type":"text"},{"styles":{"code":true},"text":"re.match()","type":"text"},{"styles":{},"text":" with a 5-digit suffix pattern.","type":"text"}],"id":"8711c34c-479b-497b-8b1e-4ffb1e738b81","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Build a loop that runs all four checks on each row, collects rejected rows with reasons, and counts valid versus invalid.","type":"text"}],"id":"d4b96138-86aa-4ccf-af3d-42c90b6a3050","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Write the rejected rows to ","type":"text"},{"styles":{"code":true},"text":"rejected.csv","type":"text"},{"styles":{},"text":" using ","type":"text"},{"styles":{"code":true},"text":"csv.DictWriter","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"4a070b25-107e-4a68-9d51-7f4add098c1b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"id":"afbb27f0-adf5-4aa4-ab33-b885d10d335c","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Final integrated coding example","type":"text"}],"id":"517d56f4-54fc-439c-9bfc-6cf26209eda2","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Scenario:","type":"text"},{"styles":{},"text":" A list of order rows arrives at the Quality Check Point. Each row must pass four checks: non-null amount, numeric type, valid range, and correct ID format. Valid rows are kept. Invalid rows go to the dead letter tray.","type":"text"}],"id":"96b0e398-e5bd-4cc6-a359-3913026b37e7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"import csv\nimport re\nimport pandas as pd\n\n# --- Incoming rows ---\nrows = [\n    {\"order_id\": \"ORD-00001\", \"amount\": 250.0},\n    {\"order_id\": \"ORD-00002\", \"amount\": None},          # null — Missing Tag\n    {\"order_id\": \"ORD-00003\", \"amount\": \"bad\"},          # wrong type — Wrong Size\n    {\"order_id\": \"ORD-00004\", \"amount\": -10.0},          # out of range — Range Meter\n    {\"order_id\": \"INVALID-5\", \"amount\": 180.0},          # bad format — Format Scanner\n    {\"order_id\": \"ORD-00006\", \"amount\": 99.5},\n]\n\nvalid_rows    = []\nrejected_rows = []\n\nfor row in rows:\n    order_id = row.get(\"order_id\")\n    amount   = row.get(\"amount\")\n\n    # --- Missing Tag Sign: null check ---\n    if pd.isna(amount) or amount is None:\n        rejected_rows.append({**row, \"reason\": \"null amount\"})\n        continue\n\n    # --- Wrong Size Gauge: type check ---\n    if not isinstance(amount, (int, float)):\n        rejected_rows.append({**row, \"reason\": f\"invalid type: {type(amount).__name__}\"})\n        continue\n\n    # --- Range Meter: range check ---\n    if amount < 0 or amount > 100_000:\n        rejected_rows.append({**row, \"reason\": f\"amount out of range: {amount}\"})\n        continue\n\n    # --- Format Scanner: string format check ---\n    if not re.match(r\"^ORD-\\d{5}$\", str(order_id)):\n        rejected_rows.append({**row, \"reason\": f\"invalid order_id format: {order_id}\"})\n        continue\n\n    # --- Passed all checks ---\n    valid_rows.append(row)\n\n# --- Count Board: summary ---\nvalid_count   = len(valid_rows)\ninvalid_count = len(rejected_rows)\n\nprint(f\"Valid rows  : {valid_count}\")\nprint(f\"Invalid rows: {invalid_count}\")\nprint(f\"Total rows  : {valid_count + invalid_count}\")\n\n# --- Dead Letter Tray: write rejected rows to CSV ---\nif rejected_rows:\n    with open(\"rejected.csv\", \"w\", newline=\"\", encoding=\"utf-8\") as f:\n        writer = csv.DictWriter(f, fieldnames=rejected_rows[0].keys())\n        writer.writeheader()\n        writer.writerows(rejected_rows)\n    print(f\"Rejected rows written to rejected.csv\")","type":"text"}],"id":"14d4d225-7d75-4cfa-aad3-bf1823d735e8","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Sample output:","type":"text"}],"id":"9b17cdf3-574e-4360-a122-3c975fe37d53","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Valid rows  : 2\nInvalid rows: 4\nTotal rows  : 6\nRejected rows written to rejected.csv","type":"text"}],"id":"16d90e6d-3b0a-4fbe-af37-ba53f8fe97d3","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"code":true},"text":"rejected.csv","type":"text"},{"styles":{"bold":true},"text":" contents:","type":"text"}],"id":"2bab0789-fd9e-4237-8928-62acdbd6592e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"order_id,amount,reason\nORD-00002,,null amount\nORD-00003,bad,invalid type: str\nORD-00004,-10.0,amount out of range: -10.0\nINVALID-5,180.0,invalid order_id format: INVALID-5","type":"text"}],"id":"c9f982c7-5170-4da3-ab61-d2f46ef9984d","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"What each section maps to:","type":"text"}],"id":"c55332d5-7e7d-4749-a670-969239dbac60","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Code section","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Metaphor part","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"pd.isna(amount) or amount is None","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Missing Tag Sign","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"isinstance(amount, (int, float))","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Wrong Size Gauge","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"amount < 0 or amount > 100_000","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Range Meter","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"re.match(r\"^ORD-\\d{5}$\", order_id)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Format Scanner","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"rejected_rows.append({**row, \"reason\": ...})","type":"text"},{"styles":{},"text":" + ","type":"text"},{"styles":{"code":true},"text":"continue","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Reject Bin","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"valid_count","type":"text"},{"styles":{},"text":" / ","type":"text"},{"styles":{"code":true},"text":"invalid_count","type":"text"},{"styles":{},"text":" print","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Count Board","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"csv.DictWriter","type":"text"},{"styles":{},"text":" → ","type":"text"},{"styles":{"code":true},"text":"rejected.csv","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Dead Letter Tray","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"cfd83b8f-a90c-45d4-9f5d-90946b6801db","props":{"textColor":"default"},"type":"table"},{"children":[],"id":"5670efc1-6da3-4a0e-939d-c5a825b6cf5c","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"italic":true},"text":"If you can write this script from memory — especially the four check types, the reason field on rejected rows, and the dead letter CSV — you are ready for internship-level data validation questions at the Quality Check Point.","type":"text"}],"id":"2a6cced7-96bb-4435-9dea-96cf3848ba7e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[],"id":"0d70c9d8-7db4-4982-87a0-685b03d6b25f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"}]'::jsonb, '3e9e3dd3-a59b-4b02-968a-ee95e7317583') ON CONFLICT ("node_id") DO UPDATE SET "bad_example" = EXCLUDED."bad_example", "completed_at" = EXCLUDED."completed_at", "created_at" = EXCLUDED."created_at", "definition" = EXCLUDED."definition", "good_example" = EXCLUDED."good_example", "is_completed" = EXCLUDED."is_completed", "key_points" = EXCLUDED."key_points", "last_edited" = EXCLUDED."last_edited", "map_id" = EXCLUDED."map_id", "ment