INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-05-26T07:52:16.949164+00:00', '', '', 'cbad0c81-0971-4126-8588-aeb742a24750', false, '[]'::jsonb, '2026-05-27T06:29:24.653+00:00', 'f22b10db-248b-447f-80b6-4a27bd9171ed', '', '4df6b326-9b1a-46e4-8f29-a335a39a4982', '', '[]'::jsonb, '[{"children":[],"content":[{"styles":{"bold":true},"text":"Step 1: Grasping Data Engineering Fundamentals","type":"text"}],"id":"abd2d029-6d23-487d-a293-a04d8284fc28","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":1,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"id":"6baf5c60-eb5a-43d7-8f38-6d0789623f49","props":{"backgroundColor":"default","caption":"","name":"image.png","showPreview":true,"textAlignment":"left","url":"https://ixmvqmfesibpnrjmvzuj.supabase.co/storage/v1/object/public/study-assets/3e9e3dd3-a59b-4b02-968a-ee95e7317583/4df6b326-9b1a-46e4-8f29-a335a39a4982/1779863362331-kd8athfske.png"},"type":"image"},{"children":[],"content":[{"styles":{"bold":true},"text":"The Data Engineering Lifecycle","type":"text"}],"id":"b6ac6f0a-673e-45cb-aa4f-126d9a982432","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The Data Engineering Lifecycle is the ","type":"text"},{"styles":{"bold":true},"text":"foundational, step-by-step framework","type":"text"},{"styles":{},"text":" that guides how data moves from its point of creation to its final point of business value. Mastering this lifecycle makes you ","type":"text"},{"styles":{"bold":true},"text":"tool-agnostic","type":"text"},{"styles":{},"text":" — once you understand the fundamental steps, you can swap any software or cloud platform and still build the pipeline.","type":"text"}],"id":"647af149-1b47-4b15-8fce-b47bed8a9b0a","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"id":"8b89084a-40c3-472f-9c4e-9091fbe4d91f","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"🏙️ Mental Model — The Water Purification Plant","type":"text"}],"id":"78f11630-819a-4561-a72e-b1f6c1160092","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{"bold":true},"text":"Lifecycle Stage","type":"text"}],"props":{"backgroundColor":"rgba(214, 213, 212, 0.035)","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"Water Plant Analogy","type":"text"}],"props":{"backgroundColor":"rgba(214, 213, 212, 0.035)","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Generation","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Raw water from rainfall, rivers, underground wells","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Ingestion","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Automated pumps & pipes capturing the water","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Storage","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Massive raw reservoir holding collected water","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Transformation","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Chemical treatment plant — removes impurities, adds minerals","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Serving","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Clean, drinkable water delivered to homes & factories","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Undercurrents","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Security guards, facility blueprints, maintenance teams & management","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"20a85ef1-3b18-48