INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-08-04T05:51:25.172242+00:00', '', '', 'cda0f581-9154-4dbf-8971-417dbfdd9ac8', false, '[]'::jsonb, '2026-08-04T05:52:06.841+00:00', '2ad473fe-77dd-481e-8ba7-4b2b0336173f', '', '66cc06ff-827f-4a22-bb3d-3ed0e53aa227', '', '[]'::jsonb, '[{"children":[],"content":[],"id":"02417544-9e1b-4447-b8db-004a16fb728b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Non-Correlated Subquery  VS   Correlated Subquery","type":"text"}],"id":"5def7786-1e22-451a-a035-f42e07744782","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"This is one of the most fundamental concepts tested in SQL interviews! Let''s break down the core difference clearly, and then look at an example of each using your database tables (","type":"text"},{"styles":{"code":true},"text":"customers","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"accounts","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"transactions","type":"text"},{"styles":{},"text":").","type":"text"}],"id":"b01ccab7-8163-4b5a-ad7a-8f3f07603946","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"cf9c6ffd-8d43-4448-8841-22f5c267122d","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"The Core Difference","type":"text"}],"id":"b3ffc747-3e0b-4e1f-9b4a-faa56c59bdbe","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":{"columnWidths":[null,null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Feature","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Non-Correlated Subquery","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Correlated Subquery","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Dependency","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Completely ","type":"text"},{"styles":{"bold":true},"text":"independent","type":"text"},{"styles":{},"text":" of the outer query.","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"Dependent","type":"text"},{"styles":{},"text":" on the outer query (references a column from the outer table).","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Execution","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Runs ","type":"text"},{"styles":{"bold":true},"text":"once total","type":"text"},{"styles":{},"text":", before the outer query runs.","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Runs ","type":"text"},{"styles":{"bold":true},"text":"repeatedly—once for every row","type":"text"},{"styles":{},"text":" evaluated by the outer query.","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Analogy","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Looking up a single fixed number on a calculator before solving a problem.","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Checking an individual item against a list line-by-line in a loop.","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"0d93805f-043f-4bc1-a5dd-89315382c79b","props":{"textColor":"default"},"type":"table"},{"children":[],"id":"cfc28fe0-4ca4-4c9f-ac3a-4ef6099b5a2c","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"1. Non-Correlated Subquery (Independent)","type":"text"}],"id":"5abc6878-34a1-47e7-ae71-894f774b3bba","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"A ","type":"text"},{"styles":{"bold":true},"text":"non-correlated subquery","type":"text"},{"styles":{},"text":" does not rely on any columns from the outer query. The database engine executes the inner query ","type":"text"},{"styles":{"bold":true},"text":"just once","type":"text"},{"styles":{},"text":", gets the result (a single value or a static list), and passes that result to the outer query.","type":"text"}],"id":"ad88c327-66b6-4579-9881-cc39264bcc85","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Example:","type":"text"}],"id":"c0563899-4c6b-4aaa-9860-3bea07874ef8","props":{"backgroundColor":"default","isToggleable":false,"level":4,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"italic":true},"text":"Goal: Find all transactions where the transaction amount is greater than the average of ALL transactions.","type":"text"}],"id":"3aea5b25-d32e-45c2-97e2-071855a25bac","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"SELECT \n    txn_id, \n    amount \nFROM transactions \nWHERE amount > (\n    -- Inner query runs ONCE first (calculates e.g., 108,000)\n    SELECT AVG(amount) \n    FROM transactions\n);\n","type":"text"}],"id":"bc7cf608-a3c0-4879-9e10-799a2942181d","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"How it works:","type":"text"}],"id":"d3e93bc4-91c2-4fec-afa1-d19c2fa364dd","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"The subquery runs ","type":"text"},{"styles":{"bold":true},"text":"once","type":"text"},{"styles":{},"text":" to calculate ","type":"text"},{"styles":{"code":true},"text":"AVG(amount)","type":"text"},{"styles":{},"text":" across the entire table (e.g., ","type":"text"},{"styles":{"code":true},"text":"108000","type":"text"},{"styles":{},"text":").","type":"text"}],"id":"cc6455df-f23b-43fb-94b7-4ce40542b5cc","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"The outer query becomes: ","type":"text"},{"styles":{"code":true},"text":"SELECT txn_id, amount FROM transactions WHERE amount > 108000;","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"764762a9-237d-439b-bc6f-6cfbb5973ee0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"id":"fa138906-0ff9-4eff-ac9b-182fde5b6a8e","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"2. Correlated Subquery (Dependent / Row-by-Row)","type":"text"}],"id":"c159423d-e1d4-4e61-b8b2-b67319a658fa","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"A ","type":"text"},{"styles":{"bold":true},"text":"correlated subquery","type":"text"},{"styles":{},"text":" references a column from the outer query table inside its ","type":"text"},{"styles":{"code":true},"text":"WHERE","type":"text"},{"styles":{},"text":" clause. Because of this outer reference, it ","type":"text"},{"styles":{"bold":true},"text":"cannot run independently","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"31f0ab4b-d9a8-4f53-b347-46b816aeef85","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"The database engine must re-run the subquery ","type":"text"},{"styles":{"bold":true},"text":"for every single row","type":"text"},{"styles":{},"text":" processed by the outer query!","type":"text"}],"id":"3c33ca01-99a8-4536-8192-b516e8bae613","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Example:","type":"text"}],"id":"cc2f8050-b218-4618-ad51-9e8720f421c0","props":{"backgroundColor":"default","isToggleable":false,"level":4,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"italic":true},"text":"Goal: Find customers who have at least one transaction over Rs. 100,000.","type":"text"}],"id":"4228ac3d-9649-4f33-a06e-e42661bd03d6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"SELECT c.name \nFROM customers AS c\nWHERE EXISTS (\n    -- Subquery references outer table column ''c.customer_id''\n    SELECT 1 \n    FROM accounts AS a\n    INNER JOIN transactions AS t USING (account_id)\n    WHERE a.customer_id = c.customer_id  -- <--- CORRELATION LINK\n      AND t.amount > 100000\n);\n","type":"text"}],"id":"bdc2c604-db20-4983-a217-5b13c403100e","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"How it works:","type":"text"}],"id":"0bffdeb5-bd6d-433a-b8c9-3bf7b3efcfb6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"The outer query grabs Customer 1 (","type":"text"},{"styles":{"code":true},"text":"C1","type":"text"},{"styles":{},"text":" — Kasun Perera).","type":"text"}],"id":"e0effa95-f1d8-4f51-a889-679906a2375b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"The subquery runs using ","type":"text"},{"styles":{"code":true},"text":"c.customer_id = ''C1''","type":"text"},{"styles":{},"text":" to check if Kasun has a transaction $> 100000$. (Returns ","type":"text"},{"styles":{"code":true},"text":"FALSE","type":"text"},{"styles":{},"text":").","type":"text"}],"id":"5ddf8ab8-6f28-4cae-a3b5-8e5d8a45c676","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"The outer query grabs Customer 2 (","type":"text"},{"styles":{"code":true},"text":"C2","type":"text"},{"styles":{},"text":" — Nimali Silva).","type":"text"}],"id":"651b6659-4570-42d1-86a4-704942286cb8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"The subquery runs using ","type":"text"},{"styles":{"code":true},"text":"c.customer_id = ''C2''","type":"text"},{"styles":{},"text":" to check if Nimali has a transaction $> 100000$. (Returns ","type":"text"},{"styles":{"code":true},"text":"TRUE","type":"text"},{"styles":{},"text":").","type":"text"}],"id":"65a3ccbc-cf32-4d8a-8dd5-de697a73e823","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"This repeats for ","type":"text"},{"styles":{"bold":true},"text":"every row","type":"text"},{"styles":{},"text":" in the outer ","type":"text"},{"styles":{"code":true},"text":"customers","type":"text"},{"styles":{},"text":" table.","type":"text"}],"id":"75870ddc-3abf-4964-89d4-5db24f0873f7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"id":"6e4c81d3-edc9-483f-af70-98956b2dae18","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Key Interview Summary Script 🎙️","type":"text"}],"id":"f91b646a-888b-4d52-aea4-6d0316341ef7","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"A ","type":"text"},{"styles":{"bold":true,"italic":true},"text":"non-correlated subquery","type":"text"},{"styles":{"italic":true},"text":" is independent of the outer query. It runs only once to produce a static scalar value or list, which the outer query then uses.","type":"text"},{"styles":{},"text":" ","type":"text"},{"styles":{"italic":true},"text":"A ","type":"text"},{"styles":{"bold":true,"italic":true},"text":"correlated subquery","type":"text"},{"styles":{"italic":true},"text":" depends directly on a column from the outer table. It must re-execute row-by-row for every candidate row evaluated by the outer query, making it function like a ","type":"text"},{"styles":{"code":true},"text":"FOR EACH","type":"text"},{"styles":{"italic":true},"text":" loop.\"","type":"text"}],"id":"a03d846b-b456-4e53-9129-c479bdb41599","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[],"id":"40193928-8fc5-4012-9ef7-e42005838b5b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"}]'::jsonb, '3e9e3dd3-a59b-4b02-968a-ee95e7317583') ON CONFLICT ("node_id") DO UPDATE SET "bad_example" = EXCLUDED."bad_example", "completed_at" = EXCLUDED."completed_at", "created_at" = EXCLUDED."created_at", "definition" = EXCLUDED."definition", "good_example" = EXCLUDED."good_example", "is_completed" = EXCLUDED."is_completed", "key_points" = EXCLUDED."key_points", "last_edited" = EXCLUDED."last_edited", "map_id" = EXCLUDED."map_id", "mental_model" = EXCLUDED."mental_model", "notes" = EXCLUDED."notes", "resources" = EXCLUDED."resources", "rich_content" = EXCLUDED."rich_content", "user_id" = EXCLUDED."user_id";
INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-09-10T13:59:41.683934+00:00', '', '', '99d38213-5497-4496-b489-28fb271a655e', false, '[]'::jsonb, '2026-09-10T14:05:39.728+00:00', 'ecc1046a-b3c9-4728-8417-64672cae5789', '', '2cefabde-40ec-4dee-aa33-6a832d55ba83', '', '[]'::jsonb, '[{"children":[],"content":[{"styles":{},"text":"Here is the exact step-by-step breakdown of Phase 1 (Product Discovery & Market Alignment), extracted strictly from the methodology in the transcript and framed through the lens of a Forward Deployed Engineer (FDE).","type":"text"}],"id":"a1ff5a01-908c-4c6a-8b25-33d064d0e6ab","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"An FDE doesn’t just take tickets and write code; they sit between the business problem and the technical execution. Directors and venture studios want to see that before you touch an AI coding agent, you deeply understand the operational friction you are trying to eliminate.","type":"text"}],"id":"cd1fe558-277f-440a-93de-a85fe73e9ee1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Here is the general framework and the exact narration you can mimic. You can later feed this template into Anti-Gravity to fill in the blanks with your specific project details.","type":"text"}],"id":"0865c5f6-11bb-4019-b3ed-4dedeb2fed8c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"44d3c02d-9231-4fc7-a510-63169529cdc1","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"The FDE Mindset: Phase 1 (Product Discovery & Market Alignment)","type":"text"}],"id":"a13586db-5e37-42db-ade3-9d79b88ea6e2","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Based on the transcript, this phase is all about the \"conversations to have before you build.\" It is the externalization of architectural thinking where you pressure-test your ideas using a planning AI (like ChatGPT or Claude) to figure out what the system is before writing the first spec.","type":"text"}],"id":"896729d9-3064-4a8f-80f2-90fb46ef5103","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"The Core Steps:","type":"text"}],"id":"c9487416-3c61-4999-99f2-381df60ea352","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Defining the Business Problem & Pain Points:","type":"text"},{"styles":{},"text":" What is the actual operational friction? FDEs look for what people are currently doing manually or inefficiently.","type":"text"}],"id":"6cc2636d-fef9-45f0-8e39-bd1360807fb5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"User Profiling & Core Flows:","type":"text"},{"styles":{},"text":" Who uses this, and what is the absolute shortest path to deliver value to them? (e.g., from sign-in to the final output).","type":"text"}],"id":"8f356796-3c17-474f-96d2-56e28fce3675","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Market & Implementation Research:","type":"text"},{"styles":{},"text":" How is this currently being solved? What tools are people duct-taping together, and where do those tools fail?","type":"text"}],"id":"8461153c-ab8f-42a2-b083-805bd427e5a7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Ruthless Scoping (In-Scope vs. Out-of-Scope):","type":"text"},{"styles":{},"text":" FDEs must deliver rapid, reliable value. That means aggressively defining what ","type":"text"},{"styles":{"italic":true},"text":"not","type":"text"},{"styles":{},"text":" to build so the AI agent stays disciplined and doesn''t hallucinate unnecessary features.","type":"text"}],"id":"a890300c-07bf-4a84-b53f-617270a75c09","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"id":"3bb65801-b38a-41eb-9fd9-3b136eab1f7b","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"The Narration Template (FDE Persona)","type":"text"}],"id":"56216b1d-3aa5-47ed-b52f-eb567679d493","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Use this script as your structural template. The bracketed sections ","type":"text"},{"styles":{"code":true},"text":"[...]","type":"text"},{"styles":{},"text":" are where you will eventually inject your project details.","type":"text"}],"id":"58fef31a-f098-43eb-ba39-085e80d59adb","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"The Opening (Setting the FDE Frame)","type":"text"}],"id":"4f2f9d15-61e3-429f-adbc-2da5dc5fe04c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"In a venture studio environment, my job isn''t to just open Cursor and start vibe-coding. My job is to act as the bridge between a business problem and a technical solution. So, before I ever initialize a codebase, I start with product discovery. I sit down with a planning AI to pressure-test the core logic. I need to answer: What are we actually building, who is it for, and what could go wrong?\"","type":"text"}],"id":"d49f1054-3335-4ac3-88ca-0f11a829e7f7","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"bold":true},"text":"Step 1: The Business Problem & Pain Points","type":"text"}],"id":"7675b9f0-bf46-4f6d-b2cb-a671acc9589d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"I always start by defining the operational friction. The current market has a clear pain point: ","type":"text"},{"styles":{"bold":true,"italic":true},"text":"[Describe the painful, manual, or slow process users currently face]","type":"text"},{"styles":{"italic":true},"text":". The problem isn''t that tools don''t exist; it''s that ","type":"text"},{"styles":{"bold":true,"italic":true},"text":"[Explain why current solutions fail—e.g., they require too much manual labor, lack real-time syncing, etc.]","type":"text"},{"styles":{"italic":true},"text":".\"","type":"text"}],"id":"15b80fb7-0011-4315-a33d-ff5d8861cdbb","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"bold":true},"text":"Step 2: The Solution & Core User Flow","type":"text"}],"id":"cba1c145-6579-4cca-ba6a-3494af630e68","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"Once the pain point was clear, I defined the exact solution and the core user flow. As an FDE, I want the shortest path to value. The flow is strictly defined: ","type":"text"},{"styles":{"bold":true,"italic":true},"text":"[Describe the sequence: e.g., A user authenticates -> enters a workspace -> inputs plain English -> the system outputs a specific deliverable]","type":"text"},{"styles":{"italic":true},"text":". By defining this sequence explicitly, I ensure the AI coding agent won''t later try to build a core feature on the wrong page.\"","type":"text"}],"id":"49d12d30-4021-4138-a6c4-b2e38b4da929","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"bold":true},"text":"Step 3: Implementation Research","type":"text"}],"id":"d5122a28-a820-4a91-a3f9-32c01a261ebd","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"I evaluated the current market to see how incumbents approach this. You have ","type":"text"},{"styles":{"bold":true,"italic":true},"text":"[Competitor A]","type":"text"},{"styles":{"italic":true},"text":", which does ","type":"text"},{"styles":{"bold":true,"italic":true},"text":"[Feature]","type":"text"},{"styles":{"italic":true},"text":" well but completely misses ","type":"text"},{"styles":{"bold":true,"italic":true},"text":"[Gap in the market]","type":"text"},{"styles":{"italic":true},"text":". Then you have ","type":"text"},{"styles":{"bold":true,"italic":true},"text":"[Competitor B]","type":"text"},{"styles":{"italic":true},"text":", which is too rigid. The implementation opportunity here was to build a system that leverages ","type":"text"},{"styles":{"bold":true,"italic":true},"text":"[Specific Tech, e.g., Agentic AI, Real-time WebSockets]","type":"text"},{"styles":{"italic":true},"text":" to automate the heavy lifting while keeping the user in the architect seat.\"","type":"text"}],"id":"e0b35db2-ea32-4448-a100-0c44f55106e7","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"bold":true},"text":"Step 4: Setting MVP Guardrails (The ''Out-of-Scope'' Rule)","type":"text"}],"id":"b72df62e-ce53-4529-bad2-5b3ed51b95e5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"The most critical part of my discovery phase was deciding what NOT to build. If you give an AI an open-ended prompt, the codebase will eventually collapse under its own weight. I explicitly defined the boundaries: ","type":"text"},{"styles":{"bold":true,"italic":true},"text":"[List 3-4 complex features like Enterprise Billing, Role-Based Permissions, or Version History]","type":"text"},{"styles":{"italic":true},"text":" were deliberately marked as OUT OF SCOPE. My success criteria was simply: ","type":"text"},{"styles":{"bold":true,"italic":true},"text":"[State the one binary metric of success for the core feature]","type":"text"},{"styles":{"italic":true},"text":".\"","type":"text"}],"id":"99855342-16da-40be-8e52-8ba88728df0d","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"cae5379e-4d90-4ea8-8a16-875a54a96b57","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Here is the breakdown of ","type":"text"},{"styles":{"bold":true},"text":"Phase 2 (Architectural Planning & The 6-File Context System)","type":"text"},{"styles":{},"text":", extracted directly from the transcript and framed for the Forward Deployed Engineer (FDE) persona.","type":"text"}],"id":"d074cd05-0d4a-4a97-ac00-748cf04fa61e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"An FDE knows that the biggest risk with AI-assisted development is \"context drift.\" If you just ask an AI to build a project, it might do great for two hours, but by week three, it forgets previous decisions, contradicts its own codebase, and breaks features. To prevent this, an FDE establishes strict, immutable constraints ","type":"text"},{"styles":{"italic":true},"text":"before","type":"text"},{"styles":{},"text":" the AI touches the code.","type":"text"}],"id":"a6c20c56-7c3b-4af9-b935-b048119252a5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"f4c3a657-75d6-48b6-a130-880c854c7f71","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"The FDE Mindset: Phase 2 (Architectural Planning)","type":"text"}],"id":"dc1bd41f-4d7b-44d7-908d-bb61eae1118d","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Based on the transcript, this phase is about building the brain of the project. You take all the product discovery from Phase 1 and translate it into a structured context system (the 6 files). This turns the AI from a \"guesser\" into an implementation engine that understands your exact system architecture.","type":"text"}],"id":"51ab39f6-9a92-4f90-a95b-f40104baae7f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"The Core Steps (The 6 Files):","type":"text"}],"id":"918dc730-7aba-4ee6-989f-51d729d24e0b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Project Overview:","type":"text"},{"styles":{},"text":" A concrete definition of goals, core user flows, and success criteria.","type":"text"}],"id":"28e721a4-2dc2-43d5-bfe1-eeb83ab0a0eb","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Architecture Blueprint (Invariants):","type":"text"},{"styles":{},"text":" The exact tech stack, database schema strategies, and system \"invariants\" (strict rules the system must never violate, like where state is managed or how background tasks run).","type":"text"}],"id":"bbb7d152-70b6-4f43-81d7-7b3a4a0bc8ee","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code Standards:","type":"text"},{"styles":{},"text":" Shared conventions for TypeScript, linting, and framework features to keep the AI''s syntax consistent across hundreds of prompts.","type":"text"}],"id":"6ba9678f-c833-4d11-8eb9-f127d94ce8bd","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"UI Context:","type":"text"},{"styles":{},"text":" Design tokens and color palettes so the UI remains cohesive and the AI doesn''t hallucinate random styling.","type":"text"}],"id":"8cbe1ccb-f34f-4720-b9e9-9246cd11bfe3","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"AI Workflow Rules:","type":"text"},{"styles":{},"text":" Behavioral guardrails for the agent. The golden rule: ","type":"text"},{"styles":{"italic":true},"text":"Focus on one subsystem at a time and stay in your lane.","type":"text"}],"id":"9504d383-e362-41c9-a7c3-f2bf204e1b65","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Progress Tracker:","type":"text"},{"styles":{},"text":" The most critical file. LLMs have no memory between sessions. This living document tracks the current phase, completed work, and architectural decisions made along the way.","type":"text"}],"id":"77cac7bf-d8c5-4ca8-ba56-469b0c52bd18","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"id":"2d12e745-efcf-4539-8aad-73e7758dade7","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"The Narration Template (FDE Persona)","type":"text"}],"id":"6de4811a-584e-453d-bf57-8459a02032c0","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Use this script to explain how you control and command AI tools during the architectural planning phase.","type":"text"}],"id":"f20d5df1-4ef4-429c-a5d1-71e1b3c9700e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"The Opening (Setting the FDE Frame)","type":"text"}],"id":"90208071-d6b7-4e8e-b4ea-735184ea3c7d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"As a Forward Deployed Engineer, my job is to build robust systems rapidly, which means I use AI as an implementation engine. But I know the trap: AI codebases easily collapse under their own weight if they lack architectural boundaries. So, before writing a single prompt, I create a 6-file context system to act as the AI''s ''brain'' for the project.\"","type":"text"}],"id":"1a163e14-380d-4284-a694-b569b8187220","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"bold":true},"text":"Step 1: Establishing the System Rules (Overview & Architecture)","type":"text"}],"id":"83be4115-e855-429a-8c99-9df2a670381e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"I start by defining the boundaries. In the ","type":"text"},{"styles":{"code":true},"text":"project_overview","type":"text"},{"styles":{"italic":true},"text":" and ","type":"text"},{"styles":{"code":true},"text":"architecture","type":"text"},{"styles":{"italic":true},"text":" files, I lock in the tech stack and the system invariants. I explicitly tell the AI how the layers communicate—for instance, how ","type":"text"},{"styles":{"bold":true,"italic":true},"text":"[Authentication Tool]","type":"text"},{"styles":{"italic":true},"text":" talks to the ","type":"text"},{"styles":{"bold":true,"italic":true},"text":"[Database]","type":"text"},{"styles":{"italic":true},"text":". I define hard rules, like: ","type":"text"},{"styles":{"bold":true,"italic":true},"text":"[State an invariant rule, e.g., ''Never run long-lived tasks in standard API routes; always route them to a background job'']","type":"text"},{"styles":{"italic":true},"text":". This stops the AI from guessing my architecture.\"","type":"text"}],"id":"5755d2ea-b413-455e-9f1b-3e96484444c9","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"bold":true},"text":"Step 2: Enforcing Consistency (Standards & UI)","type":"text"}],"id":"11347fac-095a-4e51-ba75-c3b52755376a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"Next, I set the standards. AI tends to drift in its coding style. To prevent this, I feed it a ","type":"text"},{"styles":{"code":true},"text":"code_standards","type":"text"},{"styles":{"italic":true},"text":" and a ","type":"text"},{"styles":{"code":true},"text":"ui_context","type":"text"},{"styles":{"italic":true},"text":" file. This forces the agent to strictly adhere to ","type":"text"},{"styles":{"bold":true,"italic":true},"text":"[Specific Framework Rules, e.g., Next.js 15 App Router conventions]","type":"text"},{"styles":{"italic":true},"text":" and use predefined design tokens instead of hardcoding random hex colors.\"","type":"text"}],"id":"de3c3ad0-4401-4355-a19a-61d60c659e0a","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"bold":true},"text":"Step 3: Managing Agent Behavior (Workflow & Progress Tracking)","type":"text"}],"id":"52b87438-244a-4985-8ae8-b7df8b0193e2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"The final piece is controlling the agent''s behavior over time. I create ","type":"text"},{"styles":{"code":true},"text":"ai_workflow_rules","type":"text"},{"styles":{"italic":true},"text":" which enforce a strict protocol: the AI must only work on one scoped feature at a time. Most importantly, I maintain a dynamic ","type":"text"},{"styles":{"code":true},"text":"progress_tracker","type":"text"},{"styles":{"italic":true},"text":". Because agents lose memory between sessions, my very first prompt every morning is to make the agent read the tracker. It instantly knows what is built, what is in progress, and the architectural decisions we made yesterday. This completely eliminates context drift.\"","type":"text"}],"id":"4011990f-6913-4819-b2ea-00ffa730913b","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"81e8a83c-f6c6-4a93-9389-927b23d4b278","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Here is the breakdown of ","type":"text"},{"styles":{"bold":true},"text":"Phase 3 (Agent Initialization & Spec-Driven Execution)","type":"text"},{"styles":{},"text":", extracted strictly from the transcript and framed for the Forward Deployed Engineer (FDE) persona.","type":"text"}],"id":"8ba51acd-05cc-4d82-96e0-ca47f8cfac1c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"For an FDE, the execution phase is about eliminating variables. You do not want the AI guessing syntax, using deprecated documentation, or touching parts of the codebase it shouldn''t. This phase is about turning the AI into a highly controlled, predictable execution engine through \"Agent Skills\" and isolated \"Feature Specs.\"","type":"text"}],"id":"edc330c6-e987-43c7-94ad-7dfb5714f9da","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"5da841ea-59bf-4eef-ba11-34658742fb2d","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"The FDE Mindset: Phase 3 (Agent Initialization & Execution)","type":"text"}],"id":"498cd7ef-34e9-4fdc-b310-afb3298ce6cd","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Based on the transcript, this phase moves from planning to building. Instead of writing one massive prompt, you break the build into highly scoped, sequential units (e.g., UI first, then database, then API routing, then wiring them together).","type":"text"}],"id":"4c7382d3-c5c5-40ea-883d-7b98f5f3a6e1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"The Core Steps:","type":"text"}],"id":"399115e7-a242-4697-b9f5-cd54290df80d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Agent Initialization & Skill Injection:","type":"text"},{"styles":{},"text":" Creating an entry file (like ","type":"text"},{"styles":{"code":true},"text":"agents.md","type":"text"},{"styles":{},"text":" or ","type":"text"},{"styles":{"code":true},"text":".cursorrules","type":"text"},{"styles":{},"text":") at the root so the agent automatically reads your 6-file context. Crucially, installing \"Agent Skills\" via CLI to give the AI the latest documentation and best practices for specific frameworks.","type":"text"}],"id":"56b52698-eb14-4ba2-a323-1608b90f155d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Feature Scoping (The Unit Spec):","type":"text"},{"styles":{},"text":" Writing a dedicated markdown file for ","type":"text"},{"styles":{"italic":true},"text":"one","type":"text"},{"styles":{},"text":" feature at a time (e.g., ","type":"text"},{"styles":{"code":true},"text":"03_auth.md","type":"text"},{"styles":{},"text":"). Every spec contains a Goal, Design Decisions, Implementation Details, and a Verification Checklist.","type":"text"}],"id":"c85b534c-03b4-45f4-87a7-a2f449af1113","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"The Execution Protocol:","type":"text"},{"styles":{},"text":" Using a strict, repeatable prompt to trigger the build: ","type":"text"},{"styles":{"italic":true},"text":"\"Read this spec, update the progress tracker, and implement exactly as specified.\"","type":"text"}],"id":"5536d990-9d3c-4554-9306-e351504005fc","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Quality Assurance & Code Review:","type":"text"},{"styles":{},"text":" Treating AI output like a junior developer''s pull request. Reviewing the code (or using tools like CodeRabbit), isolating bugs, and running corrective prompts before merging to the main branch.","type":"text"}],"id":"ed165ef7-57d0-4ffd-bf00-cec6fe12c9f2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"id":"cfe3d0b6-3db1-44ed-9d9e-b5bb0417be9a","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"The Narration Template (FDE Persona)","type":"text"}],"id":"9fcf6519-5cd7-44f7-a40e-c2714a191b8c","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Use this script to explain how you drive the AI to execute complex features without breaking the system.","type":"text"}],"id":"1861d609-bdd4-4836-b8e1-7ce36b6d9b05","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"The Opening (Setting the FDE Frame)","type":"text"}],"id":"3a1936b8-0d26-4266-9f5e-5d87acbacc71","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"As a Forward Deployed Engineer, execution is about predictability. I don''t let the AI ''vibe code'' its way through a project. I treat the AI as an execution engine that requires explicit, isolated instructions. My execution phase is strictly spec-driven, ensuring every feature lands exactly within the architectural boundaries I set.\"","type":"text"}],"id":"ef9615a1-abd3-411b-bc79-e0aa0d62d2c7","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"bold":true},"text":"Step 1: Skill Injection & Initialization","type":"text"}],"id":"4ce7129a-1f57-472b-ae44-620f15140b86","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"Before asking the agent to write code, I solve the LLM knowledge-cutoff problem. I inject ''Agent Skills'' into the workspace for my core technologies ","type":"text"},{"styles":{"bold":true,"italic":true},"text":"[Mention tools, e.g., Auth provider, Database ORM]","type":"text"},{"styles":{"italic":true},"text":". This gives the agent the absolute latest documentation, API routes, and integration patterns, so it never hallucinates deprecated syntax. I also set a root instructions file to force the agent to read my context documents before every session.\"","type":"text"}],"id":"59631e43-2a0a-472b-b472-1ba48d59b8ed","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"bold":true},"text":"Step 2: Writing the Feature Spec","type":"text"}],"id":"1443f1cc-5f1a-4488-aa43-4d8252958227","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"I break the project down into isolated units. For example, when building ","type":"text"},{"styles":{"bold":true,"italic":true},"text":"[Specific Feature]","type":"text"},{"styles":{"italic":true},"text":", I don''t just prompt the chat. I write a dedicated spec document. I define the Goal, the specific ","type":"text"},{"styles":{"bold":true,"italic":true},"text":"[UI/Backend]","type":"text"},{"styles":{"italic":true},"text":" constraints, the dependencies, and most importantly, a Verification Checklist. This tells the AI exactly what ''done'' looks like and explicitly tells it what NOT to touch.\"","type":"text"}],"id":"1ea8a802-8d86-431f-898f-8b5d29984922","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"bold":true},"text":"Step 3: The Execution Protocol","type":"text"}],"id":"dd17f434-d529-419e-ba51-1c37ac14c936","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"My prompting strategy is highly disciplined. For every feature, I open a fresh chat window to clear stale context, and I use the exact same protocol: ","type":"text"},{"styles":{"bold":true,"italic":true},"text":"''Read this spec file, update the progress tracker to mark this as in-progress, and implement it exactly as specified.''","type":"text"},{"styles":{"italic":true},"text":" The AI reads the rules, logs its intent, and executes cleanly.\"","type":"text"}],"id":"9659e3ef-170a-4b2e-a7ea-da84a7f5a31d","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"bold":true},"text":"Step 4: Review and Isolate","type":"text"}],"id":"b0827acb-5074-4dc0-93ee-037c0684f4ee","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"I treat AI output like a Pull Request. If a bug occurs, I don''t panic-prompt the agent with a raw error log. I document the error in a ","type":"text"},{"styles":{"code":true},"text":"current_issues.md","type":"text"},{"styles":{"italic":true},"text":" file, provide a screenshot or specific logs, and instruct the AI to ","type":"text"},{"styles":{"bold":true,"italic":true},"text":"''Analyze this issue using best practices and provide your reasoning before writing a fix.''","type":"text"},{"styles":{"italic":true},"text":" Once it passes my review, I merge the branch and move to the next spec.\"","type":"text"}],"id":"3e1d2177-e0bf-41ac-a7ac-bb713b611298","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"945d62c6-e515-4053-a38d-d3eface8eab0","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Here is the breakdown of ","type":"text"},{"styles":{"bold":true},"text":"Phase 4 (Structured Debugging & Edge Case Handling)","type":"text"},{"styles":{},"text":", extracted from the transcript and framed for the Forward Deployed Engineer (FDE) persona.","type":"text"}],"id":"332e24bd-066a-4e5b-9c74-4dfdaa25c1a1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"When working with AI agents, the most dangerous moment is when a bug occurs. Junior developers will immediately paste the raw error log into the chat, hit send, and watch the AI spiral—trying to fix one bug while breaking ten other features. An FDE handles debugging as a strict, documented protocol to maintain total control over the codebase.","type":"text"}],"id":"52478238-9399-48a2-8dae-57ec7f0fa11e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"a70d87f3-6ffd-4870-9ad6-f26bc8631356","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"The FDE Mindset: Phase 4 (Structured Debugging)","type":"text"}],"id":"bef571d0-a885-4523-b409-08d1015a1acd","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Based on the transcript, this phase is about slowing the AI down. You force the agent to analyze the root cause, present a plan, and wait for your human approval before it is allowed to write a single line of corrective code. You also leverage automated review tools to catch the edge cases that both humans and LLMs miss.","type":"text"}],"id":"2aaf730d-3225-4a76-8dfd-40a8ce1bae5b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"The Core Steps:","type":"text"}],"id":"7e2b5e0c-435a-4ce7-acee-fce0564b62fc","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"The ","type":"text"},{"styles":{"code":true},"text":"current_issues.md","type":"text"},{"styles":{"bold":true},"text":" Protocol:","type":"text"},{"styles":{},"text":" Never paste errors directly into a conversational prompt. Document the bug, the error logs, and the replication steps in a dedicated markdown file.","type":"text"}],"id":"a67cf43f-b67b-4a3f-9e60-6f911e8d2e1b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Visual Debugging:","type":"text"},{"styles":{},"text":" If the issue is UI-related, place a screenshot in a ","type":"text"},{"styles":{"code":true},"text":"screenshots/","type":"text"},{"styles":{},"text":" folder and link it in the issues document so the AI \"sees\" the layout failure.","type":"text"}],"id":"6fe5e582-c053-4e42-a946-ae58ed5f8bfc","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"The Analysis-First Prompt:","type":"text"},{"styles":{},"text":" Command the agent to read the issue, consult its framework skills, and output a root-cause analysis. Explicitly tell it to ","type":"text"},{"styles":{"italic":true},"text":"wait for your green light","type":"text"},{"styles":{},"text":" before executing.","type":"text"}],"id":"59d793ba-d2c9-4c85-8004-e1a7ccdbe36e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Automated Code Review (The PR Gate):","type":"text"},{"styles":{},"text":" Use AI code review tools (like CodeRabbit) on Pull Requests before merging. This catches edge cases (like missing accessibility labels, unhandled promise rejections, or empty string validations) that the coding agent overlooked.","type":"text"}],"id":"b2a67f86-e9dc-4b4e-8473-d7a5f2fa6834","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"id":"d3036785-e38b-4b66-bfbd-faebd6b4cab9","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"The Narration Template (FDE Persona)","type":"text"}],"id":"6de4825d-3e06-4b11-ac09-7dd34ceb0216","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Use this script to explain how you surgically resolve issues when the AI hallucinates or breaks the system.","type":"text"}],"id":"d835cca4-bbcc-412c-a82a-939bcb6fa747","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"The Opening (Setting the FDE Frame)","type":"text"}],"id":"2801aa61-6c36-4947-a1f6-ae576aea3bd9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"As a Forward Deployed Engineer, my biggest risk isn''t the AI failing to write code; it''s the AI spiraling and breaking the architecture when trying to fix a bug. To prevent this, I use a strict, structured debugging protocol. I don''t let the agent guess. I force it to analyze the root cause before it is allowed to execute a fix.\"","type":"text"}],"id":"fc78b94c-0452-461c-abda-a18f8095c8ec","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"bold":true},"text":"Step 1: Documenting and Isolating the Issue","type":"text"}],"id":"eb0dc19e-93ec-4b67-b2ca-660b368c36b0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"Whenever I hit a bug—whether it''s a server error or a UI glitch—I never paste raw logs into the chat. Instead, I log it in a ","type":"text"},{"styles":{"code":true},"text":"current_issues.md","type":"text"},{"styles":{"italic":true},"text":" file. I outline the exact error log, the context of what I was trying to do, and if it''s a visual issue, I drag a screenshot into the workspace. I isolate the problem entirely from the previous generation context.\"","type":"text"}],"id":"29a8068a-652d-45dc-bf76-e7de5d32850f","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"bold":true},"text":"Step 2: The Analysis-First Prompting Strategy","type":"text"}],"id":"a97b1b56-c3af-4a77-b5c0-0be433730b95","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"Once documented, I open a fresh chat and use a specific corrective prompt: ","type":"text"},{"styles":{"bold":true,"italic":true},"text":"''Read ","type":"text"},{"styles":{"code":true},"text":"current_issues.md","type":"text"},{"styles":{"bold":true,"italic":true},"text":". Consult your [Specific Framework] agent skills. Deeply analyze the root cause of this bug. Provide a fix plan, and wait for my approval to execute.''","type":"text"},{"styles":{"italic":true},"text":" By forcing the AI to explain its reasoning first, I ensure it actually understands the system architecture rather than just guessing syntax.\"","type":"text"}],"id":"40ce4a73-8b10-4a01-901e-d878b004a175","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"bold":true},"text":"Step 3: Edge Case Reviews","type":"text"}],"id":"e4fc4d0e-e17f-47c6-8c51-d3b2cea2c558","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"Finally, because AI coding agents optimize for the ''happy path,'' they often miss edge cases. I treat the AI''s output like a junior developer''s pull request. I push the code to a staging branch and run an automated review tool to catch unhandled states—like ","type":"text"},{"styles":{"bold":true,"italic":true},"text":"[Mention a specific edge case, e.g., missing API error handling, empty string validations, or security leaks]","type":"text"},{"styles":{"italic":true},"text":". I merge to the main branch only when the code is fully hardened.\"","type":"text"}],"id":"be9829d5-9b42-4249-a563-fdc2332d2204","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"0990c4ca-066e-4db4-836c-49343af7287c","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"There is ","type":"text"},{"styles":{"bold":true},"text":"one crucial final phase","type":"text"},{"styles":{},"text":" left from the video: ","type":"text"},{"styles":{"bold":true},"text":"Phase 5 (Production Hardening, Deployment & Delivery)","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"c7549ed2-57fd-4cf2-b0cb-841d68d20792","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"For a Forward Deployed Engineer, a project is never considered done when it runs on ","type":"text"},{"styles":{"code":true},"text":"localhost:3000","type":"text"},{"styles":{},"text":". FDEs are judged strictly on ","type":"text"},{"styles":{"bold":true},"text":"customer delivery and live production stability","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"e3df7a95-8877-4a62-89af-4cdbe0669461","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Here is Phase 5, structured with the exact same FDE persona and narration framework.","type":"text"}],"id":"bd0c7700-0b3b-452d-b600-e0225b9b1dab","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"1b2c5c93-3a55-4e52-87a2-72de6137cd88","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"The FDE Mindset: Phase 5 (Production Hardening & Deployment)","type":"text"}],"id":"7158de6d-2aa7-414a-9400-b16ecb36bcf0","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Based on the transcript, this phase is about taking a system that works in isolation and making it survive real-world traffic. In the video, moving to production required transitioning third-party services from sandbox mode to live infrastructure, resolving environment variable conflicts, and fixing edge-case build failures during deployment.","type":"text"}],"id":"0d29bd02-e438-489f-87be-06058ae24abf","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"The Core Steps:","type":"text"}],"id":"9ec71d56-fdd3-4b01-ac3d-ba3a20e61052","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Infrastructure Transition (Dev to Prod):","type":"text"},{"styles":{},"text":" Moving all keys and services (Auth, Database, Storage, Background Workers) from sandbox/development tiers to production configurations with proper rate-limiting and security.","type":"text"}],"id":"e2c656a9-7251-497d-93f7-f89c25ca3c75","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Build Pipeline & Deployment Hardening:","type":"text"},{"styles":{},"text":" Fixing the subtle build traps that pass in local development but break on cloud providers (e.g., configuring ","type":"text"},{"styles":{"code":true},"text":"postinstall","type":"text"},{"styles":{},"text":" scripts for database clients like ","type":"text"},{"styles":{"code":true},"text":"prisma generate","type":"text"},{"styles":{},"text":", clearing lockfile caching issues).","type":"text"}],"id":"b599abde-c7a1-4bf0-83cb-f629d03ac1f0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Multi-Session Live Verification:","type":"text"},{"styles":{},"text":" Testing live production URLs across multiple authenticated sessions to ensure webhooks, background tasks, and real-time syncing actually work in the wild.","type":"text"}],"id":"1b0883fb-60a8-432e-91c7-45341b2870b3","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Stakeholder Delivery & Handover:","type":"text"},{"styles":{},"text":" Exporting the system''s generated artifacts (e.g., technical specifications, live workspace links) and handing them over to business stakeholders or directors.","type":"text"}],"id":"29cec5e4-64e9-435e-8a22-07a873542f9f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"id":"c086984e-861c-4e4d-9c54-1bd3d83bac3d","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"The Narration Template (FDE Persona)","type":"text"}],"id":"37609890-07a1-47e5-8c03-00323462d8ec","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Use this script to show the interviewers that you think about the entire lifecycle through to production:","type":"text"}],"id":"f8f35ac1-458d-4271-ad54-da0a2efc32cb","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"The Opening (Setting the FDE Frame)","type":"text"}],"id":"bea0364d-e941-4b15-bc45-095cec8792e3","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"As a Forward Deployed Engineer, my job isn''t finished when code runs on ","type":"text"},{"styles":{"code":true},"text":"localhost","type":"text"},{"styles":{"italic":true},"text":". My mandate is to deliver working, enterprise-grade software into production. The final phase of my pipeline is production hardening—transitioning from development sandbox environments to live infrastructure, hardening the build pipeline, and verifying the live deployment.\"","type":"text"}],"id":"905b4187-39bd-4826-b189-7960e31fc88e","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"bold":true},"text":"Step 1: Environment & Credential Isolation","type":"text"}],"id":"ff06ef82-6ef6-42ae-a5b8-b2151653e766","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"Before deploying, I strictly separate development from production. I swap out sandbox keys for production credentials across ","type":"text"},{"styles":{"bold":true,"italic":true},"text":"[Mention services, e.g., Auth, Database, Storage, Background Workers]","type":"text"},{"styles":{"italic":true},"text":". I ensure that storage policies are strictly private so client data isn''t publicly exposed via unsecured URLs.\"","type":"text"}],"id":"121b0a5e-c53b-469d-bda0-cebb584bdfb5","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"bold":true},"text":"Step 2: Resolving Production Build Traps","type":"text"}],"id":"c4075b12-9a25-46a0-94bf-5653b9e6858b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"Production environments build differently than local environments. When deploying to platforms like Vercel, I preemptively handle common build failures—such as adding a ","type":"text"},{"styles":{"code":true},"text":"postinstall: prisma generate","type":"text"},{"styles":{"italic":true},"text":" script to ","type":"text"},{"styles":{"code":true},"text":"package.json","type":"text"},{"styles":{"italic":true},"text":" so the database client compiles cleanly in serverless functions, and ensuring ","type":"text"},{"styles":{"code":true},"text":".env","type":"text"},{"styles":{"italic":true},"text":" variables match the production pipeline exactly.\"","type":"text"}],"id":"004eae8d-02b5-4bb0-a66b-e3c5f3577e18","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"bold":true},"text":"Step 3: Verification & Handover","type":"text"}],"id":"e7ca7956-bbcc-4a16-b2ce-8b9e2537bca8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"Once the build passes, I perform end-to-end smoke testing on the live domain across multiple separate browser sessions to verify real-time sync, background job execution, and access control. Finally, I package the generated technical documentation and hand over a validated, functioning product to the client or director.\"","type":"text"}],"id":"a09c3b3c-28c7-43f2-9dc2-aa602f7f7274","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"d767a499-eda7-4675-961b-48eb85047d8c","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"The Complete End-to-End FDE Framework (At a Glance)","type":"text"}],"id":"98ab855c-fac6-4a6f-a27e-95603cd76370","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"With all 5 phases complete, your entire interview narration follows this logical progression:","type":"text"}],"id":"dc979124-07b5-4244-8ec3-03253c3d012f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":{"columnWidths":[null,null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Phase","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Core Focus","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"FDE Deliverable","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Phase 1","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"Product Discovery & Market Alignment","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Business friction defined, market gap analyzed, strict \"Out of Scope\" list.","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Phase 2","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"Architectural Planning (6 Context Files)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Stack invariants, hybrid data storage rules, dynamic Progress Tracker.","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Phase 3","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"Agent Initialization & Spec Execution","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Agent Skills installed, unit-by-unit isolated spec files, prompt execution.","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Phase 4","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"Structured Debugging & PR Reviews","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"code":true},"text":"current_issues.md","type":"text"},{"styles":{},"text":" root-cause analysis, CodeRabbit automated reviews.","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Phase 5","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"Production Hardening & Deployment","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Prod key transitions, build pipeline fixes, live multi-session smoke test.","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"209f5ad3-e91c-4fe1-857b-e109c9c1bbc7","props":{"textColor":"default"},"type":"table"},{"children":[],"content":[],"id":"3e3c81df-b4cc-46fb-ba19-3016d50b7c8a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[],"id":"39aa1df6-1b0f-453a-857e-991c91f135b8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"}]'::jsonb, '3e9e3dd3-a59b-4b02-968a-ee95e7317583') ON CONFLICT ("node_id") DO UPDATE SET "bad_example" = EXCLUDED."bad_example", "completed_at" = EXCLUDED."completed_at", "created_at" = EXCLUDED."created_at", "definition" = EXCLUDED."definition", "good_example" = EXCLUDED."good_example", "is_completed" = EXCLUDED."is_completed", "key_points" = EXCLUDED."key_points", "last_edited" = EXCLUDED."last_edited", "map_id" = EXCLUDED."map_id", "mental_model" = EXCLUDED."mental_model", "notes" = EXCLUDED."notes", "resources" = EXCLUDED."resources", "rich_content" = EXCLUDED."rich_content", "user_id" = EXCLUDED."user_id";
INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-06-13T06:27:02.872405+00:00', '', '', 'ce6ef7c9-61a3-44a7-bf75-d35f5d10d3ab', false, '[]'::jsonb, '2026-06-18T13:15:26.893+00:00', '2ad473fe-77dd-481e-8ba7-4b2b0336173f', '', '4b46d852-9c47-4819-a20d-60fccc548eb9', '', '[]'::jsonb, '[{"children":[],"content":[{"styles":{},"text":"Variables","type":"text"}],"id":"6d620c80-c61e-417b-8ae6-f945aeb64689","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"PYTHON VARIABLES - MENTAL MODELS","type":"text"}],"id":"7f743f1d-64cc-43df-930a-3225e1d039ff","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The Bank''s Filing Cabinet\n|\n|-- ASSIGNMENT ------------------- LABELLING A FOLDER\n|   |-- name = value = stick a label on a folder\n|   |-- Label can be moved to a new folder anytime\n|   |-- Two labels can point to the same folder\n|   |-- = is NOT equality, it is ASSIGNMENT\n|   L-- Right side evaluates FIRST, then label is moved\n|\n|-- DATA TYPES ------------------- TYPE OF DOCUMENT IN FOLDER\n|   |-- int    = whole number ledger entry  (5, -3, 1_000_000)\n|   |-- float  = decimal ledger entry       (3.14, -0.5, 1.5e6)\n|   |-- str    = text document              (\"Kasun\", ''ACC001'')\n|   |-- bool   = yes/no checkbox            (True, False)\n|   |-- None   = empty folder, no document  (None)\n|   L-- type() = read the label on the folder''s TYPE tag\n|\n|-- TYPE CONVERSION -------------- PHOTOCOPYING TO NEW FORMAT\n|   |-- int()   = convert to whole number\n|   |-- float() = convert to decimal number\n|   |-- str()   = convert to text\n|   |-- bool()  = convert to True / False\n|   L-- Implicit vs Explicit: Python does some, you do rest\n|\n|-- NAMING RULES ----------------- LABEL PRINTING MACHINE\n|   |-- snake_case = standard for variables (account_balance)\n|   |-- UPPER_SNAKE = constants (MAX_RETRY_LIMIT = 3)\n|   |-- Cannot start with a digit\n|   |-- Cannot use reserved words (if, for, while...)\n|   |-- Case sensitive: balance ≠ Balance ≠ BALANCE\n|   L-- Descriptive names = self-documenting code\n|\n|-- MULTIPLE ASSIGNMENT ---------- BATCH LABELLING\n|   |-- a, b, c = 1, 2, 3 = unpack in one line\n|   |-- a = b = c = 0 = same value, three labels\n|   |-- a, b = b, a = swap WITHOUT a temp variable\n|   L-- _ = throwaway label (I don''t need this value)\n|\n|-- AUGMENTED ASSIGNMENT --------- UPDATE IN PLACE\n|   |-- += -= *= /= //= %= **=\n|   |-- balance += 1000 = balance = balance + 1000\n|   L-- Shorthand only - does NOT change how Python works\n|\n|-- SCOPE ------------------------ WHICH FILING ROOM?\n|   |-- Local  = inside the function''s private office\n|   |-- Global = the shared main filing room\n|   |-- global keyword = reach INTO the main room\n|   |-- LEGB rule: Local -> Enclosing -> Global -> Built-in\n|   L-- Best practice: avoid globals, pass values in/out\n|\nL-- CONSTANTS -------------------- SEALED REFERENCE BINDER\n    |-- Python has no true constants - convention only\n    |-- ALL_CAPS signals \"do not change this\"\n    |-- Defined once at module level\n    L-- MAX_BALANCE = 10_000_000 (not enforced, but respected)","type":"text"}],"id":"e9f2f83b-a7ff-4cb5-84ee-533cf778af70","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"c982a7fb-ed0d-418c-b93f-ff54fdb1ac2e","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Python","type":"text"}],"id":"a4314b1a-9f3c-4ef6-82bf-b56904f2ac78","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Decision Tree - Which Variable Concept Do I Need?","type":"text"}],"id":"d79aadde-f4ef-42d3-9afa-463138b1f9b4","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"START: I need to store or work with a value\n|\nWhat is the SITUATION?\n|           |             |             |\nSTORE IT    CONVERT IT    NAME IT       SCOPE ISSUE\n|           |             |             |\nSingle      What          What          Is the variable\nvalue?      from/to?      kind?         local or global?\n|           |             |             |\nx = value   num -> str    changes ->    Inside function:\n            str -> num    snake_case    can READ globals\nMultiple    any -> bool   fixed ->      to WRITE globals:\nat once?    num -> int    UPPER_SNAKE   use global keyword\n|           |             NEVER ->      Best practice:\na, b = 1,2  str()        reserved      pass as argument,\na = b = 0   int()        words         return the value\na, b = b, a float()\n_ = unused  bool()","type":"text"}],"id":"bf6d9b7b-a45a-4f27-9051-f4223dafe3ca","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"94098df0-33cd-4294-83b9-5b1ed7804b1d","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"🗄️ The Master Mental Model - The Bank''s Filing Cabinet","type":"text"}],"id":"e45738e1-34bd-4e31-853a-a42439f30d09","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Every variable concept maps to a filing system inside the bank.","type":"text"}],"id":"58038267-c2c5-4f75-be4c-1c3a2df71505","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"The folder","type":"text"},{"styles":{},"text":" → the object (the actual value in memory)","type":"text"}],"id":"b78b9324-192b-4d20-88c4-05c5b40bcee1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"The label","type":"text"},{"styles":{},"text":" → the variable name (stuck on the folder)","type":"text"}],"id":"29b7c116-96ae-40ea-a061-f5d6db3cc206","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Assignment","type":"text"},{"styles":{},"text":" → moving a label to point at a folder","type":"text"}],"id":"a7c945a4-1048-4833-8f8d-a971983c08f1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Type","type":"text"},{"styles":{},"text":" → what kind of document is inside the folder","type":"text"}],"id":"da65e8ea-a527-4a3c-b8e6-e53ed375d81c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Type conversion","type":"text"},{"styles":{},"text":" → photocopying the document into a new format","type":"text"}],"id":"696d4170-9f9e-41be-bdf0-4748c5da2074","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Scope","type":"text"},{"styles":{},"text":" → which room the filing cabinet is in (private office vs shared floor)","type":"text"}],"id":"200574fa-9529-4cee-8682-bb0d5c137fbc","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Constant","type":"text"},{"styles":{},"text":" → a sealed reference binder nobody should relabel","type":"text"}],"id":"0a9c0abb-e403-408b-950d-19038123fbaf","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"The golden rule: variables are labels, not boxes. You don''t put a value into a variable — you stick a label onto a value that already exists in memory.","type":"text"}],"id":"2df1652d-4b01-4041-bcb9-ad54d8c2bbe3","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"343aa267-1a4c-4599-b492-4959c8fdb81e","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"🏷️ Assignment — Labelling a Folder","type":"text"}],"id":"65ef9b73-9462-4519-bddf-5eea550d1313","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"You don''t create a box and put something inside. You create a value (the folder), then stick a label on it. The label can be moved. The folder stays where it is until nothing points to it.","type":"text"}],"id":"6f675689-2586-42f8-a727-08252d3668e7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"# Simple assignment - label points to folder\nbalance = 50000          # label \"balance\" -> folder containing 50000\nowner   = \"Kasun\"        # label \"owner\"   -> folder containing \"Kasun\"\nactive  = True           # label \"active\"  -> folder containing True\n\n# Right side evaluates FIRST, then label is moved\nbalance = balance + 1000\n# Step 1: evaluate balance + 1000 = 51000 (new folder)\n# Step 2: move label \"balance\" to point at 51000\n# Old folder (50000) is now unlabelled -> garbage collected\n\n# Two labels, same folder\noriginal  = \"ACC001\"\nreference = original      # both labels point to the SAME folder\nprint(reference)          # \"ACC001\"\n\n# Reassigning one label does NOT affect the other\noriginal = \"ACC002\"       # label \"original\" moved to new folder\nprint(reference)          # still \"ACC001\" - label didn''t move","type":"text"}],"id":"3c4ab079-917f-412e-86a3-18615f8a790c","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why this matters:","type":"text"}],"id":"a2625825-24b9-403a-ae87-2463b61ce2d9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"# With MUTABLE objects (lists, dicts), two labels = shared folder\n# Changing the folder affects ALL labels pointing to it\nlist_a = [1, 2, 3]\nlist_b = list_a           # both point to SAME list\n\nlist_b.append(4)\nprint(list_a)             # [1, 2, 3, 4] <- list_a changed too!\n# The folder was modified; both labels still point to it\n\n# To avoid this, make a COPY of the folder\nlist_b = list_a.copy()    # new folder, same contents\nlist_b.append(4)\nprint(list_a)             # [1, 2, 3] <- unchanged","type":"text"}],"id":"0fc58998-a453-4a28-80fc-22acf080582a","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"5119bd13-f54b-4b0f-b10b-3cfbfc1dadbd","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"📄 Data Types — Type of Document in the Folder","type":"text"}],"id":"0af6dfa8-22e7-4869-94c7-087ab442d5f1","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Every folder has a document type. Python reads the type automatically — you don''t declare it. But knowing the type matters for every operation.","type":"text"}],"id":"79926a6a-5741-4866-af11-f25396bdbfb6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"int — Whole Number Ledger Entry","type":"text"}],"id":"b02dddaf-a0a2-42cb-b799-d4740e42ba69","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"account_number = 1001\ntransaction_count = 0\noverdraft_limit   = -5000       # negative int\nlarge_balance     = 1_000_000   # underscore separator for readability\n                                # Python ignores underscores - just for humans\n\nprint(type(account_number))     # <class ''int''>\n\n# Int arithmetic - always produces exact whole numbers\nprint(10 // 3)      # 3   <- floor division (whole number result)\nprint(10 % 3)       # 1   <- modulo (remainder)\nprint(2 ** 10)      # 1024 <- exponentiation\nprint(10 / 3)       # 3.333... <- regular division produces FLOAT","type":"text"}],"id":"6d3796fc-d16c-4b40-9962-c8dfd8da72e2","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"float — Decimal Ledger Entry","type":"text"}],"id":"b828647b-7024-4aae-acba-6057d76992f4","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"interest_rate  = 0.035\nbalance        = 150000.75\nthreshold      = 1.5e6          # scientific notation = 1,500,000.0\ntiny           = 2.5e-4         # 0.00025\n\nprint(type(interest_rate))      # <class ''float''>\n\n# Float arithmetic - beware of precision\nprint(0.1 + 0.2)                # 0.30000000000000004  <- NOT 0.3!\n# This is a hardware limitation, not a Python bug\n\n# Fix: use round() for display, or decimal module for finance\nprint(round(0.1 + 0.2, 2))      # 0.3\ninterest = round(150000 * 0.035, 2)   # 5250.0  <- safe for display\n\n# Int vs Float operations\nprint(7 / 2)        # 3.5   <- / always gives float\nprint(7 // 2)       # 3     <- // always gives int (floor)\nprint(7.0 // 2)     # 3.0   <- // with float gives float","type":"text"}],"id":"9201c16a-579d-4d7d-b334-b9243b81e400","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"str — Text Document","type":"text"}],"id":"611e6391-05c6-49b1-a9ab-90f35bd01f74","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"name         = \"Kasun Wijesinghe\"\naccount_id   = ''ACC001''           # single or double - identical\nempty        = \"\"                 # empty string, length 0\n\nprint(type(name))                 # <class ''str''>\n\n# Strings and numbers are DIFFERENT types - cannot mix with +\nage = 28\n# print(\"Age: \" + age)            # TypeError\nprint(\"Age: \" + str(age))         # \"Age: 28\"  - must convert first\nprint(f\"Age: {age}\")              # \"Age: 28\"  - f-string handles it","type":"text"}],"id":"ac2d1aa0-501b-4166-b191-8f252da85e11","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"bool — The Yes/No Checkbox","type":"text"}],"id":"91a7932e-9d36-4392-9f63-6b277b7efea7","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"is_active    = True\nis_flagged   = False\nis_premium   = True\n\nprint(type(is_active))      # <class ''bool''>\n\n# Booleans ARE integers under the hood\nprint(True  + True)         # 2   <- True = 1\nprint(False + True)         # 1   <- False = 0\nprint(True  * 5)            # 5\n\n# Useful trick: count True values in a list\nflags = [True, False, True, True, False]\nprint(sum(flags))           # 3  <- counts the Trues\n\n# Every value has a boolean interpretation\n# FALSY values (evaluate to False in a condition):\n#   False, None, 0, 0.0, \"\", [], {}, set()\n# TRUTHY values (everything else):\n#   True, any non-zero number, any non-empty string/list/dict\n\nprint(bool(0))              # False\nprint(bool(\"\"))             # False\nprint(bool([]))             # False\nprint(bool(None))           # False\n\nprint(bool(1))              # True\nprint(bool(\"Kasun\"))        # True\nprint(bool([0]))            # True  <- list with one item, even if item is 0\n\n# Real use - check if a list has data before processing\ntransactions = []\nif transactions:            # falsy if empty, truthy if has items\n    process(transactions)\nelse:\n    print(\"No transactions to process\")","type":"text"}],"id":"77d3e85c-7e50-45bc-9abe-2fd86add7777","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"None — The Empty Folder","type":"text"}],"id":"d18910ed-6b37-4c76-ad65-910d34ef416d","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# None = folder exists but has no document inside\nresult     = None           # not yet computed\nconnection = None           # not yet established\n\nprint(type(None))           # <class ''NoneType''>\nprint(result is None)       # True  <- always use ''is'', not ==\nprint(result == None)       # True  <- works but not recommended\n\n# Common pattern - sentinel value\ndef find_account(acc_id, accounts):\n    for account in accounts:\n        if account[''id''] == acc_id:\n            return account\n    return None             # explicit signal: not found\n\nresult = find_account(\"ACC999\", accounts)\nif result is None:\n    print(\"Account not found\")\nelse:\n    process(result)","type":"text"}],"id":"24e05487-baad-403d-b9d5-6871f20e8a93","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Quick type reference:","type":"text"}],"id":"ef1533aa-b02b-4574-af47-21239e231858","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Value           Type    Truthy/Falsy\n0               int     Falsy\n1               int     Truthy\n-5              int     Truthy\n0.0             float   Falsy\n3.14            float   Truthy\n\"\"              str     Falsy\n\"Kasun\"         str     Truthy\n\"0\"             str     Truthy  <- \"0\" is a non-empty string!\n[]              list    Falsy\n[0]             list    Truthy\n{}              dict    Falsy\nNone            None    Falsy\nFalse           bool    Falsy\nTrue            bool    Truthy","type":"text"}],"id":"bb87e8fa-ec35-4fc3-a370-26154fca3733","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"c58fdb84-ff3d-4803-b186-2c3d1a19127f","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"🔄 Type Conversion — Photocopying to a New Format","type":"text"}],"id":"a2dba0cc-004f-42b8-a272-0d3dc9ab67b4","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The original folder stays. You make a new copy in a different format. You must assign that copy to a label or it is discarded.","type":"text"}],"id":"3c865ac2-d7c3-45c1-bb60-ad84db3f0820","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Explicit Conversion (You Do It)","type":"text"}],"id":"57154409-eee3-43fb-829f-5b990285018a","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# str -> int\nuser_input = \"50000\"\namount = int(user_input)        # \"50000\" -> 50000\nprint(amount + 1000)            # 51000  <- now arithmetic works\n\n# str -> float\nrate_str = \"0.035\"\nrate = float(rate_str)          # \"0.035\" -> 0.035\n\n# int / float -> str\nbalance = 150000\nlabel = \"Balance: \" + str(balance)     # must convert for concatenation\n\n# int -> float and back\nx = 7\nprint(float(x))     # 7.0\nprint(int(3.9))     # 3   <- truncates, does NOT round\n\n# str -> bool - almost never what you want\nprint(bool(\"False\"))    # True  <- non-empty string is always True!\nprint(bool(\"\"))         # False <- only empty string is False\n\n# Correct way to parse a boolean from a string\ndef parse_bool(s):\n    return s.strip().lower() == \"true\"\n\nprint(parse_bool(\"True\"))      # True\nprint(parse_bool(\"False\"))     # False\nprint(parse_bool(\"  true  \"))  # True","type":"text"}],"id":"4105d52f-eb6b-4aae-bb7d-9d8e1018cd47","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Common Conversion Errors and Fixes","type":"text"}],"id":"03d7050b-a1a6-46f2-ad6d-c52ccb7c2871","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# ValueError - string content cannot become that type\nint(\"ACC001\")           # ValueError: invalid literal for int()\nint(\"3.14\")             # ValueError: int() can''t parse a decimal string\nfloat(\"Rs.5000\")        # ValueError: extra characters\n\n# Fix: clean the string first\namount_str = \"Rs. 1,50,000.00\"\ncleaned = amount_str.replace(\"Rs. \", \"\").replace(\",\", \"\")\namount  = float(cleaned)        # 150000.0  <- works\n\n# Safe conversion with error handling\ndef safe_int(value, default=0):\n    try:\n        return int(value)\n    except (ValueError, TypeError):\n        return default\n\nprint(safe_int(\"500\"))      # 500\nprint(safe_int(\"abc\"))      # 0  <- default\nprint(safe_int(None))       # 0  <- default","type":"text"}],"id":"70d0af3f-3cbd-412c-8a2c-19f906f144e2","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Implicit Conversion (Python Does It)","type":"text"}],"id":"299fa34e-ea24-4004-b24b-4b3da81c291a","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# Python automatically promotes int to float in mixed arithmetic\nresult = 5 + 2.0        # 7.0  <- int promoted to float\nresult = True + 5       # 6    <- True treated as 1\n\n# Python does NOT automatically convert str <-> number\n\"50000\" + 1000          # TypeError: must do it explicitly","type":"text"}],"id":"c4b2ed2b-5bba-4394-ad4e-d91d0be61897","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"e9ad43e0-89eb-4108-8743-d2b8bf9f8b4d","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"🖊️ Naming Rules — The Label Printing Machine","type":"text"}],"id":"6a228e78-c0e8-48b6-8243-fdf9e50689c6","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# VALID names\nbalance           = 50000     # snake_case - standard\naccount_id        = \"ACC001\"  # snake_case with underscore\n_internal         = True      # leading underscore = private (convention)\ntotal_count_2024  = 0         # can contain digits (not at start)\n\n# INVALID names - these crash immediately\n# 2024_total = 0              # SyntaxError: cannot start with digit\n# account-id = \"ACC001\"       # SyntaxError: dash not allowed\n# for = 5                     # SyntaxError: reserved word\n\n# CONSTANTS - UPPER_SNAKE_CASE (convention, not enforced)\nMAX_RETRY_ATTEMPTS = 3\nDEFAULT_CURRENCY   = \"LKR\"\nINTEREST_RATE      = 0.035\n\n# CASE SENSITIVITY - three different variables\nbalance  = 50000\nBalance  = 75000\nBALANCE  = 99000\nprint(balance, Balance, BALANCE)    # 50000 75000 99000\n\n# RESERVED WORDS - cannot use as variable names\n# and, as, assert, async, await, break, class, continue,\n# def, del, elif, else, except, False, finally, for, from,\n# global, if, import, in, is, lambda, None, nonlocal, not,\n# or, pass, raise, return, True, try, type, while, with, yield\n\n# DESCRIPTIVE vs CRYPTIC\n# Bad\nx  = 50000\ny  = 0.035\nz  = x * y\n\n# Good\nprincipal    = 50000\nannual_rate  = 0.035\ninterest     = principal * annual_rate   # self-documenting","type":"text"}],"id":"dfe408c0-d3fb-467e-8424-3d5d3c1a7a76","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"5632e4db-a707-4b62-a8e1-ea4b3017bbec","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"📦 Multiple Assignment — Batch Labelling","type":"text"}],"id":"9a8ab05a-2d57-4f39-9ccf-3b8cea55cef4","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# UNPACK multiple values in one line\nacc_id, owner, balance = \"ACC001\", \"Kasun\", 50000\nprint(acc_id)   # \"ACC001\"\nprint(owner)    # \"Kasun\"\nprint(balance)  # 50000\n\n# Must match count exactly\n# a, b = 1, 2, 3    # ValueError: too many values to unpack\n# a, b, c = 1, 2    # ValueError: not enough values to unpack\n\n# SAME VALUE to multiple labels\nx = y = z = 0\nprint(x, y, z)      # 0 0 0\n\n# SWAP without a temporary variable\ndebit  = 5000\ncredit = 2000\n\ndebit, credit = credit, debit   # swap in one line\nprint(debit)        # 2000\nprint(credit)       # 5000\n\n# Traditional swap for comparison - three lines, a temp folder\ntemp   = debit\ndebit  = credit\ncredit = temp\n# Python''s one-liner does the same, cleaner\n\n# THROWAWAY with _ (underscore)\n# _ signals \"I know this value exists but I don''t need it\"\nfor _ in range(5):                  # loop 5 times, don''t need the counter\n    process_next_record()\n\nacc_id, _, balance = (\"ACC001\", \"Kasun\", 50000)   # skip owner\nprint(acc_id, balance)     # \"ACC001\" 50000\n\n# EXTENDED UNPACKING with *\nfirst, *middle, last = [10, 20, 30, 40, 50]\nprint(first)    # 10\nprint(middle)   # [20, 30, 40]\nprint(last)     # 50\n\n# Real use - skip header, process rest\nheader, *rows = csv_lines\nfor row in rows:\n    process(row)","type":"text"}],"id":"b400a00b-7652-41bd-970e-03dff8ed69e9","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"350ad1d2-ab45-4264-95ea-7a1746c98ede","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"➕ Augmented Assignment — Update in Place","type":"text"}],"id":"362233b5-46be-4da2-ae79-5140ff1dde75","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"balance = 50000\n\n# Augmented assignment - shorthand for self-update\nbalance += 1000     # balance = balance + 1000  -> 51000\nbalance -= 500      # balance = balance - 500   -> 50500\nbalance *= 1.035    # balance = balance * 1.035 -> apply interest\nbalance /= 12       # balance = balance / 12    -> monthly\nbalance //= 1       # floor divide -> whole number\nbalance %= 10       # remainder\nbalance **= 2       # exponentiate\n\n# Also works with strings and lists\nlog  = \"Processing\"\nlog += \" complete\"          # \"Processing complete\"\n\nitems = [1, 2, 3]\nitems += [4, 5]             # [1, 2, 3, 4, 5]\n\n# Counter pattern - very common in data engineering\nerror_count = 0\nfor record in records:\n    if not validate(record):\n        error_count += 1    # accumulate the count\n\n# Running total pattern\ntotal = 0\nfor txn in transactions:\n    total += txn[''amount'']  # accumulate the sum","type":"text"}],"id":"beb445c0-2b17-4c12-89ce-bc4726ea10a7","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"6c4c1b1f-b60c-429d-9693-4e36fb66e075","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"🏢 Scope — Which Filing Room?","type":"text"}],"id":"7a547489-03e2-4e47-93c0-f5c00c2c7345","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Scope determines which filing room a label lives in — and whether other code can see it.","type":"text"}],"id":"ca61ed0c-adc4-49df-8c55-3aada02055b3","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"# GLOBAL scope - the shared main floor (outside all functions)\nbank_name = \"National Bank\"     # visible everywhere in this file\n\ndef print_bank():\n    print(bank_name)            # can READ a global from inside a function\n\nprint_bank()                    # \"National Bank\"  <- works\n\n# LOCAL scope - the private office (inside a function)\ndef calculate_interest(principal, rate):\n    interest = principal * rate     # ''interest'' is LOCAL\n    return interest\n\n# print(interest)    # NameError: ''interest'' not defined outside the function\n# Local variables die when the function returns\n\n# CONFLICT - local shadows global\nthreshold = 100_000             # global\n\ndef check_balance(balance):\n    threshold = 50_000          # LOCAL threshold - shadows the global\n    return balance > threshold  # uses LOCAL (50,000), not global (100,000)\n\ncheck_balance(75000)    # True  <- uses local 50,000\nprint(threshold)        # 100,000  <- global unchanged\n\n# GLOBAL KEYWORD - reaching into the shared room to write\ncounter = 0             # global counter\n\ndef increment():\n    global counter      # declare intent to modify the global\n    counter += 1        # now modifies the global, not a local copy\n\nincrement()\nincrement()\nprint(counter)          # 2\n\n# WHY TO AVOID globals - hard to trace, causes bugs\n# BETTER PATTERN: pass in, return out\ndef increment_counter(counter):\n    return counter + 1      # pure function - no side effects\n\ncounter = 0\ncounter = increment_counter(counter)\ncounter = increment_counter(counter)\nprint(counter)  # 2  <- same result, clearer data flow","type":"text"}],"id":"cfce7cc9-66f2-4117-a47b-737fbd9d8f2d","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"The LEGB Rule — Which Label Does Python Find?","type":"text"}],"id":"ea2c8a6c-8100-4ae5-bd27-8df2b1db4c40","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Python searches for a name in this order:\nL -> Local         (inside the current function)\nE -> Enclosing     (inside any containing function, for nested functions)\nG -> Global        (module level, outside all functions)\nB -> Built-in      (Python''s built-in names: len, print, range, type...)\n\nFirst match wins. Search stops.","type":"text"}],"id":"2ad83e4b-127e-407e-904e-ae5a3b864bea","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"# Demonstrating LEGB\nx = \"global\"                # G\n\ndef outer():\n    x = \"enclosing\"         # E\n\n    def inner():\n        x = \"local\"         # L\n        print(x)            # \"local\" <- L found first, stop\n\n    inner()\n    print(x)                # \"enclosing\" <- L gone, E found\n\nouter()\nprint(x)                    # \"global\" <- L and E gone, G found\n\n# Built-in shadowing - naming your variable after a built-in\nlist = [1, 2, 3]            # BAD: shadows the built-in list()\nprint(list([4, 5]))         # TypeError: ''list'' object is not callable\n# Fix: rename the variable\ndata = [1, 2, 3]            # good - ''list'' built-in is still usable","type":"text"}],"id":"c1551b6c-2ec9-42cf-ab88-e37da88558f3","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"95efc340-2d69-4db5-aa70-d3784969b944","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"🔒 Constants — The Sealed Reference Binder","type":"text"}],"id":"046419fe-2905-495c-a0fa-00ed29b1be8f","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Python has no syntax to create a true constant. Convention does the job instead.","type":"text"}],"id":"f93f5c33-d462-4f9e-bcf9-980a1e8d6171","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"# Module-level constants - ALL_UPPER_SNAKE_CASE\nMAX_TRANSACTION_AMOUNT = 10_000_000\nMIN_ACCOUNT_BALANCE    = 0\nDEFAULT_CURRENCY       = \"LKR\"\nINTEREST_RATE_ANNUAL   = 0.035\nMAX_LOGIN_ATTEMPTS     = 3\nSUPPORTED_TXN_TYPES    = (\"DEBIT\", \"CREDIT\", \"TRANSFER\")\n\n# Nothing stops Python from changing these - convention is the only guard\n# If someone does MAX_TRANSACTION_AMOUNT = 999, Python allows it\n# The ALL_CAPS name is a signal to every developer: DO NOT change this\n\n# Real use - replace magic numbers with named constants\n# Bad: magic numbers scattered through code\nif amount > 10_000_000:\n    reject(amount)\n\n# Good: one place to change, self-documenting everywhere\nif amount > MAX_TRANSACTION_AMOUNT:\n    reject(amount)\n\n# Common pattern - collect all constants in one file\n# constants.py\nMAX_RETRY_ATTEMPTS  = 3\nDB_TIMEOUT_SECONDS  = 30\nBATCH_SIZE          = 1000\nLOG_FILE_PATH       = \"/var/log/bank_pipeline.log\"\n\n# Then import where needed\n# from constants import MAX_RETRY_ATTEMPTS, BATCH_SIZE","type":"text"}],"id":"5332d673-e4bd-47bc-94e8-c4afa7520825","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"095e5aa2-1c4f-4928-a151-8426defabd1f","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"⚠️ Common Variable Mistakes — The Gotcha Wall","type":"text"}],"id":"1e487bf4-a9ee-4aed-afb7-acbaefaca6cb","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# GOTCHA 1: = vs == (assignment vs comparison)\nbalance = 50000                   # assignment - moves the label\nif balance == 50000:              # comparison - checks the value\n    print(\"Match\")\n\n# Easy to accidentally type:\n# if balance = 50000:             # SyntaxError in Python (would be a bug in other langs)\n\n# GOTCHA 2: Forgetting to capture the return value\nname = \"kasun\"\nname.upper()                      # does nothing useful\nprint(name)                       # still \"kasun\"\n\nname = name.upper()               # must capture\nprint(name)                       # \"KASUN\"\n\n# GOTCHA 3: Mutable default argument (advanced, but common bug)\ndef add_transaction(amount, history=[]):   # BAD - [] shared across ALL calls\n    history.append(amount)\n    return history\n\nprint(add_transaction(100))       # [100]\nprint(add_transaction(200))       # [100, 200]  <- not [200]! shared list\n\ndef add_transaction(amount, history=None):  # GOOD - None as sentinel\n    if history is None:\n        history = []\n    history.append(amount)\n    return history\n\n# GOTCHA 4: int() truncates, does not round\nprint(int(3.9))     # 3   <- not 4\nprint(int(-3.9))    # -3  <- not -4, truncates toward zero\nprint(round(3.9))   # 4   <- use round() when rounding is needed\n\n# GOTCHA 5: String \"0\" is truthy\nvalue = \"0\"\nif value:                         # True! non-empty string\n    print(\"truthy\")               # this prints\n\n# GOTCHA 6: Chained comparison works, but read carefully\nx = 5\nprint(1 < x < 10)                 # True  <- Python supports this\nprint(1 < x and x < 10)           # True  <- same thing, explicit","type":"text"}],"id":"9adde7a4-97f7-43a8-80d3-04253005abea","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"3b4a4410-cbed-44f9-9465-2521299c090b","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"🏦 SPECIAL CASES — Common Patterns","type":"text"}],"id":"0ad824b2-caa4-42e1-8a85-abe5f52f377d","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"\"Store a value not yet computed\"\n-> variable = None  (empty folder, check with ''is None'' later)\n\n\"Count events in a loop\"\n-> counter = 0 then counter += 1 inside the loop\n\n\"Accumulate a running total\"\n-> total = 0 then total += value inside the loop\n\n\"Swap two variables\"\n-> a, b = b, a  (one line, no temp variable)\n\n\"Unpack a row from a CSV or tuple\"\n-> acc_id, owner, balance = row  (unpack directly)\n\n\"Skip values I don''t need when unpacking\"\n-> useful, _, also_useful = row  (underscore = throwaway)\n\n\"Grab first and last, collect middle\"\n-> first, *middle, last = data  (extended unpacking)\n\n\"Loop N times without needing the counter\"\n-> for _ in range(N):  (underscore = discard the counter)\n\n\"Make a number readable\"\n-> 1_000_000  (underscore separator, Python ignores it)\n\n\"Avoid a magic number buried in logic\"\n-> MAX_LIMIT = 10_000_000 at module level (named constant)\n\n\"Check if a variable has a value yet\"\n-> if variable is None:  (always ''is'', never ==)\n\n\"Safely convert user input to int\"\n-> try: int(value) except ValueError: handle_error()\n\nEND - Concept selected, write the code","type":"text"}],"id":"bf199943-8b27-49e3-9ec7-d0189c76382e","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"c83427a8-ceb5-48b0-af0f-9f28833756fe","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"🏛️ Everything Connected — One Complete Account Setup Pipeline","type":"text"}],"id":"321e6866-5afa-419b-8e29-542b0634c2b0","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# MODULE-LEVEL CONSTANTS (sealed reference binders)\nMAX_BALANCE         = 10_000_000\nMIN_BALANCE         = 0\nDEFAULT_CURRENCY    = \"LKR\"\nVALID_ACCOUNT_TYPES = (\"PREMIUM\", \"STANDARD\", \"SAVINGS\")\nINTEREST_RATES      = {\"PREMIUM\": 0.045, \"STANDARD\": 0.035, \"SAVINGS\": 0.030}\nNEXT_SEQ            = 0             # global sequence counter (avoid in real code)\n\n\ndef setup_account(raw_input):\n    \"\"\"\n    Parse raw input and set up a new bank account.\n    Input:  \"kasun wijesinghe , 50000, premium\"\n    Output: fully validated account dict\n    \"\"\"\n\n    # MULTIPLE ASSIGNMENT + UNPACK - batch labelling from split CSV\n    raw_name, raw_balance, raw_type = raw_input.split(\",\")\n\n    # TYPE CONVERSION - str -> appropriate types\n    owner_name   = raw_name.strip().title()           # str, cleaned\n    balance      = float(raw_balance.strip())         # str -> float\n    account_type = raw_type.strip().upper()           # str, normalised\n\n    # AUGMENTED ASSIGNMENT - accumulate the sequence number\n    global NEXT_SEQ\n    NEXT_SEQ += 1\n\n    # LOCAL VARIABLE - computed inside this function\n    account_id = \"ACC\" + str(NEXT_SEQ).zfill(6)      # \"ACC000001\"\n\n    # BOOL - computed flag\n    is_premium = account_type == \"PREMIUM\"\n    is_valid   = (\n        MIN_BALANCE <= balance <= MAX_BALANCE\n        and account_type in VALID_ACCOUNT_TYPES\n    )\n\n    # NONE SENTINEL - interest rate not assigned yet\n    interest_rate = None\n\n    if not is_valid:\n        return None             # signal failure with None\n\n    # LOOKUP using global constant dict\n    interest_rate = INTEREST_RATES[account_type]    # float from constant\n\n    # LOCAL COMPUTATION\n    monthly_interest = round(balance * interest_rate / 12, 2)\n\n    # SWAP example - sort a pair of values\n    opening_min, opening_max = balance, balance * 1.1\n    if opening_min > opening_max:\n        opening_min, opening_max = opening_max, opening_min  # swap\n\n    # THROWAWAY - we need the index but not the key in this loop\n    rank = None\n    for idx, (acc_type, _) in enumerate(INTEREST_RATES.items()):\n        if acc_type == account_type:\n            rank = idx + 1      # 1-based rank\n            break\n\n    # RETURN structured result\n    return {\n        ''account_id'':       account_id,\n        ''owner'':            owner_name,\n        ''balance'':          balance,\n        ''currency'':         DEFAULT_CURRENCY,   # global constant\n        ''type'':             account_type,\n        ''is_premium'':       is_premium,\n        ''interest_rate'':    interest_rate,\n        ''monthly_interest'': monthly_interest,\n        ''tier_rank'':        rank,\n    }\n\n\n# --- Run it ---\nraw = \"kasun wijesinghe , 50000, premium\"\naccount = setup_account(raw)\n\nif account is None:                 # None check with ''is''\n    print(\"Account setup failed\")\nelse:\n    print(f\"Account:   {account[''account_id'']}\")\n    print(f\"Owner:     {account[''owner'']}\")\n    print(f\"Balance:   {DEFAULT_CURRENCY} {account[''balance'']:>12,.2f}\")\n    print(f\"Type:      {account[''type'']}  (Rank #{account[''tier_rank'']})\")\n    print(f\"Premium:   {account[''is_premium'']}\")\n    print(f\"Rate:      {account[''interest_rate'']:.2%}\")\n    print(f\"Monthly:   {DEFAULT_CURRENCY} {account[''monthly_interest'']:>10,.2f}\")\n\n# Output:\n# Account:   ACC000001\n# Owner:     Kasun Wijesinghe\n# Balance:   LKR     50,000.00\n# Type:      PREMIUM  (Rank #1)\n# Premium:   True\n# Rate:      4.50%\n# Monthly:   LKR      187.50","type":"text"}],"id":"401c4841-95d6-4d26-b035-a420f4241af7","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"id":"73c6e789-0d7d-45e5-8b1d-52b1000dbb47","props":{},"type":"divider"},{"children":[],"content":[],"id":"f2d0ef55-69fb-46f2-b7af-91f905b0a123","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[],"id":"0bdfac89-6bf4-4030-a01d-edd14da60b91","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"}]'::jsonb, '3e9e3dd3-a59b-4b02-968a-ee95e7317583') ON CONFLICT ("node_id") DO UPDATE SET "bad_example" = EXCLUDED."bad_example", "completed_at" = EXCLUDED."completed_at", "created_at" = EXCLUDED."created_at", "definition" = EXCLUDED."definition", "good_example" = EXCLUDED."good_example", "is_completed" = EXCLUDED."is_completed", "key_points" = EXCLUDED."key_points", "last_edited" = EXCLUDED."last_edited", "map_id" = EXCLUDED."map_id", "mental_model" = EXCLUDED."mental_model", "notes" = EXCLUDED."notes", "resources" = EXCLUDED."resources", "rich_content" = EXCLUDED."rich_content", "user_id" = EXCLUDED."user_id";
INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-06-11T12:32:32.080557+00:00', '', '', '3efcf92b-00a5-494d-a0f4-7313ed5b77d1', false, '[]'::jsonb, '2026-06-11T12:32:55.1+00:00', '2ad473fe-77dd-481e-8ba7-4b2b0336173f', '', 'd27f1e38-7d1d-4bfa-9bae-7db38eef75ee', '', '[]'::jsonb, '[{"children":[],"content":[{"styles":{},"text":"PYTHON DEBUGGING — MENTAL MODELS\nBank Branch Incident Investigation\n│\n├── 🔍 READING TRACEBACKS ──────────── INCIDENT REPORT\n│   ├── Bank generates a report when something goes wrong\n│   ├── Read from BOTTOM UP — last line = the crime\n│   ├── Top of report = where the chain started\n│   ├── Each line = one call in the chain (who called who)\n│   └── \"Most recent call last\" = bottom line is the culprit\n│\n├── 🖨️ PRINT DEBUGGING ─────────────── POST-IT NOTES\n│   ├── Stick a note at any point → see what''s there\n│   ├── Temporary, manual, removed after investigation\n│   ├── Best for: quick local scripts, one-off checks\n│   ├── Weakness: no timestamps, no severity, clutters code\n│   └── Never leave in production — clean up after use\n│\n├── 📋 LOGGING ─────────────────────── OFFICIAL LOGBOOK\n│   ├── Permanent record kept by branch compliance officer\n│   ├── Every entry has: LEVEL · TIME · SOURCE · MESSAGE\n│   ├── Five severity levels — like incident priority codes\n│   │   ├── DEBUG    → routine internal notes (lowest)\n│   │   ├── INFO     → normal operations confirmed\n│   │   ├── WARNING  → something unusual, still running\n│   │   ├── ERROR    → something failed, needs attention\n│   │   └── CRITICAL → system down, immediate action (highest)\n│   ├── Filter by level — read only what you need\n│   └── Stays in production — controlled, not removed\n│\n├── 🔬 PDB ─────────────────────────── FORENSIC INVESTIGATOR\n│   ├── Investigator FREEZES the branch mid-operation\n│   ├── Steps through each action one at a time\n│   ├── Can inspect every variable at any frozen moment\n│   ├── Can set a specific desk to freeze at (breakpoint)\n│   ├── Can step INTO a transaction or OVER it\n│   └── Most powerful tool — full control of execution\n│\n└── 🧭 DEBUGGING WORKFLOW ──────────── INVESTIGATION PROTOCOL\n    ├── Step 1: READ the incident report (traceback)\n    ├── Step 2: LOCATE the crime scene (which line/function)\n    ├── Step 3: POST-IT notes to confirm your hunch (print)\n    ├── Step 4: LOGBOOK for repeated or production issues\n    ├── Step 5: FREEZE and investigate live (pdb)\n    └── Step 6: Fix → remove post-its → update logbook","type":"text"}],"id":"0194e35d-ee15-4297-be3c-67c488f87496","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"1b75118c-20af-4c4b-a476-f8b6ad3b026e","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"textTHE BANK BRANCH — INCIDENT INVESTIGATION DAY\n\n🔍 Incident Report       → Traceback\n🖨️ Post-It Notes         → print() debugging\n📋 Official Logbook      → logging module\n🔬 Forensic Investigator → pdb\n🧭 Investigation Protocol→ Debugging workflow\n\nEvery bug is an incident at the branch.\nEvery tool is a different way to investigate it.","type":"text"}],"id":"a1d510ed-1f82-436a-9186-1f2d45642a56","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"e5c316cf-f91b-4b55-a413-b92a0abba9a3","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"🔍 Traceback — The Incident Report","type":"text"}],"id":"915d2a3a-5660-4d97-ade0-1f45f4fe5b23","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"When something goes wrong at the bank, a formal incident report is generated automatically. The most recent event is at the bottom — that''s the actual crime. Above it is the chain of who called who to get there.","type":"text"}],"id":"d77c6851-1c50-425c-bd38-dab3b86726b9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Always read bottom-up.","type":"text"}],"id":"0987bc2a-a53d-4566-96b0-76f198581369","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"textTraceback (most recent call last):\n  File \"bank.py\", line 14, in end_of_day\n    process_payment(txn)              ← 3rd: end_of_day called this\n  File \"bank.py\", line 9, in process_payment\n    transfer(txn[''account''], amount)  ← 2nd: process_payment called this\n  File \"bank.py\", line 4, in transfer\n    validate_account(account_id)      ← 1st: transfer called this\n  File \"bank.py\", line 2, in validate_account\n    if account[''status''] == ''active'': ← THE CRIME SCENE\nKeyError: ''status''                    ← READ THIS FIRST ← actual error","type":"text"}],"id":"4c3881ac-97ec-4632-8abf-ed50ba2cfa63","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"How to read it:","type":"text"}],"id":"43db05e1-3a54-4c25-9b1c-af9d960a6436","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"textBottom line  → What went wrong     : KeyError: ''status''\nLine above   → Where it happened   : validate_account, line 2\nLines above  → How we got there    : transfer → process_payment → end_of_day\nTop line     → Where chain started : end_of_day, line 14","type":"text"}],"id":"d90a5471-29f6-454b-962a-4c6a18c17387","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Common error types — what they mean at the branch:","type":"text"}],"id":"6c76873c-91f6-45a4-a205-fae8d514c661","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"textKeyError        → Looked for a desk that doesn''t exist (dict key missing)\nIndexError      → Tried to reach seat 10 in a 5-seat row\nTypeError       → Handed wrong document type to the wrong counter\nAttributeError  → Asked a teller to do something their role doesn''t have\nNameError       → Called an employee who was never hired (undefined variable)\nValueError      → Right document type, wrong content (int(\"hello\"))","type":"text"}],"id":"66fec80f-3655-4ee1-b455-e9c9d3351b77","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"8032dd5b-7354-4cd7-b047-03eedb621357","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"🖨️ print() — The Post-It Notes","type":"text"}],"id":"becd90a5-2a90-4f98-9eac-c74036cf96c2","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"A junior investigator''s first instinct — stick a post-it note at suspicious points to see what''s there. Fast, simple, no setup. But messy and must be removed after.","type":"text"}],"id":"497ba0b3-9fca-4fed-a566-1e5408cbae19","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"pythondef process_payment(txn):\n    print(f\"DEBUG: txn received = {txn}\")            # post-it at entry\n    print(f\"DEBUG: amount = {txn[''amount'']}\")        # post-it on specific value\n\n    result = transfer(txn[''account''], txn[''amount''])\n    print(f\"DEBUG: transfer result = {result}\")      # post-it after transfer\n\n    return result","type":"text"}],"id":"d3408cb2-f70d-4034-ae17-e18e0b0fb7fd","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"The professional upgrade — f-string with context:","type":"text"}],"id":"4069f27e-e392-4e44-bb62-0593f156b425","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"python# Bad post-it — no context\nprint(balance)\n\n# Good post-it — tells you what, where, and value\nprint(f\"[process_payment] balance before deduction: {balance}\")\nprint(f\"[validate_account] account dict keys: {account.keys()}\")\nprint(f\"[transfer] amount type: {type(amount)}, value: {amount}\")","type":"text"}],"id":"53f7ec6b-b628-4ddd-83c1-af48e36fcb5b","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"When to use print():","type":"text"}],"id":"bbf3415f-577e-462d-9440-1c5729099c79","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"text✅ Quick local scripts\n✅ One-off \"what is this variable right now?\"\n✅ Rapid hypothesis testing\n❌ Production code\n❌ Loops with thousands of iterations\n❌ Multi-file systems","type":"text"}],"id":"ba02f1be-3fd6-4b16-964a-3a3aee29fe78","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"71b58334-300c-434f-b839-196268144251","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"📋 logging — The Official Logbook","type":"text"}],"id":"6c339f48-7001-4f9a-b087-5e19b9d67cd0","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The branch compliance officer maintains a permanent logbook. Every significant event is recorded with: ","type":"text"},{"styles":{"bold":true},"text":"severity level · timestamp · which department · what happened.","type":"text"},{"styles":{},"text":" Unlike post-it notes, this stays in production and can be filtered by severity.","type":"text"}],"id":"91282e9b-e832-4e1a-9c22-5874b0547db4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"pythonimport logging\n\n# Set up the logbook — format every entry\nlogging.basicConfig(\n    level=logging.DEBUG,\n    format=''%(asctime)s | %(levelname)s | %(name)s | %(message)s''\n)\n\nlogger = logging.getLogger(''bank.payments'')  # name the department","type":"text"}],"id":"f71d424a-6f78-4913-b4c7-ed83fbeca31d","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"The five severity levels — branch priority codes:","type":"text"}],"id":"9f0a0572-e0f6-4f1b-a47b-90b47e9c66f3","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"pythonlogger.debug(\"Entering validate_account with id=%s\", account_id)\n# DEBUG → routine internal note, lowest priority\n# \"Teller opened the transaction file\"\n\nlogger.info(\"Payment processed successfully: txn_id=%s amount=%s\", txn_id, amount)\n# INFO → normal operation confirmed\n# \"Transaction T001 completed normally\"\n\nlogger.warning(\"Retry attempt %d of 3 for db connection\", attempts)\n# WARNING → unusual but still running\n# \"Network slow — still connected but degraded\"\n\nlogger.error(\"Payment failed: account %s not found\", account_id)\n# ERROR → something failed, needs attention\n# \"Counter had to close — teller unavailable\"\n\nlogger.critical(\"Database connection lost — all operations halted\")\n# CRITICAL → system down, immediate action required\n# \"Branch evacuated — fire confirmed\"","type":"text"}],"id":"f64ec69b-818f-4d85-a3e2-62f0f68588cf","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Filtering — read only what you need:","type":"text"}],"id":"49e7adc8-05c1-48ce-b6d9-8df1575099d2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"python# In development: see everything\nlogging.basicConfig(level=logging.DEBUG)    # DEBUG and above\n\n# In production: only problems\nlogging.basicConfig(level=logging.WARNING)  # WARNING, ERROR, CRITICAL only\n\n# Level hierarchy — each level includes all above it:\n# DEBUG < INFO < WARNING < ERROR < CRITICAL","type":"text"}],"id":"25dcb46e-40dd-439c-9d96-d5a205349b19","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"print() vs logging — side by side:","type":"text"}],"id":"f04434b6-ad16-47f5-b27b-8734c83fdb48","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":{"columnWidths":[null,null,null],"headerRows":1,"rows":[{"cells":[{"content":[],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"print()","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"logging","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Setup","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"None","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"One-time config","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Severity","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"❌ None","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"✅ 5 levels","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Timestamp","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"❌ No","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"✅ Automatic","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Production","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"❌ Remove manually","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"✅ Filter by level","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Output target","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Screen only","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"File, screen, both","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Best for","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Quick local check","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Any real system","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"93599928-8dc0-4a33-a6d7-044566f8df65","props":{"textColor":"default"},"type":"table"},{"children":[],"id":"856f93f0-430b-4dc9-abc5-c984818b532a","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"🔬 pdb — The Forensic Investigator","type":"text"}],"id":"5fb4d8b5-0ed3-46a9-83b7-e1aa8aca3b36","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The most powerful tool. The forensic investigator walks into the branch, ","type":"text"},{"styles":{"bold":true},"text":"freezes everything mid-operation","type":"text"},{"styles":{},"text":", and steps through each action one at a time. They can inspect every variable at every frozen moment, step into a function to see inside, or step over it and keep moving.","type":"text"}],"id":"0aa24fc9-8a49-4d5d-a027-48972a63b1a2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Three ways to start the investigation:","type":"text"}],"id":"43dfebc2-b494-43be-806d-a340bf49bc95","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"python# Method 1 — Plant a freeze point directly in code (breakpoint)\ndef validate_account(account_id):\n    breakpoint()                        # ← FREEZE HERE when execution reaches this\n    if account[''status''] == ''active'':\n        return True\n\n# Method 2 — Old style, same effect\nimport pdb\npdb.set_trace()                         # ← same as breakpoint()\n\n# Method 3 — From terminal, freeze at start\n# python -m pdb bank.py","type":"text"}],"id":"559a85c4-7bc2-4a5f-b32d-584a1bccf1f0","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"The investigator''s commands — what to do when frozen:","type":"text"}],"id":"82e585f7-d35d-44f7-80ac-9843496b9e6c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"text(Pdb) l              → LIST source code around current freeze point\n(Pdb) n              → NEXT line — step OVER the next line (don''t go inside)\n(Pdb) s              → STEP — step INTO the next function (go inside)\n(Pdb) c              → CONTINUE — unfreeze, run until next breakpoint\n(Pdb) q              → QUIT — end investigation entirely\n\n(Pdb) p balance           → PRINT value of variable ''balance''\n(Pdb) p txn               → PRINT entire txn dict\n(Pdb) p type(amount)      → PRINT the type of amount\n(Pdb) p account.keys()    → PRINT all keys in account dict\n\n(Pdb) b 42           → set BREAKPOINT at line 42\n(Pdb) b validate_account  → BREAKPOINT at start of function\n(Pdb) cl             → CLEAR all breakpoints","type":"text"}],"id":"3e852c99-2e1c-460a-86d0-57193ff78e03","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"n vs s — the key distinction:","type":"text"}],"id":"3611d2d4-21f0-4d2c-aa9b-b5778623ea69","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"pythondef validate_account(account_id):\n    breakpoint()\n    result = transfer(account_id, amount)   # ← frozen here\n\n# (Pdb) n   → NEXT: runs transfer() as a black box, moves to next line\n#             investigator doesn''t go inside transfer()\n\n# (Pdb) s   → STEP: jumps INSIDE transfer() and freezes there\n#             investigator follows the chain into the function","type":"text"}],"id":"51ea2e06-d9ae-4581-82b8-e001aa80df33","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"A real investigation walkthrough:","type":"text"}],"id":"bdeac069-f173-4c3d-b880-8ef42faa2a39","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"pythondef process_payment(txn):\n    breakpoint()                           # plant the freeze\n    account = get_account(txn[''account''])\n    if account[''status''] == ''active'':      # ← KeyError here\n        deduct(account, txn[''amount''])","type":"text"}],"id":"db6236fd-b4e0-4d0f-bba0-d27fd98a6690","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"text(Pdb) l                    # see the code\n(Pdb) p txn                # {''account'': ''ACC001'', ''amount'': 5000}\n(Pdb) n                    # run get_account()\n(Pdb) p account            # {''id'': ''ACC001'', ''balance'': 50000}\n                           # ← no ''status'' key! found the crime\n(Pdb) p account.keys()     # dict_keys([''id'', ''balance''])\n                           # confirmed — ''status'' was never set\n(Pdb) q                    # investigation complete","type":"text"}],"id":"7632fe0a-e195-484f-8eff-71f2fdf31d60","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"d18cd7bd-6049-473b-b4ca-bdbaf441d106","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"🧭 The Investigation Protocol — When to Use What","type":"text"}],"id":"a8cae244-3d56-41cf-9087-4b185592e5e1","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"text▶ START: Something went wrong\n│\n▼\n╔══════════════════════════════════════════╗\n║  Is there an error message / traceback? ║\n╚══════════════════════════════════════════╝\n         │               │\n        YES              NO\n         │               │\n         ▼               ▼\n   Read BOTTOM UP    Program runs but\n   Find crime scene  output is wrong\n   Find the chain    (logic bug)\n         │               │\n         ▼               ▼\n╔══════════════╗   ╔══════════════════════════╗\n║ Is it quick? ║   ║ Do I know where roughly? ║\n╚══════════════╝   ╚══════════════════════════╝\n    │      │              │           │\n   YES     NO            YES          NO\n    │      │              │           │\n    ▼      ▼              ▼           ▼\nprint()  logging    breakpoint()   Add print()\npost-it  logbook    + pdb          at entry/exit\n                    freeze + step  points to\n                    inspect live   narrow it down","type":"text"}],"id":"db94ff41-be6d-42b5-b204-52fc98f1f246","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"The complete workflow — one decision at a time:","type":"text"}],"id":"f0d34c8a-b297-4a28-90a7-ec7b4b113b62","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"textStep 1 → READ the traceback bottom-up\nStep 2 → IDENTIFY crime scene (file, line, function)\nStep 3 → HYPOTHESISE — what value must be wrong?\nStep 4 → CONFIRM with print() or pdb → p variable\nStep 5 → FIX the root cause\nStep 6 → REMOVE print() statements\nStep 7 → ADD logging entry at appropriate level\n         (so if it happens again, logbook catches it)","type":"text"}],"id":"57b4bbef-b79b-4976-9744-96cbee32cd50","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"5a980581-ba4e-4cdf-8df7-fe6f7ef0e0b3","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"🔗 Everything Connected — One Incident at the Bank","type":"text"}],"id":"0c5eb496-ab52-403a-9031-d7813de6491c","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"pythonimport logging\nimport pdb\n\nlogging.basicConfig(\n    level=logging.DEBUG,\n    format=''%(asctime)s | %(levelname)s | %(message)s''\n)\nlogger = logging.getLogger(''bank.payments'')\n\ndef validate_account(account):\n    # 📋 LOGBOOK — routine entry at DEBUG level\n    logger.debug(\"Validating account: %s\", account.get(''id''))\n\n    if ''status'' not in account:\n        # 📋 LOGBOOK — error entry, this is a real failure\n        logger.error(\"Account missing ''status'' key: %s\", account)\n        raise KeyError(\"status\")\n\n    if account[''status''] != ''active'':\n        # 📋 LOGBOOK — warning, unusual but handled\n        logger.warning(\"Inactive account attempted: %s\", account[''id''])\n        return False\n\n    return True\n\ndef process_payment(txn):\n    # 📋 LOGBOOK — info, normal operation\n    logger.info(\"Processing payment txn_id=%s amount=%s\", txn[''id''], txn[''amount''])\n\n    # 🖨️ POST-IT — temporary, remove after confirming\n    # print(f\"DEBUG txn keys: {txn.keys()}\")\n\n    account = get_account(txn[''account''])\n\n    # 🔬 INVESTIGATOR — uncomment when investigating a freeze point\n    # breakpoint()\n\n    if not validate_account(account):\n        logger.warning(\"Payment rejected — inactive account: %s\", txn[''account''])\n        return \"Rejected\"\n\n    deduct(account, txn[''amount''])\n    logger.info(\"Payment complete: %s\", txn[''id''])\n    return \"Success\"","type":"text"}],"id":"f4c0ae41-0707-48fc-91e6-9e36fe4c9934","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"1d047655-cc9e-4aa5-8bcf-85385c1e93f3","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"🧠 The Master Mental Model","type":"text"}],"id":"5748bf6d-c8f1-470f-b5b8-06e3da8e2160","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"textTHE BRANCH INCIDENT INVESTIGATION\n\n🔍 Incident Report        → Traceback (read bottom-up)\n🖨️ Post-It Notes          → print() — quick, temporary, local\n📋 Official Logbook       → logging — permanent, levelled, production\n🔬 Forensic Investigator  → pdb — freeze, step, inspect live\n🧭 Investigation Protocol → workflow: read → locate → hypothesise → confirm → fix\n\nRule of thumb:\n  New error?           → Read traceback first\n  Quick check?         → print()\n  Production system?   → logging\n  Logic bug?           → pdb breakpoint()\n  Finished?            → Remove print(), keep logging","type":"text"}],"id":"4124bc9a-b6bf-4682-873d-9d1f0bb2392c","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[],"id":"896016fe-3f0a-4cfd-a3da-13106c21cd1d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"}]'::jsonb, '3e9e3dd3-a59b-4b02-968a-ee95e7317583') ON CONFLICT ("node_id") DO UPDATE SET "bad_example" = EXCLUDED."bad_example", "completed_at" = EXCLUDED."completed_at", "created_at" = EXCLUDED."created_at", "definition" = EXCLUDED."definition", "good_example" = EXCLUDED."good_example", "is_completed" = EXCLUDED."is_completed", "key_points" = EXCLUDED."key_points", "last_edited" = EXCLUDED."last_edited", "map_id" = EXCLUDED."map_id", "mental_model" = EXCLUDED."mental_model", "notes" = EXCLUDED."notes", "resources" = EXCLUDED."resources", "rich_content" = EXCLUDED."rich_content", "user_id" = EXCLUDED."user_id";
INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-06-14T11:28:55.356772+00:00', '', '', '339f9545-dbb0-4ff3-8165-d26f186194ef', false, '[]'::jsonb, '2026-06-14T12:17:03.152+00:00', '2ad473fe-77dd-481e-8ba7-4b2b0336173f', '', '9b228c6e-b42d-4b8f-9ac6-7da2fac2a7b3', '', '[]'::jsonb, '[{"children":[],"content":[{"styles":{},"text":"Apache Spark — Conceptual Foundation — Interview-Ready Note","type":"text"}],"id":"b77bf15f-b000-4b2f-80ab-41957694a521","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Target:","type":"text"},{"styles":{},"text":" Sysco LABS · EY GDS · Dialog Axiata — Data Engineering Intern / Junior Data Engineer","type":"text"}],"id":"d091a482-6600-4186-8f7c-57eda63b8a7e","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"dbeee840-b7e6-48f9-bd2a-a58a0e59e913","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"1. Mental Model","type":"text"}],"id":"80224c0c-a081-420b-97af-13b05b4d59f9","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Pandas is like one person doing all the work on one desk.","type":"text"},{"styles":{},"text":" ","type":"text"},{"styles":{"bold":true},"text":"Spark is like a manager dividing a large job among many workers.","type":"text"}],"id":"8b282d73-ad99-44c0-8b13-0b54f41b0307","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{},"text":"Imagine you need to process 10 million sales records to calculate monthly revenue by region.","type":"text"}],"id":"171178e2-91f0-4f0f-bccc-5fbbea2f7ccb","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"331ccb52-a47c-4255-a64a-0b2ee40f35c6","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Pandas — The Solo Worker","type":"text"}],"id":"67aaacad-e7ed-428c-b3c5-85986d789d69","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"You sit at one desk with a powerful computer. You open the entire dataset in memory. You filter, group, and aggregate — all on your machine. It works fine for small datasets. But when the file is 50 GB and your laptop has 16 GB RAM, the program crashes. Even if it doesn''t crash, it might take hours.","type":"text"}],"id":"32569efd-6c8a-4215-832c-0286c59bd556","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"You''re constrained by ","type":"text"},{"styles":{"bold":true},"text":"one machine''s memory and CPU","type":"text"},{"styles":{},"text":". That''s Pandas.","type":"text"}],"id":"df0bccd9-79e0-47cb-ab02-e798356e0698","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"5f076d95-9bed-4af0-824a-3386c6aadd74","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Spark — The Manager and Workers","type":"text"}],"id":"77072a39-bac1-4b94-b90f-fc4dfac009bb","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Now imagine you''re a ","type":"text"},{"styles":{"bold":true},"text":"manager","type":"text"},{"styles":{},"text":" (the ","type":"text"},{"styles":{"bold":true},"text":"Driver","type":"text"},{"styles":{},"text":") with a team of ","type":"text"},{"styles":{"bold":true},"text":"10 workers","type":"text"},{"styles":{},"text":" (the ","type":"text"},{"styles":{"bold":true},"text":"Executors","type":"text"},{"styles":{},"text":").","type":"text"}],"id":"a007d0fd-e7fa-4158-9a21-d19e36850ec0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"You divide the 10 million records into ","type":"text"},{"styles":{"bold":true},"text":"10 equal chunks","type":"text"},{"styles":{},"text":" (called ","type":"text"},{"styles":{"bold":true},"text":"partitions","type":"text"},{"styles":{},"text":") — one chunk per worker. Each worker independently processes their chunk in parallel on their own machine. When all workers finish, you collect the results and combine them.","type":"text"}],"id":"aaa5bc0b-0876-49ee-864f-3ffba74ffca9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"What took one person hours now takes 10 workers a few minutes — because the work is ","type":"text"},{"styles":{"bold":true},"text":"distributed","type":"text"},{"styles":{},"text":" and happens in ","type":"text"},{"styles":{"bold":true},"text":"parallel","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"34257740-7ac3-4439-ac36-692dd21d8097","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"139d0333-edda-4bbf-9b02-702b80a123d3","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"The Mapping","type":"text"}],"id":"16bafb11-8f82-4b41-8d95-2225d04577f0","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Concept","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Mental Model","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Driver","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"The manager who coordinates the job and collects results","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Executors","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"The workers who actually process the data in parallel","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Cluster Manager","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"The resource allocator (like HR) that assigns workers to the manager","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Partitions","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Chunks of work split among the workers","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Transformations","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Planning the work — \"filter this, group that\" — but not doing it yet","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Actions","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Actually starting the work — \"now execute the plan and show me results\"","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Shuffle","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Workers exchanging data with each other when needed (e.g., grouping by region requires moving all \"Western\" records to one worker)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"499107a7-aed8-4bd0-b551-c74cfd1f3a01","props":{"textColor":"default"},"type":"table"},{"children":[],"content":[{"styles":{"bold":true},"text":"This mental model is enough to explain Spark''s value to anyone — including a non-technical interviewer.","type":"text"}],"id":"9c063fd1-c5de-46a1-a970-717ec21242c7","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"0688dfaa-71f8-4079-ba5a-b83ffc0f7876","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"2. Clear Concept Explanation","type":"text"}],"id":"8362cdc1-8dd3-4a1c-a624-3a2d0dfa5783","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"What is Apache Spark?","type":"text"}],"id":"6950b475-27af-428f-acd1-0c226a04819c","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Apache Spark","type":"text"},{"styles":{},"text":" is an ","type":"text"},{"styles":{"bold":true},"text":"open-source, distributed data processing engine","type":"text"},{"styles":{},"text":" designed to process large-scale datasets across a cluster of machines in parallel.","type":"text"}],"id":"86940dc1-cfe1-4c22-a5c3-fbac7b06d808","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"It is the ","type":"text"},{"styles":{"bold":true},"text":"de facto standard","type":"text"},{"styles":{},"text":" for big data processing in modern data engineering.","type":"text"}],"id":"7c44a953-8d62-474c-9113-4fb0ecc3ede8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Why Does Spark Exist?","type":"text"}],"id":"d638afae-cf9d-4800-ac94-afcc965e62a0","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Traditional single-machine tools (like Pandas, Excel, single-node SQL databases) hit fundamental limits:","type":"text"}],"id":"8f762175-f566-4e5a-ae31-134166e9839d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Memory constraints","type":"text"},{"styles":{},"text":" — a 100 GB dataset doesn''t fit in 16 GB RAM","type":"text"}],"id":"7977d8ad-d517-4586-8b38-b390dda0570e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"CPU constraints","type":"text"},{"styles":{},"text":" — one CPU core processing millions of rows is slow","type":"text"}],"id":"17bcc198-75db-40c1-b2c4-7f19952b626f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Disk I/O constraints","type":"text"},{"styles":{},"text":" — reading/writing massive files on one disk is a bottleneck","type":"text"}],"id":"b56bf94c-f8f3-41f8-9df2-72f3c122f953","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Spark exists to solve the ","type":"text"},{"styles":{"bold":true},"text":"scale problem","type":"text"},{"styles":{},"text":" by distributing data and computation across many machines.","type":"text"}],"id":"80612db5-1352-4b60-a2dd-b41c3e883306","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Why Pandas/Single-Machine Processing Struggles with Large Data","type":"text"}],"id":"67456ec9-46cc-4bc8-91aa-ec5d2934035a","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Pandas loads the entire dataset into the memory of ","type":"text"},{"styles":{"bold":true},"text":"one machine","type":"text"},{"styles":{},"text":". When data exceeds available RAM:","type":"text"}],"id":"c15d5b18-b16c-4bd6-bd87-b2dfbc3e9341","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"The process crashes with ","type":"text"},{"styles":{"code":true},"text":"MemoryError","type":"text"}],"id":"6caaf3dd-760f-443b-9111-706c76c661e0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Even if it doesn''t crash, swapping to disk makes it extremely slow","type":"text"}],"id":"c8c6424c-3bc8-4488-93e8-824470da6d83","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"There''s no way to use additional machines — Pandas is inherently single-node","type":"text"}],"id":"3d4dcba8-8243-4f07-a784-84a02cf6b0c9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Example:","type":"text"}],"id":"baf3ff6d-71a7-4ec0-a655-e020abdf6162","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Dataset: 50 GB CSV","type":"text"}],"id":"212c8bfb-d306-479a-9251-f2be3cfcf5be","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Your laptop: 16 GB RAM","type":"text"}],"id":"5892de1d-2938-4d0c-bc6c-fa768fcb7b89","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Pandas: Tries to load all 50 GB → crashes","type":"text"}],"id":"6459ce1f-99c1-44a0-a316-e23aa2f4a31d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Spark solves this by:","type":"text"}],"id":"69ba6250-dc2e-4501-bed0-24381854b443","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Splitting the 50 GB into smaller chunks (partitions)","type":"text"}],"id":"567ef976-c056-4391-a7c6-b5d11173e69d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Distributing those partitions across many machines","type":"text"}],"id":"f92a27c6-904b-49ab-b943-4709b460c9bf","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Each machine processes only its partition — which fits in memory","type":"text"}],"id":"eb72c6d2-8034-425a-9f34-0dce19b929df","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Processing happens in parallel across all machines","type":"text"}],"id":"996e3064-8b0e-42df-a66a-95bc9d139995","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"How Spark Uses Distributed Processing","type":"text"}],"id":"226c13c2-ac24-4768-93da-1c9becc3f0a9","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Spark divides work into three layers:","type":"text"}],"id":"c41a3707-0a3e-4f52-a236-64c453fbd354","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Driver Program","type":"text"},{"styles":{},"text":" — coordinates the job","type":"text"}],"id":"9f10973d-3563-4cdb-a4e5-4e23b15eb28a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Cluster Manager","type":"text"},{"styles":{},"text":" — allocates resources (machines, memory, CPU)","type":"text"}],"id":"595451c7-c93e-4827-9ccf-f8de7f2ef3f6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Executors","type":"text"},{"styles":{},"text":" — worker processes that execute the actual data transformations on partitions","type":"text"}],"id":"2e7ccd8e-76ac-46d4-bb8c-7550cea779bd","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"The data itself is split into ","type":"text"},{"styles":{"bold":true},"text":"partitions","type":"text"},{"styles":{},"text":" — independent chunks that can be processed in parallel without interfering with each other.","type":"text"}],"id":"a1c1558b-1bd2-42a2-b0b6-182a74893c10","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"0eda0b6e-764a-4f40-a928-d8e147e0dd28","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"What the Driver Does","type":"text"}],"id":"dc34cad4-1476-4f7a-b049-c3a4de2af2fd","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The ","type":"text"},{"styles":{"bold":true},"text":"Driver","type":"text"},{"styles":{},"text":" is the ","type":"text"},{"styles":{"bold":true},"text":"brain","type":"text"},{"styles":{},"text":" of a Spark application. It:","type":"text"}],"id":"a386bf73-3769-4e67-b731-1756324da1e6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Runs your PySpark script (the code you write)","type":"text"}],"id":"a9b34716-9c77-4c63-a2b1-c3d3a6f2d524","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Creates the execution plan (the logical and physical plan of transformations)","type":"text"}],"id":"b63bcd3d-6539-4865-b875-ea40001092e6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Coordinates Executors — tells them what to do","type":"text"}],"id":"79c5c95f-288b-4159-b902-93c5e8c1b16f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Collects results from Executors and returns them to you","type":"text"}],"id":"af4b7e23-d80a-4bfe-941f-e8bf92af2858","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Mental Model:","type":"text"},{"styles":{},"text":" The Driver is the manager who reads the blueprint, divides tasks, and supervises workers.","type":"text"}],"id":"b431937f-6c88-4400-8159-c60a2391c174","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{},"text":"The Driver runs on ","type":"text"},{"styles":{"bold":true},"text":"one machine","type":"text"},{"styles":{},"text":" (often your laptop when running locally, or a dedicated node in a cluster).","type":"text"}],"id":"fdea7cb0-f8ce-4d44-812b-8ad5f76a4df6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"1bd7c942-44e1-4f20-bb07-681e9d43dda2","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"What Executors Do","type":"text"}],"id":"0cc53322-3629-4e05-aa51-b1aac44612a0","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Executors","type":"text"},{"styles":{},"text":" are the ","type":"text"},{"styles":{"bold":true},"text":"workers","type":"text"},{"styles":{},"text":". They:","type":"text"}],"id":"55b94651-c373-4d2c-a1e0-a8d00f7ae4df","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Run on separate machines (or separate processes on the same machine in local mode)","type":"text"}],"id":"dfe83fdd-c3d4-43d4-99c3-1957d468a067","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Store data partitions in memory","type":"text"}],"id":"f9a35c66-4b16-4e16-91e6-c655cbcb44bf","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Execute transformations on their assigned partitions","type":"text"}],"id":"06082cbb-213e-4ed9-ae05-4e4c76eb8cad","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Return results to the Driver when asked","type":"text"}],"id":"865e7b6c-0c49-41f0-bc04-a71e3e2ac895","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Mental Model:","type":"text"},{"styles":{},"text":" Executors are the factory workers who actually process the data chunks in parallel.","type":"text"}],"id":"460113d8-c129-47d6-bbc5-1e9354665585","props":{"backgroundColor":"default","textColor":"default"},"ty