lspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Data must be serialized to send over network, then deserialized","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Memory Pressure","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Shuffles can cause memory spikes, leading to spilling to disk","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"bab3ea63-0cbf-4eb5-b219-4e65a4ac3313","props":{"textColor":"default"},"type":"table"},{"children":[],"content":[{"styles":{},"text":"A shuffle can easily be ","type":"text"},{"styles":{"bold":true},"text":"10x-100x slower","type":"text"},{"styles":{},"text":" than in-memory transformations.","type":"text"}],"id":"b34049a4-94a6-4434-9829-7c7bcf08ebb7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"a3b7ec02-a26b-48b9-b9ff-5f3a888a0632","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Which Operations Cause Shuffle","type":"text"}],"id":"47e252e0-6952-4c0c-89ec-98cfbd36fad1","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Operation","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Why It Shuffles","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"groupBy()","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Groups data by key — requires collecting all rows with the same key","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"join()","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Matches rows from two DataFrames — requires co-locating matching keys","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"distinct()","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Removes duplicates — must compare all rows globally","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"orderBy()","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Sorts data — requires global ordering across partitions","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"repartition()","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Explicitly redistributes data into N partitions","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"55181736-e513-4eac-a55e-93c77f561107","props":{"textColor":"default"},"type":"table"},{"children":[],"content":[{"styles":{"bold":true},"text":"Operations that do NOT shuffle:","type":"text"}],"id":"722f8954-d91d-46bb-af97-2096b6f7dba3","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"code":true},"text":"select()","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"filter()","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"withColumn()","type":"text"},{"styles":{},"text":" — work independently per partition","type":"text"}],"id":"70492bb2-5925-4598-8758-774364721055","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"code":true},"text":"map()","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"flatMap()","type":"text"},{"styles":{},"text":" — row-by-row transformations","type":"text"}],"id":"6cf51173-e7a7-4595-b802-a1dc28a70be8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"id":"ffea5155-681b-4450-aba0-80638aa1b061","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Simple Example — GroupBy Causes Shuffle","type":"text"}],"id":"06cb5d17-943b-4074-9696-281b2679ff96","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Scenario:","type":"text"},{"styles":{},"text":" Calculate total sales by region.","type":"text"}],"id":"348d3dbc-4eae-4d0c-a2e5-6e999e7cfcf6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"sales_df = spark.read.parquet(\"s3://bucket/sales/\")\n\n# GroupBy causes shuffle\nresult = sales_df.groupBy(\"region\").sum(\"amount\")\n\nresult.show()","type":"text"}],"id":"5bff1923-667c-42c2-b615-5ded5913122e","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"What happens:","type":"text"}],"id":"6172e490-4efa-4f5e-a266-42db90e434b7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Data is partitioned randomly across Executors","type":"text"}],"id":"64934c9d-7ac7-4acc-99ed-1077f78689cb","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Spark initiates a ","type":"text"},{"styles":{"bold":true},"text":"shuffle","type":"text"},{"styles":{},"text":" — all \"Western\" sales move to one partition, \"Central\" to another, etc.","type":"text"}],"id":"f831d9e8-2b49-4a33-8398-e0197edc48ee","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Each partition independently sums the sales for its assigned region","type":"text"}],"id":"d56a7973-e845-4049-8158-27e4128a2494","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Results are collected and displayed","type":"text"}],"id":"b1528b1e-dd5f-4c08-96c9-40c8b7b66b79","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"id":"f4e55451-073c-45e0-a32f-76f2ceb255f1","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Why Interns Need Awareness But Not Advanced Optimization","type":"text"}],"id":"5634fab4-8fa8-4d88-970d-7ec5c75b3479","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"At intern level:","type":"text"}],"id":"19d6e2a2-bc46-42d5-ada5-48296c19d55c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Know that shuffle exists and is expensive","type":"text"}],"id":"e7675cf2-6e9c-4bb2-84f4-8df3e0708156","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Understand which operations cause it","type":"text"}],"id":"84d6f7cf-98ea-4522-abb8-27a2dd757416","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Avoid unnecessary shuffles when possible (e.g., filter before groupBy to reduce data volume)","type":"text"}],"id":"2cbc77c7-f2f6-47f7-92c4-6a20011bfe0b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Beyond intern level:","type":"text"}],"id":"f45711f2-a31e-40aa-b913-a01e6e7659cf","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Tuning ","type":"text"},{"styles":{"code":true},"text":"spark.sql.shuffle.partitions","type":"text"}],"id":"4bf27526-7daf-4e17-9c42-7492a8841804","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Broadcast joins for small tables","type":"text"}],"id":"bf9a376c-640f-4c1f-9926-6f5fa146f679","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Salting techniques for skewed data","type":"text"}],"id":"b54b379a-217b-45b0-aa9c-41b7669eb573","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Bucketing and partitioning strategies","type":"text"}],"id":"e33b42a5-fab7-4042-9179-6419a0686b13","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Interview tip:","type":"text"},{"styles":{},"text":" If asked about shuffle, explain what it is, why it''s needed, and that it''s expensive. You don''t need to explain optimization techniques unless specifically asked.","type":"text"}],"id":"a5820a8f-18f7-4067-8b91-a2928281ac33","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"54356174-6252-4585-a470-b2c591040aff","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"9. Practical Example","type":"text"}],"id":"62958b9d-7cd2-4ca6-a65b-b3b290919cb6","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Scenario: Bronze to Gold Sales Pipeline","type":"text"}],"id":"814d52f0-4f7a-4860-997f-444edd9e5bf2","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"A retail company stores raw sales data in the ","type":"text"},{"styles":{"bold":true},"text":"Bronze layer","type":"text"},{"styles":{},"text":" as Parquet files on S3. You need to:","type":"text"}],"id":"a87c4a8f-1aa7-4b07-b5b6-0379f33b0500","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Read the raw sales data","type":"text"}],"id":"42cee2b6-a173-40e9-a5d1-b8360448ef28","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Filter out invalid records (null ","type":"text"},{"styles":{"code":true},"text":"order_id","type":"text"},{"styles":{},"text":")","type":"text"}],"id":"81675573-d4c4-4e8e-8297-6a5612a9655f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Calculate total revenue by region and month","type":"text"}],"id":"dfd6a258-a0ea-40ac-8cc8-e1dd2882eef4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Write the results to the ","type":"text"},{"styles":{"bold":true},"text":"Gold layer","type":"text"},{"styles":{},"text":" for BI reporting","type":"text"}],"id":"7626d722-c601-4740-89b6-c777e72993ec","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"id":"4e890a80-99ea-429e-b1de-b1efa07291a3","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"PySpark Code","type":"text"}],"id":"f9fd1844-491e-4712-a2f3-3116f6e9386d","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"from pyspark.sql import SparkSession\nfrom pyspark.sql.functions import col, month, year, sum as spark_sum\n\n# Initialize Spark session\nspark = SparkSession.builder \\\n    .appName(\"SalesAggregation\") \\\n    .getOrCreate()\n\n# ─────────────────────────────────────────────────────\n# Step 1: Read raw sales data from Bronze (Transformation — lazy)\n# ─────────────────────────────────────────────────────\nsales_df = spark.read.parquet(\"s3://datalake/bronze/sales/\")\n\n# ─────────────────────────────────────────────────────\n# Step 2: Filter invalid records (Transformation — lazy)\n# ─────────────────────────────────────────────────────\nclean_df = sales_df.filter(col(\"order_id\").isNotNull())\n\n# ─────────────────────────────────────────────────────\n# Step 3: Add month and year columns (Transformation — lazy)\n# ─────────────────────────────────────────────────────\nenriched_df = clean_df \\\n    .withColumn(\"month\", month(col(\"order_date\"))) \\\n    .withColumn(\"year\", year(col(\"order_date\")))\n\n# ─────────────────────────────────────────────────────\n# Step 4: Group by region and month, sum revenue (Transformation — lazy)\n# ─────────────────────────────────────────────────────\nresult_df = enriched_df \\\n    .groupBy(\"region\", \"year\", \"month\") \\\n    .agg(spark_sum(\"amount\").alias(\"total_revenue\"))\n\n# ─────────────────────────────────────────────────────\n# Step 5: Write results to Gold layer (Action — triggers execution)\n# ─────────────────────────────────────────────────────\nresult_df.write \\\n    .mode(\"overwrite\") \\\n    .partitionBy(\"year\", \"month\") \\\n    .parquet(\"s3://datalake/gold/sales_by_region/\")\n\nprint(\"Pipeline completed successfully!\")","type":"text"}],"id":"d1c1ce2b-6278-4dbb-af0a-3694d6d596f2","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"1969c90d-4f67-4611-bd7e-2cd5f5967a92","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Explanation of Each Line","type":"text"}],"id":"7ee92640-f9de-4aaa-aa90-d97504f9cda0","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":{"columnWidths":[null,null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Line","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Type","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"What It Does","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"spark.read.parquet(...)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"Transformation","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Defines a DataFrame from the Parquet files in Bronze — does not load data yet","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":".filter(col(\"order_id\").isNotNull())","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"Transformation","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Adds a filter step to the plan — removes rows with null ","type":"text"},{"styles":{"code":true},"text":"order_id","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":".withColumn(\"month\", month(...))","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"Transformation","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Adds a new column ","type":"text"},{"styles":{"code":true},"text":"month","type":"text"},{"styles":{},"text":" derived from ","type":"text"},{"styles":{"code":true},"text":"order_date","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":".groupBy(\"region\", \"year\", \"month\")","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"Transformation","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Groups rows by region, year, and month — ","type":"text"},{"styles":{"bold":true},"text":"causes shuffle","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":".agg(spark_sum(\"amount\"))","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"Transformation","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Aggregates within each group — sums the ","type":"text"},{"styles":{"code":true},"text":"amount","type":"text"},{"styles":{},"text":" column","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":".write.parquet(...)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"Action","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"Triggers execution","type":"text"},{"styles":{},"text":" — reads Bronze, applies all transformations, writes to Gold","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"9a6092db-ae32-475b-8f6a-d60e65d23004","props":{"textColor":"default"},"type":"table"},{"children":[],"content":[{"styles":{"bold":true},"text":"Until ","type":"text"},{"styles":{"code":true},"text":".write()","type":"text"},{"styles":{"bold":true},"text":" is called, nothing executes.","type":"text"},{"styles":{},"text":" Spark builds the DAG and waits.","type":"text"}],"id":"7ee9ec18-75a0-4484-9018-3818c626184c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"When ","type":"text"},{"styles":{"code":true},"text":".write()","type":"text"},{"styles":{},"text":" runs:","type":"text"}],"id":"7fd4b2a3-c44e-4f24-ae44-7da493408d95","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Spark reads the Bronze Parquet files","type":"text"}],"id":"c14584a7-dcb7-4d97-b80f-667307ccecea","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Filters invalid rows","type":"text"}],"id":"f60574f3-a495-4710-bcc9-6ca289d91ccf","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Adds month/year columns","type":"text"}],"id":"4641aefb-43ac-4850-afcf-b3e98067d5a5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Shuffles","type":"text"},{"styles":{},"text":" data to group by region and month","type":"text"}],"id":"ddc49d9c-e661-4c7b-91a2-a5d7a42d9f21","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Aggregates revenue per group","type":"text"}],"id":"9c6eb0b3-3f78-4fb5-8a3a-368fb31762ed","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Writes results to Gold as partitioned Parquet files","type":"text"}],"id":"b72dbdc5-7785-466f-a4df-8fe8f9217ae9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"id":"0c1ae2b1-be66-41db-8901-b3579c7b3a28","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"10. Interview-Level Understanding","type":"text"}],"id":"ecdbd1f7-300f-4ffa-8a51-b881a15f8ad5","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Interview Question 1:","type":"text"}],"id":"bfd91b97-6a40-4028-8797-1bf9e3384e67","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"\"Why use Spark instead of Pandas?\"","type":"text"}],"id":"386f65bf-ec4e-438d-bcec-34df9999258b","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{},"text":"Strong Answer:","type":"text"}],"id":"1a46fe1d-e102-4fc3-8e86-ee58a3524e6c","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"Pandas is a single-machine library — the entire dataset must fit in memory on one machine. This works well for small to medium datasets, typically up to a few gigabytes depending on available RAM. But when data exceeds memory capacity, Pandas either crashes with a MemoryError or becomes extremely slow due to swapping to disk.","type":"text"}],"id":"e9930651-7149-42e3-8f39-af81adfc8d93","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"Spark solves this by using distributed processing. It splits the dataset into partitions and distributes those partitions across multiple machines in a cluster. Each machine processes only its partition in parallel, and the results are combined. This allows Spark to handle datasets that are terabytes or even petabytes in size — far beyond what any single machine could hold.","type":"text"}],"id":"fcc6d604-f37e-4aed-bb68-ff1df16669ca","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"In a production data engineering pipeline, especially in a Medallion Architecture processing Bronze to Gold layers, the data volumes often reach hundreds of gigabytes or more. Spark is designed for exactly this use case — scalable, fault-tolerant, distributed data processing. Pandas is great for exploratory analysis on small datasets, but for production ETL at scale, Spark is the standard.\"","type":"text"}],"id":"3a8af942-4317-45d3-878b-272e5bd999ad","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"811d9074-62d0-478b-b7c8-7e98fcb95236","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Interview Question 2:","type":"text"}],"id":"6446d0a9-5f17-420e-a602-b96745bee5b2","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"\"What is the difference between Driver and Executor?\"","type":"text"}],"id":"8c9d16cf-6d85-48fb-870e-ff9c6cb26950","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{},"text":"Strong Answer:","type":"text"}],"id":"beb96363-1a56-49ab-904c-a6cba40fddc7","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"The Driver and Executors have completely different roles in a Spark application.","type":"text"}],"id":"75036600-27bd-418f-93f2-a8beb87f7417","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"The ","type":"text"},{"styles":{"bold":true,"italic":true},"text":"Driver","type":"text"},{"styles":{"italic":true},"text":" is the coordinator. It runs your PySpark code, builds the logical execution plan, optimizes it into a physical plan using the Catalyst optimizer, and then distributes tasks to the Executors. The Driver also collects results from the Executors and returns them to you. It runs on a single machine — often your laptop in local mode, or a dedicated master node in a cluster.","type":"text"}],"id":"76060d69-185a-4615-9473-a1bb32d30f00","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"The ","type":"text"},{"styles":{"bold":true,"italic":true},"text":"Executors","type":"text"},{"styles":{"italic":true},"text":" are the workers. They run on separate machines across the cluster. Each Executor stores data partitions in memory and executes the actual transformations on those partitions in parallel. When an action is triggered, the Driver tells each Executor which tasks to run, and the Executors process their assigned data independently. Once finished, they send results back to the Driver.","type":"text"}],"id":"060db975-fb84-48d7-ab2d-3421d36227d3","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"So the Driver is the brain that plans and coordinates, while Executors are the hands that do the actual data processing work in parallel.\"","type":"text"}],"id":"25fdd3b4-e173-47e1-be10-037d560759eb","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"485d77b1-02b7-4b2f-b308-b205129940bd","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Interview Question 3:","type":"text"}],"id":"193eab1b-0bde-4312-96e0-6fcff1824c39","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"\"What is the difference between transformation and action?\"","type":"text"}],"id":"d7765a9f-cc18-40c5-b32d-61f4fc25a47d","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{},"text":"Strong Answer:","type":"text"}],"id":"9569267f-e3a8-4d13-ac2a-8421221d4013","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"The key difference is that transformations are lazy — they don''t execute immediately — while actions trigger execution.","type":"text"}],"id":"bb8149a8-2a18-4e63-9fac-fc548db556c8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"A ","type":"text"},{"styles":{"bold":true,"italic":true},"text":"transformation","type":"text"},{"styles":{"italic":true},"text":" is an operation that defines a new DataFrame from an existing one, like ","type":"text"},{"styles":{"code":true},"text":"filter","type":"text"},{"styles":{"italic":true},"text":", ","type":"text"},{"styles":{"code":true},"text":"select","type":"text"},{"styles":{"italic":true},"text":", ","type":"text"},{"styles":{"code":true},"text":"groupBy","type":"text"},{"styles":{"italic":true},"text":", or ","type":"text"},{"styles":{"code":true},"text":"join","type":"text"},{"styles":{"italic":true},"text":". When you call a transformation, Spark doesn''t actually run it. Instead, Spark records the operation in a logical execution plan — essentially a blueprint of what to do when you eventually ask for results. This is called lazy evaluation.","type":"text"}],"id":"abe1e25b-9e62-45dc-9d93-5a1717fac270","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"An ","type":"text"},{"styles":{"bold":true,"italic":true},"text":"action","type":"text"},{"styles":{"italic":true},"text":" is an operation that triggers the execution of all the transformations in the plan and returns a result. Examples are ","type":"text"},{"styles":{"code":true},"text":"show","type":"text"},{"styles":{"italic":true},"text":", ","type":"text"},{"styles":{"code":true},"text":"count","type":"text"},{"styles":{"italic":true},"text":", ","type":"text"},{"styles":{"code":true},"text":"collect","type":"text"},{"styles":{"italic":true},"text":", or ","type":"text"},{"styles":{"code":true},"text":"write","type":"text"},{"styles":{"italic":true},"text":". When you call an action, Spark finally executes the entire pipeline — reads the data, applies all the transformations, and produces the output.","type":"text"}],"id":"2810f012-991c-458e-9a05-32d9378895d8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"Lazy evaluation allows Spark to optimize the entire pipeline before executing. For example, Spark can reorder operations, push filters down to reduce data early, and eliminate unnecessary steps. This makes the execution more efficient than if each transformation ran immediately.\"","type":"text"}],"id":"2a75386a-5598-40f2-8f14-b4a4c41f46ef","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"8e01ac64-5e0a-44b1-83e4-d6c8d73974f0","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Interview Question 4:","type":"text"}],"id":"d15279bc-8149-4106-b690-abc7b0b6dcad","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"\"What is lazy evaluation and why does Spark use it?\"","type":"text"}],"id":"1a512edf-1148-4d20-b702-cc6d790fba1d","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{},"text":"Strong Answer:","type":"text"}],"id":"d6370e5f-2047-44c2-ba15-9ded6b38a4ab","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"Lazy evaluation means that transformations are not executed when you write them — they''re only executed when an action is called.","type":"text"}],"id":"5ddd8a1d-d03f-4d8d-881b-0a1aa6d229f1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"Spark uses lazy evaluation for two main reasons: optimization and fault tolerance.","type":"text"}],"id":"b30a0c51-2396-478a-acd0-a4f8e7a7a3f2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"First, ","type":"text"},{"styles":{"bold":true,"italic":true},"text":"optimization","type":"text"},{"styles":{"italic":true},"text":". Because Spark sees the entire pipeline of transformations before executing, it can analyze and optimize the plan. For example, if you filter data and then select specific columns, Spark can push the filter down to read less data from storage, and it can prune columns to only read the ones you actually need. If transformations executed immediately, Spark wouldn''t have this global view to optimize.","type":"text"}],"id":"324f291e-fa77-4214-aed0-ea5bcc942615","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"Second, ","type":"text"},{"styles":{"bold":true,"italic":true},"text":"fault tolerance","type":"text"},{"styles":{"italic":true},"text":". If a partition fails during execution, Spark can recompute just that partition using the logical plan it has stored — the lineage of transformations. It doesn''t need to restart the entire job from scratch.","type":"text"}],"id":"cc935b40-9f20-4f52-8c12-a4cbb82e3a19","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"This design makes Spark both faster and more resilient than eager execution models.\"","type":"text"}],"id":"348a34dd-ebb8-41bb-a29a-b7aaece7ab44","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"8a7defc3-1569-45df-8b40-c37e6f1c9c95","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Interview Question 5:","type":"text"}],"id":"eb19736f-7128-4d5a-86fb-5baefeff7a1d","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"\"Why is shuffle expensive?\"","type":"text"}],"id":"1e98d487-68a0-41ea-9a2a-7b34e2b95e05","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{},"text":"Strong Answer:","type":"text"}],"id":"6dc1f58c-2cb7-491d-a142-cfd4a1e161b8","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"Shuffle is expensive because it involves moving data across the network between Executors, which is fundamentally slower than in-memory processing.","type":"text"}],"id":"56b63894-c866-49f9-b9d4-b66a914496b1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"When you perform operations like ","type":"text"},{"styles":{"code":true},"text":"groupBy","type":"text"},{"styles":{"italic":true},"text":" or ","type":"text"},{"styles":{"code":true},"text":"join","type":"text"},{"styles":{"italic":true},"text":", Spark needs to redistribute data so that related rows — like all sales from the ''Western'' region — end up on the same Executor. This requires serializing the data, sending it over the network to other machines, deserializing it on the receiving end, and often writing it to disk temporarily.","type":"text"}],"id":"9bae9e31-929e-488f-846e-5228e892dbf5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"Network I/O is orders of magnitude slower than memory access. On top of that, shuffles create memory pressure, which can cause data to spill to disk, adding even more latency. A shuffle can easily be 10 to 100 times slower than transformations that work independently per partition, like ","type":"text"},{"styles":{"code":true},"text":"filter","type":"text"},{"styles":{"italic":true},"text":" or ","type":"text"},{"styles":{"code":true},"text":"select","type":"text"},{"styles":{"italic":true},"text":".","type":"text"}],"id":"31b1cc3a-3dcd-4638-b0e8-d98b19a3b64b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"That''s why best practices include filtering data early to reduce the volume before a shuffle, and avoiding unnecessary shuffles when possible.\"","type":"text"}],"id":"67e64e5f-5457-4be5-a68b-55aeed600dac","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"dc0e37ed-6cf9-4c73-8f9f-5f0505603854","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"11. C.A.C.O. Application","type":"text"}],"id":"1c53b6f5-1af6-4d9b-8234-b019ce74cb43","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Concept","type":"text"}],"id":"6190c1a5-5b76-447f-9d18-f08942ffb9c3","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Apache Spark","type":"text"},{"styles":{},"text":" is a distributed data processing engine that splits large datasets into partitions and processes them in parallel across a cluster. The ","type":"text"},{"styles":{"bold":true},"text":"Driver","type":"text"},{"styles":{},"text":" coordinates the job, ","type":"text"},{"styles":{"bold":true},"text":"Executors","type":"text"},{"styles":{},"text":" process data, and the ","type":"text"},{"styles":{"bold":true},"text":"Cluster Manager","type":"text"},{"styles":{},"text":" allocates resources. Spark uses ","type":"text"},{"styles":{"bold":true},"text":"lazy evaluation","type":"text"},{"styles":{},"text":" — transformations build a plan, actions trigger execution. ","type":"text"},{"styles":{"bold":true},"text":"Shuffle","type":"text"},{"styles":{},"text":" is the expensive redistribution of data across partitions required for operations like ","type":"text"},{"styles":{"code":true},"text":"groupBy","type":"text"},{"styles":{},"text":" and ","type":"text"},{"styles":{"code":true},"text":"join","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"9eee9835-65cf-4b46-aceb-602343de5bab","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"9acf26e9-06df-4e26-b4b9-cd30a3e3f774","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Architecture","type":"text"}],"id":"6f401bd3-0f6b-4408-91d8-b1ab2f511cef","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"PySpark Script\n    → Driver (builds DAG, optimizes, distributes tasks)\n        → Cluster Manager (allocates Executors)\n            → Executors (process partitions in parallel)\n                → Results sent back to Driver","type":"text"}],"id":"164278bb-43a4-4e5b-8024-1ee11b1e9b1b","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Key Flow:","type":"text"}],"id":"37fd05fb-ab7f-4e11-8d02-37c9f4502836","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"You write PySpark transformations (lazy)","type":"text"}],"id":"cb470c95-0830-46b3-835d-205e030fc882","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Driver builds a DAG","type":"text"}],"id":"0cb07fba-8653-4592-a59e-12bc4f53df36","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Action triggers execution","type":"text"}],"id":"54cd65b8-c5a6-4d8e-a697-d2ef6055148a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Cluster Manager provides Executors","type":"text"}],"id":"ab8a7c9d-75b1-44dc-93e9-9d7fb58ccb47","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Executors process partitions in parallel","type":"text"}],"id":"1af170a3-00f5-4555-84f3-7db6f3b7fbc0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Driver collects results","type":"text"}],"id":"9de2b827-ad79-4412-b9e4-8bbbb704963a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"id":"751a8278-4237-4dba-a0d3-38db5295ebe0","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Code — Simple PySpark Pipeline","type":"text"}],"id":"b6944c1c-f54b-4395-bbda-94d4f82709a2","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"from pyspark.sql import SparkSession\n\n# Initialize Spark session\nspark = SparkSession.builder \\\n    .appName(\"SimpleETL\") \\\n    .getOrCreate()\n\n# Read raw data from Bronze (Transformation)\nraw_df = spark.read.parquet(\"s3://bucket/bronze/sales/\")\n\n# Clean data (Transformation)\nclean_df = raw_df.filter(\"order_id IS NOT NULL AND amount > 0\")\n\n# Add derived column (Transformation)\nenriched_df = clean_df.withColumn(\"revenue\", col(\"quantity\") * col(\"unit_price\"))\n\n# Aggregate by region (Transformation — causes shuffle)\nresult_df = enriched_df.groupBy(\"region\").sum(\"revenue\")\n\n# Write to Gold (Action — triggers execution)\nresult_df.write.mode(\"overwrite\").parquet(\"s3://bucket/gold/revenue_by_region/\")","type":"text"}],"id":"1ba74306-ebe2-4b26-b38b-a28fe75c23db","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"What happens:","type":"text"}],"id":"c6b71b6e-2698-4daa-9cb8-5ad52e01dde4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Lines 1-8: Transformations build the plan","type":"text"}],"id":"559bc4f6-c941-42aa-83e5-141137b9fb14","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Line 11: ","type":"text"},{"styles":{"code":true},"text":".write()","type":"text"},{"styles":{},"text":" is an action — triggers execution","type":"text"}],"id":"047073a4-2a50-4ee5-8adc-e2cd89acaa4c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Spark reads Bronze, applies filter, adds column, shuffles to group by region, aggregates, writes to Gold","type":"text"}],"id":"e48a5074-7342-4155-8905-f8e8d5bb8273","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"id":"75f4863f-006b-4ede-98d1-fcf68c7633bd","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Optimization / Interview Tactics","type":"text"}],"id":"80be95f9-2967-456f-a50f-c8cbd4052fa8","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Lead with the mental model","type":"text"},{"styles":{},"text":" — \"Spark is like a manager dividing work among workers\" — this grounds the technical explanation","type":"text"}],"id":"4e7cfe26-810c-4b39-bb60-a0c1769bdada","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Always distinguish Driver vs Executor clearly","type":"text"},{"styles":{},"text":" — this is a common interview differentiator","type":"text"}],"id":"805adf97-4709-447a-8b33-996dde75d4f6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Explain lazy evaluation with an example","type":"text"},{"styles":{},"text":" — walk through transformations not executing until an action","type":"text"}],"id":"9c1272f6-5900-4032-8b8b-cbd14f5ebc2f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[{"children":[],"content":[{"styles":{},"text":"Databricks (Spark-as-a-service)","type":"text"}],"id":"7b48dd48-f374-4d2d-b2d3-19ad2307f207","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"AWS EMR (Elastic MapReduce — runs Spark on AWS)","type":"text"}],"id":"181dd4d9-8f96-4fdd-88c1-c5c9307bee2a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Azure Synapse / HDInsight (Spark on Azure)","type":"text"}],"id":"d3e13bc7-8652-47a1-8926-9ba1d8fee164","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Google Dataproc (Spark on GCP)","type":"text"}],"id":"5c83f3df-9c51-48c1-906e-1bb7c2e56b9e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"}],"content":[{"styles":{"bold":true},"text":"Name real tools and platforms:","type":"text"}],"id":"1e07fd71-a9db-48dd-90c2-96821ed03290","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Connect Spark to Medallion Architecture","type":"text"},{"styles":{},"text":" — \"Spark processes Bronze → Silver → Gold transformations in the lakehouse\"","type":"text"}],"id":"f3efb78f-8b3d-4a39-9e9a-175327ed1426","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Acknowledge Pandas is still useful","type":"text"},{"styles":{},"text":" — shows you understand tool selection, not just Spark advocacy","type":"text"}],"id":"c8352004-be3a-4255-902e-f9304f735fc3","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"If asked about RDDs, pivot to DataFrames","type":"text"},{"styles":{},"text":" — \"RDDs are the low-level abstraction, but most production work uses DataFrames because they''re easier and optimized by Catalyst\"","type":"text"}],"id":"0b3aa43b-2f13-4345-8d09-3fffe0889ea8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"For Sysco LABS / EY GDS / Dialog Axiata:","type":"text"},{"styles":{},"text":" These companies likely use Spark in cloud environments (AWS EMR, Databricks, Azure Synapse) — mentioning cloud integration shows practical awareness","type":"text"}],"id":"80aa17d3-1079-4ba2-9fc7-4231c2a80f77","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"id":"4e06a318-03bc-4f91-83ac-7647ecca8e19","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"12. Final Interview Summary","type":"text"}],"id":"0c2ac66c-6371-4ac1-a2b6-1cb198aa6349","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Key Terms","type":"text"}],"id":"66fab4b7-5a5b-4ec3-8c89-835b7d83e845","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Term","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Definition","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Apache Spark","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Open-source distributed data processing engine for large-scale data","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Driver","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Coordinator process that builds execution plans and manages Executors","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Executor","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Worker process that executes tasks on data partitions","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Cluster Manager","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"System that allocates resources (YARN, Kubernetes, Standalone)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Partition","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Independent chunk of data distributed across Executors","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"RDD","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Resilient Distributed Dataset — low-level Spark abstraction","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"DataFrame","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"High-level structured API with schema — the standard for most Spark work","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Transformation","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Lazy operation that defines a computation (e.g., ","type":"text"},{"styles":{"code":true},"text":"filter","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"groupBy","type":"text"},{"styles":{},"text":")","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Action","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Operation that triggers execution and returns results (e.g., ","type":"text"},{"styles":{"code":true},"text":"show","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"write","type":"text"},{"styles":{},"text":")","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Lazy Evaluation","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Transformations build a plan but don''t execute until an action is called","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"DAG","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Directed Acyclic Graph — execution plan of transformations","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Shuffle","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Redistribution of data across partitions — required for ","type":"text"},{"styles":{"code":true},"text":"groupBy","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"join","type":"text"},{"styles":{},"text":", etc.","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Catalyst Optimizer","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Spark''s query optimizer that rewrites plans for efficiency","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"e987f900-1424-4334-a4a4-3da21f0cfe26","props":{"textColor":"default"},"type":"table"},{"children":[],"id":"9fcab86a-602f-4704-a748-042e9169d263","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Must-Remember Points","type":"text"}],"id":"bef23520-f4b1-4339-9edb-13e914063540","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"✅ Spark = distributed processing — splits data into partitions, processes in parallel across many machines","type":"text"}],"id":"7ae6e199-a3fa-47f2-a31d-fa642b834fc2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"✅ ","type":"text"},{"styles":{"bold":true},"text":"Driver","type":"text"},{"styles":{},"text":" = coordinator, builds plan, manages Executors","type":"text"}],"id":"7ea96871-92d2-4e23-9630-73aa138e2172","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"✅ ","type":"text"},{"styles":{"bold":true},"text":"Executors","type":"text"},{"styles":{},"text":" = workers, process data partitions in parallel","type":"text"}],"id":"0b2fb3f6-1d7a-4616-9687-f24a651bf760","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"✅ ","type":"text"},{"styles":{"bold":true},"text":"Partitions","type":"text"},{"styles":{},"text":" = chunks of data that enable parallelism","type":"text"}],"id":"bbb7910f-83e3-41c3-95b8-a16660d92892","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"✅ ","type":"text"},{"styles":{"bold":true},"text":"Transformations","type":"text"},{"styles":{},"text":" = lazy (build plan, don''t execute)","type":"text"}],"id":"a4bba055-eb91-4a4b-89fc-2abb506c518c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"✅ ","type":"text"},{"styles":{"bold":true},"text":"Actions","type":"text"},{"styles":{},"text":" = trigger execution (show, count, write)","type":"text"}],"id":"031a98e1-4f82-4075-aa6e-b70688b841bb","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"✅ ","type":"text"},{"styles":{"bold":true},"text":"Lazy evaluation","type":"text"},{"styles":{},"text":" allows Spark to optimize the entire pipeline before running","type":"text"}],"id":"252602ef-92e1-4b1a-b218-6dea6965a842","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"✅ ","type":"text"},{"styles":{"bold":true},"text":"Shuffle","type":"text"},{"styles":{},"text":" = expensive data movement between Executors (caused by groupBy, join, orderBy)","type":"text"}],"id":"2914aee5-d0bd-4a6e-8874-51effdf2ab49","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"✅ ","type":"text"},{"styles":{"bold":true},"text":"DataFrames","type":"text"},{"styles":{},"text":" are the standard API — easier, optimized, schema-aware","type":"text"}],"id":"02b0d5e5-862d-4fc4-9ccf-6e70ffb9f88f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"✅ RDDs are low-level — know they exist, focus on DataFrames","type":"text"}],"id":"13dd3150-691f-4a11-92d0-cd1138f28018","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"✅ Pandas = single-machine; Spark = distributed — use Spark when data > memory or in production pipelines","type":"text"}],"id":"ae3933e7-c4d2-48ca-8fb2-b53225d10de5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"✅ Spark is the engine behind Medallion Architecture (Bronze → Silver → Gold)","type":"text"}],"id":"1afa8d94-074f-4922-8c63-3dfcbc668514","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"id":"ff9c116d-3637-4fa2-9c40-16d84ba2c889","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"3 Interview-Ready One-Liners","type":"text"}],"id":"56dbb2f4-a0ed-436d-b79f-d40fe5920ca6","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"1.","type":"text"},{"styles":{},"text":" ","type":"text"},{"styles":{"italic":true},"text":"\"Apache Spark is a distributed data processing engine that splits large datasets into partitions and processes them in parallel across a cluster — the Driver coordinates the job by building an optimized execution plan, and Executors run tasks on their assigned partitions, enabling Spark to handle datasets far larger than any single machine''s memory.\"","type":"text"}],"id":"b86be5c7-d704-4940-b9c1-456d6855e8a1","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"bold":true},"text":"2.","type":"text"},{"styles":{},"text":" ","type":"text"},{"styles":{"italic":true},"text":"\"Spark uses lazy evaluation — transformations like ","type":"text"},{"styles":{"code":true},"text":"filter","type":"text"},{"styles":{"italic":true},"text":" and ","type":"text"},{"styles":{"code":true},"text":"groupBy","type":"text"},{"styles":{"italic":true},"text":" don''t execute immediately but instead build a logical plan, which only runs when an action like ","type":"text"},{"styles":{"code":true},"text":"show","type":"text"},{"styles":{"italic":true},"text":" or ","type":"text"},{"styles":{"code":true},"text":"write","type":"text"},{"styles":{"italic":true},"text":" is called — this allows Spark to optimize the entire pipeline before execution and provides fault tolerance by storing lineage for recomputation.\"","type":"text"}],"id":"c55e5d05-3f2a-4b66-bddb-a1a63f9c4495","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"bold":true},"text":"3.","type":"text"},{"styles":{},"text":" ","type":"text"},{"styles":{"italic":true},"text":"\"A shuffle is the expensive redistribution of data across partitions required for operations like ","type":"text"},{"styles":{"code":true},"text":"groupBy","type":"text"},{"styles":{"italic":true},"text":" and ","type":"text"},{"styles":{"code":true},"text":"join","type":"text"},{"styles":{"italic":true},"text":" — it involves network I/O, serialization, and often disk writes, making it 10-100x slower than in-memory transformations, which is why best practices include filtering early to reduce data volume before shuffle operations.\"","type":"text"}],"id":"96f3b924-f197-4554-9a8f-2fc93c229302","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"ff46a58a-1ade-404e-871d-08d127dde6af","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Common Mistakes to Avoid","type":"text"}],"id":"e591033d-93b2-4ed6-888a-206c6fa2d7b1","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":{"columnWidths":[null,null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Mistake","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Why It''s Wrong","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Correct Understanding","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Saying \"Spark is always faster than Pandas\"","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Spark has coordination overhead — on small data, Pandas is faster","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Spark wins at scale; Pandas wins on small, local data","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Confusing Driver and Executor roles","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Shows lack of architectural understanding","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Driver = coordinator; Executors = workers processing data","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Calling transformations \"queries\"","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Transformations don''t execute immediately","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Transformations are lazy operations; actions trigger execution","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Thinking shuffle is always bad","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Some operations require shuffle — it''s necessary, just expensive","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Understand which operations cause shuffle and why it''s needed","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Using ","type":"text"},{"styles":{"code":true},"text":".collect()","type":"text"},{"styles":{},"text":" on large DataFrames","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Brings all data to Driver — crashes on large datasets","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Use ","type":"text"},{"styles":{"code":true},"text":".show()","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":".take()","type":"text"},{"styles":{},"text":", or write to storage instead","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Saying RDDs are obsolete","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"RDDs still exist under the hood; they''re just not the primary API","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"RDDs are low-level; DataFrames are high-level and preferred","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Not knowing what lazy evaluation is","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Fundamental to Spark''s design","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Transformations build plan; actions execute","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Confusing Spark SQL with SQL databases","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Spark SQL is a query interface to DataFrames, not a relational DB","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Spark SQL runs distributed queries on DataFrames","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"4cff8ecb-c4a4-4f7f-8dc2-75d2299b474e","props":{"textColor":"default"},"type":"table"},{"children":[],"id":"ae9ad452-160f-4ac8-b8e2-01700a8783b7","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"Remember the mental model.","type":"text"},{"styles":{},"text":" Pandas is one person at one desk. Spark is a manager (Driver) dividing a large job into chunks (partitions) and assigning them to many workers (Executors) who process them in parallel. Transformations are the manager planning the work. Actions are the manager saying \"start now.\" Shuffle is when workers need to exchange data with each other. This mental model unlocks every Spark concept.","type":"text"}],"id":"0589b6f5-7343-4d4f-a57c-a2b2d585f751","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[],"id":"10b69f0d-076e-44db-b7d5-affe8131f5f6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"}]'::jsonb, '3e9e3dd3-a59b-4b02-968a-ee95e7317583') ON CONFLICT ("node_id") DO UPDATE SET "bad_example" = EXCLUDED."bad_example", "completed_at" = EXCLUDED."completed_at", "created_at" = EXCLUDED."created_at", "definition" = EXCLUDED."definition", "good_example" = EXCLUDED."good_example", "is_completed" = EXCLUDED."is_completed", "key_points" = EXCLUDED."key_points", "last_edited" = EXCLUDED."last_edited", "map_id" = EXCLUDED."map_id", "mental_model" = EXCLUDED."mental_model", "notes" = EXCLUDED."notes", "resources" = EXCLUDED."resources", "rich_content" = EXCLUDED."rich_content", "user_id" = EXCLUDED."user_id";
INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-06-13T05:05:18.728342+00:00', '', '', 'ecd1629b-e8b7-4aa0-9f33-57695e038b66', false, '[]'::jsonb, '2026-06-13T05:08:41.666+00:00', '2ad473fe-77dd-481e-8ba7-4b2b0336173f', '', 'ba66a194-7f1f-4c0f-9feb-afd0b10e9b7a', '', '[]'::jsonb, '[{"children":[],"content":[{"styles":{},"text":"1. Triple-Quoted Strings (","type":"text"},{"styles":{"code":true},"text":"\"\"\"","type":"text"},{"styles":{},"text":" or ","type":"text"},{"styles":{"code":true},"text":"''''''","type":"text"},{"styles":{},"text":")","type":"text"}],"id":"54d9a95d-e4c5-4468-9031-5021cf294e61","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"In Python, standard strings defined with single (","type":"text"},{"styles":{"code":true},"text":"''","type":"text"},{"styles":{},"text":") or double (","type":"text"},{"styles":{"code":true},"text":"\"","type":"text"},{"styles":{},"text":") quotes must usually sit on a single line. If you want a string to span across multiple lines naturally without using escape characters like ","type":"text"},{"styles":{"code":true},"text":"\\n","type":"text"},{"styles":{},"text":", you use ","type":"text"},{"styles":{"bold":true},"text":"triple quotes","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"b98d8f6c-023e-4e03-b983-b5cf98e41205","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it does:","type":"text"},{"styles":{},"text":" It tells Python, ","type":"text"},{"styles":{"italic":true},"text":"\"Everything between these two sets of triple quotes is a single string, including any line breaks, tabs, or spaces I type.\"","type":"text"}],"id":"fbbff473-e629-4563-9c1f-b8d215ed1360","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"2. Line Break Preservation","type":"text"}],"id":"eb62f9d9-4368-4578-a248-2d818bcea566","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Look closely at how your code splits across lines 1 and 2:","type":"text"}],"id":"ecf4a41d-71be-432a-bfd4-74bb2513976c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Python","type":"text"}],"id":"d14806e4-fdc0-4e98-8efe-346980f84888","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"print(\"\"\"Hello Ansh Lamba. This is XYZ. How are you?\nHow is you day\"\"\")\n","type":"text"}],"id":"dd5af4b3-9e44-423a-b5fa-5149e8b9bb5a","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Because you hit ","type":"text"},{"styles":{"code":true},"text":"Enter","type":"text"},{"styles":{},"text":" after the question mark to move ","type":"text"},{"styles":{"code":true},"text":"\"How is you day\"","type":"text"},{"styles":{},"text":" to line 2, Python embeds an invisible newline character (","type":"text"},{"styles":{"code":true},"text":"\\n","type":"text"},{"styles":{},"text":") right at that spot inside the string.","type":"text"}],"id":"16ed43f7-00ba-4b3a-89ae-7257ebc6a404","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"3. The Output (The Right Side of the Image)","type":"text"}],"id":"13b4497b-2e9c-44de-aa69-c13719780c15","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The right side of your image shows the console output when this code runs:","type":"text"}],"id":"e350f30d-ddf1-4746-9b29-13c8ecb646e6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Plaintext","type":"text"}],"id":"350a14a2-8d59-458b-b9c2-d791292ac2c1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Hello Ansh Lamba. This is XYZ. How are you?\nHow is you day\n","type":"text"}],"id":"30926ee6-8ef0-498d-b77e-025c2095166a","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Because the triple quotes preserved that exact line break, the ","type":"text"},{"styles":{"code":true},"text":"print()","type":"text"},{"styles":{},"text":" function outputs the text on two separate lines, perfectly mirroring how you typed it in the editor.","type":"text"}],"id":"bbfa90ad-f16a-4fda-bb11-ea490835c383","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"A Quick Syntax Detail","type":"text"}],"id":"b1c089a8-db4a-426e-9dae-120590d8b750","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"You might notice there is a slight grammatical typo in the second line of the string (","type":"text"},{"styles":{"code":true},"text":"\"How is you day\"","type":"text"},{"styles":{},"text":" instead of ","type":"text"},{"styles":{"code":true},"text":"\"How is your day\"","type":"text"},{"styles":{},"text":"). Because Python treats everything inside the quotes as literal text data, it doesn''t check for grammar or spelling—it simply prints out exactly what you wrote, typos and all!","type":"text"}],"id":"dd7a30ee-ee3c-4a91-b6dc-9dbc90c30d9a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[],"id":"6c956dd7-e952-40a5-9d46-a84f19ba0c0c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"These two images demonstrate the fundamental ways Python handles ","type":"text"},{"styles":{"bold":true},"text":"nested quotes","type":"text"},{"styles":{},"text":" inside a string without confusing the interpreter.","type":"text"}],"id":"d23638fd-36d1-4671-ae8e-5ce4c051ce57","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"When you want quotation marks to literally appear in your final output text, you can''t just throw them in haphazardly. Python needs to know where the string ","type":"text"},{"styles":{"italic":true},"text":"actually","type":"text"},{"styles":{},"text":" starts and ends.","type":"text"}],"id":"5e5ee238-ad28-4f08-8ecc-67030a3b13b9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Here is how both methods solve that problem in detail.","type":"text"}],"id":"62d34d24-151d-44ef-8230-91618507bbc2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"2. Alternating Quotes (Image 1)","type":"text"}],"id":"8cadb6b3-95ca-4fde-a0e2-8a0f8e86f9bc","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Python","type":"text"}],"id":"23c240bb-abb5-4298-9f7e-d66818587355","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"print(\"Hello ''Ansh Lamba''. This is XYZ. How are you?\")\n","type":"text"}],"id":"cc09a843-2d4a-4e1e-a0ad-c6cb6a3aee86","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"How it works","type":"text"}],"id":"14b938dc-6b90-4286-9ffe-4aca2d1a65c9","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Python allows you to define strings using either single quotes (","type":"text"},{"styles":{"code":true},"text":"''","type":"text"},{"styles":{},"text":") or double quotes (","type":"text"},{"styles":{"code":true},"text":"\"","type":"text"},{"styles":{},"text":"). A key rule of the language is that ","type":"text"},{"styles":{"bold":true},"text":"a string must close with the exact same type of quote that opened it.","type":"text"}],"id":"10421791-65d5-487f-b991-03cbd9689f75","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"The Outer Container:","type":"text"},{"styles":{},"text":" You started the string with a double quote (","type":"text"},{"styles":{"code":true},"text":"\"","type":"text"},{"styles":{},"text":"). Python is now looking ","type":"text"},{"styles":{"italic":true},"text":"only","type":"text"},{"styles":{},"text":" for another double quote to end the string.","type":"text"}],"id":"bbf55203-0765-4c71-ac75-c77addba2cb3","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"The Inner Text:","type":"text"},{"styles":{},"text":" Because Python is waiting for a double quote, it completely ignores the single quotes around ","type":"text"},{"styles":{"code":true},"text":"''Ansh Lamba''","type":"text"},{"styles":{},"text":" as syntax. It treats them as regular literal text characters, just like the letters ","type":"text"},{"styles":{"code":true},"text":"H","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"e","type":"text"},{"styles":{},"text":", or ","type":"text"},{"styles":{"code":true},"text":"l","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"31b86ccd-538c-4ad6-a166-a4f1d266411f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"The Rule of Thumb","type":"text"}],"id":"9857afa1-1ef7-4862-b8e9-3e0d1ec4f4cb","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"If your text needs to contain single quotes, wrap the whole string in double quotes.","type":"text"}],"id":"b86cd76a-37eb-4d24-bf00-956fb7beaca9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Python","type":"text"}],"id":"c73477b6-d849-4318-8a5e-fb562ecb1532","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"# Opposite works too! Outer single quotes allow inner double quotes:\nprint(''He said, \"Python is awesome!\"'')\n","type":"text"}],"id":"79fadf98-527e-4927-a072-59f7b5b67a80","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"3. Escape Characters (Image 2)","type":"text"}],"id":"ac345144-cc89-4ae4-a5b8-b3ae2595bc32","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Python","type":"text"}],"id":"ddd27945-c3bd-447a-b4fb-9b97d00650c9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"print(''Hello \\''Ansh Lamba\\''. This is XYZ. How are you?'')\n","type":"text"}],"id":"39989140-fe20-4af6-b3ab-4e246c25a3ee","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"How it works","type":"text"}],"id":"91e8b959-1cde-4d47-96eb-98f76bc07c0f","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"What happens if you ","type":"text"},{"styles":{"italic":true},"text":"must","type":"text"},{"styles":{},"text":" use single quotes on the outside, but you ","type":"text"},{"styles":{"italic":true},"text":"also","type":"text"},{"styles":{},"text":" need single quotes on the inside?","type":"text"}],"id":"182a6d21-b8a7-4837-b3ff-6a98898b3f77","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"If you wrote ","type":"text"},{"styles":{"code":true},"text":"print(''Hello ''Ansh Lamba''...'')","type":"text"},{"styles":{},"text":", Python would see the second single quote right before ","type":"text"},{"styles":{"code":true},"text":"Ansh","type":"text"},{"styles":{},"text":" and assume the string ended right there. It would then look at ","type":"text"},{"styles":{"code":true},"text":"Ansh Lamba","type":"text"},{"styles":{},"text":" as raw code, get confused, and throw a ","type":"text"},{"styles":{"code":true},"text":"SyntaxError","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"9fffa378-2233-4771-9a1d-d1b2cfa84840","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"To prevent this, you use the backslash (","type":"text"},{"styles":{"code":true},"text":"\\","type":"text"},{"styles":{},"text":"), which is Python’s ","type":"text"},{"styles":{"bold":true},"text":"escape character","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"343e4df2-89d2-4439-a681-3d239f4c0f22","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"The Backslash Trigger:","type":"text"},{"styles":{},"text":" When Python is reading a string and encounters a ","type":"text"},{"styles":{"code":true},"text":"\\","type":"text"},{"styles":{},"text":", it says: ","type":"text"},{"styles":{"italic":true},"text":"\"Hold on, do not treat the very next character as code syntax. Treat it as pure text.\"","type":"text"}],"id":"d40e3f7d-7ffe-445f-a3b4-9e2d901fa2fb","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"The Result:","type":"text"},{"styles":{},"text":" By writing ","type":"text"},{"styles":{"code":true},"text":"\\''","type":"text"},{"styles":{},"text":", you \"escape\" the single quote. Python ignores its programming power to close the string and instead treats it as a literal graphic to print on the screen.","type":"text"}],"id":"57a7cbbd-b6db-4429-83e3-326c251e75f5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[],"id":"aeef5fcd-e25e-4d3c-b7d5-dbc5be639cac","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"}]'::jsonb, '3e9e3dd3-a59b-4b02-968a-ee95e7317583') ON CONFLICT ("node_id") DO UPDATE SET "bad_example" = EXCLUDED."bad_example", "completed_at" = EXCLUDED."completed_at", "created_at" = EXCLUDED."created_at", "definition" = EXCLUDED."definition", "good_example" = EXCLUDED."good_example", "is_completed" = EXCLUDED."is_completed", "key_points" = EXCLUDED."key_points", "last_edited" = EXCLUDED."last_edited", "map_id" = EXCLUDED."map_id", "mental_model" = EXCLUDED."mental_model", "notes" = EXCLUDED."notes", "resources" = EXCLUDED."resources", "rich_content" = EXCLUDED."rich_content", "user_id" = EXCLUDED."user_id";
INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-06-13T08:34:51.669726+00:00', '', '', 'c9cd0bb8-268e-4c06-8738-7851fc4d0143', false, '[]'::jsonb, '2026-06-13T08:37:11.315+00:00', '2ad473fe-77dd-481e-8ba7-4b2b0336173f', '', '18b38f99-a8f9-4e97-ac74-929d871712a4', '', '[]'::jsonb, '[{"children":[],"content":[{"styles":{},"text":"Project-Translation Strategy: Showcasing Junior-Level Python Competency in Enterprise Portfolio Projects","type":"text"}],"id":"ce7e76c4-1608-472a-abd1-5d396f4c80a5","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"1. Executive Summary & Strategy","type":"text"}],"id":"a5bd69d4-e97e-4d75-9bdd-698f9584c94a","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The primary hurdle for aspiring junior data engineers and interns targeting elite Sri Lankan technology firms — specifically ","type":"text"},{"styles":{"bold":true},"text":"Sysco LABS","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"bold":true},"text":"EY GDS","type":"text"},{"styles":{},"text":", and ","type":"text"},{"styles":{"bold":true},"text":"Dialog Axiata","type":"text"},{"styles":{},"text":" — is the ","type":"text"},{"styles":{"bold":true},"text":"“tutorial clone” trap","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"834bd9f8-31bf-4721-836a-3b07620d5acb","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Thousands of applicants submit portfolio repositories featuring identical scripts that:","type":"text"}],"id":"26121596-62d9-4f59-8243-1bab9b83bb24","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Load static local CSV files directly into Pandas","type":"text"}],"id":"259846df-051b-427b-9ee1-03e8ac529fc8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Execute standard ","type":"text"},{"styles":{"code":true},"text":".groupby()","type":"text"},{"styles":{},"text":" operations","type":"text"}],"id":"1e04c304-9560-4027-9bec-c38a93f33adf","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Print the results to the terminal","type":"text"}],"id":"5c2cb862-925b-40c5-9ef5-0cfa3fc7cfd1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"To hiring managers at highly competitive organizations, these projects offer almost zero signal that the candidate is capable of managing production-style pipelines.","type":"text"}],"id":"e0692fb9-f14b-4d6b-ac6e-3a197d175031","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Enterprise-ready data engineering projects must showcase ","type":"text"},{"styles":{"bold":true},"text":"software engineering hygiene","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"5aee89a0-c2b0-4d80-87e7-3734b8d5ae2f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"At the junior level, companies are not expecting you to build a custom distributed database engine. They are evaluating whether you can write Python code that is:","type":"text"}],"id":"1cb75b11-652d-4d2f-91fc-07087681ca7f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Resilient","type":"text"}],"id":"763ea2cf-f885-4ef7-b26f-c502051520ec","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Defensive","type":"text"}],"id":"9d54e54b-9998-4cc0-8211-df4ac61259f0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Secure","type":"text"}],"id":"4dd7694a-2ce4-4e93-b7ea-53394e573374","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Resource-aware","type":"text"}],"id":"e7e5bcc5-a97b-494f-99f2-a68742020a34","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Cleanly structured","type":"text"}],"id":"6a174a8c-77f5-4235-a04c-43bfb1c94fcd","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Deployment-friendly","type":"text"}],"id":"76ff9d21-e8fd-4f8a-bfdb-4ea26788ffc1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"This report translates your filtered Python-for-Data-Engineering roadmap directly into concrete, production-grade project modules.","type":"text"}],"id":"c036e834-7786-4186-aa1e-37a368a48738","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"By structuring your portfolio around these patterns, your code becomes direct evidence that you already understand enterprise concerns such as:","type":"text"}],"id":"ae1cf0df-c8f2-4448-a6bd-a6e2029b0e63","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"API rate limiting","type":"text"}],"id":"fc8709a3-3fc3-4f69-bc9d-91f39998dd33","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Network flakiness","type":"text"}],"id":"2faaf373-c586-44e5-982d-22afbb7c90bf","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Credential security","type":"text"}],"id":"2aed695d-e01b-4ef9-917d-ed6dd7c932cb","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Database connection limits","type":"text"}],"id":"8e322a3c-024e-4517-b1ad-299a8add6471","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Memory management","type":"text"}],"id":"c43f311e-0a95-4cf5-91dc-b9db400abb6a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Clean data transformations","type":"text"}],"id":"d175516f-f0fe-4bba-bd08-3f7cc6336336","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"id":"c945ff0b-5186-45e0-b735-76fffabf1548","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"2. Project-Skill Translation Matrix","type":"text"}],"id":"d3c82f70-4d28-4513-aa9a-6e25aa1891cc","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"To make your skills visible to hiring managers, every architectural decision in your project must correspond to a high-value interview talking point and a corporate requirement.","type":"text"}],"id":"479df359-5a98-4c88-afd6-f497c828bcc8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":{"columnWidths":[null,null,null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Skill","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Project Feature","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Employer Signal","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Interview Talking Point","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Resilient API Ingestion","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Custom client using ","type":"text"},{"styles":{"code":true},"text":"requests.Session()","type":"text"},{"styles":{},"text":" with ","type":"text"},{"styles":{"code":true},"text":"tenacity","type":"text"},{"styles":{},"text":" retry decorators and cursor-based pagination logic.","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Production-ready defensive coding; awareness of rate limits, TCP handshakes, and network instability.","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"“I designed the ingestion layer to reuse TCP connections, reduce overhead, and safely recover from HTTP 429 rate limits using backoff with jitter.”","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Complex Spark / SQL Transforms","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Analytical window functions such as ","type":"text"},{"styles":{"code":true},"text":"partitionBy","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"row_number","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"lead","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"lag","type":"text"},{"styles":{},"text":", and left-semi joins for incremental loads.","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Advanced data manipulation capability; understanding of shuffle optimization and analytical processing.","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"“Rather than performing costly self-joins, I wrote a PySpark window function to identify and deduplicate records on a high-volume transaction table.”","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Safe DB Connectivity","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"SQLAlchemy engine wrapper with explicit connection pooling using ","type":"text"},{"styles":{"code":true},"text":"QueuePool","type":"text"},{"styles":{},"text":" and parameterized SQL execution inside context managers.","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Understanding of database concurrency, connection leaks, and SQL injection boundaries.","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"“I used SQLAlchemy connection pooling to manage database connections safely while implementing parameterized queries to prevent SQL injection.”","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Environment & Config","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Dynamic environment loading using ","type":"text"},{"styles":{"code":true},"text":"python-dotenv","type":"text"},{"styles":{},"text":" and configuration classes.","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"High DevOps alignment; readiness for automated CI/CD deployment pipelines.","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"“I decoupled configuration from code, ensuring the same script can run locally, in Docker, or in cloud environments using environment variables.”","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Cloud I/O & File Handling","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Memory-efficient streaming generators using ","type":"text"},{"styles":{"code":true},"text":"yield","type":"text"},{"styles":{},"text":" and ","type":"text"},{"styles":{"code":true},"text":"boto3","type":"text"},{"styles":{},"text":" S3 uploads for large files.","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Resource-aware scripting; ability to process files larger than available RAM without OOM failures.","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"“To handle files larger than server RAM, I wrote a generator using ","type":"text"},{"styles":{"code":true},"text":"yield","type":"text"},{"styles":{},"text":" and ","type":"text"},{"styles":{"code":true},"text":"ijson","type":"text"},{"styles":{},"text":" to parse and stream raw JSON directly to S3 in small chunks.”","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"35eb617c-b877-4859-8360-bed8a71451a9","props":{"textColor":"default"},"type":"table"},{"children":[],"id":"b5e67cc5-6a37-4a56-a8c9-bcaeb9b1b196","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"3. Core Project Signals vs. Supporting Signals","type":"text"}],"id":"6ce41440-a7ac-40c3-9770-bc3dfbf44245","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"When developing your portfolio, allocate your energy where it gives the highest return.","type":"text"}],"id":"dc66e701-a604-4501-9952-74c579b6f83c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Do not treat all project features equally.","type":"text"}],"id":"071cff7c-b1ec-4e96-8b60-ef694f90b1d0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"+-------------------------------------------------------------+\n|                     CORE RETAINED SIGNALS                   |\n|  * Resilient Ingestion Module: tenacity, requests.Session   |\n|  * Analytical Transformation Layer: PySpark Windows / Joins |\n|  * Secured Loading Interface: SQLAlchemy Pooling, Params    |\n+-------------------------------------------------------------+\n                              |\n                              | Implements & Enforces\n                              v\n+-------------------------------------------------------------+\n|                   SUPPORTING CONFIG SIGNALS                 |\n|  * Environment Decoupling: os.environ, dotenv               |\n|  * Memory-Efficient S3 Cloud I/O: boto3, generators/yield   |\n+-------------------------------------------------------------+","type":"text"}],"id":"83ebca8e-e101-48b6-ace5-2428ca3b3ff1","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Core Project Signals","type":"text"}],"id":"2f2cd3b3-7342-4b53-843a-482cb7e1f293","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"These are the parts of the project that are most likely to be audited during interviews or GitHub reviews.","type":"text"}],"id":"19c91cea-cc80-4373-9e64-167a7fac7957","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"1. The Ingestion Module","type":"text"}],"id":"720ef3c5-8f15-40fc-a5cb-3377b662e3ab","props":{"backgroundColor":"default","isToggleable":false,"level":4,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"This is what companies such as Dialog Axiata and Sysco LABS look for first.","type":"text"}],"id":"20224e10-fbed-476e-b6bd-c6af0989bd1a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Your ingestion scripts must handle network exceptions gracefully. If an interviewer opens your repository and sees a raw ","type":"text"},{"styles":{"code":true},"text":"requests.get()","type":"text"},{"styles":{},"text":" inside a loop without timeouts or retry blocks, they may immediately categorize you as a beginner.","type":"text"}],"id":"3877c9f6-4d3d-417c-b6f0-1341dc7b9ca1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"2. The Transformation Layer","type":"text"}],"id":"9af6a13a-251d-4d80-a4be-1af71ef3a494","props":{"backgroundColor":"default","isToggleable":false,"level":4,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"For EY GDS and Sysco LABS, your transformation scripts are one of the main technical filters.","type":"text"}],"id":"ea3974cf-6b9e-4b68-9fea-6b3eafaa6fbf","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"This is where you demonstrate PySpark or heavy SQL window capabilities. It shows that you can write clean, set-based logic instead of inefficient Python loops.","type":"text"}],"id":"1f8c4136-c334-4cc4-ad71-6533b4c68b91","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"3. The Secured Loading Interface","type":"text"}],"id":"bcbcc724-b805-4617-9a7c-1e5c6541a5bb","props":{"backgroundColor":"default","isToggleable":false,"level":4,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Your database interaction logic must be robust.","type":"text"}],"id":"34e573ab-55b0-4a5c-8715-e272e5c8c3f5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"It must:","type":"text"}],"id":"f7f93bcc-bdb6-4f59-a3a2-b1ebadb392ef","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Handle connection management cleanly","type":"text"}],"id":"69c1313f-527c-4194-8c60-79181f4ad363","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Guarantee connections close even if the script crashes","type":"text"}],"id":"07118217-d8b6-4daf-8103-3445cba58d02","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Use safe, parameterized variables","type":"text"}],"id":"a2fa109e-6eda-437f-ac65-12aa6328d0f6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Avoid SQL injection risks","type":"text"}],"id":"a7424060-b66a-468e-8b3b-9e4646a0aa35","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"id":"129ff89b-dff7-4983-90b2-703ff023bd93","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Supporting Signals","type":"text"}],"id":"9cbd67a7-b7b3-4dde-bf3f-600d50247baf","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"These are not always the main interview focus, but they strongly reinforce that your project is enterprise-ready.","type":"text"}],"id":"d8c6c054-29ce-42df-98b9-f2218af2a70b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"1. Environment & Secret Management","type":"text"}],"id":"d52fc9d6-24ed-455a-bbc0-9aa839f28c65","props":{"backgroundColor":"default","isToggleable":false,"level":4,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"This should exist across all modules but requires minimal code.","type":"text"}],"id":"0efa4961-01e2-48ce-941a-31b2b908b7ad","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"It proves that you do not push AWS keys, database passwords, or API tokens into public repositories.","type":"text"}],"id":"94483aaa-e4ef-4720-8495-37e79e29a4d1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"2. Cloud and File I/O","type":"text"}],"id":"5a914d78-1fab-485f-bd19-10c7f4ad5af7","props":{"backgroundColor":"default","isToggleable":false,"level":4,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Instead of standard file reads, your script should demonstrate chunking or generator logic to handle large datasets cleanly.","type":"text"}],"id":"b79f8002-877e-49ad-8c49-9812667e58e0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"9219ed0a-f933-4e0d-a0bc-2eb8154552cd","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"4. Deep-Dive Implementation Blueprints","type":"text"}],"id":"5031e08b-cc16-4260-bb19-983ecc2be8f3","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The following blueprints provide the exact implementation patterns and code blocks you should write for each project module.","type":"text"}],"id":"cfcd7e52-b9f1-4df3-978d-ce1237f39439","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"ff969258-1f1c-47eb-95b4-5ded6c116e7c","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"4.1 Ingestion Module: Resilient API Ingestion","type":"text"}],"id":"8e2b05ba-d503-4137-ac51-c84f635811c2","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Location","type":"text"}],"id":"fd3167a2-c383-4ac2-9588-298abbc95581","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"src/ingestion/api_client.py","type":"text"}],"id":"0c39349f-695b-486c-a36e-8581d86a98f6","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"What Code to Write","type":"text"}],"id":"1f425e27-1f3d-4db0-a058-41f2593cea15","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"import logging\nimport requests\nfrom tenacity import (\n    retry,\n    stop_after_attempt,\n    wait_exponential,\n    retry_if_exception_type,\n)\n\nlogger = logging.getLogger(__name__)\n\n\nclass ResilientApiClient:\n    def __init__(self, base_url: str, timeout: tuple = (3.0, 15.0)):\n        self.base_url = base_url\n        self.timeout = timeout\n\n        # Connection pooling: reuses TCP connections\n        self.session = requests.Session()\n\n    @retry(\n        stop=stop_after_attempt(5),\n        wait=wait_exponential(multiplier=1.0, min=2, max=10),\n        retry=retry_if_exception_type(\n            (\n                requests.exceptions.HTTPError,\n                requests.exceptions.Timeout,\n            )\n        ),\n        reraise=True,\n    )\n    def fetch_page(self, endpoint: str, params: dict) -> dict:\n        \"\"\"\n        Fetches a single page of data with automated retry and backoff logic.\n        \"\"\"\n        url = f\"{self.base_url.rstrip(''/'')}/{endpoint.lstrip(''/'')}\"\n\n        logger.info(\"Initiating request: %s with params %s\", url, params)\n\n        response = self.session.get(\n            url,\n            params=params,\n            timeout=self.timeout,\n        )\n\n        # Converts bad HTTP status codes, such as 429 and 500, into exceptions\n        response.raise_for_status()\n\n        return response.json()\n\n    def get_paginated_data(self, endpoint: str, limit: int = 100):\n        \"\"\"\n        Cursor-based pagination to stream pages to downstream processes.\n        \"\"\"\n        offset = 0\n\n        while True:\n            params = {\n                \"limit\": limit,\n                \"offset\": offset,\n            }\n\n            try:\n                payload = self.fetch_page(endpoint, params)\n                data = payload.get(\"data\", [])\n\n                if not data:\n                    break\n\n                # Memory-efficient streaming of data batches\n                yield data\n\n                offset += len(data)\n\n            except Exception as e:\n                logger.error(\"Failed to fetch data at offset %s: %s\", offset, e)\n                raise","type":"text"}],"id":"254ea7ac-f8d6-42e3-bb85-863fbd6f1c3a","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"What It Solves","type":"text"}],"id":"93ff44f0-8092-4624-8742-cc720744d67b","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"This module helps your pipeline:","type":"text"}],"id":"87ef64b2-96b1-470d-8691-5afa147d4a56","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Prevent infinite hangs using explicit timeouts","type":"text"}],"id":"7284652e-67e4-4765-8b1e-c9d7d3c09928","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Reduce connection establishment overhead using ","type":"text"},{"styles":{"code":true},"text":"requests.Session()","type":"text"}],"id":"4cdef97b-5f30-4034-be73-48c496a62c53","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Survive temporary network drops or API rate limits using ","type":"text"},{"styles":{"code":true},"text":"tenacity","type":"text"}],"id":"b2733d7d-ac2d-4a4c-8a5b-843a43f5ba2d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Avoid RAM exhaustion by yielding data in chunks instead of accumulating everything in a massive list","type":"text"}],"id":"9e6896d0-c7aa-43b9-ac37-9977bb55daf2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"GitHub README Callout","type":"text"}],"id":"5f5e8347-02dd-4264-a9de-6ef4cb6a8bdc","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Ingestion Architecture:","type":"text"},{"styles":{},"text":" The ingestion client uses connection pooling with ","type":"text"},{"styles":{"code":true},"text":"requests.Session()","type":"text"},{"styles":{},"text":" to minimize repeated TCP handshakes. It also implements exponential backoff with ","type":"text"},{"styles":{"code":true},"text":"tenacity","type":"text"},{"styles":{},"text":" to absorb API rate limiting, HTTP 429 responses, and network timeouts gracefully.","type":"text"}],"id":"0c7aa91b-7e90-444e-85cf-747606bb8ef4","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"39d09065-cd85-4718-9b91-7963d2eb9588","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"4.2 Parsing & Storage Module: Memory-Aware File Handling and Cloud I/O","type":"text"}],"id":"8124ce6d-9bb6-4aa4-b557-9ed010dc65a7","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Location","type":"text"}],"id":"61412acd-7ea7-473d-9fc8-2ce3d3b1fceb","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"src/ingestion/s3_uploader.py","type":"text"}],"id":"a8c9b414-179c-4554-9164-b82076132b24","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"What Code to Write","type":"text"}],"id":"d8b1f4d3-c686-45bd-a476-ac529ff48e37","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"import os\nimport json\nimport ijson\nimport boto3\nimport logging\n\nlogger = logging.getLogger(__name__)\n\n\nclass S3ChunkedUploader:\n    def __init__(self, bucket_name: str):\n        self.bucket_name = bucket_name\n\n        self.s3_client = boto3.client(\n            \"s3\",\n            aws_access_key_id=os.environ.get(\"AWS_ACCESS_KEY_ID\"),\n            aws_secret_access_key=os.environ.get(\"AWS_SECRET_ACCESS_KEY\"),\n        )\n\n    def stream_large_json_to_s3(self, local_file_path: str, s3_key: str):\n        \"\"\"\n        Reads a massive nested JSON file token-by-token and streams it to S3.\n        \"\"\"\n        with open(local_file_path, \"rb\") as f:\n            objects = ijson.items(f, \"records.item\")\n\n            chunk = []\n            chunk_num = 0\n\n            for obj in objects:\n                chunk.append(obj)\n\n                if len(chunk) >= 5000:\n                    self._upload_chunk(chunk, s3_key, chunk_num)\n                    chunk = []\n                    chunk_num += 1\n\n            if chunk:\n                self._upload_chunk(chunk, s3_key, chunk_num)\n\n    def _upload_chunk(self, data_chunk: list, s3_key: str, chunk_num: int):\n        serialized_data = json.dumps(data_chunk)\n\n        # Clean lexical sorting\n        target_key = f\"{s3_key}/part_{str(chunk_num).zfill(5)}.json\"\n\n        logger.info(\n            \"Uploading batch %s to s3://%s/%s\",\n            chunk_num,\n            self.bucket_name,\n            target_key,\n        )\n\n        self.s3_client.put_object(\n            Bucket=self.bucket_name,\n            Key=target_key,\n            Body=serialized_data,\n        )","type":"text"}],"id":"dfbcd5b4-3ac3-4d9c-b12d-5cae13011fa6","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"What It Solves","type":"text"}],"id":"9ae12646-af16-4670-8e47-e9cd1b55551b","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"This module allows your ingestion pipeline to process multi-gigabyte JSON feeds without exceeding server RAM limits.","type":"text"}],"id":"dfa3a949-16ac-45e7-b2a5-453ceefe887b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"It demonstrates:","type":"text"}],"id":"afb2fb2c-20ae-4de7-bd14-43730afcade2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Incremental parsing using ","type":"text"},{"styles":{"code":true},"text":"ijson","type":"text"}],"id":"ee6a073c-ff3c-49fd-b84e-77fec5ca5159","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Chunk-based processing","type":"text"}],"id":"ae2f9d9c-5bfb-4b36-9530-bf777294fa26","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Basic AWS integration using ","type":"text"},{"styles":{"code":true},"text":"boto3","type":"text"}],"id":"6909813d-bf57-4025-9a52-e63de8788ce4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Flat memory usage instead of loading the entire file into RAM","type":"text"}],"id":"e3a984fe-e953-485e-ac95-dc77b2c17752","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"In practical terms, this keeps memory usage close to constant instead of increasing with the size of the source file.","type":"text"}],"id":"d8e9f44e-6306-43e3-a4f9-f4575b0f0a58","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"GitHub README Callout","type":"text"}],"id":"21fee22c-162d-440a-b360-cd0e62238cf7","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Memory-Aware Cloud I/O:","type":"text"},{"styles":{},"text":" Replaced naive standard file reads with incremental stream parsing using ","type":"text"},{"styles":{"code":true},"text":"ijson","type":"text"},{"styles":{},"text":". The pipeline streams data into AWS S3 partitions using chunked batch uploads via ","type":"text"},{"styles":{"code":true},"text":"boto3","type":"text"},{"styles":{},"text":", preventing memory overload and enabling scaling to larger-than-RAM datasets.","type":"text"}],"id":"f508e0f7-0cca-4376-9fef-c50a0c3d273b","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"71688d8a-0ce6-4c11-9ef6-377df9ec402d","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"4.3 Transformation Module: Complex PySpark / SQL Analytical Layer","type":"text"}],"id":"0ca55faf-c62b-41ef-bf2d-a6a24082cf4a","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Location","type":"text"}],"id":"a8801d1f-0569-48c2-8491-39686ff52ccb","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"src/transformation/spark_aggregator.py","type":"text"}],"id":"da053535-73b8-4120-b6f5-31d4fc079cff","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"What Code to Write","type":"text"}],"id":"7ca43da1-14b3-4b77-8903-2e7fc0efc3c4","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"from pyspark.sql import SparkSession\nfrom pyspark.sql.window import Window\nfrom pyspark.sql.functions import col, row_number, lead, coalesce, lit\n\n\ndef execute_analytics_pipeline(\n    spark: SparkSession,\n    input_path: str,\n    output_path: str,\n):\n    \"\"\"\n    Simulates a high-volume telecom data enrichment pipeline.\n\n    Resolves:\n    - Session-level deduplication\n    - Subscriber journey path analysis\n    - Partitioned output writing\n    \"\"\"\n    # Reading partitioned S3 or data lake data\n    df = spark.read.parquet(input_path)\n\n    # Window 1: Deduplication\n    # Identifies the most recent record per subscriber session\n    dedup_window = (\n        Window\n        .partitionBy(\"subscriber_id\", \"session_id\")\n        .orderBy(col(\"timestamp\").desc())\n    )\n\n    deduplicated_df = (\n        df.withColumn(\"row_num\", row_number().over(dedup_window))\n          .filter(col(\"row_num\") == 1)\n          .drop(\"row_num\")\n    )\n\n    # Window 2: Lead Analysis\n    # Finds the next cell tower used by the subscriber\n    journey_window = (\n        Window\n        .partitionBy(\"subscriber_id\")\n        .orderBy(\"timestamp\")\n    )\n\n    enriched_df = (\n        deduplicated_df\n        .withColumn(\n            \"next_connected_tower\",\n            lead(\"tower_id\", 1).over(journey_window),\n        )\n        .withColumn(\n            \"next_connected_tower\",\n            coalesce(col(\"next_connected_tower\"), lit(\"DISCONNECTED\")),\n        )\n    )\n\n    # Write output back to the data lake partitioned by date\n    enriched_df.write \\\n        .mode(\"overwrite\") \\\n        .partitionBy(\"date\") \\\n        .parquet(output_path)","type":"text"}],"id":"ed5537a8-fffd-4ec3-9751-7f5b7a61b8f1","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"What It Solves","type":"text"}],"id":"85108c6b-94c5-4bbe-bb93-235bbe54556d","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"This avoids slow, non-scalable procedural Python transformations.","type":"text"}],"id":"00b5fad0-15f0-4a1a-9c62-2b9183989190","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"It demonstrates:","type":"text"}],"id":"663a8254-8e8c-47e2-aab4-d0a77f2ef6ea","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"PySpark Window Functions","type":"text"}],"id":"f644ef1a-0494-497c-9b65-1ce354236a17","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Deduplication using ","type":"text"},{"styles":{"code":true},"text":"row_number()","type":"text"}],"id":"7c699d45-74ec-4c83-b79f-bc26766fe5c5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Sequence analysis using ","type":"text"},{"styles":{"code":true},"text":"lead()","type":"text"}],"id":"8955f832-b35d-4558-a1cd-2257771b424e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Partitioned Parquet output","type":"text"}],"id":"7a03aada-5024-407d-9b6e-25b8ad6ba247","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Big-data-style transformation thinking","type":"text"}],"id":"9e860c3d-bbf9-40b5-8578-1833d2c1f404","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"This is especially valuable for EY GDS, Sysco LABS, and other companies that test SQL, Spark, or large-scale data transformation ability.","type":"text"}],"id":"61f14b70-024e-418a-8e98-9a853e97db43","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"GitHub README Callout","type":"text"}],"id":"918533ea-e820-4326-bcd3-beaad81aa1cd","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Big Data Transformation Layer:","type":"text"},{"styles":{},"text":" Implemented in PySpark using optimized windowing algorithms such as ","type":"text"},{"styles":{"code":true},"text":"row_number()","type":"text"},{"styles":{},"text":" and ","type":"text"},{"styles":{"code":true},"text":"lead()","type":"text"},{"styles":{},"text":" to perform subscriber session deduplication and sequence analytics without expensive nested join operations. Output datasets are written as Parquet files partitioned by processing date for faster downstream query retrieval.","type":"text"}],"id":"2da9edd4-b320-40f1-8074-89e07ee09fb1","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"87dfade1-337a-4237-b1bf-8be510bffb2c","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"4.4 Loading Module: Safe Database Connectivity and Pool Tuning","type":"text"}],"id":"8b7e9646-60f8-46fe-930b-1fc75a05e1cc","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Location","type":"text"}],"id":"93e17107-ae16-4d8b-b79c-a883b21329a1","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"src/loading/database_loader.py","type":"text"}],"id":"0820dc98-ebc9-48a4-9bb6-e9b9f0ef244e","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"What Code to Write","type":"text"}],"id":"b98b8958-c411-4199-af80-231ca4cf4dc3","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"import logging\nfrom sqlalchemy import create_engine, text\nfrom sqlalchemy.pool import QueuePool\n\nlogger = logging.getLogger(__name__)\n\n\nclass SecuredDatabaseLoader:\n    def __init__(self, db_uri: str):\n        self.engine = create_engine(\n            db_uri,\n            poolclass=QueuePool,\n            pool_size=10,\n            max_overflow=5,\n            pool_timeout=30,\n            pool_recycle=1800,\n        )\n\n    def load_records_parameterized(self, table_name: str, records: list[dict]):\n        \"\"\"\n        Executes safe, parameterized bulk insert transactions using SQLAlchemy Core.\n        \"\"\"\n        if not records:\n            return\n\n        query = text(f\"\"\"\n            INSERT INTO {table_name} (\n                transaction_id,\n                subscriber_id,\n                amount,\n                status\n            )\n            VALUES (\n                :transaction_id,\n                :subscriber_id,\n                :amount,\n                :status\n            )\n            ON CONFLICT (transaction_id) DO UPDATE SET\n                status = EXCLUDED.status;\n        \"\"\")\n\n        with self.engine.begin() as connection:\n            logger.info(\n                \"Executing batch transaction of %s records for %s\",\n                len(records),\n                table_name,\n            )\n\n            try:\n                connection.execute(query, records)\n            except Exception as e:\n                logger.error(\"Database transaction aborted: %s\", e)\n                raise","type":"text"}],"id":"2f012237-9c9d-4a85-97d4-f520726f847a","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"What It Solves","type":"text"}],"id":"47ec58ad-c964-43af-8e88-5397b0e218da","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"This module demonstrates:","type":"text"}],"id":"4645ee5a-1b34-40e4-932d-8aeef61eee17","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Database connection pooling","type":"text"}],"id":"e950d1f8-6580-490b-9fce-1e29452f4d7b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Transaction safety using ","type":"text"},{"styles":{"code":true},"text":"engine.begin()","type":"text"}],"id":"03ddf020-df81-4c2f-a40b-829e6910730e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Safe batch execution","type":"text"}],"id":"00950277-98b8-4dda-a39a-a49c1cece6dd","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Reduced single-row insert overhead","type":"text"}],"id":"0c0dccd5-0e03-4fe0-bcec-ffb989bec5b1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Cleaner database resource management","type":"text"}],"id":"1f5d71eb-c16d-4e01-84ea-4ba74d97de63","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"It also shows that you understand why unmanaged connections can cause production issues.","type":"text"}],"id":"410b2b54-c035-4dd5-9a72-68af53d49a1e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Important Security Note:","type":"text"},{"styles":{},"text":" Values are parameterized in this example, but ","type":"text"},{"styles":{"code":true},"text":"table_name","type":"text"},{"styles":{},"text":" is still injected into the SQL string. In a real project, restrict ","type":"text"},{"styles":{"code":true},"text":"table_name","type":"text"},{"styles":{},"text":" to a whitelist of approved table names before using it.","type":"text"}],"id":"4601e449-c7b0-48fc-a135-8a72b3251193","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{},"text":"GitHub README Callout","type":"text"}],"id":"532c2d5d-b7a4-4827-ae95-878d1fe5551c","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Database Persistence Layer:","type":"text"},{"styles":{},"text":" Powered by SQLAlchemy Core and managed using tuned ","type":"text"},{"styles":{"code":true},"text":"QueuePool","type":"text"},{"styles":{},"text":" parameters to reuse database connections safely. The loader standardizes SQL query execution using parameterized bound variables to reduce SQL injection risk and improve transaction reliability.","type":"text"}],"id":"6187b250-d55c-433a-a86f-3c92d56e8429","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"b0f773d3-28a4-4b52-b728-99c5c1993373","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"5. Showcase Blueprint: README and Architecture Diagrams","type":"text"}],"id":"c0454331-93de-4ca5-9d3a-9e29f943bbb1","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Hiring managers may spend less than a minute reviewing a GitHub repository.","type":"text"}],"id":"86ab02a4-e524-4c1f-9dcd-bca305fdfd80","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"If they cannot quickly identify what technologies you used and what problems you solved, your project becomes invisible.","type":"text"}],"id":"9fbe3878-cda8-4ebf-a82d-8e738f3f99df","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Your repository layout and documentation must be highly organized.","type":"text"}],"id":"378f83c3-dba5-4b5d-93ae-bf24bcdae406","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"db25393a-61f4-461a-b8b8-b3c16f730576","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"5.1 Repository Structure","type":"text"}],"id":"a2d319cb-dcc0-41dc-8191-a91bb0f7038b","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"├── .env.example\n├── README.md\n├── architecture_diagram.png\n├── requirements.txt\n├── src/\n│   ├── __init__.py\n│   ├── config.py\n│   ├── ingestion/\n│   │   ├── api_client.py\n│   │   └── s3_uploader.py\n│   ├── transformati