ider"},{"children":[],"content":[{"styles":{},"text":"Topic","type":"text"}],"id":"1d1786b6-67d4-4b17-95f4-85c1360c2f1d","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"A ","type":"text"},{"styles":{"bold":true},"text":"topic","type":"text"},{"styles":{},"text":" is a ","type":"text"},{"styles":{"bold":true},"text":"named channel or category","type":"text"},{"styles":{},"text":" for a stream of related events.","type":"text"}],"id":"9bb5e383-fb2f-456d-a278-e7284c8613ef","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Think of it as a labeled mailbox in the post office. Producers send to a specific topic; consumers subscribe to topics they care about.","type":"text"}],"id":"59dffd0c-bedb-4d58-acbf-a6f7202ac63a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Examples:","type":"text"}],"id":"12dc6ef5-1e45-4457-841a-d4b5dcf77626","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"code":true},"text":"payment-transactions","type":"text"}],"id":"a599dedd-06bc-45e9-93fb-05ae26fbcec1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"code":true},"text":"network-alarms","type":"text"}],"id":"9d3b52b5-e8ec-4719-bd4a-23c289b44b32","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"code":true},"text":"user-clickstream","type":"text"}],"id":"df011463-4071-4644-9b78-548a7046f3c0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"ty