INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-06-13T15:21:06.947627+00:00', '', '', '7630b5a9-6ed3-484a-9d96-74075b5bd726', false, '[]'::jsonb, '2026-06-13T15:21:12.89+00:00', '2ad473fe-77dd-481e-8ba7-4b2b0336173f', '', '9d79bb1a-50cc-45fc-a5a4-c6698bde6254', '', '[]'::jsonb, '[{"children":[],"content":[{"styles":{},"text":"Python for Data Engineering — Topic 14: The Labeling Station","type":"text"}],"id":"f4a420e0-8555-4550-af61-69973e834805","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Type Hints","type":"text"}],"id":"c0d82b03-02b3-4f5a-83e9-dccfc114dab8","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"id":"192f3dd7-52ea-43d7-941b-d50606fe28cf","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Very short intro","type":"text"}],"id":"b2871a1e-238c-4b1f-9af7-1bd5a2238ccc","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"At the ","type":"text"},{"styles":{"bold":true},"text":"Labeling Station","type":"text"},{"styles":{},"text":", every parcel gets a clear label describing what it contains before it moves on. A ","type":"text"},{"styles":{"bold":true},"text":"name tag","type":"text"},{"styles":{},"text":" on each parcel identifies what kind of input it expects. An ","type":"text"},{"styles":{"bold":true},"text":"output tag","type":"text"},{"styles":{},"text":" on the shipment label describes what will be delivered. These ","type":"text"},{"styles":{"bold":true},"text":"info cards","type":"text"},{"styles":{},"text":" do not physically enforce anything — a mislabeled parcel can still move — but they help the next worker understand exactly what they are dealing with. Type hints are the same: they document what your function expects and returns, making code safer and easier to understand. Topic 14 is the minimum type hint knowledge an internship interviewer will expect.","type":"text"}],"id":"fd561b94-f27f-48fd-9469-cd6de5379f6e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"9b7e468c-9380-4f5e-a7c7-a8d0f4bd0a06","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Mind map","type":"text"}],"id":"a13fd41c-4c69-420e-ae59-a40639ca9581","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"LABELING STATION\n(Type Hints)\n│\n├── Name Tag\n│   └── parameter annotation: def func(x: str, y: int)\n│\n├── Output Tag\n│   └── return annotation: -> str\n│\n├── Common Forms\n│   ├── Union: str | None\n│   ├── List: list[dict]\n│   └── Dict: dict[str, int]\n│\n└── Info Card\n    └── Documentation only. Not enforced at runtime.","type":"text"}],"id":"d0ce2e50-877c-4ba0-b9be-55b0fa5f152b","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"4aaac819-d1da-4c6c-881d-4c25eef0ece6","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Decision tree","type":"text"}],"id":"e1597cf3-a61c-4f70-a69e-211192dc4f01","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Writing a function?\n│\n├── Add Name Tags to parameters\n│   └── def func(name: str, count: int, items: list[dict]):\n│\n├── Add an Output Tag to the return\n│   └── -> dict[str, int]\n│\n├── Parameter can be None sometimes?\n│   └── Use union: date: str | None\n│\n├── Returning a list of dicts?\n│   └── -> list[dict]\n│\n└── Remember: these are hints, not guards\n    └── Python runs the code regardless of mislabeled types\n        └── Hints help readers, IDEs, and type checkers understand intent","type":"text"}],"id":"e7b27f0c-17e2-417e-a415-ccbf324d0a05","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"89ac90dd-27c8-4d13-839a-d8e6aa32cd3f","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Concept breakdown","type":"text"}],"id":"9e1db3c8-778c-4a3a-adeb-475f1ad931d8","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"id":"d4605f9b-b46b-4dc8-ad9a-4bf4efbc74fe","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"1) Name Tag — parameter annotations","type":"text"}],"id":"3c57c959-7672-4c2e-a9b7-d0cbf4b7f70e","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" Adding a type label after each parameter name using a colon. Describes what type of value the function expects.","type":"text"}],"id":"9d8359e5-6b52-4e3c-9294-eda747fcd0bc","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters in an interview:","type":"text"},{"styles":{},"text":" Type hints make code self-documenting. An interviewer looking at your code can immediately understand what each parameter should be. This is professional practice.","type":"text"}],"id":"4b546297-ff2b-4e4a-a4a2-64d4afbfa4c1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"80def545-a1f9-46f7-ae53-f54d4f4bdace","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"def process_order(order_id: str, amount: float, is_urgent: bool):\n    \"\"\"Process a single order.\"\"\"\n    print(f\"Processing {order_id} for ${amount}\")","type":"text"}],"id":"806949b8-1e35-4a31-9ff3-6bbbde10b27b","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Rule: The type hint is a label, not a guard. Python does not check it at runtime.","type":"text"}],"id":"f275b019-8fff-4acc-82ec-1ae8519593f2","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"ae41f551-7853-494d-b132-fe8983475ab2","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"2) Output Tag — return annotations","type":"text"}],"id":"123867d8-6892-4570-ba92-33acf182cdb8","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" Adding ","type":"text"},{"styles":{"code":true},"text":"-> type","type":"text"},{"styles":{},"text":" before the function body colon. Describes what type the function returns.","type":"text"}],"id":"69d9cd9a-6fcf-4621-9694-638c1a18cfac","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters in an interview:","type":"text"},{"styles":{},"text":" Return type hints complete the picture. Anyone calling your function knows exactly what to expect back.","type":"text"}],"id":"c9eb4586-d5e5-4ec2-bcc1-8815c35e866c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"16ab5e3c-bfd4-48a4-864c-6ed27ff68d96","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"def get_total(orders: list[dict]) -> float:\n    \"\"\"Return the sum of all order amounts.\"\"\"\n    return sum(order[\"amount\"] for order in orders)","type":"text"}],"id":"75c8bfbc-3940-4bd2-9f3a-db91c16b48ca","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"afa81a0c-3fcd-4775-99a5-3f78698fe899","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"3) Union types — ","type":"text"},{"styles":{"code":true},"text":"str | None","type":"text"}],"id":"60484435-0990-4278-8e2a-82100c524a31","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" A value that can be one of several types. Use the pipe ","type":"text"},{"styles":{"code":true},"text":"|","type":"text"},{"styles":{},"text":" to separate types. Very common: ","type":"text"},{"styles":{"code":true},"text":"str | None","type":"text"},{"styles":{},"text":" means a string or ","type":"text"},{"styles":{"code":true},"text":"None","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"86ab2e9b-8868-4824-94c0-8d9f9d7e99a3","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters in an interview:","type":"text"},{"styles":{},"text":" Optional values (that might be ","type":"text"},{"styles":{"code":true},"text":"None","type":"text"},{"styles":{},"text":") are everywhere in real data. Knowing how to hint this is expected.","type":"text"}],"id":"7342b10a-f424-443b-b5de-ad872ce4e5d5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"685c5dde-96a0-4462-bf80-eb60109483ae","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"def find_customer(customer_id: str) -> dict | None:\n    \"\"\"Return customer dict, or None if not found.\"\"\"\n    # might return a dict or None\n    pass\n\ndef get_age(person: dict) -> int | None:\n    \"\"\"Age might be in the dict, or missing.\"\"\"\n    return person.get(\"age\")  # could be int or None","type":"text"}],"id":"f891df5a-d132-478f-a2c1-a5bf0dc665e6","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"a9c5f047-dfce-486b-98a6-9b5034f68e17","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"4) Container types — ","type":"text"},{"styles":{"code":true},"text":"list[dict]","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"dict[str, int]","type":"text"}],"id":"a4b584d0-bee0-4fbe-8c5f-25701562be0a","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" Specifying not just that a parameter is a list, but what kind of items the list contains. Same for dicts: what types are the keys and values.","type":"text"}],"id":"5168a010-0ef7-49b4-8684-8cb3e32da44c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters in an interview:","type":"text"},{"styles":{},"text":" Container types make your intent crystal clear. ","type":"text"},{"styles":{"code":true},"text":"list","type":"text"},{"styles":{},"text":" alone is vague. ","type":"text"},{"styles":{"code":true},"text":"list[dict]","type":"text"},{"styles":{},"text":" tells the reader exactly what is expected.","type":"text"}],"id":"636dab5f-03e8-48b3-a143-08ae78a69de7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"d397185f-d456-4a67-8942-a6528e55ef32","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"def process_orders(orders: list[dict]) -> dict[str, float]:\n    \"\"\"\n    Take a list of order dicts.\n    Return a summary dict with order IDs as keys and totals as values.\n    \"\"\"\n    summary = {}\n    for order in orders:\n        summary[order[\"id\"]] = order[\"amount\"]\n    return summary","type":"text"}],"id":"dbd72431-48d0-4adb-ace4-4109f74349d6","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Memorize the syntax: ","type":"text"},{"styles":{"code":true},"text":"list[str]","type":"text"},{"styles":{},"text":" — list of strings ","type":"text"},{"styles":{"code":true},"text":"list[dict]","type":"text"},{"styles":{},"text":" — list of dicts ","type":"text"},{"styles":{"code":true},"text":"dict[str, int]","type":"text"},{"styles":{},"text":" — dict with string keys and int values ","type":"text"},{"styles":{"code":true},"text":"dict[str, float]","type":"text"},{"styles":{},"text":" — dict with string keys and float values","type":"text"}],"id":"23328575-1c0a-4b82-bc1e-2cd06fba6cd6","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"ff1a0360-5282-4a73-bfac-d44fc66352a9","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"5) Info Card — documentation, not enforcement","type":"text"}],"id":"76c79e85-44b3-4584-9715-b78a66616d62","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" Type hints are ","type":"text"},{"styles":{"bold":true},"text":"hints","type":"text"},{"styles":{},"text":", not guards. Python does not check them at runtime. A function with ","type":"text"},{"styles":{"code":true},"text":"def func(x: str)","type":"text"},{"styles":{},"text":" will happily accept an integer and run until it hits code that assumes ","type":"text"},{"styles":{"code":true},"text":"x","type":"text"},{"styles":{},"text":" is a string.","type":"text"}],"id":"8e80f232-d8c3-431a-8b21-bbea2bd49011","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters in an interview:","type":"text"},{"styles":{},"text":" This is a critical distinction. Interviewers will test whether you understand that hints are advisory, not enforced. Misunderstanding this is a common mistake.","type":"text"}],"id":"9b2959b9-fbd9-4b74-8722-a4736db0665f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"0b085622-5311-4a3b-bfbe-9f62a15907c3","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"def greet(name: str) -> str:\n    \"\"\"Hint says ''name'' should be a string.\"\"\"\n    return f\"Hello, {name}!\"\n\n# This works fine:\nprint(greet(\"Alice\"))          # correct type — fine\n\n# This also runs (Python does not check the hint):\nprint(greet(123))              # wrong type — runs, prints \"Hello, 123!\"\n\n# This crashes (only when Python actually uses the type):\ngreet(None).upper()            # TypeError only when .upper() is called","type":"text"}],"id":"40be95d0-92c4-409b-b87c-4d033b5a2bed","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"78059845-c486-4b96-b10c-d763561b1662","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Common mistakes","type":"text"}],"id":"b284b935-2c8a-4291-b24f-a35fdfdf9cbc","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Mistake","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Fix","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Thinking type hints are enforced at runtime","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"They are not. Python ignores them. They are for humans and type checkers.","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Using ","type":"text"},{"styles":{"code":true},"text":"Optional[str]","type":"text"},{"styles":{},"text":" instead of ","type":"text"},{"styles":{"code":true},"text":"str | None","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Modern Python prefers the ","type":"text"},{"styles":{"code":true},"text":"|","type":"text"},{"styles":{},"text":" syntax. It is cleaner.","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Forgetting to annotate return types","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Always add ","type":"text"},{"styles":{"code":true},"text":"-> ReturnType","type":"text"},{"styles":{},"text":" so readers know what the function produces.","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Using vague ","type":"text"},{"styles":{"code":true},"text":"list","type":"text"},{"styles":{},"text":" instead of ","type":"text"},{"styles":{"code":true},"text":"list[dict]","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Be specific: ","type":"text"},{"styles":{"code":true},"text":"list[dict]","type":"text"},{"styles":{},"text":" is much clearer than ","type":"text"},{"styles":{"code":true},"text":"list","type":"text"},{"styles":{},"text":".","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Annotating but then passing the wrong type anyway","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Type hints are hints, not guards. If code will break, add runtime checks.","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Forgetting that ","type":"text"},{"styles":{"code":true},"text":"None","type":"text"},{"styles":{},"text":" is a type","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"code":true},"text":"str | None","type":"text"},{"styles":{},"text":" means \"a string or the value None\", not \"a string with a None default\".","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"2667e2c2-8c35-4931-98a7-3ecc101aacab","props":{"textColor":"default"},"type":"table"},{"children":[],"id":"f0c9faaf-6150-43ec-b3d0-2df4a396f04d","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Practice ideas","type":"text"}],"id":"446574aa-37b1-4fd1-a33e-542909897ee6","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Write a function ","type":"text"},{"styles":{"code":true},"text":"clean_status(status: str | None) -> str","type":"text"},{"styles":{},"text":" that returns a cleaned status, defaulting to ","type":"text"},{"styles":{"code":true},"text":"\"unknown\"","type":"text"},{"styles":{},"text":" if ","type":"text"},{"styles":{"code":true},"text":"None","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"ebfd0f1e-e78c-4f7d-82b0-26e8464b05e0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Write a function ","type":"text"},{"styles":{"code":true},"text":"get_orders(customer_id: str) -> list[dict]","type":"text"},{"styles":{},"text":" with proper type hints.","type":"text"}],"id":"3c1b2e62-3566-464f-9998-af08b100e19a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Write a function ","type":"text"},{"styles":{"code":true},"text":"summarize(orders: list[dict]) -> dict[str, float]","type":"text"},{"styles":{},"text":" that returns a summary dict.","type":"text"}],"id":"150b71d7-c0df-4bcc-858a-743863013a56","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Write a function that violates its own type hint (e.g., returns an ","type":"text"},{"styles":{"code":true},"text":"int","type":"text"},{"styles":{},"text":" when hint says ","type":"text"},{"styles":{"code":true},"text":"str","type":"text"},{"styles":{},"text":"). Run it and show that Python does not enforce the hint.","type":"text"}],"id":"129bc8f9-e61d-4afd-b863-a8cfcb5ebd0f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"For each function, explain aloud what the type hints mean and why they matter.","type":"text"}],"id":"d64bcf45-ddbd-403b-b8bb-9fae997dff6d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"id":"e1e55b10-5992-4ddc-b992-3e103a7ce673","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Final integrated coding example","type":"text"}],"id":"39799b4b-869e-4e7e-bdf2-095e7438ced1","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Scenario:","type":"text"},{"styles":{},"text":" A small pipeline has utility functions for cleaning orders, calculating totals, and generating reports. Add type hints to each function to document what they expect and return.","type":"text"}],"id":"767f509c-b093-47b2-b8e9-da66bdfae16c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"# pipeline.py\n\ndef clean_status(status: str | None) -> str:\n    \"\"\"\n    Clean an order status string.\n    \n    Returns a lowercase status, or \"unknown\" if input is None.\n    Type hints are documentation only — Python does not enforce them.\n    \"\"\"\n    if status is None:\n        return \"unknown\"\n    return status.strip().lower()\n\n\ndef get_total(orders: list[dict]) -> float:\n    \"\"\"\n    Calculate total amount from a list of order dicts.\n    \n    Each dict must have an \"amount\" key with a numeric value.\n    Returns a float (sum of all amounts).\n    \"\"\"\n    return sum(order.get(\"amount\", 0) for order in orders)\n\n\ndef process_orders(\n    orders: list[dict],\n    threshold: float | None = None\n) -> dict[str, float]:\n    \"\"\"\n    Process orders and return a summary.\n    \n    Parameters:\n      orders: list of order dicts, each with \"id\" and \"amount\" keys\n      threshold: optional minimum amount filter (None means no filter)\n    \n    Returns:\n      dict mapping order ID (str) to total (float)\n    \"\"\"\n    summary = {}\n    \n    for order in orders:\n        order_id = order.get(\"id\", \"unknown\")\n        amount = order.get(\"amount\", 0)\n        \n        # Skip if threshold is set and amount is below it\n        if threshold is not None and amount < threshold:\n            continue\n        \n        summary[order_id] = amount\n    \n    return summary\n\n\n# --- Example usage ---\n\nif __name__ == \"__main__\":\n    # Sample data\n    orders = [\n        {\"id\": \"ORD-001\", \"amount\": 250.0, \"status\": \"  Shipped  \"},\n        {\"id\": \"ORD-002\", \"amount\": 150.0, \"status\": None},\n        {\"id\": \"ORD-003\", \"amount\": 500.0, \"status\": \"pending\"},\n    ]\n    \n    # --- Name Tags: parameters are annotated ---\n    # --- Output Tags: returns are annotated ---\n    \n    # clean_status: str | None -> str\n    print(clean_status(orders[1][\"status\"]))  # \"unknown\"\n    \n    # get_total: list[dict] -> float\n    total = get_total(orders)\n    print(f\"Total: ${total}\")                  # Total: $900.0\n    \n    # process_orders: (list[dict], float | None) -> dict[str, float]\n    summary = process_orders(orders, threshold=200.0)\n    print(f\"Summary: {summary}\")               # {''ORD-001'': 250.0, ''ORD-003'': 500.0}\n    \n    # --- Info Card: hints are documentation, not enforcement ---\n    # This code runs fine even though type hint says str:\n    result = clean_status(123)  # Python does not check — hint is just a label\n    print(f\"Result: {result}\")   # Result: unknown","type":"text"}],"id":"b9cbfc50-e264-47cd-8ac4-be4eb7b50a50","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"What each section maps to:","type":"text"}],"id":"bc0a39d6-0a0d-43ff-8849-ee1837f95bd9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Code section","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Metaphor part","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"status: str | None","type":"text"},{"styles":{},"text":" parameter","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Name Tag","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"-> str","type":"text"},{"styles":{},"text":" / ","type":"text"},{"styles":{"code":true},"text":"-> float","type":"text"},{"styles":{},"text":" / ","type":"text"},{"styles":{"code":true},"text":"-> dict[str, float]","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Output Tag","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"str | None","type":"text"},{"styles":{},"text":" union type","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Union type hint","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"list[dict]","type":"text"},{"styles":{},"text":" container type","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Container type hint","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"dict[str, float]","type":"text"},{"styles":{},"text":" specific dict","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Container type hint","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"\"Python does not enforce...\" comment","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Info Card — hints are documentation","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"2580f742-6f43-4b0c-b699-66f8e6cce82a","props":{"textColor":"default"},"type":"table"},{"children":[],"id":"3976b0b8-0415-4417-93b5-4e3d7a5f00f9","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"italic":true},"text":"If you can write these functions from memory — with correct parameter and return type hints, union types, and container types — and explain that hints are documentation not enforcement, you are ready for internship-level type hint questions at the Labeling Station.","type":"text"}],"id":"7d28f726-1c79-43ca-84d9-286c62350f05","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[],"id":"1d741c9b-09dd-41a3-ad10-29d3727d3f45","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"}]'::jsonb, '3e9e3dd3-a59b-4b02-968a-ee95e7317583') ON CONFLICT ("node_id") DO UPDATE SET "bad_example" = EXCLUDED."bad_example", "completed_at" = EXCLUDED."completed_at", "created_at" = EXCLUDED."created_at", "definition" = EXCLUDED."definition", "good_example" = EXCLUDED."good_example", "is_completed" = EXCLUDED."is_completed", "key_points" = EXCLUDED."key_points", "last_edited" = EXCLUDED."last_edited", "map_id" = EXCLUDED."map_id", "mental_model" = EXCLUDED."mental_model", "notes" = EXCLUDED."notes", "resources" = EXCLUDED."resources", "rich_content" = EXCLUDED."rich_content", "user_id" = EXCLUDED."user_id";
