code":true},"text":"NOT IN","type":"text"},{"styles":{},"text":" vs ","type":"text"},{"styles":{"code":true},"text":"NOT EXISTS","type":"text"},{"styles":{},"text":" Edge Case ⚠️","type":"text"}],"id":"efb9f957-0c1d-431c-aa52-320ea44328d6","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"In interviews, if the interviewer asks ","type":"text"},{"styles":{"italic":true},"text":"\"What potential risk does this query have?\"","type":"text"},{"styles":{},"text":", mention this:","type":"text"}],"id":"cffd2f05-5015-48da-b93a-a1ce3c1d0096","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"If ","type":"text"},{"styles":{"code":true},"text":"accounts.customer_id","type":"text"},{"styles":{"italic":true},"text":" ever contains a ","type":"text"},{"styles":{"code":true},"text":"NULL","type":"text"},{"styles":{"italic":true},"text":" value, ","type":"text"},{"styles":{"code":true},"text":"NOT IN","type":"text"},{"styles":{"italic":true},"text":" will evaluate to ","type":"text"},{"styles":{"code":true},"text":"UNKNOWN","type":"text"},{"styles":{"italic":true},"text":" and return zero rows! To prevent this, either add ","type":"text"},{"styles":{"code":true},"text":"WHERE customer_id IS NOT NULL","type":"text"},{"styles":{"italic":true},"text":" inside the subquery or use ","type":"text"},{"styles":{"code":true},"text":"NOT EXISTS","type":"text"},{"styles":{"italic":true},"text":".\"","type":"text"}],"id":"e3e46752-8814-4305-a1db-4a50f37d80c8","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{},"text":"-- Safe alternative using NOT EXISTS (Correlated Subquery version)\nSELECT c.name\nFROM customers AS c\nWHERE NOT EXISTS (\n    SELECT 1 \n    FROM accounts AS a \n    WHERE a.customer_id = c.customer_id\n);\n","type":"text"}],"id":"a5e4d262-42fa-4efe-8473-c6953ed4c80d","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"id":"02112ef6-bff4-483a-80a2-06f6f851ea33","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Ready for ","type":"text"},{"styles":{"bold":true},"text":"Question 37","type":"text"},{"styles":{},"text":" whenever you are!","type":"text"}],"id":"81f59e72-8c7c-40e9-9b7c-b725d86daca4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Rewrite Q37 using ","type":"text"},{"styles":{"code":true},"text":"NOT EXISTS","type":"text"},{"styles":{},"text":" instead of ","type":"text"},{"styles":{"code":true},"text":"NOT IN","type":"text"},{"styles":{},"text":". Why is ","type":"text"},{"styles":{"code":true},"text":"NOT EXISTS","type":"text"},{"styles":{},"text":" generally considered safer?","type":"text"}],"id":"41e742e9-7d35-49af-a3f2-e5a61b8682a8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Question 37 Evaluation","type":"text"}],"id":"c3e7cd65-6d65-4a00-8d77-e97bf9ef82e8","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Your Answer:","type":"text"}],"id":"19cbb40d-765c-4096-b98a-4b961ebc5057","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"SELECT name\nFROM customers \nWHERE NOT EXISTS (\n\tSELECT customer_id\n\tFROM accounts \n)\n","type":"text"}],"id":"7393d789-b5b4-437b-b073-483cc0fd12ad","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"id":"60f9a506-47ab-4f58-925e-2a6ca614a17c","props":{},"type":"divider"},{"children":[],"content":