INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-06-19T05:06:39.600378+00:00', '', '', 'eec23390-4b58-4c15-8c4a-ce3520b79d2b', false, '[]'::jsonb, '2026-06-19T15:03:42.19+00:00', '2ad473fe-77dd-481e-8ba7-4b2b0336173f', '', 'd78d6357-2508-408a-b25f-24038d19b3f9', '', '[]'::jsonb, '[{"children":[],"id":"10d42036-3c2e-4931-a534-2b33bc9ae15c","props":{"backgroundColor":"default","caption":"","name":"Gemini_Generated_Image_6bf39l6bf39l6bf3.png","showPreview":true,"textAlignment":"left","url":"https://ixmvqmfesibpnrjmvzuj.supabase.co/storage/v1/object/public/study-assets/3e9e3dd3-a59b-4b02-968a-ee95e7317583/d78d6357-2508-408a-b25f-24038d19b3f9/1781881419385-ub7u5fkkja.webp"},"type":"image"},{"children":[],"content":[],"id":"be980d2c-0602-44a0-9e8a-927cb437e9a5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"}]'::jsonb, '3e9e3dd3-a59b-4b02-968a-ee95e7317583') ON CONFLICT ("node_id") DO UPDATE SET "bad_example" = EXCLUDED."bad_example", "completed_at" = EXCLUDED."completed_at", "created_at" = EXCLUDED."created_at", "definition" = EXCLUDED."definition", "good_example" = EXCLUDED."good_example", "is_completed" = EXCLUDED."is_completed", "key_points" = EXCLUDED."key_points", "last_edited" = EXCLUDED."last_edited", "map_id" = EXCLUDED."map_id", "mental_model" = EXCLUDED."mental_model", "notes" = EXCLUDED."notes", "resources" = EXCLUDED."resources", "rich_content" = EXCLUDED."rich_content", "user_id" = EXCLUDED."user_id";
INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-06-11T12:20:57.347609+00:00', '', '', 'ccd081c5-b491-4a74-9e0f-f361690ac838', false, '[]'::jsonb, '2026-06-11T12:29:11.505+00:00', '2ad473fe-77dd-481e-8ba7-4b2b0336173f', '', '929787e0-535b-432f-896d-bc55fd8861a1', '', '[]'::jsonb, '[{"children":[],"content":[{"styles":{"bold":true},"text":"🧠 The Master Mental Model — The Banking Operations Centre","type":"text"}],"id":"3d34fb65-ae0d-45ff-b0dc-e204eae3e817","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Before any syntax, picture this:","type":"text"}],"id":"b7773ab9-ae49-49bc-9e16-22705183f27f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"textYour Python program is a Banking Operations Centre.\n\nTransactions are happening every second.\nThings go wrong constantly — network drops, invalid inputs,\nfiles missing, databases timing out.\n\nThe Operations Centre has three zones:\n\n┌─────────────────────────────────────────────────────┐\n│  TRY ZONE        │ \"Attempt the operation here\"      │\n│  Normal work     │ Process the transaction           │\n├─────────────────────────────────────────────────────┤\n│  EXCEPT ZONE     │ \"Something went wrong — handle it\"│\n│  Incident desk   │ Log it, notify, recover           │\n├─────────────────────────────────────────────────────┤\n│  FINALLY ZONE    │ \"Always do this no matter what\"   │\n│  Closing duties  │ Close files, release connections  │\n└─────────────────────────────────────────────────────┘","type":"text"}],"id":"ba620080-a9a4-4d0b-9673-6dedc639b1b8","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Whether the transaction succeeds or fails — the closing duties always happen. The incident desk only activates when something breaks. Normal work always runs in the try zone. That''s the entire mental model for every error handling pattern you''ll ever write.","type":"text"}],"id":"68d63f7d-74f2-47f5-ac1a-200c41014566","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"5e0d6568-d904-4551-85c7-e335973796ed","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"⚠️ What Is an Exception?","type":"text"}],"id":"48bceaf3-ec94-4e8f-a003-a218a80a2a97","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"An exception is Python''s way of saying ","type":"text"},{"styles":{"italic":true},"text":"\"something unexpected happened and I can''t continue normally.\"","type":"text"},{"styles":{},"text":" Without handling it, the program crashes and prints a ","type":"text"},{"styles":{"bold":true},"text":"traceback","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"99a1cdd4-3861-41a0-8b0c-67227807d16a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"python# This crashes with no error handling:\nbalance = 50000\nwithdrawal = 60000\nresult = balance - withdrawal\n\n# Wait — let''s make it actually crash:\naccount_data = {''balance'': 50000}\nprint(account_data[''owner''])    # KeyError: ''owner''\n\nnumbers = [1, 2, 3]\nprint(numbers[10])              # IndexError: list index out of range\n\nint(\"abc\")                      # ValueError: invalid literal for int()\n\n10 / 0                          # ZeroDivisionError: division by zero","type":"text"}],"id":"dd49bf4c-1352-4af0-92db-4ba46eddc053","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Each of these is a different ","type":"text"},{"styles":{"bold":true},"text":"type","type":"text"},{"styles":{},"text":" of exception. Python has a hierarchy of them — and that hierarchy matters.","type":"text"}],"id":"0a326bf1-96f4-48d1-9f9b-1d0af90b555b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"88382e34-3c0a-42bc-b3f9-0e82542f579d","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"🌳 The Exception Hierarchy — The Family Tree","type":"text"}],"id":"72af82c8-9196-45ca-a265-52dd3fdd6195","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"text\nBaseException\n└── Exception                    ← catch-all for most errors\n      ├── ValueError             ← wrong type/value (\"abc\" → int)\n      ├── TypeError              ← wrong type operation (1 + \"a\")\n      ├── KeyError               ← dict key doesn''t exist\n      ├── IndexError             ← list index out of range\n      ├── FileNotFoundError      ← file doesn''t exist\n      ├── PermissionError        ← no access to file\n      ├── ZeroDivisionError      ← division by zero\n      ├── AttributeError         ← object has no such attribute\n      ├── ImportError            ← module not found\n      ├── StopIteration          ← generator exhausted ← you just learned this!\n      └── OSError\n            ├── FileNotFoundError\n            └── PermissionError","type":"text"}],"id":"dfd2e0af-056e-4bdb-9a73-87fed0e2e4ac","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why the hierarchy matters:","type":"text"},{"styles":{},"text":" When you ","type":"text"},{"styles":{"code":true},"text":"except ValueError","type":"text"},{"styles":{},"text":", you catch ONLY ValueError. When you ","type":"text"},{"styles":{"code":true},"text":"except Exception","type":"text"},{"styles":{},"text":", you catch EVERYTHING under it. Catching too broadly is bad practice — like saying \"if anything ever goes wrong in the entire bank, just print sorry.\"","type":"text"}],"id":"a795463a-816c-4c4f-bb85-74b6129bfaa8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"2d82a022-1b1b-4255-b323-23f357f7893c","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"🏗️ try / except / else / finally — The Full Structure","type":"text"}],"id":"d864de57-93c0-422c-8718-be5b9efbcfa8","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"pythontry:\n    # Attempt the operation\n    pass\n\nexcept SpecificError:\n    # Handle this specific error type\n    pass\n\nexcept AnotherError:\n    # Handle a different error type\n    pass\n\nexcept Exception as e:\n    # Catch anything else (use sparingly)\n    pass\n\nelse:\n    # Runs ONLY if try succeeded (no exception)\n    pass\n\nfinally:\n    # ALWAYS runs — success or failure\n    pass","type":"text"}],"id":"a02eb23d-9be8-433c-8584-a4326a172d21","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Most people know try/except. The ones who know ","type":"text"},{"styles":{"code":true},"text":"else","type":"text"},{"styles":{},"text":" and ","type":"text"},{"styles":{"code":true},"text":"finally","type":"text"},{"styles":{},"text":" stand out in interviews.","type":"text"}],"id":"f8ce3a07-6633-48bf-95d0-17f8cc579fb2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"b808f156-2d76-41b1-b718-6aa3195e6b9c","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"💰 Complete Banking Example — All Zones in Action","type":"text"}],"id":"e41bf887-6361-4855-a93d-85eb768d636a","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"pythondef process_withdrawal(account_id, amount, db_connection):\n    cursor = None\n\n    try:\n        # TRY ZONE — attempt the operation\n        cursor = db_connection.cursor()\n\n        # Fetch account\n        cursor.execute(\n            \"SELECT balance FROM accounts WHERE account_id = %s\",\n            (account_id,)\n        )\n        row = cursor.fetchone()\n\n        if row is None:\n            raise ValueError(f\"Account {account_id} not found\")\n\n        balance = row[0]\n\n        if amount <= 0:\n            raise ValueError(\"Withdrawal amount must be positive\")\n\n        if amount > balance:\n            raise ValueError(f\"Insufficient funds: balance Rs.{balance}, requested Rs.{amount}\")\n\n        # Update balance\n        cursor.execute(\n            \"UPDATE accounts SET balance = balance - %s WHERE account_id = %s\",\n            (amount, account_id)\n        )\n        db_connection.commit()\n\n    except ValueError as e:\n        # Business logic errors — known, expected, recoverable\n        db_connection.rollback()\n        print(f\"Transaction rejected: {e}\")\n        return None\n\n    except Exception as e:\n        # Unexpected errors — unknown, log them\n        db_connection.rollback()\n        print(f\"Unexpected error processing withdrawal: {e}\")\n        raise   # re-raise — let the caller decide what to do\n\n    else:\n        # Only runs if try succeeded completely\n        print(f\"Withdrawal of Rs.{amount} from {account_id} successful\")\n        return balance - amount\n\n    finally:\n        # ALWAYS runs — close the cursor whether it worked or not\n        if cursor:\n            cursor.close()\n        print(\"Database cursor closed\")","type":"text"}],"id":"75c2cdb6-9105-495f-9211-f2f057decd16","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"The flow visualised:","type":"text"}],"id":"5e2c4611-e642-4306-bfde-a3ffb2f9d587","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"textAttempt withdrawal\n      │\n      ├── Account not found?      → ValueError → rollback → return None\n      ├── Negative amount?        → ValueError → rollback → return None\n      ├── Insufficient funds?     → ValueError → rollback → return None\n      ├── DB connection dropped?  → Exception  → rollback → re-raise\n      │\n      ├── Everything worked?      → else block → \"successful\"\n      │\n      └── Regardless of outcome   → finally → close cursor","type":"text"}],"id":"340bfe00-782e-423b-bdb2-7f549cca3366","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"55efa5cc-b560-4462-8dc2-475f21c46493","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"🎯 ","type":"text"},{"styles":{"code":true},"text":"raise","type":"text"},{"styles":{"bold":true},"text":" — Throwing Exceptions Yourself","type":"text"}],"id":"cdf51032-1317-42a6-aa75-8ef2f2b673a4","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"You''re not limited to catching exceptions — you can throw them too. This is how you enforce business rules:","type":"text"}],"id":"0ed6fde6-7e4d-4c4e-af3f-6be7eaed0076","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"pythondef deposit(self, amount):\n    if not isinstance(amount, (int, float)):\n        raise TypeError(f\"Amount must be a number, got {type(amount).__name__}\")\n    if amount <= 0:\n        raise ValueError(f\"Deposit amount must be positive, got {amount}\")\n    if amount > 1_000_000:\n        raise ValueError(\"Single deposit cannot exceed Rs.1,000,000 — contact branch\")\n    self.__balance += amount","type":"text"}],"id":"33f26670-4b04-40be-b866-59710f1a0d7e","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"code":true},"text":"raise","type":"text"},{"styles":{"bold":true},"text":" alone","type":"text"},{"styles":{},"text":" (inside an except block) re-raises the current exception — lets it bubble up to the caller:","type":"text"}],"id":"30582bff-0bed-4732-b0ca-dff2bfb6062d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"pythonexcept Exception as e:\n    log_to_file(e)   # log it here\n    raise            # then let it propagate up","type":"text"}],"id":"463d949b-6646-44d6-8cad-bc8132cfd245","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"62dcbc7b-7ac4-4bfd-af24-20f025b693d7","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"🏦 Custom Exceptions — Your Own Exception Types","type":"text"}],"id":"483b4c5e-f8b0-4d75-8b34-f6f7053c7148","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"For a banking system, generic exceptions like ","type":"text"},{"styles":{"code":true},"text":"ValueError","type":"text"},{"styles":{},"text":" don''t carry enough meaning. Custom exceptions make your code self-documenting:","type":"text"}],"id":"1d6b3d03-988e-4da4-a67e-06003fba6479","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"# Define your exception hierarchy\nclass BankingError(Exception):\n    \"\"\"Base class for all banking exceptions\"\"\"\n    pass\n\nclass InsufficientFundsError(BankingError):\n    def __init__(self, balance, amount):\n        self.balance = balance\n        self.amount = amount\n        super().__init__(\n            f\"Cannot withdraw Rs.{amount}. Available balance: Rs.{balance}\"\n        )\n\nclass AccountFrozenError(BankingError):\n    def __init__(self, account_id):\n        super().__init__(f\"Account {account_id} is frozen — contact branch\")\n\nclass DailyLimitExceededError(BankingError):\n    def __init__(self, limit):\n        super().__init__(f\"Daily transaction limit of Rs.{limit} exceeded\")\n\n# Using custom exceptions\ndef withdraw(self, amount):\n    if self.status == ''FROZEN'':\n        raise AccountFrozenError(self.account_id)\n    if amount > self.__balance:\n        raise InsufficientFundsError(self.__balance, amount)\n    if amount > self.daily_limit:\n        raise DailyLimitExceededError(self.daily_limit)\n    self.__balance -= amount\n\n# Catching custom exceptions — precisely\ntry:\n    account.withdraw(50000)\nexcept InsufficientFundsError as e:\n    print(f\"Rejected: {e}\")\n    notify_customer(e.balance, e.amount)  # access the custom attributes\nexcept AccountFrozenError as e:\n    print(f\"Blocked: {e}\")\n    escalate_to_compliance()\nexcept DailyLimitExceededError as e:\n    print(f\"Limit hit: {e}\")","type":"text"}],"id":"54b241c9-4142-46d9-9993-3701e6267752","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Mental model — Custom Exception as a Specific Alarm:","type":"text"}],"id":"4caadc76-f44a-43eb-99db-060b8eaf1798","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"A generic exception is a building''s fire alarm — it tells you \"something is wrong\" but not what or where. A custom exception is a specific sensor — \"smoke detector, 3rd floor, east wing.\" You can respond precisely instead of evacuating the whole building every time.","type":"text"}],"id":"5125ed40-1d45-4f88-9a41-be55e9da85d7","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"e1f59cc6-2339-4fdb-9fce-3b47bf26de32","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"📖 Reading a Stack Trace — The Skill Interviewers Test","type":"text"}],"id":"7f50c57a-d8b4-4cbe-b6f4-a2c42fbd29da","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"This is directly on your JD. When something crashes in production, you read the traceback bottom-up:","type":"text"}],"id":"dd866ec6-fc05-4346-bcda-84e0d3525867","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"textTraceback (most recent call last):\n  File \"banking_app.py\", line 47, in process_payment   ← 3. where it was called from\n    result = transfer(from_acc, to_acc, amount)\n  File \"banking_app.py\", line 23, in transfer           ← 2. where transfer was called\n    validate_account(to_acc)\n  File \"banking_app.py\", line 12, in validate_account   ← 1. where it actually broke\n    if account[''status''] == ''ACTIVE'':\nKeyError: ''status''                                       ← 0. START HERE — the actual error","type":"text"}],"id":"a5942a8b-1dfa-40a3-a20c-bab41084d23b","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"The four-step reading process:","type":"text"}],"id":"9ada76fa-e2b9-44dd-9739-e95ae89a1ab6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"textStep 1 — Read the BOTTOM line first\n          KeyError: ''status'' → a dict was accessed with a key that doesn''t exist\n\nStep 2 — Read the file and line number just above it\n          banking_app.py line 12 in validate_account\n          if account[''status''] == ''ACTIVE''\n          → the account dict is missing the ''status'' key\n\nStep 3 — Read upward to find how we got here\n          transfer() called validate_account()\n          process_payment() called transfer()\n\nStep 4 — Form the hypothesis\n          \"account dict was passed without a ''status'' key —\n           either it came from a partial DB query or a new\n           account that hasn''t been fully initialised\"","type":"text"}],"id":"fb1fd8ee-bba7-4f13-971b-eea4ec0d4d32","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"In an interview:","type":"text"},{"styles":{},"text":" If shown a stack trace, always say ","type":"text"},{"styles":{"italic":true},"text":"\"I read from the bottom up. The error is X, it occurred in function Y at line Z, called from...\"","type":"text"},{"styles":{},"text":" — that structure alone tells the interviewer you know what you''re doing.","type":"text"}],"id":"9b7509bc-de07-47eb-a401-a12d44241664","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"d7df555f-17c3-4459-82b9-24de9395e60a","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"🔗 How Everything Connects — The Full Mental Model","type":"text"}],"id":"34e778a4-a756-433f-ba2a-9393a37f9522","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Now let''s tie it all together with everything you''ve learned:","type":"text"}],"id":"65f3a189-02a6-43f3-980e-0ac2d08c4536","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"textDECORATORS\n    │\n    │  @require_auth        → raises PermissionError if not authenticated\n    │  @validate_amount     → raises ValueError if amount invalid\n    │  @timer               → no exception, just measures\n    ▼\nFUNCTION CALL\n    │\n    ▼\nTRY BLOCK\n    │  calls class method on BankAccount object (OOP)\n    │  method uses private __balance (encapsulation)\n    │  SavingsAccount overrides withdraw (polymorphism/inheritance)\n    │\n    ├── EXCEPT InsufficientFundsError → rollback, notify\n    ├── EXCEPT AccountFrozenError     → escalate\n    ├── EXCEPT Exception              → log, re-raise\n    │\n    ├── ELSE   → transaction successful, record in list (list)\n    │            update dict cache    (dict)\n    │            add txn_id to set    (set — deduplication)\n    │\n    └── FINALLY → close DB cursor, release connection\n                  (always, whether it worked or not)\n                   │\n                   └── generator → if processing bulk transactions,\n                                   yield one at a time from log file\n                                   StopIteration when file ends","type":"text"}],"id":"002c0d7c-2b60-4b09-8dc8-1f8cd23dddd2","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"383436e5-3e8b-43bf-94c4-93de728e3f7b","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"✅ Interview Questions — With Strong Answers","type":"text"}],"id":"8b1feda4-faed-40e4-ad8d-33c440880880","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"\"What is the difference between ","type":"text"},{"styles":{"code":true},"text":"except Exception","type":"text"},{"styles":{"bold":true},"text":" and ","type":"text"},{"styles":{"code":true},"text":"except SpecificError","type":"text"},{"styles":{"bold":true},"text":"?\"","type":"text"}],"id":"102d8970-6a9c-4fea-91a3-c747b894a82f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true,"italic":true},"text":"\"Catching ","type":"text"},{"styles":{"code":true},"text":"Exception","type":"text"},{"styles":{"bold":true,"italic":true},"text":" catches everything — it''s a safety net but it hides bugs. Catching a specific type like ","type":"text"},{"styles":{"code":true},"text":"ValueError","type":"text"},{"styles":{"bold":true,"italic":true},"text":" means you handle exactly what you expect and let unexpected errors bubble up to a level that can properly deal with them. In banking code I''d catch specific business errors like ","type":"text"},{"styles":{"code":true},"text":"InsufficientFundsError","type":"text"},{"styles":{"bold":true,"italic":true},"text":" explicitly and only use bare ","type":"text"},{"styles":{"code":true},"text":"Exception","type":"text"},{"styles":{"bold":true,"italic":true},"text":" as a last resort with a re-raise.\"","type":"text"}],"id":"8b123aa3-b593-4f36-8d7d-581b05dcf860","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"bold":true},"text":"\"What does ","type":"text"},{"styles":{"code":true},"text":"finally","type":"text"},{"styles":{"bold":true},"text":" do and when would you use it?\"","type":"text"}],"id":"6643c96c-1fba-42d0-8b63-32aae8e53d97","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true,"italic":true},"text":"\"Finally always executes — whether the try block succeeded or an exception was raised. I use it for cleanup that must happen regardless: closing database cursors, releasing file handles, closing network connections. In banking, you never want a DB connection left open because an exception interrupted the normal flow.\"","type":"text"}],"id":"456abe20-60a0-418a-be75-235e5e605950","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"bold":true},"text":"\"What''s the difference between ","type":"text"},{"styles":{"code":true},"text":"else","type":"text"},{"styles":{"bold":true},"text":" and ","type":"text"},{"styles":{"code":true},"text":"finally","type":"text"},{"styles":{"bold":true},"text":" in a try block?\"","type":"text"}],"id":"3e18c620-4f38-419e-a05a-43fee899d5bc","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true,"italic":true},"text":"\"","type":"text"},{"styles":{"code":true},"text":"else","type":"text"},{"styles":{"bold":true,"italic":true},"text":" runs only when the try block succeeded with no exception — I use it for logic that should only happen on success, like logging a confirmed transaction. ","type":"text"},{"styles":{"code":true},"text":"finally","type":"text"},{"styles":{"bold":true,"italic":true},"text":" runs always — success or failure — I use it for cleanup.\"","type":"text"}],"id":"8d90b332-56af-4541-a27b-d5795c59fe0c","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"bold":true},"text":"\"Why create custom exceptions instead of using built-in ones?\"","type":"text"}],"id":"35f11cd4-6063-45ac-bc9c-fa8717d67dac","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true,"italic":true},"text":"\"Built-in exceptions like ","type":"text"},{"styles":{"code":true},"text":"ValueError","type":"text"},{"styles":{"bold":true,"italic":true},"text":" are too generic — they don''t carry domain meaning. A custom ","type":"text"},{"styles":{"code":true},"text":"InsufficientFundsError","type":"text"},{"styles":{"bold":true,"italic":true},"text":" can carry the balance and requested amount as attributes, making it self-documenting and allowing callers to respond precisely. It also makes the code read like the business domain, not like generic Python.\"","type":"text"}],"id":"48e33a8e-3557-4bf5-8986-bef885765ac0","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"bold":true},"text":"\"How do you read a stack trace?\"","type":"text"}],"id":"8381d997-de2d-47fc-8075-cf1e6bd42a6e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true,"italic":true},"text":"\"Bottom up. The last line is the actual error type and message — start there. The line above it is where it broke in the code. Then I read upward to trace how execution arrived there. I''m looking for the first place where something unexpected happened — often that''s not the line that threw the error but the line that produced the bad data that caused it.\"","type":"text"}],"id":"8f3c018a-1dc0-43a7-bde1-783ad1f7edfb","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"e8818dc9-ea76-4c35-9309-16e841b53351","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"🧠 The One-Line Summary of Each Concept","type":"text"}],"id":"aa2a5e18-afc2-439b-a84d-7d5cd97e0fca","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"text\nry       → \"attempt this, it might fail\"\nexcept    → \"if THIS specific thing fails, do this\"\nelse      → \"if nothing failed, also do this\"\nfinally   → \"no matter what happened, always do this\"\nraise     → \"something is wrong — tell the caller\"\ncustom    → \"name the problem precisely so callers can respond precisely\"\ntraceback → \"read bottom-up — error first, then trace how you got there\"","type":"text"}],"id":"6c4736a5-9421-470b-83e7-b0856aa39f73","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[],"id":"e792c7e8-5c9a-4609-a867-68b362fd981b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"}]'::jsonb, '3e9e3dd3-a59b-4b02-968a-ee95e7317583') ON CONFLICT ("node_id") DO UPDATE SET "bad_example" = EXCLUDED."bad_example", "completed_at" = EXCLUDED."completed_at", "created_at" = EXCLUDED."created_at", "definition" = EXCLUDED."definition", "good_example" = EXCLUDED."good_example", "is_completed" = EXCLUDED."is_completed", "key_points" = EXCLUDED."key_points", "last_edited" = EXCLUDED."last_edited", "map_id" = EXCLUDED."map_id", "mental_model" = EXCLUDED."mental_model", "notes" = EXCLUDED."notes", "resources" = EXCLUDED."resources", "rich_content" = EXCLUDED."rich_content", "user_id" = EXCLUDED."user_id";
