fault"},"type":"tableCell"},{"content":[{"styles":{},"text":"What it does","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Example","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Use case","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Supported data types","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Sample SQL script","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Aggregate","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"COUNT(expr)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Counts rows/non-null values in window","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Count of orders per customer","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Reporting totals, data quality checks","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"All data types","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"SELECT customer_id, COUNT(*) OVER(PARTITION BY customer_id) AS order_count FROM orders;","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Aggregate","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"SUM(expr)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Running or partitioned total of numeric col","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Running total of daily sales","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Cumulative revenue, YTD sales","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Numeric","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"SELECT order_date, SUM(amount) OVER(ORDER BY order_date) AS running_total FROM sales;","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Aggregate","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"AVG(expr)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Average within window/partition","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"7-day moving average of sales","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Trend smoothing, KPI dashboards","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Numeric","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"SELECT order_date, AVG(amount) OVER(ORDER BY order_date ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS moving_avg FROM sales;","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Aggregate","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"MIN(expr)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Minimum value in partition/window","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"defau