owspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"SELECT dept, MAX(salary) OVER(PARTITION BY dept) AS max_salary FROM employees;","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Rank","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"ROW_NUMBER()","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Unique sequential number per row, no ties","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Numbers rows 1,2,3 even for duplicates","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Pagination, dedup (keep first row)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Empty (no expr)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"SELECT *, ROW_NUMBER() OVER(PARTITION BY customer_id ORDER BY order_date DESC) AS rn FROM orders;","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Rank","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"RANK()","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Rank with gaps for ties (1,2,2,4)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Ranking students by score with ties","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Leaderboards where ties should skip ranks","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Empty (no expr)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"SELECT student, score, RANK() OVER(ORDER BY score DESC) AS rnk FROM scores;","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Rank","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"DENSE_RANK()","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Rank without gaps for ties (1,2,2,3)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Ranking products by sales","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Tiered pricing, rank-tier grouping","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Empty (no expr)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"SELECT product, sales, DENSE_RANK() OVER(ORDER BY sales DESC) AS drnk FROM products;","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Rank","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"CUME_DIST()","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Cumulative distribution (fraction ≤ current row)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Percentile position of a value","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Percentile/distribution analysis","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Empty (no expr)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"SELECT score, CUME_DIST() OVER(ORDER BY score) AS cum_dist FROM scores;","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Rank","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"PERCENT_RANK()","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Relative rank as a percentage (0 to 1)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Compare one salary against all salaries","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Benchmarking, HR analytics","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Empty (no expr)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"SELECT salary, PERCENT_RANK() OVER(ORDER BY salary) AS pct_rank FROM employees;","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Rank","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"NTILE(n)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Splits rows into n equal buckets","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Divide customers into 4 spending quartiles","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Quartile/decile segmentation, A/B bucketing","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Numeric (n = bucket count)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"SELECT customer_id, NTILE(4) OVER(ORDER BY total_spend DESC) AS quartile FROM customer_spend;","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Value/Analytic","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"LAG(expr,offset,default)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Value from a previous row","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Previous month''s sales","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Month-over-month change, trend detection","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"All data types","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"SELECT month, sales, LAG(sales,1,0) OVER(ORDER BY month) AS prev_month_sales FROM monthly_sales;","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Value/Analytic","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"LEAD(expr,offset,default)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Value from a following row","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Next transaction date for a customer","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Churn detection, gap analysis","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"All data types","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"SELECT customer_id, order_date, LEAD(order_date) OVER(PARTITION BY customer_id ORDER BY order_date) AS next_order FROM orders;","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Value/Analytic","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"FIRST_VALUE(expr)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"First value in the window frame","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"First purchase date per customer","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Cohort analysis, first-touch attribution","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"All data types","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"SELECT customer_id, order_date, FIRST_VALUE(order_date) OVER(PARTITION BY customer_id ORDER BY order_date) AS first_order FROM orders;","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Value/Analytic","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"LAST_VALUE(expr)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Last value in the window frame","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Latest status update per ticket","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Last-touch attribution, current state tracking","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"All data types","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"SELECT ticket_id, status, LAST_VALUE(status) OVER(PARTITION BY ticket_id ORDER BY updated_at ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS latest_status FROM ticket_updates;","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"92939ff1-7753-4f6b-ae3b-3e2a6f1600ee","props":{"textColor":"default"},"type":"table"},{"children":[],"content":[],"id":"5cc839e8-aded-4320-a03d-13f055eeb87d","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[],"id":"0d9ac6f4-c791-467d-8855-e88e748799e2","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Topic 2: The Watch Desk","type":"text"}],"id":"bffa8a5b-316f-4422-9037-e8042118ecb3","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"id":"56951f09-2b9f-4d27-bdc0-9a1001002a25","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"What This Note Is","type":"text"}],"id":"73aa1c68-0fc8-4633-b2a0-461405b7169b","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Inside the Control Room, the ","type":"text"},{"styles":{"bold":true},"text":"Watch Desk","type":"text"},{"styles":{},"text":" is the station that watches rows in relation to other rows — without collapsing them. Every other station (WHERE, GROUP BY, HAVING) either filters rows or collapses them into groups. The Watch Desk keeps every row intact and attaches extra information to each one: its rank, its running total, what happened in the row before it, what comes next. This is what window functions do. An internship interviewer will expect you to know how to operate the Watch Desk confidently.","type":"text"}],"id":"f51dc5e0-92b3-44aa-b99b-7f9fbe6dcc6a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"b026cf20-4578-4ba3-99d2-144c034fe517","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Mind Map","type":"text"}],"id":"1dae532e-d356-478c-93ae-84ad2d7c0a4c","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"                          THE WATCH DESK\n                        (Window Functions)\n                               │\n          ┌────────────────────┼────────────────────┐\n          │                    │                    │\n     RANKING               NAVIGATION           AGGREGATION\n    MONITORS                LENSES               TAPES\n          │                    │                    │\n  ROW_NUMBER()             LAG()              SUM() OVER (...)\n  (Rank Monitor)        (Timeline Lens)      (Running Tape)\n          │                    │                    │\n  RANK()                   LEAD()             AVG() OVER (...)\n  (Tie Monitor)          (Forecast Lens)     (Trend Tape)\n          │\n  DENSE_RANK()\n  (Compact Rank Monitor)\n          │\n          └──────── All monitors use ──────────┐\n                                               │\n                              ┌────────────────┴──────────────────┐\n                              │                                   │\n                    PARTITION BOARD                          SORT BOARD\n                   (PARTITION BY)                    (ORDER BY inside OVER)\n                  \"Which group?\"                       \"In what order?\"\n\n          │\n          └──────── Common Patterns ────────────┐\n                                               │\n                         ┌─────────────────────┼─────────────────────┐\n                         │                     │                     │\n                  Top-N per group       Running Total       Period-over-Period\n                (ROW_NUMBER + CTE)    (SUM() OVER ...)     (LAG() comparison)\n                  Deduplication\n               (ROW_NUMBER + CTE)","type":"text"}],"id":"4774f291-8d3d-459b-a179-601161872fd1","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"6c15ee3e-bede-4fd9-acef-691db2f4408c","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Decision Tree","type":"text"}],"id":"cd7ee5ff-395e-4fd3-966c-0bbb27e69a6e","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"START: You need information that relates one row to other rows\n          │\n          ▼\nDo you need to collapse rows into one result per group?\n    YES → Use GROUP BY (not a window function)\n    NO  → Use a window function (OVER clause)\n          │\n          ▼\nWhat do you need?\n          │\n    ┌─────┴──────┬──────────────┬──────────────┐\n    │            │              │              │\nRANK A ROW   COMPARE TO    COMPUTE A      COMPUTE A\nIN A GROUP   ANOTHER ROW   RUNNING TOTAL  MOVING AVG\n    │            │              │              │\n    ▼            ▼              ▼              ▼\nNeed ranks?   Need prev    SUM() OVER     AVG() OVER\n              row value?   (Running Tape) (Trend Tape)\n    │         → LAG()\n    │         Need next\n    │         row value?\n    │         → LEAD()\n    │\n    ▼\nDo ties exist in your data?\n    │\n    ├─ YES, gaps are OK     → RANK() (Tie Monitor)\n    ├─ YES, no gaps wanted  → DENSE_RANK() (Compact Rank Monitor)\n    └─ Ties do not matter / need unique row IDs → ROW_NUMBER() (Rank Monitor)\n          │\n          ▼\nDo you need Top-N per group?\n    YES → ROW_NUMBER() in a CTE, then filter WHERE rn <= N in outer query\n          │\n          ▼\nDo you need to deduplicate rows?\n    YES → ROW_NUMBER() PARTITION BY the duplicate key, keep WHERE rn = 1\n          │\n          ▼\nDo you need PARTITION BY?\n    YES → rows ranked/computed independently per group\n    NO  → window covers the entire result set","type":"text"}],"id":"f773cf4b-da32-4b08-a6a6-e013802967e7","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"73fce8a1-c5ba-4573-bae7-588a3bf3a03e","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Perfect, let''s rebuild the foundation properly before you dive into practice. This is a complete refresher — read it once, then keep it open as reference while solving the questions.","type":"text"}],"id":"fd3d7715-3354-422f-9f8a-04995b6deb1f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"ffb7043f-4aa4-40f6-85c6-2b95b1fe3764","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"📘 SQL Window Functions — Complete Notes","type":"text"}],"id":"ed856fdb-4628-42ae-84a7-fafb00668b5f","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"1. What is a Window Function?","type":"text"}],"id":"b5d69763-f98f-4e45-b21f-f896b834673e","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"A ","type":"text"},{"styles":{"bold":true},"text":"window function","type":"text"},{"styles":{},"text":" performs a calculation across a ","type":"text"},{"styles":{"bold":true},"text":"set of rows related to the current row","type":"text"},{"styles":{},"text":" — but unlike ","type":"text"},{"styles":{"code":true},"text":"GROUP BY","type":"text"},{"styles":{},"text":", it ","type":"text"},{"styles":{"bold":true},"text":"does NOT collapse the rows","type":"text"},{"styles":{},"text":". Every row keeps its identity, and you get an extra calculated column alongside it.","type":"text"}],"id":"15050edd-6f72-4850-98eb-d615a234b5ad","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Think of it as: ","type":"text"},{"styles":{"italic":true},"text":"\"For this row, look at a ''window'' (a group) of related rows, calculate something, and attach the result to this row.\"","type":"text"}],"id":"fdac82cd-5166-47a0-8e14-9e0c2de0dcbe","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"The Key Difference vs GROUP BY","type":"text"}],"id":"1d132bf9-c086-4780-b341-3c9915057333","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"-- GROUP BY: collapses rows → 1 row per department\nSELECT department, AVG(salary) \nFROM employees \nGROUP BY department;","type":"text"}],"id":"faed5313-b180-4b23-8060-b15721948317","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Result: only 4 rows (one per department) — you lose individual employee detail.","type":"text"}],"id":"282d41a9-221e-4fc2-a06c-cc6387fe0f39","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"-- WINDOW FUNCTION: keeps all rows, adds context\nSELECT emp_name, department, salary,\n       AVG(salary) OVER (PARTITION BY department) AS dept_avg_salary\nFROM employees;","type":"text"}],"id":"d176b37c-0c06-426c-91e1-fced4e5410dc","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Result: 20 rows (every employee), but each row now also shows their department''s average salary next to it.","type":"text"}],"id":"9d716f50-7142-4608-a082-659ccb55dbec","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"This is the #1 reason window functions exist","type":"text"},{"styles":{},"text":": you want detail + aggregate context, side by side, in the same row.","type":"text"}],"id":"ade27cf1-ea74-4af5-8ea0-d36e20e90cf4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"6129ebab-d8aa-4c70-88ce-3f8e062a6a0d","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"2. The Syntax — Break it Down Piece by Piece","type":"text"}],"id":"22a293fa-ca65-4aa3-bc18-0e00dc8d58c4","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"function_name(column) OVER (\n    PARTITION BY column1, column2   -- optional: splits data into groups\n    ORDER BY column3                -- optional: defines order within each group\n    ROWS/RANGE BETWEEN ... AND ...  -- optional: defines the \"frame\" (subset of the partition)\n)","type":"text"}],"id":"a735c647-7943-47ff-81b7-f35043136ab4","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Piece 1: ","type":"text"},{"styles":{"code":true},"text":"function_name(column)","type":"text"}],"id":"2775038e-269b-4681-b830-07b469ade7d3","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"This can be:","type":"text"}],"id":"cec27094-a4dc-4489-b2d8-a55bce81fc3a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Aggregate functions: ","type":"text"},{"styles":{"code":true},"text":"SUM()","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"AVG()","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"COUNT()","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"MIN()","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"MAX()","type":"text"}],"id":"5e261502-4099-4177-89ab-2ec07d70558d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Ranking functions: ","type":"text"},{"styles":{"code":true},"text":"ROW_NUMBER()","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"RANK()","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"DENSE_RANK()","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"NTILE(n)","type":"text"}],"id":"d729843e-ef78-4d8e-837b-295c071d168c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Offset functions: ","type":"text"},{"styles":{"code":true},"text":"LAG()","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"LEAD()","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"FIRST_VALUE()","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"LAST_VALUE()","type":"text"}],"id":"df818997-e7d1-4211-ad83-e165d26696b9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Distribution functions: ","type":"text"},{"styles":{"code":true},"text":"PERCENT_RANK()","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"CUME_DIST()","type":"text"}],"id":"8a9af597-c12b-464f-8974-66570464bd92","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Piece 2: ","type":"text"},{"styles":{"code":true},"text":"OVER (...)","type":"text"}],"id":"6d186f6a-a1a0-40b1-853e-496b4ce7dc3f","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"This is what makes it a ","type":"text"},{"styles":{"bold":true},"text":"window function","type":"text"},{"styles":{},"text":". Without ","type":"text"},{"styles":{"code":true},"text":"OVER()","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"SUM()","type":"text"},{"styles":{},"text":" or ","type":"text"},{"styles":{"code":true},"text":"RANK()","type":"text"},{"styles":{},"text":" mean nothing on their own in this context.","type":"text"}],"id":"d4a44b9b-5a5f-45bb-9145-1e069809f053","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Piece 3: ","type":"text"},{"styles":{"code":true},"text":"PARTITION BY","type":"text"}],"id":"f3582de1-43c9-4481-8472-31dbfd625f59","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Splits your data into ","type":"text"},{"styles":{"bold":true},"text":"independent groups","type":"text"},{"styles":{},"text":" (windows). The function resets/recalculates separately for each group.","type":"text"}],"id":"c76f4f9e-ab1d-4ae2-bbcb-ed5e41335354","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Think of it like ","type":"text"},{"styles":{"code":true},"text":"GROUP BY","type":"text"},{"styles":{},"text":", but it doesn''t merge rows — it just tells the function \"only look within this group when calculating.\"","type":"text"}],"id":"a7dc70bc-f602-4420-8eab-5ac168449c73","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"If you skip ","type":"text"},{"styles":{"code":true},"text":"PARTITION BY","type":"text"},{"styles":{},"text":", the entire table is treated as ","type":"text"},{"styles":{"bold":true},"text":"one single window","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"a985c1ef-dd24-4821-8e56-aecf8b32134b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"AVG(salary) OVER (PARTITION BY department)\n-- \"Calculate average salary, but only using rows from the SAME department as the current row\"","type":"text"}],"id":"9e050900-00f8-4787-a3de-54472d255848","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Piece 4: ","type":"text"},{"styles":{"code":true},"text":"ORDER BY","type":"text"},{"styles":{},"text":" (inside OVER)","type":"text"}],"id":"8364957e-c26c-4aa2-a7bd-689223b15831","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Defines the ","type":"text"},{"styles":{"bold":true},"text":"order","type":"text"},{"styles":{},"text":" in which rows are processed within each partition. This matters hugely for:","type":"text"}],"id":"8cff5063-289c-464c-8e04-c85f53bfa7d6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Ranking functions (who is \"1st\"?)","type":"text"}],"id":"03b83d57-a0bb-40f8-912f-d6e3239a7074","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Running totals (running total needs an order to accumulate)","type":"text"}],"id":"73728e8b-91f2-4dd8-8232-4d1679f42709","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"LAG/LEAD (need order to know what''s \"before\" or \"after\")","type":"text"}],"id":"d26d54b5-1ff2-468a-99bf-f639fd6b6ee0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"SUM(salary) OVER (PARTITION BY department ORDER BY hire_date)\n-- \"Running total of salary within each department, ordered by hire date\"","type":"text"}],"id":"bcd20c41-62cb-4f42-9939-7d65f5c54fe3","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"⚠️ ","type":"text"},{"styles":{"bold":true},"text":"Important","type":"text"},{"styles":{},"text":": ","type":"text"},{"styles":{"code":true},"text":"ORDER BY","type":"text"},{"styles":{},"text":" inside ","type":"text"},{"styles":{"code":true},"text":"OVER()","type":"text"},{"styles":{},"text":" is completely different from the ","type":"text"},{"styles":{"code":true},"text":"ORDER BY","type":"text"},{"styles":{},"text":" at the end of the query. The one at the end sorts your final output. The one inside ","type":"text"},{"styles":{"code":true},"text":"OVER()","type":"text"},{"styles":{},"text":" controls calculation logic.","type":"text"}],"id":"e9d5efd9-b920-4cf0-9626-6a866d00e196","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Piece 5: The Frame Clause ","type":"text"},{"styles":{"code":true},"text":"ROWS/RANGE BETWEEN...","type":"text"}],"id":"cc23a9fa-163d-4744-9947-72c1ef401ea4","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"This defines exactly ","type":"text"},{"styles":{"bold":true},"text":"which rows","type":"text"},{"styles":{},"text":" (relative to the current row) are included in the calculation. Covered in detail later — skip this for now while learning ranking functions (they don''t need it).","type":"text"}],"id":"aec4e0ca-cbca-40f3-913d-62d33e77ada8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"ca822c7d-9283-47f8-a205-b0401ab46535","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"3. Where Window Functions Fit in Query Execution Order","type":"text"}],"id":"e20b72ee-30e0-4888-ab5d-34d700b2bc41","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"This trips up a lot of people. SQL doesn''t run top to bottom as written. Actual logical execution order:","type":"text"}],"id":"9c70d861-c544-497f-b831-bc670db5d2cd","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"FROM → WHERE → GROUP BY → HAVING → WINDOW FUNCTIONS → SELECT → ORDER BY → LIMIT","type":"text"}],"id":"2e496cef-515f-437d-8a48-80f63803346c","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Key implications:","type":"text"}],"id":"84e4dd9c-18ca-4daa-98f7-935f9a1dd4b8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[{"children":[],"content":[{"styles":{},"text":"-- ❌ This FAILS\nSELECT emp_name, RANK() OVER (ORDER BY salary DESC) AS rnk\nFROM employees\nWHERE rnk <= 3;","type":"text"}],"id":"c7244b3f-f8a0-4da3-a169-ed1e876c7bc2","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"-- ✅ Correct way: wrap in a subquery/CTE\nSELECT * FROM (\n    SELECT emp_name, RANK() OVER (ORDER BY salary DESC) AS rnk\n    FROM employees\n) t\nWHERE rnk <= 3;","type":"text"}],"id":"05d81c1c-df27-4d1a-9d2b-1938544d38e7","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"This exact pattern (rank inside subquery, then filter outside) is asked in almost every interview.","type":"text"},{"styles":{},"text":" Memorize it.","type":"text"}],"id":"df654c41-8bf4-4881-9183-709c2c98cb84","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"}],"content":[{"styles":{},"text":"You ","type":"text"},{"styles":{"bold":true},"text":"cannot","type":"text"},{"styles":{},"text":" use a window function''s alias in the ","type":"text"},{"styles":{"code":true},"text":"WHERE","type":"text"},{"styles":{},"text":" clause (because ","type":"text"},{"styles":{"code":true},"text":"WHERE","type":"text"},{"styles":{},"text":" runs before window functions are calculated).","type":"text"}],"id":"2d21958b-ce3c-432e-b6a9-77e34c48fa50","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Window functions run ","type":"text"},{"styles":{"bold":true},"text":"before","type":"text"},{"styles":{},"text":" the final ","type":"text"},{"styles":{"code":true},"text":"ORDER BY","type":"text"},{"styles":{},"text":" and ","type":"text"},{"styles":{"code":true},"text":"SELECT","type":"text"},{"styles":{},"text":", but ","type":"text"},{"styles":{"bold":true},"text":"after","type":"text"},{"styles":{},"text":" ","type":"text"},{"styles":{"code":true},"text":"GROUP BY","type":"text"},{"styles":{},"text":"/","type":"text"},{"styles":{"code":true},"text":"HAVING","type":"text"},{"styles":{},"text":". So you ","type":"text"},{"styles":{"italic":true},"text":"can","type":"text"},{"styles":{},"text":" apply a window function on top of an already-aggregated result.","type":"text"}],"id":"a3b01f9c-05b1-4b6e-b9d1-366f41a9e761","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"id":"309b4391-c9bc-4016-bbb5-8403eba9d250","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"4. Category Overview (so you know what''s coming)","type":"text"}],"id":"c6792c38-bd37-403c-80c1-6815da44af71","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":{"columnWidths":[null,null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Category","type":"text"}],"props":{"backgroundCol