:"cc5ed6b2-751e-413c-971a-79d4e522cda9","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"What the fact_sales Table Stores","type":"text"}],"id":"e3a83b87-cb42-4acb-961a-38fd10bd9955","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":{"columnWidths":[null,null,null,null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"sale_key","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"customer_key","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"product_key","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"date_key","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"sales_amount","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"9001","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"5001","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"301","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"20230315","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"185,000","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"9002","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"5002","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"408","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"20240812","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"95,000","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"d3e57fd2-942f-47b1-b2d2-653c75835bca","props":{"textColor":"default"},"type":"table"},{"children":[],"content":[{"styles":{},"text":"Sale 9001 (March 2023) → ","type":"text"},{"styles":{"code":true},"text":"customer_key 5001","type":"text"},{"styles":{},"text":" → ","type":"text"},{"styles":{"bold":true},"text":"Colombo","type":"text"},{"styles":{},"text":" ✅","type":"text"}],"id":"69e53361-4115-4375-9a53-a5e4e6691033","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Sale 9002 (August 2024) → ","type":"text"},{"styles":{"code":true},"text":"customer_key 5002","type":"text"},{"styles":{},"text":" → ","type":"text"},{"styles":{"bold":true},"text":"Kandy","type":"text"},{"styles":{},"text":" ✅","type":"text"}],"id":"fa3a2df3-089f-47e5-9515-fd6b35d0ffa1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"id":"dbb21346-bba2-4cc5-85eb-be0e83f519c9","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"What SCD Type 1 Would Have Done Wrong","type":"text"}],"id":"fbdd3616-b1d6-4f85-bfcb-c2c2dd942ae8","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"If SCD Type 1 was used, ","type":"text"},{"styles":{"code":true},"text":"dim_customer","type":"text"},{"styles":{},"text":" would only have:","type":"text"}],"id":"668fa3d1-58cb-47a0-8bdd-3bc746f84656","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":{"columnWidths":[null,null,null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"customer_key","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"customer_id","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"customer_name","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"city","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"5001","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"C001","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Amaya Silva","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Kandy","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"ce25d514-b75c-4d97-8642-14457e2d7fff","props":{"textColor":"default"},"type":"table"},{"children":[],"content":[{"styles":{},"text":"Now the March 2023 sale (","type":"text"},{"styles":{"code":true},"text":"customer_key = 5001","type":"text"},{"styles":{},"text":") is attributed to ","type":"text"},{"styles":{"bold":true},"text":"Kandy","type":"text"},{"styles":{},"text":" even though Amaya was in Colombo then.","type":"text"}],"id":"6cf4576e-581b-4bbf-9a0f-36927015043c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"The regional sales report for 2023 would show Kandy revenue that never actually came from Kandy. Business decisions about store locations would be based on corrupted data.","type":"text"}],"id":"fe1c1ad3-6ce0-4158-9054-f14a96128ac7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Why SCD Type 2 Preserves Correct Historical Reporting","type":"text"}],"id":"f52ebd2a-1b4f-4e48-9390-9b8cd37b6d56","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"With SCD Type 2:","type":"text"}],"id":"f3f9736d-0b2a-4c18-bb03-d241e953dae2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"-- Total sales by city in 2023\nSELECT\n    c.city,\n    SUM(f.sales_amount) AS total_revenue\nFROM fact_sales f\nJOIN dim_customer c ON f.customer_key = c.customer_key\nJOIN dim_date d     ON f.date_key     = d.date_key\nWHERE d.year = 2023\nGROUP BY c.city;","type":"text"}],"id":"2e84d121-5598-4bf1-abe4-26dac32d6e10","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Result:","type":"text"}],"id":"ba9d9c0e-dea1-4829-bb20-e160349701ef","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"city     | total_revenue\n---------|---------------\nColombo  | 185,000       ← Amaya''s March 2023 purchase, correctly attributed","type":"text"}],"id":"6e7e7f4e-f400-45f5-9d0f-dec44f2922e4","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"The fact table''s ","type":"text"},{"styles":{"code":true},"text":"customer_key","type":"text"},{"styles":{},"text":" acts as a ","type":"text"},{"styles":{"bold":true},"text":"time-frozen pointer","type":"text"},{"styles":{},"text":" to the exact version of Amaya''s record that was valid at the time of the purchase. No manual date calculations needed in the query. The schema handles history automatically.","type":"text"}],"id":"9def58b5-4499-4d01-ad55-d5cf6d94c702","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"11de874c-711b-4820-9636-60263f144551","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"7. Interview-Level Understanding","type":"text"}],"id":"a0455986-f454-48fb-a218-238a81a2f7d8","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Interview Question 1:","type":"text"}],"id":"f53ee1c5-0083-457f-a43d-3a7db3b3b7ef","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"\"When would you use a snowflake schema instead of a star schema?\"","type":"text"}],"id":"ccd1cd99-f2e0-42c9-9934-ea3c01d6e100","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{},"text":"Strong Answer:","type":"text"}],"id":"46a64a14-a794-48dc-ae3d-133ec3276f54","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"In most analytics scenarios, I would default to a star schema because it minimizes joins, delivers faster query performance, and is easier for BI tools and analysts to work with.","type":"text"}],"id":"ba03607a-09b4-4e1a-bb53-b8e81db78a21","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"However, I would consider a snowflake schema in specific situations. First, if dimension tables contain significant hierarchical data with high redundancy — for example, a product dimension where department and category information is repeated across tens of thousands of product rows, and those attributes change frequently. Normalizing them reduces storage and makes updates cleaner.","type":"text"}],"id":"072ffd8e-76ed-4b62-b793-f24d4db6c6d5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"Second, if the organization has strong data governance requirements where a single authoritative source for each hierarchy level is important for consistency.","type":"text"}],"id":"e68229b6-f710-4542-aa9d-5897327141d4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"In practice, many modern warehouses like Snowflake and BigQuery handle storage redundancy cheaply, so the storage savings of a snowflake schema rarely justify the added query complexity. Star schema usually wins for pure analytics performance.\"","type":"text"}],"id":"3c83997a-216f-43da-97cd-7182a3e026a1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"43304458-2221-404e-9996-02357d1012ee","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Interview Question 2:","type":"text"}],"id":"cb92f050-31f8-4a02-b53f-dafa4c6f9bd8","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"\"When would you use SCD Type 1 vs SCD Type 2?\"","type":"text"}],"id":"59520704-3a39-4411-8d16-1506b88fd8ec","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{},"text":"Strong Answer:","type":"text"}],"id":"e021aea5-0893-4d1f-8974-e130e9f48428","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"The key question is: does history matter for this attribute, and is this change a correction or a real business event?","type":"text"}],"id":"0b11d2dd-d8c5-4664-a139-2d8aa58b0cd8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"SCD Type 1 is appropriate when a value is being corrected — for example, a customer''s name was misspelled, or a product code was entered incorrectly. The old value was never correct, so there''s no meaningful history to preserve. Overwriting is the right action.","type":"text"}],"id":"89583991-89ff-498c-8068-6d244fb7b63a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"SCD Type 2 is appropriate when a value has genuinely changed as a real business event — a customer moves to a different city, an employee transfers to a new department, a product gets recategorized. The old value was correct at the time. Historical reports need to reflect what was true when each transaction occurred.","type":"text"}],"id":"34fe6e65-40a1-4b09-83c3-baae8bd7270b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"A practical example: if a customer moves from Colombo to Kandy, SCD Type 2 preserves this. Sales made while she was in Colombo continue to be attributed to Colombo. New sales are attributed to Kandy. Without SCD Type 2, regional performance reports become inaccurate — and business decisions based on those reports would be flawed.\"","type":"text"}],"id":"e3684e01-8de8-4bc2-a876-d068a4ce2cfe","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"123e35f4-6923-4981-8cbb-dea127d973fc","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"What is Enough at Intern Level","type":"text"}],"id":"2b899c0c-8f6f-4548-8016-02b53672725e","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"At intern level, you are expected to:","type":"text"}],"id":"2aacd617-31c7-4a8a-bdec-bf30cd4fab84","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Explain what a snowflake schema is and how it differs from a star schema","type":"text"}],"id":"789088ef-aec9-4528-af0a-8e6aba84d03f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Explain SCD Types 1 and 2 conceptually and when to use each","type":"text"}],"id":"7eccba5d-80bd-450e-b176-8af796c45679","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Show a correct SCD Type 2 table design with ","type":"text"},{"styles":{"code":true},"text":"effective_date","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"expiry_date","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"is_current","type":"text"}],"id":"ca6fe983-a517-40a5-8887-391079f26483","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Explain the surrogate key vs natural key role in SCD Type 2","type":"text"}],"id":"dfe90664-98b2-47ac-a9b3-0659f8d04197","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Give a clear practical example (customer moving cities)","type":"text"}],"id":"32e64b49-5ec5-4514-ad43-eacaed7f2543","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Beyond intern level (awareness only):","type":"text"}],"id":"a515a2c9-6fe1-4c6a-8899-c25010bb029f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"SCD Type 3 (stores current + previous value in the same row — limited history)","type":"text"}],"id":"fe476ecb-1f26-4342-a29c-3f57bd9200d3","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"SCD Type 4, Type 6 (hybrid approaches — rarely asked at intern level)","type":"text"}],"id":"f1afce43-b6e9-490b-8904-56556bb982ae","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Full ETL logic for detecting and processing SCD Type 2 changes in Airflow or dbt","type":"text"}],"id":"c24a1075-d05e-4225-8996-d4e0d4a4963c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"dbt snapshots (the modern tool-based SCD Type 2 implementation)","type":"text"}],"id":"bde5b707-d8d8-4945-8cc4-7fa7b8c3c3cd","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"id":"06a3a7e4-528d-479e-b3bf-158adcc17123","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"8. C.A.C.O. Application","type":"text"}],"id":"4c2fcf82-79a4-42ed-9c91-ff9fd89beec4","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Concept","type":"text"}],"id":"562a052f-6c25-4f66-bb44-974b045e98bf","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"A snowflake schema extends the star schema by normalizing dimension tables into sub-tables organized by hierarchy. It reduces redundancy but increases join complexity.","type":"text"}],"id":"1b203f97-30a9-48b2-9c24-1ded069a7765","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"SCD Type 2 is the most important slowly changing dimension strategy in data engineering. It preserves historical accuracy by inserting a new versioned row when a tracked dimension attribute changes, rather than overwriting the existing row.","type":"text"}],"id":"68019915-8506-4905-b73c-2ec50d686160","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"fb4cd6ac-a796-438e-a3ad-4538d3697b81","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Architecture","type":"text"}],"id":"35bacff4-6137-430e-adeb-dc79b3026e0a","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Source System (OLTP)\n    → ETL Pipeline\n        → Detect changes in dimension attributes\n            → SCD Type 1: UPDATE existing row\n            → SCD Type 2:\n                  UPDATE old row (set expiry_date, is_current = FALSE)\n                  INSERT new row (new surrogate key, today = effective_date,\n                                  expiry = 9999-12-31, is_current = TRUE)\n        → Load fact table (using current dimension surrogate keys at load time)","type":"text"}],"id":"482dd72c-fd3e-4004-bb55-becffb71f029","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"7b2049bc-a2ba-4f1c-b1e9-b2ecf65d2036","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Code — SCD Type 2 Table Design","type":"text"}],"id":"bb98cab0-4cd5-4866-966d-4135f1e2841d","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"-- ─────────────────────────────────────────────────────\n-- SCD Type 2: dim_customer\n-- ─────────────────────────────────────────────────────\nCREATE TABLE dim_customer (\n\n    -- Surrogate key — unique per version, changes with each new version\n    customer_key    INT             PRIMARY KEY,\n\n    -- Natural key — same across all versions of the same customer\n    customer_id     VARCHAR(20)     NOT NULL,       -- e.g., ''C001''\n\n    -- Tracked attributes — a change here triggers a new row\n    customer_name   VARCHAR(200)    NOT NULL,\n    city            VARCHAR(100)    NOT NULL,\n    region          VARCHAR(100),\n    customer_segment VARCHAR(50),                   -- ''Gold'', ''Silver'', ''Bronze''\n\n    -- SCD Type 2 version control columns\n    effective_date  DATE            NOT NULL,       -- When this version became active\n    expiry_date     DATE            NOT NULL,       -- When this version expired\n                                                    -- 9999-12-31 = still active\n    is_current      BOOLEAN         NOT NULL        -- TRUE = active version\n\n);","type":"text"}],"id":"53152ea3-bbde-45ca-b882-b79ce91c752e","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Sample Data — SCD Type 2 in Action","type":"text"}],"id":"75f14706-eef7-49ed-9af1-df1e3f2fb064","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"-- Initial state: Amaya lives in Colombo (January 2022)\nINSERT INTO dim_customer VALUES\n(5001, ''C001'', ''Amaya Silva'', ''Colombo'', ''Western'', ''Gold'',\n ''2022-01-15'', ''9999-12-31'', TRUE);\n\n-- July 2024: Amaya moves to Kandy\n-- Step 1: Close the old row\nUPDATE dim_customer\nSET    expiry_date = ''2024-07-01'',\n       is_current  = FALSE\nWHERE  customer_id = ''C001''\nAND    is_current  = TRUE;\n\n-- Step 2: Insert the new version\nINSERT INTO dim_customer VALUES\n(5002, ''C001'', ''Amaya Silva'', ''Kandy'', ''Central'', ''Gold'',\n ''2024-07-01'', ''9999-12-31'', TRUE);","type":"text"}],"id":"38063c50-fa90-49f3-822d-2612e1fc99ab","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Querying Current and Historical Records","type":"text"}],"id":"8b8619db-28dd-4107-b86b-ab50e870cbcd","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"-- Get only current customer records (for current state reporting)\nSELECT customer_id, customer_name, city\nFROM   dim_customer\nWHERE  is_current = TRUE;\n\n-- Get all versions of a specific customer (for audit/history)\nSELECT customer_key, customer_name, city,\n       effective_date, expiry_date, is_current\nFROM   dim_customer\nWHERE  customer_id = ''C001''\nORDER BY effective_date;\n\n-- Correct historical join: sales with the city at time of purchase\nSELECT\n    f.sale_key,\n    f.sales_amount,\n    c.city AS city_at_time_of_purchase,\n    d.full_date AS sale_date\nFROM   fact_sales    f\nJOIN   dim_customer  c ON f.customer_key = c.customer_key\nJOIN   dim_date      d ON f.date_key     = d.date_key\nWHERE  c.customer_id = ''C001''\nORDER BY d.full_date;","type":"text"}],"id":"b675bf67-815b-44ca-9084-7bce153887eb","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Note:","type":"text"},{"styles":{},"text":" The historical join works automatically because the fact table stores the ","type":"text"},{"styles":{"code":true},"text":"customer_key","type":"text"},{"styles":{},"text":" (surrogate) at the time of loading — which points to the exact version row that was current then. No date-range filtering is needed in the join.","type":"text"}],"id":"6b21c914-e49a-427e-86e8-f8a540733f52","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"2369041f-28f2-4732-b43f-74167234d006","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Optimization / Interview Tactics","type":"text"}],"id":"bb8de9a3-2ad8-4c6b-b89f-da8053f80fce","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Lead with the natural vs surrogate key distinction","type":"text"},{"styles":{},"text":" — this shows deep understanding of SCD Type 2, not just surface knowledge","type":"text"}],"id":"4d1829e3-111f-4440-b262-3b92d9e88fd9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Always explain the \"why\" of SCD Type 2","type":"text"},{"styles":{},"text":" — corrupted historical reports are the business consequence; mention this explicitly","type":"text"}],"id":"6f7e5bcc-bf2c-4072-bda0-de36fddf2fb4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Use ","type":"text"},{"styles":{"code":true},"text":"9999-12-31","type":"text"},{"styles":{"bold":true},"text":" as the sentinel expiry date","type":"text"},{"styles":{},"text":" — this is the industry convention; knowing it shows practical awareness","type":"text"}],"id":"9a59a326-224f-4a31-a0d6-f8fd503da817","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Mention dbt snapshots","type":"text"},{"styles":{},"text":" casually — ","type":"text"},{"styles":{"italic":true},"text":"\"In modern pipelines, tools like dbt have a snapshots feature that automates SCD Type 2 logic\"","type":"text"},{"styles":{},"text":" — this shows tool awareness without overclaiming expertise","type":"text"}],"id":"380daeb7-ed37-4686-b9ec-ad4f75c3bee0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Know when NOT to use SCD Type 2","type":"text"},{"styles":{},"text":" — if a company only needs current state, Type 2 adds complexity for no benefit; showing this judgment impresses interviewers","type":"text"}],"id":"80111bf5-2c77-43b6-ba69-2e70bf8ec672","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"For snowflake schema:","type":"text"},{"styles":{},"text":" be ready to say ","type":"text"},{"styles":{"italic":true},"text":"\"I''d default to star schema unless there''s a specific reason to normalize dimensions\"","type":"text"},{"styles":{},"text":" — this shows design judgment","type":"text"}],"id":"59fb59a9-2b6a-43b4-a2b7-3d54cf3c0a11","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"id":"ee4b15d5-5c8b-4f06-a6f3-806e6cefcf87","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"9. Final Interview Summary","type":"text"}],"id":"39012c39-2c19-4ed6-8654-6ce96cc44349","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Key Terms","type":"text"}],"id":"4d5b0d0c-c35f-449f-be08-1aa378ba0830","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Term","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Definition","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Snowflake Schema","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Star schema extension where dimension tables are normalized into sub-tables","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Star Schema","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Fact table at center with flat denormalized dimension tables surrounding it","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"SCD","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Slowly Changing Dimension — a dimension whose values change over time","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"SCD Type 1","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Handle change by overwriting old value — no history preserved","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"SCD Type 2","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Handle change by inserting new row and closing old row — full history preserved","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"effective_date","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"The date a dimension row version became active","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"expiry_date","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"The date a dimension row version was superseded; ","type":"text"},{"styles":{"code":true},"text":"9999-12-31","type":"text"},{"styles":{},"text":" means still active","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"is_current","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Boolean flag: TRUE = active version, FALSE = historical version","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Surrogate Key","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"System-generated integer PK; unique per version in SCD Type 2","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Natural Key","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Original business identifier; same across all versions of an entity","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Version Row","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"One row in SCD Type 2 representing one time-period state of an entity","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Sentinel Date","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"code":true},"text":"9999-12-31","type":"text"},{"styles":{},"text":" used as expiry_date for the current active row","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"6b0fb1f5-2400-4a74-a5b9-8a8f1bb36035","props":{"textColor":"default"},"type":"table"},{"children":[],"id":"5f1729ae-057f-446e-8dde-1d218a06cdff","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Must-Remember Points","type":"text"}],"id":"81f78f71-4592-4dbd-b76e-49a11d2b5b2b","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"✅ Snowflake schema = normalized dimension sub-tables; more joins, less redundancy","type":"text"}],"id":"15e18709-b199-4bab-baba-1348f6714fbe","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"✅ Star schema = flat denormalized dimensions; fewer joins, faster analytics — ","type":"text"},{"styles":{"bold":true},"text":"preferred by default","type":"text"}],"id":"84fbffb5-d38f-4f5a-9014-f12935421eec","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"✅ SCD Type 1 = overwrite — use for ","type":"text"},{"styles":{"bold":true},"text":"corrections","type":"text"},{"styles":{},"text":" (data was wrong)","type":"text"}],"id":"9c033d36-c4c9-4036-9af8-b2e6b8f51c86","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"✅ SCD Type 2 = new row + close old row — use for ","type":"text"},{"styles":{"bold":true},"text":"real business changes","type":"text"},{"styles":{},"text":" (data was right, world changed)","type":"text"}],"id":"c72c0879-a163-4fa7-9f9d-2a5d8f4a0176","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"✅ SCD Type 2 needs: ","type":"text"},{"styles":{"code":true},"text":"effective_date","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"expiry_date","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"is_current","type":"text"}],"id":"304a8573-d05a-4572-aa89-1ccc59cf684c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"✅ Natural key (","type":"text"},{"styles":{"code":true},"text":"customer_id","type":"text"},{"styles":{},"text":") stays the same across all versions","type":"text"}],"id":"cfc4945e-98d6-43cc-a95c-5501c9741cec","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"✅ Surrogate key (","type":"text"},{"styles":{"code":true},"text":"customer_key","type":"text"},{"styles":{},"text":") is unique per version — this is what the fact table stores","type":"text"}],"id":"2c93212b-7a17-4510-9a94-ea75e016fdcb","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"✅ ","type":"text"},{"styles":{"code":true},"text":"expiry_date = 9999-12-31","type":"text"},{"styles":{},"text":" + ","type":"text"},{"styles":{"code":true},"text":"is_current = TRUE","type":"text"},{"styles":{},"text":" = the current active version","type":"text"}],"id":"edcb590a-4c94-45eb-ba01-8a8506f74587","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"✅ The fact table''s surrogate key FK creates an automatic time-frozen link to the correct dimension version","type":"text"}],"id":"52496449-48ba-44a6-8b2e-349e49b221b3","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"✅ SCD Type 2 is the most commonly tested SCD type at junior data engineer interviews","type":"text"}],"id":"1b4643ab-3d4d-4f6f-9f63-c8e748488567","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"id":"42df7427-4422-4b29-9087-f6675445dfdf","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"3 Interview-Ready One-Liners","type":"text"}],"id":"0f755ec1-4b5a-4124-a74b-d693ca3b39f8","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"1.","type":"text"},{"styles":{},"text":" ","type":"text"},{"styles":{"italic":true},"text":"\"A snowflake schema normalizes dimension tables into sub-tables to reduce redundancy, but at the cost of additional joins. For most analytics use cases, I''d prefer a star schema because fewer joins mean faster queries and simpler BI integration.\"","type":"text"}],"id":"21adc4a5-5014-4af6-9c1a-9626ea075f2e","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"bold":true},"text":"2.","type":"text"},{"styles":{},"text":" ","type":"text"},{"styles":{"italic":true},"text":"\"SCD Type 2 preserves historical accuracy by inserting a new versioned row when a tracked dimension attribute changes — using effective and expiry dates and an is_current flag — so that each fact record is permanently linked to the correct state of its dimension at the time the event occurred.\"","type":"text"}],"id":"95e63706-301f-4f09-ae2b-c37f0486bd39","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"bold":true},"text":"3.","type":"text"},{"styles":{},"text":" ","type":"text"},{"styles":{"italic":true},"text":"\"The key distinction between SCD Type 1 and Type 2 is intent: Type 1 is for correcting data that was never right, while Type 2 is for tracking changes that were real — like a customer genuinely moving cities — where historical reports must reflect what was true at the time.\"","type":"text"}],"id":"aec26416-8236-4143-ae16-822cd06c2855","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"70d6a35f-6e6b-46f2-84a2-6ef7c5c26078","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Common Mistakes to Avoid","type":"text"}],"id":"4ba38d70-2cc1-4ff6-95be-7a6f66acaf1f","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":{"columnWidths":[null,null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Mistake","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Why It''s Wrong","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Correct Understanding","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Saying snowflake schema is always better","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"More joins hurt analytics performance; storage is cheap today","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Star schema is the default; snowflake only when hierarchy management justifies it","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Confusing snowflake the schema with Snowflake the platform","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"They are unrelated","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Snowflake Inc. is a cloud data warehouse; snowflake schema is a dimensional modeling pattern","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Saying SCD Type 2 updates the existing row","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"It never updates tracked attributes on the old row","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"It closes the old row (expiry_date, is_current=FALSE) and inserts a brand new row","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Forgetting that the natural key stays constant","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Makes the versioning logic unclear","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Natural key = the business entity; surrogate key = the specific version","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Using natural key as the FK in the fact table","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Destroys point-in-time accuracy","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Fact table must store the surrogate key — which is unique per version","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Applying SCD Type 2 to every attribute","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Overkill; not every attribute needs history","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Only track attributes where history matters for reporting accuracy","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Forgetting the sentinel date convention","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Shows lack of practical awareness","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Active rows use ","type":"text"},{"styles":{"code":true},"text":"9999-12-31","type":"text"},{"styles":{},"text":" as expiry_date — this is the industry standard","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"55e319b7-04b5-4630-a5cc-4e4a426a0a25","props":{"textColor":"default"},"type":"table"},{"children":[],"id":"ca92352c-c96f-40ce-aa11-e59973a4a2f0","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"Remember the address book.","type":"text"},{"styles":{},"text":" SCD Type 1 crosses out the old address. SCD Type 2 keeps it, stamps the date it was valid, and adds the new address below. Your analytical queries can now always find where someone lived on any given day — which is the entire point of historical data engineering.","type":"text"}],"id":"a6fc01f0-1131-4f33-a99e-0965a1b9c609","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[],"id":"08975039-1346-44d1-b012-2d766a23031d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"}]'::jsonb, '3e9e3dd3-a59b-4b02-968a-ee95e7317583') ON CONFLICT ("node_id") DO UPDATE SET "bad_example" = EXCLUDED."bad_example", "completed_at" = EXCLUDED."completed_at", "created_at" = EXCLUDED."created_at", "definition" = EXCLUDED."definition", "good_example" = EXCLUDED."good_example", "is_completed" = EXCLUDED."is_completed", "key_points" = EXCLUDED."key_points", "last_edited" = EXCLUDED."last_edited", "map_id" = EXCLUDED."map_id", "mental_model" = EXCLUDED."mental_model", "notes" = EXCLUDED."notes", "resources" = EXCLUDED."resources", "rich_content" = EXCLUDED."rich_content", "user_id" = EXCLUDED."user_id";
