INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-05-26T13:47:07.758988+00:00', '', '', '658bfb95-c938-4fa4-b39a-3051744406bb', false, '[]'::jsonb, '2026-05-26T13:49:32.327+00:00', 'f22b10db-248b-447f-80b6-4a27bd9171ed', '', 'fce7885a-7c7e-4cad-b4fd-26891036acdb', '', '[]'::jsonb, '[{"children":[],"content":[{"styles":{"bold":true},"text":"Data Warehouses & Dimensional Modeling","type":"text"}],"id":"54807adf-fc60-493e-a4d4-07619d63b321","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"A ","type":"text"},{"styles":{"bold":true},"text":"Data Warehouse","type":"text"},{"styles":{},"text":" is a highly structured, OLAP-based storage environment built exclusively for analytical querying over large historical datasets. To organize data ","type":"text"},{"styles":{"italic":true},"text":"inside","type":"text"},{"styles":{},"text":" a warehouse effectively, data engineers use ","type":"text"},{"styles":{"bold":true},"text":"Dimensional Modeling","type":"text"},{"styles":{},"text":" — a design technique developed by Ralph Kimball that structures data into exactly two types of tables: ","type":"text"},{"styles":{"bold":true},"text":"Facts","type":"text"},{"styles":{},"text":" and ","type":"text"},{"styles":{"bold":true},"text":"Dimensions","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"2933f211-d253-4039-89a8-4f08df81a06a","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"id":"27cb9107-70cc-4674-99a4-01e0fe617b6f","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"🏬 Mental Model — The Retail Store Analogy","type":"text"}],"id":"b876d67a-4010-4cc0-8b27-7b20cc496172","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Think of a data warehouse as a ","type":"text"},{"styles":{"bold":true},"text":"retail store''s back-office reporting system","type":"text"},{"styles":{},"text":":","type":"text"}],"id":"1f70cc7c-d7cb-42fc-bf87-5cda0e94ba28","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{"bold":true},"text":"Concept","type":"text"}],"props":{"backgroundColor":"rgba(214, 213, 212, 0.035)","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"Analogy","type":"text"}],"props":{"backgroundColor":"rgba(214, 213, 212, 0.035)","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Fact Table","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"The ","type":"text"},{"styles":{"bold":true},"text":"cash register receipt","type":"text"},{"styles":{},"text":" — records ","type":"text"},{"styles":{"italic":true},"text":"what happened","type":"text"},{"styles":{},"text":": quantity sold, price paid, discount applied","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Dimension Table","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"The ","type":"text"},{"styles":{"bold":true},"text":"product catalogue, customer card, and calendar","type":"text"},{"styles":{},"text":" — describes ","type":"text"},{"styles":{"italic":true},"text":"who, what, where, and when","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"8158f0c1-1f60-4eba-911c-9d056be8dcd3","props":{"textColor":"default"},"type":"table"},{"children":[],"content":[{"styles":{"bold":true},"text":"The receipt alone tells you numbers. The catalogue and customer card give those numbers context and meaning.","type":"text"}],"id":"4764c868-3cd1-4576-9fdf-033697169ed1","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textColor":"rgb(214, 213, 212)"},"type":"quote"},{"children":[],"id":"a4794fe1-6e9d-4511-9472-635a1246f565","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"📖 The Two Building Blocks","type":"text"}],"id":"755f1047-b000-4549-a6e7-2a2bb733ddd9","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"📊 Fact Tables — ","type":"text"},{"styles":{"bold":true,"italic":true},"text":"\"What Happened\"","type":"text"}],"id":"910ada11-aca2-4022-b65e-4344c90b0536","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Fact tables store ","type":"text"},{"styles":{"bold":true},"text":"measurable, quantitative events","type":"text"},{"styles":{},"text":" — the numeric metrics your business cares about.","type":"text"}],"id":"b634a15e-efd8-44d6-9bdb-c38441a933bf","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Every ","type":"text"},{"styles":{"bold":true},"text":"row","type":"text"},{"styles":{},"text":" represents a single business event (a sale, a click, a shipment, a login)","type":"text"}],"id":"5eaebf35-65b6-4bbe-ad39-9bd126ffaa74","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Fact tables are ","type":"text"},{"styles":{"bold":true},"text":"narrow but deep","type":"text"},{"styles":{},"text":" — few columns, but millions or billions of rows","type":"text"}],"id":"e7087832-e89f-46a4-b771-f52e6a3e849b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Columns contain ","type":"text"},{"styles":{"bold":true},"text":"numeric measures","type":"text"},{"styles":{},"text":" and ","type":"text"},{"styles":{"bold":true},"text":"foreign keys","type":"text"},{"styles":{},"text":" pointing to dimension tables","type":"text"}],"id":"9d098325-ccef-445b-a179-f27878c6c6d5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Think of facts as ","type":"text"},{"styles":{"bold":true},"text":"verbs","type":"text"},{"styles":{},"text":" — something ","type":"text"},{"styles":{"italic":true},"text":"happened","type":"text"}],"id":"21a1df25-dcb9-45b3-82e7-602a96e6711b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Typical Fact Table columns:","type":"text"}],"id":"451d61bc-47aa-44f3-8e93-9ca4063cb3ee","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":{"columnWidths":[null,null,null],"headerCols":3,"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{"bold":true},"text":"Column","type":"text"}],"props":{"backgroundColor":"rgba(214, 213, 212, 0.035)","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"Type","type":"text"}],"props":{"backgroundColor":"rgba(214, 213, 212, 0.035)","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"Description","type":"text"}],"props":{"backgroundColor":"rgba(214, 213, 212, 0.035)","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"tableCell"}]}],"type":"tableContent"},"id":"35f861a7-67c4-407c-8dd2-0880da5a471a","props":{"textColor":"default"},"type":"table"},{"children":[],"content":{"columnWidths":[null,null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{"bold":true},"text":"Column","type":"text"}],"props":{"backgroundColor":"rgba(214, 213, 212, 0.035)","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"Type","type":"text"}],"props":{"backgroundColor":"rgba(214, 213, 212, 0.035)","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"Description","type":"text"}],"props":{"backgroundColor":"rgba(214, 213, 212, 0.035)","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"Sale_ID","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"row