},{"styles":{"code":true},"text":".env","type":"text"},{"styles":{},"text":" to Git","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Add ","type":"text"},{"styles":{"code":true},"text":".env","type":"text"},{"styles":{},"text":" to ","type":"text"},{"styles":{"code":true},"text":".gitignore","type":"text"},{"styles":{},"text":" immediately","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Using ","type":"text"},{"styles":{"code":true},"text":"os.environ[\"KEY\"]","type":"text"},{"styles":{},"text":" without a default","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Use ","type":"text"},{"styles":{"code":true},"text":"os.environ.get(\"KEY\", \"default\")","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Forgetting to call ","type":"text"},{"styles":{"code":true},"text":"load_dotenv()","type":"text"},{"styles":{},"text":" before reading env vars","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Call ","type":"text"},{"styles":{"code":true},"text":"load_dotenv()","type":"text"},{"styles":{},"text":" at the top of the script","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Putting non-secret config in ","type":"text"},{"styles":{"code":true},"text":".env","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Use YAML or INI for non-secret structured config","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Using ","type":"text"},{"styles":{"code":true},"text":"yaml.load()","type":"text"},{"styles":{},"text":" instead of ","type":"text"},{"styles":{"code":true},"text":"yaml.safe_load()","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Always use ","type":"text"},{"styles":{"code":true},"text":"yaml.safe_load()","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"No ","type":"text"},{"styles":{"code":true},"text":".env.example","type":"text"},{"styles":{},"text":" in the repo","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Commit ","type":"text"},{"styles":{"code":true},"text":".env.example","type":"text"},{"styles":{},"text":" with empty values so teammates know what keys to set","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Hardcoding secrets directly in Python files","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Move them to ","type":"text"},{"styles":{"code":true},"text":".env","type":"text"},{"styles":{},"text":" immediately","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"77d48d75-3513-4a59-9ec6-343a2bd2c7f6","props":{"textColor":"default"},"type":"table"},{"children":[],"id":"61293f52-fbe6-48d9-8298-4b2d8e63c35e","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Practice ideas","type":"text"}],"id":"d187ba48-4423-47e2-b914-e8ddbed608f9","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Create a ","type":"text"},{"styles":{"code":true},"text":".env","type":"text"},{"styles":{},"text":" file with three fake keys. Add it to ","type":"text"},{"styles":{"code":true},"text":".gitignore","type":"text"},{"styles":{},"text":". Create a ","type":"text"},{"styles":{"code":true},"text":".env.example","type":"text"},{"styles":{},"text":" with the same keys but empty values.","type":"text"}],"id":"4277e9c0-b8cf-427f-9908-e8ba746e7fbe","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Write a script that calls ","type":"text"},{"styles":{"code":true},"text":"load_dotenv()","type":"text"},{"styles":{},"text":" and reads all three values with ","type":"text"},{"styles":{"code":true},"text":"os.environ.get()","type":"text"},{"styles":{},"text":", using safe defaults.","type":"text"}],"id":"84a6679d-3cdf-492d-91ed-7ee7a8fcc3f4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Create a ","type":"text"},{"styles":{"code":true},"text":"config.yaml","type":"text"},{"styles":{},"text":" with three non-secret settings. Load it with ","type":"text"},{"styles":{"code":true},"text":"yaml.safe_load()","type":"text"},{"styles":{},"text":" and print each value.","type":"text"}],"id":"674efbea-ab0c-4fff-baf2-9c4a8ed134a9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Do the same with a ","type":"text"},{"styles":{"code":true},"text":"config.ini","type":"text"},{"styles":{},"text":" file using ","type":"text"},{"styles":{"code":true},"text":"configparser","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"f2d9f407-21c9-494f-a680-935f8c1eea46","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Explain aloud: what goes in ","type":"text"},{"styles":{"code":true},"text":".env","type":"text"},{"styles":{},"text":" and what goes in ","type":"text"},{"styles":{"code":true},"text":"config.yaml","type":"text"},{"styles":{},"text":"? Why?","type":"text"}],"id":"7159bcbd-5c68-4ef7-b043-40987056c4ce","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"id":"209fa049-7f24-4d9f-a4c5-4b689216e8e2","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Final integrated coding example","type":"text"}],"id":"e8935525-269c-4f2d-8548-406bcb095f3a","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Scenario:","type":"text"},{"styles":{},"text":" A small pipeline job starts up. It loads secrets from ","type":"text"},{"styles":{"code":true},"text":".env","type":"text"},{"styles":{},"text":" and non-secret settings from ","type":"text"},{"styles":{"code":true},"text":"config.yaml","type":"text"},{"styles":{},"text":". It prints a summary of what it loaded and confirms that secrets are not hardcoded anywhere.","type":"text"}],"id":"20dc5314-31a8-4e86-9bf9-905d161b02db","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"# .env  (never committed — listed in .gitignore)\nDB_PASSWORD=supersecret\nAPI_KEY=abc123xyz\nDB_HOST=localhost\n\n# .env.example  (committed — shows teammates what keys are needed)\nDB_PASSWORD=\nAPI_KEY=\nDB_HOST=\n\n# config.yaml  (safe to commit — no secrets)\nbatch_size: 500\ninput_path: \"data/orders.csv\"\nthreshold: 100","type":"text"}],"id":"8adedceb-0b50-479b-ac19-39c6b880e004","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"import os\nimport yaml\nfrom dotenv import load_dotenv\n\n# --- Control Switch: unlock the hidden drawer ---\nload_dotenv()   # reads .env into os.environ\n\n# --- Lockbox: retrieve secrets safely ---\ndb_password = os.environ.get(\"DB_PASSWORD\", \"\")\napi_key     = os.environ.get(\"API_KEY\", \"not_set\")\ndb_host     = os.environ.get(\"DB_HOST\", \"localhost\")\n\nif not db_password:\n    raise ValueError(\"DB_PASSWORD is not set. Check your .env file.\")\n\n# --- Light config: load non-secret settings from YAML ---\nwith open(\"config.yaml\", \"r\") as f:\n    config = yaml.safe_load(f)\n\nbatch_size  = config[\"batch_size\"]\ninput_path  = config[\"input_path\"]\nthreshold   = config[\"threshold\"]\n\n# --- Summary: confirm what was loaded ---\nprint(\"Control Room ready.\")\nprint(f\"  DB host:    {db_host}\")\nprint(f\"  API key:    {''set'' if api_key != ''not_set'' else ''MISSING''}\")\nprint(f\"  Batch size: {batch_size}\")\nprint(f\"  Input path: {input_path}\")\nprint(f\"  Threshold:  {threshold}\")\n# Note: never print db_password or api_key values","type":"text"}],"id":"eb08c31a-f15c-49f0-89c2-248f8c0514f9","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"What each section maps to:","type":"text"}],"id":"83a9c50d-d01d-47de-8181-20fdbb400eff","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Code section","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Metaphor part","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":".env","type":"text"},{"styles":{},"text":" file with secrets","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Hidden Drawer","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":".gitignore","type":"text"},{"styles":{},"text":" entry for ","type":"text"},{"styles":{"code":true},"text":".env","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Notice Board","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"load_dotenv()","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Control Switch","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"os.environ.get(\"KEY\", \"default\")","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Lockbox","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"yaml.safe_load()","type":"text"},{"styles":{},"text":" for non-secret config","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Light Config","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"079cb7e1-4501-4299-8a4e-c49a98c3d5b6","props":{"textColor":"default"},"type":"table"},{"children":[],"id":"6b01d3c1-f1e3-43d8-b7c2-9a9ac17d12af","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"italic":true},"text":"If you can write this script from memory, explain why ","type":"text"},{"styles":{"code":true},"text":".env","type":"text"},{"styles":{"italic":true},"text":" is in ","type":"text"},{"styles":{"code":true},"text":".gitignore","type":"text"},{"styles":{"italic":true},"text":", and clearly state what belongs in ","type":"text"},{"styles":{"code":true},"text":".env","type":"text"},{"styles":{"italic":true},"text":" versus ","type":"text"},{"styles":{"code":true},"text":"config.yaml","type":"text"},{"styles":{"italic":true},"text":", you are ready for internship-level config management questions in the Control Room.","type":"text"}],"id":"9c8cc701-b256-46cc-989c-b10024d69169","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[],"id":"aa1d3918-49fb-4011-8a24-1aadd728f621","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"}]'::jsonb, '3e9e3dd3-a59b-4b02-968a-ee95e7317583') ON CONFLICT ("node_id") DO UPDATE SET "bad_example" = EXCLUDED."bad_example", "completed_at" = EXCLUDED."completed_at", "created_at" = EXCLUDED."created_at", "definition" = EXCLUDED."definition", "good_example" = EXCLUDED."good_example", "is_completed" = EXCLUDED."is_completed", "key_points" = EXCLUDED."key_points", "last_edited" = EXCLUDED."last_edited", "map_id" = EXCLUDED."map_id", "mental_model" = EXCLUDED."mental_model", "notes" = EXCLUDED."notes", "resources" = EXCLUDED."resources", "rich_content" = EXCLUDED."rich_content", "user_id" = EXCLUDED."user_id";
INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-06-13T15:26:38.380254+00:00', '', '', '29e5c08e-935c-4d3b-afe3-5cb01b56981c', false, '[]'::jsonb, '2026-06-13T15:26:40.235+00:00', '2ad473fe-77dd-481e-8ba7-4b2b0336173f', '', 'aed6258e-7fd1-44ec-aa13-8a090ca835a3', '', '[]'::jsonb, '[{"children":[],"content":[{"styles":{},"text":"Python for Data Engineering — Topic 15: The Bonus Shelf","type":"text"}],"id":"b4b3b60d-e8a9-45c7-8055-00cfbcce866b","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"boto3 / S3","type":"text"}],"id":"50bdb636-0062-476f-8c50-41a162d3c6be","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"id":"67e9a924-114e-4b47-858c-783b5979a2ae","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Very short intro","type":"text"}],"id":"31f884d0-8e05-47e6-91b7-4fa652955ec5","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"At the ","type":"text"},{"styles":{"bold":true},"text":"Distribution Hub","type":"text"},{"styles":{},"text":", the ","type":"text"},{"styles":{"bold":true},"text":"Bonus Shelf","type":"text"},{"styles":{},"text":" holds extra supplies — things that are nice to have but not strictly required. If your internship uses ","type":"text"},{"styles":{"bold":true},"text":"cloud storage","type":"text"},{"styles":{},"text":", you will need to access it. The ","type":"text"},{"styles":{"bold":true},"text":"cloud locker key","type":"text"},{"styles":{},"text":" (AWS credentials from environment variables) unlocks access. The ","type":"text"},{"styles":{"bold":true},"text":"upload cart","type":"text"},{"styles":{},"text":" and ","type":"text"},{"styles":{"bold":true},"text":"download cart","type":"text"},{"styles":{},"text":" move files in and out. The ","type":"text"},{"styles":{"bold":true},"text":"inventory list","type":"text"},{"styles":{},"text":" shows what is stored. The ","type":"text"},{"styles":{"bold":true},"text":"read bin","type":"text"},{"styles":{},"text":" pulls data directly without saving a local copy. Topic 15 is a ","type":"text"},{"styles":{"bold":true},"text":"bonus topic","type":"text"},{"styles":{},"text":" — if your internship touches S3, you will be grateful to know it. If not, skip it without worry.","type":"text"}],"id":"2b74bcb2-2bb7-4aa5-be78-eeeacda26cdd","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"bc0ecf46-d58b-47c8-8b91-2a69307ee7bf","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Mind map","type":"text"}],"id":"97838fcc-1649-4d7a-97e9-8eeddb8ffa79","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"BONUS SHELF\n(boto3 / S3)\n│\n├── Cloud Locker Key\n│   └── credentials via env vars (AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY)\n│\n├── S3 Client\n│   └── boto3.client(\"s3\")\n│\n├── Upload Cart\n│   └── upload_file(local_path, bucket, s3_key)\n│\n├── Download Cart\n│   └── download_file(bucket, s3_key, local_path)\n│\n├── Inventory List\n│   └── list_objects_v2(Bucket=bucket)\n│\n└── Read Bin\n    └── get_object(Bucket=bucket, Key=key)[\"Body\"].read()","type":"text"}],"id":"6aff3489-0e49-433c-b315-7eef917501e7","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"2858abac-e9dd-4345-be68-7e4bc3102764","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Decision tree","type":"text"}],"id":"fbfa8a94-a9b6-42c4-a142-c7d06875fbb6","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Does your internship use AWS S3?\n│\n├── NO → Skip this topic. Come back if needed.\n│\n└── YES → Continue\n\nDo you have AWS credentials?\n└── Set as env vars: AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY\n\nNeed to work with S3?\n│\n├── Create a client\n│   └── s3 = boto3.client(\"s3\")\n│\n├── Need to upload a file?\n│   └── s3.upload_file(local_path, bucket, s3_key)\n│\n├── Need to download a file?\n│   └── s3.download_file(bucket, s3_key, local_path)\n│\n├── Need to see what is in a bucket?\n│   └── s3.list_objects_v2(Bucket=bucket)\n│\n└── Need to read a file without saving it locally?\n    └── data = s3.get_object(Bucket=bucket, Key=key)[\"Body\"].read()","type":"text"}],"id":"8a56d03a-df9b-47ae-88f0-cdf61ec8ee83","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"9109ff78-e1a9-40c5-83c8-03700666c628","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Concept breakdown","type":"text"}],"id":"08ac88bf-3329-46f5-8217-6673f8c8206e","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"id":"97ff8d3d-1dd3-4ace-8bd4-6d07d70b0b72","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"1) Cloud Locker Key — credentials via env vars","type":"text"}],"id":"f0e30e23-3acf-4869-92bd-5a135b99e512","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" AWS credentials (access key ID and secret access key) stored in environment variables. ","type":"text"},{"styles":{"code":true},"text":"boto3","type":"text"},{"styles":{},"text":" reads them automatically when creating a client.","type":"text"}],"id":"f696aced-9d6b-4ee9-8f32-4c55cf94c36d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters in an internship:","type":"text"},{"styles":{},"text":" Hardcoding credentials is a serious security risk. Environment variables are the safe, standard pattern. If your internship uses S3, you will need to know this.","type":"text"}],"id":"f81fd800-3ba3-46b5-808f-40f27d7dc0a1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"5bf417b1-acbc-4120-a0cb-89abe267689d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"# .env (never commit!)\nAWS_ACCESS_KEY_ID=AKIAIOSFODNN7EXAMPLE\nAWS_SECRET_ACCESS_KEY=wJalrXUtnFEMI/K7MDENG/bPxRfiCYEXAMPLEKEY","type":"text"}],"id":"7c2a2981-f8ba-49a9-864c-18fc1ea47340","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"import os\nfrom dotenv import load_dotenv\n\nload_dotenv()\n\n# boto3 reads these automatically\naccess_key = os.environ.get(\"AWS_ACCESS_KEY_ID\")\nsecret_key = os.environ.get(\"AWS_SECRET_ACCESS_KEY\")","type":"text"}],"id":"3641ab3a-6bff-4ec9-870b-f094cb2a09dc","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Rule: Never hardcode credentials. Always use environment variables.","type":"text"}],"id":"08e70b07-d92e-4bb1-9605-e7f5e501af57","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"b645c6fa-26d1-4087-bcd0-016244ebb240","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"2) S3 Client — ","type":"text"},{"styles":{"code":true},"text":"boto3.client(\"s3\")","type":"text"}],"id":"5a71fad5-1426-4f72-bb17-6551a458bcdd","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" Creates a client object that lets you call S3 operations. The client reads credentials from the environment automatically.","type":"text"}],"id":"ce759942-c969-40ce-ad9e-6fb809c2fd30","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters in an internship:","type":"text"},{"styles":{},"text":" This is the entry point for all S3 work. Knowing how to create it is the foundation.","type":"text"}],"id":"1e7a25ee-7d5e-42bf-8703-e47b2a7e2618","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"9975412d-f28c-481a-8363-0619c5184c34","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"import boto3\n\ns3 = boto3.client(\"s3\", region_name=\"us-east-1\")","type":"text"}],"id":"a2bde651-f886-40f2-9308-74942d059173","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Rule: ","type":"text"},{"styles":{"code":true},"text":"region_name","type":"text"},{"styles":{},"text":" is optional but good practice. Specify the region your bucket is in.","type":"text"}],"id":"68925646-b5c2-4144-9974-8711da0f65f3","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"c6eb5985-59ea-4069-b871-a60f70a736ba","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"3) Upload Cart — ","type":"text"},{"styles":{"code":true},"text":"upload_file()","type":"text"}],"id":"a3381775-246c-4a93-aaea-f03c254bf0ae","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" Uploads a local file to S3. Takes the local file path, the S3 bucket name, and the S3 key (object name).","type":"text"}],"id":"3edb7f27-5bea-42ed-b841-336a87197ee4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters in an internship:","type":"text"},{"styles":{},"text":" Saving processed data to the cloud is a very common task. This is the simple way to do it.","type":"text"}],"id":"1d7b2b96-bd3c-41f2-948b-e483ab2d22f6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"be91a2e7-7f85-41d0-8de0-4f06ab397b41","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"s3.upload_file(\n    \"local_orders.csv\",           # local file path\n    \"my-data-bucket\",             # S3 bucket name\n    \"processed/orders.csv\"        # S3 key (path inside bucket)\n)","type":"text"}],"id":"2fcd4a73-70c1-4cba-8cad-bf102e5fb250","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"76e4caf8-7c5f-4a4c-984a-26c1d6d9754f","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"4) Download Cart — ","type":"text"},{"styles":{"code":true},"text":"download_file()","type":"text"}],"id":"0c43ef8e-d582-4a9f-9a71-16e1cc5852b1","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" Downloads a file from S3 to your local system. Takes the bucket name, S3 key, and where to save it locally.","type":"text"}],"id":"3f004276-af79-47f0-bdab-b612a4f3a8d4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters in an internship:","type":"text"},{"styles":{},"text":" Retrieving cloud data is equally common. This is the standard way.","type":"text"}],"id":"65e6989b-15c3-4cd4-8908-907518b37f06","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"4e87cee1-988d-4fd1-9981-17b90dc845c8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"s3.download_file(\n    \"my-data-bucket\",             # S3 bucket name\n    \"raw/orders.csv\",             # S3 key\n    \"local_orders.csv\"            # local file path\n)","type":"text"}],"id":"0345ec99-8e76-46cb-982e-c685a295101c","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"80bdf926-21bf-44dc-9099-c51117902cd4","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"5) Inventory List — ","type":"text"},{"styles":{"code":true},"text":"list_objects_v2()","type":"text"}],"id":"6a8acb6f-8a04-4837-b5c3-9d2b43c541db","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" Lists all objects (files) in an S3 bucket. Returns metadata including key (name), size, and last modified time.","type":"text"}],"id":"42014f81-deb9-46d8-8617-9bdfee96c72e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters in an internship:","type":"text"},{"styles":{},"text":" You often need to know what files are in a bucket before processing them. This is the way to check.","type":"text"}],"id":"738b36a2-f56d-4333-8292-06afc4e6444a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"02027776-c579-4661-aa0f-3ffefbecdd33","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"response = s3.list_objects_v2(Bucket=\"my-data-bucket\", Prefix=\"processed/\")\n\nfor obj in response.get(\"Contents\", []):\n    print(f\"Key: {obj[''Key'']}, Size: {obj[''Size'']}\")","type":"text"}],"id":"ad447a7a-605d-4ddf-8ef3-0d849638808b","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Rule: The result might have thousands of files. For now, assume it fits in memory. Advanced: use a paginator.","type":"text"}],"id":"2ab992d6-f385-4111-a41e-f4e7f52825b8","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"9ad94614-6191-4e9e-9b6f-c4c70fc9ef3e","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"6) Read Bin — ","type":"text"},{"styles":{"code":true},"text":"get_object()[Body].read()","type":"text"}],"id":"bb6b91da-82f9-450a-84fb-c0fe7af3b1e2","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" Reads the content of an S3 object (file) directly into memory without saving it to disk first. Very useful for small files and piping data.","type":"text"}],"id":"882a1511-2fb1-4cbc-847c-397370e833a9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters in an internship:","type":"text"},{"styles":{},"text":" This avoids creating temporary files and is faster for small data. A very common pattern.","type":"text"}],"id":"08e93c7b-a74f-4e75-9264-2b529ff40aaf","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"b57b79fd-cfc8-4d34-8078-2f615a3baa9f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"response = s3.get_object(Bucket=\"my-data-bucket\", Key=\"config.json\")\ncontent = response[\"Body\"].read()\n\n# Parse the JSON directly\nimport json\nconfig = json.loads(content)","type":"text"}],"id":"21a4b5b0-40c6-4827-8cf6-b4d04ee6a162","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"098961d5-5516-4192-adcd-7c8a2ea03172","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Common mistakes","type":"text"}],"id":"2778c5ab-d424-4b4c-b204-589a6c0090bb","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Mistake","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Fix","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Hardcoding AWS credentials","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Always use environment variables","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Forgetting ","type":"text"},{"styles":{"code":true},"text":"load_dotenv()","type":"text"},{"styles":{},"text":" before accessing env vars","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Call it at the top of your script","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Wrong bucket name or key","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Double-check the exact bucket and key names","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Forgetting to specify region","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Add ","type":"text"},{"styles":{"code":true},"text":"region_name=\"us-east-1\"","type":"text"},{"styles":{},"text":" (or your region)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Trying to read ","type":"text"},{"styles":{"code":true},"text":"response","type":"text"},{"styles":{},"text":" directly instead of ","type":"text"},{"styles":{"code":true},"text":"response[\"Body\"]","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Use ","type":"text"},{"styles":{"code":true},"text":"response[\"Body\"].read()","type":"text"},{"styles":{},"text":" for content","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Not handling missing files","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Add try/except for ","type":"text"},{"styles":{"code":true},"text":"s3.download_file()","type":"text"},{"styles":{},"text":" — it raises if the key does not exist","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"9d0b86fc-dbd5-4f97-acf3-771249b16f36","props":{"textColor":"default"},"type":"table"},{"children":[],"id":"2a5376aa-3567-4356-b292-471e17b232a9","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Practice ideas","type":"text"}],"id":"ca5eca9a-cc77-4c7f-9db9-ca523a7499fc","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Set up AWS credentials in a ","type":"text"},{"styles":{"code":true},"text":".env","type":"text"},{"styles":{},"text":" file. Load them with ","type":"text"},{"styles":{"code":true},"text":"load_dotenv()","type":"text"},{"styles":{},"text":". Verify they are accessible via ","type":"text"},{"styles":{"code":true},"text":"os.environ","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"63351e9f-8696-4be2-849d-ca60c81ffa27","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Create an S3 client with ","type":"text"},{"styles":{"code":true},"text":"boto3.client(\"s3\")","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"20525952-ecb4-457e-b90e-18d4abf9b309","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"List the objects in an S3 bucket using ","type":"text"},{"styles":{"code":true},"text":"list_objects_v2()","type":"text"},{"styles":{},"text":". Print the key and size of each.","type":"text"}],"id":"e83bee99-b4e9-4082-8897-297d1eeeac98","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Upload a local test file to S3 with ","type":"text"},{"styles":{"code":true},"text":"upload_file()","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"819f4416-a10e-4480-88df-28426e8611dc","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Download the file back with ","type":"text"},{"styles":{"code":true},"text":"download_file()","type":"text"},{"styles":{},"text":" and verify it matches the original.","type":"text"}],"id":"63aa6f2e-0336-4fb3-9ff7-14a78e0de4be","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Read a small JSON file from S3 directly with ","type":"text"},{"styles":{"code":true},"text":"get_object()[Body].read()","type":"text"},{"styles":{},"text":" and parse it.","type":"text"}],"id":"0658b8ad-4dc1-418b-a24c-f42e2f2538bf","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"id":"a66b0e47-7eee-4946-a6cf-ce204b94b92c","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Final integrated coding example","type":"text"}],"id":"6a965124-c62c-4391-a267-4399e9f7e03a","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Scenario:","type":"text"},{"styles":{},"text":" A small pipeline checks what order files are in an S3 bucket, downloads the latest one, processes it, uploads the result back, and reads a config file directly from S3.","type":"text"}],"id":"fd33764c-968f-4b87-b7c6-ae6e88a9bb79","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"import os\nimport json\nimport boto3\nfrom dotenv import load_dotenv\n\n# --- Cloud Locker Key: load credentials from environment ---\nload_dotenv()\n\n# boto3 reads AWS_ACCESS_KEY_ID and AWS_SECRET_ACCESS_KEY automatically\n# (they must be set in .env or system environment)\n\n# --- S3 Client: create the connection ---\ns3 = boto3.client(\"s3\", region_name=\"us-east-1\")\n\nBUCKET = \"my-data-bucket\"\n\n# --- Inventory List: see what files are in the bucket ---\nprint(\"Files in bucket:\")\nresponse = s3.list_objects_v2(Bucket=BUCKET, Prefix=\"raw/\")\n\nif \"Contents\" in response:\n    for obj in response[\"Contents\"]:\n        print(f\"  {obj[''Key'']} ({obj[''Size'']} bytes)\")\nelse:\n    print(\"  No files found\")\n\n# --- Download Cart: fetch the latest order file ---\norder_file = \"raw/orders_2025-01-15.csv\"\nlocal_file = \"orders.csv\"\n\ntry:\n    s3.download_file(BUCKET, order_file, local_file)\n    print(f\"\\nDownloaded {order_file} to {local_file}\")\nexcept Exception as e:\n    print(f\"Error downloading: {e}\")\n    local_file = None\n\n# --- Process the file (simulated) ---\nif local_file:\n    with open(local_file, \"r\") as f:\n        data = f.read()\n    \n    # Simulate processing\n    processed_data = data.upper()\n    \n    # --- Upload Cart: save results back to S3 ---\n    output_file = \"processed/orders_2025-01-15.csv\"\n    with open(\"temp_processed.csv\", \"w\") as f:\n        f.write(processed_data)\n    \n    s3.upload_file(\"temp_processed.csv\", BUCKET, output_file)\n    print(f\"Uploaded processed file to {output_file}\")\n    \n    # Clean up local temp file\n    os.remove(\"temp_processed.csv\")\n\n# --- Read Bin: fetch config directly from S3 without saving locally ---\nconfig_key = \"config/pipeline.json\"\nresponse = s3.get_object(Bucket=BUCKET, Key=config_key)\nconfig_bytes = response[\"Body\"].read()\nconfig = json.loads(config_bytes)\n\nprint(f\"\\nConfig loaded from S3: {config}\")","type":"text"}],"id":"18f83ba2-535b-48c0-9cfd-adf70f9f4da3","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"What each section maps to:","type":"text"}],"id":"aa190142-6f1d-4472-8114-d9aee76ba74d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Code section","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Metaphor part","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"load_dotenv()","type":"text"},{"styles":{},"text":" + env vars","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Cloud Locker Key","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"boto3.client(\"s3\")","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"S3 Client","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"s3.list_objects_v2(...)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Inventory List","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"s3.download_file(...)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Download Cart","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"s3.upload_file(...)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Upload Cart","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"s3.get_object(...)[Body].read()","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Read Bin","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"689bb851-63b2-4ddf-8a8c-4275784be5c4","props":{"textColor":"default"},"type":"table"},{"children":[],"id":"44b2039c-45ac-4c38-a2e6-b98ef2d69aa5","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"Important note:","type":"text"},{"styles":{},"text":" This is a ","type":"text"},{"styles":{"bold":true},"text":"bonus topic","type":"text"},{"styles":{},"text":". If your internship does not use AWS S3, you do not need to master this. But if it does, these six concepts will get you 90% of the way there.","type":"text"}],"id":"a95df0bb-1d28-4f06-99d4-a93f6a4e1a91","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"If you can write this script from memory and explain the six operations, you are ready for S3 questions on the Bonus Shelf — should they come up.","type":"text"}],"id":"c0364b29-dfb0-47cb-a81e-99674057118e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[],"id":"f560eb41-b94c-4c17-81da-91734da31cc9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"}]'::jsonb, '3e9e3dd3-a59b-4b02-968a-ee95e7317583') ON CONFLICT ("node_id") DO UPDATE SET "bad_example" = EXCLUDED."bad_example", "completed_at" = EXCLUDED."completed_at", "created_at" = EXCLUDED."created_at", "definition" = EXCLUDED."definition", "good_example" = EXCLUDED."good_example", "is_completed" = EXCLUDED."is_completed", "key_points" = EXCLUDED."key_points", "last_edited" = EXCLUDED."last_edited", "map_id" = EXCLUDED."map_id", "mental_model" = EXCLUDED."mental_model", "notes" = EXCLUDED."notes", "resources" = EXCLUDED."resources", "rich_content" = EXCLUDED."rich_content", "user_id" = EXCLUDED."user_id";
INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-06-14T06:59:07.409972+00:00', '', '', '5c001af1-16d2-424c-a68e-0dffb195fb70', false, '[]'::jsonb, '2026-06-14T06:59:09.705+00:00', '2ad473fe-77dd-481e-8ba7-4b2b0336173f', '', '8f2578da-0041-439a-a6e1-b0b60013d632', '', '[]'::jsonb, '[{"children":[],"content":[{"styles":{},"text":"SQL for Data Engineering — Internship Study Note","type":"text"}],"id":"d4a8561e-dc32-4bd3-83a8-b79095787f7c","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Topic 3: The Multi-Step Desk","type":"text"}],"id":"68b062b0-2663-431d-a55c-28a378b50277","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"id":"3a67fbdd-0719-4145-b18c-4aaa6f989dea","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"What This Note Is","type":"text"}],"id":"5c5a05f7-b473-4b49-ba06-28c0732e4c18","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Inside the Control Room, the ","type":"text"},{"styles":{"bold":true},"text":"Multi-Step Desk","type":"text"},{"styles":{},"text":" is the station where complex work gets broken into clean, ordered steps. Instead of writing one tangled query, you use the Shortcut Panel (WITH) to open a series of trays. The first query goes into the Draft Tray. Each following query goes into a Revision Tray, building on what came before. The result is a Clean Workflow Board — a query anyone can read, debug, and change one step at a time. This is what CTEs do. An internship interviewer will expect you to know how to use them and when to prefer them over nested subqueries.","type":"text"}],"id":"be232b3f-6745-4b9a-ae20-e088c4196461","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"0ada09f9-66e2-44f3-bd83-afbaaca16e93","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Mind Map","type":"text"}],"id":"24c2fb47-5362-4e61-b0fa-1bc882f42c63","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"                        THE MULTI-STEP DESK\n                           (CTEs / WITH)\n                                │\n          ┌─────────────────────┼─────────────────────┐\n          │                     │                     │\n    SHORTCUT PANEL         TRAY SYSTEM          CLEAN WORKFLOW\n       (WITH)                   │                   BOARD\n          │              ┌──────┴──────┐         (Readability,\n    Opens the desk       │             │          Reuse, Debug)\n                    DRAFT TRAY   REVISION TRAY\n                  (first CTE)   (next CTEs that\n                                build on prior)\n                                     │\n                              Can chain as many\n                              trays as needed\n                                     │\n                              Final SELECT reads\n                              from the last tray\n\n          │\n          └──── Key Properties ────────────────────────┐\n                                                       │\n                    ┌──────────────────┬───────────────┴──────────┐\n                    │                  │                           │\n             Named and reusable  Defined once,           Easier to debug:\n             within the query    used many times         test each tray\n                                 in final SELECT         independently\n                                                                   │\n                                                    ┌──────────────┘\n                                                    │\n                                         Non-recursive only\n                                         (recursive exists\n                                         but is out of scope\n                                         for internship level)","type":"text"}],"id":"eebcad36-1828-4fef-a869-1553f0407c37","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"0872ca2a-d952-4c8f-ae36-7e981340e14f","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Decision Tree","type":"text"}],"id":"b7bff1dc-8b92-4bc3-884b-278aaa9e09c0","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"START: You need to write a multi-step SQL query\n          │\n          ▼\nIs the logic more than one step deep?\n    NO  → A plain SELECT is fine\n    YES → Consider CTE or subquery\n          │\n          ▼\nWould a nested subquery make this hard to read?\n    NO  → Subquery is acceptable for simple one-off filters\n    YES → Use a CTE (Multi-Step Desk)\n          │\n          ▼\nDo you need to reuse the same intermediate result more than once?\n    YES → CTE is clearly better (write once, reference many times)\n    NO  → Either works; prefer CTE for readability\n          │\n          ▼\nDo you need to debug one step at a time?\n    YES → CTE is better (you can run each tray independently)\n    NO  → Either works\n          │\n          ▼\nHow many steps?\n    │\n    ├─ 1 step → One CTE in the Draft Tray\n    ├─ 2–4 steps → Chain Revision Trays, each building on the last\n    └─ More than that → Still CTEs, but ask if the query can be simplified\n          │\n          ▼\nDoes any CTE need to call itself (hierarchy, tree)?\n    YES → Recursive CTE (out of internship scope — flag it, do not implement)\n    NO  → Standard non-recursive CTE (this note''s scope)\n          │\n          ▼\nWrite: WITH draft AS (...), revision AS (...) SELECT * FROM revision;","type":"text"}],"id":"236674fd-53d6-4220-bdfc-5e141683993e","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"de52808b-ab68-4a8c-a6e5-7104721a2ec3","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Concept Breakdown","type":"text"}],"id":"c4bf4db2-ffe5-4a52-8194-151885248e6e","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"id":"0d3a4239-86fb-4a44-be98-13764880f20d","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"1. What a CTE Is","type":"text"}],"id":"23303cc0-ff90-4b58-9a03-e7a04f0bd403","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" A CTE (Common Table Expression) is a named, temporary result set that you define at the top of a query and reference like a table anywhere below it. It exists only for the duration of that query. It does not create a permanent table or view.","type":"text"}],"id":"a5a6ffad-46eb-42d7-92e2-22dd6032bb05","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters:","type":"text"},{"styles":{},"text":" CTEs are the standard way to write multi-step SQL in data engineering. Interviewers use CTE questions to check if you can structure logic clearly. If you write deeply nested subqueries instead, it signals that you cannot organize complex work.","type":"text"}],"id":"66daf2c8-75fd-4dc2-8233-cb9ce69166ff","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"5efbfa10-7e58-4961-ba65-756387bd7f77","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"WITH active_users AS (\n    SELECT user_id, name\n    FROM users\n    WHERE status = ''active''         -- Draft Tray: isolate active users\n)\nSELECT *\nFROM active_users;                  -- final SELECT reads from the tray","type":"text"}],"id":"8e711f07-41b3-4080-a2e0-d50ae089408d","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"id":"6fc14add-081c-4fd8-af81-62f1d5100700","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"2. Shortcut Panel — WITH ... AS (...)","type":"text"}],"id":"20ad6cba-edbb-40c6-af11-7f410121ce36","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" WITH is the keyword that opens the Multi-Step Desk. Every CTE is declared using WITH (or a comma after the first one). The syntax is:","type":"text"}],"id":"fe9b5554-8d35-42f8-bb28-f98567003d29","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"WITH cte_name AS (\n    SELECT ...\n)\nSELECT ...\nFROM cte_name;","type":"text"}],"id":"702eab37-3904-4034-a18e-e3f2e3b07064","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"You only write WITH once, at the start. Each additional CTE is separated by a comma.","type":"text"}],"id":"5c2e6e24-9222-47da-824f-00558b97a3d7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters:","type":"text"},{"styles":{},"text":" Getting the syntax right is the minimum bar. Interviewers notice immediately if you write WITH before every CTE instead of just the first one — that is a syntax error.","type":"text"}],"id":"cfa625be-da59-4bf0-b2b8-a7d67c299653","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"c571ff39-85ca-45fa-8223-93cd5e4a35de","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"WITH first_cte AS (\n    SELECT ...         -- Draft Tray\n),\nsecond_cte AS (        -- comma, NOT another WITH\n    SELECT ...         -- Revision Tray\n)\nSELECT *\nFROM second_cte;","type":"text"}],"id":"92f80d45-c2df-443e-b7e4-14a08d94c2ce","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"id":"db00508c-962b-457d-aa33-bc864d6b1884","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"3. Draft Tray — First CTE","type":"text"}],"id":"901e6f68-1ede-4825-8fb8-d157a323d595","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" The first CTE in the chain. It reads directly from a real table. It is where raw data enters the desk and gets its first transformation — filtering, cleaning, or selecting only needed columns.","type":"text"}],"id":"dbe317e9-41f7-4c25-9166-6309ceb68fc2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters:","type":"text"},{"styles":{},"text":" The Draft Tray is where you establish the clean base that every Revision Tray depends on. A clean Draft Tray means every step after it works on reliable data.","type":"text"}],"id":"85234c4a-03dd-47d8-940d-13a91cbb9454","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"91f1d48e-ba38-4110-bee6-9100e3d4f710","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"WITH clean_orders AS (\n    SELECT\n        order_id,\n        customer_id,\n        amount,\n        order_date\n    FROM orders\n    WHERE status = ''completed''      -- filter raw data in the Draft Tray\n      AND amount IS NOT NULL\n)\nSELECT * FROM clean_orders;","type":"text"}],"id":"d11430c0-dcf1-4646-8b53-3230128a4a7b","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"id":"7fee331e-b4f2-4382-a308-8292a87680d1","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"4. Revision Tray — Chaining CTEs","type":"text"}],"id":"9a5b223a-a882-4929-b6f1-d6e2d10f7f12","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" Each CTE after the first can reference any CTE defined before it. This is how you build logic step by step: each Revision Tray receives the output of the Draft Tray (or a prior Revision Tray) and applies the next transformation.","type":"text"}],"id":"f0917e0f-91d5-42c4-bf77-5bd92f8ffd52","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters:","type":"text"},{"styles":{},"text":" Chaining is the core skill tested in CTE interview questions. You need to show you can break a complex problem into ordered steps and build each step on the last.","type":"text"}],"id":"01acfa83-4297-49d3-b505-dbf3db618f95","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"ba4d7802-55f6-4fbd-80d9-70a4df4425ab","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"WITH clean_orders AS (                         -- Draft Tray\n    SELECT order_id, customer_id, amount\n    FROM orders\n    WHERE status = ''completed''\n),\ncustomer_totals AS (                           -- Revision Tray 1\n    SELECT\n        customer_id,\n        SUM(amount) AS total_spent\n    FROM clean_orders                          -- reads from Draft Tray\n    GROUP BY customer_id\n),\nhigh_value AS (                                -- Revision Tray 2\n    SELECT *\n    FROM customer_totals                       -- reads from Revision Tray 1\n    WHERE total_spent > 1000\n)\nSELECT * FROM high_value;                      -- final SELECT","type":"text"}],"id":"86eb795b-4084-4345-92ce-96e3b141a197","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"id":"98c2d37f-de90-4605-90d3-5bf5d0d795a5","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"5. Clean Workflow Board — Readability, Reuse, and Debugging","type":"text"}],"id":"8e5b333b-b81b-4466-8e23-ec3833e12343","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" The three practical reasons CTEs are preferred over nested subqueries in a professional setting:","type":"text"}],"id":"e43ffff6-6011-4827-b7ab-cd4071c09610","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Readability:","type":"text"},{"styles":{},"text":" Each step has a name. You read the query top to bottom like a list of instructions, not inside-out like a nested subquery.","type":"text"}],"id":"6ebc24a2-8f40-4e06-b3a9-343b08331ec9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Reuse:","type":"text"},{"styles":{},"text":" A CTE defined once can be referenced multiple times in the final SELECT or in later CTEs. A subquery must be copy-pasted.","type":"text"}],"id":"4c44ace3-8fa0-4f2b-b18c-a27cd7c27d93","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Debugging:","type":"text"},{"styles":{},"text":" You can run a CTE in isolation by temporarily ending the query at that step and running ","type":"text"},{"styles":{"code":true},"text":"SELECT * FROM that_cte","type":"text"},{"styles":{},"text":". You cannot do this easily with a nested subquery.","type":"text"}],"id":"3abc908d-9cf2-44dd-b46e-9ec3d2589ab9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters:","type":"text"},{"styles":{},"text":" Interviewers ask \"why would you use a CTE instead of a subquery?\" This answer — readability, reuse, debugging — is the complete, expected response.","type":"text"}],"id":"43f4bd9f-d3f2-41d6-983c-adf4373f806d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example (reuse):","type":"text"}],"id":"3d340970-f59d-4748-acd0-bfe09a683634","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"WITH monthly_revenue AS (\n    SELECT\n        DATE_TRUNC(''month'', order_date) AS month,\n        SUM(amount) AS revenue\n    FROM orders\n    GROUP BY 1\n)\n-- CTE used twice in the final SELECT without rewriting it\nSELECT\n    m.month,\n    m.revenue,\n    m.revenue / NULLIF(SUM(m.revenue) OVER (), 0) AS share_of_total\nFROM monthly_revenue m\nORDER BY m.month;","type":"text"}],"id":"0aea4474-1302-4752-926f-c236729a0ad7","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"id":"4597941f-9037-40ad-b4bb-1068d3ddadb9","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"6. Recursive CTE — Awareness Only","type":"text"}],"id":"edacf770-2a6a-413b-87bb-de6a8f459523","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" A recursive CTE calls itself to process hierarchical or tree-structured data (e.g., org charts, folder paths). Syntax uses ","type":"text"},{"styles":{"code":true},"text":"WITH RECURSIVE","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"675319af-b2f6-4530-a46d-5b363ea8271f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters for internships:","type":"text"},{"styles":{},"text":" You will not be asked to write one at internship level, but you should be able to say: ","type":"text"},{"styles":{"italic":true},"text":"\"A recursive CTE is used for hierarchical data. It has an anchor member and a recursive member. It is out of scope for my current preparation.\"","type":"text"},{"styles":{},"text":" That answer is enough.","type":"text"}],"id":"060a880b-c58f-4279-bd62-89584101c887","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"42793fe1-2be5-4d6c-90ca-c0d7756cbc20","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"When CTE vs Subquery","type":"text"}],"id":"b860e412-9616-46a1-8cc4-07e615d567e8","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":{"columnWidths":[null,null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Situation","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Use CTE","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Use Subquery","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Logic is more than one step deep","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"✓","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Same intermediate result used more than once","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"✓","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"You need to debug step by step","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"✓","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Simple one-time filter in a WHERE clause","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"✓","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Very short, self-contained logic","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"✓","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Sharing query with a team","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"✓","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"f849f11e-2461-4370-a958-903723e63dd9","props":{"textColor":"default"},"type":"table"},{"children":[],"id":"6f3c8ca2-7ba9-4b04-8614-23af1a00efff","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Common Mistakes","type":"text"}],"id":"5ec270d9-8ab0-4a4a-83e2-ecf61f957fd9","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":{"columnWidths":[null,null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Mistake","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Why It Is Wrong","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Fix","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Writing WITH before every CTE","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Syntax error — WITH is written only once","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Write WITH once, separate additional CTEs with commas","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Referencing a CTE defined after the current one","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"CTEs can only reference CTEs defined before them","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Always define CTEs in the order they are needed","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Treating a CTE as a permanent table","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"CTEs exist only for the duration of the query","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Use a real table or view if persistence is needed","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Writing one giant CTE that does everything","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Defeats the purpose — harder to read and debug","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Break into smaller, focused trays","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Forgetting the final SELECT","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"A CTE with no SELECT after it produces nothing","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Always end with a SELECT from the last CTE","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Nesting CTEs inside CTEs","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"CTEs cannot be defined inside other CTEs","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Define all CTEs at the top level, chain them by referencing each other","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Using a CTE for a trivial one-line filter","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Adds unnecessary complexity","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Use a simple WHERE clause instead","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"e39725fe-017d-44c6-b014-f9f95a7530d1","props":{"textColor":"default"},"type":"table"},{"children":[],"id":"ef75c5d7-41f8-488f-b4b9-259134943a15","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Practice Ideas","type":"text"}],"id":"4ab4e79d-6215-416a-911d-aaefc8ae00cf","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"These are sized for an interview whiteboard or a 20-minute coding task.","type":"text"}],"id":"92cfcee5-9945-4d86-b6be-ff2601bd30da","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Write a two-CTE query: the first CTE filters orders to the last 90 days, the second CTE aggregates total revenue per customer from the first.","type":"text"}],"id":"ef1d8a56-cdbf-4817-bc21-f724e86d4831","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Rewrite a three-level nested subquery as a chain of three CTEs. Compare readability.","type":"text"}],"id":"acbe9374-790c-40e5-aca3-a0770360a35e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Write a CTE that deduplicates a table using ROW_NUMBER(), then a second CTE that aggregates the clean data.","type":"text"}],"id":"7ce42637-a745-4c5a-92d5-dc52d2009462","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Write a CTE chain where the same Draft Tray CTE is referenced by two different Revision Trays, each computing a different metric.","type":"text"}],"id":"3e75cf97-ba5f-41db-9195-c2581c07f5f2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Explain out loud: \"Why would you use a CTE instead of a subquery?\" Practice giving the three-word answer: readability, reuse, debugging — then expand each to one sentence.","type":"text"}],"id":"9dd93c08-010c-4267-a647-1d1e3cab6347","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"id":"55e54b6c-9ded-469f-ac26-bd012d7f6d75","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Final Integrated Coding Example","type":"text"}],"id":"65b3ad14-3547-414c-95b5-2ddebd624daf","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Scenario:","type":"text"},{"styles":{},"text":" You have a ","type":"text"},{"styles":{"code":true},"text":"transactions","type":"text"},{"styles":{},"text":" table. You need to clean it, deduplicate it, compute per-customer monthly spending, flag high-value customers, and produce a final ranked summary.","type":"text"}],"id":"29ae0cfe-48d6-446f-be41-be96b25adc83","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"-- =============================================================\n-- MULTI-STEP DESK: Customer Monthly Spending Summary\n-- =============================================================\n\n-- DRAFT TRAY: clean and filter raw transactions\nWITH clean_transactions AS (\n    SELECT\n        transaction_id,\n        customer_id,\n        UPPER(TRIM(region))                         AS region,\n        DATE_TRUNC(''month'', transaction_date)       AS txn_month,\n        COALESCE(amount, 0)                         AS amount\n    FROM transactions\n    WHERE status = ''confirmed''\n      AND transaction_date IS NOT NULL\n),\n\n-- REVISION TRAY 1: deduplicate (keep one row per transaction_id)\ndeduped_transactions AS (\n    SELECT\n        *,\n        ROW_NUMBER() OVER (\n            PARTITION BY transaction_id\n            ORDER BY amount DESC\n        ) AS rn\n    FROM clean_transactions\n),\n\n-- REVISION TRAY 2: aggregate monthly spending per customer per region\nmonthly_spending AS (\n    SELECT\n        customer_id,\n        region,\n        txn_month,\n        SUM(amount)   AS total_spent,\n        COUNT(*)      AS txn_count\n    FROM deduped_transactions\n    WHERE rn = 1                                   -- keep deduplicated rows only\n    GROUP BY customer_id, region, txn_month\n),\n\n-- REVISION TRAY 3: flag and rank customers by spending within each region and month\nranked_customers AS (\n    SELECT\n        customer_id,\n        region,\n        txn_month,\n        total_spent,\n        txn_count,\n        CASE\n            WHEN total_spent >= 5000 THEN ''high''\n            WHEN total_spent >= 1000 THEN ''medium''\n            ELSE                          ''low''\n        END AS spending_tier,\n        RANK() OVER (\n            PARTITION BY region, txn_month\n            ORDER BY total_spent DESC\n        ) AS spending_rank\n    FROM monthly_spending\n)\n\n-- =============================================================\n-- FINAL SELECT: top 5 spenders per region per month\n-- =============================================================\nSELECT\n    region,\n    txn_month,\n    customer_id,\n    total_spent,\n    txn_count,\n    spending_tier,\n    spending_rank\nFROM ranked_customers\nWHERE spending_rank <= 5\nORDER BY region, txn_month, spending_rank;","type":"text"}],"id":"2a94faeb-4034-4f0c-9cbc-0dc73863d123","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"What each concept is doing in this script:","type":"text"}],"id":"1b022f89-5ed9-4d41-a4cd-1b8fd0b6a749","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Concept","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Where it appears","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"WITH — Shortcut Panel","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Opens the desk at ","type":"text"},{"styles":{"code":true},"text":"clean_transactions","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Draft Tray","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"code":true},"text":"clean_transactions","type":"text"},{"styles":{},"text":": filters, cleans, normalizes raw data","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Revision Tray 1","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"code":true},"text":"deduped_transactions","type":"text"},{"styles":{},"text":": builds on Draft Tray, adds ROW_NUMBER()","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Revision Tray 2","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"code":true},"text":"monthly_spending","type":"text"},{"styles":{},"text":": builds on Revision Tray 1, aggregates","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Revision Tray 3","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"code":true},"text":"ranked_customers","type":"text"},{"styles":{},"text":": builds on Revision Tray 2, ranks and flags","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Clean Workflow Board","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Each step is named, readable, and debuggable in isolation","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"CTE used for aggregation","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"code":true},"text":"monthly_spending","type":"text"},{"styles":{},"text":" uses GROUP BY + SUM + COUNT","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"CTE building on another","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Every tray reads from the tray before it","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Final SELECT","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Reads from ","type":"text"},{"styles":{"code":true},"text":"ranked_customers","type":"text"},{"styles":{},"text":", applies the top-N filter","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Simple output","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Ordered by region, month, rank","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"d4e8bdde-efc7-4477-a7f8-b81b80bb1c09","props":{"textColor":"default"},"type":"table"},{"children":[],"id":"f98ac3e9-d14d-46c9-91db-1b4a7ae54c0d","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"italic":true},"text":"This note is scoped exclusively to internship-level CTE readiness for Topic 3. Do not add to it. Use it as written.","type":"text"}],"id":"18a22421-3abd-4357-9e4d-b268cc7a4c39","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[],"id":"ef197ab5-a640-4c0a-8aa8-1f0f3ba26718","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"}]'::jsonb, '3e9e3dd3-a59b-4b02-968a-ee95e7317583') ON CONFLICT ("node_id") DO UPDATE SET "bad_example" = EXCLUDED."bad_example", "completed_at" = EXCLUDED."completed_at", "created_at" = EXCLUDED."created_at", "definition" = EXCLUDED."definition", "good_example" = EXCLUDED."good_example", "is_completed" = EXCLUDED."is_completed", "key_points" = EXCLUDED."key_points", "last_edited" = EXCLUDED."last_edited", "map_id" = EXCLUDED."map_id", "mental_model" = EXCLUDED."mental_model", "notes" = EXCLUDED."notes", "resources" = EXCLUDED."resources", "rich_content" = EXCLUDED."rich_content", "user_id" = EXCLUDED."user_id";
INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-06-14T07:25:17.007622+00:00', '', '', 'b64e6846-705a-43e8-8f7c-bddc111f17c5', false, '[]'::jsonb, '2026-06-14T07:25:19.105+00:00', '2ad473fe-77dd-481e-8ba7-4b2b0336173f', '', 'b7ec3abd-6362-46aa-8d4a-c16ccdcbd7c1', '', '[]'::jsonb, '[{"children":[],"content":[{"styles":{},"text":"SQL for Data Engineering — Internship Study Note","type":"text"}],"id":"cce110a7-ae8a-4a88-a22a-8e402d897e97","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Topic 10: The Upsert Desk","type":"text"}],"id":"4906f6ee-2c56-45d8-9468-2a0892de1253","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"id":"19981139-00f4-4525-9720-53198989e0ca","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"What This Note Is","type":"text"}],"id":"c95a323d-eaf1-478a-977a-d7d556c9fc71","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Inside the Control Room, the ","type":"text"},{"styles":{"bold":true},"text":"Upsert Desk","type":"text"},{"styles":{},"text":" is the station that ensures data loads can be run repeatedly without breaking. When new data arrives, the Conflict Bell (","type":"text"},{"styles":{"code":true},"text":"ON CONFLICT","type":"text"},{"styles":{},"text":") detects rows that already exist based on a unique key. The Fix Lever (","type":"text"},{"styles":{"code":true},"text":"DO UPDATE","type":"text"},{"styles":{},"text":") updates the existing row instead of failing. This makes the load Safe to Re-run — no matter how many times you execute it, the result is the same. This is idempotency. An internship interviewer will expect you to know how to write a load script that does not crash or create duplicates when it runs a second time.","type":"text"}],"id":"b5fe7a45-8691-4187-a47a-e6d5e6e690f4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"3e16cfe1-d340-4c26-94d4-6a0448c4ef30","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Mind Map","type":"text"}],"id":"afa7c47c-4257-4463-b7dd-c80625bf0238","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"                          THE UPSERT DESK\n                        (Idempotent Load)\n                               │\n          ┌────────────────────┼────────────────────┐\n          │                    │                    │\n    SAFE RE-RUN           CONFLICT BELL          FIX LEVER\n   (Idempotency)          ON CONFLICT            DO UPDATE\n          │                    │                    │\n  Running the script     Detects when a       What to do when\n  multiple times         row with the same    conflict is detected\n  produces the same      unique key already       │\n  final state            exists               ┌───┴───┐\n          │                    │              │       │\n    ┌─────┴─────┐         Based on:      DO NOTHING  DO UPDATE SET\n    │           │         PRIMARY KEY    (skip row)  (overwrite)\n  First run  Second run   or UNIQUE\n  inserts    updates      constraint\n  100 rows   same 100\n             (no dupes)\n\n          │\n          └──── Why it matters ──────────────────────┐\n                                                     │\n                     Data pipelines rerun on failure.\n                     Without idempotency:\n                     - Duplicates are created\n                     - Script crashes on unique key violation\n                     - You cannot safely retry","type":"text"}],"id":"c55af0f9-4987-4a15-baa3-e06635881247","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"459df8f9-c46e-46cf-bcd0-f62973982d55","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Decision Tree","type":"text"}],"id":"794bbc60-c1c1-4fd5-bd5f-631cd9818404","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"START: You need to load data into a table\n          │\n          ▼\nCould this script run more than once?\n    NO  → Simple INSERT is acceptable (rare in real pipelines)\n    YES → Continue\n          │\n          ▼\nDoes the table have a PRIMARY KEY or UNIQUE constraint?\n    NO  → You cannot use ON CONFLICT (need a unique key first)\n    YES → Continue\n          │\n          ▼\nWhat should happen when a row with the same key already exists?\n    │\n    ├─ Ignore the new row (keep the old one)\n    │      → INSERT ... ON CONFLICT DO NOTHING\n    │\n    └─ Update the existing row with new values\n           → INSERT ... ON CONFLICT DO UPDATE SET ...\n          │\n          ▼\nIs this a PostgreSQL / SQLite environment?\n    YES → Use INSERT ... ON CONFLICT (this note''s scope)\n    NO  → Other dialects:\n          - MySQL: INSERT ... ON DUPLICATE KEY UPDATE\n          - SQL Server: MERGE\n          (Out of internship scope — flag and research if needed)\n          │\n          ▼\nDoes your final script pass this test?\n    \"If I run this script twice on the same data, does the table\n     still have the same row count and values as after the first run?\"\n    YES → Idempotent (Safe Re-run achieved)\n    NO  → Fix it using ON CONFLICT","type":"text"}],"id":"8af91032-5aea-4de5-8081-3d7af0fdc740","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"0871c7ce-8d8d-44f3-ac7c-e0c38416b5cf","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Concept Breakdown","type":"text"}],"id":"9c25f7b8-a3ac-4c2b-9b51-270af58a7c81","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"id":"8112918b-22f4-4097-892d-88d6dcc789a8","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"1. What Idempotency Means","type":"text"}],"id":"74aa4ea3-20db-435f-8f0a-a9ba3f57d318","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" A script is ","type":"text"},{"styles":{"bold":true},"text":"idempotent","type":"text"},{"styles":{},"text":" if running it multiple times produces the same final state as running it once. No duplicates are created. No errors are raised. The result is predictable and safe to retry.","type":"text"}],"id":"d1abd9f5-4459-41b1-9a77-93dbf0469668","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters:","type":"text"},{"styles":{},"text":" Data pipelines fail and retry. If your load script is not idempotent, every retry creates duplicate rows or crashes the job. Interviewers ask: ","type":"text"},{"styles":{"italic":true},"text":"\"What happens if this script runs twice?\"","type":"text"},{"styles":{},"text":" The correct answer is: ","type":"text"},{"styles":{"italic":true},"text":"\"It should be safe — the second run should not change the result.\"","type":"text"}],"id":"b110c88c-4fe9-43f2-bf9b-a2257b15db4a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example (conceptual):","type":"text"}],"id":"9780fa21-3c3e-47b8-89ec-e4dcb5ca832b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"-- Non-idempotent: running twice creates duplicates\nINSERT INTO users (user_id, name) VALUES (1, ''Alice'');\n-- Run 1: inserts Alice\n-- Run 2: crashes (user_id = 1 already exists)\n\n-- Idempotent: running twice produces the same result\nINSERT INTO users (user_id, name)\nVALUES (1, ''Alice'')\nON CONFLICT (user_id) DO NOTHING;\n-- Run 1: inserts Alice\n-- Run 2: detects conflict, does nothing, no crash, no duplicate","type":"text"}],"id":"82a84b93-11d0-4700-93cf-c70de2bccd9b","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"id":"dfd301bc-c155-4aaa-a987-94802df5fc2f","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"2. Why Repeated Runs Must Not Create Duplicates","type":"text"}],"id":"75a751e8-b01b-4098-844f-360840afd7a5","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" In production, pipelines retry on failure. If the script partially completes (loads 50 out of 100 rows, then crashes), the retry must not insert the same 50 rows again. It must either skip them or update them.","type":"text"}],"id":"abd0f9fb-4de7-4497-85a7-138cbda4feb5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters:","type":"text"},{"styles":{},"text":" This is one of the first real-world data quality problems an intern encounters. Duplicate rows break aggregations, metrics, and downstream reports. Interviewers test whether you know how to prevent this.","type":"text"}],"id":"b81d4f41-e456-4b79-bf05-989707ae754b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"918e205e-3607-484f-93dd-8fe02e8e9e37","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"-- DANGEROUS: naive INSERT with no conflict handling\nINSERT INTO daily_revenue (date, amount)\nSELECT ''2024-01-15'', 10000;\n-- First run: inserts 1 row\n-- Second run: inserts another row with the same date → 2 rows total (WRONG)\n\n-- SAFE: idempotent INSERT\nINSERT INTO daily_revenue (date, amount)\nVALUES (''2024-01-15'', 10000)\nON CONFLICT (date) DO UPDATE SET amount = EXCLUDED.amount;\n-- First run: inserts 1 row\n-- Second run: updates the existing row → still 1 row total (CORRECT)","type":"text"}],"id":"3c617a7b-97d0-441f-9726-eaf59c00049e","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"id":"ddc8afa0-5577-4da1-8261-f2d993d02228","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"3. What INSERT ... ON CONFLICT Does","type":"text"}],"id":"d74a1129-ccee-4a40-b751-42c5a8e4665a","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" ","type":"text"},{"styles":{"code":true},"text":"INSERT ... ON CONFLICT","type":"text"},{"styles":{},"text":" is a PostgreSQL (and SQLite) feature that detects when an inserted row would violate a UNIQUE or PRIMARY KEY constraint. Instead of crashing, it triggers the Conflict Bell and lets you decide what to do.","type":"text"}],"id":"344a5ee0-00c6-4cc8-ae1d-499e13eda3f6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Syntax:","type":"text"}],"id":"d846300d-b482-4787-ac96-7a1f7b3f2d07","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"INSERT INTO table_name (columns)\nVALUES (values)\nON CONFLICT (unique_column) DO ...;","type":"text"}],"id":"3b70f30c-591c-4ec6-8714-85be2b8d4ac0","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"The conflict is detected on the column(s) specified in parentheses — this column must have a UNIQUE or PRIMARY KEY constraint.","type":"text"}],"id":"aa21fd0a-782e-4d3f-b2b9-fe1c2b78e75d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters:","type":"text"},{"styles":{},"text":" This is the foundation of idempotent loads in PostgreSQL. Interviewers expect you to know this syntax and when to use it.","type":"text"}],"id":"55389dd0-601e-40b0-b49b-2b233eb411d3","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"b4531eb6-6242-4f6b-aa6f-8544bddce160","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"-- Table has PRIMARY KEY on user_id\nINSERT INTO users (user_id, name, email)\nVALUES (1, ''Alice'', ''alice@example.com'')\nON CONFLICT (user_id) DO NOTHING;\n-- If user_id = 1 exists, skip the insert\n-- If user_id = 1 does not exist, insert normally","type":"text"}],"id":"e102db1e-6467-46b4-9110-4fb3a4c218fa","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"id":"fe8320db-d0c7-4bf9-bcb7-15307a3e3f72","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"4. What DO UPDATE Does","type":"text"}],"id":"752ff1d1-fa83-4cb2-a17e-b4ed1f1bc87d","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" ","type":"text"},{"styles":{"code":true},"text":"DO UPDATE SET column = value","type":"text"},{"styles":{},"text":" is the Fix Lever. When a conflict is detected, instead of skipping the row, it updates the existing row with new values.","type":"text"}],"id":"92f77f9b-f6a0-4d1d-9ede-341515bfc0e1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"You can reference the new values using the special keyword ","type":"text"},{"styles":{"code":true},"text":"EXCLUDED","type":"text"},{"styles":{},"text":", which represents the row you tried to insert.","type":"text"}],"id":"39b2c9ca-5137-4984-a84a-ce2d9c87bbb4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Syntax:","type":"text"}],"id":"c8d6e45d-2f43-4167-82d1-63352519503d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"ON CONFLICT (unique_column)\nDO UPDATE SET\n    column1 = EXCLUDED.column1,\n    column2 = EXCLUDED.column2;","type":"text"}],"id":"bde7eab7-aab3-45f2-975f-fa9f8015f713","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters:","type":"text"},{"styles":{},"text":" This is the most common idempotent pattern in data engineering: \"insert if new, update if exists.\" Interviewers will ask you to write this.","type":"text"}],"id":"f3140560-54be-4feb-a266-81ef46980aad","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"73f8a248-07a3-46f5-9202-7e29e31bf042","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"INSERT INTO users (user_id, name, email, updated_at)\nVALUES (1, ''Alice'', ''alice@newdomain.com'', CURRENT_TIMESTAMP)\nON CONFLICT (user_id)\nDO UPDATE SET\n    name       = EXCLUDED.name,\n    email      = EXCLUDED.email,\n    updated_at = EXCLUDED.updated_at;\n-- If user_id = 1 exists, update name, email, and updated_at\n-- If user_id = 1 does not exist, insert new row","type":"text"}],"id":"676b93e3-d1ab-464e-b9e5-3ff27ec81170","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"id":"d4ea39c7-f247-4be2-af5c-132eb3d576da","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"5. Short Example — Inserting Safely (DO NOTHING)","type":"text"}],"id":"40536cb1-ac04-4f92-b038-e6141f791daf","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" Use ","type":"text"},{"styles":{"code":true},"text":"ON CONFLICT ... DO NOTHING","type":"text"},{"styles":{},"text":" when you want to preserve the existing row and skip the new one if a conflict occurs.","type":"text"}],"id":"b9332759-5f98-4ef9-8dda-41c0e72f0401","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters:","type":"text"},{"styles":{},"text":" Common in append-only logs or when the first write wins and later writes should be ignored.","type":"text"}],"id":"30448b5f-d9f8-4389-885b-285b92377421","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"fe279bdd-5a71-4501-9f6f-26a5ee472d7a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"-- Load daily revenue; if date already exists, skip\nINSERT INTO daily_revenue (date, amount)\nVALUES (''2024-01-15'', 10000)\nON CONFLICT (date) DO NOTHING;\n-- Idempotent: running this 5 times still results in 1 row","type":"text"}],"id":"cf665461-74c3-428a-9173-659f98970c57","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"id":"480de9d9-1481-4920-9169-df44819065fd","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"6. Short Example — Updating on Conflict (DO UPDATE)","type":"text"}],"id":"33a9cea3-6282-4e30-9370-02a03a0385f8","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" Use ","type":"text"},{"styles":{"code":true},"text":"ON CONFLICT ... DO UPDATE","type":"text"},{"styles":{},"text":" when the new data should overwrite the old data if a conflict occurs.","type":"text"}],"id":"dfbd0ce8-fd86-4e88-b4d1-4ca2912b5bbc","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters:","type":"text"},{"styles":{},"text":" Most common in dimension tables, user profiles, or daily snapshots where the latest value is the correct one.","type":"text"}],"id":"41865cf3-0d14-4792-8937-5037d7233b02","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"07205435-1937-43f0-a21d-5fdff05f3e99","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"-- Update user email if user_id already exists\nINSERT INTO users (user_id, email, last_login)\nVALUES (42, ''user42@example.com'', CURRENT_TIMESTAMP)\nON CONFLICT (user_id)\nDO UPDATE SET\n    email      = EXCLUDED.email,\n    last_login = EXCLUDED.last_login;\n-- Idempotent: running this script updates the same row each time","type":"text"}],"id":"5de1c244-2e93-49aa-aa60-b40fe180c72d","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"id":"b7f7cc07-ac62-41ff-8a8a-d2921c84f883","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"7. Short Example — Why Naive INSERT Fails on Rerun","type":"text"}],"id":"c1721766-1802-4a4a-97d6-ce9675338026","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" A plain INSERT without ON CONFLICT will crash on the second run if the row already exists.","type":"text"}],"id":"545b8357-acc6-44d3-8bc1-566bf76be4eb","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters:","type":"text"},{"styles":{},"text":" This is the \"broken before\" example that every intern needs to see to understand why ON CONFLICT exists.","type":"text"}],"id":"a8e4725c-8731-405d-a870-753127e7df45","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"87d1bd3f-48ce-4e70-94d4-f65f5a6da9f9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"-- Attempt 1: succeeds\nINSERT INTO products (product_id, name, price)\nVALUES (101, ''Widget'', 19.99);\n\n-- Attempt 2: crashes\nINSERT INTO products (product_id, name, price)\nVALUES (101, ''Widget'', 19.99);\n-- ERROR: duplicate key value violates unique constraint \"products_pkey\"\n\n-- Fixed with ON CONFLICT:\nINSERT INTO products (product_id, name, price)\nVALUES (101, ''Widget'', 19.99)\nON CONFLICT (product_id) DO NOTHING;\n-- Attempt 2: succeeds silently, no duplicate, no crash","type":"text"}],"id":"4368f87b-3c4e-4e77-9638-b571295c9786","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"id":"41b3e0d9-81c3-4054-8265-31f29501eedf","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Common Mistakes","type":"text"}],"id":"5e414660-c8be-4954-bd25-b168ce4546c8","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":{"columnWidths":[null,null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Mistake","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Why It Is Wrong","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Fix","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Using ON CONFLICT without a unique constraint","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Query fails — ON CONFLICT requires a UNIQUE or PRIMARY KEY","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Add a unique constraint first","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Writing ON CONFLICT on a column with no constraint","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Syntax error or runtime error","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Specify the column that has the constraint","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Forgetting to use EXCLUDED in DO UPDATE","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Updates with literal values or NULL instead of the new row''s values","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Use ","type":"text"},{"styles":{"code":true},"text":"EXCLUDED.column_name","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Using DO UPDATE but not updating anything","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Functionally identical to DO NOTHING but misleading","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Use DO NOTHING if no update is needed","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Assuming INSERT ... ON CONFLICT works in all SQL dialects","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"PostgreSQL and SQLite only; MySQL and SQL Server use different syntax","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Know your dialect; research MERGE or ON DUPLICATE KEY UPDATE if needed","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Not testing the rerun","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Script appears to work on first run but crashes or duplicates on second","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Always test: run the script twice and verify row count","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Updating only some columns in DO UPDATE","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Other columns retain old values when you may want them updated","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Explicitly list all columns that should be refreshed","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"080226e2-794a-486b-bd3d-d23234b6c354","props":{"textColor":"default"},"type":"table"},{"children":[],"id":"1ced0dfb-829d-441a-afc7-dfad2394acf7","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Practice Ideas","type":"text"}],"id":"93037d99-94ce-477a-8d7a-2eb7cfd3033a","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"These are sized for an interview whiteboard or a 20-minute coding task.","type":"text"}],"id":"ad439fe9-f796-4867-99c0-9ad5b32e9d71","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Write an INSERT script that loads a user row. Make it idempotent using ON CONFLICT DO NOTHING.","type":"text"}],"id":"25727e7c-7cae-407a-b707-9da7960a988e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Write an INSERT script that loads a product row. Make it idempotent using ON CONFLICT DO UPDATE to refresh the price.","type":"text"}],"id":"3b970112-62ff-4f3b-bfef-047fbc0f03a5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Run a naive INSERT twice on a table with a primary key. Show that it crashes. Then fix it with ON CONFLICT.","type":"text"}],"id":"adfd2240-aeb6-41d7-a685-4d6113e75d46","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Explain out loud: ","type":"text"},{"styles":{"italic":true},"text":"\"What does idempotency mean in the context of a data load?\"","type":"text"},{"styles":{},"text":" Practice this in two sentences.","type":"text"}],"id":"770fc933-a0d7-4755-9598-a48606dfb7f3","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Write a script that loads daily metrics. Use ON CONFLICT to ensure running it twice on the same day does not create duplicates.","type":"text"}],"id":"5c782191-0a0c-40dc-bf55-6025343e33ec","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Debug a script where ON CONFLICT is used but EXCLUDED is missing in the DO UPDATE clause. Explain why the update does not work.","type":"text"}],"id":"f97263e5-7cc0-48ba-834a-ce44996e0c7c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"id":"0843b4d6-9f98-4aff-87db-374a3b026fce","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Final Integrated Coding Example","type":"text"}],"id":"411e3a58-d407-468b-8e8e-5ed1cb9413ae","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Scenario:","type":"text"},{"styles":{},"text":" You are loading a ","type":"text"},{"styles":{"code":true},"text":"daily_metrics","type":"text"},{"styles":{},"text":" table from a source file. The table has a PRIMARY KEY on ","type":"text"},{"styles":{"code":true},"text":"(metric_date, region)","type":"text"},{"styles":{},"text":". You need to write a load script that:","type":"text"}],"id":"46e3dc18-e80f-4831-a555-0c7b23777aed","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Inserts new rows.","type":"text"}],"id":"61385686-a7b3-454f-87eb-3c508a3782b3","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Updates existing rows if the same date + region appears again.","type":"text"}],"id":"d7fc809c-d0e2-4e74-8f89-d69605034a31","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Can be run multiple times safely (idempotent).","type":"text"}],"id":"1a8ff8b2-c597-4858-9810-973b236c861c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"-- =============================================================\n-- UPSERT DESK: Idempotent Daily Metrics Load\n-- =============================================================\n\n-- Step 1: Create the target table with a composite primary key\nCREATE TABLE IF NOT EXISTS daily_metrics (\n    metric_date  DATE,\n    region       VARCHAR(50),\n    revenue      DECIMAL(10, 2),\n    orders       INT,\n    updated_at   TIMESTAMP,\n    PRIMARY KEY (metric_date, region)\n);\n\n-- =============================================================\n-- Step 2: Naive INSERT (breaks on rerun — shown for comparison)\n-- =============================================================\n/*\nINSERT INTO daily_metrics (metric_date, region, revenue, orders, updated_at)\nVALUES\n    (''2024-01-15'', ''US'', 15000.00, 120, CURRENT_TIMESTAMP),\n    (''2024-01-15'', ''EU'', 8000.00, 65, CURRENT_TIMESTAMP);\n\n-- First run: inserts 2 rows\n-- Second run: ERROR — duplicate key violation on (metric_date, region)\n*/\n\n-- =============================================================\n-- Step 3: Idempotent INSERT using ON CONFLICT (Safe Re-run)\n-- =============================================================\n\n-- Conflict Bell detects existing (metric_date, region) pair\n-- Fix Lever updates the row with new values using EXCLUDED keyword\n\nINSERT INTO daily_metrics (metric_date, region, revenue, orders, updated_at)\nVALUES\n    (''2024-01-15'', ''US'', 15000.00, 120, CURRENT_TIMESTAMP),\n    (''2024-01-15'', ''EU'', 8000.00, 65, CURRENT_TIMESTAMP),\n    (''2024-01-16'', ''US'', 16000.00, 130, CURRENT_TIMESTAMP)\n\nON CONFLICT (metric_date, region)        -- Conflict Bell rings\nDO UPDATE SET                            -- Fix Lever activates\n    revenue    = EXCLUDED.revenue,       -- Use the new revenue value\n    orders     = EXCLUDED.orders,        -- Use the new orders value\n    updated_at = EXCLUDED.updated_at;    -- Refresh the timestamp\n\n-- =============================================================\n-- Verification: Check the result\n-- =============================================================\n\nSELECT * FROM daily_metrics\nORDER BY metric_date, region;\n\n-- First run result:\n-- | metric_date | region | revenue  | orders | updated_at          |\n-- |-------------|--------|----------|--------|---------------------|\n-- | 2024-01-15  | EU     | 8000.00  | 65     | 2024-01-15 10:00:00 |\n-- | 2024-01-15  | US     | 15000.00 | 120    | 2024-01-15 10:00:00 |\n-- | 2024-01-16  | US     | 16000.00 | 130    | 2024-01-15 10:00:00 |\n\n-- Second run result (same script run again):\n-- | metric_date | region | revenue  | orders | updated_at          |\n-- |-------------|--------|----------|--------|---------------------|\n-- | 2024-01-15  | EU     | 8000.00  | 65     | 2024-01-15 10:05:00 | ← updated_at refreshed\n-- | 2024-01-15  | US     | 15000.00 | 120    | 2024-01-15 10:05:00 | ← updated_at refreshed\n-- | 2024-01-16  | US     | 16000.00 | 130    | 2024-01-15 10:05:00 | ← updated_at refreshed\n\n-- Same row count. Same data values. Different timestamp.\n-- This is idempotency: Safe Re-run achieved.","type":"text"}],"id":"7363829a-eb03-4a12-8de1-97d688150fad","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"What each concept is doing in this script:","type":"text"}],"id":"b61aa925-74aa-46f3-8e45-f30706b9ad68","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Concept","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Where it appears","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Idempotency (Safe Re-run)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Script can run multiple times; same final row count","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"PRIMARY KEY constraint","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"code":true},"text":"PRIMARY KEY (metric_date, region)","type":"text"},{"styles":{},"text":" enables conflict detection","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"ON CONFLICT (Conflict Bell)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Detects when ","type":"text"},{"styles":{"code":true},"text":"(metric_date, region)","type":"text"},{"styles":{},"text":" pair already exists","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"DO UPDATE (Fix Lever)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Updates existing rows instead of crashing or skipping","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"EXCLUDED keyword","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"References the new row''s values: ","type":"text"},{"styles":{"code":true},"text":"EXCLUDED.revenue","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"EXCLUDED.orders","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Naive INSERT failure","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Commented-out block shows what happens without ON CONFLICT","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Verification query","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"code":true},"text":"SELECT * FROM daily_metrics","type":"text"},{"styles":{},"text":" confirms idempotent behavior","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"1dfc8cff-698d-470b-b1c1-59e6f4c3de4b","props":{"textColor":"default"},"type":"table"},{"children":[],"content":[{"styles":{"bold":true},"text":"Interview talking points for this script:","type":"text"}],"id":"db0fd6d8-a147-49e5-b0fe-3afea67de07b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"\"The naive INSERT crashes on the second run because the primary key is violated.\"","type":"text"}],"id":"79a1c03c-b3ac-4976-a3d9-7f564677003c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"\"ON CONFLICT detects the duplicate and triggers DO UPDATE instead of failing.\"","type":"text"}],"id":"229ee600-70bb-449b-9115-7f99f3bb0480","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"\"EXCLUDED refers to the row I tried to insert — I use it to overwrite the old values.\"","type":"text"}],"id":"6404e382-18d1-42e2-b828-7c525b93257c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"\"Running this script 10 times produces the same final table as running it once — that is idempotency.\"","type":"text"}],"id":"5b47aca2-d758-48a6-ba3f-4d80c6aeaf0a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"\"Idempotency is critical in data pipelines because retries are common and duplicates break everything.\"","type":"text"}],"id":"a84245a1-7de7-424f-a24e-db27558629c5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"id":"9f6dde95-7e62-4bca-bd81-613c41cf614e","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"italic":true},"text":"This note is scoped exclusively to internship-level idempotent load / upsert readiness for Topic 10. Do not add to it. Use it as written.","type":"text"}],"id":"95348a74-7ce9-49c1-93fd-875986070417","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[],"id":"58fafeb1-779f-403a-a6f1-b8fa96ea158d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"}]'::jsonb, '3e9e3dd3-a59b-4b02-968a-ee95e7317583') ON CONFLICT ("node_id") DO UPDATE SET "bad_example" = EXCLUDED."bad_example", "completed_at" = EXCLUDED."completed_at", "created_at" = EXCLUDED."created_at", "definition" = EXCLUDED."definition", "good_example" = EXCLUDED."good_example", "is_completed" = EXCLUDED."is_completed", "key_points" = EXCLUDED."key_points", "last_edited" = EXCLUDED."last_edited", "map_id" = EXCLUDED."map_id", "mental_model" = EXCLUDED."mental_model", "notes" = EXCLUDED."notes", "resources" = EXCLUDED."resources", "rich_content" = EXCLUDED."rich_content", "user_id" = EXCLUDED."user_id";
