INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-08-05T04:05:17.615048+00:00', '', '', '7785e470-12ef-4393-a42f-75d7aa767a82', false, '[]'::jsonb, '2026-08-30T04:54:12.193+00:00', '2ad473fe-77dd-481e-8ba7-4b2b0336173f', '', '6cb16f92-43b4-44a6-86b6-26d4cac6ae3f', '', '[]'::jsonb, '[{"children":[],"content":[{"styles":{},"text":"📘 THE EXTRACT BRANCH — Complete Study Note for Data Engineering Interviews","type":"text"}],"id":"a0630d01-1dae-418c-ac1e-83331bba4107","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"id":"993feebe-477a-4cb5-9893-ace64e6a115b","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"🎯 What \"Extract\" Actually Means (Read This First)","type":"text"}],"id":"5b818e84-9ecb-4cfb-9f0d-5466afae8d99","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Extract = getting raw data OUT of a source system and INTO your pipeline, safely and reliably.","type":"text"}],"id":"b57919b0-4155-4b53-8bcc-123b8eeda1cc","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Sources can be:","type":"text"}],"id":"a8c6dd73-90c5-4bc6-9ca6-a4ea0dbc0975","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Files","type":"text"},{"styles":{},"text":" (CSV, JSON, sometimes XML/Parquet)","type":"text"}],"id":"8c439f46-0c60-426c-8838-75ccdde30acc","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"APIs","type":"text"},{"styles":{},"text":" (REST endpoints returning JSON)","type":"text"}],"id":"7ba170ee-e381-4ec7-8c89-a68559bb0933","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Databases","type":"text"},{"styles":{},"text":" (SQL queries against another system)","type":"text"}],"id":"ba61f2c3-d308-4d37-8eb5-dc3a104e0608","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"The ","type":"text"},{"styles":{"bold":true},"text":"core challenge","type":"text"},{"styles":{},"text":" interviewers care about isn''t \"can you open a file\" — it''s:","type":"text"}],"id":"c7f7f9ce-f753-491d-abf3-5af8d18bac53","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Can you handle ","type":"text"},{"styles":{"bold":true},"text":"large data without crashing memory","type":"text"},{"styles":{},"text":"?","type":"text"}],"id":"479ace6a-24fc-4e87-8ab8-ecce504bd449","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Can you handle ","type":"text"},{"styles":{"bold":true},"text":"messy/broken data","type":"text"},{"styles":{},"text":" without crashing the script?","type":"text"}],"id":"dd71be03-aceb-465c-bebc-61665a0437d5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Can you handle ","type":"text"},{"styles":{"bold":true},"text":"unreliable sources","type":"text"},{"styles":{},"text":" (slow APIs, rate limits, network failures)?","type":"text"}],"id":"b27194db-c169-452a-9a74-6a4d2b3afae4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Can you write ","type":"text"},{"styles":{"bold":true},"text":"reusable, testable extraction code","type":"text"},{"styles":{},"text":", not one-off scripts?","type":"text"}],"id":"e0f51b28-3ef7-4d35-a27c-d7800f3cd0ce","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Every concept below exists to solve one of these four problems. Keep that in mind — it''s what makes this \"connected\" instead of random facts.","type":"text"}],"id":"0f13679f-c689-4ca9-88f1-1c79705f6033","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"77148a85-c812-4762-90eb-73736adb7cca","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"SECTION 1 — Reading CSV Files (The Foundation)","type":"text"}],"id":"39b7f344-9e21-4e3e-9e83-2eccd57752e9","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Why it matters","type":"text"}],"id":"8a8708d5-e7d1-4405-bab3-3432d2c14b9d","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"CSV is the most common interview format because it''s simple to generate and forces you to think about parsing, types, and errors.","type":"text"}],"id":"ff484a65-22f3-4c5c-af4f-5f3e3d091e35","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"The naive way (what beginners do)","type":"text"}],"id":"fceaad81-49a7-46fe-b55d-9bc43dd45fcd","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"import csv\n\ndef read_csv_naive(filepath):\n    with open(filepath, ''r'') as f:\n        reader = csv.reader(f)\n        header = next(reader)\n        data = []\n        for row in reader:\n            data.append(row)\n    return data","type":"text"}],"id":"904c858e-2ad2-4840-a4ba-afc17d5b370d","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Problem:","type":"text"},{"styles":{},"text":" loads everything into a list in memory. Fine for small files, fails for large ones (interviewers will ask \"what if this file is 10GB?\").","type":"text"}],"id":"76b49513-c16b-4824-85f3-bd226b5b65b8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"The better way — ","type":"text"},{"styles":{"code":true},"text":"csv.DictReader","type":"text"}],"id":"a2e9d03a-9cec-4b7b-a2b0-67791198a669","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"import csv\n\ndef read_csv_as_dicts(filepath):\n    with open(filepath, ''r'', newline='''', encoding=''utf-8'') as f:\n        reader = csv.DictReader(f)\n        for row in reader:\n            yield row   # <-- generator, explained in Section 3","type":"text"}],"id":"343e1bbe-f47b-4269-b10f-57e28bd0cc77","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why DictReader:","type":"text"},{"styles":{},"text":" gives you ","type":"text"},{"styles":{"code":true},"text":"{''name'': ''John'', ''amount'': ''250''}","type":"text"},{"styles":{},"text":" instead of ","type":"text"},{"styles":{"code":true},"text":"[''John'', ''250'']","type":"text"},{"styles":{},"text":" — column-name access is safer and more realistic (mirrors how you''d handle real tables).","type":"text"}],"id":"93e95e43-c041-4702-a789-5dfd747d2feb","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Key gotchas interviewers test","type":"text"}],"id":"b4965d2e-3ee3-41e8-92e4-e8d800e655df","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":{"columnWidths":[null,null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Gotcha","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Why it matters","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Fix","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Everything read as ","type":"text"},{"styles":{"bold":true},"text":"string","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"code":true},"text":"''250''","type":"text"},{"styles":{},"text":" isn''t ","type":"text"},{"styles":{"code":true},"text":"250","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"manually cast: ","type":"text"},{"styles":{"code":true},"text":"int(row[''amount''])","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Missing values (","type":"text"},{"styles":{"code":true},"text":"''''","type":"text"},{"styles":{},"text":")","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"crashes ","type":"text"},{"styles":{"code":true},"text":"int('''')","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"check before casting: ","type":"text"},{"styles":{"code":true},"text":"int(row[''amount'']) if row[''amount''] else 0","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Different encodings","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"code":true},"text":"UnicodeDecodeError","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"specify ","type":"text"},{"styles":{"code":true},"text":"encoding=''utf-8''","type":"text"},{"styles":{},"text":" or ","type":"text"},{"styles":{"code":true},"text":"''latin-1''","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Extra/missing columns","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"code":true},"text":"DictReader","type":"text"},{"styles":{},"text":" fills missing with ","type":"text"},{"styles":{"code":true},"text":"None","type":"text"},{"styles":{},"text":", extra go into a ","type":"text"},{"styles":{"code":true},"text":"None","type":"text"},{"styles":{},"text":" key","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"validate row length","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Different delimiters (","type":"text"},{"styles":{"code":true},"text":";","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"\\t","type":"text"},{"styles":{},"text":")","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"breaks default parser","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"code":true},"text":"csv.reader(f, delimiter='';'')","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"feb7537a-8107-4ecc-a94e-bc19d23c846c","props":{"textColor":"default"},"type":"table"},{"children":[],"content":[{"styles":{},"text":"Practice Exercise 1","type":"text"}],"id":"a236504e-2695-4cd9-bf0b-37f8bb2bb07a","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"file\n#\n# Write a generator that yields cleaned dicts:\n# - amount defaults to 0.0 if missing\n# - skip rows where date is missing, but log a warning","type":"text"}],"id":"eea4edbf-5a7e-42ca-8f1f-fe233eb8cec9","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"8add16e2-2156-4b08-96f9-502b1ab1794e","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"SECTION 2 — Reading & Flattening JSON","type":"text"}],"id":"20554234-e435-47c0-9c5c-aa17ba03d2cb","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Why it matters","type":"text"}],"id":"29919cfe-3e64-4e2d-ac04-633cbc94e717","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Real-world APIs and NoSQL exports return ","type":"text"},{"styles":{"bold":true},"text":"nested JSON","type":"text"},{"styles":{},"text":", not flat tables. You must flatten it before it can go into rows/dataframes/SQL tables.","type":"text"}],"id":"d691f842-2a80-4eb6-8cc6-8b27c1b6097c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Basic JSON reading","type":"text"}],"id":"680b1035-f14a-41f6-bb6f-4b1031c91c5d","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"import json\n\ndef read_json_file(filepath):\n    with open(filepath, ''r'') as f:\n        data = json.load(f)   # loads entire file into memory (a dict or list)\n    return data","type":"text"}],"id":"37f10241-3cb4-4275-a8fc-15717f788939","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Reading JSON Lines (JSONL) — very common in real DE work","type":"text"}],"id":"29e70ad5-59d1-4d37-be5a-fb090bcc65ec","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Each line is its own JSON object — this format is memory-friendly because you can process line-by-line.","type":"text"}],"id":"4dc1eb1b-4ced-408c-93af-a7a75c113943","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"def read_jsonl(filepath):\n    with open(filepath, ''r'') as f:\n        for line in f:\n            yield json.loads(line)","type":"text"}],"id":"1b7dcc81-3cf5-4972-89b6-355f90851893","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"The Big Skill: Flattening Nested JSON","type":"text"}],"id":"ea057275-39bc-4df3-a311-69dc00df8a70","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Example input:","type":"text"}],"id":"d39fce1c-02ab-477f-9297-546ee57b590c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"{\n  \"id\": 1,\n  \"name\": \"Alice\",\n  \"address\": {\"city\": \"Chennai\", \"zip\": \"600001\"},\n  \"orders\": [{\"item\": \"Book\", \"price\": 10}, {\"item\": \"Pen\", \"price\": 2}]\n}","type":"text"}],"id":"3955221d-19b1-4f29-a8a1-fc1dd398b971","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Flattening dicts (recursive function — a classic interview ask):","type":"text"}],"id":"63164e03-a3e6-4bad-a014-1283bbd05c81","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"def flatten_dict(d, parent_key='''', sep=''_''):\n    items = {}\n    for k, v in d.items():\n        new_key = f\"{parent_key}{sep}{k}\" if parent_key else k\n        if isinstance(v, dict):\n            items.update(flatten_dict(v, new_key, sep=sep))\n        elif isinstance(v, list):\n            # Lists need special handling - often you''d explode these into separate rows\n            items[new_key] = v  # keep as-is, or handle separately (see below)\n        else:\n            items[new_key] = v\n    return items\n\n# Result: {\"id\": 1, \"name\": \"Alice\", \"address_city\": \"Chennai\", \"address_zip\": \"600001\", \"orders\": [...]}","type":"text"}],"id":"45a98da1-46b8-4406-8140-b9b1213a0086","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Handling nested lists (exploding into multiple rows):","type":"text"}],"id":"fe593c3d-b118-49b8-8d02-d77c693e7614","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"def explode_orders(record):\n    \"\"\"One customer record with N orders -> N flat rows\"\"\"\n    base = {k: v for k, v in record.items() if k != ''orders''}\n    rows = []\n    for order in record.get(''orders'', []):\n        row = {**base, **order}   # merge customer info + order info\n        rows.append(row)\n    return rows\n\n# Input: 1 customer with 2 orders\n# Output: 2 rows, each with customer info repeated + one order''s info","type":"text"}],"id":"1d117f39-7925-43bb-974e-76b79afa644b","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"This \"explode\" pattern is ","type":"text"},{"styles":{"bold":true},"text":"extremely common","type":"text"},{"styles":{},"text":" — it''s exactly what ","type":"text"},{"styles":{"code":true},"text":"pandas.json_normalize()","type":"text"},{"styles":{},"text":" does under the hood, and interviewers love asking you to do it manually to test real understanding.","type":"text"}],"id":"798f2209-d5e4-43dd-a460-967fde8011a4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Practice Exercise 2","type":"text"}],"id":"4269ccd7-63ea-4eaa-8b98-31ecbf4c3075","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# Given a JSON list of users, each with a nested \"skills\" list of dicts:\n# [{\"name\": \"John\", \"skills\": [{\"name\": \"Python\", \"level\": \"Expert\"}, {\"name\": \"SQL\", \"level\": \"Intermediate\"}]}]\n#\n# Write a function that flattens this into rows like:\n# {\"name\": \"John\", \"skill_name\": \"Python\", \"skill_level\": \"Expert\"}\n# {\"name\": \"John\", \"skill_name\": \"SQL\", \"skill_level\": \"Intermediate\"}","type":"text"}],"id":"d8e1fff9-8e94-4d40-a235-e696107d0939","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"a8c9adb1-0761-4050-b707-631133844ca9","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"SECTION 3 — Generators & ","type":"text"},{"styles":{"code":true},"text":"yield","type":"text"},{"styles":{},"text":" (Memory-Safe Extraction)","type":"text"}],"id":"533ef3a1-45d3-4730-a79b-0a663039f918","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Why it matters — THIS IS THE #1 TESTED CONCEPT IN DE INTERVIEWS","type":"text"}],"id":"e630639a-b7ab-41ad-a781-4adb6eb0ab21","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Data engineers deal with files/datasets too big for memory. Generators let you process ","type":"text"},{"styles":{"bold":true},"text":"one record at a time","type":"text"},{"styles":{},"text":" instead of loading everything.","type":"text"}],"id":"92fa0498-cb9b-49a9-becd-2a453c8d8064","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"The core mental model","type":"text"}],"id":"e5d20c1c-0e16-4dd8-9f81-e5e61c8a030e","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"A ","type":"text"},{"styles":{"bold":true},"text":"list","type":"text"},{"styles":{},"text":" holds ALL values in memory at once.","type":"text"}],"id":"a8b66d89-7500-4dba-b3aa-02a00eee167a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"A ","type":"text"},{"styles":{"bold":true},"text":"generator","type":"text"},{"styles":{},"text":" holds a \"recipe\" for producing values one at a time, on demand.","type":"text"}],"id":"b20ccec2-89b5-4bcd-847d-0a98aebd2474","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"# LIST — bad for big data\ndef get_rows_list(filepath):\n    rows = []\n    with open(filepath) as f:\n        for line in f:\n            rows.append(line.strip())\n    return rows   # entire file in memory\n\n# GENERATOR — good for big data\ndef get_rows_gen(filepath):\n    with open(filepath) as f:\n        for line in f:\n            yield line.strip()   # one line at a time, memory-efficient","type":"text"}],"id":"7f93247d-404f-4679-8c36-3e270d3f6c42","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"How ","type":"text"},{"styles":{"code":true},"text":"yield","type":"text"},{"styles":{},"text":" actually works (be ready to explain this in words)","type":"text"}],"id":"f54fcbe1-b673-4650-ba86-108450c72cb1","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Calling a generator function does ","type":"text"},{"styles":{"bold":true},"text":"NOT","type":"text"},{"styles":{},"text":" run the code immediately — it returns a generator object.","type":"text"}],"id":"3b0fd3cd-10e1-4afc-8932-057145924b2f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Each call to ","type":"text"},{"styles":{"code":true},"text":"next()","type":"text"},{"styles":{},"text":" runs the function until it hits ","type":"text"},{"styles":{"code":true},"text":"yield","type":"text"},{"styles":{},"text":", returns that value, and ","type":"text"},{"styles":{"bold":true},"text":"pauses","type":"text"},{"styles":{},"text":" (keeping local state).","type":"text"}],"id":"01be6652-eb7e-47b7-8886-4eb2444cfe75","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"The next ","type":"text"},{"styles":{"code":true},"text":"next()","type":"text"},{"styles":{},"text":" call resumes right after the ","type":"text"},{"styles":{"code":true},"text":"yield","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"ba965617-4b18-44c3-8e7b-44fe390e2ca6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"def counter():\n    print(\"start\")\n    yield 1\n    print(\"middle\")\n    yield 2\n    print(\"end\")\n\ngen = counter()\nnext(gen)  # prints \"start\", returns 1\nnext(gen)  # prints \"middle\", returns 2","type":"text"}],"id":"963e537d-362e-47c8-8c20-10e65b3162b4","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Chaining generators (a realistic pipeline pattern)","type":"text"}],"id":"e0629a07-faef-4d0a-965e-f6bee031b70d","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"def read_lines(filepath):\n    with open(filepath) as f:\n        for line in f:\n            yield line.strip()\n\ndef parse_csv_lines(lines):\n    header = next(lines).split('','')\n    for line in lines:\n        values = line.split('','')\n        yield dict(zip(header, values))\n\ndef filter_valid(records):\n    for r in records:\n        if r.get(''amount''):\n            yield r\n\n# Chained pipeline — nothing executes until you iterate!\npipeline = filter_valid(parse_csv_lines(read_lines(''data.csv'')))\nfor row in pipeline:\n    print(row)","type":"text"}],"id":"c831bf26-f5ab-4a9c-bf1b-cf8dc6864726","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"This chaining pattern IS an extract pipeline","type":"text"},{"styles":{},"text":" — this is exactly the shape of code interviewers want to see.","type":"text"}],"id":"077f7029-ebd0-4bbe-b06f-521ba2c7295f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"code":true},"text":"yield","type":"text"},{"styles":{},"text":" vs ","type":"text"},{"styles":{"code":true},"text":"return","type":"text"},{"styles":{},"text":" — classic interview question","type":"text"}],"id":"c8c97138-3a8c-4e21-8775-a92006376123","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{"code":true},"text":"return","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"code":true},"text":"yield","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Exits function completely","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Pauses function, keeps state","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Gives back one value at once","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Gives back many values, one at a time","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Function runs fully before returning","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Function runs incrementally as you iterate","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"ff7bd3db-366b-4afa-86a6-61c6583bca99","props":{"textColor":"default"},"type":"table"},{"children":[],"content":[{"styles":{},"text":"Practice Exercise 3","type":"text"}],"id":"b846ef47-3b17-469e-a067-2fe331d6a0f8","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# Write a generator pipeline with 3 chained generator functions:\n# 1. read_lines(filepath) - yields raw lines\n# 2. to_dicts(lines) - yields parsed dicts  \n# 3. clean_amount(dicts) - yields dicts with amount cast to float, skipping bad rows\n# Then iterate and print only rows where amount > 100","type":"text"}],"id":"ab4b5796-61f5-4e5d-a18f-1494fb5052a3","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"2c118b3d-0c69-4df9-a5c6-9fbd06018d85","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"SECTION 4 — Chunked Reading (Pandas-Specific)","type":"text"}],"id":"be553dcc-791f-4569-a8bb-d74ea21ea186","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Why it matters","type":"text"}],"id":"5f2da04c-b396-464f-9159-3dbd40c3103a","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"When you must use pandas (common in DE work) but the file is too big to fit in memory, ","type":"text"},{"styles":{"code":true},"text":"chunksize","type":"text"},{"styles":{},"text":" processes it in batches.","type":"text"}],"id":"239d57ec-3468-475e-8751-b5c99d34b5df","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"import pandas as pd\n\ndef process_large_csv(filepath, chunk_size=10000):\n    total_sum = 0\n    for chunk in pd.read_csv(filepath, chunksize=chunk_size):\n        # chunk is a normal DataFrame, just a subset of rows\n        chunk[''amount''] = chunk[''amount''].fillna(0)\n        total_sum += chunk[''amount''].sum()\n    return total_sum","type":"text"}],"id":"004e6b4c-79de-4b40-b0c0-7217e22b2bc8","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Key interview point:","type":"text"},{"styles":{},"text":" ","type":"text"},{"styles":{"code":true},"text":"chunksize","type":"text"},{"styles":{},"text":" returns an ","type":"text"},{"styles":{"bold":true},"text":"iterator of DataFrames","type":"text"},{"styles":{},"text":", not one big DataFrame. You must aggregate results across chunks yourself (like a manual MapReduce).","type":"text"}],"id":"dfec54c7-579f-4f45-9f99-d7d1ce276344","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Practice Exercise 4","type":"text"}],"id":"b41eb8e3-4390-4ada-b60e-8f4f3af567fe","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# Given a large CSV of transactions, use chunksize=5000 to:\n# - Count total rows\n# - Sum the ''amount'' column\n# - Find the max single transaction\n# ...without ever loading the full file into memory at once","type":"text"}],"id":"0afec655-b4fc-422e-bd02-5f26f961d3af","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"967004b3-73cc-409a-840e-3b23091defaf","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"SECTION 5 — Extracting from APIs (","type":"text"},{"styles":{"code":true},"text":"requests","type":"text"},{"styles":{},"text":")","type":"text"}],"id":"3c68f2c0-2e73-4b57-a9f7-afb59a8b9615","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Why it matters","type":"text"}],"id":"d195dccb-2ad8-4b20-a0da-d8bd483763b0","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Most real-world data engineering extracts pull from REST APIs, not static files.","type":"text"}],"id":"4f3831de-d6e9-42ac-b9f5-99878982d9fd","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"The basics","type":"text"}],"id":"cdd865eb-c5b3-49b7-b5a0-dc2d4c6c8762","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"import requests\n\ndef fetch_data(url, params=None):\n    response = requests.get(url, params=params)\n    response.raise_for_status()   # raises exception if status is 4xx/5xx\n    return response.json()","type":"text"}],"id":"3d1c9285-f80f-4ff7-80a4-ce17df785a61","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Key concepts to know cold","type":"text"}],"id":"68ccb6f9-4dfa-4b30-b371-cd504db6be0e","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Concept","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"What it means","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"response.status_code","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"200 = OK, 404 = not found, 500 = server error, 429 = rate-limited","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"response.raise_for_status()","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"throws ","type":"text"},{"styles":{"code":true},"text":"HTTPError","type":"text"},{"styles":{},"text":" automatically on bad status — cleaner than manual checks","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"response.json()","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"parses JSON body into Python dict/list","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Headers/Auth","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"code":true},"text":"requests.get(url, headers={''Authorization'': f''Bearer {token}''})","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Timeouts","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"ALWAYS set one: ","type":"text"},{"styles":{"code":true},"text":"requests.get(url, timeout=10)","type":"text"},{"styles":{},"text":" — an API interviewer WILL ask \"what if the API hangs forever?\"","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"5b7996df-25eb-4e80-8f1d-a70cc28005e1","props":{"textColor":"default"},"type":"table"},{"children":[],"content":[{"styles":{},"text":"Practice Exercise 5","type":"text"}],"id":"7bdf6bea-beab-4c40-8377-ef0be74379d8","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# Write a function fetch_users(api_url) that:\n# - Calls the API with a 5-second timeout\n# - Raises a clear error if status is not 200\n# - Returns the parsed JSON\n# - Handles requests.exceptions.Timeout and requests.exceptions.ConnectionError separately","type":"text"}],"id":"c8a875c8-dcfd-4408-a6c7-085e062ae922","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"03faf04a-4df7-4e3f-a7e4-67155a02bbe1","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"SECTION 6 — Handling Pagination","type":"text"}],"id":"887ab11d-9c43-4eb5-bea6-b0d875c5768d","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Why it matters","type":"text"}],"id":"69782844-0bdb-4488-bd6b-67febc828af9","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"APIs never give you everything in one call — they paginate. This is an almost-guaranteed interview coding question.","type":"text"}],"id":"5a1497d9-c7d2-458c-b3f7-3694a9e4822f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Pattern 1: Page number based","type":"text"}],"id":"87b1eb84-ba00-498f-9fa0-18a0ce906ec6","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"def fetch_all_paginated(base_url):\n    page = 1\n    all_data = []\n    while True:\n        response = requests.get(base_url, params={''page'': page, ''per_page'': 100})\n        response.raise_for_status()\n        data = response.json()\n        if not data:          # empty list = no more pages\n            break\n        all_data.extend(data)\n        page += 1\n    return all_data","type":"text"}],"id":"ca71fe42-9ecb-4514-90e9-1dfb4a03a477","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Pattern 2: \"Next cursor/token\" based (more realistic for modern APIs)","type":"text"}],"id":"8facb76b-3ace-4597-988f-aace80ec7dfc","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"def fetch_all_cursor(base_url):\n    all_data = []\n    next_cursor = None\n    while True:\n        params = {''cursor'': next_cursor} if next_cursor else {}\n        response = requests.get(base_url, params=params)\n        payload = response.json()\n        all_data.extend(payload[''results''])\n        next_cursor = payload.get(''next_cursor'')\n        if not next_cursor:\n            break\n    return all_data","type":"text"}],"id":"b8df3d2a-3dee-4c8f-a6d3-9de89f5f26e6","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"As a generator (memory-safe, preferred style)","type":"text"}],"id":"fe2d420c-5e4d-4b28-b12f-b2f922c442d6","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"def fetch_all_paginated_gen(base_url):\n    page = 1\n    while True:\n        response = requests.get(base_url, params={''page'': page})\n        data = response.json()\n        if not data:\n            break\n        yield from data     # yields each item individually\n        page += 1","type":"text"}],"id":"c5370cd5-3841-441e-a6c1-df162ffc75f5","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"code":true},"text":"yield from","type":"text"},{"styles":{},"text":" — yields every item of an iterable one-by-one, instead of yielding the whole list at once. Know this syntax; it''s often specifically asked.","type":"text"}],"id":"140e3ab0-0688-482b-a7c2-45a3dc76cd7c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Practice Exercise 6","type":"text"}],"id":"e549a3c9-2940-4265-b113-1d1de92aefa7","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# Simulate a paginated API using a local function (no internet needed):\ndef fake_api(page):\n    data = {1: [1,2,3], 2: [4,5,6], 3: []}\n    return data.get(page, [])\n\n# Write a generator that calls fake_api with increasing page numbers\n# and yields individual items until an empty page is returned","type":"text"}],"id":"ee75f036-08fe-4878-80fb-24ce9b01a661","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"e93d03ec-f4f1-4680-a80e-fa98ebc6a2c2","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"SECTION 7 — Retry Logic & Decorators","type":"text"}],"id":"0223aa4a-83e4-4ce8-ba42-ddb09a54e567","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Why it matters","type":"text"}],"id":"8cbfc2b9-966e-43f8-8d21-41636c949ca5","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Networks fail. APIs rate-limit. A production extractor must retry intelligently instead of crashing on the first failure.","type":"text"}],"id":"d5b94c64-8843-49e7-814c-6d3f2842f19c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Building it step by step","type":"text"}],"id":"7ad7474c-8c0a-41cd-90f3-8d21fece13e9","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Step 1 — manual retry (understand the logic first)","type":"text"}],"id":"1e01a2ef-ba42-471d-b6cb-bec17c98fa36","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"import time\n\ndef fetch_with_retry(url, max_retries=3, delay=2):\n    for attempt in range(1, max_retries + 1):\n        try:\n            response = requests.get(url, timeout=5)\n            response.raise_for_status()\n            return response.json()\n        except requests.exceptions.RequestException as e:\n            print(f\"Attempt {attempt} failed: {e}\")\n            if attempt == max_retries:\n                raise   # give up after last attempt\n            time.sleep(delay)","type":"text"}],"id":"08f76baa-7b23-4af4-9cbe-d75812e4277c","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Step 2 — turn it into a reusable decorator (this is what interviewers actually want to see)","type":"text"}],"id":"3e0ce3d0-cff5-4f72-b9ce-3de507a5ebc0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"import time\nimport functools\n\ndef retry(max_retries=3, delay=2, exceptions=(Exception,)):\n    def decorator(func):\n        @functools.wraps(func)\n        def wrapper(*args, **kwargs):\n            for attempt in range(1, max_retries + 1):\n                try:\n                    return func(*args, **kwargs)\n                except exceptions as e:\n                    print(f\"Attempt {attempt} failed: {e}\")\n                    if attempt == max_retries:\n                        raise\n                    time.sleep(delay)\n        return wrapper\n    return decorator\n\n# Usage:\n@retry(max_retries=3, delay=2, exceptions=(requests.exceptions.RequestException,))\ndef fetch_data(url):\n    response = requests.get(url, timeout=5)\n    response.raise_for_status()\n    return response.json()","type":"text"}],"id":"6ff93e57-48d3-4ecc-b239-bab350b443e1","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Concepts you must be able to explain in words","type":"text"}],"id":"f588e177-586f-467d-9e39-c3a69cecacf1","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why decorators?","type":"text"},{"styles":{},"text":" They let you add retry/logging/timing behavior to any function without rewriting its internals — separation of concerns.","type":"text"}],"id":"9a6be368-7693-41ad-a414-552390687501","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"code":true},"text":"*args, **kwargs","type":"text"},{"styles":{},"text":" — needed so the decorator works on any function signature.","type":"text"}],"id":"3fab2ac3-e50b-4e6c-9122-8ce3aa711128","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"code":true},"text":"functools.wraps","type":"text"},{"styles":{},"text":" — preserves the original function''s name/docstring (interviewers sometimes ask \"what does this do and why do we need it?\").","type":"text"}],"id":"5939a72d-a554-492f-8cfe-d054628c6682","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Exponential backoff","type":"text"},{"styles":{},"text":" (common follow-up): instead of fixed ","type":"text"},{"styles":{"code":true},"text":"delay","type":"text"},{"styles":{},"text":", do ","type":"text"},{"styles":{"code":true},"text":"delay * (2 ** attempt)","type":"text"},{"styles":{},"text":" so wait time increases each retry.","type":"text"}],"id":"95ce4cee-29d6-4c5e-b1d5-9e75ed9803f0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Practice Exercise 7","type":"text"}],"id":"127c4be6-a7ff-4094-a6b9-bf4f106130b2","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# Write a retry decorator with exponential backoff that:\n# - Retries a flaky function up to 4 times\n# - Waits 1s, then 2s, then 4s, then 8s between attempts\n# - Only retries on ConnectionError, not on ValueError\n# Test it against a fake function that fails 3 times then succeeds","type":"text"}],"id":"64fcbd39-ba52-4f98-b138-44b6129da8f9","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"3819ec44-94f8-4aef-ab1c-6da1a2422599","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"SECTION 8 — Extracting from Databases (","type":"text"},{"styles":{"code":true},"text":"sqlite3","type":"text"},{"styles":{},"text":" / SQLAlchemy)","type":"text"}],"id":"d7b416d7-e304-45a6-a218-5f1336ef3e2c","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Why it matters","type":"text"}],"id":"76be4a47-0e35-44cd-a3a0-ffecc9691644","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Sometimes your \"source\" is another database — you extract via SQL query, not a file/API.","type":"text"}],"id":"fe351bf7-6861-4994-8390-73a41c23b75f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Using ","type":"text"},{"styles":{"code":true},"text":"sqlite3","type":"text"},{"styles":{},"text":" (standard library, most commonly tested)","type":"text"}],"id":"a6037dbe-7752-4b13-8599-dbef460cc2b5","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"import sqlite3\n\ndef extract_from_db(db_path, query):\n    conn = sqlite3.connect(db_path)\n    conn.row_factory = sqlite3.Row   # lets you access columns by name, like a dict\n    cursor = conn.cursor()\n    cursor.execute(query)\n    for row in cursor:\n        yield dict(row)     # generator, memory-safe\n    conn.close()","type":"text"}],"id":"99c59ff4-51a1-468d-b1b8-1f2e8cfe2b56","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Using context managers properly (interviewers check this)","type":"text"}],"id":"e342a804-7d41-4f2f-8221-b31737a2360a","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"def extract_from_db_safe(db_path, query):\n    with sqlite3.connect(db_path) as conn:\n        conn.row_factory = sqlite3.Row\n        cursor = conn.execute(query)\n        for row in cursor:\n            yield dict(row)\n    # connection auto-closes even if an error occurs","type":"text"}],"id":"6a99a481-607e-471e-906a-b30ca69c23d8","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Parameterized queries (SQL injection — a real interview red flag if you get this wrong)","type":"text"}],"id":"2c149337-e2c0-419b-80f4-fc60a5767041","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# WRONG — vulnerable to SQL injection\ncursor.execute(f\"SELECT * FROM users WHERE id = {user_id}\")\n\n# RIGHT — parameterized\ncursor.execute(\"SELECT * FROM users WHERE id = ?\", (user_id,))","type":"text"}],"id":"39b53fa2-940c-4d43-a82b-6a6e9bcf9814","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Practice Exercise 8","type":"text"}],"id":"7bfac364-db67-4462-9b0b-5bcdc6240731","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# Create a small SQLite DB with a ''sales'' table (id, region, amount, date)\n# Write a generator extract_sales(db_path, min_amount) that:\n# - Uses a parameterized query to filter rows where amount > min_amount\n# - Yields each row as a dict","type":"text"}],"id":"d429a17c-ff3d-48c8-9d7f-f0f442a3fdfd","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"9c114bbb-2eaa-42f2-b77d-ccb014c233c7","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"SECTION 9 — Error Handling Specific to Extraction","type":"text"}],"id":"9dc329b4-3760-4a46-b1e5-9c792aea61ba","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The extraction-specific error mindset","type":"text"}],"id":"713c2fa0-079d-4ef0-aa6f-139e399cb73f","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Every source type has its own failure modes — know them:","type":"text"}],"id":"d1ddb1b5-4bab-4927-ad15-bdff1d5c0c8e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":{"columnWidths":[null,null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Source","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Common failures","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"How to handle","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"CSV/JSON files","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"File not found, bad encoding, malformed rows","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"code":true},"text":"try/except FileNotFoundError","type":"text"},{"styles":{},"text":", skip/log bad rows, don''t crash whole pipeline","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"APIs","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Timeout, rate limit (429), auth failure (401), server error (500)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"retry decorator, exponential backoff, respect ","type":"text"},{"styles":{"code":true},"text":"Retry-After","type":"text"},{"styles":{},"text":" header","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Databases","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Connection drop, locked DB, bad query","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"context managers, connection retries","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"13ead912-9f77-47ad-ac50-757e14522bc4","props":{"textColor":"default"},"type":"table"},{"children":[],"content":[{"styles":{},"text":"Custom exceptions (shows senior-level thinking even as a fresher)","type":"text"}],"id":"18c363a0-4399-4f55-830b-7e6b354efc3f","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"class ExtractionError(Exception):\n    \"\"\"Base exception for extraction failures\"\"\"\n    pass\n\nclass SourceNotFoundError(ExtractionError):\n    pass\n\ndef extract_file(filepath):\n    try:\n        with open(filepath) as f:\n            return f.read()\n    except FileNotFoundError:\n        raise SourceNotFoundError(f\"Source file missing: {filepath}\")","type":"text"}],"id":"4a373ed1-edab-4a79-921b-d23c4674af89","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why custom exceptions matter:","type":"text"},{"styles":{},"text":" in a real pipeline, you want to catch \"extraction failed\" separately from \"transformation failed\" — this makes debugging and monitoring possible.","type":"text"}],"id":"5581cc00-6069-410b-87de-fe71a8e2a10c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"61f8ab48-b717-4ccf-9427-15295b75e1c9","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"🏗️ CAPSTONE PROJECT — The \"Universal Extractor\"","type":"text"}],"id":"37e92add-8467-475f-805f-6a8a6450387e","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Build this AFTER you''ve done all 8 practice exercises above. This combines every concept into one cohesive script — exactly the kind of thing an interviewer might ask you to build or extend live.","type":"text"}],"id":"7ea9dfc2-3005-4640-acb9-676441fa8176","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"\"\"\"\nUniversal Extractor\nSupports: CSV file, JSON Lines file, REST API (paginated), SQLite DB\nAll extraction methods return a GENERATOR of dicts (memory-safe, consistent interface)\n\"\"\"\n\nimport csv\nimport json\nimport time\nimport sqlite3\nimport logging\nimport functools\nimport requests\n\nlogging.basicConfig(level=logging.INFO)\nlogger = logging.getLogger(\"extractor\")\n\n\n# ---------- Custom Exceptions ----------\nclass ExtractionError(Exception):\n    pass\n\n\n# ---------- Retry Decorator ----------\ndef retry(max_retries=3, delay=1, exceptions=(Exception,)):\n    def decorator(func):\n        @functools.wraps(func)\n        def wrapper(*args, **kwargs):\n            for attempt in range(1, max_retries + 1):\n                try:\n                    return func(*args, **kwargs)\n                except exceptions as e:\n                    logger.warning(f\"[{func.__name__}] Attempt {attempt} failed: {e}\")\n                    if attempt == max_retries:\n                        raise ExtractionError(f\"Failed after {max_retries} attempts\") from e\n                    time.sleep(delay * attempt)   # simple backoff\n        return wrapper\n    return decorator\n\n\n# ---------- 1. CSV Extraction ----------\ndef extract_csv(filepath):\n    try:\n        with open(filepath, ''r'', newline='''', encoding=''utf-8'') as f:\n            reader = csv.DictReader(f)\n            for row in reader:\n                yield row\n    except FileNotFoundError:\n        raise ExtractionError(f\"CSV file not found: {filepath}\")\n\n\n# ---------- 2. JSONL Extraction ----------\ndef extract_jsonl(filepath):\n    try:\n        with open(filepath, ''r'', encoding=''utf-8'') as f:\n            for line_num, line in enumerate(f, 1):\n                line = line.strip()\n                if not line:\n                    continue\n                try:\n                    yield json.loads(line)\n                except json.JSONDecodeError:\n                    logger.warning(f\"Skipping malformed JSON at line {line_num}\")\n    except FileNotFoundError:\n        raise ExtractionError(f\"JSONL file not found: {filepath}\")\n\n\n# ---------- 3. Paginated API Extraction ----------\n@retry(max_retries=3, delay=2, exceptions=(requests.exceptions.RequestException,))\ndef _fetch_page(url, page):\n    response = requests.get(url, params={''page'': page}, timeout=5)\n    response.raise_for_status()\n    return response.json()\n\ndef extract_api(url):\n    page = 1\n    while True:\n        data = _fetch_page(url, page)\n        if not data:\n            break\n        yield from data\n        page += 1\n\n\n# ---------- 4. Database Extraction ----------\ndef extract_db(db_path, query, params=()):\n    try:\n        with sqlite3.connect(db_path) as conn:\n            conn.row_factory = sqlite3.Row\n            cursor = conn.execute(query, params)\n            for row in cursor:\n                yield dict(row)\n    except sqlite3.Error as e:\n        raise ExtractionError(f\"DB extraction failed: {e}\")\n\n\n# ---------- Unified Interface ----------\ndef extract(source_type, **kwargs):\n    \"\"\"Single entry point - dispatches to the right extractor\"\"\"\n    extractors = {\n        ''csv'': extract_csv,\n        ''jsonl'': extract_jsonl,\n        ''api'': extract_api,\n        ''db'': extract_db,\n    }\n    if source_type not in extractors:\n        raise ValueError(f\"Unknown source type: {source_type}\")\n    return extractors[source_type](**kwargs)\n\n\n# ---------- Usage Example ----------\nif __name__ == \"__main__\":\n    for record in extract(''csv'', filepath=''sales.csv''):\n        print(record)","type":"text"}],"id":"f1e693b6-3a6c-4239-9f96-e881bbfbe609","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Why this capstone is interview-gold","type":"text"}],"id":"290d8884-104f-4457-a2cc-0cf23e488961","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"It uses ","type":"text"},{"styles":{"bold":true},"text":"generators everywhere","type":"text"},{"styles":{},"text":" (memory safety)","type":"text"}],"id":"b71a3b4f-94bc-496c-b5bd-95958e8f3dd3","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"It uses ","type":"text"},{"styles":{"bold":true},"text":"decorators","type":"text"},{"styles":{},"text":" for retry logic (reusability)","type":"text"}],"id":"eeeab6af-43d0-4399-8263-552a11bf1a9b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"It has ","type":"text"},{"styles":{"bold":true},"text":"custom exceptions","type":"text"},{"styles":{},"text":" (clean error handling)","type":"text"}],"id":"9408c2f4-9083-45b2-9126-0bfce4a28d4a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"It has a ","type":"text"},{"styles":{"bold":true},"text":"unified interface","type":"text"},{"styles":{},"text":" (","type":"text"},{"styles":{"code":true},"text":"extract()","type":"text"},{"styles":{},"text":") — shows you think about clean API design, not just scripts","type":"text"}],"id":"a014a591-6e9c-49c9-8de0-728a9f82d905","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Every source type is ","type":"text"},{"styles":{"bold":true},"text":"isolated and testable","type":"text"},{"styles":{},"text":" independently","type":"text"}],"id":"6e1520c5-36a9-46f8-8b6a-c3798370f894","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"id":"f106833c-bcdf-4d6f-9312-4a3ef92f5c24","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"🎤 Scenario-Based Interview Questions (Practice Saying These Out Loud)","type":"text"}],"id":"de6c1b54-dc56-45bc-a900-52295e0d8abe","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"How would you extract data from a 50GB CSV file without running out of memory?\"","type":"text"},{"styles":{},"text":" → Generators, chunked reading, never load fully into a list.","type":"text"}],"id":"57431dd7-7760-4d6e-9167-1139a90099aa","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"An API you''re pulling from randomly times out. How do you handle it?\"","type":"text"},{"styles":{},"text":" → Retry decorator with exponential backoff + timeout parameter.","type":"text"}],"id":"6cfd5def-eddf-4c4f-a71d-409d9589e31c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"How do you handle a JSON file with deeply nested structures that needs to go into a flat SQL table?\"","type":"text"},{"styles":{},"text":" → Recursive flattening + exploding nested lists into separate rows.","type":"text"}],"id":"38cf994b-8727-45ca-a462-6d990ae9c519","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"What happens if the API changes and starts returning an extra field, or removes a field?\"","type":"text"},{"styles":{},"text":" → Use ","type":"text"},{"styles":{"code":true},"text":".get()","type":"text"},{"styles":{},"text":" with defaults instead of direct key access; validate schema before processing.","type":"text"}],"id":"dcc8c873-bc14-4af6-96fd-09fc9d3c5c33","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"How would you avoid re-extracting data you already pulled yesterday?\"","type":"text"},{"styles":{},"text":" → Incremental extraction — track a ","type":"text"},{"styles":{"code":true},"text":"last_extracted_timestamp","type":"text"},{"styles":{},"text":" or use API''s ","type":"text"},{"styles":{"code":true},"text":"updated_since","type":"text"},{"styles":{},"text":" param / DB ","type":"text"},{"styles":{"code":true},"text":"WHERE updated_at > ?","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"e6af09df-d708-4609-9bca-be6b9831bfc5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"Difference between ","type":"text"},{"styles":{"code":true},"text":"csv.reader","type":"text"},{"styles":{"italic":true},"text":" and ","type":"text"},{"styles":{"code":true},"text":"csv.DictReader","type":"text"},{"styles":{"italic":true},"text":"?\"","type":"text"},{"styles":{},"text":" → ","type":"text"},{"styles":{"code":true},"text":"reader","type":"text"},{"styles":{},"text":" gives lists, ","type":"text"},{"styles":{"code":true},"text":"DictReader","type":"text"},{"styles":{},"text":" gives dicts using header row as keys — easier, safer access.","type":"text"}],"id":"7d748fbf-aa3c-4b16-81db-3de51f429794","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"Why use a generator instead of returning a list?\"","type":"text"},{"styles":{},"text":" → Lazy evaluation, doesn''t hold everything in memory, works well when chained into pipelines.","type":"text"}],"id":"0519414d-a199-477a-a44f-2d65f9b17266","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"What''s the difference between ","type":"text"},{"styles":{"code":true},"text":"yield","type":"text"},{"styles":{"italic":true},"text":" and ","type":"text"},{"styles":{"code":true},"text":"yield from","type":"text"},{"styles":{"italic":true},"text":"?\"","type":"text"},{"styles":{},"text":" → ","type":"text"},{"styles":{"code":true},"text":"yield","type":"text"},{"styles":{},"text":" gives one value; ","type":"text"},{"styles":{"code":true},"text":"yield from","type":"text"},{"styles":{},"text":" delegates to another iterable, yielding all its values one by one.","type":"text"}],"id":"14ccd3ba-0911-4ba2-929f-564458092acd","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"id":"a83694d0-c16c-4bd7-ac78-aeeeb3acf64f","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"✅ Study & Practice Checklist","type":"text"}],"id":"5fdb9e37-7776-446e-98c6-4952bb57274f","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Go in this exact order. Don''t skip ahead — each section builds on the last.","type":"text"}],"id":"9e079495-332b-4ed7-ab56-2d2b3501ac08","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Section 1 — CSV reading + Practice Exercise 1","type":"text"}],"id":"604bcc9c-c434-43dd-9bf9-5ea12f819420","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Section 2 — JSON flattening + Practice Exercise 2","type":"text"}],"id":"abf2a614-6e9f-4dea-8a1a-685e662e9981","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Section 3 — Generators/yield + Practice Exercise 3 (","type":"text"},{"styles":{"bold":true},"text":"spend the most time here","type":"text"},{"styles":{},"text":")","type":"text"}],"id":"bcc2cf9e-c5d8-4ecf-b922-6173cd81e62c","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Section 4 — Pandas chunking + Practice Exercise 4","type":"text"}],"id":"655bf06c-d720-46e5-a879-9564f9e9bb38","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Section 5 — API basics + Practice Exercise 5","type":"text"}],"id":"b597eb6b-47b6-4ae7-885d-2ced1ca31091","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Section 6 — Pagination + Practice Exercise 6","type":"text"}],"id":"5f5ccf67-cbfb-4727-a7fb-d53e9401cacd","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Section 7 — Retry decorators + Practice Exercise 7","type":"text"}],"id":"d2eb8dc0-a8bd-488a-97d7-c550efb5f685","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Section 8 — DB extraction + Practice Exercise 8","type":"text"}],"id":"0012621a-9b93-4c68-a028-550373af024a","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Section 9 — Error handling patterns (read + rewrite in your own words)","type":"text"}],"id":"55d3dc18-2569-4a32-b53b-a65ddb99cbb5","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Build the ","type":"text"},{"styles":{"bold":true},"text":"Capstone Universal Extractor","type":"text"},{"styles":{},"text":" from scratch, without copying","type":"text"}],"id":"140f3410-8b13-49fd-b384-888613b3b2f5","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Answer all 8 scenario questions out loud, unscripted","type":"text"}],"id":"1c877593-f6b4-430e-821e-1c26a89fc770","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Once you can build the capstone project from memory and explain every design decision in it, you are genuinely interview-ready for the Extract portion.","type":"text"}],"id":"1c6b65d2-1c67-43a3-a846-4f6df38daf34","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"15bd6632-ac81-48e8-b930-4a9643312bef","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Want me to build the ","type":"text"},{"styles":{"bold":true},"text":"same depth of note for the Transform branch","type":"text"},{"styles":{},"text":" next, using the same structure (theory → code → gotchas → practice exercises → capstone → scenario questions)?","type":"text"}],"id":"073733dd-39e5-4f16-bb4e-0e2acbc48a01","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[],"id":"45700f40-3c82-4d44-aba5-6f059b17fe52","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"}]'::jsonb, '3e9e3dd3-a59b-4b02-968a-ee95e7317583') ON CONFLICT ("node_id") DO UPDATE SET "bad_example" = EXCLUDED."bad_example", "completed_at" = EXCLUDED."completed_at", "created_at" = EXCLUDED."created_at", "definition" = EXCLUDED."definition", "good_example" = EXCLUDED."good_example", "is_completed" = EXCLUDED."is_completed", "key_points" = EXCLUDED."key_points", "last_edited" = EXCLUDED."last_edited", "map_id" = EXCLUDED."map_id", "mental_model" = EXCLUDED."mental_model", "notes" = EXCLUDED."notes", "resources" = EXCLUDED."resources", "rich_content" = EXCLUDED."rich_content", "user_id" = EXCLUDED."user_id";
INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-08-06T16:17:43.852356+00:00', '', '', '004c8549-e32c-4f47-abc0-68de71910327', false, '[]'::jsonb, '2026-08-06T16:19:49.95+00:00', '2ad473fe-77dd-481e-8ba7-4b2b0336173f', '', '4c31fed3-93f9-41ee-be4d-38b4246a2477', '', '[]'::jsonb, '[{"children":[],"content":[{"styles":{},"text":"📘 SPARK ARCHITECTURE CONCEPTS — Complete Study Note for Interviews","type":"text"}],"id":"5ce41508-57c5-4aeb-87b8-f73b0be19029","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"id":"91450cb1-bd72-4b09-a30a-db6c2e049e3a","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"🎯 Why You Need to Understand Architecture Before Writing PySpark Code","type":"text"}],"id":"739f8762-0d9a-4bf5-b88f-8ede2c1374cd","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Here is the honest truth: ","type":"text"},{"styles":{"bold":true},"text":"you can memorize PySpark syntax without understanding Spark architecture, but you will fail the interview the moment they ask \"why.\"","type":"text"}],"id":"ab3b482f-ec94-4a34-b2b5-afe9b6332e79","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"Why is your Spark job slow?\"","type":"text"},{"styles":{},"text":" — you need architecture to answer this","type":"text"}],"id":"354dd344-a403-4950-905f-e950f7f5ba22","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"What is the difference between a transformation and an action?\"","type":"text"},{"styles":{},"text":" — architecture","type":"text"}],"id":"50598be1-ce39-4eea-ad68-e7eee9ee1301","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"Why did your job run out of memory?\"","type":"text"},{"styles":{},"text":" — architecture","type":"text"}],"id":"292a2bb9-37a3-4914-9d9f-f93a8b04d599","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"What does shuffling mean and why is it expensive?\"","type":"text"},{"styles":{},"text":" — architecture","type":"text"}],"id":"58c82915-0d0b-4225-b4c4-f5b9f0c9676c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Every PySpark line you write makes more sense, runs better, and is easier to explain ","type":"text"},{"styles":{"bold":true},"text":"when you understand what is happening underneath it.","type":"text"},{"styles":{},"text":" This note gives you that foundation completely.","type":"text"}],"id":"633f1b14-d1ac-4bb0-8a50-9365d19bd04c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"2572d9b9-77d9-463c-a48b-47e4dd15a88d","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"SECTION 1 — What is Spark and Why Does It Exist?","type":"text"}],"id":"b7dd1e8c-99c2-4897-973b-017a72773766","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The problem Spark solves","type":"text"}],"id":"86dca891-ae97-4668-95c3-75e35fc7ad10","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Before Spark, the dominant big data tool was ","type":"text"},{"styles":{"bold":true},"text":"Hadoop MapReduce","type":"text"},{"styles":{},"text":". It worked, but it had one massive problem: ","type":"text"},{"styles":{"bold":true},"text":"every intermediate result was written to disk.","type":"text"}],"id":"26ff32b9-5389-4297-9489-3109a9ea4a9f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"MapReduce job:\nStep 1: Read from disk -> Process -> Write to disk\nStep 2: Read from disk -> Process -> Write to disk\nStep 3: Read from disk -> Process -> Write to disk\n\nFor a 10-step ML algorithm: 10 reads + 10 writes to disk\nDisk I/O is slow. Very slow.","type":"text"}],"id":"76de1525-8130-4367-96bf-dbd0f339b215","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"What Spark did differently","type":"text"}],"id":"01446efb-4b98-4fef-b2af-dd2e49e8af05","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Spark keeps ","type":"text"},{"styles":{"bold":true},"text":"intermediate results in memory (RAM)","type":"text"},{"styles":{},"text":" instead of writing them to disk after every step.","type":"text"}],"id":"86acfb45-0953-4d0b-9818-31de26f175c1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Spark job:\nRead from disk once -> Process in memory -> Process in memory -> Process in memory -> Write to disk once\n\nSame 10-step algorithm: 1 read + 1 write to disk\nEverything in between: RAM\nRAM is 100x faster than disk","type":"text"}],"id":"92329a0d-34a7-4fc9-b595-ac1c1c0601bf","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"This is the single most important thing to understand about Spark — it is fast because it processes data in memory.","type":"text"}],"id":"191082ef-f8fa-42bc-a006-89947caefb71","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"The official one-liner (memorize this)","type":"text"}],"id":"60a806df-1f2d-4b51-90e3-835c1a91764a","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"Apache Spark is an open-source, distributed computing framework designed for fast, large-scale data processing by keeping data in memory across a cluster of machines.\"","type":"text"}],"id":"f15378f3-e97b-460e-b664-8506e2abd0e3","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Where Spark fits in the DE world","type":"text"}],"id":"0e98bae3-4138-42db-ad5c-06bcb94fbaf8","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Data size fits in one machine''s RAM    → Use pandas\nData size fits in one machine''s disk   → Use pandas with chunking or SQLite\nData size needs multiple machines      → Use Spark","type":"text"}],"id":"9fba2433-192a-4472-84c3-610bf13a2a0f","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"a1b3a8e6-4209-4a2f-b9a0-972ccf9c2020","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"SECTION 2 — The Cluster Model (How Spark Uses Multiple Machines)","type":"text"}],"id":"14397f37-1f1d-4f1f-b528-7b2f92259288","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The core idea","type":"text"}],"id":"c251d418-af74-4841-be12-69fbb0dacdef","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Spark splits your data across ","type":"text"},{"styles":{"bold":true},"text":"multiple computers (nodes)","type":"text"},{"styles":{},"text":" and processes each piece in parallel. This is called ","type":"text"},{"styles":{"bold":true},"text":"distributed computing.","type":"text"}],"id":"a84d5f85-7d13-406c-8bf5-e75dec5544e2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Without Spark (one machine):\n[Your laptop] — processes 1TB of data sequentially — takes 10 hours\n\nWith Spark (cluster of 10 machines):\n[Machine 1] — processes 100GB\n[Machine 2] — processes 100GB     → all running simultaneously\n[Machine 3] — processes 100GB        → takes ~1 hour\n...\n[Machine 10] — processes 100GB","type":"text"}],"id":"2f459f90-eaa0-4163-9d33-ba3dd6335c40","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"The three roles in a Spark cluster","type":"text"}],"id":"8e52cbb3-ec5c-4848-a3a0-9f5b39df6c59","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"┌─────────────────────────────────────────┐\n│              CLUSTER MANAGER            │  ← manages the machines\n│         (YARN / Kubernetes / Mesos)     │     allocates resources\n└─────────────────────────────────────────┘\n              │\n              ▼\n┌─────────────────────────────────────────┐\n│               DRIVER NODE               │  ← your program lives here\n│  - Runs your PySpark code               │     the \"brain\"\n│  - Creates the SparkContext             │\n│  - Breaks job into tasks                │\n│  - Coordinates everything               │\n└─────────────────────────────────────────┘\n              │\n    ┌─────────┼─────────┐\n    ▼         ▼         ▼\n┌───────┐ ┌───────┐ ┌───────┐\n│Executor│ │Executor│ │Executor│  ← worker nodes\n│Node 1  │ │Node 2  │ │Node 3  │     the \"muscles\"\n│- Runs  │ │- Runs  │ │- Runs  │\n│  tasks │ │  tasks │ │  tasks │\n│- Stores│ │- Stores│ │- Stores│\n│  data  │ │  data  │ │  data  │\n└───────┘ └───────┘ └───────┘","type":"text"}],"id":"df349f3a-f307-46f2-9466-f5673a124437","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"The Driver — understand this deeply","type":"text"}],"id":"b3145e81-e284-4a9d-913b-adefa974e60c","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The Driver is where ","type":"text"},{"styles":{"bold":true},"text":"your code runs","type":"text"},{"styles":{},"text":". It does not process data itself — it:","type":"text"}],"id":"d413b382-bf2f-4298-9be7-a5f59f732167","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Reads your PySpark code","type":"text"}],"id":"080254a5-1aec-4764-b6b0-abd27bed2693","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Builds an execution plan (called a DAG — explained in Section 5)","type":"text"}],"id":"65f37328-394f-495d-a383-ce6f823b6ca3","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Sends tasks to Executors","type":"text"}],"id":"87ac5680-04b9-45fc-8db1-9638be2914b0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Collects results","type":"text"}],"id":"28015ffd-1129-49f9-9970-c40531b69a09","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Interview gotcha:","type":"text"},{"styles":{},"text":" If you call ","type":"text"},{"styles":{"code":true},"text":".collect()","type":"text"},{"styles":{},"text":" on a huge dataset, the Driver receives ALL the data. If the dataset is larger than Driver memory, your job crashes. This is one of the most common beginner mistakes in Spark.","type":"text"}],"id":"9bd285b5-5bbc-4cca-ba0d-8bf9b0546892","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"The Executors — understand this deeply","type":"text"}],"id":"a15e6961-cb16-45b6-ad27-622fc1f87a55","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Executors are the actual workers. Each Executor:","type":"text"}],"id":"7e057b12-3f75-4065-a091-f03cadb20672","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Runs on one node in the cluster","type":"text"}],"id":"e380c114-28c9-41b9-8a68-fed708e25b56","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Has a set amount of CPU cores and RAM","type":"text"}],"id":"364e31af-0b72-497e-9354-6b575aa1e95e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Processes its chunk of data","type":"text"}],"id":"26027fc7-5be7-4820-aeed-b439b8750238","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Stores results in memory (or spills to disk if RAM is full)","type":"text"}],"id":"d5bfadfc-d640-4955-a5d4-68bab388a33e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Reports back to the Driver","type":"text"}],"id":"251c2090-5f6f-4612-adde-ad6e260ca583","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"The Cluster Manager","type":"text"}],"id":"238aca03-857f-43f9-aa94-751003ee5845","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The Cluster Manager sits above everything and decides:","type":"text"}],"id":"2bc5583f-e172-4511-9c68-16bfa29087b3","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Which machines are available","type":"text"}],"id":"2c5ae364-665a-4cc8-9a8c-f4c99f7d9b74","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"How much memory and CPU each Executor gets","type":"text"}],"id":"43c3f90d-b097-416f-95ca-561e4a7d55f5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Where to schedule new jobs","type":"text"}],"id":"07025992-90cd-4959-a4da-3115dcdbddf8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Common cluster managers: ","type":"text"},{"styles":{"bold":true},"text":"YARN","type":"text"},{"styles":{},"text":" (Hadoop ecosystem), ","type":"text"},{"styles":{"bold":true},"text":"Kubernetes","type":"text"},{"styles":{},"text":" (modern cloud), ","type":"text"},{"styles":{"bold":true},"text":"Standalone","type":"text"},{"styles":{},"text":" (Spark''s own simple manager), ","type":"text"},{"styles":{"bold":true},"text":"Mesos","type":"text"},{"styles":{},"text":" (older).","type":"text"}],"id":"d9855aa5-7d4b-4baf-a7da-0bb494ce35d4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Practice: Draw This From Memory","type":"text"}],"id":"4cc264f0-6e08-4f9b-8b5b-fb0b60e53022","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Close this note and draw the three-tier diagram (Cluster Manager → Driver → Executors) with bullet points for each role. If you can draw and explain it in 2 minutes, you''ve got it.","type":"text"}],"id":"e715d5b8-6d17-4185-887a-dac059d85c5d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"6eb5f3cf-b0fe-4334-91b0-acb2fbd63cfe","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"SECTION 3 — How Data is Split: Partitions","type":"text"}],"id":"f4d7bb1f-bceb-4350-bf7f-8f2113f78351","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The most important low-level concept","type":"text"}],"id":"2ebd0529-d0ce-4bce-bac5-c0c2de929062","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"When Spark reads a dataset, it doesn''t give the whole thing to one Executor. It ","type":"text"},{"styles":{"bold":true},"text":"splits the data into partitions","type":"text"},{"styles":{},"text":" — chunks that can be processed independently and in parallel.","type":"text"}],"id":"5456a67e-a0f9-4075-bf14-2eb8b3740ac9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Dataset: 1,000,000 rows\nPartitions: 10\nEach partition: 100,000 rows\n\nExecutor 1 → processes partition 1 (rows 1-100k)\nExecutor 2 → processes partition 2 (rows 100k-200k)\n...\nExecutor 10 → processes partition 10 (rows 900k-1M)\n\nAll happening simultaneously = parallel processing","type":"text"}],"id":"c323f270-efee-4492-b5f4-3b470400171f","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Partitions and parallelism","type":"text"}],"id":"4b1a0899-03a8-40ea-b97d-1498d0bd8ccc","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"More partitions = more parallelism (up to the number of CPU cores available)","type":"text"}],"id":"1db555d6-4edb-40d5-9305-335e422a3a98","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Too few partitions = some cores sit idle (underutilization)","type":"text"}],"id":"6e2486ea-fbe0-4b0e-bdef-f039a6f03519","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Too many partitions = too much scheduling overhead","type":"text"}],"id":"b6d07916-4315-495b-9588-fea702513a4e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Rule of thumb:","type":"text"},{"styles":{},"text":" 2-4 partitions per CPU core in your cluster","type":"text"}],"id":"567d5a85-758c-4397-b71a-c638003faa83","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Controlling partitions in PySpark","type":"text"}],"id":"83e2e9f6-a7e1-4d4b-851d-c510facdff53","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# Check how many partitions a DataFrame has\ndf.rdd.getNumPartitions()\n\n# Increase partitions (when you have too few)\ndf = df.repartition(100)\n\n# Decrease partitions (when you have too many — more efficient than repartition)\ndf = df.coalesce(10)","type":"text"}],"id":"e01bc57e-0235-4464-8912-d11e4265b8d5","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"code":true},"text":"repartition","type":"text"},{"styles":{},"text":" vs ","type":"text"},{"styles":{"code":true},"text":"coalesce","type":"text"},{"styles":{},"text":" — classic interview question","type":"text"}],"id":"8bae0151-a637-4b56-96ba-3aa4fe1d40d8","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":{"columnWidths":[null,null,null],"headerRows":1,"rows":[{"cells":[{"content":[],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"code":true},"text":"repartition","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"code":true},"text":"coalesce","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Direction","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Can increase OR decrease","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Can only decrease","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Shuffle","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"YES — full shuffle","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"NO — avoids shuffle","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Use when","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Need more parallelism, or need even distribution","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Need to reduce partitions before writing output","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Speed","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Slower (shuffle cost)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Faster (no shuffle)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"bc6f28e4-3e84-47b1-b36d-7ee6d5040d31","props":{"textColor":"default"},"type":"table"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why does this matter?","type":"text"},{"styles":{},"text":" Before writing output files, you often ","type":"text"},{"styles":{"code":true},"text":"coalesce(1)","type":"text"},{"styles":{},"text":" to write one file instead of one file per partition. But coalesce on a large dataset = one Executor doing all the work. Trade-offs everywhere.","type":"text"}],"id":"b1fc16fa-3bc8-4705-8f59-8a5205d6f0d1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"674213f6-3253-4c82-9e2a-9c1e3574eb7b","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"SECTION 4 — RDD vs DataFrame vs Dataset","type":"text"}],"id":"279efb25-eeb4-4edd-9996-f5d7da40254c","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The three abstractions — know all three, use DataFrame","type":"text"}],"id":"5c8e97fa-f5a2-4096-91f2-7d59d3690928","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"RDD (Resilient Distributed Dataset) — the original","type":"text"}],"id":"994485ac-935b-4740-9977-1a8b818dd2e1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Spark''s fundamental data structure (2012)","type":"text"}],"id":"241b6635-10db-4478-8697-a50e492f3bb4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"A distributed collection of objects — like a distributed Python list","type":"text"}],"id":"d658dfbc-5512-4c3a-a992-9afb2ca6c182","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"No schema, no column names — just objects","type":"text"}],"id":"05dc0a80-8238-4493-8cf6-9f7670a0a7c3","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"You write low-level code to manipulate it","type":"text"}],"id":"fe861f80-22c7-4832-9a92-fb3f9f4e4420","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Still exists under the hood of everything","type":"text"}],"id":"684e9653-d08a-48db-b730-a6cb5a5c4f58","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"rdd = sc.parallelize([1, 2, 3, 4, 5])\nrdd.map(lambda x: x * 2).collect()   # [2, 4, 6, 8, 10]","type":"text"}],"id":"f84ecaf2-adb0-4da5-bf6e-a068d5fa54bd","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"DataFrame — what you actually use","type":"text"}],"id":"0d3c85b0-ae22-4474-a378-fec572dec0ab","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Built on top of RDD but adds schema (column names + types)","type":"text"}],"id":"d1760756-592a-49d2-a25f-9a8c2e2fde0a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Looks exactly like a pandas DataFrame or a SQL table","type":"text"}],"id":"7b373ec6-b9f3-45b5-9a1c-3061c907da91","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Uses Spark''s Catalyst optimizer (explained in Section 6) — much faster","type":"text"}],"id":"60c94527-33c9-49d8-88db-9b762c891e19","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"This is what all modern PySpark code uses","type":"text"}],"id":"2e035e56-9515-4229-a7f2-e8e39457f788","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"df = spark.read.csv(\"sales.csv\", header=True, inferSchema=True)\ndf.groupBy(\"region\").sum(\"amount\").show()","type":"text"}],"id":"129cc698-d930-4774-b160-3307147bd678","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Dataset — typed DataFrame (mostly Java/Scala)","type":"text"}],"id":"f4044231-91c2-4d86-bfa5-acb373d91556","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"DataFrame + compile-time type safety","type":"text"}],"id":"2fd54efc-bef0-4bc9-816f-5e00070dff69","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Not used in Python (Python is dynamic, can''t have compile-time types)","type":"text"}],"id":"e973a4a9-4a91-4c59-98e4-887ec966b915","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"You will not write Dataset code in Python — just know it exists","type":"text"}],"id":"5016ab5e-d47d-4d3d-91c3-913387460e84","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"The relationship between them","type":"text"}],"id":"830c5dc8-11c8-4924-b6d2-7de960de1fea","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"RDD (foundation — distributed, untyped)\n └── DataFrame (structured, optimized — what you use in PySpark)\n      └── Dataset (typed — Java/Scala only)","type":"text"}],"id":"1d03985d-cf47-44b6-9a9c-ca16e89f0a6e","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Interview one-liner","type":"text"}],"id":"c2061e06-c70e-4006-9905-d37cf5e2b076","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"In PySpark I work with DataFrames — they give me SQL-like operations with Spark''s Catalyst optimizer for performance, while RDDs sit underneath as the lower-level abstraction. I''d only drop to RDD-level for operations that can''t be expressed as DataFrame transformations.\"","type":"text"}],"id":"5345bf89-38a3-495f-b900-be660b72d353","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"37e9a60b-717e-43cf-aa3d-1ab9905796e9","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"SECTION 5 — Transformations vs Actions (THE Most Important Concept)","type":"text"}],"id":"90a5b33d-87ff-4915-8f45-3e8c31d7a2e0","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"This is the single most tested Spark concept in interviews","type":"text"}],"id":"7cf306e6-2720-478a-b06a-b9091c54389f","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"The core idea — lazy evaluation","type":"text"}],"id":"176c664e-f26e-41ba-9ba0-213680fffb99","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Spark does NOT execute your code line by line. When you write transformations, Spark just ","type":"text"},{"styles":{"bold":true},"text":"records what you want to do","type":"text"},{"styles":{},"text":" — it does not actually do it. It waits until you trigger an ","type":"text"},{"styles":{"bold":true},"text":"action","type":"text"},{"styles":{},"text":", then executes everything at once.","type":"text"}],"id":"408d857a-6586-4c87-a798-e292d3c883a3","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"df = spark.read.csv(\"sales.csv\", header=True)   # nothing executes yet\ndf2 = df.filter(df.amount > 100)                 # nothing executes yet\ndf3 = df2.groupBy(\"region\").sum(\"amount\")         # nothing executes yet\n\ndf3.show()   # <-- THIS triggers execution of ALL the above steps","type":"text"}],"id":"9dea0d33-d0fd-426a-b9ca-8c440af29d15","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Why lazy evaluation exists","type":"text"}],"id":"5710c7aa-a4bd-41dd-92eb-a6ed27acc4e0","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Spark collects all your transformations first, then ","type":"text"},{"styles":{"bold":true},"text":"optimizes the entire plan","type":"text"},{"styles":{},"text":" before running anything. This means Spark can:","type":"text"}],"id":"1a8b81e0-2c12-4c3d-8107-6c72e0e6dd8d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Reorder operations for efficiency","type":"text"}],"id":"a5671780-4009-4dfc-8669-2ffeeed324a8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Push filters down closer to the data source (read less data)","type":"text"}],"id":"c83c13d5-5c56-49d7-b38a-7f8ed7dc1b84","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Combine multiple steps into one","type":"text"}],"id":"2997f479-402b-4d12-8c15-ccb1caa50bba","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Skip steps whose results aren''t actually needed","type":"text"}],"id":"a1f10d92-9013-48fb-8d44-584e5007229e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Transformations — \"record this, don''t run it yet\"","type":"text"}],"id":"3fc3ace9-22bf-48bb-b6ad-6d70817892b4","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Returns a new DataFrame/RDD. Does NOT trigger execution.","type":"text"}],"id":"d1a894ed-c579-43a3-a9a3-5d7f5d955661","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Narrow transformations","type":"text"},{"styles":{},"text":" — each partition''s output depends only on ONE input partition. No data movement between machines needed.","type":"text"}],"id":"0969c5a8-4b54-4b32-8cf7-8d520ee15631","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"df.filter(df.amount > 0)         # filter one row at a time\ndf.select(\"region\", \"amount\")    # column selection\ndf.withColumn(\"tax\", df.amount * 0.1)  # add column row by row\ndf.map(...)                      # RDD-level, one-to-one","type":"text"}],"id":"bd02eefa-49fb-4986-9ef3-895016d88990","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Wide transformations","type":"text"},{"styles":{},"text":" — output partitions depend on MULTIPLE input partitions. Requires ","type":"text"},{"styles":{"bold":true},"text":"shuffling","type":"text"},{"styles":{},"text":" data across the network.","type":"text"}],"id":"985fdda8-496f-4cd7-a810-ca67ce0ea1b0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"df.groupBy(\"region\").sum()       # needs all rows for a region together\ndf.join(other_df, on=\"id\")       # needs matching rows from both sides\ndf.orderBy(\"amount\")             # needs global sort across all partitions\ndf.distinct()                    # needs to compare across all partitions","type":"text"}],"id":"36ecc38a-420c-4bc3-8d6b-97127c48170c","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Actions — \"now actually run everything\"","type":"text"}],"id":"608824d3-deba-47ec-97e6-019d2eecc264","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Triggers execution of all pending transformations. Returns a result to the Driver.","type":"text"}],"id":"78b1136f-68b3-42be-b45c-3aca0a1429ff","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"df.show()          # print rows to console\ndf.collect()       # bring ALL rows to Driver as Python list — DANGEROUS on big data\ndf.count()         # count rows — triggers full scan\ndf.first()         # get first row\ndf.take(10)        # get first 10 rows\ndf.write.csv(...)  # write to storage — triggers execution\ndf.toPandas()      # convert to pandas DataFrame — brings all data to Driver","type":"text"}],"id":"30f28122-8f20-4060-aba8-acf0d405897b","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"The mental model — recipe vs cooking","type":"text"}],"id":"bd5a9f91-8797-4c18-9135-534da7d12759","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Transformations = writing a recipe (nothing gets cooked yet)\nActions         = putting it in the oven (everything cooks at once)","type":"text"}],"id":"df463f3f-dc4e-4f1b-a288-09952ebfbae3","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Interview gotcha: what happens if you never call an action?","type":"text"}],"id":"de127076-9a03-48d5-9301-0d599d220009","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Nothing runs. If your Spark script has only transformations and no actions, it does nothing. This is a real beginner bug.","type":"text"}],"id":"7f66660a-e2c9-47bb-9dd8-bb71f0cbfe9a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Practice: Classify These","type":"text"}],"id":"2f2a1501-51c9-41d8-83b9-05b8f20892f9","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"For each line, say \"transformation\" or \"action\" and say whether it''s narrow or wide:","type":"text"}],"id":"7607e1e0-0079-46f2-8e94-89d3ebdf46d1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"df.filter(df.amount > 100)         # ?\ndf.groupBy(\"region\").count()       # ?\ndf.show()                          # ?\ndf.select(\"id\", \"amount\")          # ?\ndf.join(other, on=\"id\")            # ?\ndf.collect()                       # ?\ndf.distinct()                      # ?\ndf.withColumn(\"x\", df.a + df.b)   # ?","type":"text"}],"id":"8e832c98-9522-44d7-a024-f0165cb42f0c","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Answers: transformation/narrow, transformation/wide, action, transformation/narrow, transformation/wide, action, transformation/wide, transformation/narrow","type":"text"}],"id":"236498d1-a09c-4bd0-b69e-0d6d9eef346a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"9d5bf44f-b8b8-480e-b0c7-4ea8ca9c11af","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"SECTION 6 — The DAG and Execution Planning","type":"text"}],"id":"953cbfb0-bd01-464e-a4d6-014325fd81cc","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"What is a DAG?","type":"text"}],"id":"539aa931-6e88-40cb-adb5-d3c763c3f17e","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"DAG = ","type":"text"},{"styles":{"bold":true},"text":"Directed Acyclic Graph","type":"text"},{"styles":{},"text":" — Spark''s internal representation of your computation as a sequence of steps with dependencies.","type":"text"}],"id":"f9555373-c718-4618-9455-1393a016e466","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"When you write PySpark code, Spark builds a DAG:","type":"text"}],"id":"012c0fb6-2675-4ee9-a9dd-48806afc029f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Read CSV ──► Filter ──► GroupBy ──► Aggregate ──► Write","type":"text"}],"id":"dc30079e-7bd8-40a6-87ad-cf79611d5bec","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"\"Directed\" = flows one way (forward) \"Acyclic\" = no loops (can''t go back)","type":"text"}],"id":"4c53d8f1-6ab0-4aec-8261-1caaa4b09a41","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Why the DAG matters for you","type":"text"}],"id":"f54f67a1-c7d2-425d-9bda-360431b9d5dc","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The DAG lets Spark ","type":"text"},{"styles":{"bold":true},"text":"optimize before running","type":"text"},{"styles":{},"text":". Example:","type":"text"}],"id":"7910a9a3-7b4a-44b4-8134-9f4d73d79d96","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"# You write:\ndf = spark.read.csv(\"huge_file.csv\")    # 100 million rows\ndf2 = df.filter(df.amount > 1000)       # maybe 10,000 rows survive\ndf3 = df2.select(\"region\", \"amount\")   # drop unnecessary columns\ndf3.show()","type":"text"}],"id":"b05c2231-0676-4f53-b278-33695013e809","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Spark sees the full DAG and realizes: ","type":"text"},{"styles":{"italic":true},"text":"\"I can push the filter down to happen AT READ TIME — I don''t need to read all 100 million rows into memory first.\"","type":"text"},{"styles":{},"text":" This is called ","type":"text"},{"styles":{"bold":true},"text":"predicate pushdown","type":"text"},{"styles":{},"text":" and it is one of Spark''s most powerful automatic optimizations.","type":"text"}],"id":"ec6bebda-eeb8-4381-a97d-e96feca12f0d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Catalyst Optimizer — the engine behind DataFrame performance","type":"text"}],"id":"fcb2c1e9-386e-4d1a-a764-e55b16d5bb2e","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"When you use DataFrames (not RDDs), your operations go through ","type":"text"},{"styles":{"bold":true},"text":"Catalyst","type":"text"},{"styles":{},"text":", Spark''s query optimizer. Catalyst:","type":"text"}],"id":"aff49edf-6374-4f09-b135-8921aef7ee69","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Parses your code into a logical plan","type":"text"}],"id":"df6f5303-9669-4c0f-9b36-c528adda2907","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Analyzes it (checks column names, types exist)","type":"text"}],"id":"ed1d5a1d-dd43-4628-b9cc-901a3e7d84c0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Optimizes it (pushes filters down, reorders joins, etc.)","type":"text"}],"id":"c8a12922-909b-4898-8454-a3ab81fe47f5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Converts to a physical plan (actual executable steps)","type":"text"}],"id":"750885ed-059f-4155-a8c4-ce35f53fcac1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Generates optimized code via ","type":"text"},{"styles":{"bold":true},"text":"Tungsten","type":"text"},{"styles":{},"text":" (Spark''s code generation engine)","type":"text"}],"id":"8a97dbf1-4485-4ab0-94bc-882b97f3cadf","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"This is why DataFrames are faster than RDDs","type":"text"},{"styles":{},"text":" — RDDs bypass Catalyst entirely. You write what you want and Spark does it literally. DataFrames let Catalyst decide the smartest way.","type":"text"}],"id":"f27b4cbc-a71c-4735-8c09-c1ad21b6be11","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Spark UI — where you see the DAG visually","type":"text"}],"id":"3bb1ec6e-243a-4df9-b564-ba055b741dc7","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"In a real Spark cluster, ","type":"text"},{"styles":{"code":true},"text":"http://localhost:4040","type":"text"},{"styles":{},"text":" shows you:","type":"text"}],"id":"afaba7a9-1088-45ec-9aeb-c122deb3088d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"The DAG for each job","type":"text"}],"id":"34e89e16-e52f-412b-87d2-87335413a1b7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Which stages completed","type":"text"}],"id":"af6a6cfd-165b-4082-b1c1-13c4a524265c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"How long each stage took","type":"text"}],"id":"362f7de9-7dfb-4eeb-bd0c-78fca7b39dc6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Shuffle read/write sizes","type":"text"}],"id":"9da963e4-5843-404c-a107-8103b855df2b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Failed tasks","type":"text"}],"id":"278f5d4f-fa9b-4a12-96b8-9de4ae7b6e23","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Interview tip:","type":"text"},{"styles":{},"text":" Mention the Spark UI when asked about debugging or performance. ","type":"text"},{"styles":{"italic":true},"text":"\"First thing I''d do is check the Spark UI to see the DAG, identify which stage is slow, and check shuffle sizes.\"","type":"text"}],"id":"78ae64ad-d5d1-413b-aee9-c52209c11009","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"41f2bbfe-7ba0-481a-aaa7-7e4e59493080","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"SECTION 7 — Jobs, Stages, and Tasks (How Execution is Organized)","type":"text"}],"id":"ca22fd0b-4236-4e8e-8c56-7744dddb0d6c","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The three-level hierarchy","type":"text"}],"id":"c940aea9-5f3a-41c4-abdf-71fdf7f265fd","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"JOB\n└── One job per action (show, count, write, etc.)\n    └── STAGES\n        └── One stage per shuffle boundary\n            └── TASKS\n                └── One task per partition","type":"text"}],"id":"f7c186d8-b283-4d8e-88eb-f893e041d385","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Example — tracing one job through this hierarchy","type":"text"}],"id":"8a4181ca-8083-4591-a4d7-fd459e610961","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"df.groupBy(\"region\").sum(\"amount\").show()","type":"text"}],"id":"f1ae023d-77c4-4d75-8722-41a3104c7d5d","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"This creates ONE JOB (because there''s one action: ","type":"text"},{"styles":{"code":true},"text":"show","type":"text"},{"styles":{},"text":")","type":"text"}],"id":"12ed7471-d298-4625-8724-792151fb1709","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Inside that job, there are TWO STAGES (because ","type":"text"},{"styles":{"code":true},"text":"groupBy","type":"text"},{"styles":{},"text":" requires a shuffle):","type":"text"}],"id":"4b10ea57-35fd-4c9d-bad9-456e0cbe7478","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Stage 1:","type":"text"},{"styles":{},"text":" Read CSV, apply any filters, do local partial aggregation on each partition","type":"text"}],"id":"af6f0277-fce7-48cb-8164-20ee38f813cd","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Stage 2:","type":"text"},{"styles":{},"text":" Shuffle data so all rows for \"South\" go to the same executor, finish aggregation","type":"text"}],"id":"855fd06d-5afb-4bdc-864f-3992381db76a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Inside each Stage, there are N TASKS where N = number of partitions","type":"text"}],"id":"dca9ea5c-605d-4011-a40e-7feb10bf7c18","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Why stage boundaries matter","type":"text"}],"id":"467fd928-d90b-42cb-ab49-9598c1249760","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"A stage boundary = a shuffle. ","type":"text"},{"styles":{"bold":true},"text":"Shuffles are expensive","type":"text"},{"styles":{},"text":" because:","type":"text"}],"id":"9c5a46a7-c785-497a-8051-bc6bfc72b201","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Data moves across the network between machines","type":"text"}],"id":"793f60d5-28c1-4859-b1c3-0f9478a31f05","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Data is written to disk during the shuffle","type":"text"}],"id":"89244606-736f-4a16-b807-7205c21d6708","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Network and disk I/O are the two slowest things in computing","type":"text"}],"id":"68612663-314c-4b5c-b6c5-cbebe297c355","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Interview insight:","type":"text"},{"styles":{},"text":" When someone says \"my Spark job is slow,\" the first thing to investigate is ","type":"text"},{"styles":{"bold":true},"text":"shuffle operations","type":"text"},{"styles":{},"text":" — how many are there, how much data is being shuffled.","type":"text"}],"id":"397edc72-b935-43da-a2f6-be883daef4e0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"e0faec95-9f5a-4522-8ffb-28f3ba877bae","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"SECTION 8 — Shuffling (The Performance Killer)","type":"text"}],"id":"400a3014-0342-4dab-9af8-9b63b084cad1","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"What exactly is a shuffle?","type":"text"}],"id":"9e4d3b4a-833f-4989-ad26-ca5f155a7665","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"A shuffle happens when Spark needs to ","type":"text"},{"styles":{"bold":true},"text":"redistribute data across partitions","type":"text"},{"styles":{},"text":" so that related rows end up on the same partition.","type":"text"}],"id":"ce8e77d7-48d8-4815-bfb0-4854ba4d44b4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"BEFORE groupBy(\"region\") shuffle:\nPartition 1: [South, North, East, South]\nPartition 2: [North, East, South, West]\nPartition 3: [East, West, North, East]\n\nAFTER shuffle:\nPartition 1: [South, South, South]   ← all South rows together\nPartition 2: [North, North, North]   ← all North rows together\nPartition 3: [East, East, East, East]\nPartition 4: [West, West]","type":"text"}],"id":"2873c6cc-bd82-4b20-8368-1b02cf1207c4","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Now each partition can do its aggregation independently.","type":"text"}],"id":"60525be2-c4df-4d74-9b4d-e6d81b07bbc2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"The cost of shuffling","type":"text"}],"id":"3b1a68b6-587a-404d-ba7f-85e295e0617f","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Network I/O:","type":"text"},{"styles":{},"text":" data travels between machines","type":"text"}],"id":"97c8ea77-afb7-49be-8dfb-262ca3ec7c1d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Disk I/O:","type":"text"},{"styles":{},"text":" intermediate shuffle data is written to disk first, then read","type":"text"}],"id":"56898c12-37a4-4204-b739-c9745cf809b9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Memory pressure:","type":"text"},{"styles":{},"text":" shuffle buffers consume Executor RAM","type":"text"}],"id":"38ed3a05-15a5-47dd-9df7-294a46f836a6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Operations that cause shuffles (wide transformations — repeat from Section 5)","type":"text"}],"id":"409430bc-29c6-4cdf-a3b7-397b54f2e018","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"groupBy\njoin\norderBy / sort\ndistinct\nrepartition (coalesce does NOT shuffle)","type":"text"}],"id":"633387de-97a6-4e45-b80c-44d6f0cbd1c9","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"How to minimize shuffle damage","type":"text"}],"id":"d6a2a2b9-2385-4395-bc6d-6e18992e2f88","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Strategy 1 — Filter before you shuffle","type":"text"}],"id":"60427800-0630-4de5-b242-bc73c7f25f2a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"# BAD: shuffle all 100M rows, then filter\ndf.groupBy(\"region\").sum().filter(col(\"sum(amount)\") > 1000)\n\n# BETTER: filter first to reduce data before shuffle\ndf.filter(df.amount > 0).groupBy(\"region\").sum()","type":"text"}],"id":"5411cb6f-986e-4d4e-87fd-0fc06a32e8a7","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Strategy 2 — Use broadcast joins for small tables","type":"text"}],"id":"70fbbb0e-d57e-47ce-9ca4-e8e03df1d5e8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"from pyspark.sql.functions import broadcast\n\n# BAD: both tables shuffle to join\ndf_orders.join(df_customers, on=\"customer_id\")\n\n# GOOD: small table (customers) is sent to every executor — no shuffle\ndf_orders.join(broadcast(df_customers), on=\"customer_id\")","type":"text"}],"id":"1c6b8771-0eae-4dd6-8018-56fd2374d47e","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"When to broadcast:","type":"text"},{"styles":{},"text":" the smaller table fits in Executor memory (typically < 10MB, configurable). Spark can also auto-broadcast based on ","type":"text"},{"styles":{"code":true},"text":"spark.sql.autoBroadcastJoinThreshold","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"94d91c92-03be-40c2-b3d2-c64a162c12b3","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Strategy 3 — Avoid unnecessary distinct/orderBy","type":"text"}],"id":"9b364cc1-ded6-4e01-9079-e8e0f90d74ab","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"# Global orderBy shuffles ALL data to sort globally\ndf.orderBy(\"amount\")   # expensive\n\n# If you only need top N, use limit first\ndf.orderBy(\"amount\", ascending=False).limit(10)   # still shuffles but less data","type":"text"}],"id":"b9983ed7-a693-4d4d-bd96-bd3c414221b2","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Strategy 4 — Partition by the join/group key upfront","type":"text"},{"styles":{},"text":" If you know you''ll always ","type":"text"},{"styles":{"code":true},"text":"groupBy(\"region\")","type":"text"},{"styles":{},"text":", partitioning the data by ","type":"text"},{"styles":{"code":true},"text":"region","type":"text"},{"styles":{},"text":" when reading means related rows are already co-located — no shuffle needed.","type":"text"}],"id":"a1e1683e-626d-4d97-bf7e-7a28c87f7320","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"81389f52-d9a5-4423-a091-cf138804c023","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"SECTION 9 — Caching and Persistence","type":"text"}],"id":"8dc3a535-4d8a-4aa7-b9c0-2ab248138d2d","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The problem without caching","type":"text"}],"id":"4775e360-f6e3-4147-9855-afd7aedd8ab5","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"df_clean = df.filter(df.amount > 0).withColumn(\"tax\", df.amount * 0.1)\n\n# Every time you use df_clean, Spark re-executes the filter and withColumn from scratch\nresult1 = df_clean.groupBy(\"region\").sum()\nresult2 = df_clean.orderBy(\"amount\").limit(10)\n# df_clean was computed TWICE — wasted work","type":"text"}],"id":"934f35d1-463a-4032-8df9-b73e25ebb032","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"The fix — cache or persist","type":"text"}],"id":"7d3b9640-cb48-4837-964a-788642539879","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"df_clean = df.filter(df.amount > 0).withColumn(\"tax\", df.amount * 0.1)\ndf_clean.cache()   # tells Spark: store this result in memory after first computation\n\nresult1 = df_clean.groupBy(\"region\").sum()   # computes df_clean, stores in memory\nresult2 = df_clean.orderBy(\"amount\").limit(10)  # reuses cached df_clean — fast\n\ndf_clean.unpersist()   # release memory when done","type":"text"}],"id":"4ad9216c-4faf-4483-8cc5-6fb400d475a9","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"code":true},"text":"cache()","type":"text"},{"styles":{},"text":" vs ","type":"text"},{"styles":{"code":true},"text":"persist()","type":"text"},{"styles":{},"text":" — the difference","type":"text"}],"id":"cd31a0d3-0bc7-430c-9cbd-2d3d88390af5","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"df.cache()   # stores in memory only (same as persist(StorageLevel.MEMORY_ONLY))\n\nfrom pyspark import StorageLevel\ndf.persist(StorageLevel.MEMORY_ONLY)          # memory only — fastest, data lost if evicted\ndf.persist(StorageLevel.MEMORY_AND_DISK)      # memory first, spill to disk if needed\ndf.persist(StorageLevel.DISK_ONLY)            # disk only — slowest but always available\ndf.persist(StorageLevel.MEMORY_ONLY_SER)      # serialized in memory — less space, more CPU","type":"text"}],"id":"4c90a142-d860-47a4-bf33-fbb4c53389e0","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"When to cache (interview answer)","type":"text"}],"id":"0fb311a6-5afe-4c29-b78d-71d8c2216d97","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"I cache a DataFrame when it''s the result of an expensive transformation and I need to use it multiple times in the same job. Without caching, Spark would recompute it from scratch every time. I always unpersist when I''m done to free Executor memory for other tasks.\"","type":"text"}],"id":"2020e31d-dbfa-414b-a3f3-8f93119c8228","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"When NOT to cache","type":"text"}],"id":"b11cf166-28ee-4339-ab66-31419ca0a3b3","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"If you only use the DataFrame once — caching wastes memory","type":"text"}],"id":"60328c10-0f7e-4235-a0c5-a0d40c4012c2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"If the DataFrame is larger than available Executor RAM — cache spills to disk, might be slower than recomputing","type":"text"}],"id":"958654f9-e1a5-4de9-a8ac-8521d3a6fc46","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"If the computation is cheap — re-running a simple filter is faster than cache overhead","type":"text"}],"id":"a1695ce7-06f1-48c1-a155-1812b919f554","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"id":"ec28ebe1-47b5-417d-8598-961fc85d7a1e","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"SECTION 10 — Memory Management in Spark","type":"text"}],"id":"b7b2e600-29cc-4327-8c29-dd2aa3aaa91a","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"How Executor memory is divided","type":"text"}],"id":"2589e8cc-dda1-4fce-b047-943566abf501","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"EXECUTOR MEMORY (e.g. 4GB total)\n├── Reserved Memory (~300MB) — Spark system use, not configurable\n├── Spark Memory (~60% of remaining) — split between:\n│   ├── Execution Memory — shuffle buffers, sort, join operations\n│   └── Storage Memory — cached DataFrames\n└── User Memory (~40% of remaining) — your Python objects, UDFs, etc.","type":"text"}],"id":"5f609910-975d-4112-9c81-f07970a1f892","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Spilling — what happens when memory fills up","type":"text"}],"id":"1b2a6d7a-6f51-42a0-9aa1-64a6c2a9f73a","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"When Execution Memory is full, Spark ","type":"text"},{"styles":{"bold":true},"text":"spills","type":"text"},{"styles":{},"text":" intermediate data to disk. This means:","type":"text"}],"id":"97110588-2605-4ae6-8998-3f3e6c7a1772","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Your job doesn''t crash (usually)","type":"text"}],"id":"51b132f0-04f2-4f78-80b3-6d0e25c1e67a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"But it slows down significantly because of disk I/O","type":"text"}],"id":"c6d85b93-5548-44b4-8070-52439824d74c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"You''ll see \"spill\" metrics in the Spark UI","type":"text"}],"id":"b723aff8-55eb-4b2a-bc64-56a082d701c0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Out of Memory errors — the most common Spark error","type":"text"}],"id":"a31736af-8ea9-4c6a-ac3a-cb51c93985a6","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"java.lang.OutOfMemoryError: GC overhead limit exceeded\norg.apache.spark.SparkException: Job aborted due to stage failure: \n  Task 0 in stage 1.0 failed: ExecutorLostFailure","type":"text"}],"id":"bd0d424d-99c2-4693-98ff-123825b070eb","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Causes:","type":"text"}],"id":"a4d978b9-8fd7-4934-985f-24fc7a8b0e69","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Too many rows in one partition (skewed data)","type":"text"}],"id":"e0d21937-2e05-4f80-9d0a-aa03856d86b7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Collecting too much data to the Driver","type":"text"}],"id":"5e9c8f84-3d0e-4d3d-9879-390d51eae077","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Caching too many DataFrames","type":"text"}],"id":"4098a22c-61c1-4aec-9b0c-780fbe8b1845","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Fixes:","type":"text"}],"id":"4121ddee-60ca-4c72-8073-502a7d7f5594","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Increase partitions (repartition) to spread data more evenly","type":"text"}],"id":"e09a382c-6048-4e78-9843-aed4df018503","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Use ","type":"text"},{"styles":{"code":true},"text":"coalesce","type":"text"},{"styles":{},"text":" carefully when writing output","type":"text"}],"id":"a3b3b896-6ec8-49b2-8eb2-3e4a4b45a838","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Avoid ","type":"text"},{"styles":{"code":true},"text":"collect()","type":"text"},{"styles":{},"text":" on large DataFrames","type":"text"}],"id":"e7ad3893-6885-40f6-be51-4fa33e4102e2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Increase Executor memory in cluster config","type":"text"}],"id":"de2a8d2f-9156-4922-95c7-a7e2e330f25c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Fix data skew (covered in Section 11)","type":"text"}],"id":"65a2fb77-1633-438c-9bfd-4e9c8de531dd","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"id":"b1c9f1df-5000-4e22-98ac-d260659fcb76","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"SECTION 11 — Data Skew (Advanced But Commonly Asked)","type":"text"}],"id":"b68f2ae8-9116-4988-9927-b293cd08dbcb","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"What is data skew?","type":"text"}],"id":"d8bac6ec-69d4-46c7-af05-d755fec67ab4","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Data skew = one partition has FAR more rows than others, causing one Executor to do most of the work while others sit idle.","type":"text"}],"id":"f0909eb8-de39-4f70-b0e2-e0ab8fe12be5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"After groupBy shuffle:\nPartition 1 (South): 50,000,000 rows   ← this Executor works for 10 minutes\nPartition 2 (North): 100 rows           ← this Executor finishes in 1 second\nPartition 3 (East):  500 rows           ← this Executor finishes in 1 second","type":"text"}],"id":"ee7a8db7-eca8-4a44-a66a-58b412632b54","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Your job takes 10 minutes because one partition is massive. The cluster is 90% idle.","type":"text"}],"id":"ca372be7-0b33-4586-bd35-470549362e4b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Why it happens","type":"text"}],"id":"7a615bbc-b7f7-4615-aaed-7d1e0761ab42","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Real-world data is rarely evenly distributed. A \"South\" region might have 1000x more transactions than \"East\". When Spark shuffles by region, all South data goes to one partition.","type":"text"}],"id":"50df64bd-f008-4078-823b-4fe29c5fd15c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"How to detect it","type":"text"}],"id":"016b6674-7724-4989-a279-8d3365f51ca8","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"In the Spark UI, look at the ","type":"text"},{"styles":{"bold":true},"text":"Tasks","type":"text"},{"styles":{},"text":" tab for a stage. If one task took 10 minutes and all others took 1 second — you have skew.","type":"text"}],"id":"397f7d9e-134b-47f4-a72d-e62f37b2f06b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"How to fix it","type":"text"}],"id":"4b810276-812b-4744-9d43-ad6ac548804f","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Approach 1 — Salting (adding a random key to spread the data)","type":"text"}],"id":"86db8448-953c-47e5-a988-cdae075b6d96","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"from pyspark.sql.functions import concat, col, lit, rand, floor\n\n# Add a random \"salt\" to the skewed key to split it into N sub-groups\nn = 10\ndf_salted = df.withColumn(\"salted_region\", concat(col(\"region\"), lit(\"_\"), (floor(rand() * n)).cast(\"string\")))\n\n# GroupBy the salted key (spreads South into South_0, South_1, ... South_9)\npartial = df_salted.groupBy(\"salted_region\").sum(\"amount\")\n\n# Remove salt and aggregate again\nfrom pyspark.sql.functions import regexp_replace\nfinal = partial.withColumn(\"region\", regexp_replace(\"salted_region\", \"_[0-9]+$\", \"\"))\n               .groupBy(\"region\").sum(\"sum(amount)\")","type":"text"}],"id":"29a6a64f-c304-4ed8-a56e-2a2416a32eaa","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Approach 2 — Broadcast join for skewed joins","type":"text"},{"styles":{},"text":" If one side of a join is small, broadcast it to avoid the shuffle entirely.","type":"text"}],"id":"6372ecda-05ea-4009-a37f-ec89b66e8372","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Approach 3 — Skew hint (Spark 3.0+)","type":"text"}],"id":"c8058e93-cb40-4ab8-82cb-8d4b3c06ba86","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"df.hint(\"skew\", \"region\")   # tells Spark''s AQE to handle skew automatically","type":"text"}],"id":"e528ee11-d5ea-42e3-8395-98103c94464c","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Adaptive Query Execution (AQE) — Spark 3.0+ auto-fix","type":"text"}],"id":"5dba67a1-902b-4085-9128-cf5ef099f354","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Spark 3.0 introduced AQE, which dynamically adjusts the execution plan based on runtime statistics:","type":"text"}],"id":"807d05ac-0260-4f2d-8111-345a951da169","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Automatically merges small partitions after a shuffle","type":"text"}],"id":"bedb2fb3-cca2-46e7-8b03-c908fe2ce4ea","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Automatically converts sort-merge joins to broadcast joins when one side turns out small","type":"text"}],"id":"016c92d2-d7cb-4fbd-aeea-5a3f7dbc3437","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Automatically handles some skew scenarios","type":"text"}],"id":"22c8fbff-98ff-4f21-b47f-cb6c30b4a54f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"spark = SparkSession.builder \\\n    .config(\"spark.sql.adaptive.enabled\", \"true\") \\\n    .getOrCreate()","type":"text"}],"id":"0267cf04-37ed-473a-bc80-70ff301fa819","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Interview tip:","type":"text"},{"styles":{},"text":" ","type":"text"},{"styles":{"italic":true},"text":"\"For Spark 3.0+ I enable AQE first and let Spark handle skew automatically. For older versions or severe skew, I use salting.\"","type":"text"}],"id":"fbac3ed5-357f-468b-8921-a52c631679c3","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"9844ae7d-c6a2-4728-b857-8e1fe7bea763","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"SECTION 12 — Spark Session and Configuration","type":"text"}],"id":"44db4dac-d37d-4b0f-8d93-ce72c7a8e576","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"SparkSession — your entry point to everything","type":"text"}],"id":"98f9c627-c66c-407f-898b-6314d581ef7f","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"from pyspark.sql import SparkSession\n\nspark = SparkSession.builder \\\n    .appName(\"SalesPipeline\") \\\n    .master(\"local[*]\") \\           # local[*] = use all local cores (for dev/testing)\n    .config(\"spark.executor.memory\", \"4g\") \\\n    .config(\"spark.executor.cores\", \"2\") \\\n    .config(\"spark.sql.shuffle.partitions\", \"200\") \\  # default is 200 — tune this\n    .getOrCreate()","type":"text"}],"id":"fbe0461e-ab7a-4799-9ece-bd47e98f49b0","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Key config parameters to know","type":"text"}],"id":"3efe0c4d-b52f-430d-ae27-92ca31d28288","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":{"columnWidths":[null,null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Config","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Default","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"What it does","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"spark.executor.memory","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"1g","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"RAM per Executor","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"spark.executor.cores","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"1","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"CPU cores per Executor","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"spark.sql.shuffle.partitions","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"200","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Partitions created after a shuffle","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"spark.sql.autoBroadcastJoinThreshold","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"10MB","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Tables smaller than this are auto-broadcast","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"spark.sql.adaptive.enabled","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"true (Spark 3.x)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Enable AQE","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"c6e2e553-9a0f-4118-993f-6229cbc69fd4","props":{"textColor":"default"},"type":"table"},{"children":[],"content":[{"styles":{"code":true},"text":"local[*]","type":"text"},{"styles":{},"text":" vs cluster mode","type":"text"}],"id":"31a5fda9-a045-4f53-bac5-83d47962fd68","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"code":true},"text":"local[*]","type":"text"},{"styles":{},"text":" — runs on your laptop, uses all cores. For learning and testing.","type":"text"}],"id":"6f0b7462-2bda-452e-b00c-f78af386c011","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"code":true},"text":"yarn","type":"text"},{"styles":{},"text":" or ","type":"text"},{"styles":{"code":true},"text":"k8s","type":"text"},{"styles":{},"text":" — real cluster mode. For production.","type":"text"}],"id":"8a0796cc-57f8-4986-b633-166ee91b0648","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"In interviews, you''ll write ","type":"text"},{"styles":{"code":true},"text":"local[*]","type":"text"},{"styles":{},"text":" because there''s no real cluster. Just know that in production you''d change the master URL to point to your cluster.","type":"text"}],"id":"04534c14-c779-4220-b6a4-f48a25748285","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"SparkContext vs SparkSession","type":"text"}],"id":"f1014e1f-d575-4397-8e2c-6a160c4a32c8","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"SparkContext (sc):","type":"text"},{"styles":{},"text":" the old entry point (Spark 1.x), connects to the cluster","type":"text"}],"id":"190bb390-43be-445b-89e9-1949542ca9f7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"SparkSession (spark):","type":"text"},{"styles":{},"text":" the modern entry point (Spark 2.0+), wraps SparkContext, adds SQL and DataFrame support","type":"text"}],"id":"2078ca46-56ee-456f-bc5f-48783db24b1a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"SparkSession creates a SparkContext internally — you almost never touch SparkContext directly anymore","type":"text"}],"id":"6928016f-fc0d-4408-8f4d-60ec3be535bb","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"id":"13c07f66-7b8e-44bc-9199-1803b0861440","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"SECTION 13 — Reading and Writing Data in Spark","type":"text"}],"id":"8abd09c6-34d9-423a-8a6f-94b7e8be7cc9","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Reading — the DataFrameReader API","type":"text"}],"id":"5b3057b9-35a8-46cb-8f8f-7e26e5fe2b74","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# CSV\ndf = spark.read.csv(\"path/to/file.csv\", header=True, inferSchema=True)\ndf = spark.read.option(\"header\", True).option(\"inferSchema\", True).csv(\"path/\")\n\n# JSON\ndf = spark.read.json(\"path/to/file.json\")\n\n# Parquet (the preferred format for DE)\ndf = spark.read.parquet(\"path/to/data.parquet\")\n\n# From a database\ndf = spark.read.format(\"jdbc\") \\\n    .option(\"url\", \"jdbc:postgresql://host/db\") \\\n    .option(\"dbtable\", \"sales\") \\\n    .option(\"user\", \"user\") \\\n    .option(\"password\", \"pass\") \\\n    .load()","type":"text"}],"id":"a4df66f0-92e9-4d1f-a5b5-f994ac4f8faa","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Writing — the DataFrameWriter API","type":"text"}],"id":"15f21a7a-c681-4560-96c4-37f7c963d6c9","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# CSV — one file per partition (use coalesce to control file count)\ndf.coalesce(1).write.csv(\"output/\", header=True, mode=\"overwrite\")\n\n# Parquet — preferred for data lakes\ndf.write.parquet(\"output/\", mode=\"overwrite\")\n\n# Partitioned write — creates folder structure (year=2024/month=01/)\ndf.write.partitionBy(\"year\", \"month\").parquet(\"output/\", mode=\"overwrite\")\n\n# Modes\n# \"overwrite\" — replace existing data\n# \"append\"    — add to existing data\n# \"ignore\"    — do nothing if data exists\n# \"error\"     — throw error if data exists (default)","type":"text"}],"id":"70ccf63c-0324-4d37-a551-95f0a237aa4e","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Why Parquet? (You WILL be asked this)","type":"text"}],"id":"1d221997-5a00-4656-bc7c-62d96be2429c","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"CSV:     text-based, row-oriented, slow for analytics, no compression by default\nJSON:    text-based, schema flexible, slow for analytics\nParquet: columnar, compressed, fast for analytics, schema embedded in file","type":"text"}],"id":"5632517f-d4a3-4c28-b768-8aee2d8471c0","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Columnar format explained:","type":"text"}],"id":"78ce8bce-9566-43cb-ad67-f02b1915682e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Row format (CSV/JSON):\nRow 1: [id=1, region=South, amount=250, date=2024-01-01]\nRow 2: [id=2, region=North, amount=150, date=2024-01-01]\n\nIf I only need the ''amount'' column, I still read ALL columns → wasteful\n\nColumnar format (Parquet):\nColumn id:     [1, 2, 3, 4...]\nColumn region: [South, North, East, West...]\nColumn amount: [250, 150, 300, 100...]  ← I read ONLY this column\nColumn date:   [2024-01-01, ...]\n\nReading only ''amount'' = reading only 1/4 of the data → 4x faster","type":"text"}],"id":"31d66144-e7a5-44f5-9ef5-7e8a5fd38294","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Interview one-liner:","type":"text"},{"styles":{},"text":" ","type":"text"},{"styles":{"italic":true},"text":"\"I default to Parquet for intermediate and output data in Spark pipelines — it''s columnar so analytics queries only read the columns they need, it compresses well (often 5-10x smaller than CSV), and it preserves schema so I don''t need to re-specify types on every read.\"","type":"text"}],"id":"1b07138c-7b9c-4fa3-b738-f0cde88676a2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"e0908947-3bb6-4b65-8b7a-e533a42d494a","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"SECTION 14 — Fault Tolerance (Why \"Resilient\" in RDD)","type":"text"}],"id":"25579eef-303f-4387-9e21-7d2c7ba20e57","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The problem","type":"text"}],"id":"785ea58a-cb01-477b-931d-d3d0b2c8613f","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"When you have 100 machines, at any given moment some of them will fail — disk errors, network issues, hardware faults. Your job should not crash just because one machine failed.","type":"text"}],"id":"4248792e-7e14-49ff-9ce4-1fd63734e41b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"How Spark handles it — Lineage","type":"text"}],"id":"d6376688-b7bc-4cdd-9a61-893d81bfb840","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Spark tracks the ","type":"text"},{"styles":{"bold":true},"text":"lineage","type":"text"},{"styles":{},"text":" of every RDD/DataFrame — the exact sequence of transformations that created it.","type":"text"}],"id":"503dd158-bc5e-447b-82cb-c362e8907ba4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"sales.csv\n    └── filter(amount > 0)\n         └── groupBy(region)\n              └── sum(amount)","type":"text"}],"id":"535c4aec-9fcb-45bd-88b9-62cebddc0d2f","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"If Executor 3 fails while processing partition 7, Spark knows:","type":"text"}],"id":"fc1ab9b1-599f-4217-902e-e6801e60ec90","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Partition 7 came from reading rows 600k-700k of sales.csv","type":"text"}],"id":"01360374-86f0-4d87-884e-ee56aaec97b9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"It needs to apply filter, then groupBy, then sum","type":"text"}],"id":"4d91c402-8ff1-4494-8136-1cd1c0b94fdd","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Spark simply ","type":"text"},{"styles":{"bold":true},"text":"recomputes partition 7 from scratch","type":"text"},{"styles":{},"text":" on a different Executor","type":"text"}],"id":"de020fe2-1ce3-4edb-8678-687a4bf82b90","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"No data is lost. No job restarts. Just that one partition gets recomputed.","type":"text"}],"id":"f2e4dd5c-3cc6-48d4-b0fe-ae46454e5d8d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Why caching interacts with fault tolerance","type":"text"}],"id":"768d6856-041c-492f-a82a-22d3e04ab083","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"If you''ve cached a DataFrame and a node holding cached data fails, Spark recomputes the lost partitions from lineage — but this takes time. If recomputation is cheap, no need to replicate cache. If the computation is expensive, use ","type":"text"},{"styles":{"code":true},"text":"MEMORY_AND_DISK_2","type":"text"},{"styles":{},"text":" storage level which replicates to 2 nodes.","type":"text"}],"id":"5aac7190-e2e6-46a7-a08d-5b87e9541d57","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"b55d0927-d782-4493-9ef1-7639a5f067c9","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"SECTION 15 — Spark vs pandas — When to Use Which","type":"text"}],"id":"7df5d5ad-3a19-439d-9b81-f2f8fccb2069","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"This comes up in almost every interview. Have a clear, confident answer.","type":"text"}],"id":"9f56f6cb-926c-4b3a-a9b3-54936ebf5a24","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Situation","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Use","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Data fits comfortably in one machine''s RAM","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"pandas","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Quick exploration, one-time analysis","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"pandas","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Data is larger than one machine can handle","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Spark","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Need distributed, parallel processing","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Spark","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Part of a production pipeline processing terabytes daily","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Spark","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Building ML features on huge datasets","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Spark (MLlib)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"7e1ac340-d69a-4351-a25b-188cca2ae754","props":{"textColor":"default"},"type":"table"},{"children":[],"content":[{"styles":{},"text":"Pandas API on Spark (Spark 3.2+)","type":"text"}],"id":"afdbda17-5fb5-48a1-b0b8-c41004051c4c","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"import pyspark.pandas as ps   # write pandas-like code, executes on Spark\n\ndf = ps.read_csv(\"huge_file.csv\")   # but distributed!\ndf.groupby(\"region\")[\"amount\"].sum()","type":"text"}],"id":"c6dfed49-8f01-48a2-805c-cffa3427a5b5","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"This lets you write familiar pandas syntax that runs on a Spark cluster — good to mention as a bridge between the two worlds.","type":"text"}],"id":"46eec425-5781-4ca6-a93e-d88fdc5b5790","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"c958cf9b-6f8b-4dc2-ac9b-280ea18c38af","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"🎤 Scenario-Based Interview Questions","type":"text"}],"id":"29fc246b-7677-4f4b-bc1b-c2fc0498568b","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"What is Apache Spark and how is it different from Hadoop MapReduce?\"","type":"text"},{"styles":{},"text":" → Spark keeps intermediate results in memory, making it 10-100x faster than MapReduce which writes to disk after every step.","type":"text"}],"id":"e63933b7-9a52-4915-aaba-9edcfc1241a3","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"Explain the difference between a transformation and an action.\"","type":"text"},{"styles":{},"text":" → Transformations are lazy — they build a plan but don''t execute. Actions trigger execution of all pending transformations. Examples: filter/groupBy = transformations; show/collect/count = actions.","type":"text"}],"id":"114c622d-3878-409e-8034-b7fcbec7fdef","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"What is a shuffle and why is it expensive?\"","type":"text"},{"styles":{},"text":" → A shuffle redistributes data across partitions over the network. It involves disk I/O and network I/O — the two slowest operations in distributed systems. Minimizing shuffles is the most important Spark optimization.","type":"text"}],"id":"b447bb3b-64a5-4f4c-8047-6e3579eea112","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"Your Spark job is running very slowly. How do you debug it?\"","type":"text"},{"styles":{},"text":" → Check Spark UI: look at stage durations, task timings, shuffle read/write sizes. Identify the slowest stage. Check for data skew (one task much slower than others). Check for excessive shuffles.","type":"text"}],"id":"52118f04-916f-47c4-ac48-352b9b40d26e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"What is data skew and how do you fix it?\"","type":"text"},{"styles":{},"text":" → Skew = one partition has far more data than others, causing one Executor to do most work. Fix with salting, broadcast joins, or AQE in Spark 3.0+.","type":"text"}],"id":"2002b797-c7ca-4f1d-8ab3-dd136bc63c2a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"When would you use cache() in Spark?\"","type":"text"},{"styles":{},"text":" → When a DataFrame is expensive to compute and reused multiple times in the same job. Without caching, Spark recomputes it from scratch each time.","type":"text"}],"id":"75dbc798-6b80-45ef-a288-ad4d54952471","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"What is the difference between repartition and coalesce?\"","type":"text"},{"styles":{},"text":" → repartition can increase or decrease partitions but causes a full shuffle. coalesce can only decrease and avoids shuffle — use coalesce before writing output.","type":"text"}],"id":"9a08421f-0bb8-4917-b47e-411b2c295534","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"Why is Parquet preferred over CSV in data pipelines?\"","type":"text"},{"styles":{},"text":" → Parquet is columnar (reads only needed columns), compressed (smaller files), and schema-aware (no need to re-specify types). Much faster for analytical queries.","type":"text"}],"id":"ffe9fd61-a7c0-4e20-a5fa-51587ce1ee55","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"What is lazy evaluation and why does Spark use it?\"","type":"text"},{"styles":{},"text":" → Spark doesn''t execute transformations immediately — it builds a DAG and optimizes the full plan before execution. This allows Catalyst to push filters down, eliminate unnecessary steps, and choose optimal join strategies.","type":"text"}],"id":"395dbb86-a53e-4485-a096-a2863100e082","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"What is the role of the Driver in a Spark cluster?\"","type":"text"},{"styles":{},"text":" → The Driver runs your application code, builds the execution plan, coordinates Executors, and collects results. It''s the \"brain\" — it does not process data itself, that''s the Executors'' job.","type":"text"}],"id":"0c92d7aa-216a-4a3e-a6cb-42c5c9893eb4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"id":"07a7862a-2e4d-4ade-b522-21fe6cce9b6c","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"✅ Study & Practice Checklist","type":"text"}],"id":"acf2efbf-fbda-4f70-8023-b22ea95f7033","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Section 1 — What Spark is and why it exists (write the one-liner from memory)","type":"text"}],"id":"9fc68428-fba9-40b9-9503-2316a45148d0","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Section 2 — Cluster model: draw Driver/Executor/ClusterManager diagram from memory","type":"text"}],"id":"0b086ea7-d2ec-4f79-aea9-9e7732c3e611","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Section 3 — Partitions: explain repartition vs coalesce out loud","type":"text"}],"id":"b0939583-71ee-4a51-9aeb-8197e7c29d99","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Section 4 — RDD vs DataFrame vs Dataset: explain the hierarchy","type":"text"}],"id":"ba9c7ef3-7722-4ab5-9578-20b91b684496","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Section 5 — Transformations vs Actions: ","type":"text"},{"styles":{"bold":true},"text":"classify 10 operations without looking","type":"text"},{"styles":{},"text":" — most tested","type":"text"}],"id":"8bdf299c-9664-4e24-975a-d6076d6d4054","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Section 6 — DAG and Catalyst optimizer: explain predicate pushdown in your own words","type":"text"}],"id":"31f6290f-3c7d-4638-988f-bb3d26bb67d9","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Section 7 — Jobs, Stages, Tasks: trace one groupBy job through all three levels","type":"text"}],"id":"8c6b38a0-cf70-4abc-87ad-899ae82ca6da","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Section 8 — Shuffling: name all operations that cause shuffles, explain broadcast join","type":"text"}],"id":"f33c186e-b784-476f-9a3c-d24a98b7a778","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Section 9 — Caching: explain when to cache and when not to","type":"text"}],"id":"302c4f89-2a4b-4a76-abb5-9d16d6b797eb","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Section 10 — Memory management: explain what spilling is and why OOM errors happen","type":"text"}],"id":"da582877-b4c4-4294-b539-b7eaa4a81b00","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Section 11 — Data skew: explain the problem and at least one solution","type":"text"}],"id":"bec16e48-a88c-4649-9638-b311586ca0c8","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Section 12 — SparkSession: write a basic SparkSession creation from memory","type":"text"}],"id":"4d1dc512-d746-4a42-bc85-82e42df830cd","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Section 13 — Reading/writing: explain why Parquet is preferred","type":"text"}],"id":"9cb71bd7-fb98-4501-980f-15df8bb7f6cb","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Section 14 — Fault tolerance: explain lineage in your own words","type":"text"}],"id":"905e8e51-17cb-48d2-9c5a-6732063ccf23","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Section 15 — Spark vs pandas: give a clear, confident answer on when to use each","type":"text"}],"id":"3881f976-a1f7-44e3-affe-38b07eb302e5","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Answer all 10 scenario questions out loud, unscripted","type":"text"}],"id":"774ad973-67fc-4ae7-b724-b32e587d2b06","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"id":"f4d181d5-0be9-4fb5-b63f-a1f6fb2bf0cf","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"When you can draw the cluster diagram, classify any operation as transformation or action without hesitation, explain shuffling and why it is expensive, and answer all 10 scenario questions fluently — you have the Spark architecture foundation that makes your PySpark code meaningful rather than just memorized syntax.","type":"text"}],"id":"18acf85f-160b-4a31-8f06-0c9ad24e4086","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Next: the PySpark coding note builds directly on every concept here. Every PySpark operation will make sense because you now know what is happening underneath it.","type":"text"}],"id":"9495fb5d-156b-408d-8f7a-4f44e224612a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[],"id":"3b2e9932-3e19-450a-b306-da6b7d95be38","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"}]'::jsonb, '3e9e3dd3-a59b-4b02-968a-ee95e7317583') ON CONFLICT ("node_id") DO UPDATE SET "bad_example" = EXCLUDED."bad_example", "completed_at" = EXCLUDED."completed_at", "created_at" = EXCLUDED."created_at", "definition" = EXCLUDED."definition", "good_example" = EXCLUDED."good_example", "is_completed" = EXCLUDED."is_completed", "key_points" = EXCLUDED."key_points", "last_edited" = EXCLUDED."last_edited", "map_id" = EXCLUDED."map_id", "mental_model" = EXCLUDED."mental_model", "notes" = EXCLUDED."notes", "resources" = EXCLUDED."resources", "rich_content" = EXCLUDED."rich_content", "user_id" = EXCLUDED."user_id";
INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-06-14T14:53:48.355528+00:00', '', '', 'ccfaa4d0-2db4-4e4e-abd6-93763e276581', false, '[]'::jsonb, '2026-06-14T14:53:50.245+00:00', '2ad473fe-77dd-481e-8ba7-4b2b0336173f', '', '798c3e29-fef0-477d-988c-1feffce19353', '', '[]'::jsonb, '[{"children":[],"content":[{"styles":{},"text":"🐍 Python Interview Think-Aloud Strategy — Complete Interview-Ready Note","type":"text"}],"id":"73312c92-be31-44cc-90a5-9f204d05fe97","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Data Engineering Intern / Junior DE · Sysco LABS · EY GDS · Dialog Axiata","type":"text"}],"id":"4be31472-1fb9-4ec0-b600-e21ccd7e90c1","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"id":"086f5005-7014-4788-af09-401dbf602e46","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"1. 🧠 Mental Model — Python Interviews are Problem Decomposition and Clean Coding Tests","type":"text"}],"id":"64972b09-aa5e-4992-abd3-daf999253e12","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The Core Idea","type":"text"}],"id":"0ab496c5-c2a4-4c25-a85b-ff3b532b5afa","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"The interviewer is not testing whether you can write the most efficient algorithm. They are testing whether you can think clearly, code cleanly, and communicate your reasoning.","type":"text"}],"id":"da6b2d42-3fa6-46bc-9f9d-83bbcb1209a4","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{},"text":"When a senior engineer at Sysco LABS or EY GDS gives you a Python coding question, they already know you can write basic Python — that''s on your CV. What they are actually testing is:","type":"text"}],"id":"03c98399-ad4c-4633-ac4c-160237bda670","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"What They''re Listening For","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"What This Signals","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Can you clarify input/output before coding?","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"You don''t jump to solutions before understanding the problem","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Can you break a problem into logical steps?","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"You think in decomposition — a core engineering skill","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Can you write readable, maintainable code?","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"You write code others can work with, not just code that runs","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Do you handle edge cases?","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"You think beyond the happy path — production mindset","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Can you explain your reasoning while coding?","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"You can collaborate and communicate — essential for teams","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"819223f1-d958-4034-a777-f6caa2b76479","props":{"textColor":"default"},"type":"table"},{"children":[],"content":[{"styles":{},"text":"The Code Monkey vs The Thinking Engineer","type":"text"}],"id":"423b5622-2a3a-4c78-915f-0591c310ccb3","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Here''s the difference between candidates:","type":"text"}],"id":"4d0f069f-6808-4d81-870c-f8b7af779f48","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"❌ Code Monkey","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"✅ Thinking Engineer","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Starts typing immediately without clarifying anything","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Asks: \"Just to confirm — what''s the expected input format? A list of dictionaries?\"","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Writes a 20-line block of nested code in silence","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Explains: \"I''ll start by validating the input, then I''ll process each record, then return the result\"","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Gets stuck and freezes","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Says: \"I''m stuck on how to handle duplicates — let me think through two approaches\"","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Submits code without testing","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Says: \"Let me trace through this with an example to make sure it works\"","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Uses variable names like ","type":"text"},{"styles":{"code":true},"text":"x","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"lst","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"temp","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Uses ","type":"text"},{"styles":{"code":true},"text":"valid_records","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"customer_id","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"order_total","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"d2c8f50a-b02d-4cf6-ae8a-c22db513a042","props":{"textColor":"default"},"type":"table"},{"children":[],"content":[{"styles":{},"text":"The second candidate may not write faster code, but they will be perceived as ","type":"text"},{"styles":{"bold":true},"text":"far more hireable","type":"text"},{"styles":{},"text":" because they demonstrated clear thinking, communication, and engineering discipline.","type":"text"}],"id":"480350f4-fa96-4eca-b7a9-f5d41af52eeb","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"The Mindset Shift","type":"text"}],"id":"ea496268-df10-4bf0-bb41-86b8e0dd6594","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"❌ Old Mindset","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"✅ Interview-Ready Mindset","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"\"I need to code the perfect solution fast.\"","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"\"I need to show I can think clearly and write clean, testable code.\"","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"\"Silence means I''m focused.\"","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"\"Silence means the interviewer has no insight into my thinking.\"","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"\"I''ll test after I finish.\"","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"\"I''ll test as I build — with examples I say out loud.\"","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"\"One big function is fine.\"","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"\"Breaking logic into functions shows I think in reusable components.\"","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"dd2373c0-d424-47b0-84b9-86ec1acc0cce","props":{"textColor":"default"},"type":"table"},{"children":[],"content":[{"styles":{},"text":"💡 ","type":"text"},{"styles":{"bold":true},"text":"Rule:","type":"text"},{"styles":{},"text":" In a live Python interview, your verbal explanation and code structure are as important as whether the code runs correctly.","type":"text"}],"id":"793e7ba7-0459-4d74-abe4-2b873ebfea68","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"59cca6db-8b73-49e5-8a48-01f2c5049be4","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"2. 🏗️ The Python Solving Framework — 7-Step Process","type":"text"}],"id":"88ca732b-a765-4018-a439-e013ae7ff4f9","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Use this framework for every Python interview question. Practice it until it becomes automatic.","type":"text"}],"id":"2714d368-d0a0-4526-85d9-035cf8cdab59","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Step 1 — Clarify Input and Output    →  What data comes in? What should come out?\n         ↓\nStep 2 — Restate the Problem         →  Confirm understanding out loud\n         ↓\nStep 3 — Start with Simple Logic     →  Get something working first, optimize later\n         ↓\nStep 4 — Use Functions                →  Break logic into named, reusable pieces\n         ↓\nStep 5 — Handle Edge Cases            →  Empty input, None, invalid data, duplicates\n         ↓\nStep 6 — Test with Examples           →  Walk through the code with sample data out loud\n         ↓\nStep 7 — Explain Improvements         →  What would you add for production?","type":"text"}],"id":"c584d0a7-e54b-485d-b51c-3e7499339c0c","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Each Step Explained","type":"text"}],"id":"ab2f9e31-d1cd-408f-b883-b0a4919fd3c7","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"id":"3b3fab00-702d-4588-a932-5ebc40c0f655","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Step 1 — Clarify Input and Output","type":"text"}],"id":"fb3f5428-418b-4718-818a-45a9e1ddf86a","props":{"backgroundColor":"default","isToggleable":false,"level":4,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What to do:","type":"text"},{"styles":{},"text":" Before writing any code, ask about the input format and expected output format.","type":"text"}],"id":"ed4845e5-c425-4b9c-9910-5d4d9a080ad7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters:","type":"text"},{"styles":{},"text":" Python data can come in many forms — list, dict, JSON string, CSV file. Clarifying saves you from solving the wrong problem.","type":"text"}],"id":"ac99ea26-ce7d-4a44-9cb2-27ae2e0fc6d7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"What to say:","type":"text"}],"id":"8f6cc873-6604-497c-9084-2900d9925852","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"Just to confirm — the input is a list of dictionaries, where each dictionary represents a customer record? And the output should be a dictionary with customer names as keys and total spend as values?\"","type":"text"}],"id":"9445bfe4-b85f-4aaf-a60e-2bf45195a80b","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"Is the input coming from a file, or is it already a Python object in memory?\"","type":"text"}],"id":"1ca90d1f-bbfd-4327-a205-bc902e4ce250","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"Should the output be printed, returned, or written to a file?\"","type":"text"}],"id":"a3e2f0d3-157b-46e1-8f1c-64a7924cab40","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"f17cb7c4-110f-4723-8b7f-fcb90ad9de11","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Step 2 — Restate the Problem","type":"text"}],"id":"b522ade5-6c5b-4e74-81c8-31af00e75195","props":{"backgroundColor":"default","isToggleable":false,"level":4,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What to do:","type":"text"},{"styles":{},"text":" Repeat the problem in your own words out loud to confirm understanding.","type":"text"}],"id":"95096776-fa51-4719-9431-2283d74c6cdb","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters:","type":"text"},{"styles":{},"text":" Catches misunderstandings before you waste time coding the wrong solution. Also shows communication discipline.","type":"text"}],"id":"49c64c88-24a9-4b0f-9f77-082efc4aac08","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"What to say:","type":"text"}],"id":"5ed4db02-941f-4b71-b370-c86687472dc9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"So we''re reading a list of sales records, grouping them by product, calculating the total quantity sold for each product, and returning the top 5 products by quantity. Is that correct?\"","type":"text"}],"id":"aad1c52d-ab94-4b9c-a6b4-80184090d37c","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"a9bb096b-2a63-4aab-a1c9-06d2398e5f3e","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Step 3 — Start with Simple Working Logic","type":"text"}],"id":"c1c4d88c-c668-420d-80df-eafe85d29952","props":{"backgroundColor":"default","isToggleable":false,"level":4,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What to do:","type":"text"},{"styles":{},"text":" Write the simplest version that works first. Don''t try to optimize or handle every edge case on the first pass.","type":"text"}],"id":"7ef626fa-efa0-4e59-81ca-5a98dbcf42e3","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters:","type":"text"},{"styles":{},"text":" A working solution you can improve is better than a half-finished \"optimal\" solution. Interviewers value progress.","type":"text"}],"id":"b0240d96-aef4-42cc-a976-f30bbf6ead2a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"What to say:","type":"text"}],"id":"d162665a-1153-44c3-8ad8-b03fb6ab6d4e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"Let me start with the basic logic first — I''ll loop through the records, accumulate totals, then sort. I can optimize or refactor after I have something working.\"","type":"text"}],"id":"0c3695e4-5fc9-4f53-bbe5-5dcddeb1e4c3","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"81e983d2-05fc-4388-bb3d-33f540d6cb43","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Step 4 — Use Functions","type":"text"}],"id":"181d7a55-ebe2-4fa6-bc24-b2c7f49f0cb5","props":{"backgroundColor":"default","isToggleable":false,"level":4,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What to do:","type":"text"},{"styles":{},"text":" Break your logic into small, well-named functions. Even for a short problem, use at least one function.","type":"text"}],"id":"2389d881-9b0e-47d9-91bb-ff8a5b78962c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters:","type":"text"},{"styles":{},"text":" Functions show you think in reusable, testable components — a key engineering habit. They also make your code easier to explain.","type":"text"}],"id":"a4191793-0001-473b-aa7b-a572cc6e3f6d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"What to say:","type":"text"}],"id":"82db92ea-2d70-4944-8f94-bdb02860f3b4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"I''ll write a function called ","type":"text"},{"styles":{"code":true},"text":"calculate_totals()","type":"text"},{"styles":{"italic":true},"text":" that takes the list of records and returns a dictionary of totals. This makes the logic testable and reusable.\"","type":"text"}],"id":"42c29cf9-399b-4c35-9ce4-f50df98f283d","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"bold":true},"text":"Example structure:","type":"text"}],"id":"09dbe680-740c-4271-89c9-d79c20b6532b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"def process_records(records):\n    # Main logic here\n    pass\n\ndef validate_record(record):\n    # Validation logic here\n    pass","type":"text"}],"id":"0e8c33dd-b7b4-43e9-8a02-bb6012951ff6","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"5af974e8-6248-4142-bcb9-2821cf37c2a9","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Step 5 — Handle Edge Cases","type":"text"}],"id":"f952b45a-ca66-4287-8304-3ec12c29605a","props":{"backgroundColor":"default","isToggleable":false,"level":4,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What to do:","type":"text"},{"styles":{},"text":" Before finalizing, think through edge cases — empty input, None values, missing keys, invalid data types, duplicates.","type":"text"}],"id":"54804d05-bac7-451c-9438-f5ba6a4e11e6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters:","type":"text"},{"styles":{},"text":" Handling edge cases separates production-quality code from academic code. Interviewers specifically test for this.","type":"text"}],"id":"a0687841-cdea-4307-b7dc-eb9677aa4e82","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"What to say:","type":"text"}],"id":"9024f187-990b-47fc-b154-8defaddc33db","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"I should handle the case where the input list is empty — I''ll return an empty dictionary in that case.\"","type":"text"}],"id":"87a42254-3521-4bc3-8049-64f559f79f83","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"What if a record is missing the ''quantity'' field? I''ll use ","type":"text"},{"styles":{"code":true},"text":".get()","type":"text"},{"styles":{"italic":true},"text":" with a default value of 0 to avoid KeyError.\"","type":"text"}],"id":"1fba0259-01fb-4100-b28a-fe51ed44f306","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"If there are duplicate records, I''ll need to decide whether to deduplicate or sum them. Let me clarify that.\"","type":"text"}],"id":"f5a31bce-a3d4-4a12-8037-4b3d735d0ff7","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"57cf53f5-4442-42b3-b815-6a2d65903050","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Step 6 — Test with Examples","type":"text"}],"id":"63554593-e035-43e2-be25-af6d01769888","props":{"backgroundColor":"default","isToggleable":false,"level":4,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What to do:","type":"text"},{"styles":{},"text":" After writing the code, trace through it with a concrete example out loud. Show that the logic works.","type":"text"}],"id":"73d389f4-2748-4894-9213-ac4ab2de839a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters:","type":"text"},{"styles":{},"text":" This is your self-check — and it shows the interviewer you think about correctness, not just completion.","type":"text"}],"id":"f2c8f538-80bb-4b5a-81bb-5ced7c46617b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"What to say:","type":"text"}],"id":"39b2127e-98ca-4d65-92ef-9b0fc8c6632d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"Let me trace through this with an example. If the input is ","type":"text"},{"styles":{"code":true},"text":"[{''product'': ''A'', ''qty'': 10}, {''product'': ''A'', ''qty'': 5}]","type":"text"},{"styles":{"italic":true},"text":", we''d loop through, accumulate totals — product A gets 15 — and return ","type":"text"},{"styles":{"code":true},"text":"{''A'': 15}","type":"text"},{"styles":{"italic":true},"text":". That''s correct.\"","type":"text"}],"id":"e03ac2c5-e93d-41cb-b5f2-06aae4c310c2","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"badd33f4-f7a4-4e6f-a000-210657acf042","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Step 7 — Explain Improvements","type":"text"}],"id":"6b2412b9-da07-479b-9b33-c2a07b6eb68e","props":{"backgroundColor":"default","isToggleable":false,"level":4,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What to do:","type":"text"},{"styles":{},"text":" After the working solution, mention what you''d improve or add for production.","type":"text"}],"id":"22a6348d-7be0-4287-955c-203437a3398e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters:","type":"text"},{"styles":{},"text":" Shows you understand the difference between a quick solution and a robust one. Signals engineering maturity.","type":"text"}],"id":"a0347430-795a-427e-95bc-f11ba34ed5d9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"What to say:","type":"text"}],"id":"0a29576e-46ae-45c7-8eaa-702c2951f24c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"For production, I''d add more robust error handling — logging when a record fails validation rather than silently skipping it. I''d also add type hints and docstrings for maintainability.\"","type":"text"}],"id":"1325e888-9a5f-43c7-b8ad-1ce92295efb1","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"If the dataset were very large, I''d process it in chunks rather than loading everything into memory at once.\"","type":"text"}],"id":"b03418c2-2fc6-4c3b-922f-1d35c3452f94","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"fbe46e77-c6e9-43f5-a6ff-6143337f678b","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"3. 🗣️ Think-Aloud Phrases — What to Say at Each Stage","type":"text"}],"id":"61fd9ef3-3e70-4871-a690-565ff18c016b","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Here are ready-to-use phrases to verbalize your thinking at each stage of Python problem-solving:","type":"text"}],"id":"74b1d17f-e055-4c1a-bbde-91047209c2ca","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"cf8ee738-9b7d-49a9-a240-6ed8d13c9062","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Before Coding","type":"text"}],"id":"7ea9e1d7-6ab3-4a51-b2e7-4636312342b9","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"Let me make sure I understand the input and output format first.\"","type":"text"}],"id":"45116293-8686-40a3-8933-8ec46fd22573","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"So the input is [format] and the expected output is [format] — is that right?\"","type":"text"}],"id":"f8446892-fa3e-409b-b5fa-01ccdfe3c6c0","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"Before I start coding, let me outline the steps: first I''ll [step 1], then [step 2], then [step 3].\"","type":"text"}],"id":"0f2afcba-d0cf-4246-bab9-edc2b0fb4408","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"I''ll start with the simplest version first and refine from there.\"","type":"text"}],"id":"1a40f86f-4871-4670-b592-dcbee5d4be15","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"74a202d3-1af9-42a5-a164-ee3c596ed40d","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"While Choosing Data Structures","type":"text"}],"id":"a84ced0c-f71e-4fa3-8b85-46948bbd460f","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"I''ll use a dictionary here because we need to group by [key] and accumulate [values].\"","type":"text"}],"id":"ddcacc4e-87bc-4f57-8951-a8387c10a99d","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"A list makes sense here because we need to preserve order and allow duplicates.\"","type":"text"}],"id":"dd073647-c176-43a1-a6e3-47c021402830","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"I''ll use a set to track unique [entities] since we don''t care about duplicates.\"","type":"text"}],"id":"b379890e-1369-441c-8535-6aac214029ae","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"Since we need fast lookups by [key], a dictionary is the right choice.\"","type":"text"}],"id":"7abbcc70-e8b3-4864-82c9-ad0401c88fb3","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"c6e353f5-e664-4376-8c82-d3da8e852f90","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"While Writing Functions","type":"text"}],"id":"20b08595-17ae-4ab3-8a9c-d968dd0bfaef","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"I''ll write a separate function for this logic so it''s testable and reusable.\"","type":"text"}],"id":"501d4f60-9eaf-41d5-80c5-6ddb570cb632","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"I''ll call this function ","type":"text"},{"styles":{"code":true},"text":"validate_record()","type":"text"},{"styles":{"italic":true},"text":" — it takes a record and returns True if valid, False otherwise.\"","type":"text"}],"id":"da8ae9c2-7a07-4da9-b379-419ef9123340","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"Breaking this into functions makes it easier to read and debug.\"","type":"text"}],"id":"70f2ec66-f56d-481b-8324-5042a7c40633","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"2d09151a-5720-4508-ad3b-9888cfcf1c54","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"When Handling Invalid Data","type":"text"}],"id":"09235f8f-d884-4791-ac9c-89ecd4079d15","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"I''ll use ","type":"text"},{"styles":{"code":true},"text":".get()","type":"text"},{"styles":{"italic":true},"text":" with a default value to handle missing keys gracefully.\"","type":"text"}],"id":"4221429d-1ba2-43a6-bde0-6592ac28a17e","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"I should check if the input is None or empty before processing — let me add that at the top.\"","type":"text"}],"id":"01bad2c3-48e1-462d-b137-674acddfce7a","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"If a record is invalid, I''ll skip it and continue rather than crashing the whole process.\"","type":"text"}],"id":"8a0dea07-53f4-4abd-90a1-e119a608a61d","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"I''ll add a try-except block here in case the date parsing fails.\"","type":"text"}],"id":"016a1131-1263-4df3-8f1d-76843c039a19","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"78dda72c-1767-4a40-9167-59f5e01cb61c","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"When Debugging","type":"text"}],"id":"a796919e-8abf-4d2a-a309-83951b8c1840","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"Let me trace through this line by line with an example to see where it''s breaking.\"","type":"text"}],"id":"e51a8893-e1da-40a0-8ff1-724736e60e02","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"I think the issue is here — I''m modifying the list while iterating over it. Let me fix that.\"","type":"text"}],"id":"a58a5c87-c4dd-4ea3-bdb1-a018e684b76d","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"Let me print the intermediate values to see what''s actually happening.\"","type":"text"}],"id":"d0a5d61b-9392-4522-a67c-736fc3751d98","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"Actually, I see the bug — I''m using ","type":"text"},{"styles":{"code":true},"text":"=","type":"text"},{"styles":{"italic":true},"text":" instead of ","type":"text"},{"styles":{"code":true},"text":"==","type":"text"},{"styles":{"italic":true},"text":" in the condition.\"","type":"text"}],"id":"439ae19e-6ae3-4df3-82a8-6ed30986650f","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"62867b40-99e1-4908-8032-e697664f91f6","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"When Improving the Solution","type":"text"}],"id":"caaa2f5c-9992-4122-91a7-2c01b697c4c2","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"This works, but if I wanted to optimize, I''d use a list comprehension instead of a loop.\"","type":"text"}],"id":"5d9de6ba-9cf8-4826-a685-7b958511e913","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"For production, I''d add logging and better error messages.\"","type":"text"}],"id":"f040acff-7403-4154-b1f0-92f3e71dc965","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"If performance mattered, I''d process this in chunks rather than loading everything into memory.\"","type":"text"}],"id":"f5763dcf-bdd9-4c7f-a266-0f78298a317d","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"40c39913-4a66-4532-8a61-77cc7f9bcbce","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"When Stuck","type":"text"}],"id":"03facd09-41de-498c-8656-65835cb7118c","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"I''m stuck on how to handle [specific issue]. Let me think through two approaches.\"","type":"text"}],"id":"7823c4da-a2cf-4120-aff2-808019790317","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"I''m not sure if I should use a loop or a comprehension here — let me start with a loop for clarity.\"","type":"text"}],"id":"50d78b4a-3720-41bd-956a-c79635786444","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"Let me step back and think about the structure of the data again.\"","type":"text"}],"id":"9a5a38be-9e9f-45e1-b990-e6d72c2baea8","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"Can I clarify the expected behavior when [edge case scenario]?\"","type":"text"}],"id":"45068e8c-82e7-42c1-9be0-4eb017cfe979","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"71669df9-d5e9-4184-8956-d259145a18b4","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"4. 🔧 Common Python Areas for Data Engineering — Interview Approach","type":"text"}],"id":"4a40632f-2309-41a5-82f5-4f1d971ec10a","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Here''s how to ","type":"text"},{"styles":{"bold":true},"text":"approach","type":"text"},{"styles":{},"text":" the most common Python areas in DE interviews — with focus on what to say and what to check, not deep teaching.","type":"text"}],"id":"acdc22b1-bf0c-4cf0-8233-a6255b0beddb","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"e665d127-93ad-41b4-9948-1327d79fb543","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Area 1 — Lists","type":"text"}],"id":"8e47b78b-e05e-4ee1-a578-e3a548af335f","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"When used:","type":"text"},{"styles":{},"text":" Ordered collections, preserving sequence, allowing duplicates.","type":"text"}],"id":"faadcd66-7321-4267-910c-0dbc016e7d61","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"What to say:","type":"text"}],"id":"d6c264a9-3774-4a3a-9bc7-c480bde9928a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"I''ll use a list to store the records because order matters and we might have duplicates.\"","type":"text"}],"id":"c2bc5c6a-5756-441b-ade4-4917b4baf29d","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"bold":true},"text":"Common operations:","type":"text"}],"id":"708508ee-a868-49ea-a2ba-e18e53d508d9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Append: ","type":"text"},{"styles":{"code":true},"text":"records.append(item)","type":"text"}],"id":"9d6c8933-4ef2-4aac-b62e-08cadaf0f05f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Loop: ","type":"text"},{"styles":{"code":true},"text":"for record in records:","type":"text"}],"id":"b4f756c7-834d-495e-89f5-e9038429cbee","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"List comprehension: ","type":"text"},{"styles":{"code":true},"text":"[x * 2 for x in numbers]","type":"text"}],"id":"d35be3e4-6743-4983-b5ba-34760f8c2b5f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"What to check:","type":"text"}],"id":"ad98457b-7228-46a4-881f-7c365faf8f05","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Are you modifying the list while iterating? (Common bug — use a copy or new list)","type":"text"}],"id":"79734627-9996-430b-a409-7ac0a19456ca","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"id":"3ae1eb1c-7b09-40ac-8d6c-a6bbdab9bc21","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Area 2 — Dictionaries","type":"text"}],"id":"13444018-baef-49d8-b4e0-9276ccdf4540","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"When used:","type":"text"},{"styles":{},"text":" Key-value storage, grouping, counting, fast lookups.","type":"text"}],"id":"534418b9-247c-4885-8597-0f5b7369aa50","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"What to say:","type":"text"}],"id":"2e5a4532-433c-4447-a561-c3d7b63a0138","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"I''ll use a dictionary to group sales by product_id — the key is the product, the value is the total.\"","type":"text"}],"id":"61e6d28a-90bd-4389-ac25-8fff74e8a187","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"bold":true},"text":"Common operations:","type":"text"}],"id":"0b90fb9b-5dce-4953-98a3-e12a808e2228","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Safe access: ","type":"text"},{"styles":{"code":true},"text":"record.get(''key'', default_value)","type":"text"}],"id":"6529cf3c-a71b-4bc3-a720-349d805403e4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Add/update: ","type":"text"},{"styles":{"code":true},"text":"totals[key] = totals.get(key, 0) + value","type":"text"}],"id":"50571482-b0e3-45b3-8e93-9576e38276ec","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Loop: ","type":"text"},{"styles":{"code":true},"text":"for key, value in totals.items():","type":"text"}],"id":"f75d48c7-85ee-419f-9c12-7575e145f873","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"What to check:","type":"text"}],"id":"228aee95-ce2a-44a2-ac2c-eeddd365f60b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Are you handling missing keys? (Use ","type":"text"},{"styles":{"code":true},"text":".get()","type":"text"},{"styles":{},"text":" or ","type":"text"},{"styles":{"code":true},"text":"defaultdict","type":"text"},{"styles":{},"text":")","type":"text"}],"id":"584557d7-e203-4635-8c54-4cd9ae3388d3","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"id":"e223b64e-0e83-4bb8-8d20-b503a71484c7","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Area 3 — Sets","type":"text"}],"id":"5cff09a1-56f4-4001-888e-3d3951c35b4b","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"When used:","type":"text"},{"styles":{},"text":" Unique values, membership testing, deduplication.","type":"text"}],"id":"4509f37f-710a-4e62-9f79-ec42294b5bcd","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"What to say:","type":"text"}],"id":"bfbeef29-c7e8-4437-b0a3-6cc5f35b96c5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"I''ll use a set to track unique customer IDs since we only care about distinct customers.\"","type":"text"}],"id":"817b5c24-447a-4b9c-97e9-79374342cceb","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"bold":true},"text":"Common operations:","type":"text"}],"id":"5cfc4c9c-cade-4433-9401-bed04f2b5ab1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Add: ","type":"text"},{"styles":{"code":true},"text":"unique_ids.add(customer_id)","type":"text"}],"id":"6bf046a1-6dbd-4000-8360-0188a53f832e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Check membership: ","type":"text"},{"styles":{"code":true},"text":"if product_id in seen:","type":"text"}],"id":"79c6e9bd-458a-4d72-9933-f9e22d5675c5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Convert from list: ","type":"text"},{"styles":{"code":true},"text":"unique_values = set(values)","type":"text"}],"id":"614513fd-9287-43a3-9815-f96cea6144a5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"What to check:","type":"text"}],"id":"d2f29dd4-f7ad-40f1-ba44-9979d98c44ee","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Sets are unordered — if order matters, don''t use a set","type":"text"}],"id":"e384c347-1fe5-458a-812b-c5d804b59d0b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"id":"131ba263-f760-4a49-8324-010f96b00534","props":{},"type":"divider"},{"children":[]