= EXCLUDED."rich_content", "user_id" = EXCLUDED."user_id";
INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-05-25T05:09:45.336967+00:00', '', '', 'eadba7c4-62c8-4347-97ba-15a0ce422a9d', false, '[]'::jsonb, '2026-05-25T05:10:15.665+00:00', '21b23730-1e24-468d-a7ac-836d2cdf3ffe', '', 'b6beaf9e-5dc5-474d-9705-4102609e53f3', '', '[]'::jsonb, '[{"children":[],"content":[{"styles":{"bold":true},"text":"1. Mental Model","type":"text"}],"id":"bea15494-58d2-4589-b84d-3521d47b2a4d","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Think of this like ","type":"text"},{"styles":{"bold":true},"text":"two kinds of architects","type":"text"},{"styles":{},"text":" in the construction world:","type":"text"}],"id":"9839dd9c-8541-4059-91b3-a274fd58d569","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"text","type":"text"}],"id":"8e496de3-a143-4f92-952a-f30712dfccd2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"code":true},"text":"TYPE A — The Restoration Architect\n Works with existing buildings\n Adapts, renovates, optimizes\n Deep knowledge of what''s already there\n \"Don''t tear it down — make it work better\"\n\nTYPE B — The Custom Home Builder\n Designs from scratch\n Builds bespoke, high-performance systems\n Deep knowledge of materials and construction\n \"Let''s build exactly what we need\"","type":"text"}],"id":"e55cd758-26ac-41ab-9a61-dab14230e481","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Neither is better. The right choice depends entirely on ","type":"text"},{"styles":{"bold":true},"text":"where the organization is","type":"text"},{"styles":{},"text":" and ","type":"text"},{"styles":{"bold":true},"text":"what problems it faces","type":"text"},{"styles":{},"text":". Most real data engineers live somewhere on the spectrum between these two poles — and the best ones know ","type":"text"},{"styles":{"bold":true},"text":"when to shift","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"4ec6ceef-c818-4973-a36b-da6a3f6db0a8","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"id":"9cef1aea-3449-4777-a7b5-9f9f89abccbf","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"2. Explanation","type":"text"}],"id":"12e51913-dca9-485f-bc29-f3c396506b36","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"The A-to-B Continuum","type":"text"}],"id":"3bd66d92-7dd4-434b-816c-ba2a46d24d21","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The book introduces a spectrum of data engineering personas — not rigid categories, but a ","type":"text"},{"styles":{"bold":true},"text":"sliding scale","type":"text"},{"styles":{},"text":":","type":"text"}],"id":"5063de20-cd85-49c2-8815-e10afa267504","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"text","type":"text"}],"id":"3e1d45ae-e356-43ad-8f6d-224630ba8230","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"code":true},"text":"TYPE A ←————————————————————————→ TYPE B\n(Abstraction) (Build)\n\nUses managed tools, Builds custom systems,\noff-the-shelf services, frameworks, and pipelines\nand existing platforms from the ground up","type":"text"}],"id":"03f59c9f-02ec-4e74-9c00-f6bcdd4f688a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"54c1ac3a-859b-412a-990e-583910931728","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"Type A — The Abstraction Engineer","type":"text"}],"id":"84a226b4-6f33-493c-bd58-07ae92858c8c","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"\"A\" stands for Abstraction","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"394ac0e7-d788-44e8-9c6e-58b09b015f54","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Type A data engineers ","type":"text"},{"styles":{"bold":true},"text":"keep data engineering complexity low","type":"text"},{"styles":{},"text":" by leveraging off-the-shelf tools, managed services, and prebuilt components. They resist the urge to build custom when a product already exists.","type":"text"}],"id":"e1f1a147-97e9-40fe-a353-22a2725385f0","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Core characteristics","type":"text"},{"styles":{},"text":":","type":"text"}],"id":"9be48eda-c210-4bb7-993d-86d8b74b27b1","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Assembles pipelines from managed tools (Fivetran, dbt, Snowflake, Airflow)","type":"text"}],"id":"2bab81bb-813c-4bed-8320-22263b3ba867","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Prioritizes ","type":"text"},{"styles":{"bold":true},"text":"speed to value","type":"text"},{"styles":{},"text":" over technical elegance","type":"text"}],"id":"f1a81aa8-98d0-4c12-9ae6-87093e502eff","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Avoids \"undifferentiated heavy lifting\" — the work that doesn''t create competitive advantage","type":"text"}],"id":"2bb41da3-60b9-495a-9337-3ab1896b4bee","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Deeply skilled at ","type":"text"},{"styles":{"bold":true},"text":"evaluating, integrating, and configuring","type":"text"},{"styles":{},"text":" tools","type":"text"}],"id":"567a12c2-4d10-4130-8ec5-7bdcecf5dc7c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Often the right fit for ","type":"text"},{"styles":{"bold":true},"text":"Stage 1 and Stage 2","type":"text"},{"styles":{},"text":" organizations","type":"text"}],"id":"517ea7e2-99fc-4eb7-85ca-3d4a87443ed8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Mindset","type":"text"},{"styles":{},"text":": ","type":"text"},{"styles":{"italic":true},"text":"\"Has someone already solved this? Use it. Only build when there''s no alternative or when building creates real competitive advantage.\"","type":"text"}],"id":"4c1027fc-3439-4b89-a6d9-09ce6aeb01da","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"id":"c99d4167-1862-45cf-8884-1a062feed635","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"Type B — The Build Engineer","type":"text"}],"id":"ca50d28a-caeb-4d74-b398-c7dc663659c5","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"\"B\" stands for Build","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"bd82d1a5-a683-4227-956b-a8f9271971ff","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Type B data engineers write ","type":"text"},{"styles":{"bold":true},"text":"custom data systems, frameworks, and infrastructure","type":"text"},{"styles":{},"text":" from scratch. They go deep into the internals of data platforms and build things the market doesn''t yet offer.","type":"text"}],"id":"a5f6574c-d0df-4add-803d-60da895c6fa9","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Core characteristics","type":"text"},{"styles":{},"text":":","type":"text"}],"id":"5f82b79f-74df-4b64-bbb5-4a77f8c47102","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Builds custom ingestion frameworks, processing engines, or storage systems","type":"text"}],"id":"52ff6a17-3a1c-4ad8-9c60-cc71715fd910","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Deep proficiency in software engineering — Java, Scala, Python at a systems level","type":"text"}],"id":"ee724ecf-d9b9-4f6d-bb62-7941a40762aa","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Works on problems where ","type":"text"},{"styles":{"bold":true},"text":"no off-the-shelf solution exists","type":"text"},{"styles":{},"text":" or where scale demands custom optimization","type":"text"}],"id":"01918dbb-942b-4c08-95b9-d3afc7cbc72b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Often found at ","type":"text"},{"styles":{"bold":true},"text":"large tech companies, Stage 3 organizations","type":"text"},{"styles":{},"text":", or companies whose data IS the product","type":"text"}],"id":"67006d4a-8c0c-4ef4-83ab-c33caf3b57f2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Maintains and extends open-source frameworks","type":"text"}],"id":"c1ababbd-9c95-4cc8-96bf-37dd732e69cd","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Mindset","type":"text"},{"styles":{},"text":": ","type":"text"},{"styles":{"italic":true},"text":"\"The tools available don''t solve our problem at our scale or with our constraints — we need to build it ourselves.\"","type":"text"}],"id":"c71e892d-6c84-4d4c-b3fa-318771baa886","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"id":"e178facf-f037-46d8-8edf-eb5ed6354192","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"The Crucial Nuance: These Are Not Fixed Identities","type":"text"}],"id":"97b1e457-853a-435d-87e2-a6d3362ebc11","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The book is careful to point out that this is a ","type":"text"},{"styles":{"bold":true},"text":"continuum, not a binary","type":"text"},{"styles":{},"text":":","type":"text"}],"id":"a061d097-9b6c-41ea-9607-00723e910b55","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"text","type":"text"}],"id":"fbedc472-ab1e-48cf-9d35-a108a3583a23","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"code":true},"text":"Most data engineers operate HERE\n ↓\nTYPE A ←———[●●●●●●●●●●]———→ TYPE B\n Shifts based on:\n - Company stage\n - Problem at hand\n - Team size\n - Build vs buy economics","type":"text"}],"id":"f293b44d-620b-44fe-8dbb-fdada342e54a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"A data engineer at a startup might be ","type":"text"},{"styles":{"bold":true},"text":"fully Type A","type":"text"},{"styles":{},"text":" — using every managed service available. The same engineer, five years later at a large-scale platform company, might shift ","type":"text"},{"styles":{"bold":true},"text":"toward Type B","type":"text"},{"styles":{},"text":" to build custom infrastructure their tooling can''t handle.","type":"text"}],"id":"a044b7ae-3f92-444f-98aa-6cc58a39f92d","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"id":"74e04efe-da32-4d13-b727-e7c0814c5c7f","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"How This Connects to Data Maturity","type":"text"}],"id":"91382a76-e1ca-4c1f-9423-8ed83c36371a","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The maturity model from Block 3 maps cleanly onto this continuum:","type":"text"}],"id":"f4c0585f-6c27-463e-86f4-72758e84111b","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":{"columnWidths":[null,null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{"bold":true},"text":"Maturity Stage","type":"text"}],"props":{"backgroundColor":"rgba(214, 213, 212, 0.035)","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"Dominant Persona","type":"text"}],"props":{"backgroundColor":"rgba(214, 213, 212, 0.035)","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"Why","type":"text"}],"props":{"backgroundColor":"rgba(214, 213, 212, 0.035)","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Stage 1","type":"text"},{"styles":{},"text":" — Starting with data","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Strongly Type A","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Speed matters most; avoid complexity; use turnkey solutions","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Stage 2","type":"text"},{"styles":{},"text":" — Scaling with data","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Mostly Type A, drifting toward B","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Some custom needs emerge; but resist over-engineering","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Stage 3","type":"text"},{"styles":{},"text":" — Leading with data","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Mix of A and B","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Custom tooling justified ","type":"text"},{"styles":{"italic":true},"text":"only","type":"text"},{"styles":{},"text":" where it creates competitive advantage","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"f06257c6-6794-4959-8cb7-a4b2207e92c3","props":{"textColor":"default"},"type":"table"},{"children":[],"id":"7b927fa9-8106-4957-bcbb-b9616718e8f4","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"3. Application","type":"text"}],"id":"ea080b3d-7aac-4e8d-838e-b10354f7c0b9","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"The build vs. buy decision in practice","type":"text"}],"id":"6b03c74b-cc67-4a80-af2a-6277d5b00883","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"This framework directly informs one of the most consequential recurring decisions in data engineering: ","type":"text"},{"styles":{"bold":true},"text":"should we build this or buy it?","type":"text"}],"id":"26a73353-75ef-41e4-8b53-4f741b991d00","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Ask these questions before building anything custom:","type":"text"}],"id":"b73959a7-db7a-4785-8000-b6788d3829dc","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Does a managed solution already exist that covers 80%+ of our needs?","type":"text"}],"id":"12eec6b8-814f-4c91-857f-baa267055af3","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"What is the ","type":"text"},{"styles":{"bold":true},"text":"total cost of ownership","type":"text"},{"styles":{},"text":" of maintaining custom code long-term?","type":"text"}],"id":"dd7d8041-d57b-446c-9566-ba334698375a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Does building this create a ","type":"text"},{"styles":{"bold":true},"text":"genuine competitive advantage","type":"text"},{"styles":{},"text":" — or does it just feel satisfying?","type":"text"}],"id":"3fbd6c0f-871e-4506-802e-73ee313c26d8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Is our team capable of maintaining this without creating a single point of failure?","type":"text"}],"id":"b19555df-ede0-4bcc-8658-33a127d7ce02","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"The book''s bias is clear: ","type":"text"},{"styles":{"bold":true},"text":"default to Type A, drift toward Type B only when justified","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"bcbab8f0-58e7-4f6a-af1d-a1cc9758a8e0","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"The career implication","type":"text"}],"id":"d5ffe702-3054-4e07-ac35-4c3a98c723c1","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Understanding where you sit on this spectrum helps you:","type":"text"}],"id":"2a14ccb5-1af7-475f-b474-8fa6a0d1c1de","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Target the right employers","type":"text"},{"styles":{},"text":" — startups and mid-market companies typically want Type A; FAANG and data-product companies want Type B depth","type":"text"}],"id":"91a9172e-349f-4b6f-af42-55d173c5e0ad","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Identify skill gaps","type":"text"},{"styles":{},"text":" — if you''re Type A–heavy, learning systems-level Python or Scala moves you toward B; if you''re Type B–heavy, practicing tool evaluation and integration strengthens your A side","type":"text"}],"id":"5c2807aa-e039-4e6d-ab8a-88b1b31dfd54","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Avoid the ego trap","type":"text"},{"styles":{},"text":" — many engineers default to Type B work because ","type":"text"},{"styles":{"italic":true},"text":"building feels more impressive","type":"text"},{"styles":{},"text":" than configuring. The book calls this out directly as a Stage 2 pitfall","type":"text"}],"id":"a88ae8a7-5f19-431f-ad19-0f27e748f4ea","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"id":"a06fdad2-3fd0-4506-878d-1cf7f4856bfe","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"4. Examples","type":"text"}],"id":"acb28091-7350-477b-9d7b-3c12b979febb","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Example 1 — Type A done right: The lean startup stack\n","type":"text"},{"styles":{},"text":"A 3-person data team at a growth-stage SaaS company needs to ingest data from 15 SaaS sources, transform it, and serve dashboards to the sales team. They choose Fivetran (ingestion) + Snowflake (storage) + dbt (transformation) + Looker (serving). Total setup time: 3 weeks. Zero custom code. The business gets reliable data fast. ","type":"text"},{"styles":{"italic":true},"text":"This is Type A working exactly as intended","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"ea25a27a-a412-4f90-8528-20cd3f8eec2b","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Example 2 — Type B done right: The custom stream processor\n","type":"text"},{"styles":{},"text":"A real-time fraud detection company processes 2 million events per second. No managed streaming service meets their sub-10ms latency requirement at that volume. Their engineers build a custom Flink-based processing layer with proprietary state management. This is expensive and complex — but it''s their ","type":"text"},{"styles":{"bold":true},"text":"core competitive moat","type":"text"},{"styles":{},"text":". ","type":"text"},{"styles":{"italic":true},"text":"This is the rare, justified Type B scenario","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"b6519320-3a27-458b-acae-e961d8e49dba","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Example 3 — The anti-pattern: Type B when Type A was the answer\n","type":"text"},{"styles":{},"text":"A 20-person analytics team decides to build their own data orchestration tool because \"Airflow is too complex to set up.\" They spend four months building it. It lacks half of Airflow''s features, has no community support, and breaks when the one engineer who built it leaves. Meanwhile, competitors using managed Airflow shipped three new data products. ","type":"text"},{"styles":{"italic":true},"text":"This is the most common and costly Type B mistake — building for the sake of building","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"fc2709f7-4475-4052-8dd3-6a8ee81020f9","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"id":"b19600b5-2845-4479-82c8-692e1e43fae2","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"🧠 Socratic Check: Look at the last 3 data engineering decisions you made (or would make in a new role). For each one — did you reach for a tool (Type A) or reach for a keyboard to build (Type B)? Was that the right call given the stage of the organization? The best data engineers develop a sharp instinct for this judgment, and it improves with deliberate practice.","type":"text"}],"id":"654a28ab-39eb-42c2-922f-12082f042cf4","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textColor":"rgb(214, 213, 212)"},"type":"quote"},{"children":[],"content":[{"styles":{},"text":"\n","type":"text"}],"id":"bb92790c-44d1-444b-b6e6-4070cacdc5f7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[],"id":"72865049-5a59-4991-be11-1441181f7a99","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"}]'::jsonb, '3e9e3dd3-a59b-4b02-968a-ee95e7317583') ON CONFLICT ("node_id") DO UPDATE SET "bad_example" = EXCLUDED."bad_example", "completed_at" = EXCLUDED."completed_at", "created_at" = EXCLUDED."created_at", "definition" = EXCLUDED."definition", "good_example" = EXCLUDED."good_example", "is_completed" = EXCLUDED."is_completed", "key_points" = EXCLUDED."key_points", "last_edited" = EXCLUDED."last_edited", "map_id" = EXCLUDED."map_id", "mental_model" = EXCLUDED."mental_model", "notes" = EXCLUDED."notes", "resources" = EXCLUDED."resources", "rich_content" = EXCLUDED."rich_content", "user_id" = EXCLUDED."user_id";
INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-05-27T04:32:15.88935+00:00', '', '', 'f77b06b0-6307-4e45-8cab-9f3b00f5338c', false, '[]'::jsonb, '2026-05-27T04:33:44.597+00:00', '21b23730-1e24-468d-a7ac-836d2cdf3ffe', '', 'd43ce557-514a-4f37-b849-e8f6668e3127', '', '[]'::jsonb, '[{"children":[],"content":[{"styles":{"bold":true},"text":"1. Mental Model","type":"text"}],"id":"0b993449-12f5-4754-91ba-90d585bf0ae8","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Using the city design analogy — before a single building is constructed, someone has to define ","type":"text"},{"styles":{"bold":true},"text":"what the city is trying to achieve, what the rules are, and what the overall layout looks like","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"9e4cd1ac-da4a-4b9e-b6de-56dc6f0dde2d","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"ENTERPRISE ARCHITECTURE\n(the entire city plan)\n         │\n         ├── IT Architecture      (roads, utilities, infrastructure)\n         ├── Software Architecture (individual buildings)\n         ├── Data Architecture    (how information flows between buildings)\n         └── Security Architecture (walls, gates, access control)\n\nDATA ARCHITECTURE specifically asks:\n  - What data does the business need?\n  - Where does it live?\n  - How does it move?\n  - How does it change over time?\n  - What are the rules governing it?","type":"text"}],"id":"e179ccce-3d5b-4b30-bf14-1c296646235d","props":{"language":"text"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textColor":"rgb(214, 213, 212)"},"text":"The key insight: ","type":"text"},{"styles":{"bold":true},"text":"data architecture is not just a technical diagram","type":"text"},{"styles":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textColor":"rgb(214, 213, 212)"},"text":". It is a living design system that reflects both business goals and technical realities, and it must evolve continuously as both change.","type":"text"}],"id":"07b74e56-4bf3-4c4b-ba4f-c229f5a0e660","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"2. Explanation","type":"text"}],"id":"74deaf9a-1e3c-4148-9424-5bd0f41acda3","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Enterprise Architecture — the big picture","type":"text"}],"id":"842cfe2e-e893-4708-bb47-d2a2f6862189","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Enterprise architecture is the ","type":"text"},{"styles":{"bold":true},"text":"design of an organization''s technical and business systems","type":"text"},{"styles":{},"text":" to achieve its goals. It sits at the top of the abstraction hierarchy and encompasses everything from business processes to the specific software and data systems that support them.","type":"text"}],"id":"f96c2331-2509-4838-96c3-35f2374114ed","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"The book defines enterprise architecture as:","type":"text"}],"id":"e221c4a8-e760-404d-9aae-639d1fe6b2fe","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"The design of systems to support change in the organization, achieved by flexible and reversible decisions reached through careful evaluation of trade-offs.","type":"text"}],"id":"306a52f1-2d09-42a8-9c89-9374770b7f92","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textColor":"rgb(214, 213, 212)"},"type":"quote"},{"children":[],"content":[{"styles":{},"text":"Two words dominate this definition — ","type":"text"},{"styles":{"bold":true},"text":"flexible","type":"text"},{"styles":{},"text":" and ","type":"text"},{"styles":{"bold":true},"text":"reversible","type":"text"},{"styles":{},"text":". Good enterprise architecture does not lock the organization into rigid, irreversible choices. It creates room to adapt.","type":"text"}],"id":"09118f7f-7040-42f4-9e3b-71c5fc661e6a","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"id":"01a1eead-104f-4623-9627-33a312dcbc9a","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"Data Architecture — the specific discipline","type":"text"}],"id":"7ea45292-6fd1-45c3-ae48-08ede26dbb45","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Within enterprise architecture, ","type":"text"},{"styles":{"bold":true},"text":"data architecture","type":"text"},{"styles":{},"text":" is the subset focused on data specifically. The book defines it as:","type":"text"}],"id":"d4e34381-dc74-40ed-95f2-49e588f00938","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Data architecture is the design of systems to support the evolving data needs of an enterprise, achieved by flexible and reversible decisions reached through careful evaluation of trade-offs.","type":"text"}],"id":"3639d475-26a6-458d-93d0-bacebc3bcfa9","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textColor":"rgb(214, 213, 212)"},"type":"quote"},{"children":[],"content":[{"styles":{},"text":"The key components of data architecture are:","type":"text"}],"id":"eb54d509-102e-4792-a469-79332a17afd0","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Operational architecture","type":"text"},{"styles":{},"text":" — what data processes are needed, how data interacts with business processes, and how people use data in their work","type":"text"}],"id":"629c4c64-9240-428c-8863-fc7bd475ef0f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Technical architecture","type":"text"},{"styles":{},"text":" — how data is ingested, stored, transformed, and served; the actual systems and tools that implement the operational architecture","type":"text"}],"id":"8276ce0a-8cdb-48e2-a1fa-be5dd57fc585","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Think of operational architecture as ","type":"text"},{"styles":{"bold":true},"text":"what the city needs to do","type":"text"},{"styles":{},"text":", and technical architecture as ","type":"text"},{"styles":{"bold":true},"text":"how the buildings and roads make that happen","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"b361cfbe-7eeb-4a5a-a957-9e96e55d8943","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"id":"635ebe79-b3b9-4f2d-9373-5b78c17061e7","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"What makes data architecture \"good\"?","type":"text"}],"id":"721237f1-e3ae-4374-a786-a5f58f76dddb","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The book is specific about this. Good data architecture:","type":"text"}],"id":"0dbd9778-a05f-41f6-8afb-3ab8ef39787f","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Supports the ","type":"text"},{"styles":{"bold":true},"text":"current and future needs","type":"text"},{"styles":{},"text":" of the business","type":"text"}],"id":"bd23c47b-9387-4c14-8add-56550c609ae8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Makes ","type":"text"},{"styles":{"bold":true},"text":"reversible decisions","type":"text"},{"styles":{},"text":" wherever possible — avoids lock-in","type":"text"}],"id":"c247faa9-ff0c-4511-b198-4b50e80a739c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Accepts that ","type":"text"},{"styles":{"bold":true},"text":"requirements will change","type":"text"},{"styles":{},"text":" and plans for that","type":"text"}],"id":"27f1184d-12e9-4c29-aa0e-e4aa1967885b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Balances ","type":"text"},{"styles":{"bold":true},"text":"cost, simplicity, scalability, and reliability","type":"text"},{"styles":{},"text":" simultaneously","type":"text"}],"id":"cfec7247-8b58-451d-b2e6-77d027f6240a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Is designed ","type":"text"},{"styles":{"bold":true},"text":"collaboratively","type":"text"},{"styles":{},"text":" — not by one person in isolation","type":"text"}],"id":"61fceb27-646d-4bdf-a171-c80969326c00","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Treats architecture as an ongoing practice, not a one-time project","type":"text"}],"id":"eed717cd-f55e-43c2-8ee3-c694bfaa3563","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Bad data architecture, by contrast:","type":"text"}],"id":"d4929f77-ba19-489b-a5d8-27903a4634b5","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Over-engineers for requirements that may never materialize","type":"text"}],"id":"326dd58d-869b-42bb-8857-834ab316381c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Creates rigid monoliths that are expensive to change","type":"text"}],"id":"4818c0b9-7b5e-4764-81fc-695214807a93","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Is built around tools rather than business needs","type":"text"}],"id":"580fda3c-58ef-431d-98e4-dcf50cb0b261","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Ignores trade-offs — optimizing for one dimension while destroying others","type":"text"}],"id":"f0fdb667-7e9c-4688-8729-baf78b8ef7fb","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Is designed once and never revisited","type":"text"}],"id":"6899ee52-9a2d-4a21-ac77-2180f28b75cc","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"The trade-off lens","type":"text"}],"id":"372f6ae0-b4f0-4e09-9317-67afba67d24d","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The book introduces the idea that ","type":"text"},{"styles":{"bold":true},"text":"architecture is fundamentally about trade-offs","type":"text"},{"styles":{},"text":". There is no perfect architecture. Every decision involves:","type":"text"}],"id":"5400cf60-90a2-4622-ba15-e58bac7e7cd2","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"COST         ↔   PERFORMANCE\nSIMPLICITY   ↔   FLEXIBILITY\nSPEED NOW    ↔   SCALABILITY LATER\nBUILD        ↔   BUY\nCENTRALIZED  ↔   DECENTRALIZED","type":"text"}],"id":"485f1cbb-4a6d-4884-bb45-84b353535ff3","props":{"language":"text"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textColor":"rgb(214, 213, 212)"},"text":"A data architect or data engineer choosing an architecture must understand ","type":"text"},{"styles":{"bold":true},"text":"what they are optimizing for","type":"text"},{"styles":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textColor":"rgb(214, 213, 212)"},"text":" and what they are willing to sacrifice. The best architects make these trade-offs explicit rather than pretending they don''t exist.","type":"text"}],"id":"515a203a-4b4c-4d37-a2ee-20606d539583","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"3. Application","type":"text"}],"id":"0a514801-4ed1-4d1c-8715-c8e54e5fcba2","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why this definition matters in practice","type":"text"}],"id":"e060c4e8-a0f2-46eb-ae9a-61905bd8f629","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Many organizations treat data architecture as a one-time deliverable — a diagram drawn at the start of a project that collects dust afterward. The book explicitly rejects this view. Architecture is a living design system that requires:","type":"text"}],"id":"5a71ea5e-c3e4-40f7-a1aa-de1f42e60bdc","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Continuous evaluation as business requirements evolve","type":"text"}],"id":"dcd7f363-c8f3-4f87-83bd-88593a39a039","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Regular revisiting of previous decisions as new tools become available","type":"text"}],"id":"7e9f19a1-713b-4792-9a13-edf0799ffc23","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Collaborative input from engineers, architects, and business stakeholders","type":"text"}],"id":"6e483a31-f4ef-48c9-b30b-b3b7f8b8867e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"When do data engineers need to think architecturally?","type":"text"}],"id":"0bf834e6-ba5c-42cc-91f0-4073f5d1f010","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The book makes a key organizational observation: ","type":"text"},{"styles":{"bold":true},"text":"at smaller companies, data engineers often absorb the responsibilities of a data architect","type":"text"},{"styles":{},"text":". This means data engineers need to understand architectural thinking even if they don''t carry the title. Specifically, architectural thinking is required when:","type":"text"}],"id":"df37ae41-2087-4454-a2b7-569f77911b88","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Selecting storage systems","type":"text"}],"id":"35e7f27f-47b4-4ff4-87a5-01d9fede93a6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Deciding between batch and streaming pipelines","type":"text"}],"id":"5454122a-5048-42b5-bef7-9b457eb71697","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Evaluating whether to build vs buy a component","type":"text"}],"id":"054af69d-fde2-4313-b24c-cb5202ee1e57","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Designing a new data platform or migrating an old one","type":"text"}],"id":"4eb183fb-3cf7-4840-87f6-b4b9cca8b99b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Determining how to integrate new data sources into an existing system","type":"text"}],"id":"5a5f8635-17e7-4b23-9e55-3ae5dc5dde85","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"4. Examples","type":"text"}],"id":"c421a792-1c8d-4d79-9b56-325e84dc3fc4","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Example 1 — Simple: Operational vs technical architecture\n","type":"text"},{"styles":{},"text":"A marketing team needs daily reports on campaign performance. The ","type":"text"},{"styles":{"bold":true},"text":"operational architecture","type":"text"},{"styles":{},"text":" answers: what data is needed, from which sources, for which business people, at what frequency? The ","type":"text"},{"styles":{"bold":true},"text":"technical architecture","type":"text"},{"styles":{},"text":" answers: how does data from Google Ads and Salesforce land in Snowflake, get transformed by dbt, and serve a Looker dashboard? Both layers are part of data architecture — the operational defines the need, the technical defines the implementation.","type":"text"}],"id":"aa37a307-5d38-4bec-87ec-86f6d26fbf8f","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Example 2 — Intermediate: The rigid architecture trap\n","type":"text"},{"styles":{},"text":"A company designs a data warehouse architecture in 2018, optimized entirely for batch reporting. By 2022 the business needs real-time fraud detection and customer personalization. The architecture cannot accommodate streaming, and there is no flexible layer to add it without rebuilding. The original design had no reversibility built in. ","type":"text"},{"styles":{"italic":true},"text":"This is bad architecture — it optimized for the present and ignored the need for future adaptability","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"61e411dc-a81b-4c2b-9802-805864b4c42d","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Example 3 — Complex: Architecture as living practice\n","type":"text"},{"styles":{},"text":"A fast-growing SaaS company reviews its data architecture quarterly. Each review asks: what has changed in the business, what new data sources have emerged, where are the bottlenecks, and which decisions made 6 months ago still make sense? One quarter they discover their raw storage layer is growing 10x faster than predicted and migrate to a lakehouse pattern. Another quarter they decommission a custom pipeline in favor of a managed connector. ","type":"text"},{"styles":{"italic":true},"text":"This is architecture treated as a continuous practice, not a frozen diagram","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"67f9f2f8-fc2c-46e3-b81d-551ed0b5fdf5","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"id":"bec6864c-5d18-4fae-ad8f-8e1097700fc8","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"🧠 Socratic Check: Think about any data system you know. Was the architecture explicitly designed with trade-offs in mind, or did it just grow organically from tool choices? Most systems in the real world are the latter — and the moment the business requirements change, those systems become painful to adapt. That tension is what this chapter is about.","type":"text"}],"id":"f3ecdf0b-0c59-4e51-8e38-64f74f107931","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textColor":"rgb(214, 213, 212)"},"type":"quote"},{"children":[],"content":[],"id":"59ee6833-232a-4d9d-af81-58ff4bd9368a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[],"id":"1a51c91e-81c7-4108-b40e-296b50784611","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"}]'::jsonb, '3e9e3dd3-a59b-4b02-968a-ee95e7317583') ON CONFLICT ("node_id") DO UPDATE SET "bad_example" = EXCLUDED."bad_example", "completed_at" = EXCLUDED."completed_at", "created_at" = EXCLUDED."created_at", "definition" = EXCLUDED."definition", "good_example" = EXCLUDED."good_example", "is_completed" = EXCLUDED."is_completed", "key_points" = EXCLUDED."key_points", "last_edited" = EXCLUDED."last_edited", "map_id" = EXCLUDED."map_id", "mental_model" = EXCLUDED."mental_model", "notes" = EXCLUDED."notes", "resources" = EXCLUDED."resources", "rich_content" = EXCLUDED."rich_content", "user_id" = EXCLUDED."user_id";
INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-06-11T15:50:51.04615+00:00', '', '', '9d4215d2-8f40-482e-bfec-182309243876', false, '[]'::jsonb, '2026-08-06T16:53:35.238+00:00', '2ad473fe-77dd-481e-8ba7-4b2b0336173f', '', '0d53b416-f386-4c75-93d9-b35155ab8201', '', '[]'::jsonb, '[{"children":[],"content":[{"styles":{},"text":"Based on your CV and target companies (big tech in Sri Lanka like LZ, Nagaro, EY, Virtusa, WSO2), you have a ","type":"text"},{"styles":{"bold":true},"text":"strong foundation","type":"text"},{"styles":{},"text":" — Azure/Databricks/Fabric experience, end-to-end project ownership, and clear data engineering thinking.","type":"text"}],"id":"e42e2a66-9e1e-4d06-92d0-f420dbb8969e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"But I see ","type":"text"},{"styles":{"bold":true},"text":"one critical gap","type":"text"},{"styles":{},"text":" that will come up in interviews for mid-tier and big tech companies:","type":"text"}],"id":"a00e34ac-467f-4e52-bf59-c640c7a6b489","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"d0ddd9cc-b067-4512-aeda-1ba0df212094","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"🎯 The Gap: ","type":"text"},{"styles":{"bold":true},"text":"Local/Open-Source Data Engineering Stack","type":"text"}],"id":"b70363ce-9e73-44b1-9497-3673b7fbf3a0","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Your CV is heavily Azure/Microsoft ecosystem. That''s valuable, but:","type":"text"}],"id":"799b528d-0e85-48eb-affb-a9401351ea33","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Most Sri Lankan tech companies use ","type":"text"},{"styles":{"bold":true},"text":"AWS","type":"text"},{"styles":{},"text":" or ","type":"text"},{"styles":{"bold":true},"text":"on-prem","type":"text"},{"styles":{},"text":" stacks (Spark on YARN, Airflow, PostgreSQL, S3)","type":"text"}],"id":"a5d907a3-9a99-43c1-bb9d-e1720a1eacec","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Interviewers want to see you can ","type":"text"},{"styles":{"bold":true},"text":"build pipelines without clicking through Azure UI","type":"text"},{"styles":{},"text":" — raw code, infrastructure-as-code thinking","type":"text"}],"id":"d97b78e4-7164-43d1-bcc1-48e806566ba8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Your current projects are cloud-platform-specific; there''s no evidence you can ","type":"text"},{"styles":{"bold":true},"text":"architect from scratch using open-source tools","type":"text"}],"id":"f65e895b-1fbb-4011-bb40-e41a0ae83e46","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Big tech companies want engineers who understand the ","type":"text"},{"styles":{"bold":true},"text":"underlying concepts","type":"text"},{"styles":{},"text":" (Spark, SQL, orchestration, dimensional modeling) ","type":"text"},{"styles":{"bold":true},"text":"independent of vendor tooling","type":"text"},{"styles":{},"text":". Your CV shows you know the concepts — but wrapped in Microsoft products.","type":"text"}],"id":"bc729116-8dfb-4872-91b6-1d88d84ed16c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"0653735a-81c0-4b31-b27b-9417cc2a3e91","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"✅ The Perfect Project to Fill This Gap","type":"text"}],"id":"65cd30b8-829b-4a61-bc03-80d16deb7f6a","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Real-Time E-Commerce Analytics Pipeline (End-to-End, Cloud-Agnostic)","type":"text"}],"id":"e7f3acfa-f00e-4d3b-88bc-ddf88308ea4f","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why this project specifically:","type":"text"}],"id":"cca1eafc-1678-4a24-9c83-66c9211f115d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Uses open-source tools","type":"text"},{"styles":{},"text":" (Spark, Airflow, PostgreSQL, Docker) — portable across any company''s stack","type":"text"}],"id":"cbd1a02d-f529-49fa-bc94-a5c5054f5b06","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Shows both batch and streaming","type":"text"},{"styles":{},"text":" — most of your projects are batch; adding streaming shows breadth","type":"text"}],"id":"cbe24c99-8a10-4787-9dfa-ce191c2c597c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Demonstrates orchestration without a managed service","type":"text"},{"styles":{},"text":" — you write Airflow DAGs yourself, not drag-drop","type":"text"}],"id":"6efb0b9f-60a2-45a4-b499-b593e7ae70ac","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Deployable locally","type":"text"},{"styles":{},"text":" (laptop) ","type":"text"},{"styles":{"bold":true},"text":"and","type":"text"},{"styles":{},"text":" cloud-ready (AWS) — shows you understand infrastructure","type":"text"}],"id":"085bba3e-3eef-4524-a1f3-e80e60bf8986","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Covers every interview topic","type":"text"},{"styles":{},"text":" — ETL, dimensional modeling, incremental loads, idempotency, performance tuning, data quality","type":"text"}],"id":"d72d88d7-3cf0-4bb8-83a6-1b50efc2595d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Tells a business story","type":"text"},{"styles":{},"text":" — e-commerce is universally understood, easy to explain impact","type":"text"}],"id":"3a1832ce-c56d-4dfc-b1aa-cbf7635e2b65","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"id":"7fcc3ecb-15e8-4baf-88c1-b8c0556425ae","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"🏗️ Project Architecture (What You''ll Build)","type":"text"}],"id":"c349cd39-7ca7-4901-b3ed-88d689249c57","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"┌─────────────────────────────────────────────────────────────────┐\n│                        DATA SOURCES                              │\n├─────────────────────────────────────────────────────────────────┤\n│ 1. Simulated E-Commerce API (FastAPI you build)                │\n│    - Orders, Customers, Products, Events stream                 │\n│ 2. Static CSV (Product catalog, Region lookup)                  │\n└─────────────────────────────────────────────────────────────────┘\n                            │\n                            ▼\n┌─────────────────────────────────────────────────────────────────┐\n│                    INGESTION LAYER                               │\n├─────────────────────────────────────────────────────────────────┤\n│ - Airflow DAG orchestrates daily batch extract                  │\n│ - Python script pulls incremental data (watermark-based)        │\n│ - Lands in: data/raw/orders/date=2024-01-15/orders.parquet     │\n└─────────────────────────────────────────────────────────────────┘\n                            │\n                            ▼\n┌─────────────────────────────────────────────────────────────────┐\n│              TRANSFORMATION LAYER (PySpark)                      │\n├─────────────────────────────────────────────────────────────────┤\n│ Bronze: Raw data as-is (Parquet, partitioned by date)          │\n│ Silver: Cleaned, deduped, type-cast, validated                  │\n│ Gold:   Dimensional model (Star schema) + aggregated metrics    │\n│         - dim_customer, dim_product, dim_date                   │\n│         - fact_orders                                            │\n│         - agg_daily_sales (pre-aggregated for dashboards)       │\n│ All written as Delta Lake tables (ACID, time travel)            │\n└─────────────────────────────────────────────────────────────────┘\n                            │\n                            ▼\n┌─────────────────────────────────────────────────────────────────┐\n│                  DATA WAREHOUSE (PostgreSQL)                     │\n├─────────────────────────────────────────────────────────────────┤\n│ - Gold layer loaded via bulk COPY (not row-by-row inserts)     │\n│ - Upsert logic for dim tables (SCD Type 1 for customers)       │\n│ - Fact table append-only with watermark tracking                │\n└─────────────────────────────────────────────────────────────────┘\n                            │\n                            ▼\n┌─────────────────────────────────────────────────────────────────┐\n│                   ORCHESTRATION (Airflow)                        │\n├─────────────────────────────────────────────────────────────────┤\n│ DAG 1: Daily Batch Pipeline                                     │\n│   extract >> transform_bronze >> transform_silver >>            │\n│   transform_gold >> load_warehouse >> data_quality_checks       │\n│ DAG 2: Weekly aggregation refresh                               │\n└─────────────────────────────────────────────────────────────────┘\n                            │\n                            ▼\n┌─────────────────────────────────────────────────────────────────┐\n│             MONITORING & DATA QUALITY                            │\n├─────────────────────────────────────────────────────────────────┤\n│ - Great Expectations for schema validation                      │\n│ - Custom checks: row count thresholds, null%, duplicate%        │\n│ - Metrics logged to a monitoring table                          │\n└─────────────────────────────────────────────────────────────────┘\n                            │\n                            ▼\n┌─────────────────────────────────────────────────────────────────┐\n│                      VISUALIZATION                               │\n├─────────────────────────────────────────────────────────────────┤\n│ Option A: Metabase (open-source BI) querying PostgreSQL        │\n│ Option B: Export aggregated CSVs → Power BI (reuse your skill) │\n└─────────────────────────────────────────────────────────────────┘","type":"text"}],"id":"30fdaae9-60cd-4505-911c-0dfbf8905afb","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"8ca71d21-2ede-419a-8df8-ba7270b8133b","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"📦 Tech Stack (What Makes This Defensible)","type":"text"}],"id":"afa5445f-711b-4902-abc0-29b72509b037","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":{"columnWidths":[null,null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Layer","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Tool","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Why This Choice (Interview Defense)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Data Source","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"FastAPI (Python)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"\"I built a mock API to simulate real-world event streaming — shows I can work with APIs, not just files\"","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Orchestration","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Apache Airflow","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"\"Industry-standard scheduler; I wrote DAGs in pure Python, not drag-drop — transferable to any company''s stack\"","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Processing","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"PySpark (local mode)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"\"Spark is the standard for big data DE; running locally proves I understand the code, not just managed Databricks UI\"","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Storage Format","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Delta Lake (Parquet + transaction log)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"\"ACID transactions, time travel, schema enforcement — production-grade features without needing Databricks\"","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Warehouse","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"PostgreSQL","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"\"Open-source, widely used, shows I can design schemas and optimize SQL without vendor lock-in\"","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Data Quality","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Great Expectations","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"\"Automated data validation — I define expectations as code, failing the pipeline if quality thresholds aren''t met\"","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Containerization","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Docker Compose","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"\"Entire stack runs in containers — one ","type":"text"},{"styles":{"code":true},"text":"docker-compose up","type":"text"},{"styles":{},"text":" and it''s live; shows I think about deployability\"","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"IaC (Bonus)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Terraform (AWS deployment)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"\"After proving it works locally, I deployed to AWS using Terraform — infrastructure as code, repeatable across environments\"","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"221d2622-fd5b-4e5d-822a-850fa969f8dc","props":{"textColor":"default"},"type":"table"},{"children":[],"id":"508a1578-cb74-4be2-af2e-62e26e755217","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"🎯 What This Project Proves (The Interview Story)","type":"text"}],"id":"f1ada8a4-2839-4c76-aab6-621286545bd1","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"When asked ","type":"text"},{"styles":{"italic":true},"text":"\"Walk me through a recent project,\"","type":"text"},{"styles":{},"text":" you say:","type":"text"}],"id":"c986ac9e-ff03-4031-a4c6-786462af503a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"I built an end-to-end e-commerce analytics pipeline to demonstrate production-grade data engineering using open-source tools. The business scenario: an online retailer needs daily insights into sales, customer behavior, and inventory trends — but their transactional database isn''t optimized for analytics.\nI designed a medallion architecture: raw API data lands in Bronze as Parquet, gets cleaned and validated in Silver using PySpark, then transformed into a Star schema in Gold with dimensional tables and pre-aggregated metrics. All layers use Delta Lake for ACID guarantees.\nThe pipeline is orchestrated via Airflow — one DAG handles daily incremental loads using watermark-based extraction to avoid reprocessing, another refreshes weekly aggregations. I built in data quality checks using Great Expectations so the pipeline fails fast if schema drifts or null thresholds are breached.\nThe Gold layer loads into PostgreSQL via bulk COPY for performance, with upserts on dimension tables to handle slowly changing customer attributes. The whole stack runs in Docker, and I also deployed it to AWS using Terraform to show cloud portability.\nThis project demonstrates every stage of the DE lifecycle — ingestion, transformation, dimensional modeling, orchestration, quality, and delivery — using tools I can take to any company.\"","type":"text"}],"id":"81875f4b-e688-4821-afad-d6f3f04fe524","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{"bold":true},"text":"That answer hits every checkbox a senior interviewer has.","type":"text"}],"id":"bb356515-f820-42a1-8038-05836cbe06b1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"0b1673f6-9e4a-4880-b8c6-226a1bf97d2a","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"📋 Project Implementation Phases (How You Build It)","type":"text"}],"id":"ae3f2a60-557e-47d7-a906-a2f5ff817cd4","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Phase 1: Mock Data Source (Week 1)","type":"text"}],"id":"3a12b6a3-9e43-43c9-8ec0-000741ea9602","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# Build a FastAPI app that serves:\n# GET /orders?since=2024-01-01  → returns new orders since that date (incremental)\n# GET /customers\n# GET /products\n# Seed with realistic fake data using Faker library\n# Deploy locally, containerized","type":"text"}],"id":"afce12ec-62ed-4b21-aa0b-a897b2702d29","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Phase 2: Airflow + Ingestion (Week 1-2)","type":"text"}],"id":"9c449864-52a5-40af-bffb-2997a85be9a9","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# Set up Airflow in Docker\n# Write DAG: extract_orders_daily\n#   - Python operator hits your API with last watermark\n#   - Writes to data/raw/orders/date=YYYY-MM-DD/orders.parquet\n#   - Updates watermark in a state table (PostgreSQL)","type":"text"}],"id":"db80f4c0-b044-452d-b840-7623aa14bcd9","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Phase 3: Bronze Layer (Week 2)","type":"text"}],"id":"e4a5ac19-6994-4d9f-95f1-1532d9188f37","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# PySpark script reads raw Parquet\n# Writes to Delta Lake Bronze with schema enforcement\n# Partitioned by date\n# No transformations — just store as-is with metadata","type":"text"}],"id":"ee5145e7-eeed-44a6-825b-bf9c7ef2bf62","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Phase 4: Silver Layer (Week 2-3)","type":"text"}],"id":"39024745-59bb-403b-bd08-cc4b6a74b801","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# PySpark transformations:\n#   - Type casting (string amounts → double)\n#   - Null handling (drop/fill)\n#   - Deduplication (window function, keep latest by updated_at)\n#   - Validation (reject rows missing order_id)\n# Write to Delta Silver, partitioned by date","type":"text"}],"id":"971ef9ba-e0ff-4eff-b44e-008b7423b285","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Phase 5: Gold Layer — Dimensional Model (Week 3-4)","type":"text"}],"id":"c533b43b-f2e2-4182-b064-6caed57a8f52","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# Design Star schema:\n#   dim_customer (SCD Type 1 — overwrite)\n#   dim_product (static)\n#   dim_date (date dimension with year/month/day/quarter)\n#   fact_orders (grain: one row per order line)\n#   agg_daily_sales (pre-agg: total sales, order count per product per day)\n# PySpark writes these as Delta tables","type":"text"}],"id":"af6fcc15-666c-46b0-a6f4-c5bdeb7fc3dd","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Phase 6: Load to PostgreSQL (Week 4)","type":"text"}],"id":"fb3e0a24-13d8-4861-a026-4a0cffead1cd","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# PySpark reads Gold Delta tables\n# Exports to CSV (or direct JDBC write for small data)\n# Postgres COPY command for bulk load (much faster than INSERT)\n# Upsert dim_customer using ON CONFLICT\n# Fact table: append-only, no duplicates (watermark prevents re-extract)","type":"text"}],"id":"add19021-4ca2-4d8f-9bfc-17008659dffa","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Phase 7: Data Quality Layer (Week 5)","type":"text"}],"id":"2d365ca1-819c-48c6-a637-fbdcd3785b18","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# Great Expectations suite:\n#   - Expect column ''order_id'' to never be null\n#   - Expect ''amount'' to be > 0\n#   - Expect row count > 100 (sanity check on extraction)\n#   - Expect schema to match expected types\n# Airflow task runs GE validation; fails DAG if violated","type":"text"}],"id":"ee84bd8a-03bb-4eb7-b9f4-a18f547a19b2","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Phase 8: Monitoring & Observability (Week 5)","type":"text"}],"id":"3f2836a4-0f09-4591-a497-9d4655e600fd","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# Create a pipeline_run_log table in Postgres\n# Each DAG run logs:\n#   - run_id, start_time, end_time, rows_extracted, rows_loaded, status\n# Build a simple monitoring dashboard (Metabase or even pandas + matplotlib)","type":"text"}],"id":"12614e06-cecd-4048-b52e-370ad97a42af","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Phase 9: Dockerization (Week 6)","type":"text"}],"id":"980dcaa7-137d-429a-9d01-ff674004d407","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# docker-compose.yml with:\n#   - airflow-webserver\n#   - airflow-scheduler\n#   - postgres (warehouse)\n#   - your FastAPI mock source\n#   - spark master (optional for true distributed mode)\n# One command: docker-compose up → entire pipeline runs","type":"text"}],"id":"067ebfef-7fc6-4a25-b9a3-3f3b822185ba","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Phase 10: Cloud Deployment (Optional — Week 7)","type":"text"}],"id":"586e7077-873e-4e0f-87c1-56e1c5580d64","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# Terraform to deploy on AWS:\n#   - EC2 for Airflow\n#   - RDS Postgres for warehouse\n#   - S3 for data lake (Bronze/Silver/Gold)\n#   - EMR or Glue for Spark (or stay with local Spark, just store in S3)\n# Result: cloud-deployed, production-ready pipeline","type":"text"}],"id":"907ada5d-901d-4a8d-a9eb-359f8f6e0c23","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"d90dce69-8b7d-4c6d-8fbc-cddc6cf06536","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"🎯 What Makes This Better Than Your Existing Projects","type":"text"}],"id":"1f43f6b1-0823-418a-97a3-062701e37c53","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Your Current Projects","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"This New Project","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Azure/Fabric-specific","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"Cloud-agnostic","type":"text"},{"styles":{},"text":" — works on any cloud or on-prem","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Platform UI-driven (ADF, Fabric)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"Code-first","type":"text"},{"styles":{},"text":" — Airflow DAGs, PySpark scripts you wrote","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Batch-only","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"Incremental load patterns","type":"text"},{"styles":{},"text":" — watermark-based, shows production thinking","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"No explicit orchestration code visible","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"Airflow DAGs you can show and explain line-by-line","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"No data quality layer visible","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"Great Expectations","type":"text"},{"styles":{},"text":" — codified quality checks","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Deployable only in Azure","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"Dockerized + Terraform","type":"text"},{"styles":{},"text":" — deployable anywhere","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"f88ff460-cb03-4cc1-9ce4-d552d1d0e022","props":{"textColor":"default"},"type":"table"},{"children":[],"id":"9cf4d983-384f-47f0-b927-6cfb184fbdc4","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"🎤 How You Defend Every Decision (Interview Prep)","type":"text"}],"id":"53fc6daf-1b34-4165-a9fa-5d1f5d574a3c","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Q: Why PySpark locally instead of pandas?","type":"text"},{"styles":{},"text":" → \"To prove I understand Spark''s distributed nature, not just managed Databricks. Running locally in client mode demonstrates the same concepts — partitions, transformations vs actions, lazy evaluation — that apply at scale.\"","type":"text"}],"id":"889382c1-fdea-42bf-af85-add3e7425c65","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Q: Why Delta Lake instead of plain Parquet?","type":"text"},{"styles":{},"text":" → \"ACID transactions, schema enforcement, and time travel. If a job fails mid-write, Delta rolls back. I can also query historical versions of the data — critical for debugging and auditing in production.\"","type":"text"}],"id":"37fc96ec-1fe3-4936-a8f0-9a9b596a24d1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Q: Why Airflow instead of ADF?","type":"text"},{"styles":{},"text":" → \"Airflow is open-source, Python-native, and transferable across any company. I wanted to show I can write orchestration logic as code, not just configure a UI.\"","type":"text"}],"id":"7e370261-91dc-4e3e-ace8-12f2684fe80e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Q: Why PostgreSQL instead of Snowflake/BigQuery?","type":"text"},{"styles":{},"text":" → \"To demonstrate I can design schemas, write optimized SQL, and manage a warehouse without relying on a managed service. Postgres is also widely used in startups and mid-size companies, so the skills transfer directly.\"","type":"text"}],"id":"4f1b11a7-201b-4fcc-94dc-a94ef877b2e5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Q: Why build a mock API instead of using a public dataset?","type":"text"},{"styles":{},"text":" → \"Real DE work involves extracting from APIs with authentication, pagination, and error handling. Building the API myself let me simulate realistic failure modes — rate limits, schema changes, downtime — and show I can handle them.\"","type":"text"}],"id":"8194a4f6-3901-47a7-9a25-29f956bc4334","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Q: Why Great Expectations?","type":"text"},{"styles":{},"text":" → \"Data quality can''t be an afterthought. GE lets me define expectations as code, version them, and fail pipelines automatically when quality degrades. It''s the DE equivalent of unit tests.\"","type":"text"}],"id":"a125a3e4-e035-4375-98b8-348ec4e315c3","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Q: Why not just use Databricks Community Edition?","type":"text"},{"styles":{},"text":" → \"I wanted to understand the raw components — Spark, Airflow, Delta — without abstraction layers. Databricks is excellent for production, but for learning and proving capability, building from primitives shows deeper understanding.\"","type":"text"}],"id":"8065e34c-bb2c-4d08-b8d8-f4aff1a75180","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"92cca4c8-1cab-424a-9990-d6abec22375a","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"✅ Final Deliverables (What Goes on GitHub)","type":"text"}],"id":"b609f43e-e413-4a44-9533-57ac37cea7a6","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"ecommerce-analytics-pipeline/\n│\n├── README.md                  ← Architecture diagram, setup instructions, design decisions\n├── docker-compose.yml         ← One-command local deployment\n├── requirements.txt           ← Python dependencies\n│\n├── data/                      ← Local data lake structure\n│   ├── raw/\n│   ├── bronze/\n│   ├── silver/\n│   └── gold/\n│\n├── airflow/\n│   ├── dags/\n│   │   ├── daily_pipeline.py          ← Main ETL DAG\n│   │   └── weekly_aggregation.py\n│   └── plugins/\n│\n├── spark/\n│   ├── jobs/\n│   │   ├── bronze_ingestion.py\n│   │   ├── silver_transformation.py\n│   │   └── gold_dimensional.py\n│   └── utils/\n│\n├── api/                       ← Your FastAPI mock source\n│   ├── main.py\n│   ├── models.py\n│   └── seed_data.py\n│\n├── sql/\n│   ├── schema.sql             ← Postgres warehouse DDL (Star schema)\n│   └── upsert_customers.sql\n│\n├── great_expectations/\n│   ├── expectations/\n│   └── checkpoints/\n│\n├── terraform/                 ← Optional AWS deployment\n│   ├── main.tf\n│   ├── variables.tf\n│   └── outputs.tf\n│\n└── docs/\n    ├── ARCHITECTURE.md        ← Deep dive on design decisions\n    ├── DATA_MODEL.md          ← ERD + Star schema explanation\n    └── RUNBOOK.md             ← How to run, troubleshoot, extend","type":"text"}],"id":"d4e766f7-f097-4335-9832-7a181f369782","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"46fb6fe7-b01b-41af-a917-c2f5d691e892","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"🎯 Timeline","type":"text"}],"id":"f2ca92c4-86c9-40b9-8662-7561c5b16076","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Week 1-2:","type":"text"},{"styles":{},"text":" Mock API + Airflow setup + basic ingestion","type":"text"}],"id":"df4b1dd4-f558-44a9-ac56-cc6661cbb9a4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Week 3-4:","type":"text"},{"styles":{},"text":" Bronze/Silver/Gold transformations in PySpark","type":"text"}],"id":"f0783d02-e8fb-4a43-8af0-4d8e3f5b72e4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Week 5:","type":"text"},{"styles":{},"text":" Data quality + PostgreSQL load + dimensional modeling","type":"text"}],"id":"d3dc1194-4bf2-4bff-bf52-6242ed6c293b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Week 6:","type":"text"},{"styles":{},"text":" Dockerization + documentation","type":"text"}],"id":"9b3079e5-270b-46ba-ae99-02b7f13e634f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Week 7 (optional):","type":"text"},{"styles":{},"text":" Terraform + AWS deployment","type":"text"}],"id":"3e53175c-81f5-4236-95bc-b5907618a058","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Total: 6-7 weeks","type":"text"},{"styles":{},"text":" if you work consistently 10-15 hours/week.","type":"text"}],"id":"ff986405-1d0d-4d04-bb43-9e75b52968d6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"b87776f1-9d30-41e1-9211-5be4b49e819e","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"🏆 Why This Gets You Hired","type":"text"}],"id":"ad1c4391-7933-46b1-8c43-0373c3ca69b5","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Shows you can build without vendor tools","type":"text"},{"styles":{},"text":" — critical for companies not locked into Azure","type":"text"}],"id":"fcbe9d86-3867-4da2-9c45-7bdbc7983bda","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Covers every interview topic","type":"text"},{"styles":{},"text":" — ETL, orchestration, dimensional modeling, data quality, performance","type":"text"}],"id":"f416698d-7e4f-4b2e-ac88-b1c516d7c82c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Tells a clear business story","type":"text"},{"styles":{},"text":" — every interviewer understands e-commerce metrics","type":"text"}],"id":"754af1c7-19dc-4a34-96b9-fabd5201cf47","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Deployable and demonstrable","type":"text"},{"styles":{},"text":" — you can literally run ","type":"text"},{"styles":{"code":true},"text":"docker-compose up","type":"text"},{"styles":{},"text":" in an interview","type":"text"}],"id":"24b76d81-7bfd-4c99-bb24-c9da6a2e984a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Depth over breadth","type":"text"},{"styles":{},"text":" — one well-architected project beats five shallow ones","type":"text"}],"id":"d3918509-7e00-4213-8bdd-68988dc82d89","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"You own every line","type":"text"},{"styles":{},"text":" — no tutorials, no copy-paste; you can defend every decision","type":"text"}],"id":"44ce7013-8db6-4a74-b99f-40ad13d30a61","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Combined with your existing Azure/Databricks projects, this shows you''re ","type":"text"},{"styles":{"bold":true},"text":"platform-agnostic, conceptually strong, and production-ready","type":"text"},{"styles":{},"text":" — exactly what big tech companies in Sri Lanka want.","type":"text"}],"id":"5b41b62b-267a-408d-9d9e-c9df5d47f50a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Want me to give you the ","type":"text"},{"styles":{"bold":true},"text":"detailed Phase 1 implementation","type":"text"},{"styles":{},"text":" (FastAPI mock source + initial Airflow DAG setup) so you can start building this weekend?","type":"text"}],"id":"21b047bf-6ee5-43f6-af40-c1c73f1a273b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[],"id":"68542dce-2b51-4a4a-bcd0-0f4c4f86fa9b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"}]'::jsonb, '3e9e3dd3-a59b-4b02-968a-ee95e7317583') ON CONFLICT ("node_id") DO UPDATE SET "bad_example" = EXCLUDED."bad_example", "completed_at" = EXCLUDED."completed_at", "created_at" = EXCLUDED."created_at", "definition" = EXCLUDED."definition", "good_example" = EXCLUDED."good_example", "is_completed" = EXCLUDED."is_completed", "key_points" = EXCLUDED."key_points", "last_edited" = EXCLUDED."last_edited", "map_id" = EXCLUDED."map_id", "mental_model" = EXCLUDED."mental_model", "notes" = EXCLUDED."notes", "resources" = EXCLUDED."resources", "rich_content" = EXCLUDED."rich_content", "user_id" = EXCLUDED."user_id";
