INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-06-19T05:45:40.594775+00:00', '', '', '01bb9cdf-88ff-4650-b479-a311f5ac498f', false, '[]'::jsonb, '2026-06-19T06:31:05.836+00:00', '2ad473fe-77dd-481e-8ba7-4b2b0336173f', '', '1d2119e1-1e5c-4a12-8d83-7befed858d96', '', '[]'::jsonb, '[{"children":[],"content":[{"styles":{},"text":"15 Targeted Data Engineering Scenario-Based Python Interview Questions — Control Flow","type":"text"}],"id":"ff34e571-d124-4790-88fe-67c7283cfc8c","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"id":"0e555147-244c-4b9a-aad3-52e2ab38c790","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Question 1: Classify Sales Order Priority","type":"text"}],"id":"f3e4c7f1-241f-4a5e-8a3d-4be635093ee2","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Scenario:","type":"text"}],"id":"b07a74d5-b954-4487-92d3-9dd636abb264","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"You are a fresher Data Engineer at ","type":"text"},{"styles":{"bold":true},"text":"Sysco","type":"text"},{"styles":{},"text":", a global food distribution company. Every sales order that arrives in the pipeline must be classified into a priority tier before it is dispatched to the warehouse system. The classification is based on the order''s total value. Only one tier can apply to each order — the tiers are mutually exclusive.","type":"text"}],"id":"145c5bb8-f002-44db-9737-aba714352de1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Task:","type":"text"}],"id":"c79c87b3-e05a-46fa-b3b3-f709439f808e","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Write a Python program that reads a single order amount and prints the correct priority tier:","type":"text"}],"id":"3bfbf5e7-064d-4c6e-afa8-1d89aedf4917","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"\"CRITICAL\"","type":"text"},{"styles":{},"text":" if amount >= 50000","type":"text"}],"id":"af197ed5-d531-4f2a-99ba-3621a39fd93b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"\"HIGH\"","type":"text"},{"styles":{},"text":" if amount >= 20000","type":"text"}],"id":"f3128905-dc62-4580-91c1-b7d47473f834","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"\"STANDARD\"","type":"text"},{"styles":{},"text":" if amount >= 5000","type":"text"}],"id":"ee9b27ba-d2ed-461e-9f86-971ad8967fda","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"\"LOW\"","type":"text"},{"styles":{},"text":" for anything below 5000","type":"text"}],"id":"6931678e-0d06-4fed-92dd-64f24ff4811f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Input:","type":"text"}],"id":"34e12bbc-a3b2-4753-ab4b-a6060ff8b2eb","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"order_amount = 23500","type":"text"}],"id":"fd112cda-3c81-4b22-b34f-63959a294d93","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Expected Output:","type":"text"}],"id":"c8e6092a-b47b-4c78-89bb-e8eaab2f06d1","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Order Priority: HIGH","type":"text"}],"id":"2913d1e4-2ab9-4f38-af5c-63a45b085381","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Concepts Tested:","type":"text"}],"id":"64e654f8-98e1-4b1f-835a-8126e5eda81e","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"code":true},"text":"if / elif / else","type":"text"},{"styles":{},"text":" chain (mutually exclusive classification)","type":"text"}],"id":"0546beba-23d0-449b-877c-e3973241b738","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Understanding that first matching gate wins and the rest are skipped","type":"text"}],"id":"ffa436bb-aedf-4f50-a0d6-af7af5bf4a8f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Starter Code:","type":"text"}],"id":"3523b622-4dba-4dcd-9224-86dff1a49536","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"order_amount = 23500\n\n# TODO: Use if/elif/else to classify the order\n# Only ONE tier should be printed — the first matching condition wins\n# Print: \"Order Priority: <TIER>\"","type":"text"}],"id":"c92cf5a3-a4dc-4d2b-9f73-c6acc75ee7bb","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Expected Solution:","type":"text"}],"id":"85cbc77d-f3d9-4cff-87cd-211aeca10f6f","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"order_amount = 23500\n\nif order_amount >= 50000:\n    priority = \"CRITICAL\"\nelif order_amount >= 20000:\n    priority = \"HIGH\"\nelif order_amount >= 5000:\n    priority = \"STANDARD\"\nelse:\n    priority = \"LOW\"\n\nprint(\"Order Priority:\", priority)","type":"text"}],"id":"7c8712b2-f888-49e1-82f5-83020ceeb94d","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Interview Explanation:","type":"text"}],"id":"cf367089-d5c4-41f4-9a88-ec7e00851a6f","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"This uses an ","type":"text"},{"styles":{"code":true},"text":"if/elif/else","type":"text"},{"styles":{},"text":" chain because each order belongs to exactly one tier — the tiers are mutually exclusive. The moment the first true condition is found, Python skips all remaining checks. This is the correct tool when only one outcome should run. The most common fresher mistake here is using four separate ","type":"text"},{"styles":{"code":true},"text":"if","type":"text"},{"styles":{},"text":" statements instead of ","type":"text"},{"styles":{"code":true},"text":"elif","type":"text"},{"styles":{},"text":", which would allow multiple tiers to print for the same order — a classic data quality bug in classification pipelines. In real Data Engineering, incorrect classification leads to wrong routing of orders to warehouses. Getting this right means the downstream systems receive clean, single-category records.","type":"text"}],"id":"38e252b5-ffa0-4dd5-9665-15598c733e45","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"ea8f933c-4664-47dd-9c60-145d3cf04a34","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Question 2: Multi-Check Validation on a Financial Record","type":"text"}],"id":"8ec07986-63ae-4f1a-89c9-645d97b8f427","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Scenario:","type":"text"}],"id":"e11d0581-7dfc-4806-bb9d-8c189fe5f9db","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"You are working on an audit pipeline at ","type":"text"},{"styles":{"bold":true},"text":"EY","type":"text"},{"styles":{},"text":". Before any financial transaction record is accepted into the ledger, it must pass three independent compliance checks:","type":"text"}],"id":"1d68bff7-bc43-4623-8f87-d038025b7d4c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"The amount must be greater than zero","type":"text"}],"id":"b01ed318-2900-4617-99d6-d4a63b549320","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"The transaction type must be either ","type":"text"},{"styles":{"code":true},"text":"\"CREDIT\"","type":"text"},{"styles":{},"text":" or ","type":"text"},{"styles":{"code":true},"text":"\"DEBIT\"","type":"text"}],"id":"fe11afc4-053f-4a31-a6dd-dbd3fcbc5c2f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"The currency must be ","type":"text"},{"styles":{"code":true},"text":"\"USD\"","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"\"EUR\"","type":"text"},{"styles":{},"text":", or ","type":"text"},{"styles":{"code":true},"text":"\"LKR\"","type":"text"}],"id":"4dac619e-f042-450c-a113-da5fb937ad23","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Each check is independent — even if the first check fails, the system must still report which other checks failed. All three issues must be reported in a single run.","type":"text"}],"id":"ffaefc95-3226-4399-abe9-b35bddff530d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Task:","type":"text"}],"id":"342e295c-041b-4bba-b7a5-02a1ff0c1f06","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Write a Python program that runs all three checks on the given transaction record and prints a separate warning message for each check that fails.","type":"text"}],"id":"a87e7473-7bbe-480e-9620-191f6a053772","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Input:","type":"text"}],"id":"5671e5ac-8ee0-4910-8656-9a50493a84fb","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"transaction = {\n    \"id\": \"TXN-4421\",\n    \"amount\": -500,\n    \"type\": \"TRANSFER\",\n    \"currency\": \"JPY\"\n}","type":"text"}],"id":"99c6adb3-f899-41da-b33b-a72735fb0843","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Expected Output:","type":"text"}],"id":"8398900e-1298-4bfa-8464-d7926d01b2c5","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"[TXN-4421] FAIL: Amount must be greater than zero\n[TXN-4421] FAIL: Transaction type is invalid\n[TXN-4421] FAIL: Currency is not supported","type":"text"}],"id":"ce47d487-4dd8-4d92-9214-4f5035bf548a","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Concepts Tested:","type":"text"}],"id":"39417e9b-502d-483c-ac7a-975153fe9b38","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Three separate ","type":"text"},{"styles":{"code":true},"text":"if","type":"text"},{"styles":{},"text":" statements (independent checks, not mutually exclusive)","type":"text"}],"id":"fbb7025d-fc06-448f-83a6-54cf7229059f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Understanding when to use separate ","type":"text"},{"styles":{"code":true},"text":"if","type":"text"},{"styles":{},"text":" vs ","type":"text"},{"styles":{"code":true},"text":"elif","type":"text"}],"id":"f5714d07-1172-4aec-a787-dbf7a01afcdc","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Starter Code:","type":"text"}],"id":"1155f865-95e2-4f2b-b1d1-40c35db3f49a","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"transaction = {\n    \"id\": \"TXN-4421\",\n    \"amount\": -500,\n    \"type\": \"TRANSFER\",\n    \"currency\": \"JPY\"\n}\n\ntxn_id = transaction[\"id\"]\n\n# TODO: Check 1 — amount must be > 0\n# TODO: Check 2 — type must be \"CREDIT\" or \"DEBIT\"\n# TODO: Check 3 — currency must be \"USD\", \"EUR\", or \"LKR\"\n# Each check must run independently — use separate if statements","type":"text"}],"id":"663b7fa8-8f60-43f1-9dc0-b7109ff30d88","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Expected Solution:","type":"text"}],"id":"b3a68049-d029-4226-b92d-e74729945d6f","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"transaction = {\n    \"id\": \"TXN-4421\",\n    \"amount\": -500,\n    \"type\": \"TRANSFER\",\n    \"currency\": \"JPY\"\n}\n\ntxn_id = transaction[\"id\"]\n\nif transaction[\"amount\"] <= 0:\n    print(f\"[{txn_id}] FAIL: Amount must be greater than zero\")\n\nif transaction[\"type\"] not in [\"CREDIT\", \"DEBIT\"]:\n    print(f\"[{txn_id}] FAIL: Transaction type is invalid\")\n\nif transaction[\"currency\"] not in [\"USD\", \"EUR\", \"LKR\"]:\n    print(f\"[{txn_id}] FAIL: Currency is not supported\")","type":"text"}],"id":"ea9c6bd8-5ade-444d-89f6-25f41caf74fe","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Interview Explanation:","type":"text"}],"id":"78066048-0232-437d-84a7-fed90c8361d9","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Three separate ","type":"text"},{"styles":{"code":true},"text":"if","type":"text"},{"styles":{},"text":" statements are used here because all three validation rules are independent of each other — a record can fail one, two, or all three simultaneously. If ","type":"text"},{"styles":{"code":true},"text":"elif","type":"text"},{"styles":{},"text":" were used instead, Python would stop checking after the first failure, hiding the other two problems from the audit report. In a real EY-style compliance pipeline, reporting all failures at once is critical so the data team can fix everything in one correction cycle rather than discovering issues one at a time. The key interview insight is: use ","type":"text"},{"styles":{"code":true},"text":"elif","type":"text"},{"styles":{},"text":" only when conditions are mutually exclusive, and use separate ","type":"text"},{"styles":{"code":true},"text":"if","type":"text"},{"styles":{},"text":" when each condition must be evaluated on its own. Confusing these two causes silent data quality bugs that are very hard to trace later.","type":"text"}],"id":"46a07027-54c0-46f7-98d8-7ddd222eee53","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"b3197301-d6a3-4169-9210-485cd63af0bf","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Question 3: Nested Validation — Status Before Amount","type":"text"}],"id":"9af4ea43-0b6d-4a4f-a351-750c2ed76785","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Scenario:","type":"text"}],"id":"f605a487-4ee3-43fc-8ac2-9ed276a1b91b","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"At ","type":"text"},{"styles":{"bold":true},"text":"Dialog Axiata","type":"text"},{"styles":{},"text":", a telecom company, customer recharge records are processed daily. Before checking whether a recharge amount is valid, the system must first confirm that the customer account is ","type":"text"},{"styles":{"bold":true},"text":"ACTIVE","type":"text"},{"styles":{},"text":". Suspended or inactive accounts must be rejected before any amount check even begins — processing an amount for an inactive account wastes pipeline resources and corrupts reports.","type":"text"}],"id":"5e1e9138-2b8d-4216-b76c-ef5b16ef3f8c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Task:","type":"text"}],"id":"4ce59b45-3a85-4560-a082-829e1078b2a7","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Write a Python program that first checks if the customer status is ","type":"text"},{"styles":{"code":true},"text":"\"ACTIVE\"","type":"text"},{"styles":{},"text":". Only if the account is active should it then check whether the recharge amount is greater than zero. Print an appropriate message for each case.","type":"text"}],"id":"b0a42c1f-d4ab-4cac-ba8e-8db291ce9798","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Input:","type":"text"}],"id":"a4ced664-2022-49c4-bf09-c3e28a7d4fb2","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"customer = {\"id\": \"DLG-8821\", \"status\": \"ACTIVE\", \"recharge_amount\": -100}","type":"text"}],"id":"a7e8472a-f122-4287-9b03-1869d5c98fec","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Expected Output:","type":"text"}],"id":"19c6c415-fad6-40be-846e-7e5efad181ed","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"[DLG-8821] Account is active. Checking amount...\n[DLG-8821] FAIL: Recharge amount must be greater than zero","type":"text"}],"id":"b5ab56b6-4456-4741-9d4b-f994682452fa","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Concepts Tested:","type":"text"}],"id":"91ded8f2-379d-4ef9-9c8c-4bde4b0bf369","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Nested ","type":"text"},{"styles":{"code":true},"text":"if","type":"text"},{"styles":{},"text":" (outer gate: status check; inner gate: amount check)","type":"text"}],"id":"d33d1930-d7d5-4e72-ba06-93834b93ce5d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Understanding that the inner check only runs when the outer check passes","type":"text"}],"id":"8041dabe-34b8-443b-bcf6-60d88d10b8f3","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Starter Code:","type":"text"}],"id":"573b2551-e38d-4048-b0e8-0e2f6f9dfd22","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"customer = {\"id\": \"DLG-8821\", \"status\": \"ACTIVE\", \"recharge_amount\": -100}\n\ncid = customer[\"id\"]\n\n# TODO: Outer if — check if status is \"ACTIVE\"\n#   If active, print that account is active and checking amount\n#   TODO: Inner if/else — check if recharge_amount > 0\n#     If valid, print success\n#     If not, print failure\n# TODO: else for outer if — print account is not active, record rejected","type":"text"}],"id":"099d1078-844f-44db-8d9f-f610797ac2cd","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Expected Solution:","type":"text"}],"id":"3b37aa0e-2caa-4706-bb21-2af488f78f5c","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"customer = {\"id\": \"DLG-8821\", \"status\": \"ACTIVE\", \"recharge_amount\": -100}\n\ncid = customer[\"id\"]\n\nif customer[\"status\"] == \"ACTIVE\":\n    print(f\"[{cid}] Account is active. Checking amount...\")\n    if customer[\"recharge_amount\"] > 0:\n        print(f\"[{cid}] Recharge of {customer[''recharge_amount'']} accepted.\")\n    else:\n        print(f\"[{cid}] FAIL: Recharge amount must be greater than zero\")\nelse:\n    print(f\"[{cid}] FAIL: Account is not active. Record rejected.\")","type":"text"}],"id":"cf154d4a-cf76-4b00-bb5f-93e0223a8480","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Interview Explanation:","type":"text"}],"id":"8196f837-7540-4f68-97c7-8957ecb9ec54","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Nested ","type":"text"},{"styles":{"code":true},"text":"if","type":"text"},{"styles":{},"text":" is the right choice here because the amount check is meaningless unless the account is first confirmed as active — one condition is a prerequisite for the other. This mirrors real pipeline design where you gate deeper validation behind a status check to avoid wasting compute and generating misleading reports. The outer gate handles account state, and the inner gate handles business rules that only apply to valid accounts. A common fresher mistake is to run both checks as separate ","type":"text"},{"styles":{"code":true},"text":"if","type":"text"},{"styles":{},"text":" statements, which would check the amount even for suspended accounts and produce confusing output. In Data Engineering, gating logic like this prevents garbage-in-garbage-out problems in downstream systems.","type":"text"}],"id":"ab6035dd-508f-4925-bdf9-b847d2b7645d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"d0b432db-3728-4fb1-be52-db186449dad0","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Question 4: Label Transactions with a Ternary Expression","type":"text"}],"id":"f892e59b-f4d8-4f1c-a26f-2d3caf9ff9d2","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Scenario:","type":"text"}],"id":"cfbac256-9a99-4022-a119-fd5c999569dd","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"At ","type":"text"},{"styles":{"bold":true},"text":"EY","type":"text"},{"styles":{},"text":", the audit team processes a list of financial transaction amounts. For quick reporting, each transaction must be labeled as either ","type":"text"},{"styles":{"code":true},"text":"\"LARGE\"","type":"text"},{"styles":{},"text":" if the amount is 100,000 or more, or ","type":"text"},{"styles":{"code":true},"text":"\"SMALL\"","type":"text"},{"styles":{},"text":" for anything below. This label is added to a summary line — it is a simple one-condition, two-outcome assignment that does not need a full ","type":"text"},{"styles":{"code":true},"text":"if/else","type":"text"},{"styles":{},"text":" block.","type":"text"}],"id":"65270169-9ca8-429f-a8f0-496fd9062cd8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Task:","type":"text"}],"id":"b261ef55-3114-4ab2-baf1-cce55bd30f53","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Write a Python program that loops through the list of amounts and for each one, uses a ","type":"text"},{"styles":{"bold":true},"text":"ternary expression","type":"text"},{"styles":{},"text":" to assign the label, then prints the amount and its label on one line.","type":"text"}],"id":"5afe4ce7-587e-4eaf-b609-bd8186299a47","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Input:","type":"text"}],"id":"f5c822b6-cf4b-4e13-8dac-2bd7d89efcad","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"amounts = [250000, 4500, 100000, 75000, 1200000]","type":"text"}],"id":"dfacf160-5d21-44a3-8404-ef3014374ba5","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Expected Output:","type":"text"}],"id":"ca408e51-75bc-4eab-a4bc-f76f48ac011f","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"250000 -> LARGE\n4500 -> SMALL\n100000 -> LARGE\n75000 -> SMALL\n1200000 -> LARGE","type":"text"}],"id":"2953b650-6860-4de3-8eef-f9da0b2a4979","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Concepts Tested:","type":"text"}],"id":"8fac3c9b-eb89-4faa-88be-cdb2f6934a05","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Ternary expression (","type":"text"},{"styles":{"code":true},"text":"result = A if condition else B","type":"text"},{"styles":{},"text":")","type":"text"}],"id":"fa3b071c-0a9b-49cf-9316-3a160bc81d8f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"code":true},"text":"for","type":"text"},{"styles":{},"text":" loop to process a list","type":"text"}],"id":"a4761be7-e0e1-4601-b9fe-97b56e646b0f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"When to use ternary vs full ","type":"text"},{"styles":{"code":true},"text":"if/else","type":"text"}],"id":"2d8151a9-4bb9-4813-8d75-1ad6e071d4c6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Starter Code:","type":"text"}],"id":"4d256a32-f8ee-4633-8ba3-c5c750fee487","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"amounts = [250000, 4500, 100000, 75000, 1200000]\n\nfor amount in amounts:\n    # TODO: Use a ternary expression to assign label\n    # label = \"LARGE\" if ... else \"SMALL\"\n    # TODO: Print: \"<amount> -> <label>\"\n    pass","type":"text"}],"id":"59e9cd10-bc56-4cac-91b6-5246eef4f893","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Expected Solution:","type":"text"}],"id":"f4e493f1-d30b-434d-9e26-d4279ba5981e","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"amounts = [250000, 4500, 100000, 75000, 1200000]\n\nfor amount in amounts:\n    label = \"LARGE\" if amount >= 100000 else \"SMALL\"\n    print(f\"{amount} -> {label}\")","type":"text"}],"id":"d9c092cf-f75e-4259-b9bb-61abb2920cbc","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Interview Explanation:","type":"text"}],"id":"5ad7d7ed-f97b-4ee0-8121-f8a1215ee089","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The ternary expression is the right choice here because the decision is a simple one-condition, two-outcome value assignment — exactly what it is designed for. Using a full ","type":"text"},{"styles":{"code":true},"text":"if/else","type":"text"},{"styles":{},"text":" block inside the loop would work but adds unnecessary lines for such a straightforward label assignment. In real Data Engineering pipelines, ternary expressions are commonly used when tagging or labeling records in a transformation step — for example, flagging records as valid or invalid, large or small, before writing to a staging table. The important rule to remember is that ternary should only be used for assignment — if you need to print, log, or do multiple things, use a full ","type":"text"},{"styles":{"code":true},"text":"if/else","type":"text"},{"styles":{},"text":" instead. This question also reinforces the ","type":"text"},{"styles":{"code":true},"text":"for","type":"text"},{"styles":{},"text":" loop pattern of visiting every record exactly once.","type":"text"}],"id":"a97d6228-5e16-4216-976e-ece60e15d04b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"5a845177-f10f-472d-82f7-cee32c1cc893","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Question 5: Calculate Total Sales from a List of Orders","type":"text"}],"id":"6a1ff02f-a9c8-49b9-b9db-d2413d9c8c0f","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Scenario:","type":"text"}],"id":"a6c25ca9-b8f2-4c06-bb2f-a4632213098f","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"At ","type":"text"},{"styles":{"bold":true},"text":"Sysco","type":"text"},{"styles":{},"text":", the data pipeline ingests daily sales orders from distribution centers. At the end of each batch run, the pipeline must calculate the total sales value from all orders received and report how many orders were processed. This is a standard aggregation step before the data moves to the reporting layer.","type":"text"}],"id":"f3bf8806-0d44-4860-b3be-0be51c107b45","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Task:","type":"text"}],"id":"91ecbad3-2fcc-4464-8749-74337859fe5b","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Write a Python program that loops through the list of order amounts, calculates the total sales value, counts the number of orders, and prints both at the end.","type":"text"}],"id":"f7451904-4702-4cef-9f2d-1dcd4d064669","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Input:","type":"text"}],"id":"f14ec576-0406-4e43-94b7-007f8f4d54b3","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"orders = [12500, 43000, 8750, 97000, 5300, 62000]","type":"text"}],"id":"0c292c7c-eaba-40e4-89fd-fb8fd708cc92","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Expected Output:","type":"text"}],"id":"607ab287-84d9-4ee1-b0ca-c249e13a573a","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Orders Processed: 6\nTotal Sales Value: 228550","type":"text"}],"id":"2f42c906-3330-49af-8605-e88a09f11594","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Concepts Tested:","type":"text"}],"id":"dcfa5556-2f29-4945-a945-ab7b8dc9a7e3","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"code":true},"text":"for","type":"text"},{"styles":{},"text":" loop for processing a list of records","type":"text"}],"id":"e0a6ab32-15f5-40be-8ef4-c049f1bd23de","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Counter and running total variables","type":"text"}],"id":"a5b12eae-08c5-463c-a196-fdef1a754cdc","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Accumulation pattern in data pipelines","type":"text"}],"id":"099691a2-6752-419f-9ef2-a68bccb86251","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Starter Code:","type":"text"}],"id":"caa5ec3b-8ad8-4acd-8571-e5576cad7e2d","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"orders = [12500, 43000, 8750, 97000, 5300, 62000]\n\n# TODO: Initialize a counter and a total variable before the loop\n# TODO: Loop through orders\n#   Add each order to total\n#   Increment counter by 1\n# TODO: Print orders processed and total sales value","type":"text"}],"id":"6f8b81e9-f413-4291-afa9-00bcee800af8","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Expected Solution:","type":"text"}],"id":"fe6937c9-e998-4a4d-ad2c-7464363ff671","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"orders = [12500, 43000, 8750, 97000, 5300, 62000]\n\ntotal = 0\ncount = 0\n\nfor order in orders:\n    total += order\n    count += 1\n\nprint(\"Orders Processed:\", count)\nprint(\"Total Sales Value:\", total)","type":"text"}],"id":"0cd582df-f73c-4544-b891-1a3247cf66f8","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Interview Explanation:","type":"text"}],"id":"28a87be5-aadd-4bb4-904c-c46e5595d0d1","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"This question tests the most fundamental data pipeline pattern: iterating over a collection of records and accumulating values into counters and totals. Initializing ","type":"text"},{"styles":{"code":true},"text":"total","type":"text"},{"styles":{},"text":" and ","type":"text"},{"styles":{"code":true},"text":"count","type":"text"},{"styles":{},"text":" before the loop is critical — a very common fresher mistake is placing the initialization inside the loop, which resets the values on every iteration and produces a wrong result. In real pipelines at Sysco or similar companies, this pattern is used constantly — summing invoice amounts, counting records per batch, or computing totals per product category before loading into a data warehouse. The ","type":"text"},{"styles":{"code":true},"text":"for","type":"text"},{"styles":{},"text":" loop is the right choice here because the number of records is known before the loop starts. This simple pattern forms the backbone of most ETL aggregation logic.","type":"text"}],"id":"5c2710b7-4801-4b9d-a48d-ee32fac99f2d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"141601eb-4546-437c-81be-ea52da3cbb95","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Question 6: Skip Incomplete Recharge Records","type":"text"}],"id":"ca9084cc-44f7-45c4-a148-8a08eedbfc7b","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Scenario:","type":"text"}],"id":"f4081c34-ae4e-4422-8019-bac0c4e78d46","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"At ","type":"text"},{"styles":{"bold":true},"text":"Dialog Axiata","type":"text"},{"styles":{},"text":", the daily recharge data feed sometimes contains incomplete records where the recharge amount is ","type":"text"},{"styles":{"code":true},"text":"None","type":"text"},{"styles":{},"text":" or zero — these arrive due to network timeouts or incomplete API responses upstream. The pipeline must skip these bad records and process only the valid ones to calculate the total valid recharge revenue for the day.","type":"text"}],"id":"173fb00f-25a2-4dbb-8e63-3ee36ae123c4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Task:","type":"text"}],"id":"bd51f2fb-e4ca-49d2-8d10-5a506363ebe9","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Write a Python program that loops through the recharge records. If a record''s amount is ","type":"text"},{"styles":{"code":true},"text":"None","type":"text"},{"styles":{},"text":" or zero, ","type":"text"},{"styles":{"bold":true},"text":"skip it","type":"text"},{"styles":{},"text":" using ","type":"text"},{"styles":{"code":true},"text":"continue","type":"text"},{"styles":{},"text":" and print a skip message. For valid records, add the amount to the total and print a processing message. Print the final total at the end.","type":"text"}],"id":"f8b2ee98-a842-46b7-9dee-737ee9902257","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Input:","type":"text"}],"id":"30612f28-1bd6-45a7-9d8f-1107d6bcb493","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"recharges = [\n    {\"customer_id\": \"DLG-001\", \"amount\": 500},\n    {\"customer_id\": \"DLG-002\", \"amount\": None},\n    {\"customer_id\": \"DLG-003\", \"amount\": 0},\n    {\"customer_id\": \"DLG-004\", \"amount\": 1500},\n    {\"customer_id\": \"DLG-005\", \"amount\": 750},\n]","type":"text"}],"id":"b4b90e16-8bbf-43d2-bdb3-896bbad5633d","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Expected Output:","type":"text"}],"id":"8b003dfd-71bc-4556-aee2-c30b4a48f1a1","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"[DLG-001] Processed: 500\n[DLG-002] Skipped: missing amount\n[DLG-003] Skipped: missing amount\n[DLG-004] Processed: 1500\n[DLG-005] Processed: 750\nTotal valid recharge revenue: 2750","type":"text"}],"id":"c49dacf9-8319-4384-ad1e-95aa90159acd","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Concepts Tested:","type":"text"}],"id":"bb914200-48a5-47d1-8d87-69c07f95b654","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"code":true},"text":"for","type":"text"},{"styles":{},"text":" loop for record processing","type":"text"}],"id":"3426074f-615e-4201-acc8-5eb7633bc7dc","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"code":true},"text":"continue","type":"text"},{"styles":{},"text":" to skip bad records and keep the loop running","type":"text"}],"id":"cc8e166a-ad67-4e39-9657-e86d7f0b7413","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Running total accumulation","type":"text"}],"id":"e7e4a82e-eb65-4057-ae62-125514bc5252","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Difference between ","type":"text"},{"styles":{"code":true},"text":"continue","type":"text"},{"styles":{},"text":" (skip one) and ","type":"text"},{"styles":{"code":true},"text":"break","type":"text"},{"styles":{},"text":" (stop all)","type":"text"}],"id":"b5fde2ff-8435-4b2f-a25f-4bbb7fa5e637","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Starter Code:","type":"text"}],"id":"139caa6d-5a43-4996-9936-f2ccdeea10ca","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"recharges = [\n    {\"customer_id\": \"DLG-001\", \"amount\": 500},\n    {\"customer_id\": \"DLG-002\", \"amount\": None},\n    {\"customer_id\": \"DLG-003\", \"amount\": 0},\n    {\"customer_id\": \"DLG-004\", \"amount\": 1500},\n    {\"customer_id\": \"DLG-005\", \"amount\": 750},\n]\n\ntotal = 0\n\nfor record in recharges:\n    cid = record[\"customer_id\"]\n    amount = record[\"amount\"]\n\n    # TODO: If amount is None or 0, print skip message and use continue\n    # TODO: Add valid amount to total and print processing message\n\n# TODO: Print final total","type":"text"}],"id":"c98570c2-565a-43b0-8b54-0153d4eae526","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Expected Solution:","type":"text"}],"id":"2cd579a4-8d49-4be4-8bc6-4c6eaa0b2005","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"recharges = [\n    {\"customer_id\": \"DLG-001\", \"amount\": 500},\n    {\"customer_id\": \"DLG-002\", \"amount\": None},\n    {\"customer_id\": \"DLG-003\", \"amount\": 0},\n    {\"customer_id\": \"DLG-004\", \"amount\": 1500},\n    {\"customer_id\": \"DLG-005\", \"amount\": 750},\n]\n\ntotal = 0\n\nfor record in recharges:\n    cid = record[\"customer_id\"]\n    amount = record[\"amount\"]\n\n    if not amount:\n        print(f\"[{cid}] Skipped: missing amount\")\n        continue\n\n    total += amount\n    print(f\"[{cid}] Processed: {amount}\")\n\nprint(\"Total valid recharge revenue:\", total)","type":"text"}],"id":"8758d8ad-0636-4726-aab7-e168ef3f3244","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Interview Explanation:","type":"text"}],"id":"7ba1b32a-c8e0-4422-8995-7fb7d3fad51b","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"code":true},"text":"continue","type":"text"},{"styles":{},"text":" is the correct tool here because we want to skip one bad record and immediately continue processing the remaining records — the loop must not stop entirely. Using ","type":"text"},{"styles":{"code":true},"text":"break","type":"text"},{"styles":{},"text":" instead would be a critical bug — it would stop the entire pipeline the moment one bad record is encountered, leaving valid records unprocessed and causing revenue undercounting. This pattern — skip bad data, process only valid records — is one of the most common patterns in real ETL pipelines. In Dialog''s data infrastructure, incomplete recharge records are common due to upstream network issues, so the pipeline must be resilient enough to handle them without failing. The ","type":"text"},{"styles":{"code":true},"text":"if not amount","type":"text"},{"styles":{},"text":" check elegantly handles both ","type":"text"},{"styles":{"code":true},"text":"None","type":"text"},{"styles":{},"text":" and ","type":"text"},{"styles":{"code":true},"text":"0","type":"text"},{"styles":{},"text":" in one condition.","type":"text"}],"id":"5fb2ec73-e3f3-47cd-b833-5ec1638c814b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"a8a48911-81de-4d12-9009-10846df79f98","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Question 7: Stop Pipeline on First Critical Stock Failure","type":"text"}],"id":"4d7d01c3-baff-4586-85c5-41303d558c20","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Scenario:","type":"text"}],"id":"ac880fe2-094f-4528-bdaa-60572c62a556","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"At ","type":"text"},{"styles":{"bold":true},"text":"Sysco","type":"text"},{"styles":{},"text":", before dispatching a batch of food product orders, the pipeline must verify that every product in the batch has sufficient stock. If ","type":"text"},{"styles":{"bold":true},"text":"any","type":"text"},{"styles":{},"text":" product has zero stock, it is a critical blocker — the entire dispatch batch must be halted immediately and the issue escalated. There is no point checking the remaining products once a critical failure is found, because the batch cannot proceed regardless.","type":"text"}],"id":"28146942-13bf-4c4d-914d-762ec3856d89","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Task:","type":"text"}],"id":"f6696f56-bac9-4029-89f0-b8c1150c8e99","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Write a Python program that loops through the product stock records. The moment any product has ","type":"text"},{"styles":{"code":true},"text":"stock = 0","type":"text"},{"styles":{},"text":", print a critical alert and ","type":"text"},{"styles":{"bold":true},"text":"stop checking immediately","type":"text"},{"styles":{},"text":" using ","type":"text"},{"styles":{"code":true},"text":"break","type":"text"},{"styles":{},"text":". If a product passes, print a confirmation. Print a summary line after the loop.","type":"text"}],"id":"39aeda12-3192-46d9-8bac-c3a89b69d0c5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Input:","type":"text"}],"id":"5a7982e1-12f9-4b0d-af38-18141fd7beae","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"products = [\n    {\"name\": \"Canned Tomatoes\", \"stock\": 450},\n    {\"name\": \"Olive Oil\", \"stock\": 120},\n    {\"name\": \"Pasta\", \"stock\": 0},\n    {\"name\": \"Black Pepper\", \"stock\": 300},\n    {\"name\": \"Sugar\", \"stock\": 0},\n]","type":"text"}],"id":"5a7c34eb-ce4e-4e99-ae76-a4b0c7fc049c","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Expected Output:","type":"text"}],"id":"35435d5d-2608-4b65-95e8-9fe826ddc4e2","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"[Canned Tomatoes] Stock OK: 450 units\n[Olive Oil] Stock OK: 120 units\n[Pasta] CRITICAL: Zero stock detected. Halting dispatch batch.\nDispatch batch halted after critical stock failure.","type":"text"}],"id":"115ca195-9489-4430-858e-5b9d8ffa69d3","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Concepts Tested:","type":"text"}],"id":"7f449e32-660f-4219-b77d-359d3fdc7460","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"code":true},"text":"for","type":"text"},{"styles":{},"text":" loop with ","type":"text"},{"styles":{"code":true},"text":"break","type":"text"},{"styles":{},"text":" to stop early on critical failure","type":"text"}],"id":"43d962aa-9b6d-48c1-87c2-abf23962ef8f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Understanding that ","type":"text"},{"styles":{"code":true},"text":"break","type":"text"},{"styles":{},"text":" exits the entire loop immediately","type":"text"}],"id":"a3900168-0da8-446b-82b9-f69ae3b3d8e2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Remaining records are untouched after ","type":"text"},{"styles":{"code":true},"text":"break","type":"text"}],"id":"2d8120cd-b592-4c29-affd-27285bf58fb7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Starter Code:","type":"text"}],"id":"a469bb88-8d31-4c72-80ff-6a44d788f98a","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"products = [\n    {\"name\": \"Canned Tomatoes\", \"stock\": 450},\n    {\"name\": \"Olive Oil\", \"stock\": 120},\n    {\"name\": \"Pasta\", \"stock\": 0},\n    {\"name\": \"Black Pepper\", \"stock\": 300},\n    {\"name\": \"Sugar\", \"stock\": 0},\n]\n\nbatch_halted = False\n\nfor product in products:\n    name = product[\"name\"]\n    stock = product[\"stock\"]\n\n    # TODO: If stock is 0, print CRITICAL message, set batch_halted = True, and break\n    # TODO: Otherwise print stock OK message\n\n# TODO: Print summary line if batch_halted is True","type":"text"}],"id":"5134c4bb-7f02-4961-bd5a-96725ba88694","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Expected Solution:","type":"text"}],"id":"0dea719c-2a6b-4cb8-9464-961197afe813","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"products = [\n    {\"name\": \"Canned Tomatoes\", \"stock\": 450},\n    {\"name\": \"Olive Oil\", \"stock\": 120},\n    {\"name\": \"Pasta\", \"stock\": 0},\n    {\"name\": \"Black Pepper\", \"stock\": 300},\n    {\"name\": \"Sugar\", \"stock\": 0},\n]\n\nbatch_halted = False\n\nfor product in products:\n    name = product[\"name\"]\n    stock = product[\"stock\"]\n\n    if stock == 0:\n        print(f\"[{name}] CRITICAL: Zero stock detected. Halting dispatch batch.\")\n        batch_halted = True\n        break\n\n    print(f\"[{name}] Stock OK: {stock} units\")\n\nif batch_halted:\n    print(\"Dispatch batch halted after critical stock failure.\")","type":"text"}],"id":"7eb1f12c-e0cc-45c1-83d1-d90e8d2ac102","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Interview Explanation:","type":"text"}],"id":"31c8dccd-fcd8-43ae-8f0e-688c7fce3f52","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"code":true},"text":"break","type":"text"},{"styles":{},"text":" is the correct choice here because once a critical stock failure is detected, there is no business reason to continue checking the rest — the entire batch is blocked regardless. This is the \"fire alarm\" pattern: when a critical condition is found, exit the entire loop immediately. Note that ","type":"text"},{"styles":{"code":true},"text":"Sugar","type":"text"},{"styles":{},"text":" with zero stock is never even reached because the loop exits at ","type":"text"},{"styles":{"code":true},"text":"Pasta","type":"text"},{"styles":{},"text":" — this is the intended behavior when we want fast-fail behavior in a pipeline. A common fresher mistake is using ","type":"text"},{"styles":{"code":true},"text":"continue","type":"text"},{"styles":{},"text":" instead of ","type":"text"},{"styles":{"code":true},"text":"break","type":"text"},{"styles":{},"text":", which would skip the failed product and keep checking — this is wrong because the batch is already blocked and we are doing unnecessary work. In Sysco''s supply chain pipelines, catching the first critical blocker early and stopping is more efficient than discovering all blockers only after a full scan.","type":"text"}],"id":"55cff19c-cc89-47dc-a31d-e9247327e358","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"a0953cfc-769a-464a-948c-2908c45da847","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Question 8: Report Row Numbers of Invalid Transactions","type":"text"}],"id":"3b3a2b8e-9160-405a-96c7-04a84a3f4195","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Scenario:","type":"text"}],"id":"adf7169b-fb66-4a00-8d62-4e91fcb83c03","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"At ","type":"text"},{"styles":{"bold":true},"text":"EY","type":"text"},{"styles":{},"text":", the audit team receives a flat list of transaction amounts exported from a client''s financial system. Some amounts are negative, which should never occur in this particular ledger — they represent data entry errors. The audit report must identify not just which amounts are invalid, but the ","type":"text"},{"styles":{"bold":true},"text":"exact row number","type":"text"},{"styles":{},"text":" (starting from Row 1) where each invalid record appears, so the client''s data team can locate and fix them in the source system.","type":"text"}],"id":"c49db202-3d38-4b6f-b29f-e081b223775d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Task:","type":"text"}],"id":"284f9bc1-70f7-40c7-843a-cc8ec3f4ab55","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Write a Python program using ","type":"text"},{"styles":{"code":true},"text":"enumerate()","type":"text"},{"styles":{},"text":" to loop through the transaction amounts. For each negative amount, print the row number (starting from 1) and the invalid amount. Count and print the total number of invalid records found.","type":"text"}],"id":"8c7aad70-dbd1-4cee-958d-ed5571a65de8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Input:","type":"text"}],"id":"29c44870-57b4-480b-ad8e-a5ce5145de33","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"transactions = [4500, -200, 15000, -750, 8300, -100, 22000]","type":"text"}],"id":"6ba2b87b-09ed-490a-aec2-febd5c1cc5b0","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Expected Output:","type":"text"}],"id":"7ec356e0-042b-44bb-8f34-4267b4e34ad7","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Row 2: Invalid amount -200\nRow 4: Invalid amount -750\nRow 6: Invalid amount -100\nTotal invalid records found: 3","type":"text"}],"id":"6adeb0d6-f8cf-44f5-8039-2a41ce845e94","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Concepts Tested:","type":"text"}],"id":"c5b76eda-bf2a-4aa3-9137-87e3b821df93","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"code":true},"text":"enumerate()","type":"text"},{"styles":{},"text":" to get both position and value simultaneously","type":"text"}],"id":"97335ee6-40f8-4b2e-a75d-489ca905c1db","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"code":true},"text":"start=1","type":"text"},{"styles":{},"text":" for human-readable row numbers","type":"text"}],"id":"22466653-e743-43c2-b83d-50160f2b0d4d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"code":true},"text":"for","type":"text"},{"styles":{},"text":" loop with ","type":"text"},{"styles":{"code":true},"text":"if","type":"text"},{"styles":{},"text":" condition","type":"text"}],"id":"2c1c7abf-dfd6-4522-aaac-d6a5fe910cf6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Counter variable for invalid records","type":"text"}],"id":"91d67636-d8e2-4458-ad31-7e69cf34cc5b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Starter Code:","type":"text"}],"id":"a45d06b9-d193-4583-8194-bb0d7970f5d9","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"transactions = [4500, -200, 15000, -750, 8300, -100, 22000]\n\ninvalid_count = 0\n\n# TODO: Use enumerate(transactions, start=1) to loop with row numbers\n# TODO: For each negative amount, print row number and amount\n# TODO: Increment invalid_count\n# TODO: Print total invalid records at the end","type":"text"}],"id":"2fe8c2b7-91b3-4cd1-a774-b3ed988719d8","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Expected Solution:","type":"text"}],"id":"8f6dc01e-e9d6-47e4-ab54-8d7062ec12a0","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"transactions = [4500, -200, 15000, -750, 8300, -100, 22000]\n\ninvalid_count = 0\n\nfor row, amount in enumerate(transactions, start=1):\n    if amount < 0:\n        print(f\"Row {row}: Invalid amount {amount}\")\n        invalid_count += 1\n\nprint(\"Total invalid records found:\", invalid_count)","type":"text"}],"id":"17e46c72-825e-43bb-9cd9-7e025181af80","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Interview Explanation:","type":"text"}],"id":"bccb9ec7-b4c8-45b7-9cd0-09cd8469d048","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"code":true},"text":"enumerate()","type":"text"},{"styles":{},"text":" is the right tool when you need both the position and the value of each item simultaneously — it gives you both in a single clean loop variable without needing ","type":"text"},{"styles":{"code":true},"text":"range(len(list))","type":"text"},{"styles":{},"text":". The ","type":"text"},{"styles":{"code":true},"text":"start=1","type":"text"},{"styles":{},"text":" parameter makes the row numbers human-friendly, matching how a data analyst or client would count rows in a spreadsheet or audit report. In EY-style compliance work, pinpointing the exact row of an invalid record is critical for the client''s data correction team — a vague \"some records are invalid\" message is not actionable. A common fresher mistake is using ","type":"text"},{"styles":{"code":true},"text":"range(len(transactions))","type":"text"},{"styles":{},"text":" and then doing ","type":"text"},{"styles":{"code":true},"text":"transactions[i]","type":"text"},{"styles":{},"text":" separately — ","type":"text"},{"styles":{"code":true},"text":"enumerate()","type":"text"},{"styles":{},"text":" replaces this with a cleaner, more readable pattern that is considered best practice in Python data code.","type":"text"}],"id":"00c227aa-ee3f-4db7-ac99-41a832e2f560","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"f57bdd59-b3d5-40ea-84f6-c328c2829088","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Question 9: Match Customer IDs with Recharge Packages","type":"text"}],"id":"c5a369fd-6af2-448a-8f5a-5b3e34a9ff4d","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Scenario:","type":"text"}],"id":"1e98b9b4-bfe6-4d0e-82f4-7e36ca073bd1","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"At ","type":"text"},{"styles":{"bold":true},"text":"Dialog Axiata","type":"text"},{"styles":{},"text":", two separate data feeds arrive from different upstream systems: one contains a list of customer IDs, and another contains the corresponding data packages assigned to each customer. These feeds are aligned positionally — the first customer ID corresponds to the first package, the second to the second, and so on. The pipeline must combine these two feeds to produce a unified customer-package summary report.","type":"text"}],"id":"400e8095-e285-4909-b73c-b71d2554f783","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Task:","type":"text"}],"id":"c23387c5-c0cf-4878-b991-fd48b9b80fa2","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Write a Python program using ","type":"text"},{"styles":{"code":true},"text":"zip()","type":"text"},{"styles":{},"text":" to walk both lists in sync and for each pair, print the customer ID along with their assigned package. Also count and print the total number of customer-package pairs processed.","type":"text"}],"id":"940f72b6-c96e-4552-9f47-1ae25f4f2bc0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Input:","type":"text"}],"id":"431b8f7d-bab9-4ade-afb9-948c810b6e75","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"customer_ids = [\"DLG-1001\", \"DLG-1002\", \"DLG-1003\", \"DLG-1004\"]\npackages = [\"Basic 5GB\", \"Premium 20GB\", \"Basic 5GB\", \"Unlimited\"]","type":"text"}],"id":"e0b1c5f9-2911-4d35-ad32-b54489ae2a71","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Expected Output:","type":"text"}],"id":"882cb00f-52a6-4339-b7a7-c4cce6d4f5d0","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"DLG-1001 -> Basic 5GB\nDLG-1002 -> Premium 20GB\nDLG-1003 -> Basic 5GB\nDLG-1004 -> Unlimited\nTotal pairs processed: 4","type":"text"}],"id":"9dc90f1a-1384-4887-b379-abc7ff3f90ed","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Concepts Tested:","type":"text"}],"id":"b7c4cd5a-d905-4c25-9d63-140dd8a13491","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"code":true},"text":"zip()","type":"text"},{"styles":{},"text":" to walk two parallel lists in sync","type":"text"}],"id":"d7535dc0-a2fc-422e-8d39-d85164bb9554","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"code":true},"text":"for","type":"text"},{"styles":{},"text":" loop with unpacking two variables","type":"text"}],"id":"958d89fc-550a-42ed-ab21-dfbb8504745d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Counter accumulation","type":"text"}],"id":"62f8de46-aab5-4d08-8a5d-24e61fe9ffb9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Starter Code:","type":"text"}],"id":"034a503a-5e8c-4cfe-b4ed-d47e4680d046","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"customer_ids = [\"DLG-1001\", \"DLG-1002\", \"DLG-1003\", \"DLG-1004\"]\npackages = [\"Basic 5GB\", \"Premium 20GB\", \"Basic 5GB\", \"Unlimited\"]\n\ncount = 0\n\n# TODO: Use zip(customer_ids, packages) to walk both lists together\n# TODO: Print each customer ID and package\n# TODO: Increment count\n# TODO: Print total pairs processed","type":"text"}],"id":"9ed77aac-aa34-41b9-900b-64cad5161a80","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Expected Solution:","type":"text"}],"id":"6123a5bd-9ac1-46cc-8480-b16805739d47","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"customer_ids = [\"DLG-1001\", \"DLG-1002\", \"DLG-1003\", \"DLG-1004\"]\npackages = [\"Basic 5GB\", \"Premium 20GB\", \"Basic 5GB\", \"Unlimited\"]\n\ncount = 0\n\nfor cid, package in zip(customer_ids, packages):\n    print(f\"{cid} -> {package}\")\n    count += 1\n\nprint(\"Total pairs processed:\", count)","type":"text"}],"id":"7514bb35-ed4e-4dd6-bd49-b4e71f3186fb","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Interview Explanation:","type":"text"}],"id":"c4fe5baf-73ee-4d5f-ba62-32bfa09686a1","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"code":true},"text":"zip()","type":"text"},{"styles":{},"text":" is the right tool when you have two or more parallel lists that are positionally aligned and need to be processed together as pairs — it walks both lists in perfect lockstep, giving you one item from each per iteration. This is extremely common in real data pipelines where data arrives in separate feeds that must be joined by position before processing or loading. An important ","type":"text"},{"styles":{"code":true},"text":"zip()","type":"text"},{"styles":{},"text":" behavior to know for interviews is that it stops at the shorter list and silently drops remaining items from the longer one — this can cause silent data loss if the lists are different lengths, so always verify list lengths match when using ","type":"text"},{"styles":{"code":true},"text":"zip()","type":"text"},{"styles":{},"text":" for alignment. A common fresher mistake is trying to use ","type":"text"},{"styles":{"code":true},"text":"range(len(list))","type":"text"},{"styles":{},"text":" and indexing into both lists separately — ","type":"text"},{"styles":{"code":true},"text":"zip()","type":"text"},{"styles":{},"text":" is cleaner, safer, and more Pythonic.","type":"text"}],"id":"ec451bde-ee74-4acd-b372-90e3766b43a3","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"59aaf958-f70a-4dd0-9a34-3f9498fb4e17","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Question 10: Branch-Wise Product Revenue Calculation","type":"text"}],"id":"7b75cbea-e5fe-41c6-bc93-e1d5b2cfad17","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Scenario:","type":"text"}],"id":"fe442dae-3e77-4e0f-9e68-5e5134931e10","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"At ","type":"text"},{"styles":{"bold":true},"text":"Sysco","type":"text"},{"styles":{},"text":", sales revenue data is organized by branch, and each branch has multiple product sales for the day. The data engineering team must process this nested structure to calculate and report the total revenue for each branch separately before the data is loaded into the regional reporting system.","type":"text"}],"id":"8596dae8-30a5-444d-be86-1d03f54f34c4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Task:","type":"text"}],"id":"2dcefbc2-0b3b-42c7-a630-a8c395a3eb19","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Write a Python program using a ","type":"text"},{"styles":{"bold":true},"text":"nested for loop","type":"text"},{"styles":{},"text":" to iterate over each branch and then over each product''s revenue within that branch. Calculate and print the total revenue per branch.","type":"text"}],"id":"210833e0-9d67-426e-9c71-5f300b925c49","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Input:","type":"text"}],"id":"b94b1d35-6a6d-4b9a-97b7-a8acf6a66239","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"branch_sales = {\n    \"Colombo\": [15000, 23000, 8000, 41000],\n    \"Kandy\":   [9500, 17000, 32000],\n    \"Galle\":   [6000, 11000, 5500, 22000, 14000],\n}","type":"text"}],"id":"3d100ec2-347b-47c2-9be6-dc1de2f50823","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Expected Output:","type":"text"}],"id":"f3f0973e-a588-4838-94cc-4a5e39dcb52d","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Branch: Colombo | Total Revenue: 87000\nBranch: Kandy   | Total Revenue: 58500\nBranch: Galle   | Total Revenue: 58500","type":"text"}],"id":"c8e8dc1a-e722-45ef-81fc-efe426e4af06","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Concepts Tested:","type":"text"}],"id":"27efa288-ce53-4d9b-9a9f-0c08f849d1f0","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Nested ","type":"text"},{"styles":{"code":true},"text":"for","type":"text"},{"styles":{},"text":" loop (outer: branches; inner: product sales within each branch)","type":"text"}],"id":"71b55ea8-ee0c-4d29-a443-d9f2c3b43b78","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Accumulating totals inside the inner loop, resetting per branch","type":"text"}],"id":"db24d486-78fa-400e-9502-e61efa3c28eb","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Iterating over a dictionary","type":"text"}],"id":"cee26e57-21bc-458d-ba7b-b97d36791e34","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Starter Code:","type":"text"}],"id":"9be5aab1-6947-43a6-9475-261159a468f6","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"branch_sales = {\n    \"Colombo\": [15000, 23000, 8000, 41000],\n    \"Kandy\":   [9500, 17000, 32000],\n    \"Galle\":   [6000, 11000, 5500, 22000, 14000],\n}\n\n# TODO: Outer loop — iterate over branch names and their sales lists\n# TODO: Initialize branch_total = 0 before the inner loop\n# TODO: Inner loop — iterate over each sale amount for that branch\n#   Add each amount to branch_total\n# TODO: After inner loop ends, print branch name and total revenue","type":"text"}],"id":"7d9f1f8d-09ca-4df2-a05b-205d06d5a945","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Expected Solution:","type":"text"}],"id":"1a470ab4-4eef-49b7-8fa0-4c93af5fc09c","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"branch_sales = {\n    \"Colombo\": [15000, 23000, 8000, 41000],\n    \"Kandy\":   [9500, 17000, 32000],\n    \"Galle\":   [6000, 11000, 5500, 22000, 14000],\n}\n\nfor branch, sales in branch_sales.items():\n    branch_total = 0\n    for amount in sales:\n        branch_total += amount\n    print(f\"Branch: {branch} | Total Revenue: {branch_total}\")","type":"text"}],"id":"b05ffcf2-cd10-418c-aaed-b770290699a6","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Interview Explanation:","type":"text"}],"id":"6c422784-36fc-43f5-845d-f6e5933983d6","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The nested ","type":"text"},{"styles":{"code":true},"text":"for","type":"text"},{"styles":{},"text":" loop is the natural tool here because the data has two levels of structure — branches at the outer level, and individual product sales at the inner level. The inner loop completes fully for every branch before the outer loop moves to the next branch. The critical thing to get right is resetting ","type":"text"},{"styles":{"code":true},"text":"branch_total = 0","type":"text"},{"styles":{},"text":" before the inner loop, not before the outer loop — a very common fresher mistake is initializing the total before the outer loop, which causes all branch revenues to accumulate into one number instead of being calculated per branch. In real Sysco-style data pipelines, this nested structure maps directly to how data arrives from distributed warehouse systems — branch-level grouping with item-level detail — and processing it correctly is a core ETL skill.","type":"text"}],"id":"b1cbe3d8-4e17-448b-8204-760b0c27a1fa","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"7b36d194-8d6b-4aca-a83e-92e9f284b868","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Question 11: Batch Processing with a While Loop","type":"text"}],"id":"24a16594-c9f2-481a-afc8-bceec9fa6429","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Scenario:","type":"text"}],"id":"21f02df3-d2f4-44f8-80ad-66be9a62b026","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"At ","type":"text"},{"styles":{"bold":true},"text":"Nagarro","type":"text"},{"styles":{},"text":", a data pipeline receives a batch of log events that must be processed in groups of 10. The system processes one group at a time, deducting 10 from the remaining count each cycle, until all events have been processed. The pipeline does not know in advance how many cycles it will need — it depends entirely on when the remaining count reaches zero.","type":"text"}],"id":"51138e5b-b081-4b40-a772-0c8c834d8a4d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Task:","type":"text"}],"id":"8173b292-bc7f-4669-94d3-560bfb5c7cc5","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Write a Python program using a ","type":"text"},{"styles":{"code":true},"text":"while","type":"text"},{"styles":{},"text":" loop that simulates batch processing. Start with a total of 47 events. Each cycle, process a batch of 10 (or the remaining amount if fewer than 10 are left), print the cycle number and how many events were processed, and deduct from the remaining count. Stop when all events are processed.","type":"text"}],"id":"ec42bc13-d463-4bf9-bb3e-eeb8af03a234","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Input:","type":"text"}],"id":"eaa135d7-2c19-447a-bb51-8a05cefd1fa6","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"total_events = 47\nbatch_size = 10","type":"text"}],"id":"2911c171-5539-4490-8367-db434c05cc04","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Expected Output:","type":"text"}],"id":"f6b4a833-402e-495a-a4dd-be22f766d166","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Cycle 1: Processed 10 events. Remaining: 37\nCycle 2: Processed 10 events. Remaining: 27\nCycle 3: Processed 10 events. Remaining: 17\nCycle 4: Processed 10 events. Remaining: 7\nCycle 5: Processed 7 events. Remaining: 0\nAll events processed.","type":"text"}],"id":"c76ffdb7-8807-4d54-9e7c-ce8ff59e58bd","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Concepts Tested:","type":"text"}],"id":"cc11ac4d-738e-4ed7-b76a-838811957b23","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"code":true},"text":"while","type":"text"},{"styles":{},"text":" loop (condition-driven repetition when count is not known beforehand)","type":"text"}],"id":"5798ec46-9b37-411d-9acb-677d3e028510","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Updating the condition variable inside the loop","type":"text"}],"id":"2550bf49-34e0-4715-afef-54e18a578277","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"code":true},"text":"min()","type":"text"},{"styles":{},"text":" to handle the last partial batch","type":"text"}],"id":"333a0ce0-396f-4fa3-b167-367debe9f019","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Counter for cycle number","type":"text"}],"id":"8a03b515-8d47-4444-a180-acd2f32185dd","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Starter Code:","type":"text"}],"id":"b5213c80-827f-4365-8013-5a564a9aa01f","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"total_events = 47\nbatch_size = 10\nremaining = total_events\ncycle = 1\n\n# TODO: while remaining > 0\n#   TODO: Calculate how many to process this cycle (use min())\n#   TODO: Deduct processed count from remaining\n#   TODO: Print cycle number, processed count, remaining\n#   TODO: Increment cycle\n# TODO: Print \"All events processed.\" after the loop","type":"text"}],"id":"785d8379-b8db-4913-a66a-d949cced2fc5","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Expected Solution:","type":"text"}],"id":"0b0685e5-d203-4de1-981c-908b0f389697","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"total_events = 47\nbatch_size = 10\nremaining = total_events\ncycle = 1\n\nwhile remaining > 0:\n    processed = min(batch_size, remaining)\n    remaining -= processed\n    print(f\"Cycle {cycle}: Processed {processed} events. Remaining: {remaining}\")\n    cycle += 1\n\nprint(\"All events processed.\")","type":"text"}],"id":"b1821505-9aa0-416d-af81-81be063ec915","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Interview Explanation:","type":"text"}],"id":"121cb32a-1340-41ff-9a2a-2e69bd1d3a0f","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The ","type":"text"},{"styles":{"code":true},"text":"while","type":"text"},{"styles":{},"text":" loop is the right choice here because the number of cycles is not known before the loop starts — it depends entirely on how many events remain after each batch, which only becomes known during execution. The most critical rule for ","type":"text"},{"styles":{"code":true},"text":"while","type":"text"},{"styles":{},"text":" loops is that the condition variable (","type":"text"},{"styles":{"code":true},"text":"remaining","type":"text"},{"styles":{},"text":") must be updated inside the loop — forgetting this creates an infinite loop that runs forever. The ","type":"text"},{"styles":{"code":true},"text":"min(batch_size, remaining)","type":"text"},{"styles":{},"text":" trick elegantly handles the last partial batch without a separate ","type":"text"},{"styles":{"code":true},"text":"if","type":"text"},{"styles":{},"text":" statement. In Nagarro-style data engineering contexts, this pattern is used for chunked processing of large datasets — loading data in pages, processing events in windows, or retrying failed batches — where the termination condition is data-driven rather than position-driven.","type":"text"}],"id":"3e9d3f2e-3fab-4c6f-b6ae-5e6924001af8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"cb89fc89-45a9-4dcf-8e1c-8b1f51470a8d","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Question 12: Pipeline Control Menu with while True and break","type":"text"}],"id":"a6dde42d-5d39-45bb-b5f6-91694224ff70","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Scenario:","type":"text"}],"id":"6092e4a5-d68a-486a-b1f1-501dbe98c120","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"At ","type":"text"},{"styles":{"bold":true},"text":"Nagarro","type":"text"},{"styles":{},"text":", the data engineering team builds a simple command-line pipeline control tool for internal use. The tool must keep running and accepting pipeline commands until the operator explicitly chooses to exit. The tool should not exit on its own — it must wait for the operator''s decision. This is a classic \"keep the pipeline alive until instructed to stop\" pattern.","type":"text"}],"id":"f43b6f68-39a0-4360-a575-19cf69ee8540","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Task:","type":"text"}],"id":"bf36257b-98be-4d65-b46f-df28e6473242","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Write a Python program using ","type":"text"},{"styles":{"code":true},"text":"while True","type":"text"},{"styles":{},"text":" that presents a menu of pipeline actions. Based on the operator''s choice (simulated as a variable, not real ","type":"text"},{"styles":{"code":true},"text":"input()","type":"text"},{"styles":{},"text":"), execute the appropriate action. When the exit command is chosen, print a goodbye message and ","type":"text"},{"styles":{"bold":true},"text":"break","type":"text"},{"styles":{},"text":" out of the loop. For an unknown command, print an error message and continue the loop.","type":"text"}],"id":"123171a6-a1c7-498d-a32a-e6fc61a33d92","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Note for interview:","type":"text"},{"styles":{},"text":" In this question, to avoid ","type":"text"},{"styles":{"code":true},"text":"input()","type":"text"},{"styles":{},"text":", simulate a list of commands the operator enters one by one.","type":"text"}],"id":"b6d28f90-aff9-432a-a068-98e91416afe8","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{},"text":"Input:","type":"text"}],"id":"c4a219e8-d7d9-4a79-9290-42f028fa821f","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# Simulated operator commands entered one by one\ncommands = [\"start\", \"status\", \"unknown_cmd\", \"stop\"]","type":"text"}],"id":"88ddf194-8fae-4d1a-bcf7-d47f3827e8f9","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Expected Output:","type":"text"}],"id":"017d67ab-df8f-4e8f-b109-716080e3cb81","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Pipeline started.\nPipeline status: RUNNING\nUnknown command. Please try again.\nPipeline stopped. Goodbye.","type":"text"}],"id":"3c2eecb8-94b8-4e45-b062-623c1e534738","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Concepts Tested:","type":"text"}],"id":"54c61d5e-71f7-4fdb-a651-8c964c652cff","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"code":true},"text":"while True","type":"text"},{"styles":{},"text":" with ","type":"text"},{"styles":{"code":true},"text":"break","type":"text"},{"styles":{},"text":" to exit when instructed","type":"text"}],"id":"3db21787-da9f-48ad-8ec2-7573a7e2676d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"code":true},"text":"if/elif/else","type":"text"},{"styles":{},"text":" inside the loop for menu routing","type":"text"}],"id":"8099f3d9-7f48-4da2-88e3-b1c89ddce1e1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Simulating an event-driven control loop without ","type":"text"},{"styles":{"code":true},"text":"input()","type":"text"}],"id":"72e1a715-dd8b-465e-9643-442d088db703","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Starter Code:","type":"text"}],"id":"ea077ff0-b1ad-46af-b4b3-b79f4af6d9c8","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"commands = [\"start\", \"status\", \"unknown_cmd\", \"stop\"]\nindex = 0\n\n# TODO: while True loop\n#   TODO: Get current command from commands list using index\n#   TODO: Increment index\n#   TODO: if command is \"start\" -> print \"Pipeline started.\"\n#   TODO: elif command is \"status\" -> print \"Pipeline status: RUNNING\"\n#   TODO: elif command is \"stop\" -> print goodbye message and break\n#   TODO: else -> print \"Unknown command. Please try again.\"","type":"text"}],"id":"7dd4e0c1-b8f1-4daf-a5b7-393b8edeb009","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Expected Solution:","type":"text"}],"id":"83c05434-a91b-434c-afdb-d8fe7ef2ff2b","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"commands = [\"start\", \"status\", \"unknown_cmd\", \"stop\"]\nindex = 0\n\nwhile True:\n    command = commands[index]\n    index += 1\n\n    if command == \"start\":\n        print(\"Pipeline started.\")\n    elif command == \"status\":\n        print(\"Pipeline status: RUNNING\")\n    elif command == \"stop\":\n        print(\"Pipeline stopped. Goodbye.\")\n        break\n    else:\n        print(\"Unknown command. Please try again.\")","type":"text"}],"id":"f8588cd8-ec92-41a0-86a9-458259bd7353","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Interview Explanation:","type":"text"}],"id":"686ec9d2-bbc6-4d27-bdf0-260755dca325","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"code":true},"text":"while True","type":"text"},{"styles":{},"text":" is used here because the loop has no natural termination condition — it should keep running indefinitely until an explicit exit command arrives. The ","type":"text"},{"styles":{"code":true},"text":"break","type":"text"},{"styles":{},"text":" is the only exit point, making it a controlled and intentional stop. This is the \"room that never closes on its own\" pattern from your notes — only the fire alarm (","type":"text"},{"styles":{"code":true},"text":"break","type":"text"},{"styles":{},"text":") can shut it down. In real Data Engineering environments at Nagarro, pipeline daemons, monitoring agents, and queue consumers are often built this way — they run in an infinite loop, processing incoming events until a shutdown signal is received. The interview mistake to avoid is writing a regular ","type":"text"},{"styles":{"code":true},"text":"while","type":"text"},{"styles":{},"text":" condition that might accidentally become true or false too early — ","type":"text"},{"styles":{"code":true},"text":"while True","type":"text"},{"styles":{},"text":" with a deliberate ","type":"text"},{"styles":{"code":true},"text":"break","type":"text"},{"styles":{},"text":" is cleaner and more explicit for this pattern.","type":"text"}],"id":"b69db895-1d6a-4fcd-8906-99bf2cb7a3ad","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"7c3c7e37-7869-4eec-a6d4-3738d34d6623","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Question 13: Acknowledge System Log Types with pass","type":"text"}],"id":"ee1dd526-0ac3-4fbb-8e14-11e3273c5b4e","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Scenario:","type":"text"}],"id":"2c2a7bdb-7261-43a0-9f36-cd8b36d8adba","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"At ","type":"text"},{"styles":{"bold":true},"text":"Nagarro","type":"text"},{"styles":{},"text":", the pipeline monitoring system ingests a stream of system log events. The current sprint only requires processing ","type":"text"},{"styles":{"code":true},"text":"\"ERROR\"","type":"text"},{"styles":{},"text":" and ","type":"text"},{"styles":{"code":true},"text":"\"WARNING\"","type":"text"},{"styles":{},"text":" events. ","type":"text"},{"styles":{"code":true},"text":"\"INFO\"","type":"text"},{"styles":{},"text":" events are acknowledged as part of the log standard but require no action in this sprint — they are placeholders for a future logging feature that has not yet been built. Using ","type":"text"},{"styles":{"code":true},"text":"pass","type":"text"},{"styles":{},"text":" explicitly signals to the team that ","type":"text"},{"styles":{"code":true},"text":"\"INFO\"","type":"text"},{"styles":{},"text":" events are intentionally not processed, not accidentally forgotten.","type":"text"}],"id":"c452ed66-8e49-40e3-83d8-194353393c60","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Task:","type":"text"}],"id":"7c81ac31-12e3-4301-8f82-8e09aa7dc751","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Write a Python program that loops through the log events. For ","type":"text"},{"styles":{"code":true},"text":"\"ERROR\"","type":"text"},{"styles":{},"text":" events, print a critical alert. For ","type":"text"},{"styles":{"code":true},"text":"\"WARNING\"","type":"text"},{"styles":{},"text":" events, print a warning notice. For ","type":"text"},{"styles":{"code":true},"text":"\"INFO\"","type":"text"},{"styles":{},"text":" events, use ","type":"text"},{"styles":{"code":true},"text":"pass","type":"text"},{"styles":{},"text":" — acknowledge the record but take no action. Print a count of how many ","type":"text"},{"styles":{"code":true},"text":"\"ERROR\"","type":"text"},{"styles":{},"text":" events were found at the end.","type":"text"}],"id":"6f0b43da-5bfc-46ef-8f07-899f4a1263fd","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Input:","type":"text"}],"id":"9bd01d3c-1411-4aa0-ba03-0dba5775b67f","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"log_events = [\n    {\"type\": \"INFO\", \"message\": \"Pipeline started\"},\n    {\"type\": \"WARNING\", \"message\": \"High memory usage\"},\n    {\"type\": \"ERROR\", \"message\": \"Database connection failed\"},\n    {\"type\": \"INFO\", \"message\": \"Batch 1 complete\"},\n    {\"type\": \"ERROR\", \"message\": \"Null value in required field\"},\n    {\"type\": \"WARNING\", \"message\": \"Slow query detected\"},\n]","type":"text"}],"id":"6b1d6b7f-ff05-46f1-815c-e9713d0cc8c2","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Expected Output:","type":"text"}],"id":"d8254ed7-2f2c-47a5-a261-bb0894ded385","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"[WARNING] High memory usage\n[ERROR] CRITICAL: Database connection failed\n[ERROR] CRITICAL: Null value in required field\n[WARNING] Slow query detected\nTotal ERROR events: 2","type":"text"}],"id":"0fee98a7-3c3c-487f-9a5d-b66bde08fede","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Concepts Tested:","type":"text"}],"id":"df9534ec-8ba5-43c9-b26b-5a282e6d9fc2","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"code":true},"text":"pass","type":"text"},{"styles":{},"text":" as a deliberate placeholder (not ","type":"text"},{"styles":{"code":true},"text":"continue","type":"text"},{"styles":{},"text":")","type":"text"}],"id":"2d71cc7d-38a9-457e-88ca-cf702b877507","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Understanding that ","type":"text"},{"styles":{"code":true},"text":"pass","type":"text"},{"styles":{},"text":" does not skip — it falls through normally","type":"text"}],"id":"2976687b-0158-4379-9424-618a56a19bae","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Difference between ","type":"text"},{"styles":{"code":true},"text":"pass","type":"text"},{"styles":{},"text":" (do nothing, fall through) and ","type":"text"},{"styles":{"code":true},"text":"continue","type":"text"},{"styles":{},"text":" (skip this iteration)","type":"text"}],"id":"41700b1d-0678-40a5-a5e2-d02c655e7400","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"code":true},"text":"for","type":"text"},{"styles":{},"text":" loop with ","type":"text"},{"styles":{"code":true},"text":"if/elif","type":"text"},{"styles":{},"text":" structure","type":"text"}],"id":"dd4ebef1-a1ae-4937-867d-41b9da041be0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Starter Code:","type":"text"}],"id":"6bfd4b0a-0503-4988-86e7-b4d04d30ab55","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"log_events = [\n    {\"type\": \"INFO\", \"message\": \"Pipeline started\"},\n    {\"type\": \"WARNING\", \"message\": \"High memory usage\"},\n    {\"type\": \"ERROR\", \"message\": \"Database connection failed\"},\n    {\"type\": \"INFO\", \"message\": \"Batch 1 complete\"},\n    {\"type\": \"ERROR\", \"message\": \"Null value in required field\"},\n    {\"type\": \"WARNING\", \"message\": \"Slow query detected\"},\n]\n\nerror_count = 0\n\nfor event in log_events:\n    log_type = event[\"type\"]\n    message = event[\"message\"]\n\n    # TODO: if log_type is \"INFO\" -> use pass (acknowledge, do nothing)\n    # TODO: elif log_type is \"WARNING\" -> print warning notice\n    # TODO: elif log_type is \"ERROR\" -> print critical alert, increment error_count\n\n# TODO: Print total ERROR events","type":"text"}],"id":"61003dfc-3c6c-49d4-aa79-074a97b7015d","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Expected Solution:","type":"text"}],"id":"fb8314d5-099b-4b24-b846-2fec28683bc2","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"log_events = [\n    {\"type\": \"INFO\", \"message\": \"Pipeline started\"},\n    {\"type\": \"WARNING\", \"message\": \"High memory usage\"},\n    {\"type\": \"ERROR\", \"message\": \"Database connection failed\"},\n    {\"type\": \"INFO\", \"message\": \"Batch 1 complete\"},\n    {\"type\": \"ERROR\", \"message\": \"Null value in required field\"},\n    {\"type\": \"WARNING\", \"message\": \"Slow query detected\"},\n]\n\nerror_count = 0\n\nfor event in log_events:\n    log_type = event[\"type\"]\n    message = event[\"message\"]\n\n    if log_type == \"INFO\":\n        pass\n    elif log_type == \"WARNING\":\n        print(f\"[WARNING] {message}\")\n    elif log_type == \"ERROR\":\n        print(f\"[ERROR] CRITICAL: {message}\")\n        error_count += 1\n\nprint(\"Total ERROR events:\", error_count)","type":"text"}],"id":"265d590a-49ff-4abc-9483-55f75fbafc91","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Interview Explanation:","type":"text"}],"id":"7caf75af-edb4-4a79-b6e2-493c79d7b92e","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"code":true},"text":"pass","type":"text"},{"styles":{},"text":" is used here to explicitly communicate that ","type":"text"},{"styles":{"code":true},"text":"\"INFO\"","type":"text"},{"styles":{},"text":" events are intentionally not processed — the code acknowledges their existence without taking any action and falls through to the next iteration naturally. This is critically different from ","type":"text"},{"styles":{"code":true},"text":"continue","type":"text"},{"styles":{},"text":": if ","type":"text"},{"styles":{"code":true},"text":"continue","type":"text"},{"styles":{},"text":" were used instead of ","type":"text"},{"styles":{"code":true},"text":"pass","type":"text"},{"styles":{},"text":", it would skip the rest of the ","type":"text"},{"styles":{"code":true},"text":"if/elif","type":"text"},{"styles":{},"text":" block and immediately move to the next event — but with ","type":"text"},{"styles":{"code":true},"text":"pass","type":"text"},{"styles":{},"text":" inside an ","type":"text"},{"styles":{"code":true},"text":"if/elif","type":"text"},{"styles":{},"text":" chain, the else branches already won''t run for ","type":"text"},{"styles":{"code":true},"text":"\"INFO\"","type":"text"},{"styles":{},"text":" anyway, so here ","type":"text"},{"styles":{"code":true},"text":"pass","type":"text"},{"styles":{},"text":" serves primarily as a readability and intent signal. The real value of ","type":"text"},{"styles":{"code":true},"text":"pass","type":"text"},{"styles":{},"text":" is as a development placeholder — it prevents ","type":"text"},{"styles":{"code":true},"text":"SyntaxError","type":"text"},{"styles":{},"text":" when a branch body is left empty, and it signals to other engineers that the case is acknowledged but deliberately unimplemented. In real Nagarro-style pipeline development, using ","type":"text"},{"styles":{"code":true},"text":"pass","type":"text"},{"styles":{},"text":" with a comment is far better than leaving a blank branch or silently skipping a record type.","type":"text"}],"id":"1d676006-65fa-4949-9f5b-2a6c3fe3799a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"4a7d5222-2f68-4682-91a8-94727420d745","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Question 14: Search for a Customer ID Across All Records","type":"text"}],"id":"3dd642fb-b68e-4cf4-8d88-c5aa7c25a659","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Scenario:","type":"text"}],"id":"b26db862-86fa-49e0-90fb-7ef94ca42c6a","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"At ","type":"text"},{"styles":{"bold":true},"text":"Dialog Axiata","type":"text"},{"styles":{},"text":", the support team escalates a specific customer complaint. To investigate, the data engineering pipeline must search all active customer records to check whether the flagged customer ID exists in the system. If the customer is found, the pipeline should report the match and stop searching. If the customer ID does not exist anywhere in the list after a full search, the pipeline must report that the record was not found — this distinction is important for the support team''s next steps.","type":"text"}],"id":"ce0aa354-dfdf-4d16-8861-46aaebe1697e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Task:","type":"text"}],"id":"d336740e-4beb-428f-83f5-be03d572a997","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Write a Python program using a ","type":"text"},{"styles":{"code":true},"text":"for/else","type":"text"},{"styles":{},"text":" structure to search for ","type":"text"},{"styles":{"code":true},"text":"target_id","type":"text"},{"styles":{},"text":" in the customer records list. If found, print a found message and stop. If not found after checking all records, print a not-found message using the ","type":"text"},{"styles":{"code":true},"text":"else","type":"text"},{"styles":{},"text":" block.","type":"text"}],"id":"5d1d527d-4933-48e3-a143-fec3a28c57a2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Input:","type":"text"}],"id":"b3e44eaf-2238-4021-9a49-232d75012ac1","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"customers = [\n    {\"id\": \"DLG-1001\", \"name\": \"Kasun Perera\"},\n    {\"id\": \"DLG-1002\", \"name\": \"Nimali Silva\"},\n    {\"id\": \"DLG-1003\", \"name\": \"Ruwan Fernando\"},\n    {\"id\": \"DLG-1004\", \"name\": \"Ayesha Bandara\"},\n]\n\ntarget_id = \"DLG-1003\"","type":"text"}],"id":"0c9f7383-e4df-4ee2-8080-def0a6d67e7f","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Expected Output (when target found):","type":"text"}],"id":"e62277d5-587a-4fe2-9a70-86868bde7391","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Customer found: DLG-1003 | Ruwan Fernando","type":"text"}],"id":"19c7d3d6-da15-4ede-922a-259ad3eba979","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Expected Output (when target not found — e.g. target_id = \"DLG-9999\"):","type":"text"}],"id":"61afb3db-69b3-4873-a7d7-9b45b11c4404","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Customer DLG-9999 not found in the system.","type":"text"}],"id":"51569382-1971-45c2-a85b-39921930a23c","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Concepts Tested:","type":"text"}],"id":"afdbe252-0430-4f5f-8ea3-60304eea073e","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"code":true},"text":"for/else","type":"text"},{"styles":{},"text":" pattern for search problems","type":"text"}],"id":"99319364-996a-4f3b-b359-a54201ee0c7c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"code":true},"text":"break","type":"text"},{"styles":{},"text":" when the match is found","type":"text"}],"id":"e4c5dbbf-f63f-4bcf-8296-9fd31839110d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"code":true},"text":"else","type":"text"},{"styles":{},"text":" block runs only if no ","type":"text"},{"styles":{"code":true},"text":"break","type":"text"},{"styles":{},"text":" occurred","type":"text"}],"id":"24fdbc78-f3b4-47d2-b350-18be9759d6a6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Eliminating the need for a flag variable","type":"text"}],"id":"83c474af-e990-497e-af38-a6cffa097fb8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Starter Code:","type":"text"}],"id":"3e514bad-d668-4432-9d45-a3b8cc127c5d","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"customers = [\n    {\"id\": \"DLG-1001\", \"name\": \"Kasun Perera\"},\n    {\"id\": \"DLG-1002\", \"name\": \"Nimali Silva\"},\n    {\"id\": \"DLG-1003\", \"name\": \"Ruwan Fernando\"},\n    {\"id\": \"DLG-1004\", \"name\": \"Ayesha Bandara\"},\n]\n\ntarget_id = \"DLG-1003\"\n\n# TODO: for loop through customers\n#   TODO: if customer id matches target_id\n#     Print found message\n#     break\n# TODO: else (attached to the for loop, not the if)\n#   Print not found message","type":"text"}],"id":"756b2d1f-8ccf-4f73-841e-67562af19c02","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Expected Solution:","type":"text"}],"id":"c98b95f5-093d-4354-a4cb-ef32e01e9ce8","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"customers = [\n    {\"id\": \"DLG-1001\", \"name\": \"Kasun Perera\"},\n    {\"id\": \"DLG-1002\", \"name\": \"Nimali Silva\"},\n    {\"id\": \"DLG-1003\", \"name\": \"Ruwan Fernando\"},\n    {\"id\": \"DLG-1004\", \"name\": \"Ayesha Bandara\"},\n]\n\ntarget_id = \"DLG-1003\"\n\nfor customer in customers:\n    if customer[\"id\"] == target_id:\n        print(f\"Customer found: {customer[''id'']} | {customer[''name'']}\")\n        break\nelse:\n    print(f\"Customer {target_id} not found in the system.\")","type":"text"}],"id":"f1442755-792c-47aa-8880-f73c0ba1f28d","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Interview Explanation:","type":"text"}],"id":"634a76a6-8e85-4bb2-a9f1-adaf93b9a6de","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The ","type":"text"},{"styles":{"code":true},"text":"for/else","type":"text"},{"styles":{},"text":" pattern elegantly solves the \"search or report not found\" problem without needing a ","type":"text"},{"styles":{"code":true},"text":"found = False","type":"text"},{"styles":{},"text":" flag variable. The ","type":"text"},{"styles":{"code":true},"text":"else","type":"text"},{"styles":{},"text":" block is attached to the ","type":"text"},{"styles":{"code":true},"text":"for","type":"text"},{"styles":{},"text":" loop — not to any ","type":"text"},{"styles":{"code":true},"text":"if","type":"text"},{"styles":{},"text":" — and it runs only if the loop completed without hitting a ","type":"text"},{"styles":{"code":true},"text":"break","type":"text"},{"styles":{},"text":". The moment a ","type":"text"},{"styles":{"code":true},"text":"break","type":"text"},{"styles":{},"text":" fires (customer found), the ","type":"text"},{"styles":{"code":true},"text":"else","type":"text"},{"styles":{},"text":" is permanently skipped. Without ","type":"text"},{"styles":{"code":true},"text":"for/else","type":"text"},{"styles":{},"text":", you would need to set a flag before the loop, update it inside, and check it after — which is more code and less clean. The most common interview mistake is misunderstanding which ","type":"text"},{"styles":{"code":true},"text":"else","type":"text"},{"styles":{},"text":" belongs to the ","type":"text"},{"styles":{"code":true},"text":"for","type":"text"},{"styles":{},"text":" loop — indentation is critical here. In Dialog-style customer data pipelines, this search-or-report pattern is used constantly for ID lookups, deduplication checks, and existence validation before any update or enrichment operation is applied.","type":"text"}],"id":"ee42d0d5-e812-4ad4-9f20-92d48f560172","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"0af51094-397a-4ffa-b658-1973c4120c06","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Question 15: Mini ETL Pipeline — Filter, Classify, and Summarise Sales Orders","type":"text"}],"id":"c2fccae7-620b-4a15-8976-f18e2d6263d3","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Scenario:","type":"text"}],"id":"6060a1d5-b884-4259-ace7-2629a57ca95c","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"At ","type":"text"},{"styles":{"bold":true},"text":"Sysco","type":"text"},{"styles":{},"text":", end-of-day order processing runs a mini-ETL pipeline over the day''s sales orders before they are pushed to the reporting layer. The pipeline must:","type":"text"}],"id":"f516b097-feb2-4fc1-add1-8c2cc177ddaf","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Skip","type":"text"},{"styles":{},"text":" any order with a missing or zero amount (invalid data)","type":"text"}],"id":"25967398-53bb-462c-8352-4c15f6bd9266","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Classify","type":"text"},{"styles":{},"text":" each valid order as ","type":"text"},{"styles":{"code":true},"text":"\"BULK\"","type":"text"},{"styles":{},"text":" if amount >= 30000, or ","type":"text"},{"styles":{"code":true},"text":"\"REGULAR\"","type":"text"},{"styles":{},"text":" otherwise","type":"text"}],"id":"336f65b4-a1fb-49f1-a6b7-f8d6ca311882","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Count","type":"text"},{"styles":{},"text":" valid orders and accumulate a total sales value","type":"text"}],"id":"cd7127c3-3c85-4921-a2c6-9cc1efcdc7fa","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Count","type":"text"},{"styles":{},"text":" how many orders were classified as ","type":"text"},{"styles":{"code":true},"text":"\"BULK\"","type":"text"}],"id":"0391a70c-74b6-4971-9e6b-0cbf62c364e7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Print","type":"text"},{"styles":{},"text":" a summary report at the end","type":"text"}],"id":"93ce71ef-570d-46cf-9595-d47c038ac221","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"This is a realistic mini-pipeline that combines filtering, classification, counting, and reporting in one flow.","type":"text"}],"id":"cadaac50-c79b-451d-a21c-64ec47a5eeed","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Task:","type":"text"}],"id":"67984015-9403-47e1-90cd-1891d9759464","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Write a complete Python program that processes the orders list through all five pipeline steps described above and prints the final summary.","type":"text"}],"id":"e4cbbbaf-834d-4b13-a49a-a35c8b88e08f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Input:","type":"text"}],"id":"2d1896f8-44bb-429b-bd5b-2280b88f8a00","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"orders = [\n    {\"order_id\": \"SO-001\", \"amount\": 45000},\n    {\"order_id\": \"SO-002\", \"amount\": 0},\n    {\"order_id\": \"SO-003\", \"amount\": 12000},\n    {\"order_id\": \"SO-004\", \"amount\": None},\n    {\"order_id\": \"SO-005\", \"amount\": 78000},\n    {\"order_id\": \"SO-006\", \"amount\": 30000},\n    {\"order_id\": \"SO-007\", \"amount\": 5500},\n    {\"order_id\": \"SO-008\", \"amount\": 0},\n]","type":"text"}],"id":"5aa3f56d-016d-485f-beba-fffc75b0f2c9","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Expected Output:","type":"text"}],"id":"61f3425a-add0-40d7-a3af-3467ade6a438","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"[SO-001] BULK   | Amount: 45000\n[SO-002] Skipped: invalid amount\n[SO-003] REGULAR | Amount: 12000\n[SO-004] Skipped: invalid amount\n[SO-005] BULK   | Amount: 78000\n[SO-006] BULK   | Amount: 30000\n[SO-007] REGULAR | Amount: 5500\n\n--- Order Processing Summary ---\nTotal orders received : 8\nValid orders processed: 5\nInvalid orders skipped: 3\nBulk orders           : 3\nRegular orders        : 2\nTotal sales value     : 170500","type":"text"}],"id":"47269a00-cd4a-47d6-97c8-593a8ef298a0","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Concepts Tested:","type":"text"}],"id":"4f3e7ab6-4338-470b-aa0e-27d5dfeea996","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"code":true},"text":"for","type":"text"},{"styles":{},"text":" loop to process every record","type":"text"}],"id":"f41ee903-c14c-4ab0-805c-6c831446eff2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"code":true},"text":"continue","type":"text"},{"styles":{},"text":" to skip invalid records","type":"text"}],"id":"0a503aaa-1dde-4f82-acb1-0e400ad1e056","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"code":true},"text":"if/else","type":"text"},{"styles":{},"text":" (or ternary) for classification","type":"text"}],"id":"92bf5ead-82fd-4eec-8168-dedc2f82362c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Multiple counters and a running total","type":"text"}],"id":"d656ba0e-92cb-463f-9df7-e7752e1ba63f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Clean summary reporting after the loop","type":"text"}],"id":"b52ec5d9-7f22-43a3-80c0-507a97fa0210","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Starter Code:","type":"text"}],"id":"e53a846e-158a-4c26-9070-935b5e3b56eb","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"orders = [\n    {\"order_id\": \"SO-001\", \"amount\": 45000},\n    {\"order_id\": \"SO-002\", \"amount\": 0},\n    {\"order_id\": \"SO-003\", \"amount\": 12000},\n    {\"order_id\": \"SO-004\", \"amount\": None},\n    {\"order_id\": \"SO-005\", \"amount\": 78000},\n    {\"order_id\": \"SO-006\", \"amount\": 30000},\n    {\"order_id\": \"SO-007\", \"amount\": 5500},\n    {\"order_id\": \"SO-008\", \"amount\": 0},\n]\n\n# TODO: Initialize counters — total_received, valid_count, invalid_count,\n#       bulk_count, regular_count, total_sales\n\ntotal_received = len(orders)\nvalid_count = 0\ninvalid_count = 0\nbulk_count = 0\nregular_count = 0\ntotal_sales = 0\n\nfor order in orders:\n    oid = order[\"order_id\"]\n    amount = order[\"amount\"]\n\n    # TODO: Step 1 — if amount is None or 0, print skip message, increment invalid_count, continue\n\n    # TODO: Step 2 — classify as BULK or REGULAR using if/else or ternary\n\n    # TODO: Step 3 — increment valid_count, add to total_sales\n    # TODO: Step 4 — increment bulk_count or regular_count based on classification\n\n    # TODO: Step 5 — print order line\n\n# TODO: Print summary report","type":"text"}],"id":"910636ec-8985-4334-b068-bead8d33ca74","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Expected Solution:","type":"text"}],"id":"cf47f76d-505c-4762-9495-2cc8aeda390c","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"orders = [\n    {\"order_id\": \"SO-001\", \"amount\": 45000},\n    {\"order_id\": \"SO-002\", \"amount\": 0},\n    {\"order_id\": \"SO-003\", \"amount\": 12000},\n    {\"order_id\": \"SO-004\", \"amount\": None},\n    {\"order_id\": \"SO-005\", \"amount\": 78000},\n    {\"order_id\": \"SO-006\", \"amount\": 30000},\n    {\"order_id\": \"SO-007\", \"amount\": 5500},\n    {\"order_id\": \"SO-008\", \"amount\": 0},\n]\n\ntotal_received = len(orders)\nvalid_count = 0\ninvalid_count = 0\nbulk_count = 0\nregular_count = 0\ntotal_sales = 0\n\nfor order in orders:\n    oid = order[\"order_id\"]\n    amount = order[\"amount\"]\n\n    if not amount:\n        print(f\"[{oid}] Skipped: invalid amount\")\n        invalid_count += 1\n        continue\n\n    category = \"BULK\" if amount >= 30000 else \"REGULAR\"\n\n    valid_count += 1\n    total_sales += amount\n\n    if category == \"BULK\":\n        bulk_count += 1\n    else:\n        regular_count += 1\n\n    print(f\"[{oid}] {category:<7} | Amount: {amount}\")\n\nprint()\nprint(\"--- Order Processing Summary ---\")\nprint(f\"Total orders received : {total_received}\")\nprint(f\"Valid orders processed: {valid_count}\")\nprint(f\"Invalid orders skipped: {invalid_count}\")\nprint(f\"Bulk orders           : {bulk_count}\")\nprint(f\"Regular orders        : {regular_count}\")\nprint(f\"Total sales value     : {total_sales}\")","type":"text"}],"id":"6b057f95-2b1e-4356-813a-2093e214c2fd","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Interview Explanation:","type":"text"}],"id":"4d9163ef-f188-4f06-838f-2dbd315261d6","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"This question is a mini version of a real ETL pipeline — it combines the four core data engineering operations in a single flow: ","type":"text"},{"styles":{"bold":true},"text":"filter","type":"text"},{"styles":{},"text":" (skip invalid records with ","type":"text"},{"styles":{"code":true},"text":"continue","type":"text"},{"styles":{},"text":"), ","type":"text"},{"styles":{"bold":true},"text":"transform/classify","type":"text"},{"styles":{},"text":" (ternary expression for category), ","type":"text"},{"styles":{"bold":true},"text":"aggregate","type":"text"},{"styles":{},"text":" (counters and running total), and ","type":"text"},{"styles":{"bold":true},"text":"report","type":"text"},{"styles":{},"text":" (summary output). Each concept used is simple on its own, but combining them cleanly without messy nesting is the actual skill being tested. The ","type":"text"},{"styles":{"code":true},"text":"continue","type":"text"},{"styles":{},"text":" at the top of the loop creates a \"guard clause\" pattern — bad records are ejected early, and all code below only runs for valid records, keeping the logic flat and readable. In a Sysco-style pipeline, this pattern runs thousands of times per day across millions of records before data lands in a reporting database. The interview mistake to avoid is writing deeply nested ","type":"text"},{"styles":{"code":true},"text":"if","type":"text"},{"styles":{},"text":" blocks instead of using ","type":"text"},{"styles":{"code":true},"text":"continue","type":"text"},{"styles":{},"text":" to guard early — deep nesting makes code hard to read and debug in production.","type":"text"}],"id":"1f5f9499-ba86-4f5e-aba7-19aa6b75bca1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"e3c3c756-c12e-4b4e-939a-077fa03565e1","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Interview Revision Checklist","type":"text"}],"id":"57d77c97-2e6a-4cfb-9f7b-efaa74737059","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Use this checklist to review before attempting any of the 15 questions above:","type":"text"}],"id":"7aff6fca-0102-4b49-a823-a86263e1652c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"1e567d7b-d2fd-4a59-be37-2aa43acefd73","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"✅ Choosing ","type":"text"},{"styles":{"code":true},"text":"if/elif/else","type":"text"},{"styles":{},"text":" vs Separate ","type":"text"},{"styles":{"code":true},"text":"if","type":"text"}],"id":"0bb61161-330f-4b82-8332-d3d92bf984c9","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Use ","type":"text"},{"styles":{"code":true},"text":"if/elif/else","type":"text"},{"styles":{},"text":" when choices are ","type":"text"},{"styles":{"bold":true},"text":"mutually exclusive","type":"text"},{"styles":{},"text":" — only one outcome should ever run","type":"text"}],"id":"175375de-db78-4e9a-a2c3-2f311685c6b5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Use separate ","type":"text"},{"styles":{"code":true},"text":"if","type":"text"},{"styles":{},"text":" statements when each check is ","type":"text"},{"styles":{"bold":true},"text":"independent","type":"text"},{"styles":{},"text":" — multiple can be true at once","type":"text"}],"id":"e31c4817-6aa3-42e8-9c9d-f7714c157db0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Confusing these two is one of the most common and most costly data quality bugs","type":"text"}],"id":"b8a7b77e-89f0-418e-a819-bd697724c756","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"✅ Using Nested ","type":"text"},{"styles":{"code":true},"text":"if","type":"text"},{"styles":{},"text":" Without Making Code Messy","type":"text"}],"id":"8922a394-7dbc-4c53-b2ec-9d1cea4f5d78","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Only nest when one condition is a true ","type":"text"},{"styles":{"bold":true},"text":"prerequisite","type":"text"},{"styles":{},"text":" for another","type":"text"}],"id":"055ecda5-790f-4c37-9d38-7217e180f4bf","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Keep nesting to two levels maximum for readability","type":"text"}],"id":"d67efbec-b7ab-4db3-bf9c-c4bbf2bb9b16","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"If you find yourself nesting deeply, consider ","type":"text"},{"styles":{"code":true},"text":"continue","type":"text"},{"styles":{},"text":" guard clauses instead","type":"text"}],"id":"b383d411-49c4-4db9-9274-f7b1c32fd5b4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"✅ Using ","type":"text"},{"styles":{"code":true},"text":"for","type":"text"},{"styles":{},"text":" Loops for Record Processing","type":"text"}],"id":"1e61c9fc-b009-4777-8df7-154a5c291892","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"code":true},"text":"for","type":"text"},{"styles":{},"text":" loop is the right choice when you know the collection of records before the loop starts","type":"text"}],"id":"07153a8d-ad8b-4050-91b9-7c3b7c53f0ab","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Remember: the loop variable is replaced at each step — no memory between iterations","type":"text"}],"id":"a78e3002-42fc-4cec-a50a-4d3b6fc0d72f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Use ","type":"text"},{"styles":{"code":true},"text":"for item in list","type":"text"},{"styles":{},"text":" for items, ","type":"text"},{"styles":{"code":true},"text":"for key, value in dict.items()","type":"text"},{"styles":{},"text":" for dictionaries","type":"text"}],"id":"cc140788-466f-4db1-8359-e364e49a29ab","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"✅ Using ","type":"text"},{"styles":{"code":true},"text":"continue","type":"text"},{"styles":{},"text":" to Skip Bad Records","type":"text"}],"id":"8e115980-2479-457f-acc4-21f544731131","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"code":true},"text":"continue","type":"text"},{"styles":{},"text":" skips the ","type":"text"},{"styles":{"bold":true},"text":"rest of the loop body for the current item only","type":"text"},{"styles":{},"text":" and moves to the next","type":"text"}],"id":"1e3f5c2c-19bb-400a-b5ef-318109dcd9ba","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"The loop keeps running for all remaining items","type":"text"}],"id":"3d392cdf-4f8f-4fad-a0dc-8a53106f1ef2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Common use: filtering out ","type":"text"},{"styles":{"code":true},"text":"None","type":"text"},{"styles":{},"text":", zero, missing, or cancelled records before processing","type":"text"}],"id":"70eeee48-c294-4a6c-9d81-c13b3c88b0c9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"✅ Using ","type":"text"},{"styles":{"code":true},"text":"break","type":"text"},{"styles":{},"text":" to Stop Early","type":"text"}],"id":"3be20109-cb1d-49cb-b7dc-6da3eec08c8c","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"code":true},"text":"break","type":"text"},{"styles":{},"text":" ","type":"text"},{"styles":{"bold":true},"text":"exits the entire loop immediately","type":"text"},{"styles":{},"text":" — remaining items are never visited","type":"text"}],"id":"8e46dc88-4726-495b-a38b-e39133d931b8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Use it when finding one critical condition makes processing the rest pointless","type":"text"}],"id":"2476174c-0ac1-42fe-99e6-2f94039e6cdb","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"In nested loops, ","type":"text"},{"styles":{"code":true},"text":"break","type":"text"},{"styles":{},"text":" only exits the ","type":"text"},{"styles":{"bold":true},"text":"innermost","type":"text"},{"styles":{},"text":" loop — not all loops above it","type":"text"}],"id":"7adc73a7-67b0-474e-9f28-278352c9080a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"✅ Using ","type":"text"},{"styles":{"code":true},"text":"enumerate()","type":"text"},{"styles":{},"text":" for Row Numbers","type":"text"}],"id":"91c8bb49-25fb-4b52-affb-52d8ca249024","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"code":true},"text":"enumerate(list, start=1)","type":"text"},{"styles":{},"text":" gives you both ","type":"text"},{"styles":{"bold":true},"text":"position and value","type":"text"},{"styles":{},"text":" in a single loop variable","type":"text"}],"id":"f37413d2-a468-4724-88b1-8bb7c1633427","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Replaces the clunky ","type":"text"},{"styles":{"code":true},"text":"range(len(list))","type":"text"},{"styles":{},"text":" pattern completely","type":"text"}],"id":"71c29eb3-e5d2-4d07-acaa-d92990c3a0e4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Use it whenever your output or report needs to reference a row number","type":"text"}],"id":"ceeecbdb-97a2-4213-8afa-3512c56de4e4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"✅ Using ","type":"text"},{"styles":{"code":true},"text":"zip()","type":"text"},{"styles":{},"text":" for Parallel Lists","type":"text"}],"id":"cf577ac1-642b-4dec-9b3c-d8c742b7f64f","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"code":true},"text":"zip(list1, list2)","type":"text"},{"styles":{},"text":" walks both lists in lockstep, giving one item from each per step","type":"text"}],"id":"86688ff9-ce71-4dc9-bdab-61a39a53c184","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Stops at the ","type":"text"},{"styles":{"bold":true},"text":"shorter list","type":"text"},{"styles":{},"text":" — items from the longer list are silently dropped","type":"text"}],"id":"c80d7dbd-8479-4ff4-a0c1-3652de8e6cdb","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Always verify both lists have the same length before using ","type":"text"},{"styles":{"code":true},"text":"zip()","type":"text"},{"styles":{},"text":" for alignment","type":"text"}],"id":"eb00abd6-3248-4c73-865f-1be514253040","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"✅ Using ","type":"text"},{"styles":{"code":true},"text":"while","type":"text"},{"styles":{},"text":" Only When Repetition Depends on a Condition","type":"text"}],"id":"094de977-453a-47f5-8d61-788e287be899","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Use ","type":"text"},{"styles":{"code":true},"text":"while","type":"text"},{"styles":{},"text":" when you do ","type":"text"},{"styles":{"bold":true},"text":"not know","type":"text"},{"styles":{},"text":" how many iterations you need before starting","type":"text"}],"id":"d22ddb1a-7db9-4d7e-9ada-7df6d34f3c9b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Always update the condition variable inside the loop","type":"text"},{"styles":{},"text":" — failing to do so causes an infinite loop","type":"text"}],"id":"e15576ce-1d2e-4afe-8934-c7ea24f1a137","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"code":true},"text":"while True","type":"text"},{"styles":{},"text":" + ","type":"text"},{"styles":{"code":true},"text":"break","type":"text"},{"styles":{},"text":" is for loops that must run until an explicit stop signal arrives","type":"text"}],"id":"f625bdff-4f8f-4bff-822f-3e08a3f95ce9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"✅ Understanding ","type":"text"},{"styles":{"code":true},"text":"pass","type":"text"},{"styles":{},"text":" vs ","type":"text"},{"styles":{"code":true},"text":"continue","type":"text"}],"id":"7812ac89-d9f7-40b1-9af1-f18541fea3cc","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"code":true},"text":"pass","type":"text"},{"styles":{},"text":" = ","type":"text"},{"styles":{"bold":true},"text":"do nothing, fall through","type":"text"},{"styles":{},"text":" to the next line normally — the iteration is not skipped","type":"text"}],"id":"4261444f-2ece-4fe9-ab0b-fd5c7bce7646","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"code":true},"text":"continue","type":"text"},{"styles":{},"text":" = ","type":"text"},{"styles":{"bold":true},"text":"skip the rest of this iteration","type":"text"},{"styles":{},"text":" and immediately jump to the next item","type":"text"}],"id":"e18d0fce-1d72-45e2-a9d5-7119f2378503","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"code":true},"text":"pass","type":"text"},{"styles":{},"text":" is a deliberate placeholder that communicates intent; ","type":"text"},{"styles":{"code":true},"text":"continue","type":"text"},{"styles":{},"text":" is a flow control jump","type":"text"}],"id":"2b8e2371-8d75-470b-b788-752646eb62fc","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Key test: after ","type":"text"},{"styles":{"code":true},"text":"pass","type":"text"},{"styles":{},"text":", code below it (if any) still runs; after ","type":"text"},{"styles":{"code":true},"text":"continue","type":"text"},{"styles":{},"text":", it does not","type":"text"}],"id":"4c020e07-0f19-4887-971b-19401be65b86","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"✅ Understanding ","type":"text"},{"styles":{"code":true},"text":"for/else","type":"text"},{"styles":{},"text":" for Search Problems","type":"text"}],"id":"c2f39546-e514-4fbe-b285-bbfad2d0bfff","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The ","type":"text"},{"styles":{"code":true},"text":"else","type":"text"},{"styles":{},"text":" block attached to a ","type":"text"},{"styles":{"code":true},"text":"for","type":"text"},{"styles":{},"text":" loop runs ","type":"text"},{"styles":{"bold":true},"text":"only if no ","type":"text"},{"styles":{"code":true},"text":"break","type":"text"},{"styles":{"bold":true},"text":" occurred","type":"text"}],"id":"90c45f7d-31ff-4398-b727-8b5c4cdf2851","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Use it for the \"find a match or report not found\" pattern without a flag variable","type":"text"}],"id":"7e0b4fb1-d970-43ee-8d3d-ea8b0e5a5b99","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"The ","type":"text"},{"styles":{"code":true},"text":"else","type":"text"},{"styles":{},"text":" is attached to the ","type":"text"},{"styles":{"code":true},"text":"for","type":"text"},{"styles":{},"text":" keyword, not to any ","type":"text"},{"styles":{"code":true},"text":"if","type":"text"},{"styles":{},"text":" inside the loop — indentation matters","type":"text"}],"id":"135331d5-fce1-4489-ba0c-ea6ed784a36a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Without ","type":"text"},{"styles":{"code":true},"text":"for/else","type":"text"},{"styles":{},"text":", you need a ","type":"text"},{"styles":{"code":true},"text":"found = False","type":"text"},{"styles":{},"text":" flag — ","type":"text"},{"styles":{"code":true},"text":"for/else","type":"text"},{"styles":{},"text":" eliminates that cleanly","type":"text"}],"id":"afad16f2-b19c-4bbd-ae9c-a5912750b396","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"id":"1a8ac752-52b9-4606-9bc9-9102761602fa","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"italic":true},"text":"Good luck with your interviews at Sysco, EY, Dialog, and Nagarro. These 15 questions cover every control flow pattern you will need as an intern or fresher Data Engineer.","type":"text"}],"id":"545eb82c-f516-4bb9-bd71-5e8d735d8ce0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[],"id":"3b4ab5dd-61fe-48d2-ab52-bde67a1a02da","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"}]'::jsonb, '3e9e3dd3-a59b-4b02-968a-ee95e7317583') ON CONFLICT ("node_id") DO UPDATE SET "bad_example" = EXCLUDED."bad_example", "completed_at" = EXCLUDED."completed_at", "created_at" = EXCLUDED."created_at", "definition" = EXCLUDED."definition", "good_example" = EXCLUDED."good_example", "is_completed" = EXCLUDED."is_completed", "key_points" = EXCLUDED."key_points", "last_edited" = EXCLUDED."last_edited", "map_id" = EXCLUDED."map_id", "mental_model" = EXCLUDED."mental_model", "notes" = EXCLUDED."notes", "resources" = EXCLUDED."resources", "rich_content" = EXCLUDED."rich_content", "user_id" = EXCLUDED."user_id";
INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-05-26T06:04:13.476754+00:00', '', '', '15ac452e-f402-48e4-9847-4fe1978f0619', false, '[]'::jsonb, '2026-05-26T06:05:36.442+00:00', '21b23730-1e24-468d-a7ac-836d2cdf3ffe', '', 'f7cfa442-4523-4644-85cf-1d0933a5bc8b', '', '[]'::jsonb, '[{"children":[],"content":[{"styles":{"bold":true},"text":"1. Mental Model","type":"text"}],"id":"8a552310-edd2-4aec-bf1f-018dd1703805","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Think of transformation as a ","type":"text"},{"styles":{"bold":true},"text":"food processing factory","type":"text"},{"styles":{},"text":". Raw ingredients arrive from farms (source systems via ingestion). The factory cleans them, cuts them, combines them with other ingredients, applies recipes (business logic), and packages the final product for the store shelves (serving layer). Nobody eats raw, unprocessed ingredients straight from the field.","type":"text"}],"id":"248105ce-1e04-4ec6-965d-3dac076476f9","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"RAW DATA (post-ingestion)\n        │\n        ▼\n┌─────────────────────────────────────┐\n│         TRANSFORMATION              │\n│                                     │\n│  1. Cleaning & validation           │\n│     (remove nulls, fix types)       │\n│                                     │\n│  2. Standardization & enrichment    │\n│     (currency conversion, joins)    │\n│                                     │\n│  3. Business logic application      │\n│     (revenue calc, churn score)     │\n│                                     │\n│  4. Data modeling                   │\n│     (shape data for use case)       │\n│                                     │\n│  5. Featurization (for ML)          │\n│     (create training features)      │\n└─────────────────────────────────────┘\n        │\n        ▼\n  TRUSTED, USABLE DATA\n  → ready for serving","type":"text"}],"id":"65ba21c8-0202-4ee9-af6b-f8485d6d633f","props":{"language":"text"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textColor":"rgb(214, 213, 212)"},"text":"The key insight: ","type":"text"},{"styles":{"bold":true},"text":"transformation is where raw data earns the right to be trusted","type":"text"},{"styles":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textColor":"rgb(214, 213, 212)"},"text":". It is also where the most business logic lives — meaning transformation decisions have the highest organizational stakes of any lifecycle stage.","type":"text"}],"id":"13eb651c-63a3-45dc-a914-35e2253a56c3","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"2. Explanation","type":"text"}],"id":"3a81aecb-78a0-4f75-8d4d-be7fc8733e50","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What transformation is","type":"text"}],"id":"a1a0201b-86e9-4263-b264-4a13b8448831","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Transformation takes data stored after ingestion and ","type":"text"},{"styles":{"bold":true},"text":"changes its form, structure, or content","type":"text"},{"styles":{},"text":" to make it useful for downstream consumers. It is the most business-logic-heavy stage of the lifecycle.","type":"text"}],"id":"714e7914-691d-4c0f-9016-327c1b6c1432","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"The book frames transformation broadly — it''s not just SQL queries. It includes:","type":"text"}],"id":"6e6215f6-f745-42f4-a2ba-ce90ffa7c426","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Cleaning and validating raw data","type":"text"}],"id":"0c7e6b75-f97f-4bc9-abff-6af4f5c5f436","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Standardizing formats across multiple sources","type":"text"}],"id":"2afdeb44-f077-42d7-8aed-effdf25effa2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Joining datasets to create enriched views","type":"text"}],"id":"6a6cbb4d-d7b0-41ae-a9de-6ee528a6b036","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Applying business definitions and rules","type":"text"}],"id":"a31f2dc0-5dde-4de0-aedb-f61a3de3f4bf","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Shaping data into models appropriate for analytics or ML","type":"text"}],"id":"9f181834-f4ff-4339-ac2a-1d8a63a7bdb1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Types of transformations","type":"text"}],"id":"779855c3-9ca6-4099-b779-2d08cb9532e4","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Basic transformations","type":"text"}],"id":"88e023cc-4417-4452-b5c9-20768bebc3be","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The foundation of all pipeline work:","type":"text"}],"id":"0ffcb69c-a62d-47c1-873d-5f626f65ce57","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Type casting","type":"text"},{"styles":{},"text":" — converting strings to integers, timestamps to dates","type":"text"}],"id":"30744539-8082-4a87-9f11-36ddb27cbab5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Null handling","type":"text"},{"styles":{},"text":" — removing, imputing, or flagging missing values","type":"text"}],"id":"09b72f84-e113-4adc-8562-743c761307d7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Deduplication","type":"text"},{"styles":{},"text":" — removing duplicate records from the same source","type":"text"}],"id":"27da0aac-4d65-4b50-b8e3-e45510e21810","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Format standardization","type":"text"},{"styles":{},"text":" — phone numbers, currencies, country codes all normalized to one standard","type":"text"}],"id":"9ed79d83-9b50-45d9-bf27-9dd5cd2a6a11","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Enrichment","type":"text"}],"id":"446a3656-1399-4753-81db-859c67d52fe8","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Combining raw data with context to make it more valuable:","type":"text"}],"id":"6dfa5e0e-dd1e-412a-82cc-f306e8f164a5","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Joining a transaction table with a customer dimension to add demographic context","type":"text"}],"id":"55b5f09f-5c91-44c2-906b-cc9e4868ef7c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Adding a currency conversion rate to normalize international sales","type":"text"}],"id":"03cd0efe-61b9-4fc7-b4f5-4cbdee3b7613","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Appending geolocation data from an IP address table","type":"text"}],"id":"dc3ba9b2-b669-403a-9c8b-bc288f1d9e92","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Business logic application","type":"text"}],"id":"38fe038f-686e-4672-a027-f602d95e6717","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"This is where data becomes meaning:","type":"text"}],"id":"8fd7d7a6-0dcd-488a-b54c-99a85e0cf073","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Defining what a \"customer\" is (30-day active? ever purchased?)","type":"text"}],"id":"7136b79e-58a0-48d3-9191-b12d374fbbd8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Calculating revenue after refunds and discounts","type":"text"}],"id":"9cd00b8c-b027-4248-883e-b90f0bf829e8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Applying churn definitions agreed upon by the business","type":"text"}],"id":"ccadb118-310d-44e2-9820-331f25317dad","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[{"children":[],"content":[{"styles":{"bold":true},"text":"⚠️ Critical nuance: Business logic in transformation is one of the highest-risk areas in all of data engineering. If the definition of \"monthly active user\" changes, every downstream metric changes with it. This is why data governance and documentation are transformation concerns, not afterthoughts.","type":"text"}],"id":"1c6f0acd-b57c-470d-a983-d7faa62f5445","props":{"backgroundColor":"default","textColor":"rgb(214, 213, 212)"},"type":"quote"}],"content":[{"styles":{},"text":"Flagging high-risk transactions based on rules from the fraud team","type":"text"}],"id":"beb33cab-f10f-423d-b233-4086d85bd553","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Data modeling","type":"text"}],"id":"6b076403-2d99-4c17-8888-833490aaff67","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Structuring the transformed data into shapes optimized for use cases:","type":"text"}],"id":"2bb078ba-a957-4ea2-a097-60b88a34c493","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":{"columnWidths":[null,null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{"bold":true},"text":"Model type","type":"text"}],"props":{"backgroundColor":"rgba(214, 213, 212, 0.035)","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"Purpose","type":"text"}],"props":{"backgroundColor":"rgba(214, 213, 212, 0.035)","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"Example","type":"text"}],"props":{"backgroundColor":"rgba(214, 213, 212, 0.035)","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Normalized","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Reduce redundancy, maintain integrity","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"OLTP databases","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Dimensional (Kimball)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Fast analytics queries","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Star schema, fact + dimension tables","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Wide/flat tables","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Simple querying for analysts","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"One big denormalized table","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"One Big Table (OBT)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Analytics simplicity","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Single table with all joins pre-applied","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"667337bf-2289-4f8d-b585-93416bb28337","props":{"textColor":"default"},"type":"table"},{"children":[],"content":[{"styles":{},"text":"The right model depends entirely on the downstream use case — there is no universally correct shape.","type":"text"}],"id":"796f623d-326b-4f45-b770-9335ab983a97","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Featurization for ML","type":"text"}],"id":"8a403377-8347-4cd3-99e1-56cf939d80ac","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"When ML is a downstream consumer, transformation includes:","type":"text"}],"id":"b3aea37a-1c3e-4cde-9509-f7585a4dee84","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Creating numerical features from categorical data","type":"text"}],"id":"b63eca2e-5a55-4053-a6f3-ab5533fe01de","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Calculating rolling averages and lag features","type":"text"}],"id":"b8cb7be1-9297-487f-a0d1-3c51f031b55f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Normalizing and scaling values for model input","type":"text"}],"id":"b5899f6a-c824-4dd4-a90f-88259150eb60","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Generating training labels from historical outcomes","type":"text"}],"id":"49a00eac-a66b-4762-84ea-8fc5ddae6591","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"This is where data engineering and ML engineering overlap most heavily.","type":"text"}],"id":"0225c5d3-bde8-4543-83ed-addfde8fb4f5","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Where transformation happens","type":"text"}],"id":"2257a00a-3571-4bdf-bd74-a879d548c385","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The book introduces a key architectural question: ","type":"text"},{"styles":{"bold":true},"text":"where in the pipeline should transformation occur?","type":"text"}],"id":"7efbddc6-99ff-48a1-828d-e611e0abec9b","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Option 1 — ETL (transform before loading)\n  Source → [Transform] → Storage\n  Cleaner storage, but less flexible\n\nOption 2 — ELT (transform after loading)\n  Source → Storage → [Transform inside warehouse]\n  Raw data preserved, transformation more flexible\n\nOption 3 — In-flight / streaming transformation\n  Source → [Transform inside stream] → Storage\n  Used when downstream can''t tolerate raw data at all","type":"text"}],"id":"746a139f-6ffc-4a55-b2ed-8aeb6ef0ac58","props":{"language":"text"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textColor":"rgb(214, 213, 212)"},"text":"Modern cloud stacks heavily favor ","type":"text"},{"styles":{"bold":true},"text":"ELT","type":"text"},{"styles":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textColor":"rgb(214, 213, 212)"},"text":" — land raw data first, transform inside a powerful cloud warehouse using dbt or similar tools. This preserves the raw layer (you can always rerun transformations) and takes advantage of cheap cloud compute.","type":"text"}],"id":"1ba3b4af-beca-49e2-99c7-0cbf647817be","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"The transformation stack in modern data engineering","type":"text"}],"id":"a6dd8009-938c-426b-abc0-44d06488a1fa","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"At the time of the book''s writing, the dominant transformation tools are:","type":"text"}],"id":"b6f509dc-6858-4081-9eda-041968ff7b9d","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"SQL + dbt","type":"text"},{"styles":{},"text":" — the standard for analytical transformations inside data warehouses","type":"text"}],"id":"16643653-9c47-49c6-acba-83ebfa139d2a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Apache Spark","type":"text"},{"styles":{},"text":" — for large-scale, distributed data processing","type":"text"}],"id":"8b75769e-d8ea-4111-a054-1b144d96d4ee","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Pandas / Python","type":"text"},{"styles":{},"text":" — for smaller-scale, script-based transformations","type":"text"}],"id":"0705fe1d-8b48-471b-bd31-abaf4d55f3c8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Streaming frameworks (Flink, Spark Streaming)","type":"text"},{"styles":{},"text":" — for in-flight transformation of event streams","type":"text"}],"id":"4a183ab1-393e-4c3a-b927-2d1706ef3813","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[],"id":"701bf4d5-f430-4348-93de-38e3b0059550","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"3. Application","type":"text"}],"id":"05a9b3b8-092f-4449-addf-a8a82c65ab80","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why transformation decisions have organizational stakes","type":"text"}],"id":"4062e00b-dbcc-47e4-80b3-321f8ac129c9","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Transformation is where ","type":"text"},{"styles":{"bold":true},"text":"data engineering and the business most directly intersect","type":"text"},{"styles":{},"text":". A data engineer writing transformation logic is encoding business definitions into code. That means:","type":"text"}],"id":"6fb5a9c8-2927-4189-932a-0c37d52d0a8f","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"If analysts disagree on what \"revenue\" means, the transformation layer will reflect that conflict","type":"text"}],"id":"fce341de-c3d2-41fb-972d-4118797d96ca","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"If the same metric is calculated two different ways in two different pipelines, the business will see two different numbers","type":"text"}],"id":"f2f80fea-4abb-4619-901b-09ecd6947a70","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"If transformation logic is undocumented, it becomes a black box that no one trusts","type":"text"}],"id":"90afd212-2046-406d-a279-10b6aaacbe85","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"This is why the best data engineers ","type":"text"},{"styles":{"bold":true},"text":"treat transformation logic as a contract with the business","type":"text"},{"styles":{},"text":", not just as code to write.","type":"text"}],"id":"b58903bf-096f-464b-b484-91b512b3cecc","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"How to reduce transformation risk","type":"text"}],"id":"0e44f57f-d394-4a68-b857-535be01bb4fd","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Document business definitions before writing transformation code","type":"text"}],"id":"8f0d658d-68c7-4005-9d12-6365d82b1a38","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Apply ","type":"text"},{"styles":{"bold":true},"text":"data quality tests","type":"text"},{"styles":{},"text":" on transformed outputs (not just raw inputs)","type":"text"}],"id":"bf2897f2-282b-4e56-bd8d-6cafc259d872","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Version transformation logic — use dbt''s version control integration","type":"text"}],"id":"43d16d10-64f0-4072-8c97-355e9f13943b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Avoid duplicating transformation logic across multiple pipelines; define metrics once","type":"text"}],"id":"f6b21257-9e69-43b4-84ec-37b4d9fc57cf","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"4. Examples","type":"text"}],"id":"560e2322-ec33-4341-8f8b-1c60168b27c0","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Example 1 — Simple: The conflicting revenue numbers\n","type":"text"},{"styles":{},"text":"A finance team and a sales team are both reporting monthly revenue — and they get different numbers. The finance team''s pipeline applies refunds before calculating revenue; the sales team''s pipeline doesn''t. Both are transformations of the same raw transaction data, but with different business logic embedded. ","type":"text"},{"styles":{"italic":true},"text":"The fix is not technical — it''s defining one authoritative transformation that encodes the agreed business definition of revenue","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"1d555ce0-9890-4cf3-9c1e-8a0234fef3c8","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Example 2 — Intermediate: The dbt transformation layer\n","type":"text"},{"styles":{},"text":"An e-commerce company uses Fivetran to ingest raw data from Shopify, Stripe, and Google Analytics into Snowflake. A dbt project then runs a layered transformation: first a staging layer (type casting, deduplication), then an intermediate layer (joining customers to orders), then a mart layer (final business metrics like LTV, churn rate, and cohort retention). Each layer is tested and documented. Analysts query only the mart layer — they never touch raw data. ","type":"text"},{"styles":{"italic":true},"text":"This is the modern ELT transformation pattern done correctly","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"e07d970d-6e70-49b1-b33c-b5ce8baef8d7","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Example 3 — Complex: In-flight streaming transformation\n","type":"text"},{"styles":{},"text":"A bank processes credit card transactions in real-time through a Kafka stream. Each transaction event must be enriched with the customer''s credit limit and account status before reaching the fraud detection model. This enrichment (joining a live event with a database lookup) happens ","type":"text"},{"styles":{"bold":true},"text":"inside the stream","type":"text"},{"styles":{},"text":" using Kafka Streams — before the data lands anywhere. If the enrichment happened after landing, the fraud model would receive incomplete data too late to act. ","type":"text"},{"styles":{"italic":true},"text":"This is in-flight transformation driven by a downstream latency requirement","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"7a9057b9-5100-4ebe-954f-d913a47be119","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[],"id":"461bc19a-d8b4-4e59-99b8-a7036308bb9b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"🧠 Socratic Check: In any pipeline you know, who decides what transformation logic is correct — the data engineer, the analyst, or the business stakeholder? If the answer is unclear or \"whoever wrote the code last,\" that''s a governance gap. The best data engineering teams treat transformation definitions as organizational agreements, not individual engineering decisions.","type":"text"}],"id":"7085c9b2-2c40-455e-b530-fd2171b1c941","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textColor":"rgb(214, 213, 212)"},"type":"quote"},{"children":[],"content":[],"id":"2e11c2a0-31e2-4312-aec9-cb987ed01da9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"}]'::jsonb, '3e9e3dd3-a59b-4b02-968a-ee95e7317583') ON CONFLICT ("node_id") DO UPDATE SET "bad_example" = EXCLUDED."bad_example", "completed_at" = EXCLUDED."completed_at", "created_at" = EXCLUDED."created_at", "definition" = EXCLUDED."definition", "good_example" = EXCLUDED."good_example", "is_completed" = EXCLUDED."is_completed", "key_points" = EXCLUDED."key_points", "last_edited" = EXCLUDED."last_edited", "map_id" = EXCLUDED."map_id", "mental_model" = EXCLUDED."mental_model", "notes" = EXCLUDED."notes", "resources" = EXCLUDED."resources", "rich_content" = EXCLUDED."rich_content", "user_id" = EXCLUDED."user_id";
INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-06-14T14:30:46.869926+00:00', '', '', 'fceaa2e6-c708-4b19-8eca-5f56b0c38bb9', false, '[]'::jsonb, '2026-08-07T09:09:14.329+00:00', '2ad473fe-77dd-481e-8ba7-4b2b0336173f', '', '4b459ad9-af67-4190-9352-5943ae9388c2', '', '[]'::jsonb, '[{"children":[],"content":[{"styles":{},"text":"Now I have enough real-world context from Sysco LABS, EY GDS, and Dialog Axiata to build this comprehensive, interview-ready note. Here it is:","type":"text"}],"id":"d053ab72-27fa-435f-a525-790d25ff4040","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"f4a637f3-7fb2-4ac8-b30f-c0527e79f1e0","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"🧠 Data Engineering Internship Interview — Complete Interview-Ready Note","type":"text"}],"id":"c00dd276-34ba-4dea-8d95-261330ee65a0","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Target Companies: Sysco LABS · EY GDS · Dialog Axiata","type":"text"}],"id":"edb0749f-1afe-4ff9-8e2b-10599668e1a7","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"id":"f5600171-4f9d-477c-a70f-f577ec9c2248","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"1. 🗺️ Mental Model — The Interview is a Risk-Reduction Conversation","type":"text"}],"id":"cd636902-e7c6-4784-abd3-a0bac085be6d","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The Core Idea","type":"text"}],"id":"518c31ad-4148-414a-af07-57da81b48ed4","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"An interview is not an exam. It is a conversation where the interviewer is trying to reduce their uncertainty about you.","type":"text"}],"id":"3df9b89a-d81c-4bdd-8f14-448257f1ee6c","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{},"text":"When a hiring manager at Sysco LABS, EY GDS, or Dialog Axiata interviews you, they are not trying to catch you failing. They are trying to answer one key business question:","type":"text"}],"id":"7ef7ed3f-df5f-4483-a206-4eb0002d198b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"If we give this person a seat on our team, will it cost us more than it gives us?\"","type":"text"}],"id":"89e8b155-da08-4bdf-9974-927562fe0636","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{},"text":"They reduce that risk by checking whether you can: ","type":"text"}],"id":"7691d6f2-1bed-46ea-8699-e15e1f705351","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Their Question","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"What They''re Really Asking","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Can you learn fast?","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Will you be a burden for months, or will you add value quickly?","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Can you communicate clearly?","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Will you slow down senior engineers, or can we trust you to work independently?","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Can you reason through problems?","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"When you hit a blocker, will you think or will you freeze?","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Can you explain your own projects?","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Did you actually build it, or did you copy-paste it?","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Can you work well with a team?","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Will you fit without creating friction?","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"8af2c2c3-7c4b-40a4-968a-6294fe429ae6","props":{"textColor":"default"},"type":"table"},{"children":[],"content":[{"styles":{},"text":"Why This Mindset Makes Interviews Less Scary","type":"text"}],"id":"630d4583-435e-4926-ab97-511b49675826","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"When you think of an interview as an exam, every question feels like a pass/fail trap. You feel like one wrong answer ends everything.","type":"text"}],"id":"bbecf605-5cdc-4ceb-acf7-4d67a3c82356","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"When you think of it as a ","type":"text"},{"styles":{"bold":true},"text":"risk-reduction conversation","type":"text"},{"styles":{},"text":", your job shifts. You are not trying to be perfect — you are trying to be ","type":"text"},{"styles":{"bold":true},"text":"clear, honest, and trustworthy","type":"text"},{"styles":{},"text":". The interviewer wants to believe in you. Your job is to make it easy for them.","type":"text"}],"id":"16c8b762-148f-4e18-9174-aebf20313ee6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"This is especially true for intern and junior roles. The process at companies like Sysco LABS typically begins with an initial HR call to discuss basic qualifications and background, followed by a technical interview focused on role-specific knowledge and problem-solving skills. They are not expecting a senior engineer. They are expecting someone who is coachable, curious, and honest.","type":"text"}],"id":"d907a4c2-3fd2-49ac-bddd-3dd90f988172","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Mindset shift:","type":"text"}],"id":"57c61901-975b-4005-9ef1-fdf07f9c16a0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"❌ \"I must know everything.\"","type":"text"}],"id":"a730ab30-e5d3-4aef-aa55-6dd9ad426d87","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"✅ \"I must show that I think well and learn fast.\"","type":"text"}],"id":"4eedcbb6-5b42-434a-8fff-109cd1a87954","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"id":"c73d40a4-ebc7-4407-bfb4-f0139a4baed1","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"2. 🔍 What Interviewers Evaluate — The Intern/Junior DE Scorecard","type":"text"}],"id":"1a5fed26-92d6-4460-a6fa-18c722238c58","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"At companies like Sysco LABS, EY GDS, and Dialog Axiata, interviewers at the intern/junior level evaluate you across these dimensions:","type":"text"}],"id":"875d99d1-59ba-4d62-9a94-ea2ec8f07a49","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":{"columnWidths":[null,null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Dimension","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"What They Look For","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Red Flags","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Communication","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Clear, structured, confident answers","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Rambling, vague, or silent","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Learning Ability","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Examples of picking up new skills fast","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"\"I haven''t learned that yet\" with no follow-up","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"SQL / Python Fundamentals","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Can you write and explain basic queries and scripts?","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Memorized syntax without understanding","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Data Engineering Fundamentals","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Basic ETL, pipelines, databases","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Buzzword-dropping without depth","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Project Understanding","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Can you explain what YOU built and why?","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Listing tools without explaining decisions","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Reasoning Under Pressure","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Do you think out loud logically when stuck?","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Going silent or making up answers","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Honesty About Limits","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"\"I haven''t used X deeply, but here''s how I''d approach it\"","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Pretending to know things you don''t","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Team Fit","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Collaborative, respectful, professional tone","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Arrogance, negativity about past teams","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Curiosity","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"You ask questions, you''ve explored beyond coursework","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":