INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-05-26T08:01:51.580673+00:00', '', '', '4f9e7573-c613-43ab-996f-0ca6d33592b1', false, '[]'::jsonb, '2026-05-26T08:03:23.179+00:00', 'f22b10db-248b-447f-80b6-4a27bd9171ed', '', '3e5fb94f-d83d-4547-b658-2ff2722ef9ee', '', '[]'::jsonb, '[{"children":[],"content":[{"styles":{"bold":true},"text":"Step 1: Grasping Data Engineering Fundamentals","type":"text"}],"id":"89be27c8-6c44-44cd-837e-56e5d7dd58d5","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":1,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Data Modeling","type":"text"}],"id":"05966b8e-be19-4279-b553-d0a664e30fb4","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Data modeling is the process of ","type":"text"},{"styles":{"bold":true},"text":"creating a visual blueprint of how your data will be stored","type":"text"},{"styles":{},"text":" inside a Relational Database Management System (RDBMS) — before you actually build it.","type":"text"}],"id":"3463ed17-ca4f-47ca-86b1-c7e1a4f30ecc","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"id":"10883975-566b-40b8-ab6c-659e15fc54c1","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"🏗️ Mental Model — The Architectural Blueprint","type":"text"}],"id":"a4a25b10-eae2-405d-82d6-f0f00229df25","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{"bold":true},"text":"Blueprint Element","type":"text"}],"props":{"backgroundColor":"rgba(214, 213, 212, 0.035)","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"Database Equivalent","type":"text"}],"props":{"backgroundColor":"rgba(214, 213, 212, 0.035)","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Detailed schematic / blueprint","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Data model / ER diagram","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Rooms","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Tables (e.g., Users, Products, Orders)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"What each room holds","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Columns and their data types","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Hallways and doors connecting rooms","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Keys (Primary & Foreign)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"bold":true},"text":"Actual furniture","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"The real data inserted later","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"c6f6cae6-77a2-44fc-95ab-c9ced2c92155","props":{"textColor":"default"},"type":"table"},{"children":[],"content":[{"styles":{"bold":true},"text":"Just as you wouldn''t pour concrete without a blueprint, you should never build a database without a data model.","type":"text"}],"id":"f156759a-7f4b-4e9b-8ccf-4c49e4663923","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textColor":"rgb(214, 213, 212)"},"type":"quote"},{"children":[],"id":"dcc645a7-713c-4a8a-9a3d-ec6bac739090","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"📖 Why Data Modeling Exists","type":"text"}],"id":"21195d6f-b110-4465-afbe-f71acd2f825f","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Businesses generate massive, complex amounts of data. Storing everything in ","type":"text"},{"styles":{"bold":true},"text":"one giant spreadsheet is impossible","type":"text"},{"styles":{},"text":" — it becomes unmanageable, slow, and error-prone.","type":"text"}],"id":"d85cae99-3e3d-488a-8024-c2c114d13846","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Instead, data is broken down into ","type":"text"},{"styles":{"bold":true},"text":"distinct, logical tables","type":"text"},{"styles":{},"text":", each governed by a strict schema:","type":"text"}],"id":"a3983d8c-087f-4b4d-b3d8-91170b516bd5","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{"bold":true},"text":"Column","type":"text"}],"props":{"backgroundColor":"rgba(214, 213, 212, 0.035)","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"tableCell"},{"content":[{"styles":{"bold":true},"text":"Data Type","type":"text"}],"props":{"backgroundColor":"rgba(214, 213, 212, 0.035)","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"User_ID","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Integer","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"Name","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"String (VARCHAR)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"Order_Date","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Date","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"Price","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Decimal","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"56648653-3248-4868-8dd4-c6ce04b871be","props":{"textColor":"default"},"type":"table"},{"children":[],"content":[{"styles":{"bold":true},"text":"Every column has a specific data type — the DBMS enforces this strictly, ensuring data integrity across millions of records.","type":"text"}],"id":"74372f09-9256-4397-ab58-40ac196cb462","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textColor":"rgb(214, 213, 212)"},"type":"quote"},{"children":[],"id":"40cbfcdf-6cd6-4102-8ec1-40b7493a9434","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"🔑 Making Tables Relational — Keys","type":"text"}],"id":"d75a5c48-b5ee-4c4e-83b3-c1bb11f70286","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Isolated tables are useless on their own. ","type":"text"},{"styles":{"bold":true},"text":"Keys","type":"text"},{"styles":{},"text":" are what connect them and make the database truly ","type":"text"},{"styles":{"italic":true},"text":"relational","type":"text"},{"styles":{},"text":":","type":"text"}],"id":"