INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-05-26T08:05:12.819961+00:00', '', '', '9865566e-a3a5-4968-b0a7-65b207974902', false, '[]'::jsonb, '2026-05-26T08:06:09.45+00:00', 'f22b10db-248b-447f-80b6-4a27bd9171ed', '', '8195b97c-5cab-4355-b82f-d90f88350c44', '', '[]'::jsonb, '[{"children":[],"content":[{"styles":{"bold":true},"text":"Step 2: Mastering Data Storage & Processing Systems","type":"text"}],"id":"42329464-a544-4232-a339-49e83ccdcfc9","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":1,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"SQL vs. NoSQL","type":"text"}],"id":"38f69856-d09d-4d8e-843b-decc3116aefc","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The choice between SQL and NoSQL comes down to one fundamental question: ","type":"text"},{"styles":{"bold":true},"text":"how structured is your data?","type":"text"},{"styles":{},"text":" SQL enforces strict organization; NoSQL embraces flexibility.","type":"text"}],"id":"a651bc98-508f-4fd0-8cca-76dee7cd0297","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"id":"e54325a6-013e-4068-b992-ccd07236a343","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"🗂️ Mental Model — Filing Cabinet vs. Digital Folder","type":"text"}],"id":"502f8266-3016-44aa-b838-8c21deb2cdd7","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggl