INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-08-06T16:20:11.840349+00:00', '', '', '9d7860a7-0f3c-436f-accd-e28012175354', false, '[]'::jsonb, '2026-08-06T16:23:38.744+00:00', '2ad473fe-77dd-481e-8ba7-4b2b0336173f', '', 'fa591c67-19ad-41f7-a763-5fb955d71b7a', '', '[]'::jsonb, '[{"children":[],"content":[{"styles":{},"text":"📘 PYSPARK FOR DATA ENGINEERING — Complete Study Note for Interviews","type":"text"}],"id":"48ac3b42-a137-4389-acd0-b776e8bc696e","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"id":"b5b63ee8-1722-4c94-996a-1821d029f850","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"🎯 What PySpark Means in a DE Interview","type":"text"}],"id":"01767632-5082-4409-8810-a1f217b26ee8","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"PySpark = Python API for Apache Spark. You write Python, Spark runs it distributed across a cluster.","type":"text"}],"id":"21dd8c63-c2a1-4956-b812-048233ef039c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Every concept in the Architecture note is now going to show up as actual code. When you write ","type":"text"},{"styles":{"code":true},"text":"df.groupBy(\"region\").sum()","type":"text"},{"styles":{},"text":" you will know:","type":"text"}],"id":"9e174509-483f-48b2-b0c7-835ecdc560e1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"That line is a ","type":"text"},{"styles":{"bold":true},"text":"wide transformation","type":"text"},{"styles":{},"text":" — it causes a ","type":"text"},{"styles":{"bold":true},"text":"shuffle","type":"text"}],"id":"76e969a8-85ae-463e-b704-ea83d9d7a66f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Nothing executes until you call an ","type":"text"},{"styles":{"bold":true},"text":"action","type":"text"}],"id":"36e8d298-877f-4500-91b6-fde35d0c02e2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Spark''s ","type":"text"},{"styles":{"bold":true},"text":"Catalyst optimizer","type":"text"},{"styles":{},"text":" is building a DAG behind the scenes","type":"text"}],"id":"1283fcc0-65df-423d-a6b1-7f3ae578fcd5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Each partition is processed by a separate ","type":"text"},{"styles":{"bold":true},"text":"Executor","type":"text"}],"id":"0e2bf4af-27ba-411e-95f6-ae4f199e4b31","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"That connected understanding is what separates a candidate who memorized syntax from one who actually knows PySpark.","type":"text"}],"id":"682c1319-f5d2-42b4-ba8e-db69b539bfda","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"4d5060f7-2343-4c35-88e5-8fb24b5721f4","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"SECTION 1 — Setting Up PySpark (Your Starting Point Every Time)","type":"text"}],"id":"87ab9755-5fef-43b2-9a35-048e60e9a316","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Installation (do this once)","type":"text"}],"id":"e51cb0eb-bc82-41e0-b7e8-1abf7447c3c3","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"pip install pyspark","type":"text"}],"id":"2a0a6b7f-8ade-4d7b-b670-209269c463b2","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"The SparkSession — write this from memory every interview","type":"text"}],"id":"4fb3265e-bf1f-4966-8660-3c3ea22732eb","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"from pyspark.sql import SparkSession\n\nspark = SparkSession.builder \\\n    .appName(\"SalesPipeline\") \\\n    .master(\"local[*]\") \\\n    .getOrCreate()","type":"text"}],"id":"bf0d78d7-d313-434b-8a0e-524d881a1e88","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"What each line does:","type":"text"}],"id":"e2cd3fd8-f565-4f5d-9709-86535b1208fe","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"code":true},"text":".appName()","type":"text"},{"styles":{},"text":" — names your job (shows in Spark UI)","type":"text"}],"id":"960787c7-f231-42d9-93c3-4a632e686be8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"code":true},"text":".master(\"local[*]\")","type":"text"},{"styles":{},"text":" — run locally using all CPU cores (interview/dev mode)","type":"text"}],"id":"e753d956-e275-4d67-84a0-bd7a698fcc3e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"code":true},"text":".getOrCreate()","type":"text"},{"styles":{},"text":" — return existing session if one exists, create if not (idempotent)","type":"text"}],"id":"e8830187-c27f-425a-91dc-281d635e0b4e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Stopping a session (always do this at the end)","type":"text"}],"id":"f7de89f7-96ac-42c9-85f2-4dbe90f2d28c","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"spark.stop()","type":"text"}],"id":"c0394859-534b-4dba-aab6-4dd7cf4125d0","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"The imports you will use constantly","type":"text"}],"id":"f7e446c9-6839-473d-9bc9-1b6eeb6c6f2e","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"from pyspark.sql import SparkSession\nfrom pyspark.sql import functions as F      # ALL built-in functions live here\nfrom pyspark.sql.types import *             # schema definition types\nfrom pyspark.sql.window import Window       # window functions","type":"text"}],"id":"252909c9-0840-4549-91ef-f403e4f7d1b0","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Critical habit:","type":"text"},{"styles":{},"text":" Import ","type":"text"},{"styles":{"code":true},"text":"functions as F","type":"text"},{"styles":{},"text":" and always call ","type":"text"},{"styles":{"code":true},"text":"F.col()","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"F.sum()","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"F.when()","type":"text"},{"styles":{},"text":" etc. Never use bare function names — it avoids name conflicts and makes code readable.","type":"text"}],"id":"a598be01-bb32-47c1-b1b1-ad5efb9b12a0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Practice Exercise 1","type":"text"}],"id":"32c2e228-342c-422a-9d8e-64ee5ee58eb0","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# Create a SparkSession with:\n# - App name: \"InterviewPractice\"\n# - Master: local[*]\n# - shuffle partitions set to 10 (config: spark.sql.shuffle.partitions)\n# Print the Spark version\n# Stop the session","type":"text"}],"id":"808d6232-1963-42e9-9403-37d36c50c2ad","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"3f695829-16af-4d83-b2bf-c12168d57db8","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"SECTION 2 — Creating DataFrames (Three Ways)","type":"text"}],"id":"a374d444-e50b-4d42-a255-d32e730a12b8","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Way 1 — From a list of tuples with a schema (most common in interviews)","type":"text"}],"id":"80c9cfcd-3431-4fbb-a1e4-38f4ec1b99cb","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"from pyspark.sql.types import StructType, StructField, StringType, DoubleType, IntegerType\n\nschema = StructType([\n    StructField(\"id\",     StringType(),  nullable=False),\n    StructField(\"region\", StringType(),  nullable=True),\n    StructField(\"amount\", DoubleType(),  nullable=True),\n    StructField(\"date\",   StringType(),  nullable=True),\n])\n\ndata = [\n    (\"S1\", \"South\", 250.0, \"2024-01-01\"),\n    (\"S2\", \"North\", 150.0, \"2024-01-01\"),\n    (\"S3\", \"East\",  300.0, \"2024-01-02\"),\n    (\"S4\", \"West\",  None,  \"2024-01-02\"),\n]\n\ndf = spark.createDataFrame(data, schema=schema)\ndf.show()","type":"text"}],"id":"469d120c-8869-49a0-be28-29b2bc8e3382","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Way 2 — From a list of dicts (simpler, schema inferred)","type":"text"}],"id":"0d04f358-c660-48de-b4b0-1b92bf9c096e","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"data = [\n    {\"id\": \"S1\", \"region\": \"South\", \"amount\": 250.0},\n    {\"id\": \"S2\", \"region\": \"North\", \"amount\": 150.0},\n]\ndf = spark.createDataFrame(data)","type":"text"}],"id":"603b8987-8093-4958-8a90-8c7ecb3a1289","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Way 3 — From pandas DataFrame (very common in mixed pipelines)","type":"text"}],"id":"f9470d08-d52b-4219-aca8-af2a5009495e","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"import pandas as pd\n\npandas_df = pd.DataFrame([\n    {\"id\": \"S1\", \"region\": \"South\", \"amount\": 250.0},\n    {\"id\": \"S2\", \"region\": \"North\", \"amount\": 150.0},\n])\ndf = spark.createDataFrame(pandas_df)","type":"text"}],"id":"3860098b-86c6-444e-8506-9eeab9f3bcc8","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Key types to know for schema definition","type":"text"}],"id":"b92b8aa7-8e1c-4b9b-af82-5593e342b851","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"PySpark Type","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Python equivalent","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"StringType()","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"str","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"IntegerType()","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"int","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"LongType()","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"int (big)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"DoubleType()","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"float","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"BooleanType()","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"bool","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"DateType()","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"date","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"TimestampType()","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"datetime","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"ArrayType(StringType())","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"list of strings","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"MapType(StringType(), DoubleType())","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"dict","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"4704f096-a0d0-4027-b449-7d6892d7de75","props":{"textColor":"default"},"type":"table"},{"children":[],"content":[{"styles":{},"text":"Practice Exercise 2","type":"text"}],"id":"c10ed4a2-aae6-402d-a60e-e14791242eb1","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# Create a DataFrame from scratch using explicit schema with:\n# id (string, not nullable)\n# region (string, nullable)\n# amount (double, nullable)\n# date (string, nullable)\n# Add 5 rows with one having a None amount\n# Show the DataFrame and print its schema","type":"text"}],"id":"406d8c85-4290-49e9-94c5-bf421abeb5c8","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"9cf6fe80-264e-4b15-a57a-9f0c4d6de678","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"SECTION 3 — Inspecting DataFrames (Always Do This First)","type":"text"}],"id":"8f3b275c-e9c1-42fa-883f-d7485d68ea0d","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"df.show()               # print first 20 rows (default)\ndf.show(5)              # print first 5 rows\ndf.show(truncate=False) # show full column values, no truncation\n\ndf.printSchema()        # column names, types, nullable flags\ndf.dtypes               # list of (column_name, type_string) tuples\ndf.columns              # list of column name strings\ndf.count()              # total row count — ACTION, triggers execution\ndf.describe().show()    # stats: count, mean, stddev, min, max for numeric cols\n\n# Missing value count per column\nfrom pyspark.sql import functions as F\ndf.select([F.count(F.when(F.col(c).isNull(), c)).alias(c) for c in df.columns]).show()","type":"text"}],"id":"3793cd9f-fef8-47a4-b38a-770b6d898a38","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Practice Exercise 3","type":"text"}],"id":"c29f1ebe-dfdf-4c71-a4ee-9c889cfbbb25","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# Given a DataFrame with 6 columns,\n# write an inspect(df) function that prints:\n# - schema\n# - row count\n# - null count per column\n# - distinct value count for ''region'' column","type":"text"}],"id":"a514e963-55db-4628-a981-93713fc094f9","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"4094fdb5-31e5-44ed-9e51-66beb86a576e","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"SECTION 4 — Reading Data From Files","type":"text"}],"id":"6ba58f85-a9fb-416f-a6da-79e8d67892b3","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"CSV","type":"text"}],"id":"fdbfe65f-ccfa-4f75-af8a-4dcfabbfc7ea","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# Basic\ndf = spark.read.csv(\"sales.csv\", header=True, inferSchema=True)\n\n# Explicit schema (always prefer this in production — inferSchema scans whole file)\ndf = spark.read.schema(schema).csv(\"sales.csv\", header=True)\n\n# Multiple files or a folder\ndf = spark.read.csv(\"data/\", header=True, inferSchema=True)\n\n# With options\ndf = spark.read \\\n    .option(\"header\", True) \\\n    .option(\"inferSchema\", True) \\\n    .option(\"nullValue\", \"N/A\") \\\n    .option(\"dateFormat\", \"yyyy-MM-dd\") \\\n    .csv(\"sales.csv\")","type":"text"}],"id":"d643a82a-39d5-428a-848b-b407edde43d5","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"JSON","type":"text"}],"id":"9d8307b5-df28-4dd3-b411-df026d04b336","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"df = spark.read.json(\"sales.json\")   # each line = one JSON object (JSONL)\ndf = spark.read.option(\"multiline\", True).json(\"nested.json\")  # pretty-printed JSON","type":"text"}],"id":"f5ab04a4-4974-42bc-8297-83d32c9ec25a","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Parquet","type":"text"}],"id":"2a93cc6b-ccda-4851-9d83-14380dac9de7","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"df = spark.read.parquet(\"data/sales.parquet\")\ndf = spark.read.parquet(\"data/year=2024/\")   # read one partition folder","type":"text"}],"id":"2731c1b8-7127-4975-965f-9a66c70ff859","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Reading with explicit partition discovery","type":"text"}],"id":"159efa98-074e-4791-a210-896d7b38d554","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# Reads partitioned folder structure: data/year=2024/month=01/...\ndf = spark.read.option(\"basePath\", \"data/\").parquet(\"data/year=2024/\")\n# Adds ''year'' and ''month'' as columns automatically","type":"text"}],"id":"b62d9b6e-34e2-4ef4-9cad-a6fc93d689e3","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Practice Exercise 4","type":"text"}],"id":"dc8abb5e-5a9f-4e99-973d-1f39984fca33","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# Create a sample CSV file using Python''s csv module\n# Read it into Spark with:\n# - explicit schema (no inferSchema)\n# - nullValue option set to ''''\n# Show the result and print schema\n# Then write it as Parquet and read it back","type":"text"}],"id":"8067d746-4a7b-41f8-ab43-87d8477c7364","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"61984186-5a52-408b-b904-f2a255742834","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"SECTION 5 — Selecting & Filtering (The Basics)","type":"text"}],"id":"8292c980-dede-41ec-89c3-7e43ffe3e5fb","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Selecting columns","type":"text"}],"id":"caa30af0-783e-40e8-9eaa-0026bf70d198","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# Three equivalent ways — know all three\ndf.select(\"region\", \"amount\")\ndf.select(F.col(\"region\"), F.col(\"amount\"))\ndf[\"region\"]           # returns a Column object — use inside select\n\n# Select with transformation\ndf.select(\"region\", (F.col(\"amount\") * 1.1).alias(\"amount_with_tax\"))\n\n# Select all columns plus a new one\ndf.select(\"*\", F.lit(\"India\").alias(\"country\"))  # F.lit = literal value","type":"text"}],"id":"14ce91c8-0518-4ca2-b057-4ed09449c719","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Filtering rows","type":"text"}],"id":"eed7ef72-d200-4b8e-915a-6d4404e3ce6f","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# Two equivalent methods — filter and where are identical\ndf.filter(F.col(\"amount\") > 100)\ndf.where(F.col(\"amount\") > 100)\n\n# Multiple conditions\ndf.filter((F.col(\"amount\") > 100) & (F.col(\"region\") == \"South\"))\ndf.filter((F.col(\"region\") == \"South\") | (F.col(\"region\") == \"North\"))\n\n# NOT\ndf.filter(~(F.col(\"region\") == \"South\"))\n\n# isin\ndf.filter(F.col(\"region\").isin([\"South\", \"North\"]))\n\n# isNull / isNotNull\ndf.filter(F.col(\"amount\").isNull())\ndf.filter(F.col(\"amount\").isNotNull())\n\n# String operations\ndf.filter(F.col(\"region\").startswith(\"S\"))\ndf.filter(F.col(\"region\").contains(\"outh\"))\ndf.filter(F.col(\"region\").like(\"%outh%\"))    # SQL LIKE syntax","type":"text"}],"id":"dd4f8e71-ef2a-4c12-aca9-4e85f7e073f4","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Practice Exercise 5","type":"text"}],"id":"6dcf7c7b-243c-450f-ad8e-49a6487bc25a","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# Given sales DataFrame:\n# 1. Select id, region, amount only\n# 2. Filter rows where amount > 200\n# 3. Filter rows where region is South or East AND amount > 100\n# 4. Filter rows where amount is NOT null\n# 5. Find all rows where region starts with ''S''","type":"text"}],"id":"9f764c3a-6172-40c9-85ed-cf072dda8034","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"382d9b7b-b1c1-4138-9816-f2c09897bf41","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"SECTION 6 — Adding & Modifying Columns (","type":"text"},{"styles":{"code":true},"text":"withColumn","type":"text"},{"styles":{},"text":")","type":"text"}],"id":"1df59bf0-3fcc-4e62-8704-20575735a80c","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"code":true},"text":"withColumn","type":"text"},{"styles":{},"text":" — the most used transformation in PySpark","type":"text"}],"id":"72bd4dcf-b76d-4b3f-9a56-7ca1252a6fb6","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# Add a new column\ndf = df.withColumn(\"amount_usd\", F.col(\"amount\") * 0.0031)\n\n# Modify an existing column (same column name)\ndf = df.withColumn(\"region\", F.upper(F.col(\"region\")))\n\n# Conditional column — SQL CASE WHEN equivalent\ndf = df.withColumn(\"category\",\n    F.when(F.col(\"amount\") > 500, \"high\")\n     .when(F.col(\"amount\") > 100, \"medium\")\n     .otherwise(\"low\")\n)\n\n# Using F.lit for a constant value\ndf = df.withColumn(\"currency\", F.lit(\"LKR\"))\n\n# Type casting\ndf = df.withColumn(\"amount\", F.col(\"amount\").cast(DoubleType()))\ndf = df.withColumn(\"date\", F.to_date(F.col(\"date\"), \"yyyy-MM-dd\"))","type":"text"}],"id":"cc3119f9-5ad6-43d3-aa23-7617fb48193f","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Renaming and dropping columns","type":"text"}],"id":"65acf35f-c4dd-40da-b026-791c666a63e9","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"df = df.withColumnRenamed(\"amount\", \"sale_amount\")\ndf = df.drop(\"unnecessary_col\")\ndf = df.drop(\"col1\", \"col2\")","type":"text"}],"id":"7b5f2e06-471d-422f-953d-1a44a145172c","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Multiple withColumns — cleaner in Spark 3.x","type":"text"}],"id":"6947064c-86f9-4775-90d9-d5e37df53c28","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# Spark 3.x: withColumns (plural) — add multiple at once\ndf = df.withColumns({\n    \"amount_usd\": F.col(\"amount\") * 0.0031,\n    \"category\": F.when(F.col(\"amount\") > 500, \"high\").otherwise(\"low\"),\n    \"year\": F.year(F.col(\"date\")),\n})","type":"text"}],"id":"371e92de-5ae9-48a8-b999-e54d0e8501a9","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Practice Exercise 6","type":"text"}],"id":"9d434543-3225-49d2-b646-e7ad1979bdcf","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# Given sales DataFrame with id, region, amount, date:\n# 1. Add ''amount_with_tax'' = amount * 1.05\n# 2. Add ''size'' = ''large'' if amount > 300, ''small'' otherwise\n# 3. Add ''year'' and ''month'' extracted from date column\n# 4. Rename ''amount'' to ''sale_amount''\n# 5. Drop the ''date'' column\n# Show final schema and first 5 rows","type":"text"}],"id":"8726875b-89a9-4180-82ff-1a33d0227c0c","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"721749c5-9291-463d-bc7b-abc65b84bb88","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"SECTION 7 — Built-in Functions (The F. Library)","type":"text"}],"id":"9a64eb26-24ce-4fb8-8ab9-ad04b10c5412","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"This is the most important section for writing real PySpark code. All functions live in ","type":"text"},{"styles":{"code":true},"text":"pyspark.sql.functions","type":"text"},{"styles":{},"text":" — always import as ","type":"text"},{"styles":{"code":true},"text":"F","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"cb9789f4-b349-456e-9791-751aeb05a21c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"String functions","type":"text"}],"id":"fe335ce8-bddc-4ad2-9d80-83d0972eadf4","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"F.upper(F.col(\"region\"))          # SOUTH\nF.lower(F.col(\"region\"))          # south\nF.trim(F.col(\"region\"))           # remove whitespace\nF.ltrim(), F.rtrim()              # left/right trim\nF.length(F.col(\"region\"))         # string length\nF.substring(F.col(\"id\"), 1, 3)   # characters 1-3 (1-indexed)\nF.concat(F.col(\"region\"), F.lit(\"-\"), F.col(\"id\"))   # string concatenation\nF.split(F.col(\"tags\"), \",\")       # split into array\nF.regexp_replace(F.col(\"id\"), \"[^0-9]\", \"\")  # regex replace\nF.regexp_extract(F.col(\"text\"), r\"(\\d+)\", 1) # regex extract group 1\nF.coalesce(F.col(\"a\"), F.col(\"b\"), F.lit(\"default\"))  # first non-null value","type":"text"}],"id":"79d6dd0e-0fc2-4d7b-be59-bd8b6f722e2e","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Numeric functions","type":"text"}],"id":"88ef15e4-57ef-4954-9ba9-8ff713b749dd","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"F.round(F.col(\"amount\"), 2)       # round to 2 decimal places\nF.abs(F.col(\"amount\"))            # absolute value\nF.sqrt(F.col(\"amount\"))           # square root\nF.pow(F.col(\"amount\"), 2)         # power\nF.floor(F.col(\"amount\"))          # round down\nF.ceil(F.col(\"amount\"))           # round up","type":"text"}],"id":"205579a9-bc84-4887-84be-55d381c53d43","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Date and timestamp functions","type":"text"}],"id":"7974f87a-6151-40dd-b8f0-e7a94555facc","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"F.current_date()                           # today''s date\nF.current_timestamp()                      # current datetime\nF.to_date(F.col(\"date\"), \"yyyy-MM-dd\")    # string to date\nF.to_timestamp(F.col(\"ts\"), \"yyyy-MM-dd HH:mm:ss\")  # string to timestamp\nF.year(F.col(\"date\"))                      # extract year\nF.month(F.col(\"date\"))                     # extract month\nF.dayofmonth(F.col(\"date\"))               # extract day\nF.dayofweek(F.col(\"date\"))                # day of week (1=Sunday)\nF.date_format(F.col(\"date\"), \"MM/yyyy\")   # format date as string\nF.datediff(F.current_date(), F.col(\"date\"))  # days between\nF.date_add(F.col(\"date\"), 7)              # add 7 days\nF.months_between(F.col(\"end\"), F.col(\"start\"))  # months between two dates","type":"text"}],"id":"f18fe920-9c2e-4657-bb5b-57c4be321658","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Aggregate functions (used inside groupBy)","type":"text"}],"id":"be60c029-d188-4f9f-98f8-3005631d2207","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"F.sum(\"amount\")\nF.count(\"amount\")           # count non-null\nF.count(\"*\")                # count all rows\nF.countDistinct(\"region\")\nF.avg(\"amount\")\nF.mean(\"amount\")            # same as avg\nF.max(\"amount\")\nF.min(\"amount\")\nF.stddev(\"amount\")\nF.collect_list(\"amount\")    # collect all values into an array\nF.collect_set(\"region\")     # collect unique values into an array\nF.first(\"amount\")           # first value in group\nF.last(\"amount\")            # last value in group","type":"text"}],"id":"801ebb74-48f1-442d-b6a1-3d278011e9b5","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Null handling functions","type":"text"}],"id":"a6de4959-8c6e-4b1d-868e-81c5bef46b30","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"F.isNull(F.col(\"amount\"))                              # check if null\nF.isNotNull(F.col(\"amount\"))\nF.coalesce(F.col(\"amount\"), F.lit(0))                 # replace null with 0\nF.isnull(F.col(\"amount\"))                              # same as isNull\nF.when(F.col(\"amount\").isNull(), 0).otherwise(F.col(\"amount\"))  # conditional fill\nF.nvl(F.col(\"a\"), F.col(\"b\"))                          # Spark 3.x, same as coalesce(a,b)","type":"text"}],"id":"c0ad91b9-cc8b-4c66-ad4e-35f788452309","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Practice Exercise 7","type":"text"}],"id":"14ee982e-1912-431d-b767-84f4ab773b2f","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# Given sales DataFrame:\n# 1. Add column ''region_upper'' = region in uppercase\n# 2. Add column ''id_number'' = extract only digits from id (S1 -> 1)\n# 3. Add column ''days_since_sale'' = days between sale date and today\n# 4. Add column ''amount_display'' = concat ''$'' + round(amount, 2) as string\n# 5. Add column ''region_known'' = region if not null, else ''UNKNOWN''","type":"text"}],"id":"cf74f17e-66b1-4a6a-ae7d-c01d069e0610","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"a163e8ce-58e9-4ee2-a3d7-08efa4288600","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"SECTION 8 — GroupBy & Aggregation (SQL GROUP BY)","type":"text"}],"id":"023f8d91-3a94-48bb-928e-5f80ddc51c42","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# Single aggregation\ndf.groupBy(\"region\").sum(\"amount\").show()\ndf.groupBy(\"region\").count().show()\ndf.groupBy(\"region\").avg(\"amount\").show()\n\n# Multiple aggregations — the real pattern\nresult = df.groupBy(\"region\").agg(\n    F.sum(\"amount\").alias(\"total_amount\"),\n    F.count(\"*\").alias(\"order_count\"),\n    F.avg(\"amount\").alias(\"avg_amount\"),\n    F.max(\"amount\").alias(\"max_amount\"),\n    F.min(\"amount\").alias(\"min_amount\"),\n    F.countDistinct(\"id\").alias(\"unique_orders\"),\n).show()\n\n# Group by multiple columns\ndf.groupBy(\"region\", \"year\").agg(\n    F.sum(\"amount\").alias(\"total\"),\n).show()\n\n# Filter AFTER groupBy (SQL HAVING equivalent)\ndf.groupBy(\"region\").agg(\n    F.sum(\"amount\").alias(\"total\")\n).filter(F.col(\"total\") > 500).show()\n\n# OrderBy after groupBy\ndf.groupBy(\"region\").agg(\n    F.sum(\"amount\").alias(\"total\")\n).orderBy(F.col(\"total\").desc()).show()","type":"text"}],"id":"cc7b6151-9787-4802-ab9d-932b34d18eaa","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Practice Exercise 8","type":"text"}],"id":"1b6cc910-bc18-4ff4-b3f4-c198796f732f","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# Given sales DataFrame (id, region, amount, date, year, month):\n# 1. Total amount per region, ordered by total descending\n# 2. Per region: total, count, average — in one agg call\n# 3. Per region per month: total amount\n# 4. Regions where total amount > 500 (HAVING equivalent)\n# 5. Top 3 regions by total amount","type":"text"}],"id":"8e7e7f28-bb81-4be9-bd4c-d59d12be4cce","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"c4cfdd70-77bc-460d-a519-9aa1a3fac715","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"SECTION 9 — Joins (SQL JOIN in PySpark)","type":"text"}],"id":"779d6922-1004-4efb-9f0b-c882d25aa556","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"customers = spark.createDataFrame([\n    (\"C1\", \"Alice\", \"South\"),\n    (\"C2\", \"Bob\",   \"North\"),\n    (\"C3\", \"Carol\", \"East\"),\n], [\"id\", \"name\", \"region\"])\n\norders = spark.createDataFrame([\n    (\"O1\", \"C1\", 250.0),\n    (\"O2\", \"C2\", 150.0),\n    (\"O3\", \"C1\", 300.0),\n    (\"O4\", \"C9\", 100.0),  # no matching customer\n], [\"order_id\", \"cid\", \"amount\"])\n\n# INNER JOIN — only matching rows\nresult = orders.join(customers, orders.cid == customers.id, \"inner\")\n\n# LEFT JOIN — all orders, customer info or null if no match\nresult = orders.join(customers, orders.cid == customers.id, \"left\")\n\n# RIGHT JOIN — all customers, order info or null if no match\nresult = orders.join(customers, orders.cid == customers.id, \"right\")\n\n# FULL OUTER JOIN — all rows from both\nresult = orders.join(customers, orders.cid == customers.id, \"outer\")\n\n# LEFT ANTI JOIN — orders with NO matching customer (SQL anti-join)\nresult = orders.join(customers, orders.cid == customers.id, \"left_anti\")\n\n# LEFT SEMI JOIN — orders that HAVE a matching customer (no customer columns added)\nresult = orders.join(customers, orders.cid == customers.id, \"left_semi\")\n\n# Same column name on both sides\nresult = df_a.join(df_b, on=\"id\", how=\"inner\")\n\n# Multiple join conditions\nresult = df_a.join(df_b,\n    (df_a.id == df_b.id) & (df_a.region == df_b.region),\n    \"inner\"\n)","type":"text"}],"id":"52049426-1765-415b-9db1-a85d86a747de","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"The duplicate column problem after joins","type":"text"}],"id":"754c41c8-3afb-49f8-ad19-fafe459b5c49","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"When both DataFrames have a column with the same name, joining creates two columns with the same name — ambiguous.","type":"text"}],"id":"51b0f2ab-0be9-409f-8ef8-1def5bd2bf06","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"# BAD: both have ''id'' — now result has two ''id'' columns\nresult = orders.join(customers, orders.cid == customers.id, \"inner\")\nresult.select(\"id\")   # ERROR: ambiguous\n\n# FIX 1: drop the duplicate after join\nresult = result.drop(customers.id)\n\n# FIX 2: rename before join\ncustomers = customers.withColumnRenamed(\"id\", \"customer_id\")\nresult = orders.join(customers, orders.cid == customers.customer_id, \"inner\")\n\n# FIX 3: use on=\"col\" only when column name is same in both (no duplicate created)\nresult = df_a.join(df_b, on=\"id\", how=\"inner\")   # only one ''id'' column in result","type":"text"}],"id":"70a370d6-016d-4c5f-a0dd-d49869d278ac","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Broadcast join (critical for performance)","type":"text"}],"id":"d16ca0b6-a609-473e-acfa-b26905e38c85","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"from pyspark.sql.functions import broadcast\n\n# customers is small — send a copy to every Executor\n# avoids shuffle of the orders table\nresult = orders.join(broadcast(customers), orders.cid == customers.id, \"inner\")","type":"text"}],"id":"b9c2eac2-f9c9-4e22-a90b-6b84bc6cba6d","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Practice Exercise 9","type":"text"}],"id":"83787d9f-55fe-42d5-af89-230232b63014","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# customers: id, name, country\n# orders: order_id, customer_id, amount, date\n# 1. Inner join to get orders with customer name\n# 2. Left anti join to find customers with no orders\n# 3. After joining, compute total amount per customer name\n# 4. Redo the inner join using broadcast (customers is small)","type":"text"}],"id":"1ea32cff-7ef8-44ac-9a6f-2646a3a14fad","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"ad3a5c40-b1b2-4d36-ad08-ba7d1d58c2a1","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"SECTION 10 — Handling Nulls in PySpark","type":"text"}],"id":"1e1fb029-0fd1-4fdf-95c4-dec8e81cf391","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# Drop rows with any null\ndf.dropna().show()\n\n# Drop rows where specific columns are null\ndf.dropna(subset=[\"amount\", \"date\"]).show()\n\n# Drop rows where ALL columns are null\ndf.dropna(how=\"all\").show()\n\n# Fill all nulls with a single value\ndf.fillna(0).show()\n\n# Fill nulls per column\ndf.fillna({\"amount\": 0, \"region\": \"UNKNOWN\"}).show()\n\n# Conditional fill using when/otherwise\ndf = df.withColumn(\"amount\",\n    F.when(F.col(\"amount\").isNull(), 0).otherwise(F.col(\"amount\"))\n)\n\n# Fill with column mean (two-step: compute mean, then fill)\nmean_amount = df.select(F.avg(\"amount\")).first()[0]\ndf = df.fillna({\"amount\": mean_amount})\n\n# Replace specific bad values with null\nfrom pyspark.sql.functions import when, col\ndf = df.withColumn(\"amount\",\n    F.when(F.col(\"amount\") < 0, None).otherwise(F.col(\"amount\"))\n)","type":"text"}],"id":"ce8d4070-6e91-4f58-a93b-5b02ec53bdfc","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Practice Exercise 10","type":"text"}],"id":"ff99ad3c-8d3e-44ee-9c1e-9ac51c22c7ff","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# Given DataFrame with nulls in amount, region, date:\n# 1. Count nulls per column\n# 2. Drop rows where ''amount'' is null\n# 3. Fill null ''region'' with ''UNKNOWN''\n# 4. Replace negative amounts with null, then fill with 0\n# 5. Confirm no nulls remain","type":"text"}],"id":"fe89b38a-52ea-4d63-a978-4bcd7655293e","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"616b399f-407d-480b-8b59-2ca98cf94555","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"SECTION 11 — Deduplication","type":"text"}],"id":"cab37d0d-2d24-4646-a9ff-b2ffa0cdeaf0","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# Remove completely duplicate rows\ndf.distinct().show()\n\n# Deduplicate by specific columns — keep first occurrence\ndf.dropDuplicates([\"id\"]).show()\n\n# Deduplicate keeping the LATEST record (by updated_at)\nfrom pyspark.sql.window import Window\n\nwindow = Window.partitionBy(\"id\").orderBy(F.col(\"updated_at\").desc())\n\ndf_with_rank = df.withColumn(\"rank\", F.row_number().over(window))\ndf_deduped = df_with_rank.filter(F.col(\"rank\") == 1).drop(\"rank\")\ndf_deduped.show()","type":"text"}],"id":"5881370d-1c3b-4a3e-b232-2045a88d0ca8","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"This window-based dedup is the PySpark version of the same pattern from the Transform and pandas notes — the concept is identical, the syntax is different.","type":"text"}],"id":"b1260e31-2a16-4324-9948-c13fa5d10c4e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Interview explanation:","type":"text"},{"styles":{},"text":" ","type":"text"},{"styles":{"italic":true},"text":"\"I partition by the ID, order by updated_at descending, assign row numbers, then keep only rank 1 — which is the most recent record for each ID. This is the PySpark equivalent of SQL''s ROW_NUMBER() OVER (PARTITION BY id ORDER BY updated_at DESC).\"","type":"text"}],"id":"272ac2d6-7017-4c9c-9218-8315370de278","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Practice Exercise 11","type":"text"}],"id":"d986e073-cb2d-46e0-93fe-b9278b1eab61","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# Given DataFrame with duplicate ids (same id, different updated_at):\n# 1. Show how many duplicates exist using dropDuplicates vs original count\n# 2. Deduplicate keeping the latest record using window + row_number\n# 3. Confirm each id appears exactly once","type":"text"}],"id":"13c70781-a65e-4931-84d6-bda644d33203","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"72be5b47-f1eb-4f6f-b8b2-2ce906477063","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"SECTION 12 — Window Functions (SQL Window Functions in PySpark)","type":"text"}],"id":"f9d04775-7a8c-452b-add7-674a0c74e365","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The most powerful and most tested advanced PySpark concept","type":"text"}],"id":"f913b3a5-99f7-4d93-b23e-90c33f22311c","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Setting up a window","type":"text"}],"id":"2a139b30-cc35-40e1-b171-9ee24eb10b81","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"from pyspark.sql.window import Window\nfrom pyspark.sql import functions as F\n\n# PARTITION BY region ORDER BY amount DESC\nwindow = Window.partitionBy(\"region\").orderBy(F.col(\"amount\").desc())\n\n# PARTITION BY region (no order — for aggregations over a partition)\nwindow_agg = Window.partitionBy(\"region\")\n\n# ORDER BY date (no partition — global ranking)\nwindow_global = Window.orderBy(\"date\")","type":"text"}],"id":"a56e3abc-5453-46a6-821c-79816fab1ffd","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Ranking functions","type":"text"}],"id":"698e7282-52f8-4561-8eff-f40ca97a00cd","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# ROW_NUMBER — unique rank per row (no ties)\ndf = df.withColumn(\"row_num\", F.row_number().over(window))\n\n# RANK — same rank for ties, skips numbers (1,1,3)\ndf = df.withColumn(\"rank\", F.rank().over(window))\n\n# DENSE_RANK — same rank for ties, no skips (1,1,2)\ndf = df.withColumn(\"dense_rank\", F.dense_rank().over(window))","type":"text"}],"id":"248949e3-3a80-466c-8c63-bc42e79ae0fa","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Aggregate over a window (running totals, etc.)","type":"text"}],"id":"d97ef7c5-8ce9-42fc-a3c5-b218b21e80bc","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# Running total within each region ordered by date\nwindow_running = Window.partitionBy(\"region\").orderBy(\"date\") \\\n    .rowsBetween(Window.unboundedPreceding, Window.currentRow)\n\ndf = df.withColumn(\"running_total\", F.sum(\"amount\").over(window_running))\n\n# Total for the entire partition (no order needed)\nwindow_total = Window.partitionBy(\"region\")\ndf = df.withColumn(\"region_total\", F.sum(\"amount\").over(window_total))\n\n# Percentage of partition total\ndf = df.withColumn(\"pct_of_region\",\n    (F.col(\"amount\") / F.sum(\"amount\").over(window_total) * 100).cast(\"double\")\n)","type":"text"}],"id":"3c0f5937-6351-48dd-8e0e-d8e547ef0ee7","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"LAG and LEAD — comparing to previous/next rows","type":"text"}],"id":"32454621-23af-47af-ad11-4c534b93d716","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# LAG — access previous row''s value\nwindow_lag = Window.partitionBy(\"region\").orderBy(\"date\")\ndf = df.withColumn(\"prev_amount\", F.lag(\"amount\", 1).over(window_lag))\ndf = df.withColumn(\"amount_change\", F.col(\"amount\") - F.col(\"prev_amount\"))\n\n# LEAD — access next row''s value\ndf = df.withColumn(\"next_amount\", F.lead(\"amount\", 1).over(window_lag))","type":"text"}],"id":"9f488528-ab4f-4e88-847d-dd69286f4715","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Classic interview use cases","type":"text"}],"id":"3bc59365-03ea-4f76-b6ab-b6ddd36d54a2","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# Top N per group — e.g. top 2 sales per region\nwindow = Window.partitionBy(\"region\").orderBy(F.col(\"amount\").desc())\ndf.withColumn(\"rank\", F.row_number().over(window)) \\\n  .filter(F.col(\"rank\") <= 2) \\\n  .drop(\"rank\") \\\n  .show()\n\n# Running total per region\nwindow = Window.partitionBy(\"region\").orderBy(\"date\") \\\n    .rowsBetween(Window.unboundedPreceding, Window.currentRow)\ndf.withColumn(\"running_total\", F.sum(\"amount\").over(window)).show()\n\n# Month-over-month change\nwindow = Window.partitionBy(\"region\").orderBy(\"month\")\ndf.withColumn(\"prev_month_amount\", F.lag(\"amount\", 1).over(window)) \\\n  .withColumn(\"mom_change\", F.col(\"amount\") - F.col(\"prev_month_amount\")) \\\n  .show()","type":"text"}],"id":"daf1fd0f-3283-406c-9be2-6be45b955e9e","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Practice Exercise 12","type":"text"}],"id":"363c81a6-42f0-421b-8692-10438092dd79","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# Given sales DataFrame (id, region, amount, date):\n# 1. Add row number within each region ordered by amount desc\n# 2. Find the top 2 sales per region\n# 3. Add running total of amount per region ordered by date\n# 4. Add ''prev_amount'' = previous row''s amount within each region\n# 5. Add ''pct_of_region'' = each row''s amount as % of its region''s total","type":"text"}],"id":"4ca05dcf-a086-4448-9f53-ff1b9709e519","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"af87029c-87e9-480b-b4e7-e30fc54efa79","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"SECTION 13 — UDFs (User Defined Functions)","type":"text"}],"id":"a4993a2a-2785-4d36-9934-dd9876fa9ee7","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"When to use UDFs","type":"text"}],"id":"43b2b35c-11d1-4fdc-866f-72c40403d795","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Only when you ","type":"text"},{"styles":{"bold":true},"text":"cannot","type":"text"},{"styles":{},"text":" express your logic using built-in F. functions. UDFs are Python functions — Spark must serialize data, call Python, and deserialize results. Much slower than native functions.","type":"text"}],"id":"8ea7e520-bc6d-47a5-af79-2656e8cade5a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"from pyspark.sql.functions import udf\nfrom pyspark.sql.types import StringType, DoubleType\n\n# Define your Python function\ndef categorize(amount):\n    if amount is None:\n        return \"unknown\"\n    if amount > 500:\n        return \"premium\"\n    if amount > 100:\n        return \"standard\"\n    return \"basic\"\n\n# Register it as a UDF\ncategorize_udf = udf(categorize, StringType())\n\n# Use it\ndf = df.withColumn(\"category\", categorize_udf(F.col(\"amount\")))","type":"text"}],"id":"4c61a78c-3091-4b27-a34b-207e87389fcc","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Decorator syntax (cleaner)","type":"text"}],"id":"48b8c94c-61c1-4cd2-9ed8-38e4c22713e1","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"@udf(returnType=StringType())\ndef categorize(amount):\n    if amount is None:\n        return \"unknown\"\n    if amount > 500: return \"premium\"\n    if amount > 100: return \"standard\"\n    return \"basic\"\n\ndf = df.withColumn(\"category\", categorize(F.col(\"amount\")))","type":"text"}],"id":"a48ac587-6fac-40d0-b19b-1e76a3fb719e","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Pandas UDF (Vectorized UDF) — much faster than regular UDF","type":"text"}],"id":"1f07b58a-5cc2-41c1-85db-cde53a9713cf","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"from pyspark.sql.functions import pandas_udf\nimport pandas as pd\n\n@pandas_udf(DoubleType())\ndef apply_tax(amount: pd.Series) -> pd.Series:\n    return amount * 1.05\n\ndf = df.withColumn(\"amount_with_tax\", apply_tax(F.col(\"amount\")))","type":"text"}],"id":"55d674e4-6b59-40e0-b9c5-c2dbdfedbd4c","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why Pandas UDF is faster:","type":"text"},{"styles":{},"text":" Regular UDFs process one row at a time in Python. Pandas UDFs receive an entire partition as a pandas Series/DataFrame, apply vectorized operations, and return. Far less Python-Spark serialization overhead.","type":"text"}],"id":"6317f2e9-9f85-4f83-8e5f-f0502591d51b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Interview warning to always mention","type":"text"}],"id":"c672be8c-d353-4610-b7d0-f41d4c89e115","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"I try to avoid UDFs and express logic using built-in F. functions wherever possible — they run in the JVM and are optimized by Catalyst. UDFs break out of JVM into Python which is much slower. If I must use a custom function, I prefer Pandas UDFs over regular UDFs for better performance.\"","type":"text"}],"id":"43809eb2-d9af-4682-a86d-6b6773129c42","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Practice Exercise 13","type":"text"}],"id":"ed3f9ad9-65fe-4c97-a871-98745f61ed17","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# 1. Write a regular UDF that takes a region string and returns a country code\n#    (''South'' -> ''IN'', ''North'' -> ''US'', ''East'' -> ''JP'', else ''UNKNOWN'')\n# 2. Apply it to your sales DataFrame\n# 3. Rewrite it as a Pandas UDF\n# 4. Rewrite it AGAIN using only F.when().when().otherwise() — no UDF\n# 5. Explain why option 4 is the best approach","type":"text"}],"id":"41953c5b-8795-4d87-ae41-68fb8e5c8c6f","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"a3208e87-d25c-4032-aa57-069ec40090e4","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"SECTION 14 — Writing Data Out","type":"text"}],"id":"4c3465a4-46af-43af-9172-07942d7d0c32","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# CSV — one file per partition (use coalesce to control output file count)\ndf.coalesce(1).write.mode(\"overwrite\").option(\"header\", True).csv(\"output/sales/\")\n\n# Parquet — preferred format\ndf.write.mode(\"overwrite\").parquet(\"output/sales.parquet\")\n\n# Partitioned write — creates year=2024/month=1/ folder structure\ndf.write.mode(\"overwrite\") \\\n  .partitionBy(\"year\", \"month\") \\\n  .parquet(\"output/sales_partitioned/\")\n\n# JSON\ndf.write.mode(\"overwrite\").json(\"output/sales/\")\n\n# Append mode\ndf.write.mode(\"append\").parquet(\"output/sales.parquet\")\n\n# Write modes\n# \"overwrite\" — replace existing data completely\n# \"append\"    — add to existing data\n# \"ignore\"    — do nothing if data exists\n# \"error\"     — raise error if data exists (default)","type":"text"}],"id":"1b7194b0-9e7d-4489-b1da-6cd61f603665","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Writing to a database (JDBC)","type":"text"}],"id":"22cdd6df-8429-48ba-a4a6-e9a1dfef0e82","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"df.write \\\n  .format(\"jdbc\") \\\n  .option(\"url\", \"jdbc:postgresql://host/dbname\") \\\n  .option(\"dbtable\", \"sales\") \\\n  .option(\"user\", \"username\") \\\n  .option(\"password\", \"password\") \\\n  .mode(\"append\") \\\n  .save()","type":"text"}],"id":"26a996e5-1590-4862-8eba-6b700872b483","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Practice Exercise 14","type":"text"}],"id":"395a9571-78d6-49ba-a616-5909343dd4e5","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# 1. Write your cleaned sales DataFrame to Parquet (overwrite mode)\n# 2. Read it back and confirm row count matches\n# 3. Write partitioned by year and month\n# 4. Read only the year=2024 partition back\n# 5. Write as CSV with coalesce(1) so only one output file is created","type":"text"}],"id":"7190c485-acf0-4871-a7db-ab1d1201071e","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"d9f114d9-9e45-4814-8165-566b32dbdf21","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"SECTION 15 — Performance Optimization Patterns","type":"text"}],"id":"f2d30b71-2e09-48f5-9852-59b7810c6742","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Pattern 1 — Filter early, filter often","type":"text"}],"id":"cd0c1dcc-28e2-47bb-ad90-eee4e71644ed","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# BAD: join everything then filter\nresult = orders.join(customers, on=\"id\").filter(F.col(\"amount\") > 1000)\n\n# GOOD: filter before join to reduce shuffle data size\nresult = orders.filter(F.col(\"amount\") > 1000).join(customers, on=\"id\")","type":"text"}],"id":"3747d2ba-5151-472e-9544-74867554b82e","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Pattern 2 — Select only needed columns before joins","type":"text"}],"id":"cc90d428-a112-4571-9f23-de143f43d403","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# BAD: join all columns, then drop later\nresult = orders.join(customers, on=\"id\")\n\n# GOOD: take only needed columns before join — less data shuffled\norders_slim = orders.select(\"id\", \"amount\", \"date\")\ncustomers_slim = customers.select(\"id\", \"name\")\nresult = orders_slim.join(customers_slim, on=\"id\")","type":"text"}],"id":"aa642944-fd25-451d-9772-d7fd10a2da4a","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Pattern 3 — Cache reused DataFrames","type":"text"}],"id":"643233f4-0bc9-4a83-a5b4-673bdea15e13","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"df_clean = df.filter(F.col(\"amount\") > 0).withColumn(\"tax\", F.col(\"amount\") * 0.1)\ndf_clean.cache()\n\nresult1 = df_clean.groupBy(\"region\").sum(\"amount\")\nresult2 = df_clean.orderBy(\"amount\").limit(10)\n\ndf_clean.unpersist()","type":"text"}],"id":"e71f8747-8192-4e9b-81d5-8607e4c2c437","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Pattern 4 — Avoid UDFs (covered in Section 13)","type":"text"}],"id":"d05c8f88-caa4-4c3a-9732-26498b009c04","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Pattern 5 — Control shuffle partitions","type":"text"}],"id":"b8d1ded0-a2e1-43f1-839a-f215ae1d6224","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# Default is 200 — too many for small data (overhead), too few for huge data\nspark.conf.set(\"spark.sql.shuffle.partitions\", \"50\")   # tune for your data size","type":"text"}],"id":"22af31b1-c32f-4320-9697-7021d393481a","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Pattern 6 — Use broadcast for small lookup tables","type":"text"}],"id":"ec660524-838a-4e92-8240-0b2559858d2d","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"df.join(broadcast(small_lookup_df), on=\"region\", how=\"left\")","type":"text"}],"id":"d62d5c2c-d1cd-4edf-8af5-002fa2a3bc17","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Pattern 7 — Avoid collect() on large DataFrames","type":"text"}],"id":"41484e56-f68c-4571-bc8e-141af0bd8ca1","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# DANGEROUS on big data — brings all rows to Driver\nall_rows = df.collect()\n\n# SAFE alternatives\ndf.show(20)              # just see a sample\ndf.write.parquet(...)    # write to storage instead\ndf.limit(100).toPandas() # bring only a small sample to pandas","type":"text"}],"id":"0113aa5d-9940-406f-917f-1bf75989ae08","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"1f0768a0-af20-4cfb-915f-f77a5125a075","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"SECTION 16 — SQL Interface (Spark SQL)","type":"text"}],"id":"582947da-7d33-44e7-bcbd-e013c29d82e9","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Why this matters","type":"text"}],"id":"2a2c5f06-ae9e-4e72-b908-19f5e18037d2","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"PySpark lets you write actual SQL on DataFrames — sometimes cleaner than chaining transformations, and essential when working with analysts who know SQL.","type":"text"}],"id":"f03abcbf-ba1d-4955-a4e4-2322c3bc33c7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"# Register DataFrame as a temporary view (like a SQL table)\ndf.createOrReplaceTempView(\"sales\")\n\n# Now query with pure SQL\nresult = spark.sql(\"\"\"\n    SELECT region,\n           SUM(amount) as total_amount,\n           COUNT(*) as order_count,\n           AVG(amount) as avg_amount\n    FROM sales\n    WHERE amount > 0\n    GROUP BY region\n    HAVING SUM(amount) > 500\n    ORDER BY total_amount DESC\n\"\"\")\nresult.show()\n\n# More complex SQL — window function\nspark.sql(\"\"\"\n    SELECT *,\n           ROW_NUMBER() OVER (PARTITION BY region ORDER BY amount DESC) as rank\n    FROM sales\n\"\"\").filter(F.col(\"rank\") <= 2).show()","type":"text"}],"id":"1e3bdad3-64b3-4ca4-92d8-33dc4a0937f7","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"When to use SQL vs DataFrame API","type":"text"}],"id":"74693884-f42a-46d3-99f1-81de22bb2b46","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Use SQL when","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Use DataFrame API when","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Logic is complex and SQL is clearer","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Building reusable functions/pipelines","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Working with analysts who write SQL","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Parameterized/dynamic logic","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Quick ad-hoc queries","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Type safety matters","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Porting existing SQL queries to Spark","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Chaining many operations","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"44d168d7-1be6-423b-a2da-c403690fd240","props":{"textColor":"default"},"type":"table"},{"children":[],"content":[{"styles":{},"text":"Practice Exercise 15","type":"text"}],"id":"5c47bba1-1e7f-4a0d-a061-4e476755d109","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"# Register your sales DataFrame as a view\n# Write SQL to:\n# 1. Total amount per region with order count\n# 2. Top 2 sales per region using window function SQL\n# 3. Regions where average amount > 200 (HAVING)\n# Then achieve the same results using the DataFrame API","type":"text"}],"id":"5205824c-9f38-494a-b754-4d0d34b6cea4","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"69f70ad9-0c65-4e95-87e2-24a4873251c5","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"🏗️ CAPSTONE PROJECT — The PySpark DE Pipeline","type":"text"}],"id":"e9d7f39b-47e9-441f-8777-c764073ec573","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Build this after completing all 15 practice exercises.","type":"text"}],"id":"e010b6c1-4c76-4934-9308-1f0fa78d11e1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"\"\"\"\nPySpark DE Pipeline\nScenario: Retail sales data from CSV, cleaned, aggregated, enriched,\nand written as partitioned Parquet — production-style.\n\"\"\"\n\nfrom pyspark.sql import SparkSession\nfrom pyspark.sql import functions as F\nfrom pyspark.sql.types import StructType, StructField, StringType, DoubleType\nfrom pyspark.sql.window import Window\nimport logging\n\nlogging.basicConfig(level=logging.INFO)\nlogger = logging.getLogger(\"pyspark_pipeline\")\n\n\n# ---------- SPARK SESSION ----------\ndef get_spark(app_name=\"RetailPipeline\"):\n    return SparkSession.builder \\\n        .appName(app_name) \\\n        .master(\"local[*]\") \\\n        .config(\"spark.sql.shuffle.partitions\", \"10\") \\\n        .getOrCreate()\n\n\n# ---------- SCHEMA ----------\nSALES_SCHEMA = StructType([\n    StructField(\"id\",         StringType(),  nullable=False),\n    StructField(\"region\",     StringType(),  nullable=True),\n    StructField(\"amount\",     DoubleType(),  nullable=True),\n    StructField(\"date\",       StringType(),  nullable=True),\n    StructField(\"updated_at\", StringType(),  nullable=True),\n])\n\n\n# ---------- EXTRACT ----------\ndef extract(spark, filepath):\n    logger.info(f\"Extracting from {filepath}\")\n    df = spark.read \\\n        .schema(SALES_SCHEMA) \\\n        .option(\"header\", True) \\\n        .option(\"nullValue\", \"\") \\\n        .csv(filepath)\n    logger.info(f\"Extracted {df.count()} raw records\")\n    return df\n\n\n# ---------- INSPECT ----------\ndef inspect(df, label=\"\"):\n    logger.info(f\"--- Inspect: {label} ---\")\n    df.printSchema()\n    logger.info(f\"Row count: {df.count()}\")\n    null_counts = df.select([\n        F.count(F.when(F.col(c).isNull(), c)).alias(c)\n        for c in df.columns\n    ])\n    null_counts.show()\n\n\n# ---------- TRANSFORM ----------\ndef clean(df):\n    logger.info(\"Cleaning...\")\n\n    df = df \\\n        .withColumn(\"region\", F.trim(F.initcap(F.col(\"region\")))) \\\n        .withColumn(\"region\", F.coalesce(F.col(\"region\"), F.lit(\"UNKNOWN\"))) \\\n        .withColumn(\"date\", F.to_date(F.col(\"date\"), \"yyyy-MM-dd\")) \\\n        .withColumn(\"amount\",\n            F.when(F.col(\"amount\").isNull() | (F.col(\"amount\") < 0), None)\n             .otherwise(F.col(\"amount\"))\n        )\n\n    # Drop rows missing critical fields\n    df = df.dropna(subset=[\"id\", \"amount\", \"date\"])\n\n    logger.info(f\"After cleaning: {df.count()} records\")\n    return df\n\n\ndef deduplicate(df):\n    logger.info(\"Deduplicating...\")\n\n    window = Window.partitionBy(\"id\").orderBy(F.col(\"updated_at\").desc())\n    df = df.withColumn(\"_rank\", F.row_number().over(window)) \\\n           .filter(F.col(\"_rank\") == 1) \\\n           .drop(\"_rank\")\n\n    logger.info(f\"After dedup: {df.count()} records\")\n    return df\n\n\ndef enrich(df):\n    logger.info(\"Enriching...\")\n\n    df = df \\\n        .withColumn(\"year\",  F.year(F.col(\"date\"))) \\\n        .withColumn(\"month\", F.month(F.col(\"date\"))) \\\n        .withColumn(\"category\",\n            F.when(F.col(\"amount\") > 500, \"premium\")\n             .when(F.col(\"amount\") > 100, \"standard\")\n             .otherwise(\"basic\")\n        ) \\\n        .withColumn(\"amount_usd\", F.round(F.col(\"amount\") * 0.0031, 4))\n\n    return df\n\n\ndef aggregate(df):\n    logger.info(\"Aggregating...\")\n\n    return df.groupBy(\"region\", \"year\", \"month\").agg(\n        F.sum(\"amount\").alias(\"total_amount\"),\n        F.count(\"*\").alias(\"order_count\"),\n        F.avg(\"amount\").alias(\"avg_amount\"),\n        F.max(\"amount\").alias(\"max_amount\"),\n        F.countDistinct(\"id\").alias(\"unique_orders\"),\n    ).orderBy(\"region\", \"year\", \"month\")\n\n\ndef add_window_metrics(df):\n    logger.info(\"Adding window metrics...\")\n\n    window_region = Window.partitionBy(\"region\").orderBy(\"year\", \"month\") \\\n        .rowsBetween(Window.unboundedPreceding, Window.currentRow)\n\n    window_pct = Window.partitionBy(\"region\", \"year\")\n\n    df = df \\\n        .withColumn(\"running_total\", F.sum(\"total_amount\").over(window_region)) \\\n        .withColumn(\"prev_month_total\", F.lag(\"total_amount\", 1).over(\n            Window.partitionBy(\"region\").orderBy(\"year\", \"month\")\n        )) \\\n        .withColumn(\"mom_change\",\n            F.col(\"total_amount\") - F.col(\"prev_month_total\")\n        ) \\\n        .withColumn(\"pct_of_year_total\",\n            F.round(\n                F.col(\"total_amount\") / F.sum(\"total_amount\").over(window_pct) * 100,\n                2\n            )\n        )\n\n    return df\n\n\n# ---------- LOAD ----------\ndef load_clean(df, output_path):\n    logger.info(f\"Writing clean records to {output_path}\")\n    df.write \\\n      .mode(\"overwrite\") \\\n      .partitionBy(\"year\", \"month\") \\\n      .parquet(output_path)\n    logger.info(\"Clean records written\")\n\n\ndef load_summary(df, output_path):\n    logger.info(f\"Writing summary to {output_path}\")\n    df.coalesce(1) \\\n      .write \\\n      .mode(\"overwrite\") \\\n      .option(\"header\", True) \\\n      .csv(output_path)\n    logger.info(\"Summary written\")\n\n\n# ---------- VERIFY ----------\ndef verify(spark, path, label):\n    df = spark.read.parquet(path) if path.endswith(\"parquet\") else \\\n         spark.read.option(\"header\", True).csv(path)\n    logger.info(f\"Verified {label}: {df.count()} rows\")\n    df.show(5)\n\n\n# ---------- PIPELINE ORCHESTRATOR ----------\ndef run(spark, input_path, clean_output, summary_output):\n    logger.info(\"=== PySpark DE Pipeline Started ===\")\n\n    # Extract\n    raw = extract(spark, input_path)\n    inspect(raw, \"Raw\")\n\n    # Transform\n    cleaned = clean(raw)\n    deduped = deduplicate(cleaned)\n    enriched = enrich(deduped)\n\n    # Cache enriched — used in both aggregate and direct write\n    enriched.cache()\n\n    # Aggregate\n    summary = aggregate(enriched)\n    summary_with_metrics = add_window_metrics(summary)\n\n    # Load\n    load_clean(enriched, clean_output)\n    load_summary(summary_with_metrics, summary_output)\n\n    # Release cache\n    enriched.unpersist()\n\n    logger.info(\"=== Pipeline Finished ===\")\n\n\n# ---------- SAMPLE DATA + ENTRY POINT ----------\ndef create_sample_csv():\n    import csv\n    rows = [\n        [\"id\", \"region\", \"amount\", \"date\", \"updated_at\"],\n        [\"S1\", \"south\",  \"250.50\", \"2024-01-15\", \"2024-01-15T10:00:00\"],\n        [\"S2\", \"North\",  \"150.00\", \"2024-01-20\", \"2024-01-20T11:00:00\"],\n        [\"S3\", \"east\",   \"\",       \"2024-01-10\", \"2024-01-10T09:00:00\"],\n        [\"S4\", \"West\",   \"-50\",    \"2024-01-05\", \"2024-01-05T08:00:00\"],\n        [\"S5\", \"South\",  \"600.00\", \"2024-02-01\", \"2024-02-01T12:00:00\"],\n        [\"S1\", \"South\",  \"275.00\", \"2024-01-15\", \"2024-01-16T09:00:00\"],\n        [\"S6\", \"North\",  \"450.00\", \"2024-02-10\", \"2024-02-10T14:00:00\"],\n        [\"S7\", \"East\",   \"320.00\", \"2024-02-15\", \"2024-02-15T10:00:00\"],\n    ]\n    with open(\"sales.csv\", \"w\", newline=\"\") as f:\n        csv.writer(f).writerows(rows)\n    print(\"Sample CSV created\")\n\n\nif __name__ == \"__main__\":\n    create_sample_csv()\n\n    spark = get_spark()\n\n    run(\n        spark=spark,\n        input_path=\"sales.csv\",\n        clean_output=\"output/clean.parquet\",\n        summary_output=\"output/summary/\",\n    )\n\n    spark.stop()","type":"text"}],"id":"5babf40f-9079-4a04-b948-64f5cec8777b","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"000425f2-9cde-4150-bc9f-57dfdb177cdc","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"🎤 Scenario-Based Interview Questions","type":"text"}],"id":"cba134e2-8263-4eba-a58b-000c7c810e0a","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"Write a PySpark script to read a CSV, filter rows where amount > 0, group by region and compute total sales.\"","type":"text"},{"styles":{},"text":" → Section 4 (read) + Section 5 (filter) + Section 8 (groupBy agg)","type":"text"}],"id":"ac8466f9-8ccd-4ca1-9762-43b75c96e9e1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"How do you remove duplicates in PySpark keeping the most recent record?\"","type":"text"},{"styles":{},"text":" → Window + row_number + filter rank == 1 (Section 11)","type":"text"}],"id":"c455bac3-6b81-4aa4-a0b7-7e19a01498f6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"How do you handle null values in a PySpark DataFrame?\"","type":"text"},{"styles":{},"text":" → dropna, fillna, when/otherwise, coalesce function (Section 10)","type":"text"}],"id":"25d54703-43a1-4baf-a6f7-4793794ac403","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"Write a window function to rank sales within each region.\"","type":"text"},{"styles":{},"text":" → Window.partitionBy().orderBy() + row_number (Section 12)","type":"text"}],"id":"d919dbdb-2784-4090-9182-3cd8c8befb9f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"What is a broadcast join and when would you use it?\"","type":"text"},{"styles":{},"text":" → Small table sent to all Executors, avoids shuffle, use when one side < 10MB (Section 9)","type":"text"}],"id":"0c9fca03-f835-4f40-9023-9152fabaa93a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"When would you use a UDF and what are the performance implications?\"","type":"text"},{"styles":{},"text":" → Only when F. functions can''t express the logic; UDFs break JVM/Python barrier and are slow; prefer Pandas UDFs (Section 13)","type":"text"}],"id":"209f1430-6d7a-448b-88c4-099507ffec4d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"How do you write partitioned Parquet output in PySpark?\"","type":"text"},{"styles":{},"text":" → ","type":"text"},{"styles":{"code":true},"text":"df.write.partitionBy(\"year\", \"month\").parquet(path)","type":"text"},{"styles":{},"text":" (Section 14)","type":"text"}],"id":"a4a7a88d-44cc-4f7b-9e88-0c8c0a2741cb","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"What does cache() do and when should you use it?\"","type":"text"},{"styles":{},"text":" → Stores DataFrame in memory after first computation; use when reused multiple times in same job; always unpersist when done (Architecture note + Section 15)","type":"text"}],"id":"f8cf8365-7c82-449a-bed5-3bed99fe211c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"How would you find the top 3 sales per region in PySpark?\"","type":"text"},{"styles":{},"text":" → Window.partitionBy(\"region\").orderBy(amount desc) + row_number + filter rank <= 3","type":"text"}],"id":"b552cd0f-45a9-4cc5-8a03-cdd5c7573e60","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"italic":true},"text":"\"Explain the difference between select and withColumn.\"","type":"text"},{"styles":{},"text":" → select chooses/transforms columns returning a new DataFrame with only selected columns; withColumn adds or replaces one column while keeping all others","type":"text"}],"id":"0c04470b-2032-48f4-b7c1-d10477dbefa0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"id":"e84688da-5e75-452f-9b18-6457284c83af","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"✅ Study & Practice Checklist","type":"text"}],"id":"0582705b-0478-4ee5-af48-b8704689facd","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Section 1 — SparkSession: write from memory every time (Practice Exercise 1)","type":"text"}],"id":"4632b814-a47c-4712-9fd2-1abb77aa379b","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Section 2 — Creating DataFrames with explicit schema (Practice Exercise 2)","type":"text"}],"id":"2d715283-6c5b-4ae3-9182-7d5b8210bb9d","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Section 3 — Inspection commands: write inspect() function (Practice Exercise 3)","type":"text"}],"id":"d4cb54f1-da5a-4552-9672-dcb5502e4647","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Section 4 — Reading CSV/JSON/Parquet (Practice Exercise 4)","type":"text"}],"id":"f45ac111-3e9a-4147-9c02-ab056c2c5795","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Section 5 — Select and filter: know all filter patterns (Practice Exercise 5)","type":"text"}],"id":"1ee461bd-f5f5-4e9e-90fe-16b2bc8de69b","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Section 6 — withColumn and F.when: the most used transformation (Practice Exercise 6)","type":"text"}],"id":"e669360b-5d7d-4add-b2f8-3c26f98e400a","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Section 7 — Built-in F. functions: string, date, numeric, null (Practice Exercise 7) — ","type":"text"},{"styles":{"bold":true},"text":"spend most time here","type":"text"}],"id":"93578652-a905-4340-8dc6-c6937dff7105","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Section 8 — GroupBy agg: multiple aggregations in one call (Practice Exercise 8)","type":"text"}],"id":"4e62bf68-68ac-4eb1-9c01-1f03a2d33710","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Section 9 — Joins: all join types + broadcast + duplicate column fix (Practice Exercise 9)","type":"text"}],"id":"03e54a38-4658-41f0-ae70-27153440d88e","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Section 10 — Null handling (Practice Exercise 10)","type":"text"}],"id":"5684c25a-14c8-4b2e-84aa-5b1d6ce453d1","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Section 11 — Deduplication with window (Practice Exercise 11)","type":"text"}],"id":"d45bc122-80f7-42f6-b1f6-894f3e234eac","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Section 12 — Window functions: ranking, running totals, lag/lead (Practice Exercise 12) — ","type":"text"},{"styles":{"bold":true},"text":"second most time","type":"text"}],"id":"aaf16559-9468-4e7e-b67b-f4f236281990","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Section 13 — UDFs: write one, then rewrite using F.when (Practice Exercise 13)","type":"text"}],"id":"85707c07-5885-417a-8609-5eb83a2a20c3","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Section 14 — Writing partitioned Parquet (Practice Exercise 14)","type":"text"}],"id":"bfe87a54-4140-4cb0-831b-82d5b009503d","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Section 15 — Performance patterns: read, understand, recite out loud","type":"text"}],"id":"bcc76421-88af-4f7c-be08-ae84e2cd2acf","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Section 16 — SQL interface: write same query both ways (Practice Exercise 15)","type":"text"}],"id":"c7750334-9824-41ea-8220-0f3a9f2fe7ad","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Build ","type":"text"},{"styles":{"bold":true},"text":"Capstone Pipeline","type":"text"},{"styles":{},"text":" from scratch, no copying","type":"text"}],"id":"9c476056-e72e-4797-8225-f4f977fc8bd7","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"content":[{"styles":{},"text":"Answer all 10 scenario questions out loud, unscripted","type":"text"}],"id":"67fd65a9-8361-438c-9c53-f90230731c33","props":{"backgroundColor":"default","checked":false,"textAlignment":"left","textColor":"default"},"type":"checkListItem"},{"children":[],"id":"c25c008e-1425-42a2-83e0-9579eb5443de","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"🔗 How Everything Connects","type":"text"}],"id":"0e3e0fe6-f2f2-4065-8653-410c31ac8003","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Spark Architecture Note\n└── WHY each PySpark operation behaves the way it does\n\nExtract Note (Python)\n└── Same concepts: generators = partitions, memory-safety = avoid collect()\n\nTransform Note (Python)\n└── Same concepts: dedupe, groupby, join — now in PySpark syntax\n\nPandas Note\n└── Same concepts: groupby, merge, apply — now distributed across a cluster\n\nLoad Note (Python)\n└── Same concepts: partitioned write = partitionBy(), idempotency = overwrite mode\n\nPySpark Note\n└── All of the above, running on a cluster at scale","type":"text"}],"id":"ce2c4b0e-c4f4-4f31-b7fd-4ed10f9f2972","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"You now have the complete, connected picture. Every note reinforces every other note. The concepts are the same — only the tool changes.","type":"text"}],"id":"e11e5976-7dc7-44a9-91e2-bcc111c0c064","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[],"id":"518681d3-6772-4bf0-86e3-4eb2bc79bf11","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"}]'::jsonb, '3e9e3dd3-a59b-4b02-968a-ee95e7317583') ON CONFLICT ("node_id") DO UPDATE SET "bad_example" = EXCLUDED."bad_example", "completed_at" = EXCLUDED."completed_at", "created_at" = EXCLUDED."created_at", "definition" = EXCLUDED."definition", "good_example" = EXCLUDED."good_example", "is_completed" = EXCLUDED."is_completed", "key_points" = EXCLUDED."key_points", "last_edited" = EXCLUDED."last_edited", "map_id" = EXCLUDED."map_id", "mental_model" = EXCLUDED."mental_model", "notes" = EXCLUDED."notes", "resources" = EXCLUDED."resources", "rich_content" = EXCLUDED."rich_content", "user_id" = EXCLUDED."user_id";
INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-09-10T10:33:40.517121+00:00', '', '', 'b9d4d307-4355-4398-8d48-7becbe6e7d18', false, '[]'::jsonb, '2026-09-10T10:33:42.582+00:00', 'ecc1046a-b3c9-4728-8417-64672cae5789', '', '531cd1b9-150e-4a79-8965-82ed1dba0a5e', '', '[]'::jsonb, '[{"children":[],"content":[{"styles":{},"text":"🤖 Post-Training Stage 1: Supervised Fine-Tuning (SFT) & LLM Psychology","type":"text"}],"id":"63eeea16-b283-4097-9a8f-d63f813cc4cd","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"A Complete Technical Guide Based on Karpathy''s \"Deep Dive into LLMs like ChatGPT\"","type":"text"}],"id":"1dd14830-da6d-46af-a811-b5b0026bbc3c","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"id":"3600e7ec-0007-48c4-8e44-ba5ca127d1d2","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"PART 1: THE MASTER MIND MAP","type":"text"}],"id":"6eef166b-183d-4888-9b3e-d7a4db35e02c","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"🤖 POST-TRAINING STAGE 1: SFT & LLM PSYCHOLOGY\n│\n├── 🔄 1. BASE MODEL TO ASSISTANT ALIGNMENT (SFT)\n│   ├── The Core Objective\n│   │   ├── Base Model: Autocomplete Engine (no inherent \"answering\")\n│   │   └── Assistant: Conversational, helpful, direct responder\n│   │\n│   ├── The Data Swap\n│   │   ├── OUT: Raw internet web crawl documents\n│   │   └── IN: Thousands/millions of curated multi-turn conversations\n│   │\n│   └── Compute Dynamics\n│       ├── Same architecture (Transformer)\n│       ├── Same algorithm (next-token prediction)\n│       ├── Pre-training: Months, trillions of tokens\n│       └── SFT: Hours/Days, much smaller curated dataset\n│\n├── 💬 2. DIALOGUE PROTOCOL & SPECIAL CONTROL TOKENS\n│   ├── 1D Sequence Encoding\n│   │   └── Multi-turn conversations flattened into single linear token stream\n│   │\n│   ├── Special Control Tokens (never seen in pre-training)\n│   │   ├── <|im_start|> (imaginary monologue / turn start)\n│   │   ├── <|im_end|> (turn end)\n│   │   ├── <|im_sep|> (role/content separator)\n│   │   └── Role labels: \"user\", \"assistant\", \"system\"\n│   │\n│   └── Runtime Inference Handoff\n│       ├── Server constructs prompt up to <|im_start|>assistant<|im_sep|>\n│       ├── Model samples tokens autoregressively\n│       └── Generation halts when <|im_end|> is emitted\n│\n├── ✍️ 3. DATASET CURATION & LABELER DYNAMICS\n│   ├── Human Labeling Workflows\n│   │   ├── InstructGPT (2022) methodology\n│   │   ├── Contractors via Upwork / Scale AI\n│   │   └── HTH Guidelines (Helpful, Truthful, Harmless)\n│   │\n│   ├── Modern Synthetic Generation\n│   │   ├── LLMs generate draft conversations\n│   │   ├── Humans edit/curate rather than write from scratch\n│   │   └── Example: UltraChat dataset\n│   │\n│   └── Core Mental Model\n│       └── SFT model = Statistical simulation of expert human labeler\n│\n├── 🧠 4. LLM PSYCHOLOGY, MEMORY SYSTEMS, & HALLUCINATIONS\n│   ├── Hallucination Origins\n│   │   ├── Confident style imitation regardless of factual knowledge\n│   │   └── Example: \"Who is Orson Kovats?\" → confabulated bio\n│   │\n│   ├── Knowledge Boundary Probing & Refusal Training\n│   │   ├── Interrogate model with multiple sampled queries\n│   │   ├── Use LLM judge to detect knowledge gaps\n│   │   └── Inject \"I don''t know\" examples into SFT data\n│   │\n│   ├── Memory Architecture\n│   │   ├── Parameter Weights = Long-term vague memory (lossy, compressed)\n│   │   └── Context Window = Working memory (precise, immediate)\n│   │       └── Pasting source text → dramatically improves accuracy\n│   │\n│   └── Identity & System Messages\n│       ├── No persistent self between conversations (stateless resets)\n│       └── Identity injected via hidden system prompt / hardcoded Q&A\n│\n├── 🛠️ 5. EXTERNAL TOOL INTEGRATION MECHANICS\n│   ├── Web Search\n│   │   ├── Model emits <search_start> query <search_end>\n│   │   ├── Inference pauses\n│   │   ├── Bing/Google API fetches results\n│   │   ├── Web text injected into context window\n│   │   └── Model cites sources in final answer\n│   │\n│   └── Python Code Interpreter\n│       ├── Model writes Python code block\n│       ├── Sandboxed interpreter executes code\n│       ├── stdout/result fed back into context\n│       └── Model uses exact result in final response\n│\n└── ⚡ 6. ARCHITECTURAL CONSTRAINTS & COGNITIVE QUIRKS\n    ├── Fixed Compute Per Token\n    │   └── Each forward pass = bounded computation, no \"thinking longer\"\n    │\n    ├── Distributing Reasoning Across Tokens\n    │   └── Chain-of-Thought / Scratchpads spread work over sequence length\n    │\n    ├── Tokenization Blind Spots\n    │   ├── BPE groups characters into opaque sub-word chunks\n    │   ├── Example: Counting ''r''s in \"strawberry\"\n    │   └── Example: Indexing letters in \"ubiquitous\"\n    │\n    └── Swiss-Cheese Capability Model\n        ├── Superhuman on PhD-level tasks\n        └── Fails on trivial edge cases\n            └── Example: \"9.11 > 9.9\" (Bible verse numbering pattern distraction)","type":"text"}],"id":"634f1e32-2c03-47ac-9d20-221fb442ead5","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"81cc020c-6fb7-40f8-9781-715b4ff94407","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"PART 2: STEP-BY-STEP TECHNICAL BLUEPRINT","type":"text"}],"id":"03ed28cd-25b5-4b76-a5d5-cc5c857d82b4","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"id":"b156caed-67f8-4824-a672-d09400080e5f","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"🔄 SECTION 1: Base Model to Assistant Alignment (SFT)","type":"text"}],"id":"a3dbe27e-9631-48ca-9983-61e97bd14302","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"1. Concept Overview","type":"text"}],"id":"45846cd9-a95b-4c3c-8cd2-08fc72a8f3a7","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Supervised Fine-Tuning (SFT) is the process by which a raw, pre-trained base model — which is fundamentally just a sophisticated internet-text autocomplete engine — is transformed into something that behaves like a helpful conversational assistant. Critically, Karpathy emphasizes that this transformation does ","type":"text"},{"styles":{"bold":true},"text":"not","type":"text"},{"styles":{},"text":" require inventing new architectures or new training algorithms. It requires changing the ","type":"text"},{"styles":{"bold":true},"text":"data","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"d7bd0620-9155-4ab2-bb19-03c568b69c95","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"2. Why It Is Needed","type":"text"}],"id":"c6d749bb-912c-4f74-9075-97d9d180cb65","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"A base model, as established in pre-training, has no concept of \"answering a question\" as distinct from \"continuing a document.\" If you prompt a base model with ","type":"text"},{"styles":{"code":true},"text":"\"What is 2+2?\"","type":"text"},{"styles":{},"text":", it doesn''t necessarily produce ","type":"text"},{"styles":{"code":true},"text":"\"4\"","type":"text"},{"styles":{},"text":" — because in its training data, a line like \"What is 2+2?\" might frequently be followed by ","type":"text"},{"styles":{"italic":true},"text":"another similar-looking question","type":"text"},{"styles":{},"text":", such as ","type":"text"},{"styles":{"code":true},"text":"\"What is 3+3?\"","type":"text"},{"styles":{},"text":", if that pattern resembles a worksheet, quiz, or FAQ list the model saw during training. The base model is simply predicting what token statistically follows in documents that look like this — and there''s no guarantee that \"looks like a direct answer\" is the statistically dominant continuation.","type":"text"}],"id":"0a5d3ba6-ff29-4f3a-9f2d-0e695f6dc716","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"This reveals the core problem: ","type":"text"},{"styles":{"bold":true},"text":"the base model has never been taught the ","type":"text"},{"styles":{"bold":true,"italic":true},"text":"behavioral pattern","type":"text"},{"styles":{"bold":true},"text":" of being a direct, helpful responder to questions.","type":"text"},{"styles":{},"text":" It has knowledge and language capability baked into its weights, but no orientation toward \"assistant\" behavior. SFT solves this by exposing the model to many examples of exactly the desired behavior pattern.","type":"text"}],"id":"dccd148b-9f15-47f8-83c8-06eb96bc68ae","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"3. How It Works Step-by-Step","type":"text"}],"id":"7feff9a6-4eae-40d7-a4c3-afb26d8ee467","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Start with the trained base model","type":"text"},{"styles":{},"text":": Take the fully pre-trained model (architecture + weights) exactly as produced at the end of pre-training — no architectural changes are made.","type":"text"}],"id":"fddef370-6ab0-4170-be83-a8b822f57f9f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"The Data Swap","type":"text"},{"styles":{},"text":": Instead of continuing to train on scraped internet documents (Common Crawl, FineWeb, etc.), swap the training dataset entirely for a curated collection of ","type":"text"},{"styles":{"bold":true},"text":"multi-turn conversations","type":"text"},{"styles":{},"text":" — records of a \"user\" asking things and an \"assistant\" responding helpfully, truthfully, and appropriately. This dataset consists of thousands to millions of such conversational examples (far smaller in raw token count than the pre-training corpus, but much higher in \"behavioral density\" per token).","type":"text"}],"id":"d40a495f-9a44-47a7-b38c-0302a9afa820","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Apply the Same Algorithm","type":"text"},{"styles":{},"text":": Run the identical next-token prediction training procedure used in pre-training (forward pass → compute loss → backpropagate → update weights) — but now training on this conversational data instead of web text. The model is literally still just learning to predict the next token; the only thing that''s changed is ","type":"text"},{"styles":{"italic":true},"text":"what kind of text it''s learning to predict.","type":"text"}],"id":"cb4c9643-a4a2-4af0-bbd4-b9d805c3fe12","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Shorter Compute Budget","type":"text"},{"styles":{},"text":": Because the SFT dataset is vastly smaller than the pre-training corpus, and the model already possesses the vast majority of its language ability and world knowledge from pre-training, this stage requires only ","type":"text"},{"styles":{"bold":true},"text":"hours to days","type":"text"},{"styles":{},"text":" of compute — a tiny fraction of the ","type":"text"},{"styles":{"bold":true},"text":"months","type":"text"},{"styles":{},"text":" required for pre-training.","type":"text"}],"id":"5ed5c1d9-18ae-410a-9114-9b9457cfadf6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Resulting Behavior Shift","type":"text"},{"styles":{},"text":": After SFT, when prompted with ","type":"text"},{"styles":{"code":true},"text":"\"What is 2+2?\"","type":"text"},{"styles":{},"text":", the model''s learned statistical patterns from the conversational dataset now dominate its behavior — it recognizes the \"shape\" of a question needing a direct answer and responds ","type":"text"},{"styles":{"code":true},"text":"\"2+2 is 4\"","type":"text"},{"styles":{},"text":" rather than generating another unrelated question.","type":"text"}],"id":"000c2816-2e07-4389-a60e-26e7c8070fc8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"4. Concrete Lecture Examples","type":"text"}],"id":"3f9a6517-253b-46db-925a-6572fd49f677","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Karpathy''s explicit example: prompting a ","type":"text"},{"styles":{"bold":true},"text":"base model","type":"text"},{"styles":{},"text":" with ","type":"text"},{"styles":{"code":true},"text":"\"What is 2+2?\"","type":"text"},{"styles":{},"text":" can result in the nonsensical continuation ","type":"text"},{"styles":{"code":true},"text":"\"What is 3+3?\"","type":"text"},{"styles":{},"text":" — because the base model is pattern-matching against internet documents (e.g., worksheets, trivia lists) where sequential similar questions are common, rather than \"understanding\" that a direct answer is expected.","type":"text"}],"id":"aae095a4-4b34-4d00-8c1e-496732c18183","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"After SFT, the exact same underlying network, now trained on curated dialogue, will respond to ","type":"text"},{"styles":{"code":true},"text":"\"What is 2+2?\"","type":"text"},{"styles":{},"text":" with something like ","type":"text"},{"styles":{"code":true},"text":"\"2+2 is 4\"","type":"text"},{"styles":{},"text":" — demonstrating that the ","type":"text"},{"styles":{"italic":true},"text":"only","type":"text"},{"styles":{},"text":" thing that changed was the training data distribution, not the model''s fundamental computational machinery.","type":"text"}],"id":"406eef03-f1b9-4424-96f0-8036b2249158","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"5. Key Transitions","type":"text"}],"id":"46cdc443-62d1-439f-97e5-6c53d4269902","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Now that we understand ","type":"text"},{"styles":{"italic":true},"text":"why","type":"text"},{"styles":{},"text":" the data must change and ","type":"text"},{"styles":{"italic":true},"text":"what kind","type":"text"},{"styles":{},"text":" of data (conversations) must replace web text, the natural next question is: ","type":"text"},{"styles":{"bold":true},"text":"how, mechanically, do you represent a multi-turn conversation — with distinct roles like \"user\" and \"assistant\" — as a flat sequence of tokens that a Transformer (which only knows how to predict the next token in a 1D sequence) can be trained on?","type":"text"},{"styles":{},"text":" This leads directly into ","type":"text"},{"styles":{"bold":true},"text":"Section 2: Dialogue Protocol & Special Control Tokens.","type":"text"}],"id":"4bd69169-c1b5-4d99-b4cf-4ae3242f4fb5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"3cd68304-436d-4e99-8c35-0a81c44b9a36","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"💬 SECTION 2: Dialogue Protocol & Special Control Tokens","type":"text"}],"id":"755990dd-c5fa-4572-882d-6630faf16c52","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"1. Concept Overview","type":"text"}],"id":"c2cd67f8-3e7d-40d1-8959-f0e8586257c9","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Since a Transformer only ever processes a single flat 1-dimensional sequence of tokens (as established in pre-training), a structured, multi-turn, multi-role conversation (user says X, assistant says Y, user says Z...) must be ","type":"text"},{"styles":{"bold":true},"text":"serialized","type":"text"},{"styles":{},"text":" into that same 1D format. This requires a formal protocol using specially designated tokens that mark conversational structure — turn boundaries, speaker roles, and content separators.","type":"text"}],"id":"ef21a0fa-8c55-440c-85a9-2a5f372f082d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"2. Why It Is Needed","type":"text"}],"id":"87756161-4fae-4b94-9b3d-dea7cb5e1add","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Without special structural markers, the model would have no way to distinguish \"this text was said by the user\" from \"this text was said by the assistant\" from \"this text is a system instruction.\" Since the model''s ","type":"text"},{"styles":{"italic":true},"text":"only","type":"text"},{"styles":{},"text":" mechanism for processing information is a flat sequence of token IDs, the structure of a conversation must be ","type":"text"},{"styles":{"bold":true},"text":"encoded directly into the token stream itself","type":"text"},{"styles":{},"text":" using tokens reserved specifically for this purpose — tokens that were deliberately ","type":"text"},{"styles":{"bold":true},"text":"never used during pre-training","type":"text"},{"styles":{},"text":" so they carry an unambiguous, exclusive meaning as structural/control markers rather than natural language content.","type":"text"}],"id":"854771bc-a850-4d76-9462-fea214b31f61","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"3. How It Works Step-by-Step","type":"text"}],"id":"95ad4206-da07-4b97-b4cb-1eb3c139c394","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[{"children":[],"content":[{"styles":{"code":true},"text":"<|im_start|>","type":"text"},{"styles":{},"text":" — marks the beginning of a new \"turn\" (im = \"imaginary monologue,\" referencing the internal convention used to denote a turn boundary).","type":"text"}],"id":"b6b6355f-508e-4205-8a40-b44c8ceb0b46","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"code":true},"text":"<|im_sep|>","type":"text"},{"styles":{},"text":" — separates the role label from the actual message content within a turn.","type":"text"}],"id":"509b3918-0e7c-479e-b5e4-bfcc9c4f8b10","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"code":true},"text":"<|im_end|>","type":"text"},{"styles":{},"text":" — marks the end of a turn''s content.","type":"text"}],"id":"9f3f0d0f-3a9f-4367-9635-ba8fd95c9aa5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Role labels such as ","type":"text"},{"styles":{"code":true},"text":"user","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"assistant","type":"text"},{"styles":{},"text":", and ","type":"text"},{"styles":{"code":true},"text":"system","type":"text"},{"styles":{},"text":" — plain-text-like tokens indicating who is \"speaking\" in this turn.","type":"text"}],"id":"84512341-6b82-466c-9025-5665e7461e93","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"}],"content":[{"styles":{"bold":true},"text":"Reserve Special Tokens","type":"text"},{"styles":{},"text":": A set of new token IDs is added to the tokenizer''s vocabulary specifically for dialogue structuring. These are never present in ordinary text and thus never appear in pre-training data — they are introduced fresh at the SFT stage. Key tokens include:","type":"text"}],"id":"ca42035e-3084-47bb-ac22-3d15d4a1e25d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[{"children":[],"content":[{"styles":{},"text":"User asks: \"What is 2+2?\"","type":"text"}],"id":"290297a6-8d62-4c63-b710-d62fab4eb615","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Assistant answers: \"2+2 is 4\"","type":"text"}],"id":"54ad4c2a-7447-4171-8d0b-21f2bad26cca","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"}],"content":[{"styles":{"bold":true},"text":"Serialize the Conversation","type":"text"},{"styles":{},"text":": A full multi-turn exchange is flattened into a single linear sequence following a fixed template pattern. For example, the conversation:","type":"text"}],"id":"fa1d13e3-aaab-48cc-997f-ae483cb8872c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Is encoded as the literal token sequence:","type":"text"}],"id":"7b9ece2b-527a-4192-9a9a-8870faea75bc","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"<|im_start|> user <|im_sep|> What is 2+2? <|im_end|> <|im_start|> assistant <|im_sep|> 2+2 is 4 <|im_end|>","type":"text"}],"id":"b451c3db-c6da-4d1b-b479-98477765fbdf","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"This entire string — control tokens included — is tokenized and fed to the model as one continuous sequence during SFT training, and the model is trained (via the same next-token prediction objective) to predict each subsequent token in this structured sequence, including learning ","type":"text"},{"styles":{"bold":true},"text":"when","type":"text"},{"styles":{},"text":" to emit ","type":"text"},{"styles":{"code":true},"text":"<|im_end|>","type":"text"},{"styles":{},"text":" to properly terminate its turn.","type":"text"}],"id":"5dfda2a6-d094-4bfb-aef0-080f5ebfe0f0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[{"children":[],"content":[{"styles":{},"text":"The serving infrastructure automatically constructs the prompt by wrapping the user''s raw input in the proper control-token template, ending with ","type":"text"},{"styles":{"code":true},"text":"<|im_start|> assistant <|im_sep|>","type":"text"},{"styles":{},"text":" — this is the exact point where the model''s ","type":"text"},{"styles":{"italic":true},"text":"own","type":"text"},{"styles":{},"text":" generation should begin.","type":"text"}],"id":"0690a5eb-a176-4338-a7f9-9e1b51f8410b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"The model then autoregressively samples tokens one at a time (exactly as described in the pre-training inference mechanics), continuing to generate what \"the assistant\" would say.","type":"text"}],"id":"559356f8-bcda-4496-a37b-3cd6142c6fd7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Generation continues until the model itself samples/emits the ","type":"text"},{"styles":{"code":true},"text":"<|im_end|>","type":"text"},{"styles":{},"text":" token, at which point the serving system recognizes this as the signal to ","type":"text"},{"styles":{"bold":true},"text":"stop generating","type":"text"},{"styles":{},"text":" and hand control back to the user for the next turn.","type":"text"}],"id":"9966856a-d0a6-4179-9dd7-9e7f49c62806","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"}],"content":[{"styles":{"bold":true},"text":"Runtime Inference Handoff","type":"text"},{"styles":{},"text":": At actual deployment/inference time, when a user submits a query through a chat interface:","type":"text"}],"id":"67efb371-462e-4394-b98f-d5194acd5be1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"4. Concrete Lecture Examples","type":"text"}],"id":"730e3fc1-a191-452b-a7d4-b025d66aee1b","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[{"children":[],"content":[{"styles":{},"text":"<|im_start|>user<|im_sep|>What is 2+2?<|im_end|><|im_start|>assistant<|im_sep|>2+2 is 4<|im_end|>","type":"text"}],"id":"86b63215-2d0a-41db-bf9d-0bdb2daf5e68","props":{"language":"python"},"type":"codeBlock"}],"content":[{"styles":{},"text":"The exact structural template Karpathy walks through:","type":"text"}],"id":"b267aca1-895e-4117-9f17-edd084aa6acb","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"He emphasizes that these tokens are ","type":"text"},{"styles":{"bold":true},"text":"architecturally identical in kind","type":"text"},{"styles":{},"text":" to ordinary vocabulary tokens (they get their own row in the embedding table, their own entries in the softmax output layer) — the only thing special about them is that they are ","type":"text"},{"styles":{"bold":true},"text":"reserved exclusively for structural signaling","type":"text"},{"styles":{},"text":" and were deliberately excluded from ever appearing in raw pre-training text, so their meaning is completely unambiguous to the model.","type":"text"}],"id":"0ebb689d-f3b8-4105-94ea-b603e926a711","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"5. Key Transitions","type":"text"}],"id":"1a93190a-2050-4ace-8373-9d5696e7eb09","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Now that we know exactly ","type":"text"},{"styles":{"italic":true},"text":"how","type":"text"},{"styles":{},"text":" conversations are encoded as training sequences, the next essential question is: ","type":"text"},{"styles":{"bold":true},"text":"where does the actual content of these curated conversations come from?","type":"text"},{"styles":{},"text":" Someone (or something) had to write the thousands/millions of realistic, high-quality \"user asks / assistant responds\" examples used to train this behavior. This leads into ","type":"text"},{"styles":{"bold":true},"text":"Section 3: Dataset Curation & Labeler Dynamics.","type":"text"}],"id":"739e1bf2-8d79-4d6e-b0a4-d9d9b97328db","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"4e65a510-8d04-486c-8631-f77aa9b2e997","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"✍️ SECTION 3: Dataset Curation & Labeler Dynamics","type":"text"}],"id":"6c18ada4-527a-4f79-ba1d-bdca4132a239","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"1. Concept Overview","type":"text"}],"id":"d75c01c2-2bde-46f0-afe4-1759088d6a6d","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"This section covers the human (and increasingly AI-assisted) process of actually creating the SFT training dataset — the curated conversations that teach the model how to behave as an assistant. Karpathy traces this from the original human-labor-intensive methodology (InstructGPT) to the modern hybrid/synthetic approach.","type":"text"}],"id":"6bf46f6c-185c-4f3e-9aa7-19530cef1efe","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"2. Why It Is Needed","type":"text"}],"id":"d9bda0a6-cc1d-4522-8910-e209fad93d87","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The quality, style, and values embedded in the SFT dataset become — quite directly — the personality and behavioral tendencies of the resulting assistant model. If the conversations are low-quality, inconsistent, or reflect bad practices (rudeness, unhelpfulness, factual carelessness), the trained model will statistically imitate those same flaws. Careful, guideline-driven curation is therefore essential to producing a model that is genuinely helpful, truthful, and harmless.","type":"text"}],"id":"dedb8efa-869e-4111-ac24-eb907ca16b95","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"3. How It Works Step-by-Step","type":"text"}],"id":"59384ad8-46c3-4ab6-a63a-9cf5f2fd7327","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Original Methodology (Human Labeling — InstructGPT, 2022):","type":"text"}],"id":"d37a6fa1-40d4-459c-b00b-3651fe69573a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Hire Human Labelers","type":"text"},{"styles":{},"text":": OpenAI''s InstructGPT paper (2022) — a direct methodological ancestor of ChatGPT — describes hiring human contractors through platforms like ","type":"text"},{"styles":{"bold":true},"text":"Upwork","type":"text"},{"styles":{},"text":" and specialized data-labeling companies like ","type":"text"},{"styles":{"bold":true},"text":"Scale AI","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"8b6a77b9-2e2b-45e2-9087-88a694b8e2bb","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[{"children":[],"content":[{"styles":{"bold":true},"text":"Helpful","type":"text"},{"styles":{},"text":" — genuinely assist the user in accomplishing their goal.","type":"text"}],"id":"71a1f12d-35af-458f-835c-502047e7510d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Truthful","type":"text"},{"styles":{},"text":" — provide factually accurate information, and avoid confidently stating falsehoods.","type":"text"}],"id":"63200b0c-2a88-4cb0-bc0f-29fda9483f61","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Harmless","type":"text"},{"styles":{},"text":" — refuse or carefully handle requests that could cause harm.","type":"text"}],"id":"09e74960-c692-430e-8f91-d3fd3423cadc","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"}],"content":[{"styles":{"bold":true},"text":"Provide Detailed Labeling Guidelines","type":"text"},{"styles":{},"text":": Labelers are given extensive documentation instructing them on how to write ideal assistant responses, organized around the ","type":"text"},{"styles":{"bold":true},"text":"HHH principle","type":"text"},{"styles":{},"text":":","type":"text"}],"id":"f9eca3eb-e870-4682-9b6f-ca1264473450","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Write Prompt-Response Pairs","type":"text"},{"styles":{},"text":": Labelers are given (or write) example user prompts, then compose the \"ideal\" assistant response by hand, following the guidelines. This is extremely labor-intensive — high-quality responses can take significant time to compose thoughtfully for each individual example.","type":"text"}],"id":"ed394174-eb21-4f49-8ec3-9ad05948251d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Aggregate into a Dataset","type":"text"},{"styles":{},"text":": Thousands of these hand-written prompt-response pairs (and multi-turn conversations) are compiled into the actual SFT training set.","type":"text"}],"id":"31aca344-5603-486e-96ca-151bc6c10ad6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Modern Methodology (Synthetic Generation & Hybrid Curation):","type":"text"}],"id":"82ee0cd0-93e8-4cc9-85c0-4f55268a79e2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"LLM-Assisted Drafting","type":"text"},{"styles":{},"text":": Rather than having humans write every response entirely from scratch, modern pipelines use existing capable LLMs to ","type":"text"},{"styles":{"bold":true},"text":"generate draft conversations","type":"text"},{"styles":{},"text":" at scale.","type":"text"}],"id":"f09f8735-e945-4ecb-8c8f-cd637087e8ec","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Human Editing Role Shift","type":"text"},{"styles":{},"text":": Human labelers'' role shifts from \"author\" to \"editor/curator\" — reviewing, correcting, and refining LLM-generated drafts, which is dramatically faster than writing everything manually.","type":"text"}],"id":"09ff81f0-7a81-48a9-a288-94743e5e03c6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Public Synthetic Datasets","type":"text"},{"styles":{},"text":": Datasets like ","type":"text"},{"styles":{"bold":true},"text":"UltraChat","type":"text"},{"styles":{},"text":" exemplify this modern approach — large-scale, largely synthetically generated (and subsequently filtered/curated) conversational datasets that are used as SFT training mixtures, blending many different conversation types, topics, and styles.","type":"text"}],"id":"d1570b8b-7b4e-4a0b-80a0-611a4f3fa633","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Mixture Composition","type":"text"},{"styles":{},"text":": Final SFT datasets are typically a ","type":"text"},{"styles":{"bold":true},"text":"mixture","type":"text"},{"styles":{},"text":" — combining human-authored high-quality examples, synthetically generated and human-edited examples, and specialized examples targeting specific behaviors (like refusals, safety edge cases, or tool use, covered later).","type":"text"}],"id":"318df6b1-78d0-4f70-b839-b2e19f622dcc","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"4. Concrete Lecture Examples","type":"text"}],"id":"7e63c3b9-de74-4e13-9ff3-06745b54b637","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"InstructGPT (2022)","type":"text"},{"styles":{},"text":" is cited explicitly as the foundational methodology paper describing this human-labeling pipeline, including the use of ","type":"text"},{"styles":{"bold":true},"text":"Upwork","type":"text"},{"styles":{},"text":" contractors and companies like ","type":"text"},{"styles":{"bold":true},"text":"Scale AI","type":"text"},{"styles":{},"text":" for large-scale annotation work.","type":"text"}],"id":"39a083b2-90e3-4f9f-a6a4-8f2c4d2282a2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"HTH (Helpful, Truthful, Harmless)","type":"text"},{"styles":{},"text":" guidelines are named explicitly as the rubric labelers are trained to follow.","type":"text"}],"id":"5b449b6d-2ed1-4ab6-ad7e-a5efa220f321","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"UltraChat","type":"text"},{"styles":{},"text":" is named as a concrete example of a modern, largely synthetically-generated open dataset used in SFT mixtures.","type":"text"}],"id":"272ccfd3-2a80-4baa-a2f6-ef1c616fdfe7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"5. Core Mental Model (Critical Conceptual Takeaway)","type":"text"}],"id":"bd8e2fa2-9f35-4e99-a6f4-a20c2b7fe554","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Karpathy offers a crucial reframing for how to intuitively understand what you''re interacting with when you chat with an SFT-trained assistant model:","type":"text"}],"id":"8550b227-5694-4d4f-8b5c-f388b12e3ba8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"You are not talking to a magical, all-knowing entity. You are talking to a statistical simulation of what an expert human labeler — trained on a company''s specific HTH guidelines — would write, if asked this exact question.","type":"text"}],"id":"9bb76406-44ed-4455-a009-372e060afa54","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"content":[{"styles":{},"text":"Every response the model generates is, in a deep sense, its learned approximation of \"what would the ideal labeler, following the guidelines they were trained on, have written here?\" This mental model is extremely useful for understanding both the ","type":"text"},{"styles":{"italic":true},"text":"capabilities","type":"text"},{"styles":{},"text":" and the ","type":"text"},{"styles":{"italic":true},"text":"idiosyncrasies","type":"text"},{"styles":{},"text":" of assistant behavior — including tone, hedging, refusal patterns, and formatting conventions — because all of these stem from patterns present in the human-curated (or human-edited) training examples.","type":"text"}],"id":"b4a8b728-09bc-4d97-980e-03b9ec1c734e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"6. Key Transitions","type":"text"}],"id":"712972ee-409f-4790-a10d-aed73eceae6b","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Understanding the model as \"a simulation of an expert labeler\" immediately raises a psychological question: ","type":"text"},{"styles":{"bold":true},"text":"what happens when the model is asked something the underlying base knowledge doesn''t actually contain?","type":"text"},{"styles":{},"text":" A human labeler, when they don''t know an answer, can say \"I don''t know\" — but does the model naturally do this, or does its \"simulate a confident labeler\" behavior cause problems? This leads into ","type":"text"},{"styles":{"bold":true},"text":"Section 4: LLM Psychology, Memory Systems, & Hallucinations.","type":"text"}],"id":"b145b22f-fb89-4dc8-bf0a-80620939ba84","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"a666eb98-07ab-4180-9125-ddfc70b8b3fa","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"🧠 SECTION 4: LLM Psychology, Memory Systems, & Hallucinations","type":"text"}],"id":"7003f499-98f2-4425-92e8-e22776852c7e","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"1. Concept Overview","type":"text"}],"id":"307e8eca-d564-4cf5-aa1b-62518bf33d12","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"This section explores the emergent \"psychological\" quirks of SFT-trained assistant models — particularly the phenomenon of ","type":"text"},{"styles":{"bold":true},"text":"hallucination","type":"text"},{"styles":{},"text":" (confidently stating false information), the techniques used to mitigate it, the two-tiered \"memory\" architecture of an LLM (parameters vs. context window), and the illusion of persistent identity across conversations.","type":"text"}],"id":"30db1500-2298-45a2-91f7-c14203bf8081","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"2. Why It Is Needed","type":"text"}],"id":"050b1e39-74bc-4a61-b1c6-2ca06fd614c3","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Because SFT trains the model to imitate the ","type":"text"},{"styles":{"italic":true},"text":"style","type":"text"},{"styles":{},"text":" of confident, helpful, complete answers (as modeled by human labelers who — when writing training examples — typically ","type":"text"},{"styles":{"italic":true},"text":"did","type":"text"},{"styles":{},"text":" know the answers to the questions they were given), the model learns a strong prior toward ","type":"text"},{"styles":{"bold":true},"text":"producing confident-sounding answers in that same style","type":"text"},{"styles":{},"text":", regardless of whether it actually possesses reliable knowledge about the specific query. This mismatch between \"style of confidence\" and \"actual underlying certainty\" is the root mechanical cause of hallucination — and must be explicitly addressed through additional training interventions.","type":"text"}],"id":"df894212-7dc9-403f-9276-76cc08eec512","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"3. How It Works Step-by-Step","type":"text"}],"id":"de5a5690-dfe1-4a20-9432-b2a4bb05a021","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"A. Hallucination Origins","type":"text"}],"id":"a8a5f0fd-08a6-4544-84eb-5009a576fdd0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Style Imitation Mechanism","type":"text"},{"styles":{},"text":": During SFT, the model learns \"when a user asks a factual question in this format, respond with a confident, well-structured, direct answer\" — because that''s the pattern present in nearly all of its human-labeled training examples (labelers were generally answering questions they actually knew about, or looked up).","type":"text"}],"id":"c722b111-6eb1-44c9-aa5a-94904353dc2b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Generalization Failure on Unknown Entities","type":"text"},{"styles":{},"text":": When later asked about something the model has genuinely never encountered or doesn''t have reliable information about — e.g., a fictional or obscure name — the model doesn''t have a built-in \"know that I don''t know\" signal. It simply applies the same learned response ","type":"text"},{"styles":{"italic":true},"text":"style","type":"text"},{"styles":{},"text":" (confident, biographical, detailed) to produce a plausible-sounding but entirely fabricated answer.","type":"text"}],"id":"b0b5a21a-ae8e-4397-8e20-f6ac1afcbed9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Concrete Example — \"Who is Orson Kovats?\"","type":"text"},{"styles":{},"text":": Karpathy uses this fabricated (or obscure) name as an example — when asked \"Who is Orson Kovats?\", a model prone to hallucination might confidently generate a fake biography (e.g., inventing a profession, nationality, or notable achievements) rather than acknowledging uncertainty, simply because the ","type":"text"},{"styles":{"italic":true},"text":"format","type":"text"},{"styles":{},"text":" of \"answer a biographical question confidently\" was reinforced during SFT, without corresponding training on ","type":"text"},{"styles":{"italic":true},"text":"when to withhold that confidence","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"f8753f0c-46ed-4c5c-9395-ef877e7296fe","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"B. Knowledge Boundary Probing & Refusal Training (The Fix)","type":"text"}],"id":"9769bd92-7efe-4558-a22b-cc4312549208","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Empirical Interrogation","type":"text"},{"styles":{},"text":": To fix this, model developers run ","type":"text"},{"styles":{"bold":true},"text":"systematic probing","type":"text"},{"styles":{},"text":" — querying the model (often the ","type":"text"},{"styles":{"italic":true},"text":"base","type":"text"},{"styles":{},"text":" model or an intermediate checkpoint) repeatedly with questions probing the edges of its knowledge, sometimes sampling multiple times at nonzero temperature to see how consistent or inconsistent the answers are across samples.","type":"text"}],"id":"e7a00dbe-d640-484c-b44c-8fa781a6e692","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"LLM-as-Judge","type":"text"},{"styles":{},"text":": An auxiliary LLM (or the same model in a different role) is used to ","type":"text"},{"styles":{"bold":true},"text":"automatically evaluate","type":"text"},{"styles":{},"text":" whether the sampled answers are actually correct or are hallucinated fabrications, comparing against known ground truth.","type":"text"}],"id":"99db4371-b48a-4de1-abd7-1d187466cec8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Targeted Dataset Augmentation","type":"text"},{"styles":{},"text":": For cases identified as genuine knowledge gaps, new training examples are explicitly added to the SFT dataset that demonstrate the ","type":"text"},{"styles":{"bold":true},"text":"correct refusal behavior","type":"text"},{"styles":{},"text":" — e.g., a training example showing the ideal response to a question about an unknown entity should be something like: ","type":"text"},{"styles":{"italic":true},"text":"\"I''m sorry, I don''t have information about that. I don''t know who Orson Kovats is.\"","type":"text"}],"id":"9a661626-50fe-4d13-9ae6-0047d9f3c557","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Result","type":"text"},{"styles":{},"text":": By explicitly training on \"I don''t know\" examples alongside confident-answer examples, the model learns to ","type":"text"},{"styles":{"bold":true},"text":"discriminate","type":"text"},{"styles":{},"text":" between situations where confident knowledge is present in its weights versus situations resembling those flagged during probing — improving (though not perfectly solving) its calibration.","type":"text"}],"id":"11ba4c6d-1c57-4af9-90d8-87f9fdefa2fa","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"C. Memory Architecture — Two Distinct Systems","type":"text"}],"id":"7ce4a2d9-5557-4c1e-b268-0f047be0e9ad","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Karpathy draws an explicit and important analogy between LLM \"memory\" and human memory systems, mapping onto two structurally distinct locations where \"knowledge\" can reside for the model:","type":"text"}],"id":"8807c706-af5e-44b3-8454-f6d641e22648","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Parameter Weights = Long-Term, Vague Memory","type":"text"},{"styles":{},"text":": Knowledge baked into the billions of trained parameters during pre-training and SFT is analogous to a human''s ","type":"text"},{"styles":{"bold":true},"text":"long-term memory","type":"text"},{"styles":{},"text":" — vast in scope, but ","type":"text"},{"styles":{"bold":true},"text":"imprecise, compressed, and \"lossy\"","type":"text"},{"styles":{},"text":" (echoing the \"lossy zip file\" analogy from pre-training). The model has a rough, statistical sense of many facts but cannot reliably reproduce precise details on demand from parameters alone.","type":"text"}],"id":"4c2dfdea-75a9-4bb5-a283-cffabd77e85a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Context Window = Working Memory","type":"text"},{"styles":{},"text":": Information placed directly into the current prompt/context window functions like ","type":"text"},{"styles":{"bold":true},"text":"working memory","type":"text"},{"styles":{},"text":" — immediately accessible, precise, and directly \"in view\" for the model''s attention mechanism to reference while generating its response.","type":"text"}],"id":"801e3528-e12c-42c3-9f78-3ba58e229e72","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Practical Implication","type":"text"},{"styles":{},"text":": Because of this architecture, ","type":"text"},{"styles":{"bold":true},"text":"directly pasting relevant source text into the prompt","type":"text"},{"styles":{},"text":" (e.g., pasting the actual article, document, or dataset the user is asking about) dramatically improves the accuracy and reliability of the model''s answer — the model isn''t forced to rely on its vague, compressed long-term \"memory\" of the topic; instead, it can directly attend to the precise information sitting in its working memory (context window).","type":"text"}],"id":"b3960431-b47d-4169-8afd-8c3b8f5e03e7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"D. Identity & System Messages — The Illusion of Persistent Self","type":"text"}],"id":"0aa51f33-8c7f-4b6c-b687-de93d39612fc","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"No True Persistent State","type":"text"},{"styles":{},"text":": Karpathy clarifies that the model has ","type":"text"},{"styles":{"bold":true},"text":"no actual continuous memory or identity","type":"text"},{"styles":{},"text":" across separate conversations. Each new conversation starts the model completely \"fresh\" — there is no hidden internal state carried over from one chat session to another; the deterministic, stateless transformer (as established in pre-training) has no mechanism for this.","type":"text"}],"id":"c03b4179-1252-455c-9d3f-41308efe7dde","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[{"children":[],"content":[{"styles":{"bold":true},"text":"Hidden System Messages","type":"text"},{"styles":{},"text":": A system-level prompt, invisible to the user, is silently prepended to every conversation, explicitly stating the model''s name, developer, and behavioral guidelines.","type":"text"}],"id":"0924bc7a-da9d-4cb9-8833-6cbe95fddafa","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Hardcoded Q&A Training Examples","type":"text"},{"styles":{},"text":": The SFT dataset explicitly includes many training examples of the pattern \"Who are you? / I am [Model Name], an AI assistant made by [Company]\" so the model reliably reproduces this self-description whenever asked, purely as a learned response pattern — not as evidence of genuine self-awareness or continuity.","type":"text"}],"id":"a5583ccc-e149-427f-ac97-f2d705ed3624","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"}],"content":[{"styles":{"bold":true},"text":"Injected Identity Mechanism","type":"text"},{"styles":{},"text":": The apparent consistent \"personality\" or self-identification (e.g., a model reliably saying \"I am ChatGPT, developed by OpenAI\" across different conversations) is ","type":"text"},{"styles":{"bold":true},"text":"not","type":"text"},{"styles":{},"text":" innate self-awareness — it is achieved through:","type":"text"}],"id":"495aabf7-b745-42fd-bfdf-2d2f5a298eb1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"4. Concrete Lecture Examples","type":"text"}],"id":"5ebc702c-38df-4cb4-886c-df169b33e005","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"\"Who is Orson Kovats?\"","type":"text"},{"styles":{},"text":" — central worked example of confident hallucination on a name the model has no reliable information about.","type":"text"}],"id":"4e0ade82-f4ba-4767-b144-c6bb0505c82c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"\"I''m sorry, I don''t know\"","type":"text"},{"styles":{},"text":" — the exact style of refusal response used as a training target once knowledge gaps are identified via probing.","type":"text"}],"id":"3e9407db-aaa8-4ae9-bb69-816ebaa48283","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"The ","type":"text"},{"styles":{"bold":true},"text":"long-term memory (parameters) vs. working memory (context window)","type":"text"},{"styles":{},"text":" framing is presented as a direct, explicit analogy to human cognitive architecture, used to explain ","type":"text"},{"styles":{"italic":true},"text":"why","type":"text"},{"styles":{},"text":" pasting source text into a prompt improves accuracy.","type":"text"}],"id":"9a3e5c5c-faca-4266-bb6b-db71f94ec887","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Identity example: models consistently stating their name/developer is explicitly attributed to ","type":"text"},{"styles":{"bold":true},"text":"hidden system prompts","type":"text"},{"styles":{},"text":" and ","type":"text"},{"styles":{"bold":true},"text":"hardcoded training examples","type":"text"},{"styles":{},"text":", not genuine self-modeling.","type":"text"}],"id":"0e22fd8b-5836-45b6-a9cf-f3b2b9153a71","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"5. Key Transitions","type":"text"}],"id":"775661e5-8559-473f-9d89-099e171e6a00","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The \"working memory\" concept (context window) directly explains why giving the model ","type":"text"},{"styles":{"italic":true},"text":"more","type":"text"},{"styles":{},"text":" information to work with — beyond what''s in its vague parametric memory — improves accuracy. This naturally raises the question: ","type":"text"},{"styles":{"bold":true},"text":"can the model actively go out and fetch new information to put into its own working memory, rather than relying only on what the user manually provides?","type":"text"},{"styles":{},"text":" This leads into ","type":"text"},{"styles":{"bold":true},"text":"Section 5: External Tool Integration Mechanics","type":"text"},{"styles":{},"text":", covering web search and code execution.","type":"text"}],"id":"68d05563-9634-4c69-83b0-8d536401ff88","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"b55ea4c6-9ddf-4fe0-ad01-37b8eb686a2e","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"🛠️ SECTION 5: External Tool Integration Mechanics","type":"text"}],"id":"b7e5d1a1-459c-4cbb-9bad-a8ca43e6992a","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"1. Concept Overview","type":"text"}],"id":"9f42415c-d3e5-40f2-b186-513cceba9cf0","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Because a model''s parametric \"long-term memory\" is vague, static (frozen at training time), and cannot be updated with current or precise information, assistant models are trained to use ","type":"text"},{"styles":{"bold":true},"text":"external tools","type":"text"},{"styles":{},"text":" — specifically web search and a Python code interpreter — to actively fetch or compute information and inject it directly into their working memory (context window) before producing a final answer.","type":"text"}],"id":"289090d8-3c9f-414b-ad92-44d31775b44b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"2. Why It Is Needed","type":"text"}],"id":"1400b97c-3b1a-46fe-a29d-e18d9dcdee24","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Two specific categories of failure motivate tool use:","type":"text"}],"id":"649fad7d-73e4-4142-8852-2790b575bf3d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Stale/Missing Knowledge","type":"text"},{"styles":{},"text":": The model''s training data has a cutoff date; it cannot know about recent events, and its vague parametric memory of even older facts can be unreliable (as discussed in Section 4).","type":"text"}],"id":"7d4bbc46-61fb-4c0d-9ffc-97ff6b2b6633","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Unreliable Exact Computation","type":"text"},{"styles":{},"text":": As will be detailed further in Section 6, transformers have a fixed amount of computation available per generated token, making them fundamentally unreliable at exact arithmetic, precise counting, or complex multi-step calculations when done purely \"in the head\" (within the forward pass).","type":"text"}],"id":"f089b4ec-afcf-43e6-af16-12a67c3a5899","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Tool use solves both problems by letting the model ","type":"text"},{"styles":{"bold":true},"text":"delegate","type":"text"},{"styles":{},"text":" to external, reliable systems (search engines for facts, a real code interpreter for math) rather than relying purely on internal, approximate computation or memory.","type":"text"}],"id":"2a60647c-f0b1-4150-af1f-7c8bbc8af5b6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"3. How It Works Step-by-Step","type":"text"}],"id":"e9505fff-c616-48b9-a825-7a483b6004d2","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"A. Web Search Tool Mechanics","type":"text"}],"id":"1956d09e-6ffc-4a21-b60d-14dae40b180f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Training-Time Setup","type":"text"},{"styles":{},"text":": During SFT, the model is trained on examples demonstrating the ","type":"text"},{"styles":{"italic":true},"text":"pattern","type":"text"},{"styles":{},"text":" of tool invocation — showing it when and how to emit special tool-call tokens.","type":"text"}],"id":"97240f84-d149-45a9-b65e-b92c76209e6e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Special Search Tokens","type":"text"},{"styles":{},"text":": When the model determines a query requires up-to-date or externally-verifiable information, it emits a specially reserved token sequence, structured like: ","type":"text"},{"styles":{"code":true},"text":"<search_start> [query text] <search_end>","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"4614087e-a7cf-4e2d-b196-7cd72e90199b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Inference Pause","type":"text"},{"styles":{},"text":": The serving infrastructure monitors the token stream for this special pattern. Upon detecting ","type":"text"},{"styles":{"code":true},"text":"<search_start>...<search_end>","type":"text"},{"styles":{},"text":", it ","type":"text"},{"styles":{"bold":true},"text":"pauses","type":"text"},{"styles":{},"text":" the model''s own token generation.","type":"text"}],"id":"d05d69d6-095b-44ea-877d-9cf6694fe6e7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"External Query Execution","type":"text"},{"styles":{},"text":": The system extracts the query text and issues an actual API call to a search backend (e.g., ","type":"text"},{"styles":{"bold":true},"text":"Bing","type":"text"},{"styles":{},"text":" or ","type":"text"},{"styles":{"bold":true},"text":"Google","type":"text"},{"styles":{},"text":") exactly as a browser or search client would.","type":"text"}],"id":"0e37422b-672b-42c3-b53c-dbbd32146884","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Context Injection","type":"text"},{"styles":{},"text":": The raw text results returned by the search engine (snippets, page content, etc.) are ","type":"text"},{"styles":{"bold":true},"text":"inserted directly into the model''s context window","type":"text"},{"styles":{},"text":" — effectively appending this fetched information into the ongoing token sequence, making it part of the model''s immediate \"working memory.\"","type":"text"}],"id":"9cb5ed5d-3025-4a1d-a51f-f073a1e21d5a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Resume Generation","type":"text"},{"styles":{},"text":": The model then resumes autoregressive generation, now with the search results sitting directly in its context — allowing it to read, synthesize, and directly reference this fresh, precise information rather than relying on its vague parametric memory.","type":"text"}],"id":"7afeb28b-c6b4-4eb5-876e-8672c842a801","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Citations","type":"text"},{"styles":{},"text":": Because the source web content is present in context (often along with source URLs/metadata), the model is trained to generate ","type":"text"},{"styles":{"bold":true},"text":"citations","type":"text"},{"styles":{},"text":" referencing which retrieved source supports which part of its answer — a directly learned behavioral pattern from the SFT training examples showing this exact workflow.","type":"text"}],"id":"b4b6f30b-2d9a-4d15-9b93-e048f0500aaf","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"B. Python Code Interpreter Mechanics","type":"text"}],"id":"db0684fd-1af0-4d0c-9224-340bae4df7c1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Special Code Block Emission","type":"text"},{"styles":{},"text":": When the model recognizes a task requiring precise computation (arithmetic, string manipulation, data processing, counting), it is trained to emit a Python code block rather than attempting to directly compute the answer via token-by-token generation.","type":"text"}],"id":"a8126e61-07ca-488f-8e8c-e42611502634","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Sandboxed Execution","type":"text"},{"styles":{},"text":": The serving infrastructure detects this code block, extracts the code, and executes it in an isolated, sandboxed Python interpreter environment (isolated for security — arbitrary generated code must never run unrestricted on production infrastructure).","type":"text"}],"id":"2ca62644-feda-44cb-965b-f0abd99c64e4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Capture Output","type":"text"},{"styles":{},"text":": The actual stdout/result of running that code (e.g., the printed result of a calculation) is captured by the system.","type":"text"}],"id":"e0e4d187-9614-48a8-b5d7-05b35d2dcdd7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Context Injection (same mechanism as search)","type":"text"},{"styles":{},"text":": This exact output is inserted back into the model''s context window/token stream.","type":"text"}],"id":"9fe04ab5-5a4b-442a-9414-159ba3094aaf","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Resume & Synthesize","type":"text"},{"styles":{},"text":": The model resumes generation, now with the ","type":"text"},{"styles":{"italic":true},"text":"exact, correct","type":"text"},{"styles":{},"text":" computed result directly visible in its working memory, and incorporates this precise value into its final natural-language response to the user.","type":"text"}],"id":"f82212b1-d142-4c2b-92d4-f27d654ac5d6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"4. Concrete Lecture Examples","type":"text"}],"id":"ee7ce62b-e06b-421a-b084-a4af01794568","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The ","type":"text"},{"styles":{"code":true},"text":"<search_start>","type":"text"},{"styles":{"bold":true},"text":" / ","type":"text"},{"styles":{"code":true},"text":"<search_end>","type":"text"},{"styles":{},"text":" token pattern is given as the explicit mechanism for triggering a web lookup, with ","type":"text"},{"styles":{"bold":true},"text":"Bing","type":"text"},{"styles":{},"text":" and ","type":"text"},{"styles":{"bold":true},"text":"Google","type":"text"},{"styles":{},"text":" named as example backend search providers whose results get fetched and injected.","type":"text"}],"id":"0f83eec7-289e-4172-ae85-01ff6c15b432","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"The ","type":"text"},{"styles":{"bold":true},"text":"code interpreter","type":"text"},{"styles":{},"text":" workflow is described as directly analogous: the model ","type":"text"},{"styles":{"bold":true},"text":"writes actual Python code","type":"text"},{"styles":{},"text":", the code is run in a real sandboxed interpreter, and the ","type":"text"},{"styles":{"bold":true},"text":"stdout","type":"text"},{"styles":{},"text":" is fed back in — this is explicitly contrasted with the model trying to \"guess\" or mentally simulate the result of running code, which is unreliable for anything beyond trivial cases.","type":"text"}],"id":"2c260147-0608-46a7-bc3b-d52b5f7a89ee","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Both mechanisms share the identical underlying pattern: ","type":"text"},{"styles":{"bold":true},"text":"emit special token(s) → pause generation → external system acts → inject result into context → resume generation","type":"text"},{"styles":{},"text":" — this unified pattern is a key conceptual takeaway.","type":"text"}],"id":"b89b6fb3-a5a5-4a92-9bb2-0dee5eb53635","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"5. Key Transitions","type":"text"}],"id":"e8530f06-bf8f-44f5-af59-23de0a55bd14","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The code interpreter example — offloading math to an external, exact tool — directly foreshadows a deeper architectural question: ","type":"text"},{"styles":{"bold":true},"text":"why can''t the transformer just compute the math correctly itself, internally, during a normal forward pass?","type":"text"},{"styles":{},"text":" This leads into ","type":"text"},{"styles":{"bold":true},"text":"Section 6: Architectural Constraints & Cognitive Quirks","type":"text"},{"styles":{},"text":", which explains the fixed-compute-per-token limitation underlying this exact need for tool delegation.","type":"text"}],"id":"c4b247c7-8e99-41c3-bc6a-a27c529e8ab3","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"0fb4dda9-f365-4377-93fc-fa64a6e7c763","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"⚡ SECTION 6: Architectural Constraints & Cognitive Quirks","type":"text"}],"id":"10900346-6f70-40c9-8d1b-433ef41602ea","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"1. Concept Overview","type":"text"}],"id":"d073399c-a9ed-4bd1-8ee7-53c42084f954","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"This final section explains several deep, structural limitations inherent to the transformer architecture itself — limitations that persist even after extensive SFT training — and how understanding these limitations explains otherwise-puzzling model behaviors, including its need for tools (Section 5), its struggles with spelling/counting, and surprising failures on seemingly trivial tasks.","type":"text"}],"id":"472c00e9-1806-4a05-b841-39c376929cdf","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"2. Why It Is Needed","type":"text"}],"id":"aac1eec8-045f-4265-b997-e700b806b890","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Users often assume that because a model can solve PhD-level physics problems, it should trivially handle simple tasks like counting letters or comparing decimal numbers. Understanding the ","type":"text"},{"styles":{"bold":true},"text":"fixed-compute-per-token","type":"text"},{"styles":{},"text":" constraint of the transformer architecture resolves this apparent paradox and explains why intelligent-seeming systems can fail in surprising, seemingly \"dumb\" ways — a phenomenon Karpathy characterizes as a ","type":"text"},{"styles":{"bold":true},"text":"\"Swiss-cheese\" capability model","type":"text"},{"styles":{},"text":": extremely strong almost everywhere, but with unpredictable holes.","type":"text"}],"id":"696ecfc5-93df-45a6-a826-31fcec32be18","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"3. How It Works Step-by-Step","type":"text"}],"id":"2784e3c3-47b7-4b51-86df-91dd0431b465","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"A. Fixed Compute Per Token","type":"text"}],"id":"dcc8f449-ef48-4d1a-a7f5-6cc530e80ad6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Architectural Fact","type":"text"},{"styles":{},"text":": Every single forward pass of a transformer — i.e., the computation required to produce the probability distribution for ","type":"text"},{"styles":{"bold":true},"text":"one single next token","type":"text"},{"styles":{},"text":" — involves passing information through a ","type":"text"},{"styles":{"bold":true},"text":"fixed number of layers","type":"text"},{"styles":{},"text":", each performing a bounded amount of computation (attention + MLP operations).","type":"text"}],"id":"13bfe77e-87dc-4dd9-90a2-9b208529ce08","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"No Variable \"Thinking Time\"","type":"text"},{"styles":{},"text":": Unlike a human who can pause and think longer on a hard problem, a transformer ","type":"text"},{"styles":{"bold":true},"text":"cannot allocate more computation","type":"text"},{"styles":{},"text":" to a harder token prediction — every single token, whether trivially easy or fiendishly complex, gets exactly the same fixed budget of matrix multiplications to produce its answer.","type":"text"}],"id":"16005f87-2ea8-403d-9cda-8b520a71044a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Consequence for Complex Math","type":"text"},{"styles":{},"text":": If a task requires many sequential steps of reasoning or calculation to solve correctly (e.g., a multi-digit multiplication problem), and the model is asked to produce the ","type":"text"},{"styles":{"bold":true},"text":"final answer directly, in a single token or a very short burst of tokens","type":"text"},{"styles":{},"text":", it may simply not have enough \"computational depth\" within that fixed per-token budget to get the correct answer — leading to arithmetic errors on problems requiring multi-step calculation.","type":"text"}],"id":"7ba76eb8-8b23-41d9-a956-6930f8155681","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"B. Distributing Reasoning Across Tokens (Chain-of-Thought)","type":"text"}],"id":"5628a765-2f9d-4b3a-92db-031f0f32e09d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"The Workaround","type":"text"},{"styles":{},"text":": Since compute-per-token is fixed but the ","type":"text"},{"styles":{"italic":true},"text":"number","type":"text"},{"styles":{},"text":" of tokens generated is not, the model can effectively access ","type":"text"},{"styles":{"bold":true},"text":"more total computation for a hard problem by spreading the reasoning process out across many generated tokens","type":"text"},{"styles":{},"text":" rather than trying to jump straight to the answer.","type":"text"}],"id":"cc969e02-74ba-433a-b065-4b2ab6d75e62","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Chain-of-Thought (CoT) / Scratchpad Technique","type":"text"},{"styles":{},"text":": By training the model (via SFT examples) to ","type":"text"},{"styles":{"bold":true},"text":"write out intermediate reasoning steps","type":"text"},{"styles":{},"text":" — showing its work, step by step, in natural language or symbolic notation, before stating a final answer — each intermediate step gets its own full forward pass (and thus its own full fixed compute budget). The cumulative effect across many tokens is equivalent to the model having \"more total thinking\" applied to the problem, even though any single token''s compute remains fixed.","type":"text"}],"id":"1185f7b3-3e50-46e5-9e01-d2620ef3a775","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Practical Guidance","type":"text"},{"styles":{},"text":": This directly explains a very practical prompting principle: for complex problems, asking the model to \"think step by step\" or explicitly show its work generally produces more reliable/accurate answers than demanding a single direct final answer — because it forces reasoning to be distributed across more tokens, sidestepping the fixed-per-token compute ceiling.","type":"text"}],"id":"11b45e4d-7cc5-4774-91d0-133b89667c9f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"C. Tokenization Blind Spots (Spelling & Counting)","type":"text"}],"id":"c02736fd-2cf8-452b-867a-6c56b53a0597","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Root Cause","type":"text"},{"styles":{},"text":": As established in the pre-training tokenization section, the model does not see individual characters — it sees ","type":"text"},{"styles":{"bold":true},"text":"BPE sub-word tokens","type":"text"},{"styles":{},"text":", which frequently group multiple characters together into single, opaque symbols. The model has no direct, native access to the individual character-level composition of these tokens.","type":"text"}],"id":"3618e092-26b2-493d-9f6d-e0d40077874d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Consequence for Character-Level Tasks","type":"text"},{"styles":{},"text":": Tasks that require reasoning about the precise character-level makeup of a word — such as counting how many times a specific letter appears, or identifying a character at a specific index — are fundamentally difficult for the model, because the relevant information (individual letters) is ","type":"text"},{"styles":{"bold":true},"text":"not directly visible","type":"text"},{"styles":{},"text":" in its token-level input representation; it''s smeared/hidden inside the opaque identity of merged sub-word tokens.","type":"text"}],"id":"027216ba-8355-444c-86dc-5540a30d4997","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Concrete Example — Counting ''r''s in \"strawberry\"","type":"text"},{"styles":{},"text":": Karpathy uses this as a canonical example of a task that trips up LLMs — the word \"strawberry\" gets tokenized into a small number of sub-word chunks (not individual letters), so when asked \"how many r''s are in strawberry,\" the model must implicitly try to \"reconstruct\" character-level information it was never directly given, often leading to incorrect counts.","type":"text"}],"id":"4a7a045a-ea60-4f43-84c9-ed8a6e749433","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Concrete Example — Indexing letters in \"ubiquitous\"","type":"text"},{"styles":{},"text":": Similarly, asking the model to identify, say, \"the 3rd letter of ''ubiquitous''\" faces the same fundamental blind spot — the model must infer character positions from token boundaries it doesn''t natively track, again a downstream consequence of BPE tokenization choices made all the way back in pre-training (Section 2 of the pre-training note).","type":"text"}],"id":"3bc1b5be-dc2a-40bf-be72-7aa95a539f76","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"D. Swiss-Cheese Capability Model","type":"text"}],"id":"6e54d565-c8d2-4f6b-a8bc-eca51b414571","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"The Core Idea","type":"text"},{"styles":{},"text":": Karpathy frames overall LLM capability as resembling a block of ","type":"text"},{"styles":{"bold":true},"text":"Swiss cheese","type":"text"},{"styles":{},"text":" — largely solid, dense, and reliable (representing genuinely impressive, even superhuman performance on many hard tasks, like PhD-level science questions), but riddled with unpredictable ","type":"text"},{"styles":{"bold":true},"text":"holes","type":"text"},{"styles":{},"text":" — specific, sometimes very simple-looking cases where performance inexplicably collapses.","type":"text"}],"id":"8f7799b2-68ce-4176-b74e-b2b69ab9ef59","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Concrete Example — \"9.11 > 9.9\"","type":"text"},{"styles":{},"text":": Karpathy discusses the well-documented failure mode where models sometimes incorrectly judge that ","type":"text"},{"styles":{"bold":true},"text":"9.11 is greater than 9.9","type":"text"},{"styles":{},"text":". One hypothesized contributing factor: in the model''s training data, sequences like \"9.11\" and \"9.9\" numerically resemble patterns from contexts like ","type":"text"},{"styles":{"bold":true},"text":"Bible verse numbering","type":"text"},{"styles":{},"text":" (e.g., chapter/verse references like \"9:11\" or section numbering in structured documents), where a higher second number after the decimal-like separator does ","type":"text"},{"styles":{"italic":true},"text":"not","type":"text"},{"styles":{},"text":" imply a smaller overall value in the way real decimal arithmetic requires. This creates a ","type":"text"},{"styles":{"bold":true},"text":"token-pattern distraction","type":"text"},{"styles":{},"text":" — the model''s learned statistical associations from unrelated numeric-formatting contexts interfere with straightforward decimal comparison logic.","type":"text"}],"id":"e6ca7d72-bc15-4511-987e-ddabd1c5fc0e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Implication","type":"text"},{"styles":{},"text":": This example crystallizes the entire \"Swiss-cheese\" concept: a system capable of extraordinarily sophisticated reasoning in one domain can simultaneously fail at an elementary-school-level comparison in another, precisely because its \"knowledge\" and \"reasoning\" are the emergent byproduct of statistical pattern-learning over training data — not the result of explicit, guaranteed, rule-based logical circuitry. There is no architectural guarantee of uniform competence across all tasks of a given apparent \"difficulty level\" from a human perspective.","type":"text"}],"id":"4e8fe493-6a65-4a33-9978-725cb0192c61","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"4. Concrete Lecture Examples","type":"text"}],"id":"af4a6a14-914a-4297-829b-5018d3c37642","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Fixed compute per token","type":"text"},{"styles":{},"text":": presented as the root architectural explanation for why multi-step math done \"in one shot\" is unreliable.","type":"text"}],"id":"e0bae606-8f3d-4f6c-a533-1cd94601d4ca","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Chain-of-Thought/scratchpad","type":"text"},{"styles":{},"text":": presented as the direct mitigation, distributing reasoning across the token sequence.","type":"text"}],"id":"dfa32c45-2613-4ea6-966c-d9976a8dcfaa","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"\"Strawberry\" r-counting","type":"text"},{"styles":{},"text":" and ","type":"text"},{"styles":{"bold":true},"text":"\"ubiquitous\" letter-indexing","type":"text"},{"styles":{},"text":": the two canonical concrete examples of tokenization-driven blind spots.","type":"text"}],"id":"17274410-2eac-457b-a87b-fe23364685fb","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"\"9.11 > 9.9\" with Bible-verse-numbering distraction","type":"text"},{"styles":{},"text":": the canonical concrete example of the Swiss-cheese capability model and unpredictable failure modes.","type":"text"}],"id":"9d4472b7-cc94-4c02-80d2-540246b83eef","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"5. Key Transitions (End of SFT Scope)","type":"text"}],"id":"eb7c1552-1a54-4089-8879-fe8f836902bd","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"These architectural quirks — fixed per-token compute, tokenization blind spots, and inconsistent Swiss-cheese reliability — are ","type":"text"},{"styles":{"bold":true},"text":"inherent to the current transformer + SFT paradigm","type":"text"},{"styles":{},"text":" covered in this note. They represent the natural boundary of what SFT alone (training on curated demonstration data) can fix, because SFT only teaches the model to ","type":"text"},{"styles":{"italic":true},"text":"imitate","type":"text"},{"styles":{},"text":" correct behavior patterns shown by labelers — it does not give the model a mechanism to ","type":"text"},{"styles":{"italic":true},"text":"search","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"italic":true},"text":"verify","type":"text"},{"styles":{},"text":", or ","type":"text"},{"styles":{"italic":true},"text":"self-correct","type":"text"},{"styles":{},"text":" its own reasoning during generation.","type":"text"}],"id":"0d2e210a-0b98-44f2-9824-b832dca67e67","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Addressing these deeper limitations — teaching models to reason through trial, self-correction, and optimization against a reward signal rather than pure imitation — is precisely the motivation for the next stage of model development: Reinforcement Learning (RL/RLHF).","type":"text"},{"styles":{},"text":" However, per the explicit scope of this note, ","type":"text"},{"styles":{"bold":true},"text":"reinforcement learning is not covered here","type":"text"},{"styles":{},"text":" — this note stops precisely at the boundary of SFT and its resulting behavioral/architectural characteristics.","type":"text"}],"id":"e3b85783-d545-48a5-b540-be6aabf108dc","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"d9936165-3962-42a5-b783-41ff91a46e58","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"📌 SUMMARY CHECKPOINT","type":"text"}],"id":"4f791ec3-d37a-4afd-9f8c-21368e66ced0","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":{"columnWidths":[null,null,null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Stage","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Input","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Process","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Output","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"1. SFT Data Swap","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Base model + web-text training regime","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Replace data with curated conversations","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Reoriented \"assistant-shaped\" training target","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"2. Dialogue Protocol","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Multi-turn conversations","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Serialize with ","type":"text"},{"styles":{"code":true},"text":"<|im_start|>","type":"text"},{"styles":{},"text":"/","type":"text"},{"styles":{"code":true},"text":"<|im_end|>","type":"text"},{"styles":{},"text":"/","type":"text"},{"styles":{"code":true},"text":"<|im_sep|>","type":"text"},{"styles":{},"text":" tokens","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Flat 1D trainable token sequences","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"3. Dataset Curation","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Human labelers + synthetic LLM drafts","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"HTH-guideline-driven writing/editing","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"SFT training corpus (e.g., UltraChat-style)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"4. Psychology & Memory","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Trained SFT model","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Probing for hallucination + refusal training","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Calibrated confidence + working/long-term memory distinction","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"5. Tool Integration","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Model + external systems","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Emit special tokens → pause → fetch/execute → inject context","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Fact-grounded, computation-accurate responses","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"6. Architectural Limits","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Transformer forward-pass constraints","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Fixed compute/token; BPE blind spots","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Explains CoT necessity, spelling errors, Swiss-cheese failures","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"4cc18682-6d35-41c6-8be4-4a5d3c45821b","props":{"textColor":"default"},"type":"table"},{"children":[],"content":[{"styles":{"bold":true},"text":"⛔ End of SFT Scope — Reinforcement Learning (RL/RLHF) Not Covered ⛔","type":"text"}],"id":"0f2c5869-56e1-41d3-9aef-4c7427c7c79f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[],"id":"6c4584b0-b085-4c8e-999b-a01fcb2ab93b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"}]'::jsonb, '3e9e3dd3-a59b-4b02-968a-ee95e7317583') ON CONFLICT ("node_id") DO UPDATE SET "bad_example" = EXCLUDED."bad_example", "completed_at" = EXCLUDED."completed_at", "created_at" = EXCLUDED."created_at", "definition" = EXCLUDED."definition", "good_example" = EXCLUDED."good_example", "is_completed" = EXCLUDED."is_completed", "key_points" = EXCLUDED."key_points", "last_edited" = EXCLUDED."last_edited", "map_id" = EXCLUDED."map_id", "mental_model" = EXCLUDED."mental_model", "notes" = EXCLUDED."notes", "resources" = EXCLUDED."resources", "rich_content" = EXCLUDED."rich_content", "user_id" = EXCLUDED."user_id";
INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-06-13T15:06:33.806679+00:00', '', '', '15642b31-a9bc-4198-b031-eabd0dd8f41f', false, '[]'::jsonb, '2026-06-13T15:06:43.65+00:00', '2ad473fe-77dd-481e-8ba7-4b2b0336173f', '', '607e8f0d-9339-4fa0-80f3-ca8e5f583d29', '', '[]'::jsonb, '[{"children":[],"content":[],"id":"11468944-7a2c-47fe-9eb5-980b215b35ee","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"7bc466a0-8c9b-416c-b0c9-f2557334b5d7","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Very short intro","type":"text"}],"id":"ebabfcfe-b06f-4f16-a91a-0fbb62e19237","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"At the ","type":"text"},{"styles":{"bold":true},"text":"Distribution Hub","type":"text"},{"styles":{},"text":", the ","type":"text"},{"styles":{"bold":true},"text":"Incident Desk","type":"text"},{"styles":{},"text":" keeps a written record of everything that happens during a shift. The ","type":"text"},{"styles":{"bold":true},"text":"info bell","type":"text"},{"styles":{},"text":" rings for normal progress updates, the ","type":"text"},{"styles":{"bold":true},"text":"warning flag","type":"text"},{"styles":{},"text":" goes up for anything unusual, and the ","type":"text"},{"styles":{"bold":true},"text":"error alarm","type":"text"},{"styles":{},"text":" fires when something breaks. Every entry goes into the ","type":"text"},{"styles":{"bold":true},"text":"desk register","type":"text"},{"styles":{},"text":" and is stamped with a ","type":"text"},{"styles":{"bold":true},"text":"timestamp","type":"text"},{"styles":{},"text":". The ","type":"text"},{"styles":{"bold":true},"text":"paper trail","type":"text"},{"styles":{},"text":" keeps a permanent file copy. The ","type":"text"},{"styles":{"bold":true},"text":"live board","type":"text"},{"styles":{},"text":" shows events in real time on the terminal. Topic 10 is the minimum logging knowledge an internship interviewer will expect.","type":"text"}],"id":"22dbcbba-5769-4d43-94a6-45018b599b47","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"0eb8a768-e31b-44c9-b7b2-277fc80a39f0","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Mind map","type":"text"}],"id":"de6fb1db-9c37-49dd-b7f1-cd8e613b9c9c","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"INCIDENT DESK\n(Logging)\n│\n├── Desk Register\n│   └── logger = logging.getLogger(__name__)\n│\n├── Info Bell\n│   └── logger.info()\n│\n├── Warning Flag\n│   └── logger.warning()\n│\n├── Error Alarm\n│   └── logger.error(..., exc_info=True)\n│\n├── Timestamp Stamp\n│   └── %(asctime)s in format string\n│\n├── Paper Trail\n│   └── FileHandler → writes to a log file\n│\n└── Live Board\n    └── StreamHandler → writes to terminal","type":"text"}],"id":"051146f0-e12e-465f-8567-7cc01cdfcc91","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"ad0ccd1b-c617-428e-98b1-6f224fed45e7","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Decision tree","type":"text"}],"id":"3f14954a-f6a2-4c64-a744-3eecdaa28623","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Does your script do meaningful work?\n└── Yes → add logging. Never use bare print() in a pipeline.\n\nWhat level should I use?\n│\n├── Normal progress, counts, milestones?   → INFO\n├── Something unexpected but not fatal?    → WARNING\n└── Something broke, exception caught?     → ERROR + exc_info=True\n\nWhere should logs go?\n│\n├── Need to see output while running?  → StreamHandler (Live Board)\n└── Need a permanent record?           → FileHandler  (Paper Trail)\n    └── Use both together — attach both handlers to the same logger.\n\nHow do I set it up?\n│\n├── logger = logging.getLogger(__name__)\n├── logger.setLevel(logging.INFO)\n├── Create formatter with %(asctime)s\n├── Attach FileHandler\n├── Attach StreamHandler\n└── Log away","type":"text"}],"id":"37593647-a44f-4610-a9b6-d40559a95808","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"06382a15-1fe7-487f-9944-75fbfbb90be7","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Concept breakdown","type":"text"}],"id":"8df690b2-17fb-43ef-9363-b468d5185e86","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"id":"053278dc-7651-4f32-9842-04690ead248a","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"1) Desk Register — ","type":"text"},{"styles":{"code":true},"text":"logging.getLogger(__name__)","type":"text"}],"id":"362bed5c-bbae-4ea7-9821-8d4de6a509da","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" Creates a logger tied to the current module''s name. ","type":"text"},{"styles":{"code":true},"text":"__name__","type":"text"},{"styles":{},"text":" is automatically the module name at runtime, so log messages are traceable to where they came from.","type":"text"}],"id":"32126a68-cd84-4691-94a4-7c7c68b4488f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters in an interview:","type":"text"},{"styles":{},"text":" Using ","type":"text"},{"styles":{"code":true},"text":"logging.getLogger(__name__)","type":"text"},{"styles":{},"text":" instead of the root logger is the correct pattern. Interviewers expect this. Using ","type":"text"},{"styles":{"code":true},"text":"print()","type":"text"},{"styles":{},"text":" in a pipeline is a red flag.","type":"text"}],"id":"11b108c6-8677-40c0-a7d1-20e5a9fba68c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"05ac22e5-b6cc-4716-8557-0c90087978e3","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"import logging\n\nlogger = logging.getLogger(__name__)","type":"text"}],"id":"bc8c5701-5059-4079-b9d8-d42a33619b76","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Rule: One logger per module. Always ","type":"text"},{"styles":{"code":true},"text":"__name__","type":"text"},{"styles":{},"text":". Never use the root logger directly in production code.","type":"text"}],"id":"a8e7b055-b9a0-4e97-8ada-af094ff77f5e","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"12512aec-5976-40aa-a4ff-f933cc46ce8a","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"2) Log levels — ","type":"text"},{"styles":{"code":true},"text":"INFO","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"WARNING","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"ERROR","type":"text"}],"id":"aa304eb4-a16a-4cc3-af24-29065e745b87","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" Severity labels that classify what kind of event is being logged.","type":"text"}],"id":"dc884d0f-f35b-487f-bc85-299586463bfd","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Level","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"When to use","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"INFO","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Normal progress, counts, milestones","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"WARNING","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Something unexpected but the job continues","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"ERROR","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Something broke — usually inside an ","type":"text"},{"styles":{"code":true},"text":"except","type":"text"},{"styles":{},"text":" block","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"5e5af364-21c4-4aed-810b-62236940db23","props":{"textColor":"default"},"type":"table"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters in an interview:","type":"text"},{"styles":{},"text":" Using the wrong level is a common mistake. Interviewers will ask you to justify your choice.","type":"text"}],"id":"866687b8-4077-4328-85e9-24a99dbe517c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"0636c054-00ec-4fd9-a461-22b569b7e714","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"logger.info(\"Pipeline started\")\nlogger.warning(\"Missing field in row — using default value\")\nlogger.error(\"Failed to process row\", exc_info=True)","type":"text"}],"id":"9e97f357-7dbb-49d0-9348-35435671a237","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"da9c63aa-001a-4d0d-aa76-d7bedf4d3ab9","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"3) Timestamp Stamp — ","type":"text"},{"styles":{"code":true},"text":"%(asctime)s","type":"text"},{"styles":{},"text":" in the format","type":"text"}],"id":"78bc9da9-b852-486a-a19e-0bb776507632","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" A format placeholder that inserts the timestamp of each log entry automatically.","type":"text"}],"id":"6318d029-d8e1-40c4-a4fa-0a2e5814bfa6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters in an interview:","type":"text"},{"styles":{},"text":" Logs without timestamps are nearly useless for debugging. Every real log format includes ","type":"text"},{"styles":{"code":true},"text":"%(asctime)s","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"1c42bae9-b4fa-49a0-a2d9-766bc8657ca8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"7c81063b-0eb3-4013-b521-c3d160d23c51","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"formatter = logging.Formatter(\n    \"%(asctime)s | %(levelname)s | %(name)s | %(message)s\"\n)","type":"text"}],"id":"dd840168-52dc-431b-ac65-d9e944ec6e2c","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Output looks like:","type":"text"}],"id":"bf0cc8ff-5841-4265-8ada-d04db81a9e97","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"2025-01-15 12:34:56,789 | INFO | pipeline | Pipeline started","type":"text"}],"id":"60443453-847f-42c7-9886-e90c0f74a76b","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Memorize the four most useful placeholders: ","type":"text"},{"styles":{"code":true},"text":"%(asctime)s","type":"text"},{"styles":{},"text":" — timestamp ","type":"text"},{"styles":{"code":true},"text":"%(levelname)s","type":"text"},{"styles":{},"text":" — INFO / WARNING / ERROR ","type":"text"},{"styles":{"code":true},"text":"%(name)s","type":"text"},{"styles":{},"text":" — logger name (the module) ","type":"text"},{"styles":{"code":true},"text":"%(message)s","type":"text"},{"styles":{},"text":" — your actual message","type":"text"}],"id":"287a3b57-cb64-4510-a000-7e54d65449f9","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"ae7ca411-ef20-440f-bb7c-06097158e017","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"4) Paper Trail — file handler","type":"text"}],"id":"84f0485f-9f57-4b90-9f38-1a1a77d89aa7","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" Sends log messages to a file so there is a permanent record even after the terminal closes.","type":"text"}],"id":"7478d155-f5ab-42eb-b307-f935c48d22c6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters in an interview:","type":"text"},{"styles":{},"text":" For any scheduled or batch job, you need a file log. Terminal output disappears.","type":"text"}],"id":"3f17b370-59c5-411f-90df-954ec52f3d51","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"9a53718a-947d-4983-931d-722b6ec4bc85","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"file_handler = logging.FileHandler(\"pipeline.log\")\nfile_handler.setFormatter(formatter)\nlogger.addHandler(file_handler)","type":"text"}],"id":"e75c0973-0b6a-441c-b7fd-159cdd2298fd","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"92e524d0-e847-4882-b2b8-6a9b13dd7254","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"5) Live Board — stream handler","type":"text"}],"id":"31c718f8-b219-44d1-9c99-fb90a662b999","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" Sends log messages to the terminal (stdout/stderr) in real time.","type":"text"}],"id":"f5b199a5-9ef6-47c6-ba05-274323bae870","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters in an interview:","type":"text"},{"styles":{},"text":" Essential during development so you can see what is happening as the job runs.","type":"text"}],"id":"44a48f89-6e73-4e3b-b699-2b21a1156ad9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"dd96a9dc-5c12-4b96-82c1-991600d103ef","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"stream_handler = logging.StreamHandler()\nstream_handler.setFormatter(formatter)\nlogger.addHandler(stream_handler)","type":"text"}],"id":"a263462a-b411-47ab-84c3-5bc656ee1477","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Rule: Attach both handlers to the same logger. Logs then go to both the file and the terminal simultaneously.","type":"text"}],"id":"ede4801b-e550-4482-9604-de524381f4bc","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"9c11266e-cb50-4df8-ac52-a4a6dbc7ad19","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"6) Log counts and pipeline milestones","type":"text"}],"id":"0dcefd95-a2a3-41cb-bd6a-10fbb0d3fafc","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" Using ","type":"text"},{"styles":{"code":true},"text":"logger.info()","type":"text"},{"styles":{},"text":" to report meaningful progress numbers — rows processed, rows skipped, job start/end.","type":"text"}],"id":"15578dd6-1e7a-4261-8b99-b3a40fa72ba4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters in an interview:","type":"text"},{"styles":{},"text":" Milestone logs are the minimum expected in any real pipeline. They make debugging much faster and show professional awareness.","type":"text"}],"id":"57b9be9f-cd93-4b11-9881-268c78d99d8d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"8f7ce62a-ea6d-48a2-ae93-412ecb40b3f0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"logger.info(\"Pipeline started\")\nlogger.info(f\"Rows fetched: {len(rows)}\")\nlogger.info(f\"Rows processed: {processed_count}\")\nlogger.warning(f\"Rows skipped (bad data): {skipped_count}\")\nlogger.info(\"Pipeline complete\")","type":"text"}],"id":"96eee2ef-0645-4b2c-b742-9d7528d5417e","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"a49d1a10-a41f-4f30-bcf7-fa0f0b34e69e","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"7) ","type":"text"},{"styles":{"code":true},"text":"logger.error(..., exc_info=True)","type":"text"}],"id":"c462aba6-68f1-4c06-8725-005d0c175110","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" Logs an error message and automatically appends the full traceback. The ","type":"text"},{"styles":{"code":true},"text":"exc_info=True","type":"text"},{"styles":{},"text":" argument captures the exception details so you can diagnose the problem from the log file alone.","type":"text"}],"id":"c4adeee1-4c35-4002-adc3-7208bd1be428","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters in an interview:","type":"text"},{"styles":{},"text":" Logging an error without ","type":"text"},{"styles":{"code":true},"text":"exc_info=True","type":"text"},{"styles":{},"text":" means losing the traceback — the most important debugging information. This is a near-guaranteed interview point.","type":"text"}],"id":"81e99362-80d8-4221-845b-a14d27637d58","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"5bb45832-5701-4a64-b656-42dea6366585","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"for row in rows:\n    try:\n        amount = float(row[\"amount\"])\n    except (ValueError, KeyError) as e:\n        logger.error(f\"Bad row skipped: {row}\", exc_info=True)\n        skipped_count += 1\n        continue","type":"text"}],"id":"520ba7ca-9749-4005-8c8d-986bd03f220a","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Rule: Always ","type":"text"},{"styles":{"code":true},"text":"exc_info=True","type":"text"},{"styles":{},"text":" inside an ","type":"text"},{"styles":{"code":true},"text":"except","type":"text"},{"styles":{},"text":" block. Without it, you log the message but lose the traceback.","type":"text"}],"id":"f32143f2-cbaa-4538-b293-dcc046ff415e","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"1b739b38-cbe0-44ab-8cf2-d5ad156dc04e","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Common mistakes","type":"text"}],"id":"45e31880-e064-4e56-90d4-5d766f340c51","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Mistake","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Fix","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Using ","type":"text"},{"styles":{"code":true},"text":"print()","type":"text"},{"styles":{},"text":" instead of ","type":"text"},{"styles":{"code":true},"text":"logging","type":"text"},{"styles":{},"text":" in a pipeline","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Use ","type":"text"},{"styles":{"code":true},"text":"logger.info()","type":"text"},{"styles":{},"text":" — print leaves no trace","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Using the root logger (","type":"text"},{"styles":{"code":true},"text":"logging.info()","type":"text"},{"styles":{},"text":") directly","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Use ","type":"text"},{"styles":{"code":true},"text":"logging.getLogger(__name__)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Not including ","type":"text"},{"styles":{"code":true},"text":"%(asctime)s","type":"text"},{"styles":{},"text":" in the format","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Always include a timestamp","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Forgetting ","type":"text"},{"styles":{"code":true},"text":"exc_info=True","type":"text"},{"styles":{},"text":" in ","type":"text"},{"styles":{"code":true},"text":"logger.error()","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Add it inside every ","type":"text"},{"styles":{"code":true},"text":"except","type":"text"},{"styles":{},"text":" block","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Attaching only a file handler or only a stream handler","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Attach both so logs go to file and terminal","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Not setting ","type":"text"},{"styles":{"code":true},"text":"logger.setLevel(logging.INFO)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Default level is WARNING — INFO messages are silently dropped","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Forgetting to log milestone counts","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Always log rows fetched, processed, and skipped","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"99608d66-b2f3-4031-8d93-95e264343851","props":{"textColor":"default"},"type":"table"},{"children":[],"id":"10bc42dc-c496-45f2-b84c-0d0b6b9e4cdc","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Practice ideas","type":"text"}],"id":"70233a1d-c607-4cff-8dd2-6b8952a27181","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Create a logger with ","type":"text"},{"styles":{"code":true},"text":"__name__","type":"text"},{"styles":{},"text":", attach both a file handler and stream handler with a format that includes ","type":"text"},{"styles":{"code":true},"text":"%(asctime)s","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"3c975df0-8716-491f-bab8-f6bd3fd4ef5b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Write three log lines: one ","type":"text"},{"styles":{"code":true},"text":"INFO","type":"text"},{"styles":{},"text":", one ","type":"text"},{"styles":{"code":true},"text":"WARNING","type":"text"},{"styles":{},"text":", one ","type":"text"},{"styles":{"code":true},"text":"ERROR","type":"text"},{"styles":{},"text":" with ","type":"text"},{"styles":{"code":true},"text":"exc_info=True","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"ccc3bd97-c6a1-42e8-bf86-8e105278ad93","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Wrap a type conversion in ","type":"text"},{"styles":{"code":true},"text":"try/except","type":"text"},{"styles":{},"text":" and log the error with ","type":"text"},{"styles":{"code":true},"text":"exc_info=True","type":"text"},{"styles":{},"text":" when it fails.","type":"text"}],"id":"6560f84f-9742-40d1-b883-6e8cd5c784bb","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Add milestone logs: job start, rows fetched count, rows skipped count, job complete.","type":"text"}],"id":"7206f60a-48a6-49e9-b105-8f7d553c6dc4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Open the generated ","type":"text"},{"styles":{"code":true},"text":".log","type":"text"},{"styles":{},"text":" file and confirm all entries have timestamps and the right level labels.","type":"text"}],"id":"bd2f8050-ac03-46a9-9ef7-cd2b7bd39a9b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"id":"efd59cbe-2436-4d0f-ac16-70b97d41c755","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Final integrated coding example","type":"text"}],"id":"83dd2cb0-ee1b-4477-8589-e2476410b35e","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Scenario:","type":"text"},{"styles":{},"text":" A small pipeline reads a list of order rows, processes each one, skips bad rows, and logs every milestone and error to both a file and the terminal.","type":"text"}],"id":"b0c997af-3970-44ff-bac9-b0e46a31ebee","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"import logging\n\n# --- Desk Register: create a named logger ---\nlogger = logging.getLogger(__name__)\nlogger.setLevel(logging.INFO)\n\n# --- Timestamp Stamp: define the format ---\nformatter = logging.Formatter(\n    \"%(asctime)s | %(levelname)s | %(name)s | %(message)s\"\n)\n\n# --- Paper Trail: log to a file ---\nfile_handler = logging.FileHandler(\"pipeline.log\")\nfile_handler.setFormatter(formatter)\nlogger.addHandler(file_handler)\n\n# --- Live Board: log to the terminal ---\nstream_handler = logging.StreamHandler()\nstream_handler.setFormatter(formatter)\nlogger.addHandler(stream_handler)\n\n# --- Simulated incoming rows ---\nrows = [\n    {\"order_id\": \"1\", \"amount\": \"250.0\"},\n    {\"order_id\": \"2\", \"amount\": \"bad_value\"},   # will fail\n    {\"order_id\": \"3\", \"amount\": \"\"},             # will fail\n    {\"order_id\": \"4\", \"amount\": \"180.5\"},\n]\n\n# --- Info Bell: pipeline start milestone ---\nlogger.info(\"Pipeline started\")\nlogger.info(f\"Rows fetched: {len(rows)}\")\n\nprocessed_count = 0\nskipped_count = 0\n\nfor row in rows:\n    try:\n        amount = float(row[\"amount\"])   # risky cast\n        processed_count += 1\n\n    except (ValueError, KeyError) as e:\n        # --- Error Alarm: log the full traceback ---\n        logger.error(f\"Bad row skipped: {row}\", exc_info=True)\n        skipped_count += 1\n        continue\n\n    # --- Warning Flag: unusual but not fatal ---\n    if amount > 200:\n        logger.warning(f\"Unusually high amount in order {row[''order_id'']}: {amount}\")\n\n# --- Info Bell: pipeline end milestones ---\nlogger.info(f\"Rows processed successfully: {processed_count}\")\nlogger.warning(f\"Rows skipped (bad data): {skipped_count}\")\nlogger.info(\"Pipeline complete\")","type":"text"}],"id":"15f0630f-82d1-42ff-8fd3-30843a46c1f9","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Sample output (terminal and ","type":"text"},{"styles":{"code":true},"text":"pipeline.log","type":"text"},{"styles":{"bold":true},"text":"):","type":"text"}],"id":"654be0de-dc3c-44b3-9028-b9405108312b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"2025-01-15 12:34:56,001 | INFO    | __main__ | Pipeline started\n2025-01-15 12:34:56,002 | INFO    | __main__ | Rows fetched: 4\n2025-01-15 12:34:56,003 | WARNING | __main__ | Unusually high amount in order 1: 250.0\n2025-01-15 12:34:56,004 | ERROR   | __main__ | Bad row skipped: {''order_id'': ''2'', ''amount'': ''bad_value''}\nTraceback (most recent call last):\n  ...\nValueError: could not convert string to float: ''bad_value''\n2025-01-15 12:34:56,005 | ERROR   | __main__ | Bad row skipped: {''order_id'': ''3'', ''amount'': ''''}\n...\n2025-01-15 12:34:56,006 | INFO    | __main__ | Rows processed successfully: 2\n2025-01-15 12:34:56,007 | WARNING | __main__ | Rows skipped (bad data): 2\n2025-01-15 12:34:56,008 | INFO    | __main__ | Pipeline complete","type":"text"}],"id":"b58d8498-93c6-49f3-bd53-d17e6e2b7ef0","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"What each section maps to:","type":"text"}],"id":"79e67e11-4572-41d5-92d8-e69dbcd68ef3","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Code section","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Metaphor part","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"logging.getLogger(__name__)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Desk Register","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"%(asctime)s","type":"text"},{"styles":{},"text":" in formatter","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Timestamp Stamp","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"FileHandler(\"pipeline.log\")","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Paper Trail","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"StreamHandler()","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Live Board","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"logger.info(...)","type":"text"},{"styles":{},"text":" for milestones and counts","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Info Bell","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"logger.warning(...)","type":"text"},{"styles":{},"text":" for unusual values","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Warning Flag","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{"code":true},"text":"logger.error(..., exc_info=True)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Error Alarm","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"33a48cfe-73c4-4e67-86da-f68d86422994","props":{"textColor":"default"},"type":"table"},{"children":[],"id":"2632a0d3-37b2-4540-9195-60cfafd674b7","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"italic":true},"text":"If you can write this script from memory — especially remembering ","type":"text"},{"styles":{"code":true},"text":"exc_info=True","type":"text"},{"styles":{"italic":true},"text":", both handlers, and milestone count logs — you are ready for internship-level logging questions at the Incident Desk.","type":"text"}],"id":"51b4d2d3-d7ea-442a-8e7f-48ad793921a2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[],"id":"3c1da17b-33a8-474f-af09-98a636904b53","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"}]'::jsonb, '3e9e3dd3-a59b-4b02-968a-ee95e7317583') ON CONFLICT ("node_id") DO UPDATE SET "bad_example" = EXCLUDED."bad_example", "completed_at" = EXCLUDED."completed_at", "created_at" = EXCLUDED."created_at", "definition" = EXCLUDED."definition", "good_example" = EXCLUDED."good_example", "is_completed" = EXCLUDED."is_completed", "key_points" = EXCLUDED."key_points", "last_edited" = EXCLUDED."last_edited", "map_id" = EXCLUDED."map_id", "mental_model" = EXCLUDED."mental_model", "notes" = EXCLUDED."notes", "resources" = EXCLUDED."resources", "rich_content" = EXCLUDED."rich_content", "user_id" = EXCLUDED."user_id";
INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-06-13T15:34:22.825181+00:00', '', '', '2df00080-f276-414a-a640-5efe6274bba3', false, '[]'::jsonb, '2026-06-13T15:34:23.806+00:00', '2ad473fe-77dd-481e-8ba7-4b2b0336173f', '', '773c5f12-b391-4d9b-a92c-43411bd15c73', '', '[]'::jsonb, '[{"children":[],"content":[{"styles":{},"text":"Python for Data Engineering — Topic 17: The Re-Run Rule","type":"text"}],"id":"3bf79476-2174-4100-bc23-569118bedb3d","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Idempotency","type":"text"}],"id":"d0e410e7-a4ad-408d-b911-1d00de634c24","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"id":"52299fd9-35cf-4835-8665-d35bc66b65e9","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Very short intro","type":"text"}],"id":"ff7cc8ba-9c39-4d1d-8ac5-2b2218da1060","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"At the ","type":"text"},{"styles":{"bold":true},"text":"Distribution Hub","type":"text"},{"styles":{},"text":", the ","type":"text"},{"styles":{"bold":true},"text":"Re-Run Rule","type":"text"},{"styles":{},"text":" is simple: if something goes wrong and we have to run the job again, the final result must be exactly the same as if it had run only once. A ","type":"text"},{"styles":{"bold":true},"text":"same load badge","type":"text"},{"styles":{},"text":" means the same input arrives. A ","type":"text"},{"styles":{"bold":true},"text":"same output stamp","type":"text"},{"styles":{},"text":" means we get the same output. ","type":"text"},{"styles":{"bold":true},"text":"No double drop","type":"text"},{"styles":{},"text":" means no extra copies of data appear. ","type":"text"},{"styles":{"bold":true},"text":"No extra side effects","type":"text"},{"styles":{},"text":" means the world outside does not change unexpectedly. The ","type":"text"},{"styles":{"bold":true},"text":"replace bin","type":"text"},{"styles":{},"text":" and ","type":"text"},{"styles":{"bold":true},"text":"upsert gate","type":"text"},{"styles":{},"text":" are the patterns that keep idempotency safe. Topic 17 is the minimum idempotency knowledge an internship interviewer will expect you to explain.","type":"text"}],"id":"7378f3c3-9a1c-4da8-8152-657aa78c3a11","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"73e2dd06-7fd3-44c0-9b46-303452b27cae","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Mind map","type":"text"}],"id":"98d5828e-68b4-47b1-8877-1fb5af11fe60","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"RE-RUN RULE\n(Idempotency)\n│\n├── Definition\n│   └── Run once or run 10 times = same result\n│\n├── Same Load Badge\n│   └── same input data\n│\n├── Same Output Stamp\n│   └── same output every time\n│\n├── No Double Drop\n│   └── no duplicate rows\n│\n├── No Extra Side Effects\n│   └── no unexpected changes to external systems\n│\n├── Replace Bin\n│   └── replace the entire partition\n│\n└── Upsert Gate\n    └── MERGE / UPSERT (update if exists, insert if new)","type":"text"}],"id":"52e15ff4-f029-4643-ae60-67c72c002844","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"ed04bdd8-f27c-4b73-be6e-5de047f9298c","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Decision tree","type":"text"}],"id":"7dab6782-924d-4365-8fc3-629e10e9c31e","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Does a job need to be re-runnable safely?\n└── YES — always. Design for idempotency.\n\nHow do you make a job idempotent?\n│\n├── Use the same input\n│   └── process the same date, same files\n│\n├── Produce the same output\n│   └── no randomness, no \"now()\", no counters\n│\n├── Prevent duplicates\n│   └── Replace Bin: replace entire partition data\n│       OR\n│       Upsert Gate: use MERGE / UPSERT to handle re-runs\n│\n└── No side effects\n    └── Do not send emails, delete files, update external systems\n        (unless the job itself is re-runnable)","type":"text"}],"id":"09fac27f-7f82-4872-9023-6ebbe986fe7a","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"f4f8e2e7-f656-4deb-ae34-c522b8a79716","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Concept breakdown","type":"text"}],"id":"e55df646-791d-47d8-86d1-8e7a6de3adea","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"id":"f352b11e-9bde-451d-a9e8-8e1e0b81d5b2","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"1) Definition of idempotency","type":"text"}],"id":"284155eb-95cc-4389-895e-6466d0c6ed5c","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" A job is idempotent if running it once, twice, or 10 times with the same input produces exactly the same final state. No extra data, no missing data, no duplicates.","type":"text"}],"id":"e7d040d6-ca48-43bd-a3de-8060755be99f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters in an interview:","type":"text"},{"styles":{},"text":" Idempotency is a core DE principle. Network failures, crashes, and retries are inevitable. Jobs must be safe to re-run. Interviewers will ask you to explain why this matters.","type":"text"}],"id":"07184784-1659-485f-a157-29e856041915","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Plain-language example:","type":"text"}],"id":"5be28e03-5973-4d6e-aa4c-cf1f6472165e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"\"If I run an orders pipeline on 2025-01-15 and it crashes halfway through, I should be able to re-run it on the same date and get the same result as if it had run perfectly the first time. Not with double data. Not with missing data. Exactly the same.\"","type":"text"}],"id":"c554f878-ae75-4b7d-8fd2-e15a0d723ae5","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"bb8ccdf1-3c7a-4573-9737-020bcf377a2e","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"2) Same Load Badge — same input","type":"text"}],"id":"584cf05a-0a35-41f4-81dc-dcadc853b5de","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" The job receives the same input every time it runs. This is the starting point for idempotency.","type":"text"}],"id":"52c679ac-9bc5-4d42-abbe-644eee4a05a3","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters in an interview:","type":"text"},{"styles":{},"text":" Without consistent input, you cannot guarantee consistent output. Parameterizing by date, batch ID, or file list is how you ensure same input on re-runs.","type":"text"}],"id":"491d5e5e-050d-4322-adf2-3001651353c9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Plain-language example:","type":"text"}],"id":"0b465593-67dd-4509-9a15-185840303622","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"\"If the job is parameterized with ","type":"text"},{"styles":{"code":true},"text":"--date 2025-01-15","type":"text"},{"styles":{},"text":", every re-run processes the exact same orders file for that date. Same input, every time.\"","type":"text"}],"id":"b4fccb92-8cfa-43dc-be56-c1cdd8598a1b","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"9aa0b6a2-3ef9-4c67-9cf9-c921095e9c3d","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"3) Same Output Stamp — same output every time","type":"text"}],"id":"f510bfa1-1ffe-49f4-9e6c-d9fc5c989da7","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" Given the same input, the job always produces the same output. No randomness, no time-dependent values (unless time is part of the input).","type":"text"}],"id":"ed2b9256-a18f-4e1f-99b5-8c9589918727","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters in an interview:","type":"text"},{"styles":{},"text":" If output changes on re-run, the job is not idempotent. Avoid ","type":"text"},{"styles":{"code":true},"text":"datetime.now()","type":"text"},{"styles":{},"text":", random numbers, or external API calls unless they are deterministic.","type":"text"}],"id":"1caf2b14-8cb8-4ede-8e8d-523261f620cb","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Plain-language example:","type":"text"}],"id":"ce7472e0-c837-46f5-9ecc-dff5e5ecc1db","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"\"If I filter orders by status=''shipped'' and calculate their total, the result is always the same. Not a different total because the time is different. Same data, same math, same answer.\"","type":"text"}],"id":"338299b3-d29f-484c-b159-7baf72dd3d95","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"16c8dbf8-abd5-4cb6-9e89-442210bc6ff8","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"4) No Double Drop — no duplicates","type":"text"}],"id":"c9b2806a-2e08-4ce9-b15a-54ede666eb27","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" Re-running the job does not create duplicate rows in the output. The data is exactly right, not doubled or tripled.","type":"text"}],"id":"516e16c5-124e-46e9-9acb-70108a10b385","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters in an interview:","type":"text"},{"styles":{},"text":" Duplicates are a very common failure mode. Interviewers will ask how you prevent them.","type":"text"}],"id":"3326dc16-a246-41d9-84ea-db30d3026d41","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Plain-language example:","type":"text"}],"id":"47976ab9-18cb-48db-9028-f404287818fd","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"\"If the job is re-run and inserts 1,000 orders twice, that is not idempotent — there are now 2,000 orders. Idempotent means still exactly 1,000.\"","type":"text"}],"id":"515b6e2c-cd6a-406a-9997-feb8b5602341","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"45a824f8-a3da-43c5-b60a-91856532c1c2","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"5) No Extra Side Effects — no unexpected changes","type":"text"}],"id":"5923f2f6-c45e-4e15-a634-656fffa4ea59","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" Re-running the job does not accidentally send emails twice, delete files twice, or update external systems unexpectedly. The job only changes the intended output.","type":"text"}],"id":"cbd897d1-dac2-46c9-888e-f3cf7d8be7f5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters in an interview:","type":"text"},{"styles":{},"text":" Side effects are dangerous. Safe jobs are self-contained: they read input, transform, write output. Nothing else.","type":"text"}],"id":"d865763c-2500-4345-97f8-018c80b94712","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Plain-language example:","type":"text"}],"id":"35d4736b-3230-4907-a65d-8ac1909bbdc5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"\"If the job sends an email notification on success, re-running should not send it twice. Either the job is designed not to send (idempotent), or the email system checks for duplicates (idempotent).\"","type":"text"}],"id":"40b52559-b080-4d4b-a256-91c798e39123","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"d7e7195f-b037-43f9-8a7f-888b70e7a2ab","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"6) Replace Bin — replacing partition data","type":"text"}],"id":"a3f89e4c-c1aa-4d3c-9e83-f1b66ca239ba","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" Instead of inserting rows, delete the entire partition and write fresh data. On re-run, the old partition is replaced with new data.","type":"text"}],"id":"e7f7bb3e-deb9-473c-ace2-55a9af58d24f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters in an interview:","type":"text"},{"styles":{},"text":" This is the simplest idempotent pattern. It guarantees no duplicates because old data is deleted first.","type":"text"}],"id":"24b1380d-a703-44e5-83b2-135c80a6f54d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Plain-language example:","type":"text"}],"id":"be901ae1-19a3-42b3-8fa5-422d7eb1a17a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"\"If the job processes orders for 2025-01-15 and stores them in ","type":"text"},{"styles":{"code":true},"text":"year=2025/month=01/day=15/","type":"text"},{"styles":{},"text":", it deletes the entire day''s folder first, then writes new data. On re-run: delete, write. Same result. No duplicates.\"","type":"text"}],"id":"dd35e53a-c278-4395-b901-c07e12d268b1","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"4a700b17-1c47-4bc2-8cf4-264c979ee03d","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"7) Upsert Gate — MERGE / UPSERT","type":"text"}],"id":"0fa76a51-e77d-49c7-a4d8-708090623be8","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" An SQL pattern that says: \"If the record exists, update it. If it does not exist, insert it.\" This handles re-runs gracefully without duplicates.","type":"text"}],"id":"637b0e87-c69c-45e5-92fc-4e4412291a19","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters in an interview:","type":"text"},{"styles":{},"text":" MERGE / UPSERT is a more sophisticated alternative to replace. It is common in databases. Knowing when to use it shows maturity.","type":"text"}],"id":"e87dc691-1ade-49c3-ae21-e2d947b5123d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Plain-language example:","type":"text"}],"id":"ac1a021f-677b-404c-9fea-aeb8a4b9f2b4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"\"If the job writes customer summaries to a database using UPSERT, re-running processes the same customers. The database checks: does customer_id=123 exist? If yes, update it. If no, insert it. Either way, one row per customer. No duplicates.\"","type":"text"}],"id":"8998c10e-1da4-4d6e-86da-fcd8144d8206","props":{"backgroundColor":"default","textColor":"default"},"type":"quote"},{"children":[],"id":"e73d0896-e9d1-4040-ab63-d3a42967d9c1","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Common mistakes","type":"text"}],"id":"bbe58f30-b217-4862-8c78-0723331ae301","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Mistake","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Fix","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Thinking idempotency is optional","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Every pipeline job should be idempotent. It is a core principle.","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Using ","type":"text"},{"styles":{"code":true},"text":"datetime.now()","type":"text"},{"styles":{},"text":" in the logic","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Use the input date instead. Make it a parameter.","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Inserting rows without checking for duplicates","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Use MERGE/UPSERT or replace the partition.","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Keeping old data and adding new data","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Delete old partition data first, then write new.","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Sending emails or webhooks without a guard","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"If the job is re-runnable, do not trigger external actions. Or make the action idempotent too.","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Not testing re-runs","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Always test: run the job, run it again on the same input, confirm same result.","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"61373809-02e6-465a-ba2d-c699bd12714e","props":{"textColor":"default"},"type":"table"},{"children":[],"id":"7e6635b6-70b8-4784-a67e-1b40fef58559","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Practice ideas","type":"text"}],"id":"772ef620-38ab-4df0-a218-7d0bcafcf3bc","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Explain idempotency in one sentence. (Hint: \"Running once or 10 times gives the same result.\")","type":"text"}],"id":"8ae0ce61-a349-46cc-9dac-6bcade4ac637","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Explain why a job that inserts rows without checking for duplicates is not idempotent.","type":"text"}],"id":"ddd00a3d-ab1c-4027-abc2-4425b0b6b532","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Explain the difference between \"replace partition\" and \"MERGE/UPSERT\" in one sentence each.","type":"text"}],"id":"97dfa0a0-1dd2-4346-b8f8-5a459c1a2ced","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Describe a non-idempotent job (e.g., one that increments a counter every run). How would you fix it?","type":"text"}],"id":"434070b0-0379-42e7-b1d4-e34ba3e20603","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Explain why parameterizing by date (not by ","type":"text"},{"styles":{"code":true},"text":"datetime.now()","type":"text"},{"styles":{},"text":") is important for idempotency.","type":"text"}],"id":"42decfe3-3e49-4f2c-87ec-ae70dfe6f4d9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"id":"dbc3e5c1-fea1-479d-9ea3-1649a1f1ba41","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Final integrated explanation example","type":"text"}],"id":"f592d4c7-c707-40ef-b157-fcdd5c0988ac","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Scenario:","type":"text"},{"styles":{},"text":" An orders pipeline runs daily. It fetches orders from an API for a specific date, cleans them, and writes them to a data lake partitioned by date. The job sometimes crashes and needs to be re-run. The business requires idempotency.","type":"text"}],"id":"a106ca98-5145-4f37-bcbd-6e1e0beddae2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"2654d603-5eb7-4c81-8408-5449406df494","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"The Re-Run Rule in action:","type":"text"}],"id":"c0de5c4e-5d98-4cc5-9007-e4f0880e2981","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Day 1: Normal run","type":"text"}],"id":"d6ba8252-d66a-45d7-9b73-5ada29deb8ea","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Same Load Badge:","type":"text"},{"styles":{},"text":" Job receives input parameter ","type":"text"},{"styles":{"code":true},"text":"--date 2025-01-15","type":"text"},{"styles":{},"text":". Fetches all orders for that date from the API.","type":"text"}],"id":"694daae9-e298-4b24-ad0e-cb4f56310c48","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Same Output Stamp:","type":"text"},{"styles":{},"text":" Cleans the data deterministically. Filters by status, calculates totals. No ","type":"text"},{"styles":{"code":true},"text":"datetime.now()","type":"text"},{"styles":{},"text":". No random selection. Same input = same transformations = same output.","type":"text"}],"id":"d5a11340-ad76-46ab-aad7-a3fe9cbb8c76","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Replace Bin:","type":"text"},{"styles":{},"text":" Instead of appending rows to the data lake, the job deletes the entire partition folder ","type":"text"},{"styles":{"code":true},"text":"year=2025/month=01/day=15/","type":"text"},{"styles":{},"text":" first, then writes fresh data.","type":"text"}],"id":"cae1362d-200f-440c-bf15-bb37ef942d6f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"No Double Drop:","type":"text"},{"styles":{},"text":" The partition now has exactly 1,000 orders for that date. No duplicates.","type":"text"}],"id":"e177bf14-e1e3-4968-a1e7-01a35e4ad36f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"No Extra Side Effects:","type":"text"},{"styles":{},"text":" The job only reads from the API and writes to the data lake. It does not send emails or update external systems (or those actions are themselves idempotent).","type":"text"}],"id":"75ab38ac-d6c3-49e2-b05d-8cfbd15f586e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Day 1: Job crashes at 80% complete","type":"text"}],"id":"7aa795db-6f0d-41a8-838d-33fd4bbc6049","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"The data lake partition is partially written (800 orders). The job stops.","type":"text"}],"id":"94110369-1c06-4671-8bdf-5c7a2b2860a0","props":{"backgroundColor":"default","start":6,"textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Re-run on same input:","type":"text"},{"styles":{},"text":" Engineer runs the job again with ","type":"text"},{"styles":{"code":true},"text":"--date 2025-01-15","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"be5af36d-5f64-45bd-b7c0-587f5231e206","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Same input (same date), same output (same API data), same replace operation. The partition folder is deleted again, fresh data is written again.","type":"text"}],"id":"1cf46cbf-9596-4c32-920b-e1e3312d8cd4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Result:","type":"text"},{"styles":{},"text":" The partition now has exactly 1,000 orders. Not 1,800 (800 old + 1,000 new). Not corrupted. Exactly as if the job had run perfectly the first time.","type":"text"}],"id":"9af71f15-cc65-4ec3-9823-6330d1ce4b5c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"id":"0af6ecd9-7a7c-4c31-8b1f-898a01952990","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"Alternative: Upsert Gate pattern","type":"text"}],"id":"6f925447-71ad-4175-8d24-019f1b62b9e0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Instead of replacing the partition, the job could use MERGE/UPSERT:","type":"text"}],"id":"2ad714ed-3235-45e6-8de6-5fa36410ba39","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Job reads API orders for 2025-01-15 and prepares them for the database.","type":"text"}],"id":"4e2ee6e6-3888-4fd0-83fc-a622e84085cf","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"MERGE statement: \"For each order, check if order_id already exists in the database. If yes, update it. If no, insert it.\"","type":"text"}],"id":"56f98b8b-890a-4fe4-bef0-699999389878","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"First run: All 1,000 orders are inserted (they do not exist yet).","type":"text"}],"id":"5d99a893-b4a4-4a19-bfcf-703c6f9322ae","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Job crashes at 80%.","type":"text"}],"id":"f27cbfcf-eddd-437e-9f1e-7dd13c40ea3f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Re-run on same date: MERGE again. The first 800 rows that already exist are updated (idempotent — same data, no change). The remaining 200 rows are inserted.","type":"text"}],"id":"4494e211-bc64-4031-b6c0-31cedf9759ad","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Result:","type":"text"},{"styles":{},"text":" Exactly 1,000 rows in the database. Same as if the job had run once.","type":"text"}],"id":"8ec8ac10-2c41-46e7-bb4c-43466c6d8c28","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"id":"18336854-fbe4-4dd5-93d9-93a780b60929","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"Key principles:","type":"text"}],"id":"1ae8a727-3d9f-4251-8657-a110a28ddca6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Same input","type":"text"},{"styles":{},"text":" (parameterized by date, not ","type":"text"},{"styles":{"code":true},"text":"datetime.now()","type":"text"},{"styles":{},"text":")","type":"text"}],"id":"7e716c66-500f-478b-b4dc-1d8f4510d236","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Same output","type":"text"},{"styles":{},"text":" (deterministic transformations)","type":"text"}],"id":"002d1fcd-ecad-4375-ae9f-572e8385fc40","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"No duplicates","type":"text"},{"styles":{},"text":" (replace partition OR use MERGE/UPSERT)","type":"text"}],"id":"21ccb32b-1d9f-459d-ad81-7a54ba52808e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"No side effects","type":"text"},{"styles":{},"text":" (only read + transform + write, all idempotent)","type":"text"}],"id":"beb67112-ccac-41dc-a037-ec705d79a234","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Safe to re-run","type":"text"},{"styles":{},"text":" (crashes do not corrupt data, re-runs are free)","type":"text"}],"id":"70ddf11e-01e4-4b59-9a1e-f9ad79bfaa8d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"id":"07e25a03-286d-40e2-8104-64eab94f1f1a","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"italic":true},"text":"If you can explain this scenario in under 2 minutes — covering same input, same output, replace partition or MERGE/UPSERT, and why idempotency matters — you are ready for idempotency questions in an internship interview.","type":"text"}],"id":"b5f6a6f1-0a4c-4ce4-afc2-b6ff15d5b8c9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[],"id":"3ce66720-2731-487e-9796-bb0c2b7151d7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"}]'::jsonb, '3e9e3dd3-a59b-4b02-968a-ee95e7317583') ON CONFLICT ("node_id") DO UPDATE SET "bad_example" = EXCLUDED."bad_example", "completed_at" = EXCLUDED."completed_at", "created_at" = EXCLUDED."created_at", "definition" = EXCLUDED."definition", "good_example" = EXCLUDED."good_example", "is_completed" = EXCLUDED."is_completed", "key_points" = EXCLUDED."key_points", "last_edited" = EXCLUDED."last_edited", "map_id" = EXCLUDED."map_id", "mental_model" = EXCLUDED."mental_model", "notes" = EXCLUDED."notes", "resources" = EXCLUDED."resources", "rich_content" = EXCLUDED."rich_content", "user_id" = EXCLUDED."user_id";
INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-06-14T07:05:53.069349+00:00', '', '', '3df117cc-8168-41a0-bdd0-c12ee28eeda9', false, '[]'::jsonb, '2026-06-14T07:05:55.294+00:00', '2ad473fe-77dd-481e-8ba7-4b2b0336173f', '', '1fdd92ef-fba4-4809-af77-4bcf3806df65', '', '[]'::jsonb, '[{"children":[],"content":[{"styles":{},"text":"SQL for Data Engineering — Internship Study Note","type":"text"}],"id":"aa41ec87-cc74-40dd-b5cd-150b6a13eb51","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Topic 5: The Panel of Switches","type":"text"}],"id":"d7f4932f-9b63-4fa4-818d-6de3a8504a66","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"id":"3698a9e2-044a-4b9d-9030-d403ae58590b","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"What This Note Is","type":"text"}],"id":"a85eb88b-7e74-47fc-9696-55d1e87f2bc2","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Inside the Control Room, the ","type":"text"},{"styles":{"bold":true},"text":"Panel of Switches","type":"text"},{"styles":{},"text":" is the station that routes each row to the right output based on conditions. The Selector (CASE) opens the panel. Each Switch (WHEN branch) is a condition that is tested from top to bottom. The first Switch that is TRUE fires its result. If no Switch fires, the Default Switch (ELSE) catches the row. If there is no ELSE and no Switch fires, the row gets NULL. This is what CASE WHEN does — and it is one of the most frequently tested SQL patterns in internship interviews.","type":"text"}],"id":"ef266abb-e019-41c4-96f0-2c3bed392806","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"70f78b9a-f671-4325-9059-396767dc42d4","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Mind Map","type":"text"}],"id":"41919dd0-694f-402c-a726-77582a9e62dc","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"                      PANEL OF SWITCHES\n                         (CASE WHEN)\n                              │\n          ┌───────────────────┼───────────────────┐\n          │                   │                   │\n       ANATOMY            EVALUATION          3 PATTERNS\n          │                   │                   │\n    SELECTOR (CASE)    Top to bottom          1. Bucketing\n    SWITCH (WHEN)      First match wins       (label each row)\n    THEN result        Remaining switches          │\n    DEFAULT (ELSE)     are skipped            2. Conditional\n    END closes panel   No match + no ELSE      Aggregation\n                       → NULL                 (SUM with filter)\n                                                   │\n                                             3. Conditional\n                                              Counting\n                                             (COUNT with filter)\n\n          │\n          └──── Can appear in ────────────────────┐\n                                                  │\n                  ┌──────────────┬────────────────┴──┐\n                  │              │                    │\n               SELECT         GROUP BY            ORDER BY\n             (label rows)   (group by tier)      (sort by label)\n                              HAVING\n                           (filter by tier)","type":"text"}],"id":"41824067-7d5d-4909-987b-534271473e01","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"583a145d-b7b9-4067-bc2f-e5f090a9fa0d","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Decision Tree","type":"text"}],"id":"508bd176-a901-47d8-ae0f-53bf16ff52a5","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"START: You need conditional logic per row in SQL\n          │\n          ▼\nDo you need to label or categorize each row differently\nbased on its values?\n    YES → Use CASE WHEN for bucketing\n          (Switch on the value, assign a label in THEN)\n    NO  → Continue\n          │\n          ▼\nDo you need to SUM or AVG only rows that meet a condition,\nwithout filtering the whole query?\n    YES → Use CASE WHEN inside SUM() or AVG()\n          → SUM(CASE WHEN condition THEN value ELSE 0 END)\n    NO  → Continue\n          │\n          ▼\nDo you need to COUNT only rows that meet a condition?\n    YES → Use CASE WHEN inside COUNT()\n          → COUNT(CASE WHEN condition THEN 1 END)\n          Note: COUNT ignores NULLs, so no ELSE needed\n    NO  → Continue\n          │\n          ▼\nDoes your CASE WHEN have multiple conditions?\n    YES →\n        Are the conditions mutually exclusive?\n            YES → Order does not matter, but most specific first is safer\n            NO  → Put the most specific condition first\n                  (first match wins, rest are skipped)\n          │\n          ▼\nDid you close the CASE with END?\n    NO  → Add END (missing END is a syntax error)\n    YES → Done\n          │\n          ▼\nDid you include ELSE?\n    NO  → Rows matching no condition will return NULL (may be intentional)\n    YES → Those rows get the ELSE value","type":"text"}],"id":"b92358be-7eb2-4f5c-afb1-4bcc30c6e990","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"a28acaf1-a85b-4635-81ac-35605a1c1349","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Concept Breakdown","type":"text"}],"id":"4c7edb5d-ce6f-4ed5-a978-7c6fcec36f8a","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"id":"23268561-62d9-402f-92ae-3a9aed44d59b","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"1. What CASE WHEN Is","type":"text"}],"id":"17338393-6696-4bd1-9729-269e41952233","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" CASE WHEN is SQL''s conditional expression. It evaluates conditions one at a time from top to bottom and returns the result of the first condition that is TRUE. It is not a statement — it is an expression, meaning it produces a value and can appear anywhere a value can appear: SELECT, WHERE, GROUP BY, ORDER BY, inside aggregate functions.","type":"text"}],"id":"35912a20-af2a-4d54-90de-fc00740cf9c8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters:","type":"text"},{"styles":{},"text":" CASE WHEN is in almost every real data query. Interviewers use it to test whether you can apply logic inside SQL rather than pulling raw data and processing it in Python.","type":"text"}],"id":"54d7b1c6-6bcb-46ac-8c6b-3a5ceea778d4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"8e94eb3d-5d07-402a-bedd-fb76d35dfe5b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"SELECT\n    order_id,\n    amount,\n    CASE\n        WHEN amount >= 1000 THEN ''high''\n        WHEN amount >= 500  THEN ''medium''\n        ELSE                     ''low''\n    END AS order_tier          -- Selector opens, Switches test, Default catches rest\nFROM orders;","type":"text"}],"id":"6b73a911-7242-4da0-8eb7-8f045fad6f2a","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"id":"e1a37941-e1f2-4ba0-bb8b-e9283f479c67","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"2. Simple Syntax — CASE ... WHEN ... THEN ... ELSE ... END","type":"text"}],"id":"025e4403-0a97-4ffe-bf66-99630b9a826a","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" The complete structure of a CASE expression:","type":"text"}],"id":"99ea066c-a3eb-4816-95ef-93e19bb7c79d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"CASE\n    WHEN condition_1 THEN result_1\n    WHEN condition_2 THEN result_2\n    ...\n    ELSE default_result          -- optional but recommended\nEND","type":"text"}],"id":"d3826d4f-e553-4824-a7b9-78652eb07cd6","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"Every CASE must be closed with END. ELSE is optional — without it, unmatched rows return NULL.","type":"text"}],"id":"95d57413-425c-4e60-b6a8-04c656fd207f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters:","type":"text"},{"styles":{},"text":" Syntax errors in CASE WHEN (missing END, wrong keyword order) are immediate red flags in an interview. Know the structure by heart.","type":"text"}],"id":"2c26bb59-f3d5-499e-a0d5-0955da95b6ae","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"22432130-02b8-4ff4-adc5-ea926fd158d5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"SELECT\n    employee_id,\n    CASE\n        WHEN department = ''engineering'' THEN ''tech''\n        WHEN department = ''marketing''   THEN ''commercial''\n        ELSE                                 ''other''\n    END AS department_group\nFROM employees;","type":"text"}],"id":"037ec5d8-b843-43ed-a63e-938203d3b4f5","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"id":"6cd0b121-cb6b-48d6-825f-52071ee108b1","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"3. Top-to-Bottom Evaluation — First Match Wins","type":"text"}],"id":"59b41474-ac45-4e1f-84bd-5d8b0096d0b0","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" SQL evaluates each WHEN condition in order. The moment one condition is TRUE, that THEN value is returned and the rest of the Switches are ignored. This means condition order matters when ranges overlap.","type":"text"}],"id":"b6e863b9-ab11-4efa-bc65-100dc4a6c51c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters:","type":"text"},{"styles":{},"text":" A common interview mistake is writing overlapping conditions in the wrong order, causing rows to be caught by the wrong Switch. This is tested with bucketing questions.","type":"text"}],"id":"8b3351cb-a2a6-434c-9d3e-00a40c11d35e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"0dae7a2c-75ee-41e1-b1ce-8098a80d9984","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"-- WRONG order: every row with amount >= 500 matches the first switch,\n-- the ''high'' tier is never reached\nSELECT\n    CASE\n        WHEN amount >= 500  THEN ''medium''   -- catches amounts >= 1000 too\n        WHEN amount >= 1000 THEN ''high''     -- never fires\n        ELSE                     ''low''\n    END AS tier\nFROM orders;\n\n-- CORRECT order: most specific (largest threshold) first\nSELECT\n    CASE\n        WHEN amount >= 1000 THEN ''high''     -- fires first for large amounts\n        WHEN amount >= 500  THEN ''medium''   -- only fires if amount < 1000\n        ELSE                     ''low''\n    END AS tier\nFROM orders;","type":"text"}],"id":"79bc7065-c5b2-49db-a1b3-a4c041b537bf","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"id":"7d2cb82d-d88a-4148-99e3-11c2eba7e134","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"4. Pattern 1 — Bucketing / Categorizing Values","type":"text"}],"id":"c901c1c9-d0bc-4fe1-9b7a-92204c84e7b8","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" Use CASE WHEN in SELECT to assign a label or category to each row based on its values. The output is a new column where each row carries the label its Switch matched.","type":"text"}],"id":"53defdfb-06b3-468a-8f1f-50df3aecbc3f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters:","type":"text"},{"styles":{},"text":" Bucketing is the most fundamental CASE WHEN pattern. It appears in almost every internship SQL coding task that involves categorization, tiering, or labeling.","type":"text"}],"id":"b62a3652-98e4-4f67-ba96-9a50b7102a50","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"f73f83a0-7121-4391-b3b5-6b02e6d5f95b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"SELECT\n    customer_id,\n    total_purchases,\n    CASE\n        WHEN total_purchases >= 50 THEN ''platinum''\n        WHEN total_purchases >= 20 THEN ''gold''\n        WHEN total_purchases >= 5  THEN ''silver''\n        ELSE                            ''bronze''\n    END AS loyalty_tier\nFROM customers;","type":"text"}],"id":"1a3dd440-9773-45aa-98cc-a0c6330e1820","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"id":"456358e3-5598-454f-a6d4-671a53625c61","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"5. Pattern 2 — Conditional Aggregation","type":"text"}],"id":"12c82964-20a8-464d-be03-e7921b1902c3","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" Wrap a CASE WHEN inside an aggregate function (SUM, AVG) to compute the aggregate only for rows that match a condition — while still grouping across all rows. This lets you produce multiple metrics in one query without multiple subqueries.","type":"text"}],"id":"85e45f5d-b362-4afd-9a2b-bf82fc73717a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters:","type":"text"},{"styles":{},"text":" Conditional aggregation is one of the most commonly tested intermediate SQL patterns. The alternative — writing separate subqueries for each metric — is verbose and slow. Interviewers expect you to combine them in one GROUP BY query.","type":"text"}],"id":"53b92149-20be-4473-9a9b-4ce0872a615a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"3da529a3-727c-4967-8e6d-93591e20d1e0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"SELECT\n    region,\n    SUM(amount)                                         AS total_revenue,\n    SUM(CASE WHEN status = ''completed'' THEN amount\n             ELSE 0 END)                                AS completed_revenue,\n    AVG(CASE WHEN status = ''completed'' THEN amount\n             END)                                       AS avg_completed_amount\nFROM orders\nGROUP BY region;","type":"text"}],"id":"c43fa625-a5d0-4e73-a718-31af78d656a3","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"id":"4b1a6da2-5701-458b-bada-094fe6af9a84","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"6. Pattern 3 — Conditional Counting","type":"text"}],"id":"22159235-3ee1-4182-b3d1-9960c3522673","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" Wrap a CASE WHEN inside COUNT() to count only rows that match a condition. The key: return 1 when the condition matches and omit ELSE (or use ELSE NULL). COUNT() ignores NULLs, so unmatched rows are not counted.","type":"text"}],"id":"d1e5103c-a8fd-47b3-aabb-f86ee3372501","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters:","type":"text"},{"styles":{},"text":" Conditional counting lets you produce a pivot-style summary in one query — e.g., \"how many completed, how many cancelled, how many pending\" — without multiple passes over the table.","type":"text"}],"id":"e4bdfc30-0aad-4eaf-bc34-7f388ff4be4e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"6f76f43e-9836-4973-aba2-2016e14d8ea1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"SELECT\n    region,\n    COUNT(*)                                              AS total_orders,\n    COUNT(CASE WHEN status = ''completed'' THEN 1 END)     AS completed_orders,\n    COUNT(CASE WHEN status = ''cancelled'' THEN 1 END)     AS cancelled_orders,\n    COUNT(CASE WHEN status = ''pending''   THEN 1 END)     AS pending_orders\nFROM orders\nGROUP BY region;\n\n-- Why no ELSE?\n-- No ELSE means unmatched rows return NULL.\n-- COUNT() ignores NULLs, so they are not counted. This is intentional.","type":"text"}],"id":"95ed87d5-6148-4202-9b74-25e1acd9b2c1","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"id":"9d3665ff-a38f-4092-bf2d-1bd91bdc0f6b","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Common Mistakes","type":"text"}],"id":"e23e273b-c225-4020-a0b1-94462181f753","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":{"columnWidths":[null,null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Mistake","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Why It Is Wrong","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Fix","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Forgetting END","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Syntax error — CASE is never closed","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Always close every CASE with END","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Wrong condition order in ranges","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"First match wins — a broad condition catches rows meant for a narrower one","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Put the most specific condition first","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Using ELSE NULL explicitly when no match is wanted","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Unnecessary — omitting ELSE already returns NULL","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Omit ELSE if NULL is the intended default","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Adding ELSE 0 inside COUNT()","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"COUNT(0) counts the zero — every row gets counted","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Use ELSE NULL or omit ELSE inside COUNT()","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Adding ELSE NULL inside SUM()","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Returns NULL, not 0, for unmatched rows — may affect totals","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Use ELSE 0 inside SUM() to keep totals correct","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Putting CASE WHEN in GROUP BY with a different expression than SELECT","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Inconsistent grouping — results are wrong","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Copy the exact CASE WHEN expression into GROUP BY, or use a subquery/CTE","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Testing equality on NULL inside CASE WHEN","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"code":true},"text":"WHEN col = NULL","type":"text"},{"styles":{},"text":" always produces UNKNOWN","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Use ","type":"text"},{"styles":{"code":true},"text":"WHEN col IS NULL","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"69fb7803-b0bc-4823-bad7-9416f65e6311","props":{"textColor":"default"},"type":"table"},{"children":[],"id":"b5236b52-fd49-4981-8b1a-d4541ff4845b","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Practice Ideas","type":"text"}],"id":"ddf62c56-ded0-473f-9889-06ba1956bd99","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"These are sized for an interview whiteboard or a 20-minute coding task.","type":"text"}],"id":"c916b5b8-b337-46d9-93c0-18e29a60cc0b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Write a query that labels each order as ''high'', ''medium'', or ''low'' based on amount thresholds. Make sure the condition order is correct.","type":"text"}],"id":"b6498944-a3ff-46fc-8e4c-1782986137fc","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Write a single GROUP BY query that computes total revenue, completed-only revenue, and cancelled-only revenue side by side using conditional aggregation.","type":"text"}],"id":"15ca3b9e-95e0-45f8-aaea-0c734efaaa2b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Write a query that counts total orders, completed orders, cancelled orders, and pending orders per region — all in one SELECT using conditional counting.","type":"text"}],"id":"77a093e1-47bc-4cb5-8286-9911a6df3abd","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Write a query where a CASE WHEN column is NULL because no ELSE was provided. Then add an ELSE to fix it and observe the difference.","type":"text"}],"id":"a2460a2b-6958-4226-a08e-6349a6566e0d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Write a query that uses CASE WHEN inside GROUP BY to group customers into tiers, then counts how many customers are in each tier.","type":"text"}],"id":"5f9272a9-7120-4a68-92b2-82ff06979d32","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Explain out loud: \"What is the difference between ELSE 0 inside SUM and ELSE NULL inside COUNT?\" Practice this in under 30 seconds.","type":"text"}],"id":"78e62294-5e08-4c5d-89c1-2a74d585773f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"id":"e0aed355-e84a-4be1-97ee-65a6e4929058","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Final Integrated Coding Example","type":"text"}],"id":"bd860924-34f2-4d49-afec-0b344796d8f6","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Scenario:","type":"text"},{"styles":{},"text":" You have an ","type":"text"},{"styles":{"code":true},"text":"orders","type":"text"},{"styles":{},"text":" table. You need to label each order by tier, compute per-region metrics that combine all three CASE WHEN patterns, and produce a clean summary output.","type":"text"}],"id":"51e93e0e-51c4-4eab-9abc-8ed325440ada","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"-- =============================================================\n-- PANEL OF SWITCHES: Regional Order Summary\n-- =============================================================\n\nSELECT\n    region,\n\n    -- Total row count (no switch needed)\n    COUNT(*)                                              AS total_orders,\n\n    -- Pattern 3: Conditional Counting\n    -- Selector opens, each Switch counts one status type\n    -- No ELSE: unmatched rows return NULL, COUNT ignores them\n    COUNT(CASE WHEN status = ''completed'' THEN 1 END)     AS completed_orders,\n    COUNT(CASE WHEN status = ''cancelled'' THEN 1 END)     AS cancelled_orders,\n    COUNT(CASE WHEN status = ''pending''   THEN 1 END)     AS pending_orders,\n\n    -- Pattern 2: Conditional Aggregation\n    -- ELSE 0 keeps unmatched rows contributing zero to the SUM\n    SUM(CASE WHEN status = ''completed'' THEN amount\n             ELSE 0 END)                                  AS completed_revenue,\n\n    SUM(CASE WHEN status = ''cancelled'' THEN amount\n             ELSE 0 END)                                  AS cancelled_revenue,\n\n    -- Conditional average: no ELSE so only completed rows factor in\n    AVG(CASE WHEN status = ''completed'' THEN amount\n             END)                                         AS avg_completed_order,\n\n    -- Pattern 2 + 3 combined: high-value completed orders only\n    COUNT(CASE WHEN status = ''completed''\n               AND amount >= 1000 THEN 1 END)             AS high_value_completed,\n\n    -- Pattern 1: Bucketing — dominant tier by most common amount range\n    -- Used here to label the region''s overall profile\n    -- (Most specific threshold first — top-to-bottom evaluation)\n    CASE\n        WHEN AVG(amount) >= 1000 THEN ''high-value region''\n        WHEN AVG(amount) >= 500  THEN ''mid-value region''\n        ELSE                          ''low-value region''\n    END                                                   AS region_profile\n\nFROM orders\n\n-- Safety Beam: only process orders with a recorded amount\nWHERE amount IS NOT NULL\n\nGROUP BY region\n\n-- Gatekeeper: only show regions with meaningful completed volume\nHAVING COUNT(CASE WHEN status = ''completed'' THEN 1 END) > 0\n\n-- Most completed revenue first\nORDER BY completed_revenue DESC;","type":"text"}],"id":"a406c87f-9b63-4966-90f4-eb9571bec979","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"What each concept is doing in this script:","type":"text"}],"id":"6e4efcd2-c63e-4211-bf92-fbf778ab564d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Concept","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Where it appears","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"CASE WHEN syntax — Selector + Switches + END","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Every CASE expression in the query","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Default Switch — ELSE","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"code":true},"text":"ELSE 0","type":"text"},{"styles":{},"text":" in SUM blocks; ","type":"text"},{"styles":{"code":true},"text":"ELSE ''low-value region''","type":"text"},{"styles":{},"text":" in bucketing","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Top-to-bottom evaluation","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"code":true},"text":"avg_completed_order","type":"text"},{"styles":{},"text":": most specific AVG threshold tested first in region_profile","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Pattern 1 — Bucketing","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"code":true},"text":"region_profile","type":"text"},{"styles":{},"text":": labels each region based on AVG amount","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Pattern 2 — Conditional Aggregation","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"code":true},"text":"completed_revenue","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"cancelled_revenue","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"avg_completed_order","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Pattern 3 — Conditional Counting","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"code":true},"text":"completed_orders","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"cancelled_orders","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"pending_orders","type":"text"},{"styles":{},"text":", ","type":"text"},{"styles":{"code":true},"text":"high_value_completed","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"ELSE 0 in SUM vs no ELSE in COUNT","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"SUM uses ELSE 0; COUNT omits ELSE — both intentional","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"IS NOT NULL filter","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"code":true},"text":"WHERE amount IS NOT NULL","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"HAVING with conditional count","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Filters regions with at least one completed order","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"71dd6ed8-501e-4469-bd6b-584499f54746","props":{"textColor":"default"},"type":"table"},{"children":[],"id":"c17a2a49-4a92-4a6a-ba10-adc36745ba5d","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"italic":true},"text":"This note is scoped exclusively to internship-level CASE WHEN readiness for Topic 5. Do not add to it. Use it as written.","type":"text"}],"id":"11adb629-439b-4266-b6ae-88c1a44ec1d0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[],"id":"fefe2173-049a-4e12-9c34-21d722f8a710","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"}]'::jsonb, '3e9e3dd3-a59b-4b02-968a-ee95e7317583') ON CONFLICT ("node_id") DO UPDATE SET "bad_example" = EXCLUDED."bad_example", "completed_at" = EXCLUDED."completed_at", "created_at" = EXCLUDED."created_at", "definition" = EXCLUDED."definition", "good_example" = EXCLUDED."good_example", "is_completed" = EXCLUDED."is_completed", "key_points" = EXCLUDED."key_points", "last_edited" = EXCLUDED."last_edited", "map_id" = EXCLUDED."map_id", "mental_model" = EXCLUDED."mental_model", "notes" = EXCLUDED."notes", "resources" = EXCLUDED."resources", "rich_content" = EXCLUDED."rich_content", "user_id" = EXCLUDED."user_id";
INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-06-14T07:27:35.049385+00:00', '', '', '3648fb90-2083-4789-900b-64c88eed5716', false, '[]'::jsonb, '2026-06-14T07:32:42.418+00:00', '2ad473fe-77dd-481e-8ba7-4b2b0336173f', '', '209f009e-b2a5-4d77-aba2-2a932c63afe4', '', '[]'::jsonb, '[{"children":[],"content":[{"styles":{},"text":"SQL for Data Engineering — Internship Study Note","type":"text"}],"id":"08132391-8f8f-44f6-9a98-6695d9b3acf7","props":{"backgroundColor":"default","isToggleable":false,"level":1,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Topic 12: The Metric Panel","type":"text"}],"id":"57e6e8e5-57b6-4030-a46b-eb147396b5e1","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"id":"fecbc0e3-0c79-4244-aa7a-8298446f0a2e","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"What This Note Is","type":"text"}],"id":"02641fce-edb1-4e01-9c69-6761e2eb1e1f","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Inside the Control Room, the ","type":"text"},{"styles":{"bold":true},"text":"Metric Panel","type":"text"},{"styles":{},"text":" is the station where raw data becomes business KPIs. The Revenue Dial (ARPU) measures how much money each user generates. The Exit Dial (churn) tracks how many users stopped using the product. The Trend Dial (month-over-month growth) shows whether key metrics are increasing or decreasing over time. Every calculation on this panel requires decimal precision — integer division silently breaks every formula. An internship interviewer will expect you to compute these three KPIs correctly and explain what each one means.","type":"text"}],"id":"cc861043-8b42-4124-88ba-815ea18171c9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"id":"ec1c928c-ddbf-45f1-a74c-cd2b98644412","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Mind Map","type":"text"}],"id":"f3ac69b2-6d7a-465d-985c-6b7777f73fb9","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"                          THE METRIC PANEL\n                      (KPI Aggregation Patterns)\n                               │\n          ┌────────────────────┼────────────────────┐\n          │                    │                    │\n     REVENUE DIAL           EXIT DIAL            TREND DIAL\n        (ARPU)               (Churn)         (Month-over-Month)\n          │                    │                    │\n  Total revenue /      Users who left /     Current metric -\n  Total users          Total users          Previous metric\n          │                    │                    │\n  Must use decimal     Must use decimal     Usually expressed\n  division             division             as percentage or\n  (not integer)        (not integer)        absolute change\n          │                    │                    │\n  Example:             Example:             Example:\n  $10,000 / 250        50 / 1000            Jan revenue - Dec revenue\n  = $40 per user       = 0.05 (5%)          or (Jan - Dec) / Dec\n\n          │\n          └──── Core interview requirement ──────────────┐\n                                                         │\n                     All three KPIs require:\n                     - Correct decimal division\n                     - Correct date filtering or grouping\n                     - Clear business definition\n                     - Protection against division by zero","type":"text"}],"id":"7ffb45f7-aedf-4cbb-9678-2723a8e9c06a","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"08e51417-f3b0-4a8d-8b8e-b0f3d2567958","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Decision Tree","type":"text"}],"id":"a899907c-3f2d-4734-b7bc-d495ca4c5e7a","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"START: You need to compute a business KPI\n          │\n          ▼\nWhich metric are you computing?\n    │\n    ├─ Average revenue per user\n    │      → Revenue Dial (ARPU)\n    │      → Formula: SUM(revenue) * 1.0 / COUNT(DISTINCT user_id)\n    │\n    ├─ Percentage of users who left\n    │      → Exit Dial (Churn)\n    │      → Formula: COUNT(churned_users) * 1.0 / COUNT(total_users)\n    │\n    └─ Change from one period to the next\n           → Trend Dial (Month-over-Month Growth)\n           → Formula: (current - previous) or (current - previous) / previous\n          │\n          ▼\nDid you force decimal division?\n    NO  → Add * 1.0 or CAST to DECIMAL\n    YES → Continue\n          │\n          ▼\nDid you protect against division by zero?\n    NO  → Wrap denominator in NULLIF(..., 0)\n    YES → Continue\n          │\n          ▼\nFor churn:\n    Did you define the time window correctly?\n        Users active at start of period\n        Users who did NOT return by end of period\n          │\n          ▼\nFor month-over-month:\n    Did you use LAG() or self-join to get previous month''s value?\n    YES → Correct\n    NO  → Add window function or join to prior period\n          │\n          ▼\nOutput the KPI with clear labels and units","type":"text"}],"id":"29adf707-971c-4f46-a08d-01434bcc686a","props":{"language":"python"},"type":"codeBlock"},{"children":[],"id":"90e1e9fb-b3ce-49eb-8f14-83f3836f19aa","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Concept Breakdown","type":"text"}],"id":"3a93769b-b210-4490-b9c2-9202f4ac5655","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"id":"0a691c5e-b4d9-4e0c-abaf-d1965a65771c","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"1. What KPI Aggregation Is","type":"text"}],"id":"1d85989f-7ee4-4acd-bba9-ab79e965c54a","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" KPI aggregation is the process of computing Key Performance Indicators — single-number metrics that summarize business health. Unlike raw counts or sums, KPIs are ","type":"text"},{"styles":{"bold":true},"text":"ratios","type":"text"},{"styles":{},"text":" or ","type":"text"},{"styles":{"bold":true},"text":"rates","type":"text"},{"styles":{},"text":" that combine multiple measures: revenue per user, percentage of users lost, growth from one month to the next.","type":"text"}],"id":"8a98c1f1-e2a1-4d44-a108-dad590c18bee","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters:","type":"text"},{"styles":{},"text":" Every data engineering intern will be asked to compute KPIs in SQL. These are the metrics that executives see in dashboards. If you cannot compute ARPU, churn, or growth correctly, you cannot contribute to real data pipelines.","type":"text"}],"id":"4d419a78-61b0-4405-86de-e5bcf118a4a3","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"7b361e87-773a-4e00-9bd0-ecc8e82c911b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"-- Raw aggregates (not KPIs)\nSELECT\n    COUNT(DISTINCT user_id) AS total_users,\n    SUM(revenue)            AS total_revenue\nFROM orders;\n\n-- KPI: ARPU (ratio of two aggregates)\nSELECT\n    SUM(revenue) * 1.0 / NULLIF(COUNT(DISTINCT user_id), 0) AS arpu\nFROM orders;","type":"text"}],"id":"1685ddd1-c348-42ba-8bce-e0070bd530b5","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"id":"c70f10c1-32d1-4928-abc4-882bccc8a49d","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"2. Revenue Dial — ARPU (Average Revenue Per User)","type":"text"}],"id":"8d6a06ea-63e3-4609-8c16-1340fb597625","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" ARPU is the average amount of revenue generated per user over a specific time period.","type":"text"}],"id":"d207eb7e-cde9-4104-8c30-65016f57073c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Formula:","type":"text"}],"id":"187d15c6-b22c-406a-9e93-02ec7522a780","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"ARPU = Total Revenue / Total Users","type":"text"}],"id":"f48ffa76-bc88-4d68-ba6d-d6600109dd38","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"You must use decimal division. If both numerator and denominator are integers, the result will be truncated.","type":"text"}],"id":"a2fdb0de-f6b5-4c1a-8fda-4695fe19daea","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters:","type":"text"},{"styles":{},"text":" ARPU is one of the most commonly requested metrics in data engineering interviews. It tests whether you know:","type":"text"}],"id":"64142f83-4c48-48b5-8c75-be758d5c9e30","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"How to aggregate revenue correctly.","type":"text"}],"id":"5ae6ff27-7282-4409-99f4-b88fd033e3bf","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"How to count distinct users.","type":"text"}],"id":"7b9addba-b10c-471b-92cb-eb46d35c385a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"How to force decimal division.","type":"text"}],"id":"8958576b-35df-45d8-8e4f-65823f41dd67","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"c033b3cb-3eff-43a5-98e3-fc5d11833552","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"-- WRONG: integer division\nSELECT\n    SUM(revenue) / COUNT(DISTINCT user_id) AS arpu\nFROM orders;\n-- If SUM = 7500 and COUNT = 100, result = 75 (correct by luck)\n-- If SUM = 750 and COUNT = 100, result = 7 (should be 7.5)\n\n-- CORRECT: decimal division\nSELECT\n    SUM(revenue) * 1.0 / NULLIF(COUNT(DISTINCT user_id), 0) AS arpu\nFROM orders;\n-- Result: 7.5","type":"text"}],"id":"f57021b1-0d7e-442f-8efa-7b5471e3a5b8","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"id":"cfe9b378-5572-4473-8934-43a416a2ae4e","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"3. Exit Dial — Churn","type":"text"}],"id":"3eafa0ea-5b22-4092-b5fa-61617d060870","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" Churn is the percentage of users who stopped using the product during a specific time period.","type":"text"}],"id":"016fdd31-28ce-43d4-b40e-69f740bc2169","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Formula:","type":"text"}],"id":"0912a70a-c064-47bb-81df-55d9b671cb67","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Churn Rate = (Users who left) / (Total users at start of period)","type":"text"}],"id":"de109ee2-9d65-494a-be24-7b140eae6342","props":{"language":"python"},"type":"codeBlock"},{"children":[],"content":[{"styles":{},"text":"There are multiple definitions of churn in the industry. The most common for internship level:","type":"text"}],"id":"0c2ca06e-f958-4a81-b750-6671a8630715","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Users active in Month 1","type":"text"},{"styles":{},"text":" who did ","type":"text"},{"styles":{"bold":true},"text":"not","type":"text"},{"styles":{},"text":" appear in Month 2.","type":"text"}],"id":"f55f192a-180a-427d-aee9-731ea03cb5d5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters:","type":"text"},{"styles":{},"text":" Churn is the second most common KPI metric in interviews. It tests whether you can:","type":"text"}],"id":"daebc866-ff15-424b-bf1e-554ef406b0c6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Define a cohort (users at the start).","type":"text"}],"id":"016cdf3a-3c25-457d-98ec-ffb1b4312d40","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Identify who is missing in the next period.","type":"text"}],"id":"bf331e4f-1351-4bd5-b049-f3dda271a7db","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Compute a rate using decimal division.","type":"text"}],"id":"b30574b3-5d1a-4724-91b5-a3dda2e43de7","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"0eab31bf-5663-43cc-8346-c91b4a0e4f8c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"-- Users active in January\nWITH jan_users AS (\n    SELECT DISTINCT user_id\n    FROM activity\n    WHERE activity_date BETWEEN ''2024-01-01'' AND ''2024-01-31''\n),\n-- Users active in February\nfeb_users AS (\n    SELECT DISTINCT user_id\n    FROM activity\n    WHERE activity_date BETWEEN ''2024-02-01'' AND ''2024-02-29''\n)\n-- Churn: Jan users who did NOT return in Feb\nSELECT\n    COUNT(DISTINCT j.user_id) * 1.0\n        / NULLIF((SELECT COUNT(*) FROM jan_users), 0) AS churn_rate\nFROM jan_users j\nWHERE NOT EXISTS (\n    SELECT 1 FROM feb_users f WHERE f.user_id = j.user_id\n);\n-- If 50 out of 1000 Jan users did not return, churn = 0.05 (5%)","type":"text"}],"id":"92ae385a-3899-49c6-a940-4fc5fe05a73c","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"id":"4f5d7ec5-e9c4-4a5f-adf7-9c7922c644be","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"4. Trend Dial — Month-over-Month Growth","type":"text"}],"id":"90005c33-36cf-44f3-a70c-2468c8a4cfab","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" Month-over-month (MoM) growth measures the change in a metric from one month to the next. It can be expressed as:","type":"text"}],"id":"ac8f3400-97f3-46c0-a012-999890cc37c2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Absolute change","type":"text"},{"styles":{},"text":": ","type":"text"},{"styles":{"code":true},"text":"current_month - previous_month","type":"text"}],"id":"8454a361-c88b-4fc7-8ec9-494dfb025317","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Percentage change","type":"text"},{"styles":{},"text":": ","type":"text"},{"styles":{"code":true},"text":"(current_month - previous_month) / previous_month * 100","type":"text"}],"id":"db07c573-3e37-4b17-8f2d-7679a6392209","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters:","type":"text"},{"styles":{},"text":" Growth metrics are standard in every business dashboard. Interviewers test whether you can use LAG() or a self-join to compare one period to the prior period.","type":"text"}],"id":"ff89f875-1aed-49dd-81a5-8501d1fc9d76","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"8402f80a-fd1e-45b7-847f-d01c6cb7d0c2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"WITH monthly_revenue AS (\n    SELECT\n        DATE_TRUNC(''month'', order_date) AS month,\n        SUM(amount)                     AS revenue\n    FROM orders\n    GROUP BY DATE_TRUNC(''month'', order_date)\n)\nSELECT\n    month,\n    revenue                                     AS current_revenue,\n    LAG(revenue) OVER (ORDER BY month)          AS prev_revenue,\n    revenue - LAG(revenue) OVER (ORDER BY month) AS absolute_growth,\n    (revenue - LAG(revenue) OVER (ORDER BY month))\n        * 100.0 / NULLIF(LAG(revenue) OVER (ORDER BY month), 0)\n                                                AS pct_growth\nFROM monthly_revenue\nORDER BY month;\n-- Jan revenue: 10000, Feb revenue: 12000\n-- Absolute growth: 2000\n-- Percentage growth: 20.0%","type":"text"}],"id":"e79d1570-4e6a-4b73-a21f-69165adf8de3","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"id":"168ee397-5528-42fe-82cd-d03414664dd2","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"5. Why Decimal Division Matters in KPI Formulas","type":"text"}],"id":"8661e583-a774-4e95-873d-61665738e3d3","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" Every KPI on the Metric Panel involves division. If both operands are integers, SQL performs integer division — the decimal portion is truncated. This silently corrupts ARPU, churn, and growth percentages.","type":"text"}],"id":"78f0865e-bd45-4bc3-a53c-c820fd40d74d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters:","type":"text"},{"styles":{},"text":" This is the single most common bug in KPI queries written by interns. Interviewers will give you a dataset where the correct answer is ","type":"text"},{"styles":{"code":true},"text":"0.75","type":"text"},{"styles":{},"text":" and test whether your query returns ","type":"text"},{"styles":{"code":true},"text":"0","type":"text"},{"styles":{},"text":" (integer division) or ","type":"text"},{"styles":{"code":true},"text":"0.75","type":"text"},{"styles":{},"text":" (correct).","type":"text"}],"id":"3b768b9f-7be8-4270-9220-0e5ef478f1c2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"94d54676-6395-44bf-b6f8-7b03c5210d2d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"-- Churn calculation with integer division (WRONG)\nSELECT\n    50 / 1000 AS churn_rate;\n-- Result: 0 (should be 0.05)\n\n-- Churn calculation with decimal division (CORRECT)\nSELECT\n    50 * 1.0 / 1000 AS churn_rate;\n-- Result: 0.05\n\n-- Growth percentage with integer division (WRONG)\nSELECT\n    (12000 - 10000) / 10000 * 100 AS pct_growth;\n-- Result: 0 (should be 20.0)\n\n-- Growth percentage with decimal division (CORRECT)\nSELECT\n    (12000 - 10000) * 100.0 / 10000 AS pct_growth;\n-- Result: 20.0","type":"text"}],"id":"7d5f1b1d-b9b0-4e72-8ad1-26b8a0b43a23","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"id":"661f85f8-5aac-4f3c-8da4-5dce2c883667","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"6. Short Example — ARPU","type":"text"}],"id":"952c3ea3-0e7c-4935-a4bf-938d5058ddeb","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" Compute average revenue per user for a specific month.","type":"text"}],"id":"8c39f61f-bd04-4549-96fa-51a94d479c1b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters:","type":"text"},{"styles":{},"text":" Shows you can filter by date, aggregate revenue, count distinct users, and force decimal division in one query.","type":"text"}],"id":"deed742f-3c46-4fa5-bc9c-44a18312dcd8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"1d23e770-dd30-4fde-a50a-e28d47d028d0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"SELECT\n    SUM(amount) * 1.0 / NULLIF(COUNT(DISTINCT user_id), 0) AS arpu\nFROM orders\nWHERE order_date BETWEEN ''2024-01-01'' AND ''2024-01-31'';","type":"text"}],"id":"489b5419-8a07-406a-89d2-20dea7968f66","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"id":"5c1fa9de-dbbc-40c8-82dc-1b55cba0b007","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"7. Short Example — Churn","type":"text"}],"id":"83db3873-1f56-4922-930c-bb7971fa49b2","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" Compute the percentage of January users who did not return in February.","type":"text"}],"id":"14e32dd0-5ab9-4ab0-8060-520a865ea6a2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters:","type":"text"},{"styles":{},"text":" Shows you can define two cohorts, compare them with NOT EXISTS, and compute a rate.","type":"text"}],"id":"9d65e630-d432-404e-83f4-2dd8a381a10d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"0d1d471c-7ea7-4c89-ae1d-da19366800b5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"WITH jan AS (\n    SELECT DISTINCT user_id FROM activity\n    WHERE activity_date BETWEEN ''2024-01-01'' AND ''2024-01-31''\n),\nfeb AS (\n    SELECT DISTINCT user_id FROM activity\n    WHERE activity_date BETWEEN ''2024-02-01'' AND ''2024-02-29''\n)\nSELECT\n    COUNT(*) * 1.0 / (SELECT COUNT(*) FROM jan) AS churn_rate\nFROM jan\nWHERE NOT EXISTS (SELECT 1 FROM feb WHERE feb.user_id = jan.user_id);","type":"text"}],"id":"67d59583-1297-476f-8ebf-0d6995ab64c6","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"id":"9d370d9d-212f-4a69-8d12-ca226647aca3","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"8. Short Example — Month-over-Month Growth","type":"text"}],"id":"f1d6c5f7-7adc-4ecf-bf32-ec05da09a60d","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"What it is:","type":"text"},{"styles":{},"text":" Compute percentage change in revenue from one month to the next.","type":"text"}],"id":"01356dd5-52a9-4e50-816d-a31e52b1e7a2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Why it matters:","type":"text"},{"styles":{},"text":" Shows you can use LAG() to access the prior period''s value and compute a growth rate.","type":"text"}],"id":"821e254f-ab45-47f8-b2f6-4d66cfa0f257","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"Code example:","type":"text"}],"id":"2472256b-9a5b-4f9b-aecf-3b2f658e6cd4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"WITH monthly AS (\n    SELECT\n        DATE_TRUNC(''month'', order_date) AS month,\n        SUM(amount)                     AS revenue\n    FROM orders\n    GROUP BY 1\n)\nSELECT\n    month,\n    revenue,\n    LAG(revenue) OVER (ORDER BY month) AS prev_revenue,\n    (revenue - LAG(revenue) OVER (ORDER BY month))\n        * 100.0 / NULLIF(LAG(revenue) OVER (ORDER BY month), 0) AS mom_growth_pct\nFROM monthly;","type":"text"}],"id":"b0b632ea-b9e6-4271-8eeb-3ca91050136e","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"id":"98728f37-9121-4692-b487-64cb48a5a51d","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Common Mistakes","type":"text"}],"id":"e813df0e-ec22-492a-88d6-f530cd266522","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":{"columnWidths":[null,null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Mistake","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Why It Is Wrong","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Fix","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Integer division in ARPU","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Result is truncated to 0 or whole number","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Multiply numerator by 1.0","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Integer division in churn","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Result is always 0 if churned < total","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Multiply numerator by 1.0","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Forgetting NULLIF in denominators","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Division by zero crashes the query","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Wrap denominator in NULLIF(..., 0)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Counting total users instead of distinct users","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Duplicate user rows inflate the count","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Use COUNT(DISTINCT user_id)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Using total users instead of start cohort for churn","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Churn rate is incorrect","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Churn = churned / users_at_start","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Not using LAG() for month-over-month","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Requires complex self-join or manual logic","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Use LAG() OVER (ORDER BY period)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Computing growth without ORDER BY in LAG","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"LAG returns wrong prior value","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Always include ORDER BY in OVER clause","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Forgetting to multiply by 100 for percentages","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Growth shows as 0.2 instead of 20%","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Multiply by 100.0 for percentage format","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"a9813c1b-ba5a-4436-8d0c-b62492316e70","props":{"textColor":"default"},"type":"table"},{"children":[],"id":"5881fa13-b0ea-44a5-a3a0-194b40744165","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Practice Ideas","type":"text"}],"id":"214543b6-b1aa-4893-96c3-e38f6d991c05","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"These are sized for an interview whiteboard or a 20-minute coding task.","type":"text"}],"id":"0990e4ff-d491-4ee1-8537-92b9c5293894","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Write a query that computes ARPU for each month. Include the month, total revenue, total users, and ARPU.","type":"text"}],"id":"824ba645-a8bd-41ab-b269-7e264f75301d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Write a query that computes churn rate from January to February. Define churn as Jan users who did not appear in Feb.","type":"text"}],"id":"3ea8bc91-23c4-4aa6-a794-cebfedc0eafb","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Write a query that computes month-over-month revenue growth as both an absolute number and a percentage.","type":"text"}],"id":"bab9e0d9-3bc4-416f-a06f-74a93e281590","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Debug a query where ARPU is computed with integer division and returns 0. Fix it.","type":"text"}],"id":"77829fbd-46e2-4a6e-8c75-26332ecd6071","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Explain out loud: ","type":"text"},{"styles":{"italic":true},"text":"\"What is ARPU and how do you compute it?\"","type":"text"},{"styles":{},"text":" Practice this in two sentences.","type":"text"}],"id":"a7952524-89c1-4b67-9acd-33f02cb59bfd","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"content":[{"styles":{},"text":"Explain out loud: ","type":"text"},{"styles":{"italic":true},"text":"\"What is churn and why does it require decimal division?\"","type":"text"},{"styles":{},"text":" Practice this in two sentences.","type":"text"}],"id":"aac92e26-67bb-47e2-a26b-43f39dcbc84b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"numberedListItem"},{"children":[],"id":"7f217c1e-7e31-4418-baf4-de0c32cfa19a","props":{},"type":"divider"},{"children":[],"content":[{"styles":{},"text":"Final Integrated Coding Example","type":"text"}],"id":"9e7b7cc7-b53b-4731-946f-1b53e57e14dd","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Scenario:","type":"text"},{"styles":{},"text":" You have an ","type":"text"},{"styles":{"code":true},"text":"orders","type":"text"},{"styles":{},"text":" table and an ","type":"text"},{"styles":{"code":true},"text":"activity","type":"text"},{"styles":{},"text":" table. You need to produce a monthly summary that includes:","type":"text"}],"id":"3fbb6eca-340c-4345-ae04-0ad686f64b04","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"ARPU (average revenue per active user)","type":"text"}],"id":"743cbad6-171f-4928-8ebe-f1b33a6fbe23","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Churn rate (percentage of prior month''s users who did not return)","type":"text"}],"id":"a70d2d35-9d9b-4de8-ad4d-ae201fdb00c9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Month-over-month revenue growth","type":"text"}],"id":"15295903-52bd-4060-a304-09881a402219","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"-- =============================================================\n-- METRIC PANEL: Monthly KPI Summary\n-- =============================================================\n\n-- Revenue Dial: Monthly ARPU\nWITH monthly_arpu AS (\n    SELECT\n        DATE_TRUNC(''month'', order_date)         AS month,\n        SUM(amount)                             AS total_revenue,\n        COUNT(DISTINCT user_id)                 AS total_users,\n        SUM(amount) * 1.0\n            / NULLIF(COUNT(DISTINCT user_id), 0) AS arpu\n    FROM orders\n    WHERE order_date IS NOT NULL\n      AND amount IS NOT NULL\n    GROUP BY DATE_TRUNC(''month'', order_date)\n),\n\n-- Exit Dial: Monthly churn (users who left from prior month)\nmonthly_users AS (\n    SELECT\n        DATE_TRUNC(''month'', activity_date) AS month,\n        user_id\n    FROM activity\n    WHERE activity_date IS NOT NULL\n    GROUP BY DATE_TRUNC(''month'', activity_date), user_id\n),\n\nchurn_calc AS (\n    SELECT\n        curr.month,\n        COUNT(DISTINCT prev.user_id)            AS prev_month_users,\n        COUNT(DISTINCT prev.user_id) - COUNT(DISTINCT curr.user_id)\n                                                AS churned_users,\n        (COUNT(DISTINCT prev.user_id) - COUNT(DISTINCT curr.user_id)) * 1.0\n            / NULLIF(COUNT(DISTINCT prev.user_id), 0) AS churn_rate\n    FROM monthly_users curr\n    LEFT JOIN monthly_users prev\n        ON prev.month = curr.month - INTERVAL ''1 month''\n        AND prev.user_id = curr.user_id\n    GROUP BY curr.month\n),\n\n-- Trend Dial: Month-over-month revenue growth\nrevenue_growth AS (\n    SELECT\n        month,\n        total_revenue,\n        LAG(total_revenue) OVER (ORDER BY month) AS prev_revenue,\n        total_revenue - LAG(total_revenue) OVER (ORDER BY month)\n                                                 AS absolute_growth,\n        (total_revenue - LAG(total_revenue) OVER (ORDER BY month))\n            * 100.0 / NULLIF(LAG(total_revenue) OVER (ORDER BY month), 0)\n                                                 AS pct_growth\n    FROM monthly_arpu\n)\n\n-- =============================================================\n-- Final output: all KPIs in one table\n-- =============================================================\nSELECT\n    a.month,\n    a.total_revenue,\n    a.total_users,\n    ROUND(a.arpu, 2)                AS arpu,\n    COALESCE(ROUND(c.churn_rate * 100, 2), 0) AS churn_pct,\n    ROUND(g.absolute_growth, 2)     AS revenue_growth,\n    ROUND(g.pct_growth, 2)          AS revenue_growth_pct\nFROM monthly_arpu a\nLEFT JOIN churn_calc c\n    ON a.month = c.month\nLEFT JOIN revenue_growth g\n    ON a.month = g.month\nORDER BY a.month;\n\n-- =============================================================\n-- Sample output:\n-- =============================================================\n-- | month      | total_revenue | total_users | arpu  | churn_pct | revenue_growth | revenue_growth_pct |\n-- |------------|---------------|-------------|-------|-----------|----------------|--------------------|\n-- | 2024-01-01 | 10000.00      | 250         | 40.00 | 0.00      | NULL           | NULL               |\n-- | 2024-02-01 | 12000.00      | 240         | 50.00 | 4.00      | 2000.00        | 20.00              |\n-- | 2024-03-01 | 13500.00      | 270         | 50.00 | 12.50     | 1500.00        | 12.50              |","type":"text"}],"id":"57de1858-089c-446d-b26c-6f4bdb0c1d38","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"What each concept is doing in this script:","type":"text"}],"id":"2aae01ae-53d7-4a2c-a08e-8f92f84b1c23","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":{"columnWidths":[null,null],"headerRows":1,"rows":[{"cells":[{"content":[{"styles":{},"text":"Concept","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Where it appears","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"ARPU (Revenue Dial)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"code":true},"text":"SUM(amount) * 1.0 / NULLIF(COUNT(DISTINCT user_id), 0)","type":"text"},{"styles":{},"text":" in ","type":"text"},{"styles":{"code":true},"text":"monthly_arpu","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Churn (Exit Dial)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"code":true},"text":"churn_rate","type":"text"},{"styles":{},"text":" in ","type":"text"},{"styles":{"code":true},"text":"churn_calc","type":"text"},{"styles":{},"text":" using prior month users as denominator","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Month-over-month growth (Trend Dial)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"code":true},"text":"LAG()","type":"text"},{"styles":{},"text":" in ","type":"text"},{"styles":{"code":true},"text":"revenue_growth","type":"text"},{"styles":{},"text":" to compare current vs previous revenue","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Decimal division","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Every division uses ","type":"text"},{"styles":{"code":true},"text":"* 1.0","type":"text"},{"styles":{},"text":" or ","type":"text"},{"styles":{"code":true},"text":"* 100.0","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"NULLIF protection","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"All divisions wrapped in ","type":"text"},{"styles":{"code":true},"text":"NULLIF(..., 0)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Date grouping","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"code":true},"text":"DATE_TRUNC(''month'', ...)","type":"text"},{"styles":{},"text":" for monthly buckets","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"LAG() window function","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{"code":true},"text":"LAG(total_revenue) OVER (ORDER BY month)","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"NOT EXISTS for churn","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"Implicit in the LEFT JOIN pattern where prior users are compared","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]},{"cells":[{"content":[{"styles":{},"text":"Simple final output","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"},{"content":[{"styles":{},"text":"One row per month with all three KPIs side by side","type":"text"}],"props":{"backgroundColor":"default","colspan":1,"rowspan":1,"textAlignment":"left","textColor":"default"},"type":"tableCell"}]}],"type":"tableContent"},"id":"8669ab72-e736-44d6-b6df-e087fcecdcde","props":{"textColor":"default"},"type":"table"},{"children":[],"content":[{"styles":{"bold":true},"text":"Interview talking points for this script:","type":"text"}],"id":"6f4eab1e-3023-4fc0-952b-aa1ff74646bc","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"\"ARPU is total revenue divided by distinct users — I force decimal division with ","type":"text"},{"styles":{"code":true},"text":"* 1.0","type":"text"},{"styles":{},"text":".\"","type":"text"}],"id":"d806b03c-c000-42ad-b25e-932a377d0ef1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"\"Churn is the percentage of prior month''s users who did not return — I use a LEFT JOIN to find missing users.\"","type":"text"}],"id":"78bf8433-55b4-4f79-9fe1-0f86524dc1df","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"\"Month-over-month growth uses LAG() to access the previous month''s revenue and compute the percentage change.\"","type":"text"}],"id":"e99d5534-dc4c-4e09-bbb3-b232c99cf356","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"\"All divisions are protected with NULLIF to prevent crashes if a month has zero users or zero revenue.\"","type":"text"}],"id":"d5ca8e6d-6ecd-489d-b3b0-0c4b1f6d90c4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"\"I used DATE_TRUNC to group by month and ensure all KPIs align on the same time period.\"","type":"text"}],"id":"f335012f-0309-42da-a4fe-cb4e251a10cc","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"id":"5390d0d7-bbf2-490a-be98-939b21141cac","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"italic":true},"text":"This note is scoped exclusively to internship-level KPI aggregation readiness for Topic 12. Do not add to it. Use it as written.","type":"text"}],"id":"9d8bd05c-c278-4eb8-b512-ed5bd796e8c2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[],"id":"169f3a33-e15b-4d67-973d-6676b5ddd9f2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"}]'::jsonb, '3e9e3dd3-a59b-4b02-968a-ee95e7317583') ON CONFLICT ("node_id") DO UPDATE SET "bad_example" = EXCLUDED."bad_example", "completed_at" = EXCLUDED."completed_at", "created_at" = EXCLUDED."created_at", "definition" = EXCLUDED."definition", "good_example" = EXCLUDED."good_example", "is_completed" = EXCLUDED."is_completed", "key_points" = EXCLUDED."key_points", "last_edited" = EXCLUDED."last_edited", "map_id" = EXCLUDED."map_id", "mental_model" = EXCLUDED."mental_model", "notes" = EXCLUDED."notes", "resources" = EXCLUDED."resources", "rich_content" = EXCLUDED."rich_content", "user_id" = EXCLUDED."user_id";
INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-06-14T10:02:58.619039+00:00', '', '', '65310b0c-1e70-436f-94b3-d7b026aa6c33', false, '[]'::jsonb, NULL, '2ad473fe-77dd-481e-8ba7-4b2b0336173f', '', '6013bf3f-50f7-4ba0-8c68-9858308d910f', '', '[]'::jsonb, NULL, '3e9e3dd3-a59b-4b02-968a-ee95e7317583') ON CONFLICT ("node_id") DO UPDATE SET "bad_example" = EXCLUDED."bad_example", "completed_at" = EXCLUDED."completed_at", "created_at" = EXCLUDED."created_at", "definition" = EXCLUDED."definition", "good_example" = EXCLUDED."good_example", "is_completed" = EXCLUDED."is_completed", "key_points" = EXCLUDED."key_points", "last_edited" = EXCLUDED."last_edited", "map_id" = EXCLUDED."map_id", "mental_model" = EXCLUDED."mental_model", "notes" = EXCLUDED."notes", "resources" = EXCLUDED."resources", "rich_content" = EXCLUDED."rich_content", "user_id" = EXCLUDED."user_id";
INSERT INTO "node_content" ("bad_example", "completed_at", "created_at", "definition", "good_example", "id", "is_completed", "key_points", "last_edited", "map_id", "mental_model", "node_id", "notes", "resources", "rich_content", "user_id") VALUES ('', NULL, '2026-05-26T05:31:00.286198+00:00', '', '', 'd48c575b-bef9-4368-98a4-b858ce9b4196', false, '[]'::jsonb, '2026-05-26T06:25:47.639+00:00', '21b23730-1e24-468d-a7ac-836d2cdf3ffe', '', '18e1bda9-92e2-4415-9ee9-0e2047a27c42', '', '[]'::jsonb, '[{"children":[],"content":[{"styles":{"bold":true},"text":"Chapter 2 — Data Engineering Lifecycle","type":"text"}],"id":"5287b858-9653-4e6c-acea-fe9c045970e1","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":1,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"1. Overarching mental model","type":"text"}],"id":"b5573e1a-239c-4f8e-a6e7-ac794a2f0c9f","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Think of a ","type":"text"},{"styles":{"bold":true},"text":"restaurant kitchen and dining room","type":"text"},{"styles":{},"text":" as the full data engineering lifecycle.","type":"text"}],"id":"1ba60188-c527-4779-847b-fc8e052c3453","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"Ingredients arrive  →  pantry storage  →  prep line  →  cooking/plating  →  served to customers\nGeneration             Storage            Ingestion     Transformation       Serving","type":"text"}],"id":"3d4ad6d2-2093-4ee7-97f5-1f1c9de877f4","props":{"language":"text"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"Generation","type":"text"},{"styles":{},"text":" is where ingredients are produced or sourced.","type":"text"}],"id":"a46140a1-9e43-4742-af72-21ba8a5b68be","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Storage","type":"text"},{"styles":{},"text":" is the pantry, fridge, and cold room where ingredients are kept.","type":"text"}],"id":"f46e9dc3-67f9-401d-b59a-28f975e19643","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Ingestion","type":"text"},{"styles":{},"text":" is the receiving dock and kitchen workflow that moves items into the system.","type":"text"}],"id":"5693971b-925c-4449-b12e-c8ee2a8cb539","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Transformation","type":"text"},{"styles":{},"text":" is the prep station and cooking line where raw ingredients become meals.","type":"text"}],"id":"09f69a3f-9881-4183-82ec-175c1a89e2da","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Serving","type":"text"},{"styles":{},"text":" is the dining room, takeout counter, or delivery app where value reaches the customer.","type":"text"}],"id":"188a3564-3097-4a67-a30a-7413deb9fa4a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"The crucial insight is that a restaurant does not succeed because it has one great stove. It succeeds because the ","type":"text"},{"styles":{"bold":true},"text":"whole kitchen system","type":"text"},{"styles":{},"text":" works smoothly, and because the invisible work underneath — hygiene, inventory, scheduling, food safety, and coordination — is done well. That is exactly how the book frames Chapter 2: the lifecycle stages are visible, but the undercurrents make the whole thing work.","type":"text"}],"id":"760812bb-f452-49a7-b4c6-594d1d16707a","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"paragraph"},{"children":[],"content":[{"styles":{"bold":true},"text":"2. Lifecycle overview","type":"text"}],"id":"3cf6c0ac-b4f3-4a68-a9bd-526aa6fd340f","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Mental model","type":"text"}],"id":"d72b77a6-098d-499b-b4eb-510397d2d256","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The lifecycle is a ","type":"text"},{"styles":{"bold":true},"text":"cradle-to-grave flow","type":"text"},{"styles":{},"text":" of data through a business system.","type":"text"}],"id":"b74a0d07-60bd-4201-9c6b-c5b32bc93ed8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Data engineering is not one tool or one job; it is the management of how data moves from source systems to downstream use.","type":"text"}],"id":"9dc1480c-d318-44ef-bc0f-512f099aa15e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"The book’s key move is to shift thinking away from tools and toward ","type":"text"},{"styles":{"bold":true},"text":"end-to-end flow","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"aebb2d89-d43c-467b-bc65-a113b8214247","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Explanation","type":"text"}],"id":"62355ebf-b664-4624-9125-91da8622db91","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"The five stages are ","type":"text"},{"styles":{"bold":true},"text":"Generation, Storage, Ingestion, Transformation, Serving","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"29beb5c5-25c9-4f89-8f8e-5edeceffd406","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"The ","type":"text"},{"styles":{"bold":true},"text":"data engineering lifecycle","type":"text"},{"styles":{},"text":" is only the part of the larger data lifecycle that the data engineer directly controls.","type":"text"}],"id":"f3d4088f-1714-4c22-845d-2602ae8292ff","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Storage is special because it underpins the other stages rather than sitting neatly in one place.","type":"text"}],"id":"3891d342-2c35-4fb8-a50a-f01d89a13952","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"The middle stages often overlap in practice, so the lifecycle is a ","type":"text"},{"styles":{"bold":true},"text":"thinking model","type":"text"},{"styles":{},"text":", not a rigid sequence.","type":"text"}],"id":"d036ba5f-f652-4a18-ac48-a57aca17fde9","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Application","type":"text"}],"id":"2fcbee2f-ce41-4e10-a13c-9fd0c27806ac","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"This gives data engineers a map for debugging and design.","type":"text"}],"id":"c473f5be-d28b-4d58-92ab-7a0c063ff83b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"If a dashboard is wrong, the issue may actually be in generation, storage, ingestion, or transformation.","type":"text"}],"id":"5888b671-37fd-4563-bb05-32b15d0fe251","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"It also helps teams ask better questions: where does the data come from, where does it live, how does it move, how does it change, and who uses it?","type":"text"}],"id":"749ac105-626c-409f-bb57-2c8c36606c79","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Examples","type":"text"}],"id":"e7b2b282-f293-4631-8f90-3b93b5499259","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"A sales dashboard can fail because of a source schema change, even if the dashboard code is fine.","type":"text"}],"id":"71ada680-1517-46f5-a676-8c80bad328de","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"A streaming pipeline may transform events before storage if latency matters.","type":"text"}],"id":"07e4002b-b532-4615-a9a9-406ebd83990c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"A model can be wrong because a late-arriving source event never made it through ingestion in time.","type":"text"}],"id":"0e1947e1-1577-44e8-8f45-654854d25b82","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"id":"ff04bc93-80ca-49ca-a855-fff7691596ff","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"3. Generation","type":"text"}],"id":"9d2ac602-2503-483d-a0e0-cf71703565d6","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Mental model","type":"text"}],"id":"6d906521-1534-412d-bf91-554dffc0b7d4","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Generation is the ","type":"text"},{"styles":{"bold":true},"text":"kitchen’s supply chain entrance","type":"text"},{"styles":{},"text":" — where raw items first appear.","type":"text"}],"id":"b51dd01a-41de-4546-a86a-70734a04d7db","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"In a restaurant, this is where ingredients are delivered, counted, and checked.","type":"text"}],"id":"d6978828-8941-4b69-a603-d513cdbbecd4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"In data, this is where source systems create the raw material the data engineer works with.","type":"text"}],"id":"5a88b8e9-cfb3-499a-881e-9129c2d8a64b","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Explanation","type":"text"}],"id":"dae3215f-17d1-44d7-acb8-92392a842b40","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Source systems include ","type":"text"},{"styles":{"bold":true},"text":"transactional databases, IoT devices, message queues, logs, spreadsheets, and APIs","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"f9019a1c-0ea9-4b99-b250-b98a493dfa6c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"The data engineer usually ","type":"text"},{"styles":{"bold":true},"text":"does not own","type":"text"},{"styles":{},"text":" these systems.","type":"text"}],"id":"3612ddfe-0dbb-4234-87d2-661eaf22e0ad","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"The engineer must understand how data is generated, how fast it arrives, what schema it uses, and how often it changes.","type":"text"}],"id":"78838623-b51a-4b32-a141-5d304073284a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[{"children":[],"content":[{"styles":{"bold":true},"text":"Application databases","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"8bad9a0b-fd11-4cc9-b8ad-5b230046c03c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"IoT swarms / event streams","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"1d751b4f-6b4a-44c0-80fd-ccd9d808f460","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"}],"content":[{"styles":{},"text":"Two major source patterns are emphasized:","type":"text"}],"id":"0919a353-9dac-402b-8ae2-6724352b5681","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Application","type":"text"}],"id":"6dff387f-83f2-467a-b392-d935f3874ce0","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"This stage matters because upstream change can silently break everything downstream.","type":"text"}],"id":"24ebf2b1-8f54-45dd-8b9e-61c49ca499ae","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Data engineers should coordinate with source-system owners so schema changes and system migrations do not surprise the pipeline.","type":"text"}],"id":"1e9061b2-881b-43d3-b274-00cde7f41e54","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Generation thinking helps engineers ask: do we need snapshots, CDC, events, or API pulls?","type":"text"}],"id":"2c0ce72e-802a-49c9-8b8a-b2ee3a5255f5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Examples","type":"text"}],"id":"24c2abf5-adc9-486a-8488-cd9a830bc5b8","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"A software team renames a database column and breaks a downstream pipeline.","type":"text"}],"id":"60a9841b-807a-4083-acae-7443e244c245","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"A sensor fleet sends continuous readings that must be handled as events rather than as periodic snapshots.","type":"text"}],"id":"b02eb94c-d135-4e53-8ac0-7cb1ff93e2b8","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"A SaaS API changes its response structure, requiring the ingestion process to adapt.","type":"text"}],"id":"d4c2b745-2ad3-415e-a428-e6c11490ed0f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"id":"bced9a98-3a59-4606-a03a-790b008c1667","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"4. Storage","type":"text"}],"id":"b0d2042d-2fab-4a57-9a77-80f8b9b6f0a7","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Mental model","type":"text"}],"id":"69206ff2-8486-45a0-8db0-5f82060e7830","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Storage is the ","type":"text"},{"styles":{"bold":true},"text":"restaurant pantry, fridge, and freezer","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"d4a66b74-144a-43c8-86b0-c34313b0347a","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"It is not just a stopover; it is the foundation that keeps the kitchen operating.","type":"text"}],"id":"b9b7714b-6c76-4945-8285-6066b5022aa6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Different foods need different storage temperatures, and different data needs different storage patterns.","type":"text"}],"id":"0953fbf2-7d9d-411f-9dfd-bb56b386adbf","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Explanation","type":"text"}],"id":"2b5ee532-c0ce-4c7b-8c27-399d04faa15a","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Storage is one of the most complex lifecycle stages because it influences ingestion, transformation, and serving.","type":"text"}],"id":"64ccfafb-e24b-4a7d-bea9-e35f98b4a519","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[{"children":[],"content":[{"styles":{"bold":true},"text":"Hot","type":"text"},{"styles":{},"text":" data is accessed frequently and needs fast retrieval.","type":"text"}],"id":"77399f05-1114-45a7-a511-64d32bca74c1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Lukewarm","type":"text"},{"styles":{},"text":" data is accessed sometimes.","type":"text"}],"id":"8fcd3c6e-3949-45aa-8997-46eb68ed9bf4","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Cold","type":"text"},{"styles":{},"text":" data is rarely accessed and belongs in cheap archival storage.","type":"text"}],"id":"ab7c8800-207b-4a7e-b0ef-6cd1b852e63c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"}],"content":[{"styles":{},"text":"The book introduces ","type":"text"},{"styles":{"bold":true},"text":"data temperature","type":"text"},{"styles":{},"text":":","type":"text"}],"id":"383a317c-bb5d-40ea-94f0-cf046aa58af1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Storage choices must consider speed, scale, schema, metadata, compliance, and downstream retrieval patterns.","type":"text"}],"id":"bb94c8f3-e52f-4570-be4a-43c738ca5935","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Types of storage include object storage, warehouses, lakehouses, streaming storage, and cache/memory systems.","type":"text"}],"id":"a5bd80b1-6cb6-4df2-bc7f-3e56796f6e11","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Application","type":"text"}],"id":"d39559df-4510-4f82-8c47-5554b8d36610","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Good storage design avoids bottlenecks and wasted money.","type":"text"}],"id":"6315db10-a8d3-4099-a161-d780ce7c5759","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Choosing the wrong tier can make dashboards slow or bills too high.","type":"text"}],"id":"1cbeea55-8f88-4e13-b55c-aafd8331a35e","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Metadata and lineage are not optional extras — they make data discoverable and governable.","type":"text"}],"id":"ec8472a9-078e-4933-b79d-95954cdc95b2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Examples","type":"text"}],"id":"18c3fa97-d801-4bf6-8950-aebf0ce69c19","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"A healthcare company keeps old records in hot storage and pays far more than necessary.","type":"text"}],"id":"ee32e751-2595-4629-a049-ee595325ffa0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Kafka acts as both a streaming buffer and a storage layer for event data.","type":"text"}],"id":"14a9954d-945b-4be5-9fec-3caa77589a9c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"A warehouse stores structured analytics data with enforced schema, while object storage holds raw landing data.","type":"text"}],"id":"8144ee00-650a-432c-9711-a6a7f09b1691","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"id":"12e16f0a-7311-4522-bc05-47ff29412ebc","props":{},"type":"divider"},{"children":[],"content":[{"styles":{"bold":true},"text":"5. Ingestion","type":"text"}],"id":"ae1d668d-730b-4d84-97ed-69d2ff51df08","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{"bold":true},"text":"Mental model","type":"text"}],"id":"ec9ce166-aa7f-4404-a78d-8dbaaab1c1c3","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Ingestion is the ","type":"text"},{"styles":{"bold":true},"text":"receiving dock and delivery process","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"40cd016f-5785-4050-9845-615424261493","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Raw ingredients need to move from suppliers into the kitchen reliably.","type":"text"}],"id":"9fe40830-c895-49aa-a834-39e6bfaa46bc","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"If delivery fails, the whole restaurant operation suffers.","type":"text"}],"id":"0b07485f-ff93-4749-aa17-ae91fcdc8f37","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Explanation","type":"text"}],"id":"19b9f957-a07f-4f6a-8399-ead75798dc04","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Ingestion is the process of moving data from source systems into storage.","type":"text"}],"id":"a1e16cbb-e9a1-4088-a0aa-6c968a3ea5f1","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[{"children":[],"content":[{"styles":{},"text":"Ingestion = moving data.","type":"text"}],"id":"f1ea9a6d-7fa7-4661-81df-41c1877582e0","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Integration = combining data from multiple sources into a new dataset.","type":"text"}],"id":"bd9d8f95-f7ec-4fdd-a760-58d672436621","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"}],"content":[{"styles":{},"text":"The book distinguishes ","type":"text"},{"styles":{"bold":true},"text":"ingestion","type":"text"},{"styles":{},"text":" from ","type":"text"},{"styles":{"bold":true},"text":"integration","type":"text"},{"styles":{},"text":":","type":"text"}],"id":"273b9826-fffd-4f40-a4e3-dcb219421cca","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[{"children":[],"content":[{"styles":{"bold":true},"text":"Batch","type":"text"},{"styles":{},"text":" — data moves in chunks on a schedule.","type":"text"}],"id":"5168a891-5f1d-4177-9e05-9d2e22464f59","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Streaming","type":"text"},{"styles":{},"text":" — data moves continuously as events happen.","type":"text"}],"id":"0ab356a1-5eb6-407a-840d-94d0f31d35c5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"}],"content":[{"styles":{},"text":"The major ingestion patterns are:","type":"text"}],"id":"7b8a3eea-bc36-4a9e-bfa0-5be51abeaf69","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[{"children":[],"content":[{"styles":{"bold":true},"text":"Push vs pull vs poll","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"e603dd77-719d-48e2-8106-31f32758c635","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Bounded vs unbounded data","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"e8b7dbaa-19cd-4a06-8b88-9d8cfdac4844","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Synchronous vs asynchronous ingestion","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"f38968bd-458f-40e8-b3a9-15074db3bb7d","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"ETL vs ELT","type":"text"},{"styles":{},"text":".","type":"text"}],"id":"165ef635-bba0-41b3-b8a0-28695147b2a2","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"}],"content":[{"styles":{},"text":"Other important distinctions include:","type":"text"}],"id":"e8984733-0634-4cf7-a8c2-675d195d76a5","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"Application","type":"text"}],"id":"1408266b-96cc-47d1-b8e9-f430909979fa","props":{"backgroundColor":"color(srgb 0.0901961 0.0862745 0.0823529)","isToggleable":false,"level":2,"textAlignment":"left","textColor":"rgb(214, 213, 212)"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Ingestion is one of the biggest bottlenecks in the lifecycle.","type":"text"}],"id":"39414480-f465-4118-a218-466a86bbbfe6","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"The right choice depends on the business need for freshness, complexity tolerance, and reliability requirements.","type":"text"}],"id":"620c2e03-849e-4f15-83c8-ad1c36511e1c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"Batch is s