":[{"styles":{},"text":"SQL Window Function Note: Effect of ","type":"text"},{"styles":{"code":true},"text":"ORDER BY","type":"text"},{"styles":{},"text":" inside ","type":"text"},{"styles":{"code":true},"text":"OVER()","type":"text"}],"id":"2804b967-a083-47e1-aaa2-6e1a523a305f","props":{"backgroundColor":"default","isToggleable":false,"level":2,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"Main Idea","type":"text"}],"id":"0f011aaf-90ee-402b-9a0c-9b3b15f78c19","props":{"backgroundColor":"default","isToggleable":false,"level":3,"textAlignment":"left","textColor":"default"},"type":"heading"},{"children":[],"content":[{"styles":{},"text":"In window functions:","type":"text"}],"id":"234fd5a3-7d3f-42db-a405-abdd9842285c","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"paragraph"},{"children":[],"content":[{"styles":{},"text":"FUNCTION() OVER(\n    PARTITION BY column\n    ORDER BY column\n)","type":"text"}],"id":"b932bddb-5b65-495a-8c5d-118efa016842","props":{"language":"sql"},"type":"codeBlock"},{"children":[],"content":[{"styles":{"bold":true},"text":"PARTITION BY","type":"text"},{"styles":{},"text":" → Divides rows into groups (like ","type":"text"},{"styles":{"code":true},"text":"GROUP BY","type":"text"},{"styles":{},"text":", but does not collapse rows)","type":"text"}],"id":"6958bb6b-4fcb-4cf1-bc12-9769c6840f5f","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{"bold":true},"text":"ORDER BY inside OVER()","type":"text"},{"styles":{},"text":" → Controls the order in which the window calculation is performed","type":"text"}],"id":"2069fe2d-c34e-49a2-8610-a680e5bc08ea","props":{"backgroundColor":"default","textAlignment":"left","textColor":"default"},"type":"bulletListItem"},{"children":[],"content":[{"styles":{},"text":"⚠️ ","type":"text"},{"styles":{"bold":true},"tex